import React from 'react';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import {
  AppBar,
  Box,
  Drawer,
  IconButton,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Toolbar,
  Typography,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import {
  Menu as MenuIcon,
  Dashboard as DashboardIcon,
  AdminPanelSettings as AdminIcon,
  ShowChart as ChartIcon,
  AttachMoney as MoneyIcon,
} from '@mui/icons-material';

const drawerWidth = 240;

interface LayoutProps {
  children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const [mobileOpen, setMobileOpen] = React.useState(false);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const location = useLocation();

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const menuItems = [
    { text: 'Dashboard', icon: <DashboardIcon />, path: '/' },
    { text: 'Money Maker', icon: <MoneyIcon />, path: '/money-maker' },
    { text: 'Predictions', icon: <ChartIcon />, path: '/predictions' },
    { text: 'Admin', icon: <AdminIcon />, path: '/admin' },
  ];

  const drawer = (
    <div>
      <Toolbar>
        <Typography noWrap component="div" variant="h6">
          Elite Sports Analytics
        </Typography>
      </Toolbar>
      <List>
        {menuItems.map(item => (
          <ListItem key={item.text} disablePadding>
            <ListItemButton
              component={RouterLink}
              selected={location.pathname === item.path}
              to={item.path}
              onClick={() => isMobile && setMobileOpen(false)}
            >
              <ListItemIcon>{item.icon}</ListItemIcon>
              <ListItemText primary={item.text} />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
    </div>
  );

  return (
    <Box sx={{ display: 'flex' }}>
      <AppBar
        position="fixed"
        sx={{
          width: { sm: `calc(100% - ${drawerWidth}px)` },
          ml: { sm: `${drawerWidth}px` },
        }}
      >
        <Toolbar>
          <IconButton
            aria-label="open drawer"
            color="inherit"
            edge="start"
            sx={{ mr: 2, display: { sm: 'none' } }}
            onClick={handleDrawerToggle}
          >
            <MenuIcon />
          </IconButton>
          <Typography noWrap component="div" variant="h6">
            {menuItems.find(item => item.path === location.pathname)?.text || 'Dashboard'}
          </Typography>
        </Toolbar>
      </AppBar>
      <Box component="nav" sx={{ width: { sm: drawerWidth }, flexShrink: { sm: 0 } }}>
        <Drawer
          ModalProps={{
            keepMounted: true, // Better open performance on mobile.
          }}
          open={mobileOpen}
          sx={{
            '& .MuiDrawer-paper': {
              boxSizing: 'border-box',
              width: drawerWidth,
            },
          }}
          variant={isMobile ? 'temporary' : 'permanent'}
          onClose={handleDrawerToggle}
        >
          {drawer}
        </Drawer>
      </Box>
      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: 3,
          width: { sm: `calc(100% - ${drawerWidth}px)` },
          mt: '64px',
        }}
      >
        {children}
      </Box>
    </Box>
  );
};

import React, { useState, useMemo } from 'react';
import { FaSort, FaSortUp, FaSortDown, FaFilter } from 'react-icons/fa';
import { Lineup, LineupType } from '../types';
import { fadeIn } from '../hooks/useAnimation';
import { formatCurrency } from '../utils/odds';
import { motion, Variants } from 'framer-motion';

interface LineupComparisonTableProps {
  lineups: Lineup[];
  onSelect?: (lineup: Lineup) => void;
}

type SortField = 'name' | 'type' | 'winProbability' | 'projectedPayout';
type SortDirection = 'asc' | 'desc';

const tableVariants: Variants = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0 },
};

const rowVariants: Variants = {
  initial: { opacity: 0, x: -20 },
  animate: { opacity: 1, x: 0 },
};

export const LineupComparisonTable: React.FC<LineupComparisonTableProps> = ({
  lineups,
  onSelect,
}) => {
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
  const [typeFilter, setTypeFilter] = useState<string>('all');

  const getTypeColor = (type: Lineup['type']) => {
    switch (type) {
      case LineupType.SINGLE:
        return 'bg-blue-100 text-blue-800 dark:bg-blue-800/20 dark:text-blue-400';
      case LineupType.TEASER:
        return 'bg-amber-100 text-amber-800 dark:bg-amber-800/20 dark:text-amber-400';
      case LineupType.PARLAY:
        return 'bg-red-100 text-red-800 dark:bg-red-800/20 dark:text-red-400';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-800/20 dark:text-gray-400';
    }
  };

  const handleSort = (field: SortField) => {
    if (field === sortField) {
      setSortDirection(prev => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };

  const getSortIcon = (field: SortField) => {
    if (field !== sortField) return <FaSort className="w-4 h-4 text-gray-400" />;
    return sortDirection === 'asc' ? (
      <FaSortUp className="w-4 h-4 text-primary-500" />
    ) : (
      <FaSortDown className="w-4 h-4 text-primary-500" />
    );
  };

  const filteredAndSortedLineups = useMemo(() => {
    let result = [...lineups];
    if (typeFilter !== 'all') {
      result = result.filter(lineup => lineup.type === typeFilter);
    }
    result.sort((a, b) => a.name.localeCompare(b.name));
    return result;
  }, [lineups, typeFilter]);

  return (
    <motion.div
      animate="animate"
      className="glass-morphism rounded-xl overflow-hidden"
      exit="exit"
      initial="initial"
      variants={tableVariants}
    >
      {/* Filter Bar */}
      <div className="p-4 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center space-x-4">
          <FaFilter className="w-4 h-4 text-primary-500" />
          <select
            className="bg-transparent border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-1.5 text-sm"
            value={typeFilter}
            onChange={e => setTypeFilter(e.target.value)}
          >
            <option value="all">All Types</option>
            <option value={LineupType.SINGLE}>Single</option>
            <option value={LineupType.TEASER}>Teaser</option>
            <option value={LineupType.PARLAY}>Parlay</option>
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="bg-gray-50 dark:bg-gray-800/50">
              <th className="px-6 py-3 text-left cursor-pointer" onClick={() => handleSort('name')}>
                <div className="flex items-center space-x-2">
                  <span>Name</span>
                  {getSortIcon('name')}
                </div>
              </th>
              <th className="px-6 py-3 text-left cursor-pointer" onClick={() => handleSort('type')}>
                <div className="flex items-center space-x-2">
                  <span>Type</span>
                  {getSortIcon('type')}
                </div>
              </th>
              <th
                className="px-6 py-3 text-left cursor-pointer"
                onClick={() => handleSort('winProbability')}
              >
                <div className="flex items-center space-x-2">
                  <span>Win Probability</span>
                  {getSortIcon('winProbability')}
                </div>
              </th>
              <th
                className="px-6 py-3 text-left cursor-pointer"
                onClick={() => handleSort('projectedPayout')}
              >
                <div className="flex items-center space-x-2">
                  <span>Projected Payout</span>
                  {getSortIcon('projectedPayout')}
                </div>
              </th>
            </tr>
          </thead>
          <tbody>
            {filteredAndSortedLineups.map((lineup, index) => (
              <motion.tr
                key={lineup.id}
                animate="animate"
                className="border-t border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800/50 cursor-pointer transition-colors"
                custom={index}
                initial="initial"
                variants={rowVariants}
                onClick={() => onSelect?.(lineup)}
              >
                <td className="px-6 py-4">
                  <div className="flex items-center space-x-3">
                    <span className="font-medium text-gray-900 dark:text-white">{lineup.name}</span>
                    <span className="text-xs text-gray-500">
                      {new Date(lineup.createdAt).toLocaleDateString()}
                    </span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className={`font-medium ${getTypeColor(lineup.type)}`}>{lineup.type}</span>
                </td>
                <td className="px-6 py-4">
                  <span className="text-sm font-medium">{lineup.status}</span>
                </td>
              </motion.tr>
            ))}
          </tbody>
        </table>
      </div>
    </motion.div>
  );
};

import React from 'react';
import { LiveOddsTickerProps, BookOdds } from '../types/betting';
import { motion, AnimatePresence } from 'framer-motion';

const LiveOddsTicker: React.FC<LiveOddsTickerProps> = ({ data, className = '' }) => {
  if (!data || Object.keys(data).length === 0) {
    return <div className={`p-4 text-gray-500 ${className}`}>No live odds available</div>;
  }

  return (
    <div className={`space-y-4 ${className}`}>
      <h3 className="text-lg font-semibold mb-4">Live Odds</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {Object.entries(data as Record<string, BookOdds>).map(([market, bookOdds], index) => (
          <motion.div
            key={market}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white rounded-lg p-4 shadow-sm"
            initial={{ opacity: 0, y: 20 }}
            transition={{ delay: index * 0.1 }}
          >
            <div className="flex justify-between items-center mb-2">
              <span className="font-medium">{market}</span>
            </div>
            <div className="space-y-1">
              {Object.entries(bookOdds).map(([bookmaker, odds]) => (
                <div key={bookmaker} className="flex justify-between text-sm">
                  <span className="text-gray-600">{bookmaker}</span>
                  <span className="font-medium">{odds.toFixed(2)}</span>
                </div>
              ))}
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default React.memo(LiveOddsTicker);

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../../providers/AuthProvider';

interface LoginFormProps {
  onSuccess?: () => void;
  onToggleForm?: () => void;
}

const LoginForm: React.FC<LoginFormProps> = ({ onSuccess, onToggleForm }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { login } = useAuth();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      await login(email, password);
      onSuccess?.();
    } catch (err) {
      setError('Invalid email or password');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <motion.div
      animate={{ opacity: 1, y: 0 }}
      className="w-full max-w-md mx-auto"
      exit={{ opacity: 0, y: -20 }}
      initial={{ opacity: 0, y: 20 }}
    >
      <form className="space-y-6" onSubmit={handleSubmit}>
        <div>
          <label
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
            htmlFor="email"
          >
            Email
          </label>
          <input
            required
            className="input-primary mt-1"
            id="email"
            placeholder="you@example.com"
            type="email"
            value={email}
            onChange={e => setEmail(e.target.value)}
          />
        </div>

        <div>
          <label
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
            htmlFor="password"
          >
            Password
          </label>
          <input
            required
            className="input-primary mt-1"
            id="password"
            placeholder="••••••••"
            type="password"
            value={password}
            onChange={e => setPassword(e.target.value)}
          />
        </div>

        {error && (
          <motion.p
            animate={{ opacity: 1 }}
            className="text-sm text-red-600 dark:text-red-400"
            initial={{ opacity: 0 }}
          >
            {error}
          </motion.p>
        )}

        <button
          className="btn-primary w-full flex justify-center"
          disabled={isLoading}
          type="submit"
        >
          {isLoading ? (
            <svg
              className="animate-spin h-5 w-5 text-white"
              fill="none"
              viewBox="0 0 24 24"
              xmlns="http://www.w3.org/2000/svg"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              />
              <path
                className="opacity-75"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                fill="currentColor"
              />
            </svg>
          ) : (
            'Sign In'
          )}
        </button>

        <p className="text-center text-sm text-gray-600 dark:text-gray-400">
          Don't have an account?{' '}
          <button
            className="text-primary-600 dark:text-primary-400 hover:underline focus:outline-none"
            type="button"
            onClick={onToggleForm}
          >
            Sign up
          </button>
        </p>
      </form>
    </motion.div>
  );
};

export default React.memo(LoginForm);

import React, { useMemo } from 'react';
import { PredictionData } from '../types/betting';
import { StrategyRecommendation } from '../types/core';
import { motion, AnimatePresence } from 'framer-motion';

export interface MLInsight {
  factor: string;
  impact: number;
  confidence: number;
  description: string;
}

export interface MLFactorVizProps {
  playerId: string | null;
  metric: string | null;
  prediction?: PredictionData;
  strategy?: StrategyRecommendation;
}

const MLFactorViz: React.FC<MLFactorVizProps> = ({ playerId, metric, prediction, strategy }) => {
  const insights: MLInsight[] = useMemo(() => {
    if (!playerId || !metric || !prediction || !strategy) {
      return [];
    }

    return [
      {
        factor: 'Historical Performance',
        impact: strategy.confidence || 0,
        confidence: prediction.confidence,
        description: `Based on ${playerId}'s historical ${metric} performance`,
      },
      {
        factor: 'Market Trends',
        impact: strategy.expectedValue || 0,
        confidence: prediction.confidence * 0.9,
        description: 'Current market movement and betting patterns',
      },
      {
        factor: 'Player Condition',
        impact: 0.75,
        confidence: 0.85,
        description: 'Recent performance and health status',
      },
    ];
  }, [playerId, metric, prediction, strategy]);

  const getImpactColor = (impact: number) => {
    if (impact >= 0.7) return 'bg-green-500';
    if (impact >= 0.4) return 'bg-yellow-500';
    return 'bg-red-500';
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.7) return 'text-green-600';
    if (confidence >= 0.4) return 'text-yellow-600';
    return 'text-red-600';
  };

  if (!playerId || !metric) {
    return (
      <div className="p-4 text-gray-500">Select a player and metric to view ML factor analysis</div>
    );
  }

  if (!prediction || !strategy) {
    return <div className="p-4 text-gray-500">Loading ML factor analysis...</div>;
  }

  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold mb-4">ML Factor Analysis</h3>
      <div className="space-y-6">
        {insights.map((insight: MLInsight, index: number) => (
          <motion.div
            key={insight.factor}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white rounded-lg p-4 shadow-sm"
            initial={{ opacity: 0, y: 20 }}
            transition={{ delay: index * 0.1 }}
          >
            <div className="flex items-center justify-between mb-2">
              <h4 className="font-medium">{insight.factor}</h4>
              <span className={`text-sm ${getConfidenceColor(insight.confidence)}`}>
                {Math.round(insight.confidence * 100)}% confidence
              </span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2.5 mb-2">
              <motion.div
                animate={{ width: `${insight.impact * 100}%` }}
                className={`h-2.5 rounded-full ${getImpactColor(insight.impact)}`}
                initial={{ width: 0 }}
                transition={{ duration: 0.5 }}
              />
            </div>
            <p className="text-sm text-gray-600">{insight.description}</p>
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default React.memo(MLFactorViz);

import React, { Fragment } from 'react';
import { Dialog, Transition } from '@headlessui/react';
import { cn } from '../../utils/classNames';
import { motion, AnimatePresence } from 'framer-motion';

export interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  description?: string;
  children: React.ReactNode;
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'full';
  className?: string;
  showClose?: boolean;
  closeOnOverlayClick?: boolean;
}

const sizes = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-xl',
  full: 'max-w-full mx-4',
};

export const Modal: React.FC<ModalProps> = ({
  isOpen,
  onClose,
  title,
  description,
  children,
  size = 'md',
  className,
  showClose = true,
  closeOnOverlayClick = true,
}) => {
  return (
    <Transition appear as={Fragment} show={isOpen}>
      <Dialog
        as="div"
        className="fixed inset-0 z-50 overflow-y-auto"
        onClose={closeOnOverlayClick ? onClose : () => {}}
      >
        <div className="min-h-screen px-4 text-center">
          <Transition.Child
            as={Fragment}
            enter="ease-out duration-300"
            enterFrom="opacity-0"
            enterTo="opacity-100"
            leave="ease-in duration-200"
            leaveFrom="opacity-100"
            leaveTo="opacity-0"
          >
            <Dialog.Overlay className="fixed inset-0 bg-black/50 backdrop-blur-sm transition-opacity" />
          </Transition.Child>

          {/* This element is to trick the browser into centering the modal contents. */}
          <span aria-hidden="true" className="inline-block h-screen align-middle">
            &#8203;
          </span>

          <Transition.Child
            as={Fragment}
            enter="ease-out duration-300"
            enterFrom="opacity-0 scale-95"
            enterTo="opacity-100 scale-100"
            leave="ease-in duration-200"
            leaveFrom="opacity-100 scale-100"
            leaveTo="opacity-0 scale-95"
          >
            <motion.div
              animate={{ opacity: 1, y: 0 }}
              className={cn(
                'inline-block w-full p-6 my-8 overflow-hidden text-left align-middle bg-white dark:bg-gray-800 rounded-2xl shadow-xl transition-all',
                sizes[size],
                className
              )}
              exit={{ opacity: 0, y: 20 }}
              initial={{ opacity: 0, y: 20 }}
            >
              {(title || showClose) && (
                <div className="flex items-start justify-between mb-4">
                  <div>
                    {title && (
                      <Dialog.Title
                        as="h3"
                        className="text-lg font-medium leading-6 text-gray-900 dark:text-gray-100"
                      >
                        {title}
                      </Dialog.Title>
                    )}
                    {description && (
                      <Dialog.Description className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                        {description}
                      </Dialog.Description>
                    )}
                  </div>
                  {showClose && (
                    <button
                      className="text-gray-400 hover:text-gray-500 focus:outline-none"
                      type="button"
                      onClick={onClose}
                    >
                      <span className="sr-only">Close</span>
                      <svg
                        className="h-6 w-6"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          d="M6 18L18 6M6 6l12 12"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                        />
                      </svg>
                    </button>
                  )}
                </div>
              )}
              {children}
            </motion.div>
          </Transition.Child>
        </div>
      </Dialog>
    </Transition>
  );
};

