interface PayoutPreviewProps {
  eventId: string;
}

export const PayoutPreview: React.FC<PayoutPreviewProps> = ({ eventId }) => {
  const payoutPreview = usePayoutStore(state => state.getPayoutPreview(eventId));
  const { currentProfile, bankroll } = useRiskProfileStore();
  const [changedValues, setChangedValues] = useState<Set<string>>(new Set());
  const [previousValues, setPreviousValues] = useState<Record<string, number>>({});

  // WebSocket for real-time payout/odds updates
  const wsUrl = `${process.env.NEXT_PUBLIC_WS_URL || 'ws://localhost:8000/ws'}?channel=payout-preview&eventId=${eventId}`;
  useWebSocket(wsUrl, {
    onMessage: (msg: WebSocketMessage) => {
      if (msg.event === 'odds_update' && msg.data?.eventId === eventId) {
        // Optionally handle odds update
      }
      if (msg.event === 'payout_update' && msg.data?.eventId === eventId) {
        usePayoutStore.getState().updatePayoutPreview(eventId, msg.data);
      }
    },
  });

  useEffect(() => {
    if (payoutPreview) {
      const newChangedValues = new Set<string>();
      const newPreviousValues = { ...previousValues };
      if (previousValues.potential_payout !== payoutPreview.potential_payout) {
        newChangedValues.add('potential_payout');
        newPreviousValues.potential_payout = payoutPreview.potential_payout;
      }
      if (previousValues.kelly_stake !== payoutPreview.kelly_stake) {
        newChangedValues.add('kelly_stake');
        newPreviousValues.kelly_stake = payoutPreview.kelly_stake;
      }
      if (previousValues.risk_adjusted_stake !== payoutPreview.risk_adjusted_stake) {
        newChangedValues.add('risk_adjusted_stake');
        newPreviousValues.risk_adjusted_stake = payoutPreview.risk_adjusted_stake;
      }
      if (previousValues.expected_value !== payoutPreview.expected_value) {
        newChangedValues.add('expected_value');
        newPreviousValues.expected_value = payoutPreview.expected_value;
      }
      setChangedValues(newChangedValues);
      setPreviousValues(newPreviousValues);
      const timeout = setTimeout(
        () => setChangedValues(new Set()),
        parseInt(durations.normal) * 1000 || 300
      );
      return () => clearTimeout(timeout);
    }
  }, [payoutPreview]);

  if (!payoutPreview) {
    return (
      <PreviewContainer>
        <Typography color="textSecondary" variant="body2">
          Loading payout preview...
        </Typography>
      </PreviewContainer>
    );
  }

  const handlePlaceBet = () => {
    // TODO: Implement bet placement logic
    console.log('Placing bet with stake:', payoutPreview.risk_adjusted_stake);
  };

  return (
    <PreviewContainer>
      <Typography gutterBottom variant="h6">
        Payout Preview
      </Typography>

      <ValueDisplay changed={changedValues.has('potential_payout')}>
        <Typography variant="body2">Potential Payout</Typography>
        <Value changed={changedValues.has('potential_payout')} color="primary" variant="body1">
          ${payoutPreview.potential_payout.toFixed(2)}
        </Value>
      </ValueDisplay>

      <ValueDisplay changed={changedValues.has('kelly_stake')}>
        <Typography variant="body2">Kelly Criterion Stake</Typography>
        <Value changed={changedValues.has('kelly_stake')} variant="body1">
          ${payoutPreview.kelly_stake.toFixed(2)}
        </Value>
      </ValueDisplay>

      <ValueDisplay changed={changedValues.has('risk_adjusted_stake')}>
        <Typography variant="body2">Risk-Adjusted Stake</Typography>
        <Value changed={changedValues.has('risk_adjusted_stake')} color="secondary" variant="body1">
          ${payoutPreview.risk_adjusted_stake.toFixed(2)}
        </Value>
      </ValueDisplay>

      <ValueDisplay changed={changedValues.has('expected_value')}>
        <Typography variant="body2">Expected Value</Typography>
        <Value
          changed={changedValues.has('expected_value')}
          color={payoutPreview.expected_value > 0 ? 'success.main' : 'error.main'}
          variant="body1"
        >
          ${payoutPreview.expected_value.toFixed(2)}
        </Value>
      </ValueDisplay>

      <PlaceBetButton
        fullWidth
        changed={changedValues.has('risk_adjusted_stake')}
        color="primary"
        disabled={payoutPreview.expected_value <= 0}
        variant="contained"
        onClick={handlePlaceBet}
      >
        Place Bet (${payoutPreview.risk_adjusted_stake.toFixed(2)})
      </PlaceBetButton>

      <Box mt={1}>
        <Typography color="textSecondary" variant="caption">
          Risk Profile: {currentProfile.profile_type}
          <br />
          Bankroll: ${bankroll.toFixed(2)}
        </Typography>
      </Box>
    </PreviewContainer>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { useUnifiedAnalytics } from '../hooks/useUnifiedAnalytics';
import {
  Box,
  Typography,
  Paper,
  LinearProgress,
  Tooltip,
  IconButton,
  Menu,
  MenuItem,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  Cell,
} from 'recharts';
import FilterListIcon from '@mui/icons-material/FilterList';
import SortIcon from '@mui/icons-material/Sort';
import { NoResultsFallback } from './NoResultsFallback';

const PredictionContainer = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(2),
  backgroundColor: theme.palette.background.paper,
  borderRadius: theme.shape.borderRadius,
  boxShadow: theme.shadows[2],
}));

const ConfidenceBar = styled(LinearProgress)(({ theme }) => ({
  height: 8,
  borderRadius: 4,
  backgroundColor: theme.palette.grey[200],
  '& .MuiLinearProgress-bar': {
    borderRadius: 4,
  },
}));

const ShapContainer = styled(Box)(({ theme }) => ({
  marginTop: theme.spacing(2),
  height: 300,
  position: 'relative',
}));

const ControlsContainer = styled(Box)(({ theme }) => ({
  display: 'flex',
  justifyContent: 'flex-end',
  gap: theme.spacing(1),
  marginBottom: theme.spacing(1),
}));

const ValueDisplay = styled(Box)<{ changed?: boolean }>(({ theme, changed }) => ({
  padding: theme.spacing(1),
  borderRadius: theme.shape.borderRadius,
  backgroundColor: changed ? theme.palette.primary.light : 'transparent',
  transition: `background-color 0.3s`,
}));

interface PredictionDisplayProps {
  eventId: string;
}

type SortOrder = 'asc' | 'desc';
type FilterType = 'all' | 'positive' | 'negative';

export const PredictionDisplay: React.FC<PredictionDisplayProps> = ({ eventId }) => {
  // Unified analytics for prediction data
  const { ml } = useUnifiedAnalytics({ ml: { autoUpdate: false } });
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [filterAnchorEl, setFilterAnchorEl] = useState<null | HTMLElement>(null);
  const [sortAnchorEl, setSortAnchorEl] = useState<null | HTMLElement>(null);
  const [changedValues, setChangedValues] = useState<Set<string>>(new Set());

  // Memoize prediction for performance
  const prediction = useMemo(() => {
    if (!ml || !ml.mlResult) return null;
    // Find prediction for this eventId if available
    // (Assume mlResult.predictions is an array of objects with eventId)
    if (Array.isArray(ml.mlResult.predictions)) {
      return ml.mlResult.predictions.find((p: { eventId: string }) => p.eventId === eventId) || null;
    }
    return null;
  }, [ml, eventId]);

  useEffect(() => {
    if (prediction) {
      const newChangedValues = new Set<string>();
      if (prediction.confidence) newChangedValues.add('confidence');
      if (prediction.recommended_stake) newChangedValues.add('stake');
      setChangedValues(newChangedValues);
      const timeout = setTimeout(() => setChangedValues(new Set()), 1000);
      return () => clearTimeout(timeout);
    }
  }, [prediction]);

  if (ml?.isLoading) {
    return (
      <PredictionContainer>
        <Typography color="textSecondary" variant="body2">
          Loading prediction...
        </Typography>
      </PredictionContainer>
    );
  }
  if (ml?.error) {
    return <NoResultsFallback />;
  }
  if (!prediction) {
    return <NoResultsFallback />;
  }

  // Transform SHAP values for visualization
  const shapData = useMemo(() => {
    if (!prediction.shap_values) return [];
    return Object.entries(prediction.shap_values)
      .map(([feature, value]) => ({
        feature,
        value: value as number,
        absValue: Math.abs(value as number),
      }))
      .filter(item => {
        if (filterType === 'positive') return item.value > 0;
        if (filterType === 'negative') return item.value < 0;
        return true;
      })
      .sort((a, b) => {
        const multiplier = sortOrder === 'desc' ? -1 : 1;
        return multiplier * (b.absValue - a.absValue);
      })
      .slice(0, 10);
  }, [prediction, filterType, sortOrder]);

  const handleFilterClick = (event: React.MouseEvent<HTMLElement>) =>
    setFilterAnchorEl(event.currentTarget);
  const handleSortClick = (event: React.MouseEvent<HTMLElement>) =>
    setSortAnchorEl(event.currentTarget);
  const handleFilterClose = () => setFilterAnchorEl(null);
  const handleSortClose = () => setSortAnchorEl(null);

  return (
    <PredictionContainer>
      <Typography gutterBottom variant="h6">
        Prediction Analysis
      </Typography>

      <ValueDisplay changed={changedValues.has('confidence')}>
        <Typography gutterBottom variant="subtitle2">
          Confidence Level
        </Typography>
        <ConfidenceBar
          color={prediction.confidence > 0.7 ? 'success' : 'primary'}
          value={prediction.confidence * 100}
          variant="determinate"
        />
        <Typography color="textSecondary" mt={1} variant="body2">
          {prediction.confidence.toFixed(2)} ({prediction.risk_level})
        </Typography>
      </ValueDisplay>

      <ValueDisplay changed={changedValues.has('stake')}>
        <Typography gutterBottom variant="subtitle2">
          Recommended Stake
        </Typography>
        <Typography color="primary" variant="h6">
          ${prediction.recommended_stake?.toFixed(2) ?? '0.00'}
        </Typography>
      </ValueDisplay>

      <Box mt={2}>
        <Box alignItems="center" display="flex" justifyContent="space-between" mb={1}>
          <Typography variant="subtitle2">Feature Impact (SHAP Values)</Typography>
          <ControlsContainer>
            <Tooltip title="Filter">
              <IconButton aria-label="Filter SHAP values" size="small" onClick={handleFilterClick}>
                <FilterListIcon />
              </IconButton>
            </Tooltip>
            <Tooltip title="Sort">
              <IconButton aria-label="Sort SHAP values" size="small" onClick={handleSortClick}>
                <SortIcon />
              </IconButton>
            </Tooltip>
          </ControlsContainer>
        </Box>

        <Menu anchorEl={filterAnchorEl} open={Boolean(filterAnchorEl)} onClose={handleFilterClose}>
          <MenuItem
            onClick={() => {
              setFilterType('all');
              handleFilterClose();
            }}
          >
            All Features
          </MenuItem>
          <MenuItem
            onClick={() => {
              setFilterType('positive');
              handleFilterClose();
            }}
          >
            Positive Impact
          </MenuItem>
          <MenuItem
            onClick={() => {
              setFilterType('negative');
              handleFilterClose();
            }}
          >
            Negative Impact
          </MenuItem>
        </Menu>

        <Menu anchorEl={sortAnchorEl} open={Boolean(sortAnchorEl)} onClose={handleSortClose}>
          <MenuItem
            onClick={() => {
              setSortOrder('desc');
              handleSortClose();
            }}
          >
            Highest Impact First
          </MenuItem>
          <MenuItem
            onClick={() => {
              setSortOrder('asc');
              handleSortClose();
            }}
          >
            Lowest Impact First
          </MenuItem>
        </Menu>

        <ShapContainer>
          <ResponsiveContainer height="100%" width="100%">
            <BarChart aria-label="SHAP Feature Impact Bar Chart" data={shapData} layout="vertical">
              <XAxis type="number" />
              <YAxis dataKey="feature" tick={{ fontSize: 12 }} type="category" width={150} />
              <RechartsTooltip
                formatter={(value: number, name: string, props: { payload: { index: number } }) => {
                  const item = shapData[props.payload.index];
                  return [
                    `${item.value.toFixed(4)} (${item.value > 0 ? 'Positive' : 'Negative'} Impact)`,
                    'SHAP Value',
                  ];
                }}
                labelFormatter={(label: string) => `Feature: ${label}`}
              />
              <Bar animationDuration={500} dataKey="absValue">
                {shapData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.value > 0 ? '#4caf50' : '#f44336'} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </ShapContainer>
      </Box>
    </PredictionContainer>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  LinearProgress,
  Tooltip,
  IconButton,
  Chip,
  Button,
  Collapse,
  Alert,
  CircularProgress,
} from '@mui/material';
import {
  TrendingUp as TrendingUpIcon,
  TrendingDown as TrendingDownIcon,
  Info as InfoIcon,
  Warning as WarningIcon,
  CheckCircle as CheckCircleIcon,
  Error as ErrorIcon,
  Refresh as RefreshIcon,
} from '@mui/icons-material';
import { formatPercentage, formatCurrency } from '../utils/formatters';
import { debounce } from 'lodash';
import type { ModelPrediction } from '../types/prediction';

interface PredictionEnhancementProps {
  predictions: ModelPrediction[];
  onStakeOptimize: (prediction: ModelPrediction) => void;
  riskProfile: 'conservative' | 'moderate' | 'aggressive';
  bankroll: number;
  onRefresh?: () => Promise<void>;
  autoRefresh?: boolean;
  refreshInterval?: number;
}

const PredictionEnhancement: React.FC<PredictionEnhancementProps> = ({
  predictions,
  onStakeOptimize,
  riskProfile,
  bankroll,
  onRefresh,
  autoRefresh = false,
  refreshInterval = 30000,
}) => {
  const [selectedPrediction, setSelectedPrediction] = useState<ModelPrediction | null>(null);
  const [showDetails, setShowDetails] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Memoize confidence level calculation
  const getConfidenceLevel = useCallback((confidence: number) => {
    if (confidence >= 0.9) return { label: 'Safe', color: 'success' as const };
    if (confidence >= 0.7) return { label: 'Medium', color: 'warning' as const };
    return { label: 'Risky', color: 'error' as const };
  }, []);

  // Memoize Kelly stake calculation
  const calculateKellyStake = useCallback(
    (prediction: ModelPrediction) => {
      const { confidence, prediction: odds } = prediction;
      const q = 1 - confidence;
      const b = odds - 1;
      const kelly = (b * confidence - q) / b;

      const riskMultiplier = {
        conservative: 0.25,
        moderate: 0.5,
        aggressive: 0.75,
      }[riskProfile];

      return Math.max(0, Math.min(kelly * riskMultiplier * bankroll, bankroll * 0.1));
    },
    [riskProfile, bankroll]
  );

  // Debounced refresh handler
  const debouncedRefresh = useMemo(
    () =>
      debounce(async () => {
        if (!onRefresh) return;
        try {
          setIsRefreshing(true);
          setError(null);
          await onRefresh();
        } catch (err) {
          setError(err instanceof Error ? err.message : 'Failed to refresh predictions');
        } finally {
          setIsRefreshing(false);
        }
      }, 1000),
    [onRefresh]
  );

  // Auto-refresh effect
  useEffect(() => {
    if (!autoRefresh || !onRefresh) return;

    const interval = setInterval(debouncedRefresh, refreshInterval);
    return () => clearInterval(interval);
  }, [autoRefresh, onRefresh, refreshInterval, debouncedRefresh]);

  // Memoize sorted predictions
  const sortedPredictions = useMemo(() => {
    return [...predictions].sort((a, b) => b.confidence - a.confidence);
  }, [predictions]);

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5">
          Enhanced Predictions
          <Tooltip title="AI-powered predictions with multi-model consensus">
            <IconButton>
              <InfoIcon />
            </IconButton>
          </Tooltip>
        </Typography>
        {onRefresh && (
          <Button
            disabled={isRefreshing}
            startIcon={isRefreshing ? <CircularProgress size={20} /> : <RefreshIcon />}
            onClick={debouncedRefresh}
          >
            Refresh
          </Button>
        )}
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: '1fr',
            md: 'repeat(2, 1fr)',
          },
          gap: 3,
        }}
      >
        {sortedPredictions.map((prediction, index) => {
          const confidenceLevel = getConfidenceLevel(prediction.confidence);
          const suggestedStake = calculateKellyStake(prediction);

          return (
            <Card
              key={prediction.eventId + index}
              sx={{
                transition: 'transform 0.2s, box-shadow 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4,
                },
              }}
            >
              <CardContent>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
                  <Typography variant="h6">{prediction.modelName}</Typography>
                  <Chip
                    color={confidenceLevel.color}
                    icon={
                      confidenceLevel.color === 'success' ? (
                        <CheckCircleIcon />
                      ) : confidenceLevel.color === 'warning' ? (
                        <WarningIcon />
                      ) : (
                        <ErrorIcon />
                      )
                    }
                    label={confidenceLevel.label}
                  />
                </Box>

                <Box sx={{ mb: 2 }}>
                  <Typography gutterBottom color="text.secondary" variant="body2">
                    Confidence Score
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <LinearProgress
                      color={confidenceLevel.color}
                      sx={{
                        flexGrow: 1,
                        height: 8,
                        borderRadius: 4,
                        transition: 'transform 0.3s ease-in-out',
                        '&:hover': {
                          transform: 'scaleY(1.2)',
                        },
                      }}
                      value={prediction.confidence * 100}
                      variant="determinate"
                    />
                    <Typography variant="body2">
                      {formatPercentage(prediction.confidence)}
                    </Typography>
                  </Box>
                </Box>

                <Box sx={{ mb: 2 }}>
                  <Typography gutterBottom color="text.secondary" variant="body2">
                    Model Performance
                  </Typography>
                  <Box
                    sx={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(3, 1fr)',
                      gap: 1,
                    }}
                  >
                    <Box>
                      <Typography color="text.secondary" variant="caption">
                        Accuracy
                      </Typography>
                      <Typography variant="body2">
                        {formatPercentage(prediction.performance.accuracy)}
                      </Typography>
                    </Box>
                    <Box>
                      <Typography color="text.secondary" variant="caption">
                        ROI
                      </Typography>
                      <Typography variant="body2">
                        {formatPercentage(prediction.performance.roi)}
                      </Typography>
                    </Box>
                    <Box>
                      <Typography color="text.secondary" variant="caption">
                        Win Rate
                      </Typography>
                      <Typography variant="body2">
                        {formatPercentage(prediction.performance.winRate)}
                      </Typography>
                    </Box>
                  </Box>
                </Box>

                <Box sx={{ mb: 2 }}>
                  <Typography gutterBottom color="text.secondary" variant="body2">
                    Suggested Stake (Kelly Criterion)
                  </Typography>
                  <Typography color="primary" variant="h6">
                    {formatCurrency(suggestedStake)}
                  </Typography>
                </Box>

                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Button
                    fullWidth
                    color="primary"
                    variant="contained"
                    onClick={() => onStakeOptimize(prediction)}
                  >
                    Optimize Stake
                  </Button>
                  <Button
                    variant="outlined"
                    onClick={() => {
                      setSelectedPrediction(prediction);
                      setShowDetails(!showDetails);
                    }}
                  >
                    Details
                  </Button>
                </Box>

                <Collapse in={showDetails && selectedPrediction === prediction}>
                  <Box sx={{ mt: 2 }}>
                    <Typography gutterBottom variant="subtitle2">
                      Top Contributing Features
                    </Typography>
                    {prediction.features.slice(0, 3).map((feature, idx) => (
                      <Box
                        key={idx}
                        sx={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          mb: 1,
                          p: 1,
                          borderRadius: 1,
                          bgcolor: 'action.hover',
                          transition: 'background-color 0.2s',
                          '&:hover': {
                            bgcolor: 'action.selected',
                          },
                        }}
                      >
                        <Typography variant="body2">{feature.name}</Typography>
                        <Typography color="text.secondary" variant="body2">
                          {formatPercentage(feature.importance)}
                        </Typography>
                      </Box>
                    ))}
                  </Box>
                </Collapse>
              </CardContent>
            </Card>
          );
        })}
      </Box>
    </Box>
  );
};

export default React.memo(PredictionEnhancement);

import React from 'react';
import { cn } from '../../utils/classNames';
import { motion, AnimatePresence } from 'framer-motion';

export interface ProgressProps {
  value: number;
  max?: number;
  size?: 'sm' | 'md' | 'lg';
  variant?: 'default' | 'success' | 'warning' | 'danger';
  showValue?: boolean;
  valuePosition?: 'top' | 'right' | 'bottom';
  label?: string;
  className?: string;
  animate?: boolean;
}

const sizes = {
  sm: 'h-1',
  md: 'h-2',
  lg: 'h-3',
};

const variants = {
  default: {
    base: 'bg-gray-200 dark:bg-gray-700',
    bar: 'bg-primary-500',
  },
  success: {
    base: 'bg-green-100 dark:bg-green-800/30',
    bar: 'bg-green-500',
  },
  warning: {
    base: 'bg-yellow-100 dark:bg-yellow-800/30',
    bar: 'bg-yellow-500',
  },
  danger: {
    base: 'bg-red-100 dark:bg-red-800/30',
    bar: 'bg-red-500',
  },
};

export const Progress: React.FC<ProgressProps> = ({
  value,
  max = 100,
  size = 'md',
  variant = 'default',
  showValue = false,
  valuePosition = 'right',
  label,
  className,
  animate = true,
}) => {
  const percentage = Math.min(Math.max((value / max) * 100, 0), 100);

  const renderValue = () => (
    <span className="text-sm font-medium text-gray-700 dark:text-gray-200">
      {Math.round(percentage)}%
    </span>
  );

  return (
    <div className={cn('w-full', className)}>
      {(label || (showValue && valuePosition === 'top')) && (
        <div className="mb-1 flex justify-between items-center">
          {label && (
            <span className="text-sm font-medium text-gray-700 dark:text-gray-200">{label}</span>
          )}
          {showValue && valuePosition === 'top' && renderValue()}
        </div>
      )}
      <div className="relative flex items-center">
        <div
          className={cn('w-full overflow-hidden rounded-full', variants[variant].base, sizes[size])}
        >
          <motion.div
            animate={{ width: `${percentage}%` }}
            className={cn('h-full rounded-full', variants[variant].bar)}
            initial={animate ? { width: 0 } : false}
            transition={{ duration: 0.5, ease: 'easeOut' }}
          />
        </div>
        {showValue && valuePosition === 'right' && (
          <div className="ml-3 flex-shrink-0">{renderValue()}</div>
        )}
      </div>
      {showValue && valuePosition === 'bottom' && (
        <div className="mt-1 flex justify-end">{renderValue()}</div>
      )}
    </div>
  );
};

