}));

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

const TabPanel = (props: TabPanelProps) => {
  const { children, value, index, ...other } = props;

  return (
    <div
      aria-labelledby={`updates-tab-${index}`}
      hidden={value !== index}
      id={`updates-tabpanel-${index}`}
      role="tabpanel"
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
};

export const RealTimeUpdates: React.FC<{ sport: Sport }> = ({ sport }) => {
  const [value, setValue] = useState(0);
  const [expanded, setExpanded] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [updates, setUpdates] = useState<{
    odds: any[];
    injuries: any[];
    lineMovements: any[];
    news: any[];
    predictions: any[];
  }>({
    odds: [],
    injuries: [],
    lineMovements: [],
    news: [],
    predictions: [],
  });

  const { sendMessage, isConnected } = useWebSocket(
    process.env.VITE_WS_URL || 'ws://localhost:3000',
    {
      onMessage: data => {
        if (data.type === 'prediction:update') {
          setUpdates(prev => ({
            ...prev,
            predictions: [data.payload, ...prev.predictions].slice(0, 10),
          }));
        } else if (data.type === 'odds:update') {
          setUpdates(prev => ({
            ...prev,
            odds: [data.payload, ...prev.odds].slice(0, 10),
          }));
        } else if (data.type === 'model:metrics') {
          console.log('Model metrics:', data.payload);
        }
      },
    }
  );

  const { showBoundary } = useErrorBoundary();

  const handleError = useCallback(
    (error: Error) => {
      setError(error.message);
      showBoundary(error);
    },
    [showBoundary]
  );

  const loadUpdates = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const sportUpdates = await realTimeUpdates.getSportUpdates(sport);
      setUpdates(prev => ({
        ...prev,
        ...sportUpdates,
      }));
    } catch (error) {
      handleError(error as Error);
    } finally {
      setLoading(false);
    }
  }, [sport, handleError]);

  useEffect(() => {
    loadUpdates();
  }, [loadUpdates]);

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setValue(newValue);
  };

  const formatTimestamp = (timestamp: number) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString();
  };

  const handleRefresh = () => {
    loadUpdates();
  };

  if (!isConnected) {
    return (
      <UpdatesCard>
        <CardContent>
          <Alert severity="warning">WebSocket connection lost. Attempting to reconnect...</Alert>
        </CardContent>
      </UpdatesCard>
    );
  }

  return (
    <UpdatesCard>
      <CardContent>
        <Box alignItems="center" display="flex" justifyContent="space-between" mb={2}>
          <Typography variant="h6">Real-Time Updates</Typography>
          <Box>
            <IconButton disabled={loading} onClick={handleRefresh}>
              <RefreshIcon />
            </IconButton>
            <IconButton onClick={() => setExpanded(!expanded)}>
              {expanded ? <ExpandLessIcon /> : <ExpandMoreIcon />}
            </IconButton>
          </Box>
        </Box>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        <Collapse in={expanded}>
          <Tabs
            sx={{ borderBottom: 1, borderColor: 'divider' }}
            value={value}
            variant="fullWidth"
            onChange={handleTabChange}
          >
            <Tab label="Odds" />
            <Tab label="Injuries" />
            <Tab label="Line Movements" />
            <Tab label="News" />
            <Tab label="Predictions" />
          </Tabs>

          {loading ? (
            <Box display="flex" justifyContent="center" p={3}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              <TabPanel index={0} value={value}>
                <List>
                  {updates.odds.map((odds, index) => (
                    <React.Fragment key={odds.propId}>
                      <ListItem>
                        <ListItemIcon>
                          {odds.movement.direction === 'up' ? (
                            <TrendingUpIcon color="success" />
                          ) : odds.movement.direction === 'down' ? (
                            <TrendingDownIcon color="error" />
                          ) : (
                            <InfoIcon color="action" />
                          )}
                        </ListItemIcon>
                        <ListItemText
                          primary={`${odds.value} (${odds.movement.direction})`}
                          secondary={`Updated ${formatTimestamp(odds.timestamp)}`}
                        />
                        <Box display="flex" gap={1}>
                          <Chip color="success" label={`O ${odds.overMultiplier}x`} size="small" />
                          <Chip color="error" label={`U ${odds.underMultiplier}x`} size="small" />
                        </Box>
                      </ListItem>
                      {index < updates.odds.length - 1 && <Divider />}
                    </React.Fragment>
                  ))}
                </List>
              </TabPanel>

              <TabPanel index={1} value={value}>
                <List>
                  {updates.injuries.map((injury, index) => (
                    <React.Fragment key={injury.playerId}>
                      <ListItem>
                        <ListItemIcon>
                          <LocalHospitalIcon
                            color={
                              injury.status === 'out'
                                ? 'error'
                                : injury.status === 'questionable'
                                  ? 'warning'
                                  : 'success'
                            }
                          />
                        </ListItemIcon>
                        <ListItemText
                          primary={`${injury.playerName} (${injury.team})`}
                          secondary={
                            <>
                              <Typography color="textPrimary" component="span" variant="body2">
                                {injury.status.toUpperCase()}
                              </Typography>
                              {` - ${injury.injury}`}
                              {injury.expectedReturn && (
                                <Typography color="textSecondary" component="span" variant="body2">
                                  {` - Expected return: ${injury.expectedReturn}`}
                                </Typography>
                              )}
                            </>
                          }
                        />
                      </ListItem>
                      {index < updates.injuries.length - 1 && <Divider />}
                    </React.Fragment>
                  ))}
                </List>
              </TabPanel>

              <TabPanel index={2} value={value}>
                <List>
                  {updates.lineMovements.map((movement, index) => (
                    <React.Fragment key={`${movement.propId}_${movement.timestamp}`}>
                      <ListItem>
                        <ListItemIcon>
                          {movement.direction === 'up' ? (
                            <TrendingUpIcon color="success" />
                          ) : (
                            <TrendingDownIcon color="error" />
                          )}
                        </ListItemIcon>
                        <ListItemText
                          primary={`${movement.oldValue} → ${movement.newValue}`}
                          secondary={`Updated ${formatTimestamp(movement.timestamp)}`}
                        />
                        <Chip
                          color={movement.confidence >= 80 ? 'success' : 'warning'}
                          label={`${movement.confidence}% confidence`}
                          size="small"
                        />
                      </ListItem>
                      {index < updates.lineMovements.length - 1 && <Divider />}
                    </React.Fragment>
                  ))}
                </List>
              </TabPanel>

              <TabPanel index={3} value={value}>
                <List>
                  {updates.news.map((news, index) => (
                    <React.Fragment key={news.id}>
                      <ListItem>
                        <ListItemIcon>
                          <NotificationsIcon
                            color={
                              news.impact === 'high'
                                ? 'error'
                                : news.impact === 'medium'
                                  ? 'warning'
                                  : 'info'
                            }
                          />
                        </ListItemIcon>
                        <ListItemText
                          primary={news.title}
                          secondary={
                            <>
                              <Typography color="textPrimary" component="span" variant="body2">
                                {news.type.toUpperCase()}
                              </Typography>
                              {` - ${news.content}`}
                              <Typography color="textSecondary" component="span" variant="body2">
                                {` - ${formatTimestamp(news.timestamp)}`}
                              </Typography>
                            </>
                          }
                        />
                      </ListItem>
                      {index < updates.news.length - 1 && <Divider />}
                    </React.Fragment>
                  ))}
                </List>
              </TabPanel>

              <TabPanel index={4} value={value}>
                <List>
                  {updates.predictions.map((prediction, index) => (
                    <React.Fragment key={prediction.id}>
                      <ListItem>
                        <ListItemIcon>
                          <Tooltip
                            title={`Confidence: ${(prediction.confidence * 100).toFixed(1)}%`}
                          >
                            <Box>
                              {prediction.confidence > 0.8 ? (
                                <TrendingUpIcon color="success" />
                              ) : prediction.confidence > 0.6 ? (
                                <InfoIcon color="info" />
                              ) : (
                                <WarningIcon color="warning" />
                              )}
                            </Box>
                          </Tooltip>
                        </ListItemIcon>
                        <ListItemText
                          primary={`${prediction.event} - ${prediction.market}`}
                          secondary={
                            <>
                              <Typography color="textPrimary" component="span" variant="body2">
                                Prediction: {prediction.prediction}
                              </Typography>
                              <br />
                              <Typography color="textSecondary" component="span" variant="body2">
                                Updated {formatTimestamp(prediction.timestamp)}
                              </Typography>
                            </>
                          }
                        />
                        <Box display="flex" gap={1}>
                          <Chip
                            color={
                              prediction.confidence > 0.8
                                ? 'success'
                                : prediction.confidence > 0.6
                                  ? 'info'
                                  : 'warning'
                            }
                            label={`Confidence: ${(prediction.confidence * 100).toFixed(1)}%`}
                            size="small"
                          />
                        </Box>
                      </ListItem>
                      {index < updates.predictions.length - 1 && <Divider />}
                    </React.Fragment>
                  ))}
                </List>
              </TabPanel>
            </>
          )}
        </Collapse>
      </CardContent>
    </UpdatesCard>
  );
};

import React, { useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useRealtimePredictions } from '../hooks/useRealtimePredictions';
import { usePredictions } from '../hooks/usePredictions';
import { ConfidenceIndicator } from './ConfidenceIndicator';
import { ShapValueDisplay } from './ShapValueDisplay';

interface RealtimePredictionDisplayProps {
  predictionId: string;
  className?: string;
}

export function RealtimePredictionDisplay({
  predictionId,
  className = '',
}: RealtimePredictionDisplayProps) {
  const { isConnected, isConnecting, lastMessageTimestamp, isStale } = useRealtimePredictions({
    channels: ['predictions'],
    onError: error => {
      console.error('WebSocket error:', error);
    },
  });

  const { getPrediction, getConfidenceColor } = usePredictions();
  const prediction = getPrediction(predictionId);

  const formatTimestamp = (timestamp: number | null) => {
    if (!timestamp) return 'Never';
    const date = new Date(timestamp);
    return date.toLocaleTimeString();
  };

  if (!prediction) {
    return (
      <div className={`p-4 rounded-lg bg-gray-100 dark:bg-gray-800 ${className}`}>
        <div className="flex items-center justify-between">
          <span className="text-gray-500 dark:text-gray-400">Loading prediction...</span>
          {isConnecting && (
            <div className="h-4 w-4 animate-spin rounded-full border-2 border-primary-500 border-t-transparent" />
          )}
        </div>
      </div>
    );
  }

  return (
    <motion.div
      animate={{ opacity: 1, y: 0 }}
      className={`p-4 rounded-lg bg-white dark:bg-gray-800 shadow-sm ${className}`}
      exit={{ opacity: 0, y: -20 }}
      initial={{ opacity: 0, y: 20 }}
    >
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold">Real-time Prediction</h3>
        <div className="flex items-center space-x-2">
          <span className={`text-sm ${getConfidenceColor(prediction.confidence)}`}>
            {Math.round(prediction.confidence * 100)}% Confidence
          </span>
          <ConfidenceIndicator value={prediction.confidence} />
        </div>
      </div>

      <div className="space-y-4">
        {/* Prediction Value */}
        <div className="flex items-center justify-between">
          <span className="text-gray-600 dark:text-gray-400">Predicted Value</span>
          <span className="text-xl font-bold">{prediction.value.toFixed(2)}</span>
        </div>

        {/* SHAP Values */}
        <div className="space-y-2">
          <h4 className="text-sm font-medium text-gray-600 dark:text-gray-400">
            Feature Importance
          </h4>
          <div className="space-y-2">
            {prediction.factors.map(factor => (
              <ShapValueDisplay
                key={factor.name}
                name={factor.name}
                value={factor.impact}
                weight={factor.weight}
              />
            ))}
          </div>
        </div>

        {/* Connection Status and Timestamp */}
        <div className="flex items-center justify-between text-sm">
          <div className="flex items-center space-x-2">
            <div
              className={`h-2 w-2 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500'}`}
            />
            <span className={isConnected ? 'text-green-500' : 'text-red-500'}>
              {isConnected ? 'Connected' : 'Disconnected'}
            </span>
          </div>
          <div className="flex items-center space-x-2">
            <span className={`text-sm ${isStale ? 'text-red-500' : 'text-green-500'}`}>
              {isStale ? 'Stale' : 'Live'}
            </span>
            <span className="text-gray-500">
              Last update: {formatTimestamp(lastMessageTimestamp)}
            </span>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../../providers/AuthProvider';

interface RegisterFormProps {
  onSuccess?: () => void;
  onToggleForm?: () => void;
}

const RegisterForm: React.FC<RegisterFormProps> = ({ onSuccess, onToggleForm }) => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    confirmPassword: '',
    username: '',
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { register } = useAuth();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const validateForm = () => {
    if (!formData.email || !formData.password || !formData.username) {
      setError('All fields are required');
      return false;
    }
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return false;
    }
    if (formData.password.length < 8) {
      setError('Password must be at least 8 characters long');
      return false;
    }
    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!validateForm()) return;

    setIsLoading(true);
    try {
      await register(formData.email, formData.password, formData.username);
      onSuccess?.();
    } catch (err) {
      setError('Registration failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <motion.div
      animate={{ opacity: 1, y: 0 }}
      className="w-full max-w-md mx-auto"
      exit={{ opacity: 0, y: -20 }}
      initial={{ opacity: 0, y: 20 }}
    >
      <form className="space-y-6" onSubmit={handleSubmit}>
        <div>
          <label
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
            htmlFor="username"
          >
            Username
          </label>
          <input
            required
            className="input-primary mt-1"
            id="username"
            name="username"
            placeholder="johndoe"
            type="text"
            value={formData.username}
            onChange={handleChange}
          />
        </div>

        <div>
          <label
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
            htmlFor="email"
          >
            Email
          </label>
          <input
            required
            className="input-primary mt-1"
            id="email"
            name="email"
            placeholder="you@example.com"
            type="email"
            value={formData.email}
            onChange={handleChange}
          />
        </div>

        <div>
          <label
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
            htmlFor="password"
          >
            Password
          </label>
          <input
            required
            className="input-primary mt-1"
            id="password"
            name="password"
            placeholder="••••••••"
            type="password"
            value={formData.password}
            onChange={handleChange}
          />
        </div>

        <div>
          <label
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
            htmlFor="confirmPassword"
          >
            Confirm Password
          </label>
          <input
            required
            className="input-primary mt-1"
            id="confirmPassword"
            name="confirmPassword"
            placeholder="••••••••"
            type="password"
            value={formData.confirmPassword}
            onChange={handleChange}
          />
        </div>

        {error && (
          <motion.p
            animate={{ opacity: 1 }}
            className="text-sm text-red-600 dark:text-red-400"
            initial={{ opacity: 0 }}
          >
            {error}
          </motion.p>
        )}

        <button
          className="btn-primary w-full flex justify-center"
          disabled={isLoading}
          type="submit"
        >
          {isLoading ? (
            <svg
              className="animate-spin h-5 w-5 text-white"
              fill="none"
              viewBox="0 0 24 24"
              xmlns="http://www.w3.org/2000/svg"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              />
              <path
                className="opacity-75"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                fill="currentColor"
              />
            </svg>
          ) : (
            'Sign Up'
          )}
        </button>

        <p className="text-center text-sm text-gray-600 dark:text-gray-400">
          Already have an account?{' '}
          <button
            className="text-primary-600 dark:text-primary-400 hover:underline focus:outline-none"
            type="button"
            onClick={onToggleForm}
          >
            Sign in
          </button>
        </p>
      </form>
    </motion.div>
  );
};

export default React.memo(RegisterForm);

import React, { useState, useEffect } from 'react';
import axios from 'axios';

interface RiskProfile {
  id: string;
  name: string;
  maxStake: number;
  maxExposure: number;
  stopLoss: number;
  takeProfit: number;
  kellyFraction: number;
  isActive: boolean;
}

interface ActiveBet {
  id: string;
  event: string;
  stake: number;
  odds: number;
  potentialWin: number;
  risk: 'low' | 'medium' | 'high';
  expiresAt: string;
}


const RiskManagerPage: React.FC = () => {

  // State for risk profiles and active bets
  const [profiles, setProfiles] = useState<RiskProfile[]>([]);
  const [activeBets, setActiveBets] = useState<ActiveBet[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Modal state for creating new profile
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);

  // Fetch risk profiles and active bets on mount
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const [profilesRes, betsRes] = await Promise.all([
          axios.get<RiskProfile[]>('/api/risk-profiles'),
          axios.get<ActiveBet[]>('/api/active-bets'),
        ]);
        setProfiles(profilesRes.data);
        setActiveBets(betsRes.data);
      } catch (err) {
        if (axios.isAxiosError(err)) {
          setError(err.response?.data?.message || err.message || 'Failed to load data');
        } else if (err instanceof Error) {
          setError(err.message);
        } else {
          setError('Failed to load data');
        }
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const activeProfile = profiles.find(p => p.isActive);
  const totalExposure = activeBets.reduce((sum, bet) => sum + bet.stake, 0);
  const maxPotentialLoss = totalExposure;
  const maxPotentialWin = activeBets.reduce((sum, bet) => sum + bet.potentialWin, 0);

  const getRiskColor = (risk: ActiveBet['risk']) => {
    switch (risk) {
      case 'low':
        return 'text-green-600 dark:text-green-400';
      case 'medium':
        return 'text-yellow-600 dark:text-yellow-400';
      case 'high':
        return 'text-red-600 dark:text-red-400';
      default:
        return 'text-gray-600 dark:text-gray-400';
    }
  };


  return (
    <>
      <main className="section space-y-6 lg:space-y-8 animate-fade-in">
        <div className="modern-card p-6 lg:p-8">
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-8">
          <h1 className="text-2xl lg:text-3xl font-bold">⚖️ Risk Manager</h1>
          <button className="modern-button" onClick={() => setIsModalOpen(true)}>
            Create New Profile
          </button>
        </div>
        {/* Loading/Error State */}
        {loading ? (
          <div className="text-center text-gray-500 dark:text-gray-400">Loading...</div>
        ) : error ? (
          <div className="text-center text-red-600">{error}</div>
        ) : (
          <>
            {/* Overview Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
              <div className="modern-card p-6">
                <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-2">
                  Active Profile
                </h3>
                <p className="text-2xl font-bold">{activeProfile?.name || 'None'}</p>
              </div>
              <div className="modern-card p-6">
                <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-2">
                  Total Exposure
                </h3>
                <p className="text-2xl font-bold">${totalExposure.toFixed(2)}</p>
              </div>
              <div className="modern-card p-6">
                <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-2">
                  Max Potential Loss
                </h3>
                <p className="text-2xl font-bold text-red-600">-${maxPotentialLoss.toFixed(2)}</p>
              </div>
              <div className="modern-card p-6">
                <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-2">
                  Max Potential Win
                </h3>
                <p className="text-2xl font-bold text-green-600">+${maxPotentialWin.toFixed(2)}</p>
              </div>
            </div>
            {/* Risk Profiles */}
            <div className="mb-8">
              <h2 className="text-lg font-bold mb-4">Risk Profiles</h2>
              {profiles.length === 0 ? (
                <div className="text-gray-500 dark:text-gray-400">
                  No risk profiles available.
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {profiles.map(profile => (
                    <div
                      key={profile.id}
                      className={`modern-card p-6 ${profile.isActive ? 'ring-2 ring-primary-500' : ''}`}
                    >
                      <div className="flex justify-between items-start mb-4">
                        <h3 className="text-lg font-bold">{profile.name}</h3>
                        {profile.isActive && (
                          <span className="px-2 py-1 bg-primary-100 text-primary-700 text-xs font-medium rounded-full">
                            Active
                          </span>
                        )}
                      </div>
                      <div className="space-y-2 text-sm">
                        <div className="flex justify-between">
                          <span className="text-gray-500 dark:text-gray-400">Max Stake</span>
                          <span className="font-medium">${profile.maxStake}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gray-500 dark:text-gray-400">Max Exposure</span>
