type CreateProfileFormProps = {
  onSuccess: (profile: RiskProfile) => void;
  onCancel: () => void;
};

/**
 * Modal form for creating a new risk profile.
 * Integrates with /api/risk-profiles endpoint.
 */
const CreateProfileForm: React.FC<CreateProfileFormProps> = ({ onSuccess, onCancel }) => {
  const [form, setForm] = React.useState<Omit<RiskProfile, 'id' | 'isActive'>>({
    name: '',
    maxStake: 0,
    maxExposure: 0,
    stopLoss: 0,
    takeProfit: 0,
    kellyFraction: 1,
  });
  const [submitting, setSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: name === 'name' ? value : Number(value) }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    setError(null);
    try {
      const res = await axios.post<RiskProfile>('/api/risk-profiles', form);
      onSuccess(res.data);
    } catch (err: unknown) {
      if (axios.isAxiosError && axios.isAxiosError(err)) {
        setError(err.response?.data?.message || err.message || 'Failed to create profile');
      } else if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('Failed to create profile');
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label className="block text-sm font-medium mb-1">Name</label>
        <input name="name" value={form.name} onChange={handleChange} className="modern-input w-full" required />
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium mb-1">Max Stake</label>
          <input name="maxStake" type="number" value={form.maxStake} onChange={handleChange} className="modern-input w-full" min={0} required />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Max Exposure</label>
          <input name="maxExposure" type="number" value={form.maxExposure} onChange={handleChange} className="modern-input w-full" min={0} required />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Stop Loss</label>
          <input name="stopLoss" type="number" value={form.stopLoss} onChange={handleChange} className="modern-input w-full" min={0} required />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Take Profit</label>
          <input name="takeProfit" type="number" value={form.takeProfit} onChange={handleChange} className="modern-input w-full" min={0} required />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Kelly Fraction</label>
          <input name="kellyFraction" type="number" value={form.kellyFraction} onChange={handleChange} className="modern-input w-full" min={0.01} step={0.01} required />
        </div>
      </div>
      {error && <div className="text-red-600 text-sm">{error}</div>}
      <div className="flex gap-2 mt-4">
        <button type="submit" className="modern-button" disabled={submitting}>
          {submitting ? 'Creating...' : 'Create'}
        </button>
        <button type="button" className="modern-button" onClick={onCancel} disabled={submitting}>
          Cancel
        </button>
      </div>
    </form>
  );
};


