    >
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="h6">Feature Impact Analysis</Typography>
          <Tooltip title="SHAP values show how each feature contributes to the prediction">
            <Info color="action" fontSize="small" />
          </Tooltip>
        </Box>
      </DialogTitle>

      <DialogContent>
        <Box sx={{ mb: 3 }}>
          <Typography gutterBottom variant="subtitle1">
            {feature.feature}
          </Typography>
          {feature.description && (
            <Typography paragraph color="text.secondary" variant="body2">
              {feature.description}
            </Typography>
          )}
        </Box>

        <Divider sx={{ my: 2 }} />

        <Box sx={{ mb: 3 }}>
          <Typography gutterBottom variant="subtitle2">
            Impact Analysis
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            <Typography
              color={getImpactColor(feature.impact)}
              sx={{ fontWeight: 'bold' }}
              variant="h4"
            >
              {feature.impact > 0 ? '+' : ''}
              {feature.impact.toFixed(3)}
            </Typography>
            <Typography color="text.secondary" variant="body2">
              {getImpactLabel(feature.impact)}
            </Typography>
          </Box>
        </Box>

        {feature.details && (
          <>
            <Divider sx={{ my: 2 }} />
            <Typography gutterBottom variant="subtitle2">
              Additional Details
            </Typography>
            <Typography color="text.secondary" variant="body2">
              {feature.details}
