          <Box sx={{ mt: 3 }}>
            <Typography gutterBottom variant="subtitle2">
              Feature Weight
            </Typography>
            <Typography color="text.secondary" variant="body2">
              This feature contributes {feature.weight.toFixed(2)}% to the overall prediction
            </Typography>
          </Box>
        )}
      </DialogContent>

      <DialogActions>
        <Button color="primary" onClick={onClose}>
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
