interface ShapVisualizationProps {
  features: ShapFeature[];
  title: string;
  maxFeatures?: number;
  isLoading?: boolean;
}

const ShapVisualization: React.FC<ShapVisualizationProps> = ({
  features,
  title,
  maxFeatures = 8,
  isLoading = false,
}) => {
  if (isLoading) {
    return (
