  const sortedFeatures = [...features]
    .sort((a, b) => Math.abs(b.impact) - Math.abs(a.impact))
    .slice(0, maxFeatures);

  const maxImpact = Math.max(...sortedFeatures.map(f => Math.abs(f.impact)));

  return (
    <Box>
      <Typography gutterBottom variant="h6">
        {title}
      </Typography>
