import React, { useState, useEffect } from 'react';
import {
  Paper,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  IconButton,
  Box,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
} from '@mui/material';
import { Delete as DeleteIcon, Refresh as RefreshIcon } from '@mui/icons-material';
import { errorLogger, ErrorLog } from '../../utils/errorLogger';

export const ErrorLogs: React.FC = () => {
  const [logs, setLogs] = useState<ErrorLog[]>([]);
  const [severityFilter, setSeverityFilter] = useState<ErrorLog['severity'] | 'all'>('all');

  const fetchLogs = () => {
    const allLogs = errorLogger.getLogs();
    setLogs(allLogs);
  };

  useEffect(() => {
    fetchLogs();
    // Refresh logs every 30 seconds
    const interval = setInterval(fetchLogs, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleClearLogs = () => {
    errorLogger.clearLogs();
    setLogs([]);
  };

  const handleSeverityChange = (event: any) => {
    const severity = event.target.value;
    setSeverityFilter(severity);
  };

  const filteredLogs =
    severityFilter === 'all' ? logs : logs.filter(log => log.severity === severityFilter);

  const getSeverityColor = (severity: ErrorLog['severity']) => {
    switch (severity) {
      case 'error':
        return 'error';
      case 'warning':
        return 'warning';
      case 'info':
        return 'info';
      default:
        return 'default';
    }
  };

  return (
    <Paper sx={{ p: 3, mb: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">Error Logs</Typography>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <FormControl sx={{ minWidth: 120 }}>
            <InputLabel>Severity</InputLabel>
            <Select
              label="Severity"
              size="small"
              value={severityFilter}
              onChange={handleSeverityChange}
            >
              <MenuItem value="all">All</MenuItem>
              <MenuItem value="error">Error</MenuItem>
              <MenuItem value="warning">Warning</MenuItem>
              <MenuItem value="info">Info</MenuItem>
            </Select>
          </FormControl>
          <IconButton color="primary" onClick={fetchLogs}>
            <RefreshIcon />
          </IconButton>
          <IconButton color="error" onClick={handleClearLogs}>
            <DeleteIcon />
          </IconButton>
        </Box>
      </Box>

      <TableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Timestamp</TableCell>
              <TableCell>Severity</TableCell>
              <TableCell>Message</TableCell>
              <TableCell>Context</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {filteredLogs.map((log, index) => (
              <TableRow key={index}>
                <TableCell>{new Date(log.timestamp).toLocaleString()}</TableCell>
                <TableCell>
                  <Chip color={getSeverityColor(log.severity)} label={log.severity} size="small" />
                </TableCell>
                <TableCell>{log.message}</TableCell>
                <TableCell>
                  {log.context ? (
                    <pre style={{ margin: 0, whiteSpace: 'pre-wrap' }}>
                      {JSON.stringify(log.context, null, 2)}
                    </pre>
                  ) : (
                    '-'
                  )}
                </TableCell>
              </TableRow>
            ))}
            {filteredLogs.length === 0 && (
              <TableRow>
                <TableCell align="center" colSpan={4}>
                  No logs found
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
    </Paper>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Slider,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Button,
  Paper,
  Grid,
} from '@mui/material';
import { predictionService } from '../../services/predictionService';

interface ModelSettingsProps {
  onSettingsChange?: (settings: {
    modelType: string;
    confidenceThreshold: number;
    kellyThreshold: number;
  }) => void;
}

export const ModelSettings: React.FC<ModelSettingsProps> = ({ onSettingsChange }) => {
  const [modelType, setModelType] = useState('xgboost');
  const [confidenceThreshold, setConfidenceThreshold] = useState(0.7);
  const [kellyThreshold, setKellyThreshold] = useState(0.1);
  const [performance, setPerformance] = useState<any>(null);

  useEffect(() => {
    const fetchPerformance = async () => {
      const data = await predictionService.getModelPerformance(modelType);
      setPerformance(data);
    };
    fetchPerformance();
  }, [modelType]);

  const handleModelChange = (event: any) => {
    const newModelType = event.target.value;
    setModelType(newModelType);
    if (onSettingsChange) {
      onSettingsChange({
        modelType: newModelType,
        confidenceThreshold,
        kellyThreshold,
      });
    }
  };

  const handleConfidenceChange = (_: any, newValue: number | number[]) => {
    setConfidenceThreshold(newValue as number);
    if (onSettingsChange) {
      onSettingsChange({
        modelType,
        confidenceThreshold: newValue as number,
        kellyThreshold,
      });
    }
  };

  const handleKellyChange = (_: any, newValue: number | number[]) => {
    setKellyThreshold(newValue as number);
    if (onSettingsChange) {
      onSettingsChange({
        modelType,
        confidenceThreshold,
        kellyThreshold: newValue as number,
      });
    }
  };

  const handleClearCache = async () => {
    predictionService.clearCaches();
  };

  return (
    <Paper sx={{ p: 3, mb: 3 }}>
      <Typography gutterBottom variant="h6">
        Model Settings
      </Typography>

      <Grid container spacing={3}>
        <Grid sx={{ width: { xs: '100%', md: '33.33%' } }}>
          <FormControl fullWidth>
            <InputLabel>Model Type</InputLabel>
            <Select label="Model Type" value={modelType} onChange={handleModelChange}>
              <MenuItem value="xgboost">XGBoost</MenuItem>
              <MenuItem value="lightgbm">LightGBM</MenuItem>
              <MenuItem value="catboost">CatBoost</MenuItem>
              <MenuItem value="neuralNetwork">Neural Network</MenuItem>
              <MenuItem value="randomForest">Random Forest</MenuItem>
            </Select>
          </FormControl>
        </Grid>

        <Grid sx={{ width: { xs: '100%', md: '33.33%' } }}>
          <Typography gutterBottom>Confidence Threshold</Typography>
          <Slider
            max={1}
            min={0}
            step={0.05}
            value={confidenceThreshold}
            valueLabelDisplay="auto"
            valueLabelFormat={value => `${(value * 100).toFixed(0)}%`}
            onChange={handleConfidenceChange}
          />
        </Grid>

        <Grid sx={{ width: { xs: '100%', md: '33.33%' } }}>
          <Typography gutterBottom>Kelly Criterion Threshold</Typography>
          <Slider
            max={0.5}
            min={0}
            step={0.01}
            value={kellyThreshold}
            valueLabelDisplay="auto"
            valueLabelFormat={value => `${(value * 100).toFixed(0)}%`}
            onChange={handleKellyChange}
          />
        </Grid>

        <Grid sx={{ width: '100%' }}>
          <Button color="secondary" sx={{ mt: 2 }} variant="contained" onClick={handleClearCache}>
            Clear Cache
          </Button>
        </Grid>

        {performance && (
          <Grid sx={{ width: '100%' }}>
            <Box sx={{ mt: 2 }}>
              <Typography gutterBottom variant="subtitle1">
                Model Performance
              </Typography>
              <Grid container spacing={2}>
                <Grid sx={{ width: '33.33%' }}>
                  <Typography variant="body2">Accuracy</Typography>
                  <Typography variant="h6">{(performance.accuracy * 100).toFixed(1)}%</Typography>
                </Grid>
                <Grid sx={{ width: '33.33%' }}>
                  <Typography variant="body2">ROI</Typography>
                  <Typography variant="h6">{(performance.roi * 100).toFixed(1)}%</Typography>
                </Grid>
                <Grid sx={{ width: '33.33%' }}>
                  <Typography variant="body2">Win Rate</Typography>
                  <Typography variant="h6">{(performance.win_rate * 100).toFixed(1)}%</Typography>
                </Grid>
              </Grid>
            </Box>
          </Grid>
        )}
      </Grid>
    </Paper>
  );
};

