  const lastUpdate: string = performance?.data?.[0]?.timestamp || '';
  const fallbackActive: boolean = false; // Set as needed or infer from data
  const simulationMode: boolean = false; // Set as needed or infer from data

  // Only assign these from enhancedAnalysis (not from drift/realtime) to avoid duplicate declarations
  const sentiment = enhancedAnalysis.sentiment || {};
  const odds = enhancedAnalysis.marketData?.odds || {};
  const consensus = enhancedAnalysis.marketData?.consensus || {};
  const injuries = enhancedAnalysis.injuries || [];
  const patterns = enhancedAnalysis.patterns || [];
  const explainability = enhancedAnalysis.explainability || {};
  const aiStatus = modelStatus || {};

  // THEME: Replace theme.palette.* with hardcoded values for now
  const primaryColor = theme.theme === 'dark' ? '#1976d2' : '#1976d2'; // fallback to MUI blue
  const textColor = theme.theme === 'dark' ? '#fff' : '#222';

  // Local loading overlay
  if (loading || !enhancedAnalysis) {
    return (
      <Box className="flex flex-col items-center justify-center min-h-[300px]">
        <CircularProgress />
        <Typography variant="body2" className="mt-2 text-gray-400">Loading advanced analytics...</Typography>
      </Box>
    );
  }

  // Sentiment, Odds/Consensus, Injuries, Patterns, Explainability, and Model status are all defined above and should not be redeclared here.
  // (Removed duplicate declarations)

  return (
    <Box className="w-full max-w-6xl mx-auto p-4">
      <Grid container spacing={2}>
        {/* Model/AI status */}
        <Grid item xs={12} md={4}>
          <Card className="bg-gray-900 text-white dark:bg-gray-800">
            <CardContent>
              <Typography variant="h6" gutterBottom><FaRobot className="inline mr-2" />AI Model Status</Typography>
              <StatusChip label={`Status: ${aiStatus.status || 'Unknown'}`} color={aiStatus.status === 'Online' ? 'success' : 'warning'} icon={<FaRobot />} />
              <StatusChip label={`Accuracy: ${aiStatus.accuracy ? `${(aiStatus.accuracy * 100).toFixed(1)}%` : 'N/A'}`} color="info" icon={<FaBolt />} />
              <StatusChip label={`Confidence: ${aiStatus.confidence ? `${(aiStatus.confidence * 100).toFixed(1)}%` : 'N/A'}`} color="primary" icon={<FaBolt />} />
              <Typography variant="caption" className="block mt-2 text-gray-400">Last update: {lastUpdate ? new Date(lastUpdate).toLocaleTimeString() : 'N/A'}</Typography>
              {simulationMode && <StatusChip label="Simulation Mode" color="warning" icon={<FaExclamationTriangle />} />}
              {fallbackActive && <StatusChip label="Fallback Active" color="error" icon={<FaExclamationTriangle />} />}
              {error && <Typography color="error" variant="body2">{error}</Typography>}
            </CardContent>
          </Card>
        </Grid>
        {/* Sentiment & Consensus */}
        <Grid item xs={12} md={4}>
          <Card className="bg-gray-900 text-white dark:bg-gray-800">
            <CardContent>
              <Typography variant="h6" gutterBottom><FaHeartbeat className="inline mr-2" />Social Sentiment & Consensus</Typography>
              <Typography variant="body2">Score: <b>{sentiment.score ?? 'N/A'}</b></Typography>
              <Typography variant="body2">Volume: <b>{sentiment.volume ?? 'N/A'}</b></Typography>
              <Typography variant="body2">Trending: <b>{sentiment.trending ? 'Yes' : 'No'}</b></Typography>
              <Typography variant="body2">Keywords: {sentiment.keywords?.length ? sentiment.keywords.join(', ') : 'N/A'}</Typography>
              <Box className="mt-2">
                <Typography variant="body2">Consensus: Over <b>{consensus.overPercentage ?? 'N/A'}%</b> / Under <b>{consensus.underPercentage ?? 'N/A'}%</b></Typography>
              </Box>
              {/* Odds */}
              <Box className="mt-2">
                <Typography variant="body2">Odds:</Typography>
                <Typography variant="caption">Moneyline: {odds.moneyline ?? 'N/A'} | Spread: {odds.spread ?? 'N/A'} | Total: {odds.total ?? 'N/A'}</Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        {/* Pattern Recognition & Injuries */}
        <Grid item xs={12} md={4}>
          <Card className="bg-gray-900 text-white dark:bg-gray-800">
            <CardContent>
              <Typography variant="h6" gutterBottom><FaArrowUp className="inline mr-2" />Pattern Recognition & Injuries</Typography>
              {patterns.length > 0 ? (
                <Box>
                  {patterns.map((p: any, idx: number) => (
                    <StatusChip key={idx} label={p.label} color={p.positive ? 'success' : 'default'} icon={p.positive ? <FaArrowUp /> : <FaArrowDown />} />
                  ))}
                </Box>
              ) : (
                <Typography variant="body2">No significant patterns detected.</Typography>
              )}
              <Box className="mt-2">
                <Typography variant="body2">Injuries:</Typography>
                {injuries.length > 0 ? injuries.map((inj: any, idx: number) => (
                  <Typography key={idx} variant="caption">{inj.player}: {inj.status} (Impact: {inj.impact})</Typography>
                )) : <Typography variant="caption">No major injuries reported.</Typography>}
              </Box>
            </CardContent>
          </Card>
        </Grid>
        {/* Explainability (SHAP/Feature Importances) */}
        <Grid item xs={12} md={6}>
          <Card className="bg-gray-900 text-white dark:bg-gray-800 mt-4">
            <CardContent>
              <Typography variant="h6" gutterBottom>Model Explainability</Typography>
              {explainability.featureImportances ? (
                <Bar
                  data={{
                    labels: Object.keys(explainability.featureImportances),
                    datasets: [{
                      label: 'Feature Importance',
                      data: Object.values(explainability.featureImportances),
                      backgroundColor: primaryColor,
                    }],
                  }}
                  options={{
                    plugins: { legend: { display: false } },
                    responsive: true,
                    scales: { x: { ticks: { color: textColor } }, y: { ticks: { color: textColor } } },
                  }}
                />
              ) : <Typography variant="body2">No explainability data available.</Typography>}
            </CardContent>
          </Card>
        </Grid>
        {/* Risk & Confidence */}
        <Grid item xs={12} md={6}>
          <Card className="bg-gray-900 text-white dark:bg-gray-800 mt-4">
            <CardContent>
              <Typography variant="h6" gutterBottom>Risk & Confidence</Typography>
              <Box className="flex flex-row flex-wrap gap-2 items-center">
                <StatusChip label={`Risk: ${enhancedAnalysis.riskLevel ?? 'N/A'}`} color="warning" icon={<FaExclamationTriangle />} />
                <StatusChip label={`Confidence: ${enhancedAnalysis.confidence ? `${(enhancedAnalysis.confidence * 100).toFixed(1)}%` : 'N/A'}`} color="primary" icon={<FaBolt />} />
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export { AdvancedAnalytics };

import React from 'react';
import { useUnifiedAnalytics } from '@/hooks/useUnifiedAnalytics';

const safeNumber = (n: unknown) => (typeof n === 'number' && !isNaN(n) ? n : 0);

const exportToJson = (data: any) => {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'evolutionary-insights.json';
  a.click();
  URL.revokeObjectURL(url);
};

interface EvolutionaryInsightsProps {
  autoUpdateInterval?: number;
  showGameTheory?: boolean;
  showEvolutionaryMetrics?: boolean;
  showReinforcement?: boolean;
  showOptimization?: boolean;
  showRecommendation?: boolean;
}

const EvolutionaryInsights: React.FC<EvolutionaryInsightsProps> = ({
  autoUpdateInterval = 60000,
  showGameTheory = true,
  showEvolutionaryMetrics = true,
  showReinforcement = true,
  showOptimization = true,
  showRecommendation = true,
}) => {
  const { ml, betting } = useUnifiedAnalytics({
    ml: { autoUpdate: true, updateInterval: autoUpdateInterval },
    betting: true,
  });

  if (ml.loading || betting.loading) {
    return (
      <div aria-live="polite" className="flex items-center justify-center h-96" role="status">
        <div
          aria-label="Loading"
          className="animate-spin rounded-full h-32 w-32 border-t-2 border-b-2 border-blue-500"
        />
      </div>
    );
  }

  if (ml.error || betting.error) {
    return (
      <div className="p-4 bg-red-100 border border-red-400 text-red-700 rounded" role="alert">
        <h3 className="font-bold">Error</h3>
        <p>{ml.error || betting.error}</p>
        <button
          className="mt-2 px-4 py-2 bg-red-500 text-white rounded hover:bg-red-600"
          onClick={() => {
            ml.refetch();
            betting.refetch();
          }}
        >
          Retry
        </button>
      </div>
    );
  }

  const mlResult = ml.data;
  const bettingResult = betting.data;
  if (!mlResult) {
    return (
      <div className="p-4 text-gray-500" role="status">
        No Evolutionary analytics available.
      </div>
    );
  }

  return (
    <div className="space-y-8" data-testid="evolutionaryinsights-root">
      {/* Game Theory Analysis (proxy: ML metrics) */}
      {showGameTheory && (
        <section
          aria-labelledby="evolutionary-game-heading"
          className="bg-white rounded-lg shadow p-6"
        >
          <h2 className="text-2xl font-bold mb-4" id="evolutionary-game-heading">
            Game Theory Analysis
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <h3 className="text-lg font-semibold mb-2">Accuracy</h3>
              <div className="font-mono text-2xl">
                {safeNumber(mlResult.metrics?.accuracy).toFixed(4)}
              </div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">Precision</h3>
              <div className="font-mono text-2xl">
                {safeNumber(mlResult.metrics?.precision).toFixed(4)}
              </div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">Recall</h3>
              <div className="font-mono text-2xl">
                {safeNumber(mlResult.metrics?.recall).toFixed(4)}
              </div>
            </div>
          </div>
        </section>
      )}
      {/* Evolutionary Metrics (proxy: betting win rate, profit/loss) */}
      {showEvolutionaryMetrics && (
        <section
          aria-labelledby="evolutionary-metrics-heading"
          className="bg-white rounded-lg shadow p-6"
        >
          <h2 className="text-2xl font-bold mb-4" id="evolutionary-metrics-heading">
            Evolutionary Metrics
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <h3 className="text-lg font-semibold mb-2">Win Rate</h3>
              <div className="font-mono text-2xl">
                {safeNumber(bettingResult?.winRate).toFixed(2)}%
              </div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">Profit/Loss</h3>
              <div className="font-mono text-2xl">
                ${safeNumber(bettingResult?.profitLoss).toFixed(2)}
              </div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">ROI</h3>
              <div className="font-mono text-2xl">{safeNumber(bettingResult?.roi).toFixed(2)}%</div>
            </div>
          </div>
        </section>
      )}
      {/* Reinforcement Metrics (proxy: risk metrics) */}
      {showReinforcement && (
        <section
          aria-labelledby="evolutionary-reinforcement-heading"
          className="bg-white rounded-lg shadow p-6"
        >
          <h2 className="text-2xl font-bold mb-4" id="evolutionary-reinforcement-heading">
            Reinforcement Metrics
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <h3 className="text-lg font-semibold mb-2">VaR</h3>
              <div className="font-mono text-2xl">
                ${safeNumber(bettingResult?.riskMetrics?.var).toFixed(2)}
              </div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">Sharpe Ratio</h3>
              <div className="font-mono text-2xl">
                {safeNumber(bettingResult?.riskMetrics?.sharpe).toFixed(2)}
              </div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">Sortino Ratio</h3>
              <div className="font-mono text-2xl">
                {safeNumber(bettingResult?.riskMetrics?.sortino).toFixed(2)}
              </div>
            </div>
          </div>
        </section>
      )}
      {/* Optimization (proxy: risk metrics) */}
      {showOptimization && (
        <section
          aria-labelledby="evolutionary-optimization-heading"
          className="bg-white rounded-lg shadow p-6"
        >
          <h2 className="text-2xl font-bold mb-4" id="evolutionary-optimization-heading">
            Optimization
          </h2>
          <div className="text-gray-500">
            (Unified analytics: optimization strategies are surfaced in advanced risk and betting
            modules.)
          </div>
        </section>
      )}
      {/* Final Recommendation */}
      {showRecommendation && (
        <section
          aria-labelledby="evolutionary-recommendation-heading"
          className="bg-white rounded-lg shadow p-6"
        >
          <h2 className="text-2xl font-bold mb-4" id="evolutionary-recommendation-heading">
            AI Recommendation
          </h2>
          <div className="flex items-center gap-4">
            <span className="font-bold text-lg">
              {safeNumber(bettingResult?.confidence) > 0.7 ? 'Place Bet' : 'Hold'}
            </span>
            <span className="px-4 py-2 rounded-full text-sm font-semibold bg-blue-100 text-blue-800">
              {(safeNumber(bettingResult?.confidence) * 100).toFixed(1)}% Confidence
            </span>
          </div>
          <div className="flex justify-end mt-4 gap-2">
            <button
              className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
              onClick={() => {
                ml.refetch();
                betting.refetch();
              }}
            >
              Refresh Analysis
            </button>
            <button
              className="px-4 py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300"
              onClick={() => exportToJson({ mlResult, bettingResult })}
            >
              Export JSON
            </button>
          </div>
        </section>
      )}
    </div>
  );
};

export default React.memo(EvolutionaryInsights);

import React from 'react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  RadarChart,
  Radar,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
} from 'recharts';
import ShapVisualization from '../ShapVisualization';
import { useShapData } from '../../hooks/useShapData';

interface FeatureInsightsProps {
  features: {
    name: string;
    importance: number;
    correlation: number;
    entropy: number;
    uniqueness: number;
    missing: number;
    stats: {
      mean: number;
      std: number;
      min: number;
      max: number;
      q25: number;
      q50: number;
      q75: number;
    };
  }[];
  interactions: {
    feature1: string;
    feature2: string;
    strength: number;
    type: 'linear' | 'nonlinear' | 'categorical';
  }[];
  embeddings: {
    feature: string;
    vector: number[];
  }[];
  signals: {
    source: string;
    features: {
      name: string;
      value: number;
      impact: number;
    }[];
  }[];
  eventId?: string; // Optional, for SHAP
  modelType?: string;
}

const FeatureInsights: React.FC<FeatureInsightsProps> = ({
  features,
  interactions,
  embeddings,
  signals,
  eventId,
  modelType,
}) => {
  // Sort features by importance
  const sortedFeatures = [...features].sort((a, b) => b.importance - a.importance);

  // Prepare data for visualizations
  const featureMetrics = sortedFeatures.map(feature => ({
    name: feature.name,
    importance: feature.importance,
    correlation: Math.abs(feature.correlation),
    entropy: feature.entropy,
    uniqueness: feature.uniqueness,
    missing: feature.missing,
  }));

  const featureStats = sortedFeatures.map(feature => ({
    name: feature.name,
    ...feature.stats,
  }));

  const interactionData = interactions.map(interaction => ({
    name: `${interaction.feature1} × ${interaction.feature2}`,
    strength: interaction.strength,
    type: interaction.type,
  }));

  // SHAP integration
  const {
    features: shapFeatures,
    loading: shapLoading,
    error: shapError,
  } = eventId ? useShapData({ eventId, modelType }) : { features: [], loading: false, error: null };

  return (
    <div className="space-y-8">
      {/* SHAP Feature Importance Section */}
      {eventId && (
        <section className="bg-white rounded-lg shadow p-6">
          <h2 className="text-2xl font-bold mb-4">Model Feature Importance (SHAP)</h2>
          {shapLoading ? (
            <div className="text-gray-500">Loading SHAP values...</div>
          ) : shapError ? (
            <div className="text-red-500">{shapError}</div>
          ) : shapFeatures.length > 0 ? (
            <ShapVisualization
              features={shapFeatures.map(f => ({
                name: f.feature,
                value: f.value,
                impact: f.impact,
              }))}
              maxFeatures={10}
              title="SHAP Feature Impact"
            />
          ) : (
            <div className="text-gray-400">No SHAP data available for this event/model.</div>
          )}
        </section>
      )}

      {/* Feature Importance Section */}
      <section className="bg-white rounded-lg shadow p-6">
        <h2 className="text-2xl font-bold mb-4">Feature Importance</h2>
        <div className="h-96">
          <ResponsiveContainer height="100%" width="100%">
            <BarChart data={featureMetrics}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis angle={-45} dataKey="name" height={100} textAnchor="end" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="importance" fill="#3B82F6" name="Importance Score" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* Feature Metrics Section */}
      <section className="bg-white rounded-lg shadow p-6">
        <h2 className="text-2xl font-bold mb-4">Feature Metrics</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <h3 className="text-lg font-semibold mb-2">Correlation Analysis</h3>
            <ResponsiveContainer height={300} width="100%">
              <RadarChart data={featureMetrics}>
                <PolarGrid />
                <PolarAngleAxis dataKey="name" />
                <PolarRadiusAxis />
                <Radar
                  dataKey="correlation"
                  fill="#93C5FD"
                  fillOpacity={0.6}
                  name="Correlation"
                  stroke="#3B82F6"
                />
              </RadarChart>
            </ResponsiveContainer>
          </div>
          <div>
            <h3 className="text-lg font-semibold mb-2">Feature Quality</h3>
            <ResponsiveContainer height={300} width="100%">
              <BarChart data={featureMetrics}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="entropy" fill="#10B981" name="Entropy" />
                <Bar dataKey="uniqueness" fill="#6366F1" name="Uniqueness" />
                <Bar dataKey="missing" fill="#EF4444" name="Missing Values" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </section>

      {/* Feature Statistics Section */}
      <section className="bg-white rounded-lg shadow p-6">
        <h2 className="text-2xl font-bold mb-4">Feature Statistics</h2>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Feature
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Mean
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Std Dev
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Min
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Q25
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Median
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Q75
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Max
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {featureStats.map(stat => (
                <tr key={stat.name}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                    {stat.name}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {stat.mean.toFixed(4)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {stat.std.toFixed(4)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {stat.min.toFixed(4)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {stat.q25.toFixed(4)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {stat.q50.toFixed(4)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {stat.q75.toFixed(4)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {stat.max.toFixed(4)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Feature Interactions Section */}
      <section className="bg-white rounded-lg shadow p-6">
        <h2 className="text-2xl font-bold mb-4">Feature Interactions</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <h3 className="text-lg font-semibold mb-2">Interaction Strength</h3>
            <ResponsiveContainer height={300} width="100%">
              <BarChart data={interactionData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis angle={-45} dataKey="name" height={100} textAnchor="end" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="strength" fill="#3B82F6" name="Interaction Strength" />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div>
            <h3 className="text-lg font-semibold mb-2">Interaction Types</h3>
            <div className="space-y-2">
              {interactionData.map((interaction, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-2 bg-gray-50 rounded"
                >
                  <span className="text-gray-600">{interaction.name}</span>
                  <span
                    className={`px-2 py-1 rounded text-white ${
                      interaction.type === 'linear'
                        ? 'bg-blue-500'
                        : interaction.type === 'nonlinear'
                          ? 'bg-purple-500'
                          : 'bg-green-500'
                    }`}
                  >
                    {interaction.type}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* External Signals Section */}
      <section className="bg-white rounded-lg shadow p-6">
        <h2 className="text-2xl font-bold mb-4">External Signals</h2>
        <div className="space-y-6">
          {signals.map((signal, index) => (
            <div key={index}>
              <h3 className="text-lg font-semibold mb-2">{signal.source} Features</h3>
              <ResponsiveContainer height={200} width="100%">
                <BarChart data={signal.features}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Legend />
