import React, { useEffect, useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Alert,
  AlertTitle,
  IconButton,
  Chip,
  Stack,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
} from '@mui/material';
import { Close as CloseIcon } from '@mui/icons-material';
import { PerformanceMonitor } from '../../core/analytics/PerformanceMonitor';
import { useLogger } from '../../hooks/useLogger';
import { useMetrics } from '../../hooks/useMetrics';

interface PerformanceAlertsProps {
  modelName?: string;
  onAlertClick?: (alert: any) => void;
}

export const PerformanceAlerts: React.FC<PerformanceAlertsProps> = ({
  modelName,
  onAlertClick,
}) => {
  const [alerts, setAlerts] = useState<any[]>([]);
  const [severity, setSeverity] = useState<'warning' | 'critical' | 'all'>('all');
  const [timeframe, setTimeframe] = useState<'day' | 'week' | 'month' | 'all'>('day');
  const logger = useLogger();
  const metrics = useMetrics();

  useEffect(() => {
    const fetchAlerts = () => {
      const monitor = PerformanceMonitor.getInstance(logger, metrics);
      const startTime = getStartTime(timeframe);
      const filteredAlerts = monitor.getAlerts(
        modelName,
        severity === 'all' ? undefined : severity,
        startTime
      );
      setAlerts(filteredAlerts);
    };

    fetchAlerts();
    const interval = setInterval(fetchAlerts, 30000); // Refresh every 30 seconds

    return () => clearInterval(interval);
  }, [modelName, severity, timeframe, logger, metrics]);

  const getStartTime = (timeframe: string): Date | undefined => {
    if (timeframe === 'all') return undefined;

    const now = new Date();
    switch (timeframe) {
      case 'day':
        return new Date(now.setDate(now.getDate() - 1));
      case 'week':
        return new Date(now.setDate(now.getDate() - 7));
      case 'month':
        return new Date(now.setMonth(now.getMonth() - 1));
      default:
        return undefined;
    }
  };

  const handleClearAlerts = () => {
    const monitor = PerformanceMonitor.getInstance(logger, metrics);
    monitor.clearAlerts(modelName);
    setAlerts([]);
  };

  const formatMetricValue = (metric: string, value: number): string => {
    if (metric === 'roi' || metric === 'winRate' || metric === 'maxDrawdown') {
      return `${(value * 100).toFixed(1)}%`;
    }
    return value.toFixed(2);
  };

  return (
    <Card>
      <CardContent>
        <Box alignItems="center" display="flex" justifyContent="space-between" mb={2}>
          <Typography variant="h6">Performance Alerts</Typography>
          <Stack direction="row" spacing={2}>
            <FormControl size="small" sx={{ minWidth: 120 }}>
              <InputLabel>Severity</InputLabel>
              <Select
                label="Severity"
                value={severity}
                onChange={e => setSeverity(e.target.value as any)}
              >
                <MenuItem value="all">All</MenuItem>
                <MenuItem value="warning">Warning</MenuItem>
                <MenuItem value="critical">Critical</MenuItem>
              </Select>
            </FormControl>
            <FormControl size="small" sx={{ minWidth: 120 }}>
              <InputLabel>Timeframe</InputLabel>
              <Select
                label="Timeframe"
                value={timeframe}
                onChange={e => setTimeframe(e.target.value as any)}
              >
                <MenuItem value="day">Last 24 Hours</MenuItem>
                <MenuItem value="week">Last Week</MenuItem>
                <MenuItem value="month">Last Month</MenuItem>
                <MenuItem value="all">All Time</MenuItem>
              </Select>
            </FormControl>
            <IconButton size="small" onClick={handleClearAlerts}>
              <CloseIcon />
            </IconButton>
          </Stack>
        </Box>

        <Stack spacing={2}>
          {alerts.length === 0 ? (
            <Alert severity="info">No alerts in the selected timeframe.</Alert>
          ) : (
            alerts.map((alert, index) => (
              <Alert
                key={index}
                severity={alert.severity}
                sx={{ cursor: onAlertClick ? 'pointer' : 'default' }}
                onClick={() => onAlertClick?.(alert)}
              >
                <AlertTitle>
                  {alert.modelName} - {alert.metric}
                </AlertTitle>
                <Box alignItems="center" display="flex" gap={1}>
                  <Typography>
                    Current value: {formatMetricValue(alert.metric, alert.value)}
                  </Typography>
                  <Chip
                    color={alert.severity === 'critical' ? 'error' : 'warning'}
                    label={`Threshold: ${formatMetricValue(alert.metric, alert.threshold)}`}
                    size="small"
                  />
                  <Typography color="text.secondary" variant="caption">
                    {new Date(alert.timestamp).toLocaleString()}
                  </Typography>
                </Box>
              </Alert>
            ))
          )}
        </Stack>
      </CardContent>
    </Card>
  );
};

import React, { useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  Stack,
  Typography,
} from '@mui/material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { useModelPerformance } from '../../hooks/useModelPerformance';

interface PerformanceExportProps {
  modelName: string;
  onClose: () => void;
}

type ExportFormat = 'csv' | 'json' | 'excel';

export const PerformanceExport: React.FC<PerformanceExportProps> = ({ modelName, onClose }) => {
  const [format, setFormat] = useState<ExportFormat>('csv');
  const [startDate, setStartDate] = useState<Date | null>(null);
  const [endDate, setEndDate] = useState<Date | null>(null);
  const { history } = useModelPerformance(modelName);

  const handleExport = () => {
    const filteredData = history.filter(entry => {
      const timestamp = new Date(entry.timestamp);
      return (!startDate || timestamp >= startDate) && (!endDate || timestamp <= endDate);
    });

    const data = filteredData.map(entry => ({
      timestamp: new Date(entry.timestamp).toISOString(),
      ...entry.metrics,
    }));

    switch (format) {
      case 'csv':
        exportCSV(data);
        break;
      case 'json':
        exportJSON(data);
        break;
      case 'excel':
        exportExcel(data);
        break;
    }
  };

  const exportCSV = (data: any[]) => {
    const headers = Object.keys(data[0]);
    const csvContent = [
      headers.join(','),
      ...data.map(row => headers.map(header => row[header]).join(',')),
    ].join('\n');

    downloadFile(csvContent, 'performance_data.csv', 'text/csv');
  };

  const exportJSON = (data: any[]) => {
    const jsonContent = JSON.stringify(data, null, 2);
    downloadFile(jsonContent, 'performance_data.json', 'application/json');
  };

  const exportExcel = (data: any[]) => {
    // For Excel export, we'll use CSV format with .xlsx extension
    // In a real implementation, you would use a library like xlsx
    const headers = Object.keys(data[0]);
    const csvContent = [
      headers.join(','),
      ...data.map(row => headers.map(header => row[header]).join(',')),
    ].join('\n');

    downloadFile(
      csvContent,
      'performance_data.xlsx',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    );
  };

  const downloadFile = (content: string, filename: string, mimeType: string) => {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <Dialog fullWidth open maxWidth="sm" onClose={onClose}>
      <DialogTitle>Export Performance Data</DialogTitle>
      <DialogContent>
        <Stack spacing={3} sx={{ mt: 2 }}>
          <FormControl fullWidth>
            <InputLabel>Format</InputLabel>
            <Select
              label="Format"
              value={format}
              onChange={e => setFormat(e.target.value as ExportFormat)}
            >
              <MenuItem value="csv">CSV</MenuItem>
              <MenuItem value="json">JSON</MenuItem>
              <MenuItem value="excel">Excel</MenuItem>
            </Select>
          </FormControl>

          <Box>
            <Typography gutterBottom variant="subtitle2">
              Date Range
            </Typography>
            <Stack direction="row" spacing={2}>
              <DatePicker
                label="Start Date"
                slotProps={{ textField: { fullWidth: true } }}
                value={startDate}
                onChange={(date: Date | null) => setStartDate(date)}
              />
              <DatePicker
                label="End Date"
                slotProps={{ textField: { fullWidth: true } }}
                value={endDate}
                onChange={(date: Date | null) => setEndDate(date)}
              />
            </Stack>
          </Box>

          <Typography color="text.secondary" variant="body2">
            {history.length} data points available
          </Typography>
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button color="primary" variant="contained" onClick={handleExport}>
          Export
        </Button>
      </DialogActions>
    </Dialog>
  );
};

