export default React.memo(RegisterForm);

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { UnifiedServiceRegistry } from '../../services/unified/UnifiedServiceRegistry';
import { UnifiedStateService } from '../../services/unified/UnifiedStateService';
import { UnifiedNotificationService } from '../../services/unified/UnifiedNotificationService';
import { UnifiedErrorService } from '../../services/unified/UnifiedErrorService';
import { UnifiedSettingsService } from '../../services/unified/UnifiedSettingsService';
import { Card, Button, Input, Spinner, Toast, Modal } from '../ui/UnifiedUI';

interface AuthForm {
  email: string;
  password: string;
  confirmPassword?: string;
  rememberMe?: boolean;
}

interface ValidationError {
  field: string;
  message: string;
}

export const UnifiedAuth: React.FC = () => {
  // Initialize services
  const serviceRegistry = UnifiedServiceRegistry.getInstance();
  const stateService = serviceRegistry.getService<UnifiedStateService>('state');
  const notificationService =
    serviceRegistry.getService<UnifiedNotificationService>('notification');
  const errorService = serviceRegistry.getService<UnifiedErrorService>('error');
  const settingsService = serviceRegistry.getService<UnifiedSettingsService>('settings');

  // Router hooks
  const navigate = useNavigate();
  const location = useLocation();

  // State
  const [isLogin, setIsLogin] = useState(true);
  const [form, setForm] = useState<AuthForm>({
    email: '',
    password: '',
    confirmPassword: '',
    rememberMe: false,
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [validationErrors, setValidationErrors] = useState<ValidationError[]>([]);
  const [toast, setToast] = useState<{
    message: string;
    type: 'success' | 'error' | 'warning' | 'info';
  } | null>(null);
  const [showPasswordReset, setShowPasswordReset] = useState(false);
  const [showVerificationModal, setShowVerificationModal] = useState(false);

  // Check for existing session
  useEffect(() => {
    checkSession();
  }, []);

  const checkSession = async () => {
    try {
      const session = await stateService.getState('session');
      if (session?.isValid) {
        navigate('/dashboard');
      }
    } catch (error) {
      handleError('Failed to check session', error);
    }
  };

  const validateForm = (): boolean => {
    const errors: ValidationError[] = [];

    // Email validation
    if (!form.email) {
      errors.push({ field: 'email', message: 'Email is required' });
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) {
      errors.push({ field: 'email', message: 'Invalid email format' });
    }

    // Password validation
    if (!form.password) {
      errors.push({ field: 'password', message: 'Password is required' });
    } else if (form.password.length < 8) {
      errors.push({ field: 'password', message: 'Password must be at least 8 characters' });
    }

    // Confirm password validation for registration
    if (!isLogin && form.password !== form.confirmPassword) {
      errors.push({ field: 'confirmPassword', message: 'Passwords do not match' });
    }

    setValidationErrors(errors);
    return errors.length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    try {
      setLoading(true);
      setError(null);

      if (isLogin) {
        await handleLogin();
      } else {
        await handleRegister();
      }
    } catch (error) {
      handleError('Authentication failed', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async () => {
    const response = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: form.email,
        password: form.password,
        rememberMe: form.rememberMe,
      }),
    });

    if (!response.ok) {
      throw new Error('Login failed');
    }

    const data = await response.json();
    await stateService.setState('session', {
      token: data.token,
      user: data.user,
      isValid: true,
      expiresAt: data.expiresAt,
    });

    setToast({
      message: 'Login successful',
      type: 'success',
    });

    navigate('/dashboard');
  };

  const handleRegister = async () => {
    const response = await fetch('/api/auth/register', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: form.email,
        password: form.password,
      }),
    });

    if (!response.ok) {
      throw new Error('Registration failed');
    }

    setShowVerificationModal(true);
    setToast({
      message: 'Registration successful. Please verify your email.',
      type: 'success',
    });
  };

  const handlePasswordReset = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: form.email }),
      });

      if (!response.ok) {
        throw new Error('Password reset request failed');
      }

      setShowPasswordReset(false);
      setToast({
        message: 'Password reset instructions sent to your email',
        type: 'success',
      });
    } catch (error) {
      handleError('Failed to request password reset', error);
    } finally {
      setLoading(false);
    }
  };

  const handleError = (message: string, error: any) => {
    setError(message);
    setToast({ message, type: 'error' });
    errorService.handleError(error, {
      code: 'AUTH_ERROR',
      source: 'UnifiedAuth',
      details: { message },
    });
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900 py-12 px-4 sm:px-6 lg:px-8">
      <Card className="max-w-md w-full space-y-8">
        <div className="text-center">
          <h2 className="text-3xl font-bold">
            {isLogin ? 'Sign in to your account' : 'Create a new account'}
          </h2>
          <p className="mt-2 text-gray-600 dark:text-gray-400">
            {isLogin
              ? 'Welcome back! Please enter your details.'
              : 'Join us today and start betting smarter.'}
          </p>
        </div>

        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                htmlFor="email"
              >
                Email address
              </label>
              <Input
                required
                error={validationErrors.find(e => e.field === 'email')?.message}
                id="email"
                type="email"
                value={form.email}
                onChange={e => setForm({ ...form, email: e.target.value })}
              />
            </div>

            <div>
              <label
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                htmlFor="password"
              >
                Password
              </label>
              <Input
                required
                error={validationErrors.find(e => e.field === 'password')?.message}
                id="password"
                type="password"
                value={form.password}
                onChange={e => setForm({ ...form, password: e.target.value })}
              />
            </div>

            {!isLogin && (
              <div>
                <label
                  className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                  htmlFor="confirmPassword"
                >
                  Confirm Password
                </label>
                <Input
                  required
                  error={validationErrors.find(e => e.field === 'confirmPassword')?.message}
                  id="confirmPassword"
                  type="password"
                  value={form.confirmPassword}
                  onChange={e => setForm({ ...form, confirmPassword: e.target.value })}
                />
              </div>
            )}

            {isLogin && (
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <input
                    checked={form.rememberMe}
                    className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                    id="remember-me"
                    type="checkbox"
                    onChange={e => setForm({ ...form, rememberMe: e.target.checked })}
                  />
                  <label
                    className="ml-2 block text-sm text-gray-700 dark:text-gray-300"
                    htmlFor="remember-me"
                  >
                    Remember me
                  </label>
                </div>
                <button
                  className="text-sm font-medium text-primary-600 hover:text-primary-500"
                  type="button"
                  onClick={() => setShowPasswordReset(true)}
                >
                  Forgot password?
                </button>
              </div>
            )}
          </div>

          <div>
            <Button className="w-full" disabled={loading} type="submit" variant="primary">
              {loading ? <Spinner size="small" /> : isLogin ? 'Sign in' : 'Create account'}
            </Button>
          </div>

          <div className="text-center">
            <button
              className="text-sm font-medium text-primary-600 hover:text-primary-500"
              type="button"
              onClick={() => setIsLogin(!isLogin)}
            >
              {isLogin ? "Don't have an account? Sign up" : 'Already have an account? Sign in'}
            </button>
          </div>
        </form>
      </Card>

      {/* Password Reset Modal */}
      <Modal
        isOpen={showPasswordReset}
        title="Reset Password"
        onClose={() => setShowPasswordReset(false)}
      >
        <div className="space-y-4">
          <p className="text-gray-600">
            Enter your email address and we'll send you instructions to reset your password.
          </p>
          <Input
            placeholder="Enter your email"
            type="email"
            value={form.email}
            onChange={e => setForm({ ...form, email: e.target.value })}
          />
          <div className="flex justify-end space-x-4">
            <Button variant="secondary" onClick={() => setShowPasswordReset(false)}>
              Cancel
            </Button>
            <Button disabled={loading} variant="primary" onClick={handlePasswordReset}>
              {loading ? <Spinner size="small" /> : 'Send Instructions'}
            </Button>
          </div>
        </div>
      </Modal>

      {/* Email Verification Modal */}
      <Modal
        isOpen={showVerificationModal}
        title="Verify Your Email"
        onClose={() => setShowVerificationModal(false)}
      >
        <div className="text-center">
          <p className="text-gray-600 mb-6">
            We've sent a verification link to your email address. Please check your inbox and click
            the link to verify your account.
          </p>
          <Button
            variant="primary"
            onClick={() => {
              setShowVerificationModal(false);
              setIsLogin(true);
            }}
          >
            Return to Login
          </Button>
        </div>
      </Modal>

      {/* Toast Notifications */}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

import React from 'react';
import { cn } from '../../utils/classNames';
import { motion, MotionProps } from 'framer-motion';

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'success' | 'danger' | 'warning';
  size?: 'sm' | 'md' | 'lg';
  loading?: boolean;
  icon?: React.ReactNode;
  fullWidth?: boolean;
}

const variants = {
  primary: 'bg-primary-500 hover:bg-primary-600 text-white',
  secondary: 'bg-gray-500 hover:bg-gray-600 text-white',
  success: 'bg-green-500 hover:bg-green-600 text-white',
  danger: 'bg-red-500 hover:bg-red-600 text-white',
  warning: 'bg-yellow-500 hover:bg-yellow-600 text-white',
};

const sizes = {
  sm: 'px-3 py-1.5 text-sm',
  md: 'px-4 py-2 text-base',
  lg: 'px-6 py-3 text-lg',
};

function splitMotionProps(props: any) {
  const motionKeys = [
    'animate',
    'initial',
    'exit',
    'whileHover',
    'whileTap',
    'whileFocus',
    'whileDrag',
    'drag',
    'dragConstraints',
    'dragElastic',
    'dragMomentum',
    'dragPropagation',
    'onAnimationStart',
    'onAnimationComplete',
    'onUpdate',
    'onDrag',
    'onDragEnd',
    'onDragStart',
    'onDragTransitionEnd',
    'layout',
    'layoutId',
    'transition',
    'variants',
    'custom',
    'style',
    'transformTemplate',
    'transformValues',
  ];
  const motionProps: any = {};
  const rest: any = {};
  Object.entries(props).forEach(([key, value]) => {
    if (motionKeys.includes(key)) {
      motionProps[key] = value;
    } else {
      rest[key] = value;
    }
  });
  return [motionProps, rest];
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps & MotionProps>(
  (allProps, ref) => {
    const {
      variant = 'primary',
      size = 'md',
      loading = false,
      icon,
      fullWidth = false,
      className,
      children,
      disabled,
      ...props
    } = allProps;
    const baseClasses =
      'rounded-lg font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed';
    const variantClasses = variants[variant];
    const sizeClasses = sizes[size];
    const widthClasses = fullWidth ? 'w-full' : '';
    const [motionProps, buttonProps] = splitMotionProps(props);
    return (
      <motion.button
        ref={ref}
        className={cn(baseClasses, variantClasses, sizeClasses, widthClasses, className)}
        disabled={disabled || loading}
        {...motionProps}
        {...buttonProps}
      >
        <div className="flex items-center justify-center gap-2">
          {loading ? (
            <svg
              className="animate-spin h-5 w-5"
              fill="none"
              viewBox="0 0 24 24"
              xmlns="http://www.w3.org/2000/svg"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              />
              <path
                className="opacity-75"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                fill="currentColor"
              />
            </svg>
          ) : icon ? (
            <span className="w-5 h-5">{icon}</span>
          ) : null}
          {children}
        </div>
      </motion.button>
    );
  }
);

import React from 'react';
import { cn } from '../../utils/classNames';
