const glowColors = {
  default: 'shadow-gray-500/20',
  glass: 'shadow-white/20',
  premium: 'shadow-primary-500/20',
};

function splitMotionProps(props: any) {
  const motionKeys = [
    'animate',
    'initial',
    'exit',
    'whileHover',
    'whileTap',
    'whileFocus',
    'whileDrag',
    'drag',
    'dragConstraints',
    'dragElastic',
