    'onUpdate',
    'onDrag',
    'onDragEnd',
    'onDragStart',
    'onDragTransitionEnd',
    'layout',
    'layoutId',
    'transition',
    'variants',
    'custom',
    'style',
    'transformTemplate',
    'transformValues',
  ];
  const motionProps: any = {};
  const rest: any = {};
  Object.entries(props).forEach(([key, value]) => {
