import React, { Fragment } from 'react';
import { Menu, Transition } from '@headlessui/react';
import { cn } from '../../utils/classNames';

export interface DropdownItem {
  key: string;
  label: string;
  icon?: React.ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  danger?: boolean;
  divider?: boolean;
}

export interface DropdownProps {
  trigger: React.ReactNode;
  items: DropdownItem[];
  position?: 'left' | 'right';
  width?: string;
  className?: string;
}

export const Dropdown: React.FC<DropdownProps> = ({
  trigger,
  items,
  position = 'right',
  width = '200px',
  className,
}) => {
  return (
    <Menu as="div" className="relative inline-block text-left">
      <Menu.Button as={Fragment}>{trigger}</Menu.Button>
      <Transition
        as={Fragment}
        enter="transition ease-out duration-100"
        enterFrom="transform opacity-0 scale-95"
        enterTo="transform opacity-100 scale-100"
        leave="transition ease-in duration-75"
        leaveFrom="transform opacity-100 scale-100"
        leaveTo="transform opacity-0 scale-95"
      >
        <Menu.Items
          className={cn(
            'absolute z-50 mt-2 rounded-lg bg-white dark:bg-gray-800 shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none',
            position === 'right' ? 'origin-top-right right-0' : 'origin-top-left left-0',
            className
          )}
          style={{ width }}
        >
          <div className="py-1">
            {items.map((item, index) => (
              <Fragment key={item.key}>
                {item.divider ? (
                  <div className="my-1 border-t border-gray-200 dark:border-gray-700" />
                ) : (
                  <Menu.Item disabled={item.disabled}>
                    {({ active }) => (
                      <button
                        className={cn(
                          'group flex w-full items-center px-4 py-2 text-sm',
                          active
                            ? 'bg-gray-100 dark:bg-gray-700'
                            : 'text-gray-700 dark:text-gray-200',
                          item.danger && 'text-red-600 dark:text-red-500',
                          item.disabled && 'opacity-50 cursor-not-allowed'
                        )}
                        disabled={item.disabled}
                        onClick={item.onClick}
                      >
                        {item.icon && (
                          <span
                            className={cn(
                              'mr-3 h-5 w-5',
                              item.danger
                                ? 'text-red-600 dark:text-red-500'
                                : 'text-gray-400 dark:text-gray-500 group-hover:text-gray-500 dark:group-hover:text-gray-400'
                            )}
                          >
                            {item.icon}
                          </span>
                        )}
                        {item.label}
                      </button>
                    )}
                  </Menu.Item>
                )}
              </Fragment>
            ))}
          </div>
        </Menu.Items>
      </Transition>
    </Menu>
  );
};

import React from 'react';
import { cn } from '../../utils/classNames';

export interface Column<T> {
  key: keyof T | string;
  title: string;
  render?: (value: any, item: T) => React.ReactNode;
  sortable?: boolean;
  width?: string;
}

export interface TableProps<T> {
  data: T[];
  columns: Column<T>[];
  loading?: boolean;
  onSort?: (key: keyof T | string, direction: 'asc' | 'desc') => void;
  sortKey?: keyof T | string;
  sortDirection?: 'asc' | 'desc';
  className?: string;
  rowClassName?: string | ((item: T) => string);
  onRowClick?: (item: T) => void;
  emptyMessage?: string;
}

export function Table<T>({
  data,
  columns,
  loading = false,
  onSort,
  sortKey,
  sortDirection,
  className,
  rowClassName,
  onRowClick,
  emptyMessage = 'No data available',
}: TableProps<T>) {
  const handleSort = (key: keyof T | string) => {
    if (!onSort || !columns.find(col => col.key === key)?.sortable) return;

    const newDirection = sortKey === key && sortDirection === 'asc' ? 'desc' : 'asc';
    onSort(key, newDirection);
  };

  const renderSortIcon = (key: keyof T | string) => {
    if (!columns.find(col => col.key === key)?.sortable) return null;

    return (
      <span className="ml-2 inline-flex flex-col">
        <svg
          className={cn(
            'w-2 h-2 -mb-0.5',
            sortKey === key && sortDirection === 'asc' ? 'text-primary-500' : 'text-gray-400'
          )}
          fill="currentColor"
          viewBox="0 0 24 24"
        >
          <path d="M12 5l8 8H4z" />
        </svg>
        <svg
          className={cn(
            'w-2 h-2',
            sortKey === key && sortDirection === 'desc' ? 'text-primary-500' : 'text-gray-400'
          )}
          fill="currentColor"
          viewBox="0 0 24 24"
        >
          <path d="M12 19l-8-8h16z" />
        </svg>
      </span>
    );
  };

  if (loading) {
    return (
      <div className="animate-pulse space-y-4">
        <div className="h-10 bg-gray-200 dark:bg-gray-700 rounded" />
        {[...Array(5)].map((_, i) => (
          <div key={i} className="h-16 bg-gray-200 dark:bg-gray-700 rounded" />
        ))}
      </div>
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className={cn('min-w-full divide-y divide-gray-200 dark:divide-gray-700', className)}>
        <thead className="bg-gray-50 dark:bg-gray-800">
          <tr>
            {columns.map(column => (
              <th
                key={column.key.toString()}
                className={cn(
                  'px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider whitespace-nowrap',
                  column.sortable && 'cursor-pointer hover:text-gray-700 dark:hover:text-gray-200'
                )}
                scope="col"
                style={column.width ? { width: column.width } : undefined}
                onClick={() => handleSort(column.key)}
              >
                <span className="flex items-center">
                  {column.title}
                  {renderSortIcon(column.key)}
                </span>
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="bg-white dark:bg-gray-900 divide-y divide-gray-200 dark:divide-gray-800">
          {data.length === 0 ? (
            <tr>
              <td
                className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400 text-center"
                colSpan={columns.length}
              >
                {emptyMessage}
              </td>
            </tr>
          ) : (
            data.map((item, index) => (
              <tr
                key={index}
                className={cn(
                  'transition-colors hover:bg-gray-50 dark:hover:bg-gray-800',
                  typeof rowClassName === 'function' ? rowClassName(item) : rowClassName,
                  onRowClick && 'cursor-pointer'
                )}
                onClick={() => onRowClick?.(item)}
              >
                {columns.map(column => (
                  <td
                    key={column.key.toString()}
                    className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100"
                  >
                    {column.render
                      ? column.render(
                          typeof column.key === 'string'
                            ? (item as any)[column.key]
                            : item[column.key],
                          item
                        )
                      : typeof column.key === 'string'
                        ? (item as any)[column.key]
                        : item[column.key]}
                  </td>
                ))}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

import React, { ChangeEvent, useState, useEffect } from 'react';
import { FaExclamationCircle, FaCheckCircle, FaInfoCircle } from 'react-icons/fa';
import { cn } from '../../utils/classNames';
import { motion, AnimatePresence } from 'framer-motion';

type InputAttributes = Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'>;

export interface UnifiedInputProps extends InputAttributes {
  // Appearance
  variant?: 'default' | 'premium';
  size?: 'sm' | 'md' | 'lg';
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;

  // Labels and Messages
  label?: string;
  error?: string;
  info?: string;

  // Validation
  validation?: {
    required?: boolean;
    pattern?: string;
    min?: number;
    max?: number;
    validateOnBlur?: boolean;
  };

  // Animation
  animate?: boolean;

  // Callbacks
  onValidationChange?: (isValid: boolean) => void;
}

const variants = {
  label: {
    initial: { y: -10, opacity: 0 },
    animate: { y: 0, opacity: 1 },
    exit: { y: 10, opacity: 0 },
  },
  error: {
    initial: { opacity: 0, x: 20 },
    animate: { opacity: 1, x: 0 },
    exit: { opacity: 0, x: -20 },
  },
};

const sizeClasses = {
  sm: 'h-8 text-sm',
  md: 'h-10 text-base',
  lg: 'h-12 text-lg',
};

export const UnifiedInput = React.forwardRef<HTMLInputElement, UnifiedInputProps>(
  (
    {
      // Appearance props
      variant = 'default',
      size = 'md',
      leftIcon,
      rightIcon,
      className,

      // Labels and messages
      label,
      error,
      info,

      // Validation
      validation,

      // Animation
      animate = true,

      // Callbacks
      onValidationChange,
      onChange,
      onBlur,

      // Rest
      ...props
    },
    ref
  ) => {
    const [isFocused, setIsFocused] = useState(false);
    const [isDirty, setIsDirty] = useState(false);
    const [localError, setLocalError] = useState<string | undefined>(error);
    const [isValid, setIsValid] = useState(true);

    useEffect(() => {
      setLocalError(error);
    }, [error]);

    const validate = (value: string) => {
      if (!validation) return true;

      if (validation.required && !value) {
        setLocalError('This field is required');
        setIsValid(false);
        return false;
      }

      if (validation.pattern && value) {
        const regex = new RegExp(validation.pattern);
        if (!regex.test(value)) {
          setLocalError('Invalid format');
          setIsValid(false);
          return false;
        }
      }

      if (props.type === 'number' && value) {
        const num = parseFloat(value);
        if (validation.min !== undefined && num < validation.min) {
          setLocalError(`Value must be at least ${validation.min}`);
          setIsValid(false);
          return false;
        }
        if (validation.max !== undefined && num > validation.max) {
          setLocalError(`Value must be at most ${validation.max}`);
          setIsValid(false);
          return false;
        }
      }

      setLocalError(undefined);
      setIsValid(true);
      return true;
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
      setIsDirty(true);
      if (validation && !validation.validateOnBlur) {
        const isValid = validate(e.target.value);
        onValidationChange?.(isValid);
      }
      onChange?.(e);
    };

    const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      setIsFocused(false);
      if (validation?.validateOnBlur && isDirty) {
        const isValid = validate(e.target.value);
        onValidationChange?.(isValid);
      }
      onBlur?.(e);
    };

    const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
      setIsFocused(true);
      props.onFocus?.(e);
    };

    const baseClasses = cn(
      'w-full rounded-lg border px-4 transition-all duration-200',
      'focus:outline-none focus:ring-2 focus:ring-offset-2',
      sizeClasses[size],
      {
        'border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800': variant === 'default',
        'border-primary-200 dark:border-primary-800 bg-primary-50/50 dark:bg-primary-900/20':
          variant === 'premium',
        'border-red-500 focus:border-red-500 focus:ring-red-500': localError,
        'pl-10': leftIcon,
        'pr-10': rightIcon,
      },
      className
    );

    return (
      <div className="space-y-1">
        <AnimatePresence>
          {label && (
            <motion.label
              className="block text-sm font-medium text-gray-700 dark:text-gray-200"
              {...(animate ? variants.label : {})}
            >
              {label}
            </motion.label>
          )}
        </AnimatePresence>

        <div className="relative">
          {leftIcon && (
            <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-gray-400">
              {leftIcon}
            </div>
          )}

          <input
            ref={ref}
            className={baseClasses}
            onBlur={handleBlur}
            onChange={handleChange}
            onFocus={handleFocus}
            {...props}
          />

          {rightIcon && (
            <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none text-gray-400">
              {rightIcon}
            </div>
          )}
        </div>

        <AnimatePresence>
          {localError && (
            <motion.p
              className="text-sm text-red-600 dark:text-red-500 flex items-center gap-1"
              {...(animate ? variants.error : {})}
            >
              <FaExclamationCircle />
              {localError}
            </motion.p>
          )}
          {!localError && info && (
            <motion.p
              className="text-sm text-gray-500 dark:text-gray-400 flex items-center gap-1"
              {...(animate ? variants.error : {})}
            >
              <FaInfoCircle />
              {info}
            </motion.p>
          )}
        </AnimatePresence>
      </div>
    );
  }
);

UnifiedInput.displayName = 'UnifiedInput';

import React, { useState } from 'react';
import {
  Box,
  Button,
  FormControl,
  FormLabel,
  Input,
  Select,
  VStack,
  Text,
  useToast,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
} from '@chakra-ui/react';
import { useAuth } from '../../hooks/useAuth';
import { useMutation } from '@tanstack/react-query';
import axios from 'axios';

interface BetFormProps {
  eventId: string;
  marketType: string;
  selection: string;
  odds: number;
  metadata: {
    sport: string;
    league: string;
    homeTeam: string;
    awayTeam: string;
    startTime: Date;
  };
}

export const BetForm: React.FC<BetFormProps> = ({
  eventId,
  marketType,
  selection,
  odds,
  metadata,
}) => {
  const [stake, setStake] = useState<number>(0);
  const { user } = useAuth();
  const toast = useToast();

  const placeBetMutation = useMutation({
    mutationFn: async (betData: any) => {
      const response = await axios.post('/api/betting/place', betData);
      return response.data;
    },
    onSuccess: () => {
      toast({
        title: 'Bet placed successfully',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
    },
    onError: error => {
      toast({
        title: 'Error placing bet',
        description: error.message,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) {
      toast({
        title: 'Authentication required',
        description: 'Please log in to place bets',
        status: 'warning',
        duration: 5000,
        isClosable: true,
      });
      return;
    }

    placeBetMutation.mutate({
      eventId,
      marketType,
      selection,
      odds,
      stake,
      metadata,
    });
  };

  const potentialWinnings = stake * odds;

  return (
    <Box as="form" borderRadius="lg" borderWidth={1} p={4} onSubmit={handleSubmit}>
      <VStack align="stretch" spacing={4}>
        <Text fontSize="lg" fontWeight="bold">
          Place Your Bet
        </Text>

        <FormControl>
          <FormLabel>Event</FormLabel>
          <Text>
            {metadata.homeTeam} vs {metadata.awayTeam}
          </Text>
        </FormControl>

        <FormControl>
          <FormLabel>Market</FormLabel>
          <Text>{marketType}</Text>
        </FormControl>

        <FormControl>
          <FormLabel>Selection</FormLabel>
          <Text>{selection}</Text>
        </FormControl>

        <FormControl>
          <FormLabel>Odds</FormLabel>
          <Text>{odds}</Text>
        </FormControl>

        <FormControl isRequired>
          <FormLabel>Stake</FormLabel>
          <NumberInput
            min={0.01}
            step={0.01}
            value={stake}
            onChange={(_, value) => setStake(value)}
          >
            <NumberInputField />
            <NumberInputStepper>
              <NumberIncrementStepper />
              <NumberDecrementStepper />
            </NumberInputStepper>
          </NumberInput>
        </FormControl>

        <FormControl>
          <FormLabel>Potential Winnings</FormLabel>
          <Text>${potentialWinnings.toFixed(2)}</Text>
        </FormControl>

        <Button
          colorScheme="blue"
          isDisabled={!stake || stake < 0.01}
          isLoading={placeBetMutation.isPending}
          type="submit"
        >
          Place Bet
        </Button>
      </VStack>
    </Box>
  );
};

import React from 'react';
import {
  Box,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Text,
  Badge,
  useColorModeValue,
  Spinner,
  Center,
} from '@chakra-ui/react';
import { useQuery } from '@tanstack/react-query';
import axios from 'axios';
import { format } from 'date-fns';

interface Bet {
  _id: string;
  eventId: string;
  marketType: string;
  selection: string;
  odds: number;
  stake: number;
  potentialWinnings: number;
  status: 'pending' | 'won' | 'lost' | 'cancelled';
  placedAt: string;
  settledAt?: string;
  result?: string;
  metadata: {
    sport: string;
    league: string;
    homeTeam: string;
    awayTeam: string;
    startTime: string;
  };
}

interface BetHistoryProps {
  status?: string;
}

export const BetHistory: React.FC<BetHistoryProps> = ({ status }) => {
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  const { data, isLoading, error } = useQuery<{ bets: Bet[]; pagination: any }>({
    queryKey: ['bets', status],
    queryFn: async () => {
      const response = await axios.get('/api/betting/my-bets', {
        params: { status },
      });
      return response.data;
    },
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'won':
        return 'green';
      case 'lost':
        return 'red';
      case 'cancelled':
        return 'gray';
      default:
        return 'yellow';
    }
  };

  if (isLoading) {
    return (
      <Center p={8}>
        <Spinner size="xl" />
      </Center>
    );
  }

  if (error) {
    return (
      <Box p={4}>
        <Text color="red.500">Error loading betting history</Text>
      </Box>
    );
  }

  return (
    <Box bg={bgColor} borderColor={borderColor} borderRadius="lg" borderWidth={1} overflow="hidden">
      <Table variant="simple">
        <Thead>
          <Tr>
            <Th>Event</Th>
            <Th>Market</Th>
            <Th>Selection</Th>
            <Th isNumeric>Odds</Th>
            <Th isNumeric>Stake</Th>
            <Th isNumeric>Potential Winnings</Th>
            <Th>Status</Th>
            <Th>Placed At</Th>
          </Tr>
        </Thead>
        <Tbody>
          {data?.bets.map(bet => (
            <Tr key={bet._id}>
              <Td>
                <Text fontWeight="medium">
                  {bet.metadata.homeTeam} vs {bet.metadata.awayTeam}
                </Text>
                <Text color="gray.500" fontSize="sm">
                  {bet.metadata.league}
                </Text>
              </Td>
              <Td>{bet.marketType}</Td>
              <Td>{bet.selection}</Td>
              <Td isNumeric>{bet.odds}</Td>
              <Td isNumeric>${bet.stake.toFixed(2)}</Td>
              <Td isNumeric>${bet.potentialWinnings.toFixed(2)}</Td>
              <Td>
                <Badge colorScheme={getStatusColor(bet.status)}>{bet.status}</Badge>
              </Td>
              <Td>{format(new Date(bet.placedAt), 'MMM d, yyyy HH:mm')}</Td>
            </Tr>
          ))}
        </Tbody>
      </Table>
    </Box>
  );
};

import React from 'react';
import {
  Box,
  Typography,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  IconButton,
  TextField,
  Button,
  Divider,
  Paper,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import { useBettingStore } from '../../stores/bettingStore';
import { Bet } from '../../types/betting';

interface BetSlipProps {
  onPlaceBet: (bet: Omit<Bet, 'id' | 'status' | 'timestamp'>) => void;
}

const BetSlip: React.FC<BetSlipProps> = ({ onPlaceBet }) => {
  const { betSlip, removeBet, updateBetAmount, clearBetSlip } = useBettingStore();

  const handleStakeChange = (betId: string, amount: string) => {
    const numAmount = parseFloat(amount);
    if (!isNaN(numAmount) && numAmount >= 0) {
      updateBetAmount(betId, numAmount);
    }
  };

  const handlePlaceBets = () => {
    betSlip.bets.forEach(bet => {
      onPlaceBet({
        eventId: bet.eventId,
        market: bet.market,
        selection: bet.selection,
        odds: bet.odds,
        stake: bet.stake,
        potentialWinnings: bet.potentialWinnings,
      });
    });
    clearBetSlip();
  };

  if (betSlip.bets.length === 0) {
    return (
      <Box p={2}>
        <Typography gutterBottom variant="h6">
          Bet Slip
        </Typography>
        <Typography align="center" color="text.secondary">
          Add selections to your bet slip
        </Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Box alignItems="center" display="flex" justifyContent="space-between" p={2}>
        <Typography variant="h6">Bet Slip</Typography>
        <Button
          color="error"
          disabled={betSlip.bets.length === 0}
          size="small"
          onClick={clearBetSlip}
        >
          Clear All
        </Button>
      </Box>
      <Divider />
      <List>
        {betSlip.bets.map(bet => (
          <ListItem key={bet.id} divider>
            <ListItemText
              primary={bet.selection}
              secondary={
                <Box>
                  <Typography color="text.secondary" variant="body2">
                    {bet.market}
                  </Typography>
                  <Typography color="text.secondary" variant="body2">
                    Odds: {bet.odds}
                  </Typography>
                </Box>
              }
            />
            <ListItemSecondaryAction>
              <Box alignItems="center" display="flex" gap={1}>
                <TextField
                  inputProps={{ min: 0, step: 0.01 }}
                  size="small"
                  sx={{ width: '100px' }}
                  type="number"
                  value={bet.stake}
                  onChange={e => handleStakeChange(bet.id, e.target.value)}
                />
                <IconButton aria-label="delete" edge="end" onClick={() => removeBet(bet.id)}>
                  <DeleteIcon />
                </IconButton>
              </Box>
            </ListItemSecondaryAction>
          </ListItem>
        ))}
      </List>
      <Divider />
      <Box p={2}>
        <Box display="flex" justifyContent="space-between" mb={1}>
          <Typography>Total Stake:</Typography>
          <Typography>${betSlip.totalStake.toFixed(2)}</Typography>
        </Box>
        <Box display="flex" justifyContent="space-between" mb={2}>
          <Typography>Potential Winnings:</Typography>
          <Typography>${betSlip.potentialWinnings.toFixed(2)}</Typography>
        </Box>
        <Button
          fullWidth
          color="primary"
          disabled={betSlip.bets.length === 0}
          variant="contained"
          onClick={handlePlaceBets}
        >
          Place Bets
        </Button>
      </Box>
    </Box>
  );
};

export default React.memo(BetSlip);

import React, { useEffect, useState } from 'react';
import { Box, Grid, Paper, Typography, Tab, Tabs } from '@mui/material';
import { useSports, useEvents, useOdds, usePlaceBet } from '../../services/bettingService';
import { useBettingStore } from '../../stores/bettingStore';
import SportSelector from './SportSelector';
import EventList from './EventList';
import BetSlip from './BetSlip';
import OddsDisplay from './OddsDisplay';
import { ErrorBoundary } from 'react-error-boundary';
import { toast } from 'react-toastify';
import { BettingAnalytics } from './BettingAnalytics';

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      aria-labelledby={`betting-tab-${index}`}
      hidden={value !== index}
      id={`betting-tabpanel-${index}`}
      role="tabpanel"
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const BettingInterface: React.FC = () => {
  const { selectedSport, selectedEvent, updateOdds, setSelectedSport, setSelectedEvent } =
    useBettingStore();
  const { data: sports, isLoading: sportsLoading } = useSports();
  const { data: events, isLoading: eventsLoading } = useEvents(selectedSport?.id ?? '');
  const { data: odds } = useOdds(selectedEvent?.id ?? '');
  const placeBet = usePlaceBet();
  const [selectedTab, setSelectedTab] = useState(0);

  // Update odds in store when they change
  useEffect(() => {
    if (odds && selectedEvent) {
      updateOdds(selectedEvent.id, odds);
    }
  }, [odds, selectedEvent, updateOdds]);

  const handleError = (error: Error) => {
    toast.error(`An error occurred: ${error.message}`);
  };

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setSelectedTab(newValue);
  };

  if (sportsLoading) {
    return (
      <Box alignItems="center" display="flex" justifyContent="center" minHeight="100vh">
        <Typography>Loading sports data...</Typography>
      </Box>
    );
  }

  return (
    <ErrorBoundary fallback={<div>Something went wrong</div>} onError={handleError}>
      <Box sx={{ flexGrow: 1, height: '100vh', display: 'flex', flexDirection: 'column' }}>
        <Paper sx={{ width: '100%', mb: 2 }}>
          <Tabs
            indicatorColor="primary"
            textColor="primary"
            value={selectedTab}
            variant="fullWidth"
            onChange={handleTabChange}
          >
            <Tab label="Betting" />
            <Tab label="Analytics" />
          </Tabs>
        </Paper>

        <TabPanel index={0} value={selectedTab}>
          <Grid container spacing={2}>
            <Grid item md={3} xs={12}>
              <SportSelector selectedSport={selectedSport} onSportSelect={setSelectedSport} />
              <EventList
                selectedEvent={selectedEvent}
                sport={selectedSport}
                onEventSelect={setSelectedEvent}
              />
            </Grid>
            <Grid item md={6} xs={12}>
              {selectedEvent && <OddsDisplay event={selectedEvent} />}
            </Grid>
            <Grid item md={3} xs={12}>
              <BetSlip onPlaceBet={placeBet.mutate} />
            </Grid>
          </Grid>
        </TabPanel>

        <TabPanel index={1} value={selectedTab}>
          <BettingAnalytics />
        </TabPanel>
      </Box>
    </ErrorBoundary>
  );
};

export default React.memo(BettingInterface);

import React, { useState } from 'react';
import { Card, Button, Badge, Icon, Spinner } from '../ui/UnifiedUI';
import { Event, Market, Selection, Odds } from '../../types/sports';
import { BettingStrategy, RiskProfile } from '../../types/betting';
import { useRiskProfile } from '@/hooks/useRiskProfile';

interface BettingModalProps {
  isOpen: boolean;
  onClose: () => void;
  event: Event;
  market: Market;
  selection: Selection;
  odds: Odds;
  confidenceScore: number;
  expectedValue: number;
  kellyFraction: number;
  riskProfile: RiskProfile;
  selectedStrategy: BettingStrategy;
  onStrategyChange: (strategy: BettingStrategy) => void;
  stake: number;
  onStakeChange: (stake: number) => void;
  onPlaceBet: () => void;
  isLoading: boolean;
  error: string | null;
}

export const BettingModal: React.FC<BettingModalProps> = ({
  isOpen,
  onClose,
  event,
  market,
  selection,
  odds,
  confidenceScore,
  expectedValue,
  kellyFraction,
  riskProfile,
  selectedStrategy,
  onStrategyChange,
  stake,
  onStakeChange,
  onPlaceBet,
  isLoading,
  error: externalError,
}) => {
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { validateBet } = useRiskProfile();

  if (!isOpen) return null;

  const getStrategyDescription = (strategy: BettingStrategy): string => {
    switch (strategy) {
      case 'kelly':
        return 'Kelly Criterion: Optimal bet sizing based on edge and odds';
      case 'fixed':
        return 'Fixed Stake: Consistent bet size regardless of edge';
      case 'martingale':
        return 'Martingale: Double stake after losses';
      case 'fibonacci':
        return 'Fibonacci: Progressive stake based on Fibonacci sequence';
      default:
        return '';
    }
  };

  const getRecommendedStake = (): number => {
    switch (selectedStrategy) {
      case 'kelly':
        return kellyFraction * 100;
      case 'fixed':
        return 10; // Default fixed stake
      case 'martingale':
        return stake * 2; // Double previous stake
      case 'fibonacci':
        // Simple Fibonacci sequence implementation
        const fib = [1, 1, 2, 3, 5, 8, 13, 21];
        return fib[Math.min(fib.length - 1, Math.floor(stake / 10))] * 10;
      default:
        return stake;
    }
  };

  const handlePlaceBet = () => {
    const betData = {
      stake,
      confidence: confidenceScore,
      kellyFraction,
      sport: event.sport || '',
      market: market.name || '',
      eventId: event.id || '',
    };
    const validation = validateBet(betData);
    if (!validation.isValid) {
      setError('Bet does not meet risk profile: ' + validation.errors.join(', '));
      return;
    }
    setError(null);
    onPlaceBet();
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <Card className="w-full max-w-2xl p-6" variant="bordered">
        <div className="flex justify-between items-start mb-6">
          <div>
            <h3 className="text-xl font-semibold">Place Bet</h3>
            <p className="text-gray-600">
              {event.name} - {market.name}
            </p>
          </div>
          <Button size="small" variant="ghost" onClick={onClose}>
            <Icon className="w-5 h-5" name="x-mark" />
          </Button>
        </div>

        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-sm text-gray-600">Selection</p>
              <p className="font-medium">{selection.name}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Odds</p>
              <p className="font-medium">{odds.value.toFixed(2)}</p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div>
              <p className="text-sm text-gray-600">Confidence</p>
              <div className="flex items-center space-x-2">
                <p className="font-medium">{(confidenceScore * 100).toFixed(1)}%</p>
                <Badge
                  variant={
                    confidenceScore >= 0.7
                      ? 'success'
                      : confidenceScore >= 0.5
                        ? 'warning'
                        : 'danger'
                  }
                >
                  {confidenceScore >= 0.7 ? 'High' : confidenceScore >= 0.5 ? 'Medium' : 'Low'}
                </Badge>
              </div>
            </div>
            <div>
              <p className="text-sm text-gray-600">Expected Value</p>
              <p
                className={`font-medium ${expectedValue >= 0 ? 'text-green-500' : 'text-red-500'}`}
              >
                {(expectedValue * 100).toFixed(1)}%
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Kelly Fraction</p>
              <p className="font-medium">{(kellyFraction * 100).toFixed(1)}%</p>
            </div>
          </div>

          <div>
            <p className="text-sm text-gray-600 mb-2">Betting Strategy</p>
            <div className="grid grid-cols-2 gap-2">
              {(['kelly', 'fixed', 'martingale', 'fibonacci'] as BettingStrategy[]).map(
                strategy => (
                  <Button
                    key={strategy}
                    className="justify-start"
                    size="small"
                    variant={selectedStrategy === strategy ? 'primary' : 'secondary'}
                    onClick={() => onStrategyChange(strategy)}
                  >
                    <Icon
                      className="w-4 h-4 mr-2"
                      name={selectedStrategy === strategy ? 'check-circle' : 'circle'}
                    />
                    {strategy.charAt(0).toUpperCase() + strategy.slice(1)}
                  </Button>
                )
              )}
            </div>
            <p className="text-sm text-gray-600 mt-2">{getStrategyDescription(selectedStrategy)}</p>
          </div>

          <div>
            <p className="text-sm text-gray-600 mb-2">Stake</p>
            <div className="flex items-center space-x-4">
              <input
                className="w-32 px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                min="0"
                step="0.01"
                type="number"
                value={stake}
                onChange={e => onStakeChange(Number(e.target.value))}
              />
              <Button
                size="small"
                variant="secondary"
                onClick={() => onStakeChange(getRecommendedStake())}
              >
                Use Recommended
              </Button>
            </div>
          </div>

          <div>
            <Button
              className="flex items-center"
              size="small"
              variant="ghost"
              onClick={() => setShowAdvanced(!showAdvanced)}
            >
              <Icon className="w-4 h-4 mr-2" name={showAdvanced ? 'chevron-up' : 'chevron-down'} />
              Advanced Options
            </Button>

            {showAdvanced && (
              <div className="mt-4 p-4 bg-gray-50 rounded-lg">
                <div className="space-y-4">
                  <div>
                    <p className="text-sm font-medium mb-2">Risk Profile</p>
                    <div className="flex items-center space-x-2">
                      <Badge variant={riskProfile.riskLevel.toLowerCase() as any}>
                        {riskProfile.riskLevel}
                      </Badge>
                      <p className="text-sm text-gray-600">{riskProfile.recommendation}</p>
                    </div>
                  </div>

                  <div>
                    <p className="text-sm font-medium mb-2">Top Risk Factors</p>
                    <div className="space-y-2">
                      {riskProfile.factors.map((factor, index) => (
                        <div key={index} className="flex items-center justify-between">
                          <p className="text-sm">{factor.name}</p>
                          <Badge variant={factor.severity.toLowerCase() as any}>
                            {factor.severity}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {error && (
            <div className="text-red-500 text-center">
              <Icon className="w-5 h-5 mx-auto mb-2" name="exclamation-circle" />
              <p>{error}</p>
            </div>
          )}
          {externalError && !error && (
            <div className="text-red-500 text-center">
              <Icon className="w-5 h-5 mx-auto mb-2" name="exclamation-circle" />
              <p>{externalError}</p>
            </div>
          )}

          <div className="flex justify-end space-x-4">
            <Button disabled={isLoading} variant="secondary" onClick={onClose}>
              Cancel
            </Button>
            <Button disabled={isLoading || stake <= 0} variant="primary" onClick={handlePlaceBet}>
              {isLoading ? (
                <>
                  <Spinner className="mr-2" size="small" />
                  Placing Bet...
                </>
              ) : (
                'Place Bet'
              )}
            </Button>
          </div>
        </div>
      </Card>
    </div>
  );
};

import React, { useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  Divider,
  Alert,
  CircularProgress,
  Stack,
  Button,
} from '@mui/material';
