}

const INITIAL_CONFIG: ConfigurationMatrix = {
  investmentAmount: 1000,
  mlModelSet: 'ensemble',
  confidenceThreshold: 85,
  strategyMode: 'balanced',
  portfolioSize: 3,
  sportsUniverse: ['NBA'],
  timeWindow: 'today',
};

const ML_MODEL_SETS = [
