export const UnifiedEventDetails: React.FC = () => {
  // Initialize services
  const serviceRegistry = UnifiedServiceRegistry.getInstance();
  const predictionService = serviceRegistry.getService<UnifiedPredictionService>('prediction');
  const analyticsService = serviceRegistry.getService<UnifiedAnalyticsService>('analytics');
  const stateService = serviceRegistry.getService<UnifiedStateService>('state');
  const notificationService =
    serviceRegistry.getService<UnifiedNotificationService>('notification');
  const errorService = serviceRegistry.getService<UnifiedErrorService>('error');

  // Router hooks
  const { eventId } = useParams<{ eventId: string }>();

  // State
  const [event, setEvent] = useState<Event | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<{
    message: string;
    type: 'success' | 'error' | 'warning' | 'info';
  } | null>(null);
  const [selectedMarket, setSelectedMarket] = useState<Market | null>(null);
  const [showBetModal, setShowBetModal] = useState(false);
  const [selectedSelection, setSelectedSelection] = useState<Selection | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'markets' | 'statistics' | 'predictions'>(
    'overview'
  );

  // Load event data
  useEffect(() => {
    if (eventId) {
      loadEventData(eventId);
    }
  }, [eventId]);

  const loadEventData = async (id: string) => {
    try {
      setLoading(true);
      const [eventData, predictions] = await Promise.all([
        analyticsService.getEventDetails(id),
        predictionService.getEventPredictions(id),
      ]);
      setEvent({ ...eventData, predictions });
    } catch (error) {
      handleError('Failed to load event data', error);
    } finally {
      setLoading(false);
    }
  };

  const handleError = (message: string, error: any) => {
    setError(message);
    setToast({ message, type: 'error' });
    errorService.handleError(error, {
      code: 'EVENT_DETAILS_ERROR',
      source: 'UnifiedEventDetails',
      details: { message },
    });
  };

  const formatOdds = (odds: number) => {
    return odds.toFixed(2);
  };

  const formatPercentage = (value: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'percent',
      minimumFractionDigits: 1,
      maximumFractionDigits: 1,
    }).format(value / 100);
  };

  const getStatusBadge = (status: Event['status']) => {
    const variants = {
      upcoming: 'info',
      live: 'success',
      ended: 'secondary',
      cancelled: 'danger',
    };
    return <Badge variant={variants[status]}>{status.toUpperCase()}</Badge>;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Spinner size="large" />
      </div>
    );
  }

  if (!event) {
    return (
      <div className="container mx-auto px-4 py-8">
        <Card>
          <div className="text-center">
            <h2 className="text-2xl font-bold text-red-600">Event Not Found</h2>
            <p className="mt-2 text-gray-600">The requested event could not be found.</p>
          </div>
        </Card>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="max-w-7xl mx-auto">
        {/* Event Header */}
        <Card className="mb-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <img
                alt={event.homeTeam.name}
                className="w-16 h-16 object-contain"
                src={event.homeTeam.logo}
              />
              <div>
                <h1 className="text-2xl font-bold">{event.name}</h1>
                <p className="text-gray-600 dark:text-gray-400">
                  {event.competition} • {event.sport}
                </p>
              </div>
            </div>
            <div className="flex items-center space-x-4">
              {getStatusBadge(event.status)}
              <p className="text-gray-600 dark:text-gray-400">
                {new Date(event.startTime).toLocaleString()}
              </p>
            </div>
          </div>
        </Card>

        {/* Navigation Tabs */}
        <Tabs className="mb-8" value={activeTab} onChange={setActiveTab}>
          <Tab label="Overview" value="overview" />
          <Tab label="Markets" value="markets" />
          <Tab label="Statistics" value="statistics" />
          <Tab label="Predictions" value="predictions" />
        </Tabs>

        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Teams */}
            <Card>
              <h2 className="text-xl font-bold mb-4">Teams</h2>
              <div className="space-y-6">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-4">
                    <img
                      alt={event.homeTeam.name}
                      className="w-12 h-12 object-contain"
                      src={event.homeTeam.logo}
                    />
                    <div>
                      <h3 className="font-medium">{event.homeTeam.name}</h3>
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        Win Rate: {formatPercentage(event.homeTeam.stats.winRate)}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-medium">{event.homeTeam.stats.goalsScored} Goals</p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      {event.homeTeam.stats.cleanSheets} Clean Sheets
                    </p>
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-4">
                    <img
                      alt={event.awayTeam.name}
                      className="w-12 h-12 object-contain"
                      src={event.awayTeam.logo}
                    />
                    <div>
                      <h3 className="font-medium">{event.awayTeam.name}</h3>
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        Win Rate: {formatPercentage(event.awayTeam.stats.winRate)}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-medium">{event.awayTeam.stats.goalsScored} Goals</p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      {event.awayTeam.stats.cleanSheets} Clean Sheets
                    </p>
                  </div>
                </div>
              </div>
            </Card>

            {/* Venue & Weather */}
            <Card>
              <h2 className="text-xl font-bold mb-4">Venue & Weather</h2>
              <div className="space-y-4">
                <div>
                  <h3 className="font-medium">Venue</h3>
                  <p className="text-gray-600 dark:text-gray-400">
                    {event.venue.name}, {event.venue.city}, {event.venue.country}
                  </p>
                </div>
                {event.weather && (
                  <div>
                    <h3 className="font-medium">Weather</h3>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <p className="text-sm text-gray-600 dark:text-gray-400">Condition</p>
                        <p>{event.weather.condition}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-600 dark:text-gray-400">Temperature</p>
                        <p>{event.weather.temperature}°C</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-600 dark:text-gray-400">Wind Speed</p>
                        <p>{event.weather.windSpeed} km/h</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-600 dark:text-gray-400">Precipitation</p>
                        <p>{event.weather.precipitation}%</p>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </Card>

            {/* Head to Head */}
            <Card>
              <h2 className="text-xl font-bold mb-4">Head to Head</h2>
              <div className="space-y-4">
                <div className="grid grid-cols-3 gap-4 text-center">
                  <div>
                    <p className="text-2xl font-bold">{event.statistics.headToHead.homeWins}</p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">Home Wins</p>
                  </div>
                  <div>
                    <p className="text-2xl font-bold">{event.statistics.headToHead.draws}</p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">Draws</p>
                  </div>
                  <div>
                    <p className="text-2xl font-bold">{event.statistics.headToHead.awayWins}</p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">Away Wins</p>
                  </div>
                </div>
                <div>
                  <h3 className="font-medium mb-2">Last 5 Meetings</h3>
                  <div className="space-y-2">
                    {event.statistics.headToHead.lastFive.map((match, index) => (
                      <div
                        key={index}
                        className="flex items-center justify-between p-2 bg-gray-50 dark:bg-gray-800 rounded"
                      >
                        <div className="flex-1">{match.homeTeam}</div>
                        <div className="px-4 font-medium">{match.score}</div>
                        <div className="flex-1 text-right">{match.awayTeam}</div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </Card>

            {/* Form & Trends */}
            <Card>
              <h2 className="text-xl font-bold mb-4">Form & Trends</h2>
              <div className="space-y-4">
                <div>
                  <h3 className="font-medium mb-2">Recent Form</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
                        {event.homeTeam.name}
                      </p>
                      <div className="flex space-x-1">
                        {event.statistics.form.home.lastFive.map((result, index) => (
                          <Badge
                            key={index}
                            variant={
                              result === 'W' ? 'success' : result === 'D' ? 'warning' : 'danger'
                            }
                          >
                            {result}
                          </Badge>
                        ))}
                      </div>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
                        {event.awayTeam.name}
                      </p>
                      <div className="flex space-x-1">
                        {event.statistics.form.away.lastFive.map((result, index) => (
                          <Badge
                            key={index}
                            variant={
                              result === 'W' ? 'success' : result === 'D' ? 'warning' : 'danger'
                            }
                          >
                            {result}
                          </Badge>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
                <div>
                  <h3 className="font-medium mb-2">Trends</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm text-gray-600 dark:text-gray-400">Over/Under 2.5</p>
                      <p className="font-medium">
                        Over: {formatPercentage(event.statistics.trends.overUnder.over2_5)} • Under:{' '}
                        {formatPercentage(event.statistics.trends.overUnder.under2_5)}
                      </p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        Both Teams to Score
                      </p>
                      <p className="font-medium">
                        Yes: {formatPercentage(event.statistics.trends.bothTeamsToScore.yes)} • No:{' '}
                        {formatPercentage(event.statistics.trends.bothTeamsToScore.no)}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Markets Tab */}
        {activeTab === 'markets' && (
          <div className="space-y-8">
            {event.markets.map(market => (
              <Card key={market.id}>
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-xl font-bold">{market.name}</h2>
                  <Badge
                    variant={
                      market.status === 'open'
                        ? 'success'
                        : market.status === 'suspended'
                          ? 'warning'
                          : 'secondary'
                    }
                  >
                    {market.status.toUpperCase()}
                  </Badge>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {market.selections.map(selection => (
                    <div key={selection.id} className="p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <span className="font-medium">{selection.name}</span>
                        <span className="text-lg font-bold">{formatOdds(selection.odds)}</span>
                      </div>
                      {selection.prediction && (
                        <div className="space-y-1 text-sm">
                          <div className="flex justify-between">
                            <span className="text-gray-600 dark:text-gray-400">Confidence</span>
                            <span>{formatPercentage(selection.prediction.confidence)}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-gray-600 dark:text-gray-400">Value</span>
                            <span
                              className={
                                selection.prediction.expectedValue > 0
                                  ? 'text-green-600'
                                  : 'text-red-600'
                              }
                            >
                              {formatPercentage(selection.prediction.expectedValue)}
                            </span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-gray-600 dark:text-gray-400">Kelly</span>
                            <span>{formatPercentage(selection.prediction.kellyFraction)}</span>
                          </div>
                        </div>
                      )}
                      <Button
                        className="w-full mt-4"
                        disabled={market.status !== 'open'}
                        variant="primary"
                        onClick={() => {
                          setSelectedMarket(market);
                          setSelectedSelection(selection);
                          setShowBetModal(true);
                        }}
                      >
                        Place Bet
                      </Button>
                    </div>
                  ))}
                </div>
              </Card>
            ))}
          </div>
        )}

        {/* Statistics Tab */}
        {activeTab === 'statistics' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Team Statistics */}
            <Card>
              <h2 className="text-xl font-bold mb-4">Team Statistics</h2>
              <div className="space-y-6">
                <div>
                  <h3 className="font-medium mb-2">{event.homeTeam.name}</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span>Goals Scored</span>
                      <span>{event.statistics.form.home.goalsScored}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Goals Conceded</span>
                      <span>{event.statistics.form.home.goalsConceded}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Clean Sheets</span>
                      <span>{event.homeTeam.stats.cleanSheets}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Win Rate</span>
                      <span>{formatPercentage(event.homeTeam.stats.winRate)}</span>
                    </div>
                  </div>
                </div>
                <div>
                  <h3 className="font-medium mb-2">{event.awayTeam.name}</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span>Goals Scored</span>
                      <span>{event.statistics.form.away.goalsScored}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Goals Conceded</span>
                      <span>{event.statistics.form.away.goalsConceded}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Clean Sheets</span>
                      <span>{event.awayTeam.stats.cleanSheets}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Win Rate</span>
                      <span>{formatPercentage(event.awayTeam.stats.winRate)}</span>
                    </div>
                  </div>
                </div>
              </div>
            </Card>

            {/* Match Statistics */}
            <Card>
              <h2 className="text-xl font-bold mb-4">Match Statistics</h2>
              <div className="space-y-6">
                <div>
                  <h3 className="font-medium mb-2">Goals</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span>Average Goals per Game</span>
                      <span>{event.statistics.trends.overUnder.averageGoals.toFixed(2)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Over 2.5 Goals</span>
                      <span>{formatPercentage(event.statistics.trends.overUnder.over2_5)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Under 2.5 Goals</span>
                      <span>{formatPercentage(event.statistics.trends.overUnder.under2_5)}</span>
                    </div>
                  </div>
                </div>
                <div>
                  <h3 className="font-medium mb-2">Both Teams to Score</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span>Yes</span>
                      <span>{formatPercentage(event.statistics.trends.bothTeamsToScore.yes)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>No</span>
                      <span>{formatPercentage(event.statistics.trends.bothTeamsToScore.no)}</span>
                    </div>
                  </div>
                </div>
                <div>
                  <h3 className="font-medium mb-2">First Half</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span>Home Wins</span>
                      <span>{formatPercentage(event.statistics.trends.firstHalf.homeWins)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Away Wins</span>
                      <span>{formatPercentage(event.statistics.trends.firstHalf.awayWins)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Draws</span>
                      <span>{formatPercentage(event.statistics.trends.firstHalf.draws)}</span>
                    </div>
                  </div>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Predictions Tab */}
        {activeTab === 'predictions' && (
          <div className="space-y-8">
            {event.predictions.map((prediction, index) => (
              <Card key={index}>
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-xl font-bold">
                    {prediction.marketType} - {prediction.selection}
                  </h2>
                  <Badge
                    variant={
                      prediction.expectedValue > 0
                        ? 'success'
                        : prediction.expectedValue < 0
                          ? 'danger'
                          : 'warning'
                    }
                  >
                    {formatPercentage(prediction.expectedValue)} Expected Value
                  </Badge>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <h3 className="font-medium mb-2">Prediction Details</h3>
                    <div className="space-y-2">
                      <div className="flex justify-between">
                        <span>Confidence</span>
                        <span>{formatPercentage(prediction.confidence)}</span>
                      </div>
                      <div className="flex justify-between">
                        <span>Expected Value</span>
                        <span
                          className={
                            prediction.expectedValue > 0 ? 'text-green-600' : 'text-red-600'
                          }
                        >
                          {formatPercentage(prediction.expectedValue)}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span>Kelly Fraction</span>
                        <span>{formatPercentage(prediction.kellyFraction)}</span>
                      </div>
                    </div>
                  </div>
                  <div>
                    <h3 className="font-medium mb-2">Factors</h3>
                    <div className="space-y-2">
                      {prediction.factors.map((factor, factorIndex) => (
                        <div key={factorIndex} className="p-2 bg-gray-50 dark:bg-gray-800 rounded">
                          <div className="flex justify-between mb-1">
                            <span className="font-medium">{factor.name}</span>
                            <span className={factor.impact > 0 ? 'text-green-600' : 'text-red-600'}>
                              {formatPercentage(factor.impact)}
                            </span>
                          </div>
                          <p className="text-sm text-gray-600 dark:text-gray-400">
                            {factor.description}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>

      {/* Bet Modal */}
      <Modal isOpen={showBetModal} title="Place Bet" onClose={() => setShowBetModal(false)}>
        {selectedMarket && selectedSelection && (
          <div className="space-y-4">
            <div>
              <h3 className="font-medium mb-2">Bet Details</h3>
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span>Market</span>
                  <span>{selectedMarket.name}</span>
                </div>
                <div className="flex justify-between">
                  <span>Selection</span>
                  <span>{selectedSelection.name}</span>
                </div>
                <div className="flex justify-between">
                  <span>Odds</span>
                  <span>{formatOdds(selectedSelection.odds)}</span>
                </div>
              </div>
            </div>
            {selectedSelection.prediction && (
              <div>
                <h3 className="font-medium mb-2">Prediction</h3>
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span>Confidence</span>
                    <span>{formatPercentage(selectedSelection.prediction.confidence)}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Expected Value</span>
                    <span
                      className={
                        selectedSelection.prediction.expectedValue > 0
                          ? 'text-green-600'
                          : 'text-red-600'
                      }
                    >
                      {formatPercentage(selectedSelection.prediction.expectedValue)}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span>Recommended Stake</span>
                    <span>{formatPercentage(selectedSelection.prediction.kellyFraction)}</span>
                  </div>
                </div>
              </div>
            )}
            <div>
              <h3 className="font-medium mb-2">Stake</h3>
              <Input min="0" placeholder="Enter stake amount" step="0.01" type="number" />
            </div>
            <div className="flex justify-end space-x-4">
              <Button variant="secondary" onClick={() => setShowBetModal(false)}>
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={() => {
                  // Handle bet placement
                  setShowBetModal(false);
                }}
              >
                Place Bet
              </Button>
            </div>
          </div>
        )}
      </Modal>

      {/* Toast Notifications */}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Loader2, AlertTriangle } from 'lucide-react';
import { predictionService, GeneralInsight } from '../../services/predictionService'; // If fetched directly, added GeneralInsight

// import { useAppStore } from '../../store/useAppStore'; // If insights come via general app state

// interface Insight { // Using GeneralInsight from service now
//     id: string;
//     text: string;
//     source: string;
//     // Add other relevant fields like type, confidence, relatedEntityId, etc.
// }

const MLInsights: React.FC = () => {
  const [insights, setInsights] = useState<GeneralInsight[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchInsights = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const data = await predictionService.fetchGeneralInsights(); 
        setInsights(data); 
      } catch (e: any) {
        console.error("Failed to fetch ML insights", e);
        setError(e.message || "An unknown error occurred while fetching insights.");
        setInsights([]); // Clear insights on error
      } finally {
        setIsLoading(false);
      }
    };
    fetchInsights();
  }, []);

  // Placeholder content removed
  // const placeholderInsights = [
  //   { id: 'insight1', text: 'Based on recent trends, consider Player A for Over 25.5 Points.', source: 'Performance Analyzer' },
  //   { id: 'insight2', text: 'Social sentiment for Team B is highly positive for their upcoming match.', source: 'Sentiment Engine' },
  //   { id: 'insight3', text: 'Arbitrage opportunity detected: Prop X (Over) vs Prop Y (Under).', source: 'Arbitrage Scanner' },
  // ];

  if (isLoading) return (
    <div className="flex items-center justify-center p-6 glass rounded-xl bg-gradient-to-r from-purple-500/10 to-blue-500/10 animate-pulse-soft">
        <Loader2 className="w-6 h-6 animate-spin text-primary mr-2" /> 
        <p className="text-text-muted">Loading AI insights...</p>
    </div>
  );

  if (error) return (
    <div className="p-6 glass rounded-xl bg-red-500/10 text-red-400 flex items-center animate-fade-in">
        <AlertTriangle size={20} className="mr-2"/> Error: {error}
    </div>
  );

  return (
    <div className="space-y-4">
      <div className="mb-2 flex items-center gap-3">
        <span className="text-2xl">🤖</span>
        <h4 className="text-lg font-bold bg-gradient-to-r from-purple-500 to-blue-500 bg-clip-text text-transparent">Machine Learning Insights</h4>
      </div>
      {Array.isArray(insights) && insights.length > 0 ? (
        (insights || []).map(insight => (
          <div key={insight.id} className="p-4 glass rounded-xl shadow-md bg-gradient-to-r from-purple-400/10 to-blue-400/10 animate-fade-in">
            <p className="text-base text-text font-semibold mb-1">{insight.text}</p>
            <p className="text-xs text-text-muted mt-1">
                Source: {insight.source} 
                {insight.confidence && ` | Confidence: ${(insight.confidence * 100).toFixed(0)}%`}
                {insight.type && ` | Type: ${insight.type}`}
            </p>
          </div>
        ))
      ) : (
        <p className="text-text-muted text-center p-4">No AI insights available at the moment.</p>
      )}
    </div>
  );
};

export default MLInsights;

import React from 'react';
import { Box, Card, CardContent, Typography, LinearProgress, Skeleton } from '@mui/material';
import { formatPercentage } from '@/utils/formatters';

interface PerformanceMetricsProps {
  performance: {
    winRate: number;
    roi: number;
    edgeRetention: number;
    totalBets: number;
    averageOdds: number;
    profitLoss: number;
  };
  isLoading: boolean;
}

export const PerformanceMetrics: React.FC<PerformanceMetricsProps> = ({
  performance,
  isLoading,
}) => {
  const metrics = [
    {
      label: 'Win Rate',
      value: performance.winRate,
      format: formatPercentage,
      color: performance.winRate >= 0.55 ? 'success' : 'warning',
    },
    {
      label: 'ROI',
      value: performance.roi,
      format: formatPercentage,
      color: performance.roi > 0 ? 'success' : 'error',
    },
    {
      label: 'Edge Retention',
      value: performance.edgeRetention,
      format: formatPercentage,
      color: performance.edgeRetention >= 0.7 ? 'success' : 'warning',
    },
    {
      label: 'Total Bets',
      value: performance.totalBets,
      format: (value: number) => value.toString(),
      color: 'primary',
    },
    {
      label: 'Average Odds',
      value: performance.averageOdds,
      format: (value: number) => value.toFixed(2),
      color: 'primary',
    },
    {
      label: 'Profit/Loss',
      value: performance.profitLoss,
      format: (value: number) => `$${value.toFixed(2)}`,
      color: performance.profitLoss > 0 ? 'success' : 'error',
    },
  ];

  if (isLoading) {
    return (
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: '1fr',
            sm: 'repeat(2, 1fr)',
            md: 'repeat(3, 1fr)',
          },
          gap: 3,
        }}
      >
        {metrics.map((_, index) => (
          <Card key={index}>
            <CardContent>
              <Skeleton variant="text" width="60%" />
              <Skeleton height={40} sx={{ mt: 2 }} variant="rectangular" />
            </CardContent>
          </Card>
        ))}
      </Box>
    );
  }

  return (
    <Box
      sx={{
        display: 'grid',
        gridTemplateColumns: {
          xs: '1fr',
          sm: 'repeat(2, 1fr)',
          md: 'repeat(3, 1fr)',
        },
        gap: 3,
      }}
    >
      {metrics.map((metric, index) => (
        <Card key={index}>
          <CardContent>
            <Typography gutterBottom color="text.secondary" variant="subtitle2">
              {metric.label}
            </Typography>
            <Typography gutterBottom component="div" variant="h4">
              {metric.format(metric.value)}
            </Typography>
            <LinearProgress
              color={metric.color as any}
              sx={{ height: 8, borderRadius: 4 }}
              value={Math.min(Math.abs(metric.value) * 100, 100)}
              variant="determinate"
            />
          </CardContent>
        </Card>
      ))}
    </Box>
  );
};

import React from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  Divider,
  List,
  ListItem,
  ListItemText,
  Tooltip,
} from '@mui/material';
import { Info } from '@mui/icons-material';
import { ShapValue } from '../types/explainability';

interface ShapBreakdownModalProps {
  isOpen: boolean;
  onClose: () => void;
  feature: ShapValue;
}

export const ShapBreakdownModal: React.FC<ShapBreakdownModalProps> = ({
  isOpen,
  onClose,
  feature,
}) => {
  const getImpactColor = (impact: number) => {
    if (impact > 0) return 'success.main';
    if (impact < 0) return 'error.main';
    return 'text.secondary';
  };

  const getImpactLabel = (impact: number) => {
    if (impact > 0) return 'Positive Impact';
    if (impact < 0) return 'Negative Impact';
    return 'Neutral Impact';
  };

  return (
    <Dialog
      fullWidth
      maxWidth="sm"
      open={isOpen}
      PaperProps={{
        sx: {
          borderRadius: 2,
          boxShadow: 24,
        },
      }}
      onClose={onClose}
    >
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="h6">Feature Impact Analysis</Typography>
          <Tooltip title="SHAP values show how each feature contributes to the prediction">
            <Info color="action" fontSize="small" />
          </Tooltip>
        </Box>
      </DialogTitle>

      <DialogContent>
        <Box sx={{ mb: 3 }}>
          <Typography gutterBottom variant="subtitle1">
            {feature.feature}
          </Typography>
          {feature.description && (
            <Typography paragraph color="text.secondary" variant="body2">
              {feature.description}
            </Typography>
          )}
        </Box>

        <Divider sx={{ my: 2 }} />

        <Box sx={{ mb: 3 }}>
          <Typography gutterBottom variant="subtitle2">
            Impact Analysis
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            <Typography
              color={getImpactColor(feature.impact)}
              sx={{ fontWeight: 'bold' }}
              variant="h4"
            >
              {feature.impact > 0 ? '+' : ''}
              {feature.impact.toFixed(3)}
            </Typography>
            <Typography color="text.secondary" variant="body2">
              {getImpactLabel(feature.impact)}
            </Typography>
          </Box>
        </Box>

        {feature.details && (
          <>
            <Divider sx={{ my: 2 }} />
            <Typography gutterBottom variant="subtitle2">
              Additional Details
            </Typography>
            <Typography color="text.secondary" variant="body2">
              {feature.details}
            </Typography>
          </>
        )}

        {feature.weight !== undefined && (
          <Box sx={{ mt: 3 }}>
            <Typography gutterBottom variant="subtitle2">
              Feature Weight
            </Typography>
            <Typography color="text.secondary" variant="body2">
              This feature contributes {feature.weight.toFixed(2)}% to the overall prediction
            </Typography>
          </Box>
        )}
      </DialogContent>

      <DialogActions>
        <Button color="primary" onClick={onClose}>
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
};

import React, { useMemo, useCallback } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  LinearProgress,
  Tooltip,
  IconButton,
  Collapse,
  Fade,
  Skeleton,
} from '@mui/material';
import {
  Info as InfoIcon,
  TrendingUp as TrendingUpIcon,
  TrendingDown as TrendingDownIcon,
} from '@mui/icons-material';
import { formatPercentage } from '../utils/formatters';
import type { Feature } from '../types/prediction';

interface ShapFeature {
  name: string;
  value: number;
  impact: number;
}

interface ShapVisualizationProps {
  features: ShapFeature[];
  title: string;
  maxFeatures?: number;
  isLoading?: boolean;
}

const ShapVisualization: React.FC<ShapVisualizationProps> = ({
  features,
  title,
  maxFeatures = 8,
  isLoading = false,
}) => {
  if (isLoading) {
    return (
      <Box>
        <Skeleton variant="text" width="60%" />
        {[...Array(3)].map((_, index) => (
          <Box key={index} sx={{ mt: 2 }}>
            <Skeleton variant="text" width="40%" />
            <Skeleton height={24} sx={{ mt: 1 }} variant="rectangular" />
          </Box>
        ))}
      </Box>
    );
  }

  const sortedFeatures = [...features]
    .sort((a, b) => Math.abs(b.impact) - Math.abs(a.impact))
    .slice(0, maxFeatures);

  const maxImpact = Math.max(...sortedFeatures.map(f => Math.abs(f.impact)));

  return (
    <Box>
      <Typography gutterBottom variant="h6">
        {title}
      </Typography>
      {sortedFeatures.map((feature, index) => (
        <Box key={index} sx={{ mb: 2 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
            <Typography color="text.secondary" variant="body2">
              {feature.name}
            </Typography>
            <Typography color={feature.impact > 0 ? 'success.main' : 'error.main'} variant="body2">
              {feature.impact > 0 ? '+' : ''}
              {feature.impact.toFixed(3)}
            </Typography>
          </Box>
          <LinearProgress
            color={feature.impact > 0 ? 'success' : 'error'}
            sx={{
              height: 8,
              borderRadius: 4,
              backgroundColor: 'action.hover',
              '& .MuiLinearProgress-bar': {
                transform: feature.impact < 0 ? 'scaleX(-1)' : 'none',
              },
            }}
            value={(Math.abs(feature.impact) / maxImpact) * 100}
            variant="determinate"
          />
        </Box>
      ))}
    </Box>
  );
};

export default React.memo(ShapVisualization);

