        </GlassCard>
        <GlassCard className="p-4 animate-fade-in">
          <h3 className="text-lg font-semibold text-primary-600 mb-2">Your Picks</h3>
          {selectedProps.length === 0 && <div className="text-gray-400">No picks selected yet.</div>}
          <div className="space-y-2">
            {selectedProps.map((leg: PlayerProp) => (
              <EnhancedPropCard
                key={leg.id}
                playerName={leg.player?.name || (leg as any).playerName}
                statType={leg.type}
                line={leg.line}
                overOdds={(leg as any).odds?.over ?? (leg as any).overOdds}
                underOdds={(leg as any).odds?.under ?? (leg as any).underOdds}
                sentiment={(leg as any).sentiment}
                aiBoost={(leg as any).aiBoost}
                patternStrength={(leg as any).patternStrength}
                bonusPercent={bonusPercent}
                enhancementPercent={enhancementPercent}
                selected={true}
                onSelect={(pick: 'over' | 'under') => handleSelect(leg, pick)}
                onViewDetails={() => handleViewDetails(leg)}
                className="opacity-90"
              />
            ))}
          </div>
          {/* --- POE-preview: PayoutPreview integration --- */}
          {selectedProps.length > 0 && (
            <div className="mt-6 animate-fade-in">
              <PayoutPreview eventId={selectedProps[0].id} />
            </div>
          )}
        </GlassCard>
        {error && <div className="p-4 text-red-600 text-sm font-medium">{error}</div>}
        {success && <div className="p-4 text-green-600 text-sm font-medium">{success}</div>}
        <div className="flex justify-end">
          <button
            className="modern-button bg-primary-500 text-white px-8 py-3 rounded-xl font-bold text-lg disabled:opacity-50 disabled:cursor-not-allowed"
            disabled={loading || selectedProps.length < 2}
            onClick={handleSubmit}
          >
            {loading ? <span className="loading-spinner-premium"></span> : 'Submit Entry'}
          </button>
        </div>
      </div>
      {/* Overlay for prediction explanation */}
      <PredictionExplanationOverlay
        open={overlayOpen}
        onClose={() => setOverlayOpen(false)}
        data={{}}
      />
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useBettingAnalytics } from '../hooks/useBettingAnalytics';
import { useSmartAlerts } from '../hooks/useSmartAlerts';
import { BettingOpportunity } from '../services/bettingStrategy';
import { PredictionResult } from '../services/predictionService';
import { Card } from './base/Card';
import { Progress } from './base/Progress';
import { Badge } from './base/Badge';
import { Alert } from './base/Alert';
import { Skeleton } from './base/Skeleton';
import { Table } from './base/Table';

interface BettingAnalyticsProps {
  onOpportunitySelect?: (opportunity: BettingOpportunity) => void;
}

interface PredictionFactor {
  name: string;
  impact: number;
  description: string;
}

export const BettingAnalytics: React.FC<BettingAnalyticsProps> = ({
  onOpportunitySelect
}) => {
  const [selectedSport, setSelectedSport] = useState<string>('all');
  const [confidenceThreshold, setConfidenceThreshold] = useState(0.7);
  const [sortField, setSortField] = useState<string>('confidence');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('desc');

  const {
    opportunities,
    predictions,
    performance,
    isLoading,
    error
  } = useBettingAnalytics({
    minConfidence: confidenceThreshold,
    autoRefresh: true,
    refreshInterval: 30000
  });

  const { alerts } = useSmartAlerts({
    wsEndpoint: import.meta.env.VITE_WS_ENDPOINT || '',
    enabledTypes: ['LINE_MOVEMENT', 'INJURY', 'WEATHER'],
    minSeverity: 'medium'
  });

  const filteredOpportunities = useMemo(() => {
    return opportunities
      .filter(opp => selectedSport === 'all' || opp.sport === selectedSport)
      .sort((a, b) => {
        const aValue = a[sortField as keyof BettingOpportunity];
        const bValue = b[sortField as keyof BettingOpportunity];
        return sortDirection === 'asc' 
          ? (aValue > bValue ? 1 : -1)
          : (bValue > aValue ? 1 : -1);
      });
  }, [opportunities, selectedSport, sortField, sortDirection]);

  const handleOpportunityClick = useCallback((opportunity: BettingOpportunity) => {
    onOpportunitySelect?.(opportunity);
  }, [onOpportunitySelect]);

  const renderPerformanceMetrics = () => (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
      <Card>
        <div className="p-4">
          <h3 className="text-sm font-medium text-gray-500">Win Rate</h3>
          <div className="mt-2 flex items-center">
            <span className="text-2xl font-semibold">
              {(performance.winRate * 100).toFixed(1)}%
            </span>
            <Badge
              variant={performance.winRate >= 0.55 ? 'success' : 'warning'}
              className="ml-2"
            >
              {performance.winRate >= 0.55 ? 'Profitable' : 'Monitor'}
            </Badge>
          </div>
          <Progress
            value={performance.winRate * 100}
            max={100}
            variant={performance.winRate >= 0.55 ? 'success' : 'warning'}
            className="mt-2"
          />
        </div>
      </Card>

      <Card>
        <div className="p-4">
          <h3 className="text-sm font-medium text-gray-500">ROI</h3>
          <div className="mt-2 flex items-center">
            <span className="text-2xl font-semibold">
              {(performance.roi * 100).toFixed(1)}%
            </span>
            <Badge
              variant={performance.roi > 0 ? 'success' : 'danger'}
              className="ml-2"
            >
              {performance.roi > 0 ? 'Positive' : 'Negative'}
            </Badge>
          </div>
          <Progress
            value={Math.min(Math.max(performance.roi * 100, 0), 100)}
            max={100}
            variant={performance.roi > 0 ? 'success' : 'danger'}
            className="mt-2"
          />
        </div>
      </Card>

      <Card>
        <div className="p-4">
          <h3 className="text-sm font-medium text-gray-500">Edge Retention</h3>
          <div className="mt-2 flex items-center">
            <span className="text-2xl font-semibold">
              {(performance.edgeRetention * 100).toFixed(1)}%
            </span>
            <Badge
              variant={performance.edgeRetention >= 0.7 ? 'success' : 'warning'}
              className="ml-2"
            >
              {performance.edgeRetention >= 0.7 ? 'Strong' : 'Weak'}
            </Badge>
          </div>
          <Progress
            value={performance.edgeRetention * 100}
            max={100}
            variant={performance.edgeRetention >= 0.7 ? 'success' : 'warning'}
            className="mt-2"
          />
        </div>
      </Card>
    </div>
  );

  if (error) {
    return (
      <Alert
        type="error"
        title="Error Loading Analytics"
        message={error.message}
      />
    );
  }

  return (
    <div className="space-y-6">
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <Skeleton className="h-32" />
          <Skeleton className="h-32" />
          <Skeleton className="h-32" />
        </div>
      ) : (
        renderPerformanceMetrics()
      )}

      <Card>
        <div className="p-4">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-lg font-semibold">Betting Opportunities</h2>
            <div className="flex space-x-2">
              <select
                className="form-select"
                value={selectedSport}
                onChange={(e) => setSelectedSport(e.target.value)}
              >
                <option value="all">All Sports</option>
                <option value="NBA">NBA</option>
                <option value="NFL">NFL</option>
                <option value="MLB">MLB</option>
                <option value="NHL">NHL</option>
              </select>
              <select
                className="form-select"
                value={confidenceThreshold}
                onChange={(e) => setConfidenceThreshold(Number(e.target.value))}
              >
                <option value={0.6}>60%+ Confidence</option>
                <option value={0.7}>70%+ Confidence</option>
                <option value={0.8}>80%+ Confidence</option>
                <option value={0.9}>90%+ Confidence</option>
              </select>
            </div>
          </div>

          <AnimatePresence>
            {alerts.length > 0 && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="mb-4"
              >
                <Alert
                  type="warning"
                  title="Active Alerts"
                  message={`${alerts.length} alert${alerts.length === 1 ? '' : 's'} require your attention`}
                />
              </motion.div>
            )}
          </AnimatePresence>

          <Table
            data={filteredOpportunities}
            columns={[
              {
                key: 'sport',
                title: 'Sport',
                render: (value) => (
                  <Badge variant="default">{value}</Badge>
                )
              },
              {
                key: 'description',
                title: 'Opportunity',
                render: (value, item) => (
                  <div className="flex items-center">
                    <span>{value}</span>
                    {alerts.some(alert => 
                      alert.metadata.gameId === item.gameId
                    ) && (
                      <Badge variant="warning" className="ml-2">
                        Alert
                      </Badge>
                    )}
                  </div>
                )
              },
              {
                key: 'confidence',
                title: 'Confidence',
                render: (value) => (
                  <div className="w-32">
                    <Progress
                      value={value * 100}
                      max={100}
                      variant={value >= 0.8 ? 'success' : 'warning'}
                      showValue
                      size="sm"
                    />
                  </div>
                )
              },
              {
                key: 'expectedValue',
                title: 'Expected Value',
                render: (value) => (
                  <span className={value > 0 ? 'text-green-600' : 'text-red-600'}>
                    {value > 0 ? '+' : ''}{(value * 100).toFixed(1)}%
                  </span>
                )
              }
            ]}
            onRowClick={handleOpportunityClick}
            emptyMessage="No opportunities match your criteria"
            sortKey={sortField}
            sortDirection={sortDirection}
            onSort={(key) => {
              if (key === sortField) {
                setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
              } else {
                setSortField(key);
                setSortDirection('desc');
              }
            }}
          />
        </div>
      </Card>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  TableSortLabel,
  Chip,
  IconButton,
  TextField,
  MenuItem,
  Grid,
  Paper,
  Tooltip,
  CircularProgress,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import {
  TrendingUp as TrendingUpIcon,
  TrendingDown as TrendingDownIcon,
  FilterList as FilterListIcon,
  Info as InfoIcon,
} from '@mui/icons-material';
import { riskManagement } from '@/services/riskManagement';

const HistoryCard = styled(Card)(({ theme }) => ({
  background: 'rgba(255, 255, 255, 0.9)',
  backdropFilter: 'blur(10px)',
  border: '1px solid rgba(255, 255, 255, 0.2)',
  transition: 'all 0.3s ease',
  '&:hover': {
    transform: 'translateY(-2px)',
    boxShadow: theme.shadows[4],
  },
}));

interface Bet {
  id: string;
  recommendationId: string;
  amount: number;
  type: 'straight' | 'parlay' | 'teaser';
  odds: number;
  timestamp: number;
  status: 'pending' | 'won' | 'lost';
  payout?: number;
}

type Order = 'asc' | 'desc';

interface HeadCell {
  id: keyof Bet;
  label: string;
  numeric: boolean;
}

const headCells: HeadCell[] = [
  { id: 'timestamp', label: 'Date', numeric: false },
  { id: 'type', label: 'Type', numeric: false },
  { id: 'recommendationId', label: 'Recommendation', numeric: false },
  { id: 'odds', label: 'Odds', numeric: true },
  { id: 'amount', label: 'Amount', numeric: true },
  { id: 'payout', label: 'Payout', numeric: true },
  { id: 'status', label: 'Status', numeric: false },
];

const filterOptions = {
  type: ['Single', 'Parlay', 'Teaser', 'Prop'],
  status: ['pending', 'won', 'lost'] as const,
};

export const BettingHistory: React.FC = () => {
  const [bets, setBets] = useState<Bet[]>([]);
  const [loading, setLoading] = useState(true);
  const [order, setOrder] = useState<Order>('desc');
  const [orderBy, setOrderBy] = useState<keyof Bet>('timestamp');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [filters, setFilters] = useState({
    type: '',
    status: '',
  });

  useEffect(() => {
    const loadBets = async () => {
      setLoading(true);
      try {
        const userBets = riskManagement.getBets();
        setBets(userBets);
      } catch (error) {
        console.error('Error loading bets:', error);
      } finally {
        setLoading(false);
      }
    };

    loadBets();
  }, []);

  const handleRequestSort = (property: keyof Bet) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleChangePage = (event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleFilterChange = (field: string, value: string) => {
    setFilters(prev => ({
      ...prev,
      [field]: value,
    }));
  };

  const getStatusColor = (status: Bet['status']) => {
    switch (status) {
      case 'won':
        return 'success';
      case 'lost':
        return 'error';
      default:
        return 'default';
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
    }).format(amount);
  };

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString();
  };

  const filteredBets = bets.filter(bet => {
    return (
      (filters.type === '' || bet.type === filters.type) &&
      (filters.status === '' || bet.status === filters.status)
    );
  });

  const sortedBets = filteredBets.sort((a, b) => {
    const isAsc = order === 'asc';
    if (orderBy === 'timestamp') {
      return isAsc
        ? a.timestamp - b.timestamp
        : b.timestamp - a.timestamp;
    }
    if (orderBy === 'odds' || orderBy === 'amount' || orderBy === 'payout') {
      return isAsc
        ? (a[orderBy] || 0) - (b[orderBy] || 0)
        : (b[orderBy] || 0) - (a[orderBy] || 0);
    }
    return isAsc
      ? String(a[orderBy]).localeCompare(String(b[orderBy]))
      : String(b[orderBy]).localeCompare(String(a[orderBy]));
  });

  const paginatedBets = sortedBets.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  const winRate = filteredBets.length > 0
    ? (filteredBets.filter(bet => bet.status === 'won').length / filteredBets.length) * 100
    : 0;

  const totalAmount = filteredBets.reduce((sum, bet) => sum + bet.amount, 0);
  const totalPayout = filteredBets.reduce((sum, bet) => sum + (bet.payout || 0), 0);

  return (
    <Box sx={{ width: '100%' }}>
      <HistoryCard>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Betting History
          </Typography>

          {/* Filters */}
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid item xs={12} sm={6} md={3}>
              <TextField
                select
                fullWidth
                label="Bet Type"
                value={filters.type}
                onChange={(e) => handleFilterChange('type', e.target.value)}
              >
                <MenuItem value="">All</MenuItem>
                {filterOptions.type.map((type) => (
                  <MenuItem key={type} value={type}>
                    {type}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <TextField
                select
                fullWidth
                label="Status"
                value={filters.status}
                onChange={(e) => handleFilterChange('status', e.target.value)}
              >
                <MenuItem value="">All</MenuItem>
                {filterOptions.status.map((status) => (
                  <MenuItem key={status} value={status}>
                    {status.charAt(0).toUpperCase() + status.slice(1)}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
          </Grid>

          {/* Summary Stats */}
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid item xs={12} sm={6} md={3}>
              <Paper elevation={0} sx={{ p: 2, bgcolor: 'background.default' }}>
                <Typography variant="subtitle2" color="textSecondary">
                  Total Bets
                </Typography>
                <Typography variant="h6">
                  {filteredBets.length}
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Paper elevation={0} sx={{ p: 2, bgcolor: 'background.default' }}>
                <Typography variant="subtitle2" color="textSecondary">
                  Win Rate
                </Typography>
                <Typography variant="h6">
                  {winRate.toFixed(1)}%
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Paper elevation={0} sx={{ p: 2, bgcolor: 'background.default' }}>
                <Typography variant="subtitle2" color="textSecondary">
                  Total Amount
                </Typography>
                <Typography variant="h6">
                  {formatCurrency(totalAmount)}
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Paper elevation={0} sx={{ p: 2, bgcolor: 'background.default' }}>
                <Typography variant="subtitle2" color="textSecondary">
                  Total Payout
                </Typography>
                <Typography variant="h6">
                  {formatCurrency(totalPayout)}
                </Typography>
              </Paper>
            </Grid>
          </Grid>

          {/* Betting History Table */}
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  {headCells.map((headCell) => (
                    <TableCell
                      key={headCell.id}
                      align={headCell.numeric ? 'right' : 'left'}
                      sortDirection={orderBy === headCell.id ? order : false}
                    >
                      <TableSortLabel
                        active={orderBy === headCell.id}
                        direction={orderBy === headCell.id ? order : 'asc'}
                        onClick={() => handleRequestSort(headCell.id)}
                      >
                        {headCell.label}
                      </TableSortLabel>
                    </TableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={headCells.length} align="center">
                      <CircularProgress />
                    </TableCell>
                  </TableRow>
                ) : paginatedBets.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={headCells.length} align="center">
                      No bets found
                    </TableCell>
                  </TableRow>
                ) : (
                  paginatedBets.map((bet) => (
                    <TableRow key={bet.id}>
                      <TableCell>{formatDate(bet.timestamp)}</TableCell>
                      <TableCell>{bet.type}</TableCell>
                      <TableCell>{bet.recommendationId}</TableCell>
                      <TableCell align="right">{bet.odds}</TableCell>
                      <TableCell align="right">{formatCurrency(bet.amount)}</TableCell>
                      <TableCell align="right">
                        {bet.payout ? formatCurrency(bet.payout) : '-'}
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={bet.status.charAt(0).toUpperCase() + bet.status.slice(1)}
                          color={getStatusColor(bet.status)}
                          size="small"
                        />
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <TablePagination
            rowsPerPageOptions={[5, 10, 25]}
            component="div"
            count={filteredBets.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </CardContent>
      </HistoryCard>
    </Box>
  );
};

import React from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Chip,
  LinearProgress,
  Skeleton,
  Alert,
} from '@mui/material';
import { formatCurrency, formatPercentage } from '@/utils/formatters';
import { BetRecommendation } from '@/types';

interface BettingOpportunitiesProps {
  opportunities: BetRecommendation[];
  onBetPlacement: (recommendation: BetRecommendation) => void;
  alerts: Array<{
    type: string;
    severity: string;
    message: string;
    metadata: any;
  }>;
  isLoading: boolean;
}

export const BettingOpportunities: React.FC<BettingOpportunitiesProps> = ({
  opportunities,
  onBetPlacement,
  alerts,
  isLoading,
}) => {
  if (isLoading) {
    return (
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: '1fr',
            sm: 'repeat(2, 1fr)',
            md: 'repeat(3, 1fr)',
          },
          gap: 2,
        }}
      >
        {[1, 2, 3].map(index => (
          <Card key={index}>
            <CardContent>
              <Skeleton variant="text" width="60%" />
              <Skeleton height={100} sx={{ mt: 2 }} variant="rectangular" />
            </CardContent>
          </Card>
        ))}
      </Box>
    );
  }

  if (opportunities.length === 0) {
    return (
      <Alert severity="info">
        No betting opportunities available at the moment. Please check back later.
      </Alert>
    );
  }

  return (
    <Box>
      {alerts.length > 0 && (
        <Alert severity="warning" sx={{ mb: 3 }}>
          {alerts.length} active alert{alerts.length === 1 ? '' : 's'} require your attention
        </Alert>
      )}

      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: '1fr',
            sm: 'repeat(2, 1fr)',
            md: 'repeat(3, 1fr)',
          },
          gap: 2,
        }}
      >
        {opportunities.map((opportunity, index) => {
          const hasAlert = alerts.some(alert => alert.metadata?.gameId === opportunity.event_id);

          return (
            <Card
              key={index}
              sx={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                position: 'relative',
              }}
            >
              {hasAlert && (
                <Chip
                  color="warning"
                  label="Alert"
                  size="small"
                  sx={{
                    position: 'absolute',
                    top: 8,
                    right: 8,
                  }}
                />
              )}
              <CardContent>
                <Typography gutterBottom variant="h6">
                  {opportunity.event_id}
                </Typography>

                <Box sx={{ mb: 2 }}>
                  <Typography gutterBottom color="text.secondary" variant="body2">
                    Confidence
                  </Typography>
                  <LinearProgress
                    color={opportunity.confidence_score >= 0.8 ? 'success' : 'warning'}
                    sx={{ height: 8, borderRadius: 4 }}
                    value={opportunity.confidence_score * 100}
                    variant="determinate"
                  />
                  <Typography color="text.secondary" sx={{ mt: 0.5 }} variant="body2">
                    {formatPercentage(opportunity.confidence_score)}
                  </Typography>
                </Box>

                <Box sx={{ mb: 2 }}>
                  <Typography color="text.secondary" variant="body2">
                    Expected ROI: {formatPercentage(opportunity.expected_roi)}
                  </Typography>
                  <Typography color="text.secondary" variant="body2">
                    Recommended Stake: {formatCurrency(opportunity.recommended_stake)}
                  </Typography>
                </Box>

                <Button
                  fullWidth
                  color="primary"
                  disabled={hasAlert}
                  variant="contained"
                  onClick={() => onBetPlacement(opportunity)}
                >
                  Place Bet
                </Button>
              </CardContent>
            </Card>
          );
        })}
      </Box>
    </Box>
  );
};

import React from 'react';
import {
  Card,
  CardContent,
  Typography,
  Grid,
  Button,
  Chip,
  Box,
  LinearProgress,
  Tooltip,
} from '@mui/material';
import { bankrollService } from '@/services/bankroll';
import { notificationService } from '@/services/notification';

interface BettingOpportunityProps {
  opportunity: {
    id: string;
    event: {
      homeTeam: string;
      awayTeam: string;
      startTime: string;
      sport: string;
    };
    market: string;
    selection: string;
    odds: number;
    probability: number;
    edge: number;
    confidence: number;
    volume: number;
    sentiment?: {
      score: number;
      volume: number;
    };
    stats?: {
      homeTeam: any;
      awayTeam: any;
    };
    arbitrage?: {
      roi: number;
      bookmakers: string[];
    };
  };
  onPlaceBet: (opportunity: any) => void;
}

export const BettingOpportunity: React.FC<BettingOpportunityProps> = ({
  opportunity,
  onPlaceBet,
}) => {
  const {
    event,
    market,
    selection,
    odds,
    probability,
    edge,
    confidence,
    volume,
    sentiment,
    stats,
    arbitrage,
  } = opportunity;

  const handlePlaceBet = () => {
    const maxBetAmount = bankrollService.getMaxBetAmount();
    const recommendedStake = Math.min(
      maxBetAmount,
      bankrollService.getBalance() * (edge / 100)
    );

    onPlaceBet({
      ...opportunity,
      stake: recommendedStake,
    });

    notificationService.notify(
      'success',
      'Bet Placed',
      `Placed bet of $${recommendedStake.toFixed(2)} on ${selection}`,
      opportunity
    );
  };

  const getConfidenceColor = (value: number) => {
    if (value >= 0.8) return 'success';
    if (value >= 0.6) return 'primary';
    if (value >= 0.4) return 'warning';
    return 'error';
  };

  const getEdgeColor = (value: number) => {
    if (value >= 10) return 'success';
    if (value >= 5) return 'primary';
    if (value >= 2) return 'warning';
    return 'error';
  };

  return (
    <Card>
      <CardContent>
        <Grid container spacing={2}>
          {/* Event Information */}
          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom>
              {event.homeTeam} vs {event.awayTeam}
            </Typography>
            <Typography variant="body2" color="textSecondary">
              {new Date(event.startTime).toLocaleString()}
            </Typography>
            <Chip
              label={event.sport}
              size="small"
              sx={{ mt: 1 }}
            />
          </Grid>

          {/* Market and Selection */}
          <Grid item xs={12}>
            <Typography variant="subtitle1">
              {market}
            </Typography>
            <Typography variant="h5" color="primary">
              {selection}
            </Typography>
          </Grid>

          {/* Odds and Probability */}
          <Grid item xs={6}>
            <Typography variant="body2" color="textSecondary">
              Odds
            </Typography>
            <Typography variant="h6">
              {odds.toFixed(2)}
            </Typography>
          </Grid>
          <Grid item xs={6}>
            <Typography variant="body2" color="textSecondary">
              Probability
            </Typography>
            <Typography variant="h6">
              {(probability * 100).toFixed(1)}%
            </Typography>
          </Grid>

          {/* Edge and Confidence */}
          <Grid item xs={12}>
            <Box mb={1}>
              <Typography variant="body2" color="textSecondary">
                Edge
              </Typography>
              <Tooltip title={`${edge.toFixed(2)}% advantage over bookmaker odds`}>
                <Chip
                  label={`${edge.toFixed(2)}%`}
                  color={getEdgeColor(edge) as any}
                  size="small"
                />
              </Tooltip>
            </Box>
            <Box>
              <Typography variant="body2" color="textSecondary">
                Confidence
              </Typography>
              <Tooltip title={`${(confidence * 100).toFixed(1)}% confidence in this prediction`}>
                <Chip
                  label={`${(confidence * 100).toFixed(1)}%`}
                  color={getConfidenceColor(confidence) as any}
                  size="small"
                />
              </Tooltip>
            </Box>
          </Grid>

          {/* Sentiment Analysis */}
          {sentiment && (
            <Grid item xs={12}>
              <Typography variant="body2" color="textSecondary" gutterBottom>
                Sentiment Analysis
              </Typography>
              <Box display="flex" alignItems="center" gap={1}>
                <LinearProgress
                  variant="determinate"
                  value={sentiment.score * 100}
                  sx={{ flexGrow: 1 }}
                />
                <Typography variant="body2">
                  {sentiment.score.toFixed(2)}
                </Typography>
              </Box>
              <Typography variant="caption" color="textSecondary">
                Volume: {sentiment.volume}
              </Typography>
            </Grid>
          )}

          {/* Statistical Analysis */}
          {stats && (
            <Grid item xs={12}>
              <Typography variant="body2" color="textSecondary" gutterBottom>
                Statistical Analysis
              </Typography>
              <Grid container spacing={1}>
                <Grid item xs={6}>
                  <Typography variant="caption">
                    {event.homeTeam}
                  </Typography>
                  <Typography variant="body2">
                    {Object.entries(stats.homeTeam)
                      .map(([key, value]) => `${key}: ${value}`)
                      .join(', ')}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="caption">
                    {event.awayTeam}
                  </Typography>
                  <Typography variant="body2">
                    {Object.entries(stats.awayTeam)
                      .map(([key, value]) => `${key}: ${value}`)
                      .join(', ')}
                  </Typography>
                </Grid>
              </Grid>
            </Grid>
          )}

          {/* Arbitrage Information */}
          {arbitrage && (
            <Grid item xs={12}>
              <Typography variant="body2" color="textSecondary" gutterBottom>
                Arbitrage Opportunity
              </Typography>
              <Typography variant="body2">
                ROI: {arbitrage.roi.toFixed(2)}%
              </Typography>
              <Typography variant="caption" color="textSecondary">
                Bookmakers: {arbitrage.bookmakers.join(', ')}
              </Typography>
            </Grid>
          )}

          {/* Action Button */}
          <Grid item xs={12}>
            <Button
              variant="contained"
              color="primary"
              fullWidth
              onClick={handlePlaceBet}
              disabled={!bankrollService.getBalance()}
            >
              Place Bet
            </Button>
          </Grid>
        </Grid>
      </CardContent>
    </Card>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  Button,
  Chip,
  IconButton,
  Tooltip,
  LinearProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import {
  TrendingUp as TrendingUpIcon,
  TrendingDown as TrendingDownIcon,
  Star as StarIcon,
  StarBorder as StarBorderIcon,
  Info as InfoIcon,
  AttachMoney as MoneyIcon,
} from '@mui/icons-material';
import { styled } from '@mui/material/styles';
import { sportsAnalytics } from '@/services/sportsAnalytics';
import { riskManagement } from '@/services/riskManagement';
import { Sport } from '@/services/sportsAnalytics';

const RecommendationsCard = styled(Card)(({ theme }) => ({
  background: 'rgba(255, 255, 255, 0.9)',
  backdropFilter: 'blur(10px)',
  border: '1px solid rgba(255, 255, 255, 0.2)',
  transition: 'all 0.3s ease',
  '&:hover': {
    transform: 'translateY(-2px)',
    boxShadow: theme.shadows[4],
  },
}));

interface Recommendation {
  id: string;
  sport: Sport;
  event: string;
  betType: string;
  odds: number;
  confidence: number;
  edge: number;
  analysis: string;
  risk: 'low' | 'medium' | 'high';
  timestamp: number;
  favorite: boolean;
}

export const BettingRecommendations: React.FC<{ sport: Sport }> = ({ sport }) => {
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [selectedRecommendation, setSelectedRecommendation] = useState<Recommendation | null>(null);
  const [betDialogOpen, setBetDialogOpen] = useState(false);
  const [betAmount, setBetAmount] = useState('');
  const [betType, setBetType] = useState('straight');

  useEffect(() => {
    const loadRecommendations = async () => {
      const sportRecommendations = await sportsAnalytics.getRecommendations(sport);
      setRecommendations(sportRecommendations);
    };

    loadRecommendations();
    const unsubscribe = sportsAnalytics.subscribe('recommendations', (data) => {
      setRecommendations(prev => [data, ...prev].slice(0, 10));
    });

    return () => {
      unsubscribe();
    };
  }, [sport]);

  const handleBetClick = (recommendation: Recommendation) => {
    setSelectedRecommendation(recommendation);
    setBetDialogOpen(true);
  };

  const handlePlaceBet = () => {
    if (selectedRecommendation && betAmount) {
      const amount = parseFloat(betAmount);
      riskManagement.placeBet({
        recommendationId: selectedRecommendation.id,
        amount,
        type: betType,
        odds: selectedRecommendation.odds,
      });
      setBetDialogOpen(false);
      setBetAmount('');
    }
  };

  const toggleFavorite = (recommendationId: string) => {
    setRecommendations(prev =>
      prev.map(rec =>
        rec.id === recommendationId
          ? { ...rec, favorite: !rec.favorite }
          : rec
      )
    );
  };

  const getRiskColor = (risk: string) => {
    switch (risk) {
      case 'low':
        return 'success';
      case 'medium':
        return 'warning';
      case 'high':
        return 'error';
      default:
        return 'default';
    }
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 80) return 'success';
    if (confidence >= 60) return 'warning';
    return 'error';
  };

  return (
    <>
      <RecommendationsCard>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Betting Recommendations
          </Typography>

          <Grid container spacing={2}>
            {recommendations.map((recommendation) => (
              <Grid item xs={12} key={recommendation.id}>
                <Box
                  sx={{
                    p: 2,
                    border: '1px solid',
                    borderColor: 'divider',
                    borderRadius: 1,
                    position: 'relative',
                  }}
                >
                  <Box display="flex" justifyContent="space-between" alignItems="flex-start">
                    <Box>
                      <Typography variant="subtitle1">
                        {recommendation.event}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {recommendation.betType}
                      </Typography>
                    </Box>
                    <Box display="flex" gap={1}>
                      <Chip
                        size="small"
                        label={`${recommendation.odds}x`}
                        color="primary"
                      />
                      <Chip
                        size="small"
                        label={`${recommendation.confidence}% confidence`}
                        color={getConfidenceColor(recommendation.confidence)}
                      />
                      <Chip
                        size="small"
                        label={recommendation.risk.toUpperCase()}
                        color={getRiskColor(recommendation.risk)}
                      />
                      <IconButton
                        size="small"
                        onClick={() => toggleFavorite(recommendation.id)}
                      >
                        {recommendation.favorite ? (
                          <StarIcon color="warning" />
                        ) : (
                          <StarBorderIcon />
                        )}
                      </IconButton>
                    </Box>
                  </Box>

                  <Box mt={1}>
                    <Typography variant="body2" color="textSecondary">
                      Edge: {recommendation.edge.toFixed(2)}%
                    </Typography>
                    <LinearProgress
                      variant="determinate"
                      value={recommendation.confidence}
                      sx={{
                        height: 4,
                        mt: 1,
                        bgcolor: 'grey.200',
                        '& .MuiLinearProgress-bar': {
                          bgcolor: getConfidenceColor(recommendation.confidence),
                        },
                      }}
                    />
                  </Box>

                  <Box mt={2}>
                    <Typography variant="body2">
                      {recommendation.analysis}
                    </Typography>
                  </Box>

                  <Box mt={2} display="flex" justifyContent="flex-end">
                    <Button
                      variant="contained"
                      color="primary"
                      startIcon={<MoneyIcon />}
                      onClick={() => handleBetClick(recommendation)}
                    >
                      Place Bet
                    </Button>
                  </Box>
                </Box>
              </Grid>
            ))}
          </Grid>
        </CardContent>
      </RecommendationsCard>

      <Dialog open={betDialogOpen} onClose={() => setBetDialogOpen(false)}>
        <DialogTitle>Place Bet</DialogTitle>
        <DialogContent>
          {selectedRecommendation && (
            <Box sx={{ pt: 2 }}>
              <Typography variant="subtitle1" gutterBottom>
                {selectedRecommendation.event}
              </Typography>
              <Typography variant="body2" color="textSecondary" gutterBottom>
                {selectedRecommendation.betType} @ {selectedRecommendation.odds}x
              </Typography>

              <FormControl fullWidth sx={{ mt: 2 }}>
                <InputLabel>Bet Type</InputLabel>
                <Select
                  value={betType}
                  label="Bet Type"
                  onChange={(e) => setBetType(e.target.value)}
                >
                  <MenuItem value="straight">Straight Bet</MenuItem>
                  <MenuItem value="parlay">Parlay</MenuItem>
                  <MenuItem value="teaser">Teaser</MenuItem>
                </Select>
              </FormControl>

              <TextField
                fullWidth
                label="Bet Amount"
                type="number"
                value={betAmount}
                onChange={(e) => setBetAmount(e.target.value)}
                sx={{ mt: 2 }}
                InputProps={{
                  startAdornment: <MoneyIcon color="action" />,
                }}
              />

              <Box mt={2}>
                <Typography variant="body2" color="textSecondary">
                  Potential Payout: ${selectedRecommendation.odds * (parseFloat(betAmount) || 0)}
                </Typography>
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setBetDialogOpen(false)}>Cancel</Button>
          <Button
            variant="contained"
            color="primary"
            onClick={handlePlaceBet}
            disabled={!betAmount || parseFloat(betAmount) <= 0}
          >
            Confirm Bet
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

import React, { useEffect, useState } from 'react';
import { GeneralInsight } from '../services/predictionService';
import { ML_CONFIG } from '../config/constants';
import { usePrediction } from '../hooks/usePrediction';


interface PredictionDisplayProps {
    propId?: string;
    initialFeatures?: { [key: string]: number };
    context?: { [key: string]: any };
}

interface FeatureContribution {
    name: string;
    value: number;
    importance: number;
}

export const PredictionDisplay: React.FC<PredictionDisplayProps> = ({
    propId,
    initialFeatures,
    context
}) => {
    const { makePrediction, getInsights, isLoading, error, lastPrediction } = usePrediction();
    const [insights, setInsights] = useState<GeneralInsight[]>([]);
    const [features, setFeatures] = useState<{ [key: string]: number }>(
        initialFeatures || {
            player_points: 0,
            team_points: 0,
            opponent_points: 0,
            minutes_played: 0,
            home_game: 0,
            days_rest: 0
        }
    );
    const [featureContributions, setFeatureContributions] = useState<FeatureContribution[]>([]);
    const [showAdvancedMetrics, setShowAdvancedMetrics] = useState(false);

    useEffect(() => {
        const loadInsights = async () => {
            try {
                const data = await getInsights();
                setInsights(data);
            } catch (err) {
                console.error('Failed to load insights:', err);
            }
        };
        loadInsights();
    }, [getInsights]);

    const handleFeatureChange = (key: string, value: number) => {
        setFeatures(prev => ({
            ...prev,
            [key]: value
        }));
    };

    const handlePredict = async () => {
        try {
            const response = await makePrediction(features, propId, context);
            if (response.insights?.feature_contributions) {
                const contributions = Object.entries(response.insights.feature_contributions)
                    .map(([name, importance]) => ({
                        name,
                        value: features[name],
                        importance: importance as number
                    }))
                    .sort((a, b) => b.importance - a.importance);
                setFeatureContributions(contributions);
            }
        } catch (err) {
            console.error('Prediction failed:', err);
        }
    };

    const getConfidenceColor = (confidence: number) => {
        if (confidence >= 0.8) return 'text-green-600';
        if (confidence >= 0.6) return 'text-yellow-600';
        return 'text-red-600';
    };

    return (
        <div className="p-6 bg-white rounded-lg shadow-lg">
            <h2 className="text-2xl font-bold mb-6 text-gray-800">ML Prediction</h2>
            
            {/* Feature Inputs */}
            <div className="grid grid-cols-2 gap-4 mb-6">
                {Object.entries(features).map(([key, value]) => (
                    <div key={key} className="flex flex-col">
                        <label className="text-sm font-medium text-gray-700 mb-1">
                            {key.replace(/_/g, ' ').toUpperCase()}
                        </label>
                        <input
                            type="number"
                            value={value}
                            onChange={(e) => handleFeatureChange(key, parseFloat(e.target.value))}
                            className="border rounded px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                        />
                    </div>
                ))}
            </div>

            {/* Predict Button */}
            <button
                onClick={handlePredict}
                disabled={isLoading}
                className="w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors duration-200 font-medium"
            >
                {isLoading ? (
                    <span className="flex items-center justify-center">
                        <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Predicting...
                    </span>
                ) : 'Make Prediction'}
            </button>

            {/* Error Display */}
            {error && (
                <div className="mt-4 p-4 bg-red-50 border-l-4 border-red-500 text-red-700 rounded">
                    <p className="font-medium">Error</p>
                    <p>{error.message}</p>
                </div>
            )}

            {/* Last Prediction */}
            {lastPrediction && (
                <div className="mt-6 p-4 bg-gray-50 rounded-lg border border-gray-200">
                    <h3 className="font-semibold mb-3 text-gray-800">Prediction Result</h3>
                    <div className="space-y-2">
                        <p className="text-lg">
                            Outcome: <span className="font-medium">{lastPrediction.predictedOutcome}</span>
                        </p>
                        {lastPrediction.confidence && (
                            <p className={`text-lg ${getConfidenceColor(lastPrediction.confidence)}`}>
                                Confidence: {(lastPrediction.confidence * 100).toFixed(1)}%
                            </p>
                        )}
                    </div>

                    {/* Feature Contributions */}
                    {featureContributions.length > 0 && (
                        <div className="mt-4">
                            <h4 className="font-medium mb-2 text-gray-700">Feature Importance</h4>
                            <div className="space-y-2">
                                {featureContributions.map(({ name, value, importance }) => (
                                    <div key={name} className="flex items-center">
                                        <div className="w-32 text-sm text-gray-600">
                                            {name.replace(/_/g, ' ')}
                                        </div>
                                        <div className="flex-1 h-2 bg-gray-200 rounded-full overflow-hidden">
                                            <div
                                                className="h-full bg-blue-500"
                                                style={{ width: `${importance * 100}%` }}
                                            />
                                        </div>
                                        <div className="w-16 text-right text-sm text-gray-600">
                                            {(importance * 100).toFixed(1)}%
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Advanced Metrics Toggle */}
                    <button
                        onClick={() => setShowAdvancedMetrics(!showAdvancedMetrics)}
                        className="mt-4 text-sm text-blue-600 hover:text-blue-800"
                    >
                        {showAdvancedMetrics ? 'Hide' : 'Show'} Advanced Metrics
                    </button>

                    {/* Advanced Metrics */}
                    {showAdvancedMetrics && lastPrediction.insights?.model_metrics && (
                        <div className="mt-4 p-3 bg-gray-100 rounded">
                            <h4 className="font-medium mb-2 text-gray-700">Model Performance</h4>
                            <div className="grid grid-cols-2 gap-2 text-sm">
                                {Object.entries(lastPrediction.insights.model_metrics)
                                    .filter(([key]) => !key.includes('confusion_matrix'))
                                    .map(([key, value]) => (
                                        <div key={key} className="flex justify-between">
                                            <span className="text-gray-600">{key}:</span>
                                            <span className="font-medium">{(value as number).toFixed(3)}</span>
                                        </div>
                                    ))}
                            </div>
                        </div>
                    )}
                </div>
            )}

            {/* Insights */}
            {insights.length > 0 && (
                <div className="mt-6">
                    <h3 className="font-semibold mb-3 text-gray-800">ML Insights</h3>
                    <div className="space-y-3">
                        {insights.map(insight => (
                            <div
                                key={insight.id}
                                className="p-4 bg-gray-50 rounded-lg border-l-4 border-blue-500 hover:bg-gray-100 transition-colors duration-200"
                            >
                                <p className="text-sm text-gray-700">{insight.text}</p>
                                {insight.confidence && (
                                    <div className="mt-2 flex items-center justify-between">
                                        <span className="text-xs text-gray-500">
                                            Source: {insight.source}
                                        </span>
                                        <span className="text-xs text-gray-500">
                                            Confidence: {(insight.confidence * 100).toFixed(1)}%
                                        </span>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  LinearProgress,
  Tooltip,
  IconButton,
  Chip,
  Button,
  Collapse,
  Alert,
  CircularProgress,
} from '@mui/material';
import {
  TrendingUp as TrendingUpIcon,
  TrendingDown as TrendingDownIcon,
  Info as InfoIcon,
  Warning as WarningIcon,
  CheckCircle as CheckCircleIcon,
  Error as ErrorIcon,
  Refresh as RefreshIcon,
} from '@mui/icons-material';
import { formatPercentage, formatCurrency } from '../utils/formatters';
import { debounce } from 'lodash';
import type { ModelPrediction } from '../types/prediction';

interface PredictionEnhancementProps {
  predictions: ModelPrediction[];
  onStakeOptimize: (prediction: ModelPrediction) => void;
  riskProfile: 'conservative' | 'moderate' | 'aggressive';
  bankroll: number;
  onRefresh?: () => Promise<void>;
  autoRefresh?: boolean;
  refreshInterval?: number;
}

const PredictionEnhancement: React.FC<PredictionEnhancementProps> = ({
  predictions,
  onStakeOptimize,
  riskProfile,
  bankroll,
  onRefresh,
  autoRefresh = false,
  refreshInterval = 30000,
}) => {
  const [selectedPrediction, setSelectedPrediction] = useState<ModelPrediction | null>(null);
  const [showDetails, setShowDetails] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Memoize confidence level calculation
  const getConfidenceLevel = useCallback((confidence: number) => {
    if (confidence >= 0.9) return { label: 'Safe', color: 'success' as const };
    if (confidence >= 0.7) return { label: 'Medium', color: 'warning' as const };
    return { label: 'Risky', color: 'error' as const };
  }, []);

  // Memoize Kelly stake calculation
  const calculateKellyStake = useCallback(
    (prediction: ModelPrediction) => {
      const { confidence, prediction: odds } = prediction;
      const q = 1 - confidence;
      const b = odds - 1;
      const kelly = (b * confidence - q) / b;

      const riskMultiplier = {
        conservative: 0.25,
        moderate: 0.5,
        aggressive: 0.75,
      }[riskProfile];

      return Math.max(0, Math.min(kelly * riskMultiplier * bankroll, bankroll * 0.1));
    },
    [riskProfile, bankroll]
  );

  // Debounced refresh handler
  const debouncedRefresh = useMemo(
    () =>
      debounce(async () => {
        if (!onRefresh) return;
        try {
          setIsRefreshing(true);
          setError(null);
          await onRefresh();
        } catch (err) {
          setError(err instanceof Error ? err.message : 'Failed to refresh predictions');
        } finally {
          setIsRefreshing(false);
        }
      }, 1000),
    [onRefresh]
  );

  // Auto-refresh effect
  useEffect(() => {
    if (!autoRefresh || !onRefresh) return;

    const interval = setInterval(debouncedRefresh, refreshInterval);
    return () => clearInterval(interval);
  }, [autoRefresh, onRefresh, refreshInterval, debouncedRefresh]);

  // Memoize sorted predictions
  const sortedPredictions = useMemo(() => {
    return [...predictions].sort((a, b) => b.confidence - a.confidence);
  }, [predictions]);

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5">
          Enhanced Predictions
