                />
              </div>
              <div className="flex justify-between items-center mt-2 text-blue-200 text-xs">
                <span>Stake: <span className="font-bold text-green-300">${entry.stake}</span></span>
                <span>Payout: <span className="font-bold text-yellow-300">${entry.payout}</span></span>
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
};

export default EntryTracking;

import React, { useState } from 'react';
import { motion } from 'framer-motion';

export interface BankrollManagerProps {
  userId: string;
}

const BankrollManager: React.FC<BankrollManagerProps> = ({ userId }) => {
  const [bankroll, setBankroll] = useState(1000);
  const [riskLevel, setRiskLevel] = useState(0.02); // 2% default risk per bet

  const recommendedStake = bankroll * riskLevel;
  const maxDailyRisk = bankroll * 0.1; // 10% max daily risk
  const stopLoss = bankroll * 0.05; // 5% stop loss

  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold mb-4">Bankroll Management</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <motion.div
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg p-4 shadow-sm"
          initial={{ opacity: 0, y: 20 }}
        >
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Current Bankroll ($)
            </label>
            <input
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              type="number"
              value={bankroll}
              onChange={e => setBankroll(Math.max(0, Number(e.target.value)))}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Risk Level (% per bet)
            </label>
            <input
              className="w-full"
              max={0.1}
              min={0.01}
              step={0.01}
              type="range"
              value={riskLevel}
              onChange={e => setRiskLevel(Number(e.target.value))}
            />
            <div className="text-sm text-gray-600 mt-1">
              {(riskLevel * 100).toFixed(1)}% per bet
            </div>
          </div>
        </motion.div>

        <motion.div
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg p-4 shadow-sm"
          initial={{ opacity: 0, y: 20 }}
          transition={{ delay: 0.1 }}
        >
          <h4 className="font-medium mb-4">Recommendations</h4>
          <div className="space-y-3">
            <div>
              <div className="text-sm text-gray-600">Recommended Stake</div>
              <div className="text-xl font-bold text-blue-600">${recommendedStake.toFixed(2)}</div>
            </div>
            <div>
              <div className="text-sm text-gray-600">Max Daily Risk</div>
              <div className="text-xl font-bold text-blue-600">${maxDailyRisk.toFixed(2)}</div>
            </div>
            <div>
              <div className="text-sm text-gray-600">Stop Loss</div>
              <div className="text-xl font-bold text-red-600">${stopLoss.toFixed(2)}</div>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default React.memo(BankrollManager);

import React from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  LinearProgress,
  Chip,
  Tooltip,
  IconButton,
} from '@mui/material';
import {
  TrendingUp as TrendingUpIcon,
  TrendingDown as TrendingDownIcon,
  AccountBalance as BankrollIcon,
  EmojiEvents as TrophyIcon,
  Timeline as TimelineIcon,
  Warning as WarningIcon,
} from '@mui/icons-material';
import { styled } from '@mui/material/styles';
import { riskManagement } from '@/services/riskManagement';

const MetricsCard = styled(Card)(({ theme }) => ({
  background: 'rgba(255, 255, 255, 0.9)',
  backdropFilter: 'blur(10px)',
  border: '1px solid rgba(255, 255, 255, 0.2)',
  transition: 'all 0.3s ease',
  '&:hover': {
    transform: 'translateY(-2px)',
    boxShadow: theme.shadows[4],
  },
}));

const ProgressBar = styled(LinearProgress)(({ theme }) => ({
  height: 8,
  borderRadius: 4,
  marginTop: theme.spacing(1),
}));

export const BankrollMetrics: React.FC = () => {
  const bankroll = riskManagement.getBankroll();
  const bets = riskManagement.getBets();

  const calculateWinRate = () => {
    if (bankroll.totalBets === 0) return 0;
    return (bankroll.winningBets / bankroll.totalBets) * 100;
  };

  const getRoiColor = (roi: number) => {
    if (roi >= 10) return 'success.main';
    if (roi >= 0) return 'primary.main';
    return 'error.main';
  };

  const getStreakColor = (streak: number) => {
    if (streak >= 5) return 'success.main';
    if (streak >= 3) return 'primary.main';
    return 'warning.main';
  };

  return (
    <MetricsCard>
      <CardContent>
        <Grid container spacing={3}>
          {/* Header */}
          <Grid item xs={12}>
            <Box display="flex" alignItems="center" gap={1}>
              <BankrollIcon color="primary" />
              <Typography variant="h6">
                Bankroll Metrics
              </Typography>
            </Box>
          </Grid>

          {/* Current Bankroll */}
          <Grid item xs={12} md={6}>
            <Box>
              <Typography variant="subtitle2" color="textSecondary">
                Current Bankroll
              </Typography>
              <Typography variant="h4" color="primary">
                ${bankroll.current.toFixed(2)}
              </Typography>
              <Box display="flex" alignItems="center" gap={1} mt={1}>
                <Typography variant="body2" color="textSecondary">
                  Initial: ${bankroll.initial.toFixed(2)}
                </Typography>
                <Typography
                  variant="body2"
                  color={bankroll.current >= bankroll.initial ? 'success.main' : 'error.main'}
                >
                  {bankroll.current >= bankroll.initial ? (
                    <TrendingUpIcon fontSize="small" />
                  ) : (
                    <TrendingDownIcon fontSize="small" />
                  )}
                  {((bankroll.current - bankroll.initial) / bankroll.initial * 100).toFixed(1)}%
                </Typography>
              </Box>
            </Box>
          </Grid>

          {/* ROI */}
          <Grid item xs={12} md={6}>
            <Box>
              <Typography variant="subtitle2" color="textSecondary">
                Return on Investment
              </Typography>
              <Typography
                variant="h4"
                color={getRoiColor(bankroll.roi)}
              >
                {bankroll.roi.toFixed(1)}%
              </Typography>
              <Box display="flex" alignItems="center" gap={1} mt={1}>
                <Typography variant="body2" color="textSecondary">
                  Total Profit: ${bankroll.totalProfit.toFixed(2)}
                </Typography>
              </Box>
            </Box>
          </Grid>

          {/* Win Rate */}
          <Grid item xs={12} md={6}>
            <Box>
              <Typography variant="subtitle2" color="textSecondary">
                Win Rate
              </Typography>
              <Box display="flex" alignItems="center" gap={1}>
                <Typography variant="h4">
                  {calculateWinRate().toFixed(1)}%
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  ({bankroll.winningBets}/{bankroll.totalBets})
                </Typography>
              </Box>
              <ProgressBar
                variant="determinate"
                value={calculateWinRate()}
                sx={{
                  bgcolor: 'grey.200',
                  '& .MuiLinearProgress-bar': {
                    bgcolor: calculateWinRate() >= 50 ? 'success.main' : 'error.main',
                  },
                }}
              />
            </Box>
          </Grid>

          {/* Streaks */}
          <Grid item xs={12} md={6}>
            <Box>
              <Typography variant="subtitle2" color="textSecondary">
                Current Streak
              </Typography>
              <Box display="flex" alignItems="center" gap={1}>
                <Typography
                  variant="h4"
                  color={getStreakColor(bankroll.currentStreak)}
                >
                  {bankroll.currentStreak}
                </Typography>
                <Chip
                  size="small"
                  label={bankroll.currentStreakType.toUpperCase()}
                  color={bankroll.currentStreakType === 'win' ? 'success' : 'error'}
                />
              </Box>
              <Box display="flex" alignItems="center" gap={2} mt={1}>
                <Tooltip title="Longest Win Streak">
                  <Box display="flex" alignItems="center" gap={0.5}>
                    <TrophyIcon fontSize="small" color="success" />
                    <Typography variant="body2">
                      {bankroll.winStreak}
                    </Typography>
                  </Box>
                </Tooltip>
                <Tooltip title="Longest Loss Streak">
                  <Box display="flex" alignItems="center" gap={0.5}>
                    <WarningIcon fontSize="small" color="error" />
                    <Typography variant="body2">
                      {bankroll.lossStreak}
                    </Typography>
                  </Box>
                </Tooltip>
              </Box>
            </Box>
          </Grid>

          {/* Betting Stats */}
          <Grid item xs={12}>
            <Box
              sx={{
                p: 2,
                bgcolor: 'action.hover',
                borderRadius: 1,
                border: '1px solid',
                borderColor: 'divider',
              }}
            >
              <Typography variant="subtitle1" gutterBottom>
                Betting Statistics
              </Typography>
              <Grid container spacing={2}>
                <Grid item xs={6} sm={3}>
                  <Typography variant="body2" color="textSecondary">
                    Average Bet
                  </Typography>
                  <Typography variant="h6">
                    ${bankroll.averageBetSize.toFixed(2)}
                  </Typography>
                </Grid>
                <Grid item xs={6} sm={3}>
                  <Typography variant="body2" color="textSecondary">
                    Largest Bet
                  </Typography>
                  <Typography variant="h6">
                    ${bankroll.largestBet.toFixed(2)}
                  </Typography>
                </Grid>
                <Grid item xs={6} sm={3}>
                  <Typography variant="body2" color="textSecondary">
                    Largest Win
                  </Typography>
                  <Typography variant="h6" color="success.main">
                    ${bankroll.largestWin.toFixed(2)}
                  </Typography>
                </Grid>
                <Grid item xs={6} sm={3}>
                  <Typography variant="body2" color="textSecondary">
                    Largest Loss
                  </Typography>
                  <Typography variant="h6" color="error.main">
                    ${Math.abs(bankroll.largestLoss).toFixed(2)}
                  </Typography>
                </Grid>
              </Grid>
            </Box>
          </Grid>
        </Grid>
      </CardContent>
    </MetricsCard>
  );
};

import React from 'react';
import {
  Box,
  Typography,
  TextField,
  Slider,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  OutlinedInput,
} from '@mui/material';
import { UserConstraints } from '@/types';

interface UserConstraintsFormProps {
  constraints: UserConstraints;
  onConstraintsChange: (field: keyof UserConstraints, value: any) => void;
}

const SPORTS_OPTIONS = ['NBA', 'NFL', 'MLB', 'NHL', 'Soccer'];
const MARKET_OPTIONS = ['Moneyline', 'Spread', 'Over/Under', 'Props', 'Parlays'];

export const UserConstraintsForm: React.FC<UserConstraintsFormProps> = ({
  constraints,
  onConstraintsChange,
}) => {
  const handleMultiSelectChange = (
    field: 'preferred_sports' | 'preferred_markets',
    value: string[]
  ) => {
    onConstraintsChange(field, value);
  };

  return (
    <Box sx={{ maxWidth: 600, mx: 'auto' }}>
      <Typography gutterBottom variant="h6">
        Betting Constraints
      </Typography>

      <Box sx={{ mt: 3 }}>
        <Typography gutterBottom>Maximum Stake (% of Bankroll)</Typography>
        <Slider
          marks={[
            { value: 1, label: '1%' },
            { value: 25, label: '25%' },
            { value: 50, label: '50%' },
          ]}
          max={50}
          min={1}
          value={constraints.max_bankroll_stake * 100}
          valueLabelDisplay="auto"
          valueLabelFormat={value => `${value}%`}
          onChange={(_, value) =>
            onConstraintsChange('max_bankroll_stake', (value as number) / 100)
          }
        />
      </Box>

      <Box sx={{ mt: 3 }}>
        <Typography gutterBottom>Time Window (Hours)</Typography>
        <TextField
          fullWidth
          inputProps={{ min: 1, max: 168 }}
          type="number"
          value={constraints.time_window_hours}
          onChange={e => onConstraintsChange('time_window_hours', parseInt(e.target.value))}
        />
      </Box>

      <Box sx={{ mt: 3 }}>
        <FormControl fullWidth>
          <InputLabel>Preferred Sports</InputLabel>
          <Select
            multiple
            input={<OutlinedInput label="Preferred Sports" />}
            renderValue={selected => (
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                {selected.map(value => (
                  <Chip key={value} label={value} />
                ))}
              </Box>
            )}
            value={constraints.preferred_sports}
            onChange={e => handleMultiSelectChange('preferred_sports', e.target.value as string[])}
          >
            {SPORTS_OPTIONS.map(sport => (
              <MenuItem key={sport} value={sport}>
                {sport}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      <Box sx={{ mt: 3 }}>
        <FormControl fullWidth>
          <InputLabel>Preferred Markets</InputLabel>
          <Select
            multiple
            input={<OutlinedInput label="Preferred Markets" />}
            renderValue={selected => (
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                {selected.map(value => (
                  <Chip key={value} label={value} />
                ))}
              </Box>
            )}
            value={constraints.preferred_markets}
            onChange={e => handleMultiSelectChange('preferred_markets', e.target.value as string[])}
          >
            {MARKET_OPTIONS.map(market => (
              <MenuItem key={market} value={market}>
                {market}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>
    </Box>
  );
};

import React, { useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  Avatar,
  Button,
  TextField,
  IconButton,
  Divider,
  Chip,
  Alert,
  Snackbar,
  CircularProgress,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import {
  Edit as EditIcon,
  Save as SaveIcon,
  Cancel as CancelIcon,
  PhotoCamera as PhotoCameraIcon,
} from '@mui/icons-material';

const ProfileCard = styled(Card)(({ theme }) => ({
  background: 'rgba(255, 255, 255, 0.9)',
  backdropFilter: 'blur(10px)',
  border: '1px solid rgba(255, 255, 255, 0.2)',
  transition: 'all 0.3s ease',
  '&:hover': {
    transform: 'translateY(-2px)',
    boxShadow: theme.shadows[4],
  },
}));

const StyledAvatar = styled(Avatar)(({ theme }) => ({
  width: 120,
  height: 120,
  border: `4px solid ${theme.palette.primary.main}`,
  cursor: 'pointer',
  '&:hover': {
    opacity: 0.8,
  },
}));

interface UserProfile {
  id: string;
  username: string;
  email: string;
  fullName: string;
  avatar: string;
  bio: string;
  location: string;
  joinDate: string;
  stats: {
    totalBets: number;
    winningBets: number;
    totalWagered: number;
    netProfit: number;
    winRate: number;
  };
  preferences: {
    favoriteSports: string[];
    favoriteTeams: string[];
    bettingStyle: string;
  };
}

const DEFAULT_PROFILE: UserProfile = {
  id: '1',
  username: 'betpro_user',
  email: 'user@example.com',
  fullName: 'John Doe',
  avatar: '/default-avatar.png',
  bio: 'Sports betting enthusiast and data analyst',
  location: 'New York, USA',
  joinDate: '2024-01-01',
  stats: {
    totalBets: 150,
    winningBets: 85,
    totalWagered: 5000,
    netProfit: 1250,
    winRate: 56.7,
  },
  preferences: {
    favoriteSports: ['NBA', 'NFL', 'MLB'],
    favoriteTeams: ['Lakers', '49ers', 'Yankees'],
    bettingStyle: 'Value Betting',
  },
};

export const UserProfile: React.FC = () => {
  const [profile, setProfile] = useState<UserProfile>(DEFAULT_PROFILE);
  const [isEditing, setIsEditing] = useState(false);
  const [editedProfile, setEditedProfile] = useState<UserProfile>(DEFAULT_PROFILE);
  const [isLoading, setIsLoading] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success' as 'success' | 'error',
  });

  const handleEdit = () => {
    setEditedProfile(profile);
    setIsEditing(true);
  };

  const handleCancel = () => {
    setIsEditing(false);
  };

  const handleSave = async () => {
    setIsLoading(true);
    try {
      // TODO: Implement profile update API call
      await new Promise(resolve => setTimeout(resolve, 1000)); // Simulated API call
      setProfile(editedProfile);
      setIsEditing(false);
      setSnackbar({
        open: true,
        message: 'Profile updated successfully',
        severity: 'success',
      });
    } catch (error) {
      setSnackbar({
        open: true,
        message: 'Failed to update profile',
        severity: 'error',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (field: keyof UserProfile, value: string) => {
    setEditedProfile(prev => ({
      ...prev,
      [field]: value,
    }));
  };

  const handleAvatarChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditedProfile(prev => ({
          ...prev,
          avatar: reader.result as string,
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <ProfileCard>
      <CardContent>
        <Grid container spacing={3}>
          {/* Profile Header */}
          <Grid item xs={12} md={4} sx={{ textAlign: 'center' }}>
            <Box position="relative" display="inline-block">
              <StyledAvatar
                src={isEditing ? editedProfile.avatar : profile.avatar}
                alt={profile.fullName}
              />
              {isEditing && (
                <IconButton
                  component="label"
                  sx={{
                    position: 'absolute',
                    bottom: 0,
                    right: 0,
                    backgroundColor: 'primary.main',
                    color: 'white',
                    '&:hover': {
                      backgroundColor: 'primary.dark',
                    },
                  }}
                >
                  <input
                    type="file"
                    hidden
                    accept="image/*"
                    onChange={handleAvatarChange}
                  />
                  <PhotoCameraIcon />
                </IconButton>
              )}
            </Box>
            <Typography variant="h5" sx={{ mt: 2 }}>
              {isEditing ? (
                <TextField
                  fullWidth
                  value={editedProfile.fullName}
                  onChange={(e) => handleInputChange('fullName', e.target.value)}
                />
              ) : (
                profile.fullName
              )}
            </Typography>
            <Typography variant="subtitle1" color="textSecondary">
              @{isEditing ? (
                <TextField
                  fullWidth
                  value={editedProfile.username}
                  onChange={(e) => handleInputChange('username', e.target.value)}
                />
              ) : (
                profile.username
              )}
            </Typography>
          </Grid>

          {/* Profile Details */}
          <Grid item xs={12} md={8}>
            <Box display="flex" justifyContent="flex-end" mb={2}>
              {isEditing ? (
                <>
                  <Button
                    startIcon={<CancelIcon />}
                    onClick={handleCancel}
                    sx={{ mr: 1 }}
                  >
                    Cancel
                  </Button>
                  <Button
                    startIcon={<SaveIcon />}
                    variant="contained"
                    onClick={handleSave}
                    disabled={isLoading}
                  >
                    {isLoading ? <CircularProgress size={24} /> : 'Save'}
                  </Button>
                </>
              ) : (
                <Button
                  startIcon={<EditIcon />}
                  onClick={handleEdit}
                >
                  Edit Profile
                </Button>
              )}
            </Box>

            <Grid container spacing={2}>
              <Grid item xs={12}>
                <Typography variant="subtitle2" color="textSecondary">
                  Bio
                </Typography>
                {isEditing ? (
                  <TextField
                    fullWidth
                    multiline
                    rows={3}
                    value={editedProfile.bio}
                    onChange={(e) => handleInputChange('bio', e.target.value)}
                  />
                ) : (
                  <Typography>{profile.bio}</Typography>
                )}
              </Grid>

              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  Email
                </Typography>
                {isEditing ? (
                  <TextField
                    fullWidth
                    type="email"
                    value={editedProfile.email}
                    onChange={(e) => handleInputChange('email', e.target.value)}
                  />
                ) : (
                  <Typography>{profile.email}</Typography>
                )}
              </Grid>

              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary">
                  Location
                </Typography>
                {isEditing ? (
                  <TextField
                    fullWidth
                    value={editedProfile.location}
                    onChange={(e) => handleInputChange('location', e.target.value)}
                  />
                ) : (
                  <Typography>{profile.location}</Typography>
                )}
              </Grid>

              <Grid item xs={12}>
                <Divider sx={{ my: 2 }} />
              </Grid>

              {/* Stats Section */}
              <Grid item xs={12}>
                <Typography variant="h6" gutterBottom>
                  Betting Statistics
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={6} sm={4}>
                    <Typography variant="subtitle2" color="textSecondary">
                      Total Bets
                    </Typography>
                    <Typography variant="h6">
                      {profile.stats.totalBets}
                    </Typography>
                  </Grid>
                  <Grid item xs={6} sm={4}>
                    <Typography variant="subtitle2" color="textSecondary">
                      Win Rate
                    </Typography>
                    <Typography variant="h6">
                      {profile.stats.winRate}%
                    </Typography>
                  </Grid>
                  <Grid item xs={6} sm={4}>
                    <Typography variant="subtitle2" color="textSecondary">
                      Net Profit
                    </Typography>
                    <Typography
                      variant="h6"
                      color={profile.stats.netProfit >= 0 ? 'success.main' : 'error.main'}
                    >
                      ${profile.stats.netProfit.toLocaleString()}
                    </Typography>
                  </Grid>
                </Grid>
              </Grid>

              <Grid item xs={12}>
                <Divider sx={{ my: 2 }} />
              </Grid>

              {/* Preferences Section */}
              <Grid item xs={12}>
                <Typography variant="h6" gutterBottom>
                  Preferences
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <Typography variant="subtitle2" color="textSecondary">
                      Favorite Sports
                    </Typography>
                    <Box sx={{ mt: 1 }}>
                      {profile.preferences.favoriteSports.map((sport) => (
                        <Chip
                          key={sport}
                          label={sport}
                          sx={{ mr: 1, mb: 1 }}
                        />
                      ))}
                    </Box>
                  </Grid>
                  <Grid item xs={12}>
                    <Typography variant="subtitle2" color="textSecondary">
                      Favorite Teams
                    </Typography>
                    <Box sx={{ mt: 1 }}>
                      {profile.preferences.favoriteTeams.map((team) => (
                        <Chip
                          key={team}
                          label={team}
                          sx={{ mr: 1, mb: 1 }}
                        />
                      ))}
                    </Box>
                  </Grid>
                  <Grid item xs={12}>
                    <Typography variant="subtitle2" color="textSecondary">
                      Betting Style
                    </Typography>
                    <Typography>{profile.preferences.bettingStyle}</Typography>
                  </Grid>
                </Grid>
              </Grid>
            </Grid>
          </Grid>
        </Grid>

        <Snackbar
          open={snackbar.open}
          autoHideDuration={6000}
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
        >
          <Alert
            onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
            severity={snackbar.severity}
            sx={{ width: '100%' }}
          >
            {snackbar.message}
          </Alert>
        </Snackbar>
      </CardContent>
    </ProfileCard>
  );
};

