import { useState, useMemo } from 'react';
import { useLineupAPI } from '@/hooks/useLineupAPI';
import { usePredictions } from '@/hooks/usePredictions';
import { useSportsFilter } from '@/hooks/useSportsFilter';
import { Player } from '@/services/api';
import { motion, AnimatePresence } from 'framer-motion';

interface SmartLineupBuilderProps {
  onLineupSubmit?: (players: Player[]) => void;
  className?: string;
}

export function SmartLineupBuilder({ onLineupSubmit, className = '' }: SmartLineupBuilderProps) {
  const [selectedPlayers, setSelectedPlayers] = useState<Player[]>([]);
  const [filters, setFilters] = useState({
    position: '',
    team: '',
    minSalary: 0,
    maxSalary: 50000,
    minConfidence: 0,
    searchTerm: '',
  });

  const { players, isLoading, filterPlayers, validateLineup, submitLineup } = useLineupAPI();
  const { getPlayerPrediction, getConfidenceColor } = usePredictions();
  const { activeSport } = useSportsFilter();

  const filteredPlayers = useMemo(() => filterPlayers(filters), [filterPlayers, filters]);

  const { isValid, errors, totalSalary } = useMemo(
    () => validateLineup(selectedPlayers),
    [validateLineup, selectedPlayers]
  );

  const handlePlayerSelect = (player: Player) => {
    if (selectedPlayers.find(p => p.id === player.id)) {
      setSelectedPlayers(selectedPlayers.filter(p => p.id !== player.id));
    } else {
      setSelectedPlayers([...selectedPlayers, player]);
    }
  };

  const handleSubmit = async () => {
    if (!isValid || !activeSport) return;

    try {
      await submitLineup({
        players: selectedPlayers.map(p => p.id),
        sport: activeSport.id,
      });
      onLineupSubmit?.(selectedPlayers);
    } catch (error) {
      console.error('Failed to submit lineup:', error);
    }
  };

  if (isLoading) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary-500 border-t-transparent" />
      </div>
    );
  }

  return (
    <div className={`flex h-full flex-col gap-4 ${className}`}>
      {/* Filters */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-6">
        <input
          className="rounded-lg border border-gray-300 px-4 py-2 dark:border-gray-700 dark:bg-gray-800"
          placeholder="Search players..."
          type="text"
          value={filters.searchTerm}
          onChange={e => setFilters({ ...filters, searchTerm: e.target.value })}
        />
        <select
          className="rounded-lg border border-gray-300 px-4 py-2 dark:border-gray-700 dark:bg-gray-800"
          value={filters.position}
          onChange={e => setFilters({ ...filters, position: e.target.value })}
        >
          <option value="">All Positions</option>
          {['QB', 'RB', 'WR', 'TE', 'FLEX', 'DST'].map(pos => (
            <option key={pos} value={pos}>
              {pos}
            </option>
          ))}
        </select>
        {/* Add more filters as needed */}
      </div>

      {/* Players Grid */}
      <div className="grid flex-1 grid-cols-1 gap-4 overflow-auto md:grid-cols-2 lg:grid-cols-3">
        <AnimatePresence>
          {filteredPlayers.map(player => {
            const prediction = getPlayerPrediction(player.id);
            const isSelected = selectedPlayers.some(p => p.id === player.id);
            const confidenceColor = getConfidenceColor(player.confidence);

            return (
              <motion.div
                key={player.id}
                layout
                animate={{ opacity: 1, scale: 1 }}
                className={`cursor-pointer rounded-lg border p-4 transition-colors ${
                  isSelected
                    ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                    : 'border-gray-200 bg-white hover:border-primary-200 dark:border-gray-700 dark:bg-gray-800'
                }`}
                exit={{ opacity: 0, scale: 0.9 }}
                initial={{ opacity: 0, scale: 0.9 }}
                onClick={() => handlePlayerSelect(player)}
              >
                <div className="flex items-center justify-between">
                  <h3 className="font-semibold">{player.name}</h3>
                  <span className="text-sm text-gray-500">{player.position}</span>
                </div>
                <div className="mt-2 flex items-center justify-between">
                  <span className="text-sm text-gray-600 dark:text-gray-400">
                    ${player.salary.toLocaleString()}
                  </span>
                  <span className={`text-sm font-medium ${confidenceColor}`}>
                    {(player.confidence * 100).toFixed(1)}% Confidence
                  </span>
                </div>
                {prediction && (
                  <div className="mt-2 text-sm text-gray-600 dark:text-gray-400">
                    Projected: {prediction.projectedPoints.toFixed(1)} pts
                  </div>
                )}
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>

      {/* Selected Players & Submit */}
      <div className="mt-auto rounded-lg border border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-800">
        <div className="mb-4">
          <h3 className="text-lg font-semibold">Selected Players ({selectedPlayers.length})</h3>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Total Salary: ${totalSalary.toLocaleString()} / $50,000
          </p>
        </div>

        {errors.length > 0 && (
          <div className="mb-4 rounded-lg bg-red-50 p-4 dark:bg-red-900/20">
            <ul className="list-inside list-disc text-sm text-red-600 dark:text-red-400">
              {errors.map((error, index) => (
                <li key={index}>{error}</li>
              ))}
            </ul>
          </div>
        )}

        <button
          className={`w-full rounded-lg px-4 py-2 font-medium text-white transition-colors ${
            isValid
              ? 'bg-primary-500 hover:bg-primary-600'
              : 'cursor-not-allowed bg-gray-400 dark:bg-gray-600'
          }`}
          disabled={!isValid}
          onClick={handleSubmit}
        >
          Submit Lineup
        </button>
      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { useApiRequest } from '../../hooks/useApiRequest';
import { useWebSocket } from '../../hooks/useWebSocket';

interface Headline {
  headline: string;
  timestamp: number;
  link?: string;
  relatedPlayers: { id: string; name: string }[];
  sentiment: {
    twitter?: number;
    reddit?: number;
    news?: number;
  };
}

interface PlayerSentiment {
  twitter?: number;
  reddit?: number;
  news?: number;
}

const getSentimentBadge = (sentiment: PlayerSentiment) => {
  // Simple badge: green if positive, red if negative, gray if neutral/undefined
  const avg =
    sentiment &&
    [sentiment.twitter, sentiment.reddit, sentiment.news]
      .filter(v => typeof v === 'number')
      .reduce((a, b) => a + (b || 0), 0) /
      ([sentiment.twitter, sentiment.reddit, sentiment.news].filter(v => typeof v === 'number')
        .length || 1);
  let color = 'bg-gray-300 text-gray-700';
  let icon = '−';
  if (avg > 0.2) {
    color = 'bg-green-200 text-green-700';
    icon = '▲';
  } else if (avg < -0.2) {
    color = 'bg-red-200 text-red-700';
    icon = '▼';
  }
  return (
    <span className={`ml-2 px-2 py-1 rounded-full text-xs font-bold ${color}`}>
      {icon} {(avg * 100).toFixed(0)}%
    </span>
  );
};

const ESPNHeadlinesTicker: React.FC = () => {
  const [headlines, setHeadlines] = useState<Headline[]>([]);
  const [playerSentiments, setPlayerSentiments] = useState<Record<string, PlayerSentiment>>({});
  const [paused, setPaused] = useState(false);
  const tickerRef = useRef<HTMLDivElement>(null);

  // WebSocket connection for ESPN feed
  useWebSocket({
    url: 'ws://localhost:3001/espn-feed',
    onMessage: msg => {
      // Assume msg.data is a Headline or array of Headline
      let newHeadlines: Headline[] = [];
      if (Array.isArray(msg.data)) {
        newHeadlines = msg.data as Headline[];
      } else if (msg.data && typeof msg.data === 'object') {
        newHeadlines = [msg.data as Headline];
      }
      setHeadlines(prev => {
        // Merge, deduplicate by headline+timestamp
        const all = [...newHeadlines, ...prev];
        const seen = new Set();
        return all.filter(h => {
          const key = h.headline + h.timestamp;
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
      });
    },
  });

  // Fetch sentiment for each related player
  useEffect(() => {
    const fetchSentiment = async (playerId: string) => {
      try {
        const res = await fetch(`/api/sentiment/${playerId}`);
        if (!res.ok) return;
        const data = await res.json();
        setPlayerSentiments(prev => ({ ...prev, [playerId]: data }));
      } catch {}
    };
    const playerIds = headlines.flatMap(h => h.relatedPlayers.map(p => p.id));
    Array.from(new Set(playerIds)).forEach(id => {
      if (!playerSentiments[id]) fetchSentiment(id);
    });
    // Optionally, poll every 30s for live update
    const interval = setInterval(() => {
      Array.from(new Set(playerIds)).forEach(fetchSentiment);
    }, 30000);
    return () => clearInterval(interval);
    // eslint-disable-next-line
  }, [headlines]);

  // Auto-scroll logic
  useEffect(() => {
    if (paused || !tickerRef.current) return;
    const ticker = tickerRef.current;
    let frame: number;
    let start: number | null = null;
    const scrollWidth = ticker.scrollWidth;
    const clientWidth = ticker.clientWidth;
    const maxScroll = scrollWidth - clientWidth;
    const speed = 40; // px/sec
    function step(ts: number) {
      if (start === null) start = ts;
      const elapsed = ts - start;
      const px = ((elapsed / 1000) * speed) % (maxScroll + 100);
      ticker.scrollLeft = px;
      frame = requestAnimationFrame(step);
    }
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [paused, headlines]);

  if (!headlines.length) {
    return (
      <div className="glass rounded-2xl px-4 py-2 text-gray-500 animate-pulse-soft">
        Loading ESPN headlines...
      </div>
    );
  }

  return (
    <div
      ref={tickerRef}
      className="news-ticker glass rounded-2xl px-4 py-2 overflow-x-auto whitespace-nowrap cursor-pointer relative"
      style={{ transition: 'background 0.2s' }}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <div className="inline-flex items-center gap-8 news-ticker-content">
        {headlines.map((h, i) => (
          <span key={h.headline + h.timestamp + i} className="flex items-center gap-2">
            <a
              className="hover:underline text-blue-700 dark:text-blue-300 font-semibold"
              href={h.link || '#'}
              rel="noopener noreferrer"
              target="_blank"
              title={new Date(h.timestamp).toLocaleString()}
            >
              {h.headline}
            </a>
            {/* Show sentiment badges for each related player */}
            {h.relatedPlayers.map(p => (
              <span key={p.id} className="ml-1">
                <span className="text-xs text-gray-500">{p.name}</span>
                {getSentimentBadge(playerSentiments[p.id] || {})}
              </span>
            ))}
          </span>
        ))}
      </div>
      {/* Pause overlay */}
      {paused && <div className="absolute inset-0 bg-black bg-opacity-10 pointer-events-none" />}
    </div>
  );
};

export default React.memo(ESPNHeadlinesTicker);

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useAppState } from './StateProvider';

// EntryTracking: Real-time entry tracker for Poe UI
// Usage: <EntryTracking entries={optionalEntries} />

const WS_URL = 'ws://localhost:3001/entries';

// Match context Entry type
type Entry = {
  id: string;
  date: string;
  legs: number;
  entry: number;
  potentialPayout: number;
  status: 'won' | 'lost' | 'pending';
  picks: Array<{
    player: string;
    stat: string;
    line: string;
    result: 'won' | 'lost' | 'pending';
    current: number;
    target: number;
  }>;
};

const statusColor = (status: string) =>
  status === 'won'
    ? 'status-won bg-green-500'
    : status === 'lost'
      ? 'status-lost bg-red-500'
      : 'status-pending bg-gray-400';

// Convert incoming WebSocket entry to context Entry type if needed
function toContextEntry(e: any): Entry {
  return {
    id: e.id,
    date: e.date || new Date(e.timestamp || Date.now()).toISOString().split('T')[0],
    legs: e.legs || (e.picks ? e.picks.length : 0),
    entry: e.entry ?? 0,
    potentialPayout: e.potentialPayout ?? e.payout ?? 0,
    status: e.status,
    picks: e.picks || [],
  };
}

const EntryTracking: React.FC<{ entries?: Entry[] }> = ({ entries: propEntries }) => {
  const { entries: contextEntries, addEntry } = useAppState?.() || {
    entries: [],
    addEntry: undefined,
  };
  const [entries, setEntries] = useState<Entry[]>(propEntries || contextEntries || []);
  const [selected, setSelected] = useState<string | null>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const [wsError, setWsError] = useState<string | null>(null);

  // WebSocket logic only if not controlled
  useEffect(() => {
    if (propEntries) return;
    let ws: WebSocket;
    let reconnectTimer: NodeJS.Timeout | null = null;
    function connect() {
      ws = new window.WebSocket(WS_URL);
      wsRef.current = ws;
      ws.onopen = () => setWsError(null);
      ws.onmessage = event => {
        try {
          const data = JSON.parse(event.data);
          if (Array.isArray(data)) {
            // Batch update: only update local state, not context (no batch setter in context)
            setEntries(data.map(toContextEntry));
            // TODO: add batch update to context if needed in future
          } else if (data && typeof data === 'object' && data.id) {
            setEntries(prev => {
              const idx = prev.findIndex(e => e.id === data.id);
              const entry = toContextEntry(data);
              if (idx >= 0) {
                const updated = [...prev];
                updated[idx] = entry;
                return updated;
              }
              // Add to top
              if (addEntry) addEntry(entry);
              return [entry, ...prev];
            });
          }
        } catch (e) {
          // Ignore parse errors
        }
      };
      ws.onclose = () => {
        setWsError('Disconnected from entry server. Reconnecting...');
        reconnectTimer = setTimeout(connect, 2000);
      };
      ws.onerror = () => {
        setWsError('WebSocket error. Attempting reconnect...');
        ws.close();
      };
    }
    connect();
    return () => {
      wsRef.current?.close();
      if (reconnectTimer) clearTimeout(reconnectTimer);
    };
  }, [propEntries, addEntry]);

  // Sync with context if context changes (for global updates)
  useEffect(() => {
    if (!propEntries && contextEntries && contextEntries.length) {
      setEntries(contextEntries);
    }
  }, [contextEntries, propEntries]);

  // Memoize entry list and modal for performance
  const entryList = useMemo(
    () =>
      entries.map(entry => (
        <div
          key={entry.id}
          className={`modern-card p-6 hover:shadow-large transition-all entry-card-clickable animate-fade-in`}
          onClick={() => setSelected(entry.id)}
        >
          <div className="flex justify-between items-start mb-4">
            <div>
              <div className="font-bold text-xl">{entry.legs}-Leg Entry</div>
              <div className="text-sm text-gray-600 dark:text-gray-400 font-medium">
                {entry.date}
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <span className={`status-badge ${statusColor(entry.status)} animate-fade-in`}>
                {entry.status === 'pending' ? '⏳' : entry.status === 'won' ? '✅' : '❌'}{' '}
                {entry.status.toUpperCase()}
              </span>
            </div>
          </div>
          <div className="space-y-3 mb-6">
            {entry.picks.map((pick, i) => {
              const progress = pick.current / pick.target;
              const progressClass =
                pick.result === 'won' ? 'success' : pick.result === 'lost' ? 'danger' : 'pending';
              return (
                <div key={i} className="text-sm p-3 glass rounded-xl animate-fade-in">
                  <div className="flex justify-between items-center mb-2">
                    <span className="font-medium">{pick.player}</span>
                    <span
                      className={`text-xs ${pick.result === 'won' ? 'text-green-600' : pick.result === 'lost' ? 'text-red-600' : 'text-gray-500'}`}
                    >
                      {pick.result === 'won' ? '✅' : pick.result === 'lost' ? '❌' : '⏳'}
                    </span>
                  </div>
                  <div className="text-xs text-gray-600 dark:text-gray-400 mb-2">
                    {pick.stat} {pick.line}
                  </div>
                  <div className="progress-bar mb-1">
                    <div
                      className={`progress-fill ${progressClass} animate-fade-in`}
                      style={{ width: `${Math.min(progress * 100, 100)}%` }}
                    ></div>
                  </div>
                  <div className="text-xs text-gray-500">
                    {pick.current} / {pick.target}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="flex justify-between items-center pt-4 border-t">
            <div>
              <div className="text-sm text-gray-600 dark:text-gray-400 font-medium">Payout</div>
              <div className="font-bold text-lg">${entry.potentialPayout.toFixed(2)}</div>
            </div>
            <div className="text-right">
              <div className="text-sm text-gray-600 dark:text-gray-400 font-medium">Legs</div>
              <div className="font-bold text-lg text-blue-600">{entry.legs}</div>
            </div>
          </div>
        </div>
      )),
    [entries]
  );

  const selectedEntry = useMemo(() => entries.find(e => e.id === selected), [entries, selected]);

  return (
    <div className="modern-card p-6 lg:p-8 animate-fade-in">
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between mb-6 lg:mb-8 gap-4">
        <div className="flex items-center space-x-4">
          <h2 className="text-2xl lg:text-3xl font-bold">📋 Active Entries</h2>
          <span className="status-badge bg-primary-500 text-white">
            {entries.filter(e => e.status === 'pending').length} Active
          </span>
        </div>
      </div>
      {wsError && <div className="text-red-500 text-center mb-4 animate-fade-in">{wsError}</div>}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 lg:gap-6 mb-6 lg:mb-8">
        {entryList}
      </div>
      {/* Entry Modal */}
      {selectedEntry && (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
          <div className="modern-card max-w-4xl w-full p-8 text-gray-900 dark:text-white max-h-[90vh] overflow-y-auto animate-fade-in">
            <div className="flex justify-between items-start mb-8">
              <h3 className="text-2xl font-bold">📊 Entry Progress</h3>
              <button
                className="text-gray-500 hover:text-gray-700 dark:hover:text-gray-300 text-xl"
                onClick={() => setSelected(null)}
              >
                ×
              </button>
            </div>
            <div className="mb-6">
              <div className="flex items-center justify-between mb-4">
                <h4 className="text-xl font-bold">
                  {selectedEntry.legs}-Leg Entry - {selectedEntry.date}
                </h4>
                <span
                  className={`status-badge ${statusColor(selectedEntry.status)} animate-fade-in`}
                >
                  {selectedEntry.status.toUpperCase()}
                </span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-center">
                <div className="glass rounded-xl p-4">
                  <div className="text-2xl font-bold">
                    ${selectedEntry.potentialPayout.toFixed(2)}
                  </div>
                  <div className="text-sm text-gray-600 dark:text-gray-400">Potential Payout</div>
                </div>
                <div className="glass rounded-xl p-4">
                  <div
                    className={`text-2xl font-bold ${selectedEntry.status === 'won' ? 'text-green-600' : selectedEntry.status === 'lost' ? 'text-red-600' : 'text-blue-600'}`}
                  >
                    {selectedEntry.status === 'lost'
                      ? '0.00'
                      : selectedEntry.potentialPayout.toFixed(2)}
                  </div>
                  <div className="text-sm text-gray-600 dark:text-gray-400">Status</div>
                </div>
                <div className="glass rounded-xl p-4">
                  <div className="text-2xl font-bold">
                    {selectedEntry.picks.filter(p => p.result === 'won').length}/
                    {selectedEntry.picks.length}
                  </div>
                  <div className="text-sm text-gray-600 dark:text-gray-400">Hits</div>
                </div>
              </div>
            </div>
            <div className="space-y-4">
              {selectedEntry.picks.map((pick, i) => {
                const progress = pick.current / pick.target;
                const progressClass =
                  pick.result === 'won' ? 'success' : pick.result === 'lost' ? 'danger' : 'pending';
                return (
                  <div key={i} className="modern-card p-4 animate-fade-in">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <h5 className="font-bold">{pick.player}</h5>
                        <div className="text-sm text-gray-600 dark:text-gray-400">
                          {pick.stat} {pick.line}
                        </div>
                      </div>
                      <div className="text-right">
                        <span
                          className={`text-xs ${pick.result === 'won' ? 'text-green-600' : pick.result === 'lost' ? 'text-red-600' : 'text-gray-500'}`}
                        >
                          {pick.result === 'won' ? '✅' : pick.result === 'lost' ? '❌' : '⏳'}
                        </span>
                      </div>
                    </div>
                    <div className="mb-2">
                      <div className="flex justify-between text-sm mb-1">
                        <span>
                          Progress: {pick.current} / {pick.target}
                        </span>
                        <span>{(progress * 100).toFixed(0)}%</span>
                      </div>
                      <div className="progress-bar">
                        <div
                          className={`progress-fill ${progressClass} animate-fade-in`}
                          style={{ width: `${Math.min(progress * 100, 100)}%` }}
                        ></div>
                      </div>
                    </div>
                    <div className="text-xs text-gray-500">
                      {pick.result === 'pending' ? 'Live' : 'Final'}: {pick.current}{' '}
                      {pick.stat.toLowerCase()}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

