import React, { useState, useMemo } from 'react';
import { Box, Typography, TextField, MenuItem, Grid, Paper, CircularProgress } from '@mui/material';
import { BetRecommendationCard } from './BetRecommendationCard';
import { BetRecommendation } from '../../core/types/prediction';
import { PredictionExplanationModal } from './PredictionExplanationModal';

interface BetRecommendationListProps {
  recommendations: BetRecommendation[];
  loading?: boolean;
  error?: string;
}

type SortOption = 'confidence' | 'stake' | 'expectedValue' | 'riskLevel';
type FilterOption = 'all' | 'low' | 'medium' | 'high';

export const BetRecommendationList: React.FC<BetRecommendationListProps> = ({
  recommendations,
  loading = false,
  error,
}) => {
  const [sortBy, setSortBy] = useState<SortOption>('confidence');
  const [filterBy, setFilterBy] = useState<FilterOption>('all');
  const [selectedRecommendation, setSelectedRecommendation] = useState<BetRecommendation | null>(
    null
  );

  const filteredAndSortedRecommendations = useMemo(() => {
    let filtered = recommendations;

    // Apply risk level filter
    if (filterBy !== 'all') {
      filtered = filtered.filter(rec => rec.riskLevel === filterBy);
    }

    // Apply sorting
    return filtered.sort((a, b) => {
      switch (sortBy) {
        case 'confidence':
          return b.confidence - a.confidence;
        case 'stake':
          return b.stake - a.stake;
        case 'expectedValue':
          return b.expectedValue - a.expectedValue;
        case 'riskLevel':
          const riskOrder = { low: 0, medium: 1, high: 2 };
          return riskOrder[a.riskLevel] - riskOrder[b.riskLevel];
        default:
          return 0;
      }
    });
  }, [recommendations, sortBy, filterBy]);

  if (loading) {
    return (
      <Box alignItems="center" display="flex" justifyContent="center" minHeight={200}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Paper sx={{ p: 2, bgcolor: 'error.light' }}>
        <Typography color="error">{error}</Typography>
      </Paper>
    );
  }

  if (recommendations.length === 0) {
    return (
      <Paper sx={{ p: 2 }}>
        <Typography color="text.secondary">No bet recommendations available</Typography>
      </Paper>
    );
  }

  return (
    <Box>
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item sm={6} xs={12}>
          <TextField
            fullWidth
            select
            label="Sort By"
            value={sortBy}
            onChange={e => setSortBy(e.target.value as SortOption)}
          >
            <MenuItem value="confidence">Confidence</MenuItem>
            <MenuItem value="stake">Stake Amount</MenuItem>
            <MenuItem value="expectedValue">Expected Value</MenuItem>
            <MenuItem value="riskLevel">Risk Level</MenuItem>
          </TextField>
        </Grid>
        <Grid item sm={6} xs={12}>
          <TextField
            fullWidth
            select
            label="Filter By Risk"
            value={filterBy}
            onChange={e => setFilterBy(e.target.value as FilterOption)}
          >
            <MenuItem value="all">All Risk Levels</MenuItem>
            <MenuItem value="low">Low Risk</MenuItem>
            <MenuItem value="medium">Medium Risk</MenuItem>
            <MenuItem value="high">High Risk</MenuItem>
          </TextField>
        </Grid>
      </Grid>

      <Box>
        {filteredAndSortedRecommendations.map(recommendation => (
          <BetRecommendationCard
            key={recommendation.id}
            recommendation={recommendation}
            onViewDetails={() => setSelectedRecommendation(recommendation)}
          />
        ))}
      </Box>

      {selectedRecommendation && (
        <PredictionExplanationModal
          open={!!selectedRecommendation}
          prediction={{
            prediction: selectedRecommendation.prediction.prediction,
            confidence: selectedRecommendation.confidence,
            explanations: [
              {
                modelName: selectedRecommendation.prediction.type,
                confidence: selectedRecommendation.confidence,
                shapExplanation: {
                  featureNames: Object.keys(selectedRecommendation.prediction.features),
                  featureValues: Object.values(selectedRecommendation.prediction.features),
                  importanceScores: [],
                  baseValue: 0,
                  prediction: selectedRecommendation.prediction.prediction,
                },
              },
            ],
          }}
          onClose={() => setSelectedRecommendation(null)}
        />
      )}
    </Box>
  );
};

import React from 'react';
import { Card, Badge, Button, Icon } from '../ui/UnifiedUI';
import { PredictionModelOutput } from '../../hooks/usePredictions';

interface MoneyMakerResultsProps {
  event: string;
  market: string;
  selection: string;
  odds: number;
  modelOutput: PredictionModelOutput;
  kellyFraction: number;
  expectedValue: number;
  timestamp: number;
  onPlaceBet: () => void;
  className?: string;
}

export const MoneyMakerResults: React.FC<MoneyMakerResultsProps> = ({
  event,
  market,
  selection,
  odds,
  modelOutput,
  kellyFraction,
  expectedValue,
  timestamp,
  onPlaceBet,
  className = '',
}) => {
  const { confidenceScore, confidenceColor, modelMeta } = modelOutput;

  const getKellyColor = (fraction: number): 'success' | 'warning' | 'danger' => {
    if (fraction >= 0.1) return 'success';
    if (fraction >= 0.05) return 'warning';
    return 'danger';
  };

  const getEVColor = (ev: number): 'success' | 'warning' | 'danger' => {
    if (ev >= 0.1) return 'success';
    if (ev >= 0) return 'warning';
    return 'danger';
  };

  return (
    <Card className={`p-4 ${className}`}>
      <div className="flex justify-between items-start mb-4">
        <div>
          <h3 className="text-lg font-semibold">{event}</h3>
          <p className="text-sm text-gray-600">
            {market} - {selection}
          </p>
        </div>
        <div className="flex flex-col items-end space-y-2">
          <Badge variant={confidenceColor}>{confidenceScore.toFixed(2)}</Badge>
          <Badge variant={getEVColor(expectedValue)}>EV: {expectedValue.toFixed(2)}</Badge>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-4">
        <div>
          <p className="text-sm text-gray-600">Odds</p>
          <p className="text-lg font-semibold">{odds.toFixed(2)}</p>
        </div>
        <div>
          <p className="text-sm text-gray-600">Kelly Fraction</p>
          <div className="flex items-center space-x-2">
            <p className="text-lg font-semibold">{(kellyFraction * 100).toFixed(1)}%</p>
            <Badge variant={getKellyColor(kellyFraction)}>
              {kellyFraction >= 0.1 ? 'Strong' : kellyFraction >= 0.05 ? 'Moderate' : 'Weak'}
            </Badge>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-2 text-xs text-gray-500">
          <Icon className="w-4 h-4" name="info" />
          <span>
            Model: {modelMeta.type} v{modelMeta.version}
          </span>
        </div>
        <Button
          aria-label="Place Bet"
          disabled={kellyFraction < 0.05 || expectedValue < 0}
          variant="primary"
          onClick={onPlaceBet}
        >
          Place Bet
        </Button>
      </div>
    </Card>
  );
};

