import React, { useState } from "react";
import { Box, Button, TextField, Typography, CircularProgress, Alert } from "@mui/material";
import { PredictionDisplay } from ".";

interface Features {
  [key: string]: number;
}

interface PredictionResult {
  value: number;
  confidence: number;
  payout: number;
  shap_values: Record<string, number>;
  explanation: string;
}

const DEFAULT_FEATURES: Features = {
  feature1: 0,
  feature2: 0,
  feature3: 0,
};

const validateFeatures = (features: Features) => {
  // Example: all features must be numbers and not NaN
  return Object.values(features).every((v) => typeof v === 'number' && !isNaN(v));
};

const PredictionForm: React.FC = () => {
  const [features, setFeatures] = useState<Features>(DEFAULT_FEATURES);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<PredictionResult | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFeatures({ ...features, [e.target.name]: parseFloat(e.target.value) });
  };

  const handlePredict = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateFeatures(features)) {
      setError("All features must be valid numbers.");
      return;
    }
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const res = await fetch("/api/predict", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ features }),
      });
      if (!res.ok) throw new Error(`API error: ${res.status}`);
      const data = await res.json();
      setResult(data);
    } catch (err: any) {
      setError(err.message || "Prediction failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ maxWidth: 400, mx: "auto", mt: 4 }}>
      <Typography variant="h5" gutterBottom>
        Make a Prediction
      </Typography>
      <form onSubmit={handlePredict}>
        {Object.keys(features).map((key) => (
          <TextField
            key={key}
            name={key}
            label={key}
            type="number"
            value={features[key]}
            onChange={handleChange}
            margin="normal"
            fullWidth
            required
          />
        ))}
        <Button
          type="submit"
          variant="contained"
          color="primary"
          disabled={loading}
          fullWidth
          sx={{ mt: 2 }}
        >
          {loading ? <CircularProgress size={24} /> : "Predict"}
        </Button>
      </form>
      {error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}
      {result && (
        <Box sx={{ mt: 4 }}>
          <PredictionDisplay prediction={{
            value: result.value,
            confidence: result.confidence,
            payout: result.payout,
            shapValues: result.shap_values,
            explanation: result.explanation,
          }} />
        </Box>
      )}
    </Box>
  );
};

export default PredictionForm;

import React, { useState } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  Legend,
  ScatterChart,
  Scatter,
  LineChart,
  Line,
  Cell,
} from 'recharts';
import type {
  BarProps,
  XAxisProps,
  YAxisProps,
  TooltipProps,
  LegendProps,
  ScatterProps,
  LineProps,
} from 'recharts';
import {
  Box,
  Paper,
  Typography,
  Tabs,
  Tab,
  CircularProgress,
  Alert,
  Tooltip as MuiTooltip,
  IconButton,
  Chip,
  Stack,
} from '@mui/material';
import InfoIcon from '@mui/icons-material/Info';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import {
  ShapExplanation as ShapExplanationType,
  ModelExplanation,
} from '../../core/types/prediction';

interface ShapExplanationProps {
  explanation: ModelExplanation;
  className?: string;
}

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

const TabPanel = (props: TabPanelProps) => {
  const { children, value, index, ...other } = props;
  return (
    <div
      aria-labelledby={`shap-tab-${index}`}
      hidden={value !== index}
      id={`shap-tabpanel-${index}`}
      role="tabpanel"
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
};

export const ShapExplanation: React.FC<ShapExplanationProps> = ({
  explanation,
  className = '',
}) => {
  const [tabValue, setTabValue] = useState(0);
  const { shapExplanation, modelName, confidence } = explanation;

  // Prepare data for different visualizations
  const barChartData = (shapExplanation?.shapValues ?? []).map(value => ({
    feature: value.feature,
    impact: value.impact,
    direction: value.direction,
    value: value.value,
    confidence: value.confidence || 0.8,
  }));

  const scatterData = (shapExplanation?.shapValues ?? []).map(value => ({
    feature: value.feature,
    impact: value.impact,
    value: value.value,
    confidence: value.confidence || 0.8,
  }));

  const waterfallData = (shapExplanation?.shapValues ?? []).reduce(
    (acc, value, index) => {
      const prevValue = index === 0 ? shapExplanation.baseValue : acc[index - 1].end;
      return [
        ...acc,
        {
          feature: value.feature,
          start: prevValue,
          end: prevValue + value.impact,
          impact: value.impact,
          confidence: value.confidence || 0.8,
        },
      ];
    },
    [] as Array<{ feature: string; start: number; end: number; impact: number; confidence: number }>
  );

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  // Calculate feature impact statistics
  const positiveFeatures = barChartData.filter(f => f.impact > 0);
  const negativeFeatures = barChartData.filter(f => f.impact < 0);
  const totalImpact = barChartData.reduce((sum, f) => sum + Math.abs(f.impact), 0);
  const topFeatures = [...barChartData]
    .sort((a, b) => Math.abs(b.impact) - Math.abs(a.impact))
    .slice(0, 3);

  return (
    <Paper className={`p-4 ${className}`} elevation={3}>
      <Box alignItems="center" display="flex" justifyContent="space-between" mb={2}>
        <Typography variant="h6">{modelName}</Typography>
        <Box alignItems="center" display="flex" gap={2}>
          <Chip
            color="success"
            icon={<TrendingUpIcon />}
            label={`${positiveFeatures.length} Positive Features`}
            size="small"
          />
          <Chip
            color="error"
            icon={<TrendingDownIcon />}
            label={`${negativeFeatures.length} Negative Features`}
            size="small"
          />
          <Chip color="primary" label={`Total Impact: ${totalImpact.toFixed(3)}`} size="small" />
        </Box>
      </Box>

      <Box mb={2}>
        <Typography gutterBottom color="textSecondary" variant="subtitle2">
          Top Influential Features
        </Typography>
        <Stack direction="row" spacing={1}>
          {topFeatures.map((feature, index) => (
            <Chip
              key={index}
              color={feature.impact > 0 ? 'success' : 'error'}
              label={`${feature.feature}: ${feature.impact.toFixed(3)}`}
              size="small"
            />
          ))}
        </Stack>
      </Box>

      <Tabs centered value={tabValue} onChange={handleTabChange}>
        <Tab label="Feature Impact" />
        <Tab label="Feature Dependence" />
        <Tab label="Waterfall" />
      </Tabs>

      <TabPanel index={0} value={tabValue}>
        <Box height={400}>
          <ResponsiveContainer height="100%" width="100%">
            <BarChart data={barChartData} layout="vertical">
              <XAxis type="number" />
              <YAxis dataKey="feature" tick={{ fontSize: 12 }} type="category" width={150} />
              <Tooltip
                formatter={(value: number, name: string, props: any) => {
                  const item = barChartData[props.payload.index];
                  return [
                    `${item.impact.toFixed(4)} (${item.impact > 0 ? 'Positive' : 'Negative'} Impact)`,
                    'Impact',
                  ];
                }}
                labelFormatter={(label: string) => `Feature: ${label}`}
              />
              <Legend />
              <Bar
                dataKey="impact"
                fill="#8884d8"
                isAnimationActive={false}
                label={{ position: 'right' }}
              >
                {barChartData.map((entry, index) => (
                  <Cell
                    key={`cell-${index}`}
                    fill={entry.impact > 0 ? '#4caf50' : '#f44336'}
                    opacity={entry.confidence}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Box>
      </TabPanel>

      <TabPanel index={1} value={tabValue}>
        <Box height={400}>
          <ResponsiveContainer height="100%" width="100%">
            <ScatterChart>
              <XAxis dataKey="value" name="Feature Value" />
              <YAxis dataKey="impact" name="Impact" />
              <Tooltip
                formatter={(value: number, name: string, props: any) => {
                  const item = scatterData[props.payload.index];
                  return [
                    `${item.impact.toFixed(4)} (${item.impact > 0 ? 'Positive' : 'Negative'} Impact)`,
                    'Impact',
                  ];
                }}
                labelFormatter={(label: string) => `Feature: ${label}`}
              />
              <Legend />
              <Scatter data={scatterData} fill="#8884d8" isAnimationActive={false}>
                {scatterData.map((entry, index) => (
                  <Cell
                    key={`cell-${index}`}
                    fill={entry.impact > 0 ? '#4caf50' : '#f44336'}
                    opacity={entry.confidence}
                  />
                ))}
              </Scatter>
            </ScatterChart>
          </ResponsiveContainer>
        </Box>
      </TabPanel>

      <TabPanel index={2} value={tabValue}>
        <Box height={400}>
          <ResponsiveContainer height="100%" width="100%">
            <LineChart data={waterfallData}>
              <XAxis dataKey="feature" />
              <YAxis />
              <Tooltip
                formatter={(value: number, name: string, props: any) => {
                  const item = waterfallData[props.payload.index];
                  return [
                    `${item.impact.toFixed(4)} (${item.impact > 0 ? 'Positive' : 'Negative'} Impact)`,
                    'Impact',
                  ];
                }}
                labelFormatter={(label: string) => `Feature: ${label}`}
              />
              <Legend />
              <Line
                dataKey="end"
                dot={{ fill: '#8884d8' }}
                isAnimationActive={false}
                stroke="#8884d8"
                type="monotone"
              />
            </LineChart>
          </ResponsiveContainer>
        </Box>
      </TabPanel>
    </Paper>
  );
};

import React, { useState, useEffect } from 'react';
import { UnifiedServiceRegistry } from '../../services/unified/UnifiedServiceRegistry';
import { UnifiedPredictionService } from '../../services/unified/UnifiedPredictionService';
import { UnifiedAnalyticsService } from '../../services/unified/UnifiedAnalyticsService';
import { UnifiedWebSocketService } from '../../services/unified/UnifiedWebSocketService';
import { UnifiedStateService } from '../../services/unified/UnifiedStateService';
import { UnifiedSettingsService } from '../../services/unified/UnifiedSettingsService';
import { UnifiedNotificationService } from '../../services/unified/UnifiedNotificationService';
import { UnifiedErrorService } from '../../services/unified/UnifiedErrorService';
import { Card, Button, Spinner, Badge, Modal, Toast } from '../ui/UnifiedUI';

interface Prediction {
  id: string;
  eventId: string;
  marketType: string;
  prediction: number;
  confidence: number;
  timestamp: number;
  features: Record<string, number>;
  modelVersion: string;
  metadata: Record<string, any>;
}

interface PredictionOpportunity {
  id: string;
  eventId: string;
  marketType: string;
  prediction: number;
  confidence: number;
  expectedValue: number;
  kellyFraction: number;
  timestamp: number;
  metadata: Record<string, any>;
}

export const UnifiedPredictionInterface: React.FC = () => {
  // Initialize services
  const serviceRegistry = UnifiedServiceRegistry.getInstance();
  const predictionService = serviceRegistry.getService<UnifiedPredictionService>('prediction');
  const analyticsService = serviceRegistry.getService<UnifiedAnalyticsService>('analytics');
  const webSocketService = serviceRegistry.getService<UnifiedWebSocketService>('websocket');
  const stateService = serviceRegistry.getService<UnifiedStateService>('state');
  const settingsService = serviceRegistry.getService<UnifiedSettingsService>('settings');
  const notificationService =
    serviceRegistry.getService<UnifiedNotificationService>('notification');
  const errorService = serviceRegistry.getService<UnifiedErrorService>('error');

  // State
  const [predictions, setPredictions] = useState<Prediction[]>([]);
  const [opportunities, setOpportunities] = useState<PredictionOpportunity[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedPrediction, setSelectedPrediction] = useState<Prediction | null>(null);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [toast, setToast] = useState<{
    message: string;
    type: 'success' | 'error' | 'warning' | 'info';
  } | null>(null);

  // Load data
  useEffect(() => {
    loadData();
    setupWebSocket();
    return () => {
      webSocketService.disconnect();
    };
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [predictions, opportunities] = await Promise.all([
        predictionService.getPredictions(),
        predictionService.getOpportunities(),
      ]);
      setPredictions(predictions);
      setOpportunities(opportunities);
    } catch (error) {
      handleError('Failed to load prediction data', error);
    } finally {
      setLoading(false);
    }
  };

  const setupWebSocket = () => {
    webSocketService.connect();
    webSocketService.subscribe('predictions', data => {
      setPredictions(prev => [...prev, data]);
      notificationService.notifyUser({
        type: 'info',
        message: 'New prediction available',
        data,
      });
    });
    webSocketService.subscribe('opportunities', data => {
      setOpportunities(prev => [...prev, data]);
      notificationService.notifyUser({
        type: 'info',
        message: 'New opportunity detected',
        data,
      });
    });
  };

  const handleError = (message: string, error: any) => {
    setError(message);
    setToast({ message, type: 'error' });
    errorService.handleError(error, {
      code: 'PREDICTION_ERROR',
      source: 'UnifiedPredictionInterface',
      details: { message },
    });
  };

  const handlePredictionClick = (prediction: Prediction) => {
    setSelectedPrediction(prediction);
    setShowDetailsModal(true);
  };

  const handleOpportunityClick = async (opportunity: PredictionOpportunity) => {
    try {
      await predictionService.analyzeOpportunity(opportunity);
      setToast({
        message: 'Opportunity analyzed successfully',
        type: 'success',
      });
    } catch (error) {
      handleError('Failed to analyze opportunity', error);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Spinner size="large" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Card className="max-w-md">
          <div className="text-center">
            <h2 className="text-2xl font-bold text-red-500 mb-4">Error</h2>
            <p className="text-gray-600 mb-4">{error}</p>
            <Button variant="primary" onClick={loadData}>
              Retry
            </Button>
          </div>
        </Card>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-4">Predictions & Opportunities</h1>
        <div className="flex justify-between items-center">
          <div className="flex space-x-4">
            <Button variant="primary" onClick={loadData}>
              Refresh
            </Button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Predictions */}
        <div>
          <h2 className="text-2xl font-bold mb-4">Recent Predictions</h2>
          <div className="space-y-4">
            {predictions.map(prediction => (
              <Card
                key={prediction.id}
                className="cursor-pointer hover:shadow-lg transition-shadow"
                onClick={() => handlePredictionClick(prediction)}
              >
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="font-semibold">{prediction.marketType}</h3>
                    <p className="text-sm text-gray-600">Event ID: {prediction.eventId}</p>
                  </div>
                  <Badge
                    variant={
                      prediction.confidence >= 0.8
                        ? 'success'
                        : prediction.confidence >= 0.6
                          ? 'primary'
                          : 'secondary'
                    }
                  >
                    {prediction.confidence.toFixed(2)}
                  </Badge>
                </div>
                <div className="mt-2">
                  <p className="text-sm text-gray-600">
                    Prediction: {prediction.prediction.toFixed(2)}
                  </p>
                  <p className="text-xs text-gray-500">Model: {prediction.modelVersion}</p>
                </div>
              </Card>
            ))}
          </div>
        </div>

        {/* Opportunities */}
        <div>
          <h2 className="text-2xl font-bold mb-4">Betting Opportunities</h2>
          <div className="space-y-4">
            {opportunities.map(opportunity => (
              <Card
                key={opportunity.id}
                className="cursor-pointer hover:shadow-lg transition-shadow"
                onClick={() => handleOpportunityClick(opportunity)}
              >
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="font-semibold">{opportunity.marketType}</h3>
                    <p className="text-sm text-gray-600">Event ID: {opportunity.eventId}</p>
                  </div>
                  <Badge
                    variant={
                      opportunity.expectedValue >= 0.1
                        ? 'success'
                        : opportunity.expectedValue >= 0
                          ? 'primary'
                          : 'danger'
                    }
                  >
                    EV: {opportunity.expectedValue.toFixed(2)}
                  </Badge>
                </div>
                <div className="mt-2">
                  <p className="text-sm text-gray-600">
                    Prediction: {opportunity.prediction.toFixed(2)}
                  </p>
                  <p className="text-sm text-gray-600">
                    Kelly Fraction: {opportunity.kellyFraction.toFixed(2)}
                  </p>
                </div>
