  if (!prediction) {
    return (
      <div className="modern-card p-6">
        <p className="text-gray-500 dark:text-gray-400">No prediction available</p>
      </div>
    );
  }

  return (
    <div className="modern-card p-6 space-y-4">
      <div className="flex justify-between items-center">
        <h3 className="text-xl font-semibold">{prediction.eventName}</h3>
        <span
          className={`px-2 py-1 rounded text-sm ${
            connectionStatus === 'Connected'
              ? 'bg-green-100 text-green-800'
              : 'bg-yellow-100 text-yellow-800'
          }`}
        >
          {connectionStatus}
        </span>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <h4 className="font-medium mb-2">Prediction Details</h4>
          <div className="space-y-2">
            <p>Bet Type: {prediction.betType}</p>
            <p>Recommended Stake: {prediction.recommendedStake}%</p>
            <ConfidenceIndicator confidence={prediction.confidence} />
          </div>
        </div>

        <div>
          <h4 className="font-medium mb-2">Feature Impact</h4>
          <ShapValueDisplay shapValues={prediction.shapValues} />
        </div>
      </div>

      <PayoutPreviewPanel prediction={prediction} stake={prediction.recommendedStake} />
    </div>
  );
};

export default React.memo(RealtimePredictionDisplay);

import { useMemo } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

interface SHAPValue {
  feature: string;
  value: number;
}

interface SHAPChartProps {
  shapValues: SHAPValue[];
  className?: string;
}

export function SHAPChart({ shapValues, className = '' }: SHAPChartProps) {
  const sortedValues = useMemo(() => {
    return [...shapValues].sort((a, b) => Math.abs(b.value) - Math.abs(a.value));
  }, [shapValues]);

  const chartData = useMemo(() => {
    return {
      labels: sortedValues.map(v => v.feature),
      datasets: [
        {
          label: 'Feature Impact',
          data: sortedValues.map(v => v.value),
          backgroundColor: sortedValues.map(v =>
            v.value >= 0 ? 'rgba(34, 197, 94, 0.6)' : 'rgba(239, 68, 68, 0.6)'
          ),
          borderColor: sortedValues.map(v =>
            v.value >= 0 ? 'rgb(34, 197, 94)' : 'rgb(239, 68, 68)'
          ),
          borderWidth: 1,
        },
      ],
    };
  }, [sortedValues]);

  const options = {
    indexAxis: 'y' as const,
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
      title: {
        display: true,
        text: 'Feature Impact on Prediction',
        color: 'rgb(107, 114, 128)',
        font: {
          size: 16,
          weight: '500' as const,
        },
      },
      tooltip: {
        callbacks: {
          label: (context: any) => {
            const value = context.raw;
            return `Impact: ${value > 0 ? '+' : ''}${value.toFixed(3)}`;
          },
        },
      },
    },
    scales: {
      x: {
        grid: {
          color: 'rgba(107, 114, 128, 0.1)',
        },
        ticks: {
          color: 'rgb(107, 114, 128)',
        },
      },
      y: {
        grid: {
          display: false,
        },
        ticks: {
          color: 'rgb(107, 114, 128)',
          callback: (value: any) => {
            const label = chartData.labels[value];
            return label.length > 20 ? label.substring(0, 17) + '...' : label;
          },
        },
      },
    },
  };

  return (
    <div className={`h-[400px] w-full ${className}`}>
      <Bar data={chartData} options={options} />
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { UnifiedServiceRegistry } from '../../services/unified/UnifiedServiceRegistry';
import { UnifiedStateService } from '../../services/unified/UnifiedStateService';
import { UnifiedNotificationService } from '../../services/unified/UnifiedNotificationService';
import { UnifiedErrorService } from '../../services/unified/UnifiedErrorService';
import { UnifiedSettingsService } from '../../services/unified/UnifiedSettingsService';
import { Card, Button, Input, Select, Spinner, Toast, Modal, Badge } from '../ui/UnifiedUI';

interface UserProfile {
  id: string;
  email: string;
  username: string;
  firstName: string;
  lastName: string;
  phoneNumber: string;
  dateOfBirth: string;
  country: string;
  currency: string;
  timezone: string;
  language: string;
  notifications: {
    email: boolean;
    push: boolean;
    sms: boolean;
    marketing: boolean;
  };
  preferences: {
    theme: 'light' | 'dark' | 'system';
    oddsFormat: 'decimal' | 'fractional' | 'american';
    stakeLimit: number;
    autoConfirm: boolean;
  };
  security: {
    twoFactorEnabled: boolean;
    lastPasswordChange: string;
    lastLogin: string;
    loginHistory: Array<{
      date: string;
      ip: string;
      device: string;
    }>;
  };
}

interface ProfileForm {
  username: string;
  firstName: string;
  lastName: string;
  phoneNumber: string;
  dateOfBirth: string;
  country: string;
  currency: string;
  timezone: string;
  language: string;
}

interface ValidationError {
  field: string;
  message: string;
}

export const UnifiedProfile: React.FC = () => {
  // Initialize services
  const serviceRegistry = UnifiedServiceRegistry.getInstance();
  const stateService = serviceRegistry.getService<UnifiedStateService>('state');
  const notificationService =
    serviceRegistry.getService<UnifiedNotificationService>('notification');
  const errorService = serviceRegistry.getService<UnifiedErrorService>('error');
  const settingsService = serviceRegistry.getService<UnifiedSettingsService>('settings');

  // State
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [form, setForm] = useState<ProfileForm>({
    username: '',
    firstName: '',
    lastName: '',
    phoneNumber: '',
    dateOfBirth: '',
    country: '',
    currency: '',
    timezone: '',
    language: '',
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [validationErrors, setValidationErrors] = useState<ValidationError[]>([]);
  const [toast, setToast] = useState<{
    message: string;
    type: 'success' | 'error' | 'warning' | 'info';
  } | null>(null);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [showTwoFactorModal, setShowTwoFactorModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [activeTab, setActiveTab] = useState<'personal' | 'preferences' | 'security' | 'activity'>(
    'personal'
  );

  // Load profile data
  useEffect(() => {
    loadProfile();
  }, []);

  const loadProfile = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/user/profile');
      if (!response.ok) {
        throw new Error('Failed to load profile');
      }
      const data = await response.json();
      setProfile(data);
      setForm({
        username: data.username,
        firstName: data.firstName,
        lastName: data.lastName,
        phoneNumber: data.phoneNumber,
        dateOfBirth: data.dateOfBirth,
        country: data.country,
        currency: data.currency,
        timezone: data.timezone,
        language: data.language,
      });
    } catch (error) {
      handleError('Failed to load profile', error);
    } finally {
      setLoading(false);
    }
  };

  const validateForm = (): boolean => {
    const errors: ValidationError[] = [];

    // Username validation
    if (!form.username) {
      errors.push({ field: 'username', message: 'Username is required' });
    } else if (form.username.length < 3) {
      errors.push({ field: 'username', message: 'Username must be at least 3 characters' });
    }

    // Name validation
    if (!form.firstName) {
      errors.push({ field: 'firstName', message: 'First name is required' });
    }
    if (!form.lastName) {
      errors.push({ field: 'lastName', message: 'Last name is required' });
    }

    // Phone validation
    if (form.phoneNumber && !/^\+?[\d\s-]{10,}$/.test(form.phoneNumber)) {
      errors.push({ field: 'phoneNumber', message: 'Invalid phone number format' });
    }

    // Date of birth validation
    if (form.dateOfBirth) {
      const dob = new Date(form.dateOfBirth);
      const age = new Date().getFullYear() - dob.getFullYear();
      if (age < 18) {
        errors.push({ field: 'dateOfBirth', message: 'Must be at least 18 years old' });
      }
    }

    setValidationErrors(errors);
    return errors.length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    try {
      setSaving(true);
      const response = await fetch('/api/user/profile', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      });

      if (!response.ok) {
        throw new Error('Failed to update profile');
      }

      setToast({
        message: 'Profile updated successfully',
        type: 'success',
      });

      await loadProfile();
    } catch (error) {
      handleError('Failed to update profile', error);
    } finally {
      setSaving(false);
    }
  };

  const handlePasswordChange = async (currentPassword: string, newPassword: string) => {
    try {
      setSaving(true);
      const response = await fetch('/api/user/password', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ currentPassword, newPassword }),
      });

      if (!response.ok) {
        throw new Error('Failed to change password');
      }

      setToast({
        message: 'Password changed successfully',
        type: 'success',
      });
      setShowPasswordModal(false);
    } catch (error) {
      handleError('Failed to change password', error);
    } finally {
      setSaving(false);
    }
  };

  const handleTwoFactorToggle = async () => {
    try {
      setSaving(true);
      const response = await fetch('/api/user/2fa', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          enabled: !profile?.security.twoFactorEnabled,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update 2FA settings');
      }

      setToast({
        message: `Two-factor authentication ${profile?.security.twoFactorEnabled ? 'disabled' : 'enabled'} successfully`,
        type: 'success',
      });
      setShowTwoFactorModal(false);
      await loadProfile();
    } catch (error) {
      handleError('Failed to update 2FA settings', error);
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteAccount = async () => {
    try {
      setSaving(true);
      const response = await fetch('/api/user', {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete account');
      }

      setToast({
        message: 'Account deleted successfully',
        type: 'success',
      });
      // Redirect to logout or home page
    } catch (error) {
      handleError('Failed to delete account', error);
    } finally {
      setSaving(false);
    }
  };

  const handleError = (message: string, error: any) => {
    setError(message);
    setToast({ message, type: 'error' });
    errorService.handleError(error, {
      code: 'PROFILE_ERROR',
      source: 'UnifiedProfile',
      details: { message },
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Spinner size="large" />
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-3xl font-bold mb-8">Profile Settings</h1>

        {/* Navigation Tabs */}
        <div className="flex space-x-4 mb-8">
          <button
            className={`px-4 py-2 rounded-lg ${
              activeTab === 'personal'
                ? 'bg-primary-600 text-white'
                : 'bg-gray-100 dark:bg-gray-800'
            }`}
            onClick={() => setActiveTab('personal')}
          >
            Personal Info
          </button>
          <button
            className={`px-4 py-2 rounded-lg ${
              activeTab === 'preferences'
                ? 'bg-primary-600 text-white'
                : 'bg-gray-100 dark:bg-gray-800'
            }`}
            onClick={() => setActiveTab('preferences')}
          >
            Preferences
          </button>
          <button
            className={`px-4 py-2 rounded-lg ${
              activeTab === 'security'
                ? 'bg-primary-600 text-white'
                : 'bg-gray-100 dark:bg-gray-800'
            }`}
            onClick={() => setActiveTab('security')}
          >
            Security
          </button>
          <button
            className={`px-4 py-2 rounded-lg ${
              activeTab === 'activity'
                ? 'bg-primary-600 text-white'
                : 'bg-gray-100 dark:bg-gray-800'
            }`}
            onClick={() => setActiveTab('activity')}
          >
            Activity
          </button>
        </div>

        {/* Personal Information */}
        {activeTab === 'personal' && (
          <Card>
            <form className="space-y-6" onSubmit={handleSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Username
                  </label>
                  <Input
                    error={validationErrors.find(e => e.field === 'username')?.message}
                    value={form.username}
                    onChange={e => setForm({ ...form, username: e.target.value })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Email
                  </label>
                  <Input disabled className="bg-gray-50 dark:bg-gray-800" value={profile?.email} />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    First Name
                  </label>
                  <Input
                    error={validationErrors.find(e => e.field === 'firstName')?.message}
                    value={form.firstName}
                    onChange={e => setForm({ ...form, firstName: e.target.value })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Last Name
                  </label>
                  <Input
                    error={validationErrors.find(e => e.field === 'lastName')?.message}
                    value={form.lastName}
                    onChange={e => setForm({ ...form, lastName: e.target.value })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Phone Number
                  </label>
                  <Input
                    error={validationErrors.find(e => e.field === 'phoneNumber')?.message}
                    value={form.phoneNumber}
                    onChange={e => setForm({ ...form, phoneNumber: e.target.value })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Date of Birth
                  </label>
                  <Input
                    error={validationErrors.find(e => e.field === 'dateOfBirth')?.message}
                    type="date"
                    value={form.dateOfBirth}
                    onChange={e => setForm({ ...form, dateOfBirth: e.target.value })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Country
                  </label>
                  <Select
                    options={[
                      { value: 'US', label: 'United States' },
                      { value: 'UK', label: 'United Kingdom' },
                      { value: 'CA', label: 'Canada' },
                      // Add more countries
                    ]}
                    value={form.country}
                    onChange={e => setForm({ ...form, country: e.target.value })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Currency
                  </label>
                  <Select
                    options={[
                      { value: 'USD', label: 'USD ($)' },
                      { value: 'EUR', label: 'EUR (€)' },
                      { value: 'GBP', label: 'GBP (£)' },
                      // Add more currencies
                    ]}
                    value={form.currency}
                    onChange={e => setForm({ ...form, currency: e.target.value })}
                  />
                </div>
              </div>

              <div className="flex justify-end">
                <Button disabled={saving} type="submit" variant="primary">
                  {saving ? <Spinner size="small" /> : 'Save Changes'}
                </Button>
              </div>
            </form>
          </Card>
        )}

        {/* Preferences */}
        {activeTab === 'preferences' && (
          <Card>
            <div className="space-y-6">
              <div>
                <h3 className="text-lg font-medium mb-4">Theme</h3>
                <Select
                  options={[
                    { value: 'light', label: 'Light' },
                    { value: 'dark', label: 'Dark' },
                    { value: 'system', label: 'System' },
                  ]}
                  value={profile?.preferences.theme}
                  onChange={async e => {
                    try {
                      await settingsService.setSetting('theme', e.target.value);
                      await loadProfile();
                    } catch (error) {
                      handleError('Failed to update theme', error);
                    }
                  }}
                />
              </div>

              <div>
                <h3 className="text-lg font-medium mb-4">Odds Format</h3>
                <Select
                  options={[
                    { value: 'decimal', label: 'Decimal (2.50)' },
                    { value: 'fractional', label: 'Fractional (3/2)' },
                    { value: 'american', label: 'American (+150)' },
                  ]}
                  value={profile?.preferences.oddsFormat}
                  onChange={async e => {
                    try {
                      await settingsService.setSetting('oddsFormat', e.target.value);
                      await loadProfile();
                    } catch (error) {
                      handleError('Failed to update odds format', error);
                    }
                  }}
                />
              </div>

              <div>
                <h3 className="text-lg font-medium mb-4">Notifications</h3>
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <span>Email Notifications</span>
                    <input
                      checked={profile?.notifications.email}
                      className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                      type="checkbox"
                      onChange={async e => {
                        try {
                          await settingsService.setSetting('notifications.email', e.target.checked);
                          await loadProfile();
                        } catch (error) {
                          handleError('Failed to update email notifications', error);
                        }
                      }}
                    />
                  </div>
                  <div className="flex items-center justify-between">
                    <span>Push Notifications</span>
                    <input
                      checked={profile?.notifications.push}
                      className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                      type="checkbox"
                      onChange={async e => {
                        try {
                          await settingsService.setSetting('notifications.push', e.target.checked);
                          await loadProfile();
                        } catch (error) {
                          handleError('Failed to update push notifications', error);
                        }
                      }}
                    />
                  </div>
                  <div className="flex items-center justify-between">
                    <span>SMS Notifications</span>
                    <input
                      checked={profile?.notifications.sms}
                      className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                      type="checkbox"
                      onChange={async e => {
                        try {
                          await settingsService.setSetting('notifications.sms', e.target.checked);
                          await loadProfile();
                        } catch (error) {
                          handleError('Failed to update SMS notifications', error);
                        }
                      }}
                    />
                  </div>
                </div>
              </div>
            </div>
          </Card>
        )}

        {/* Security */}
        {activeTab === 'security' && (
          <Card>
            <div className="space-y-6">
              <div>
                <h3 className="text-lg font-medium mb-4">Password</h3>
                <p className="text-gray-600 dark:text-gray-400 mb-4">
                  Last changed:{' '}
                  {new Date(profile?.security.lastPasswordChange || '').toLocaleDateString()}
                </p>
                <Button variant="secondary" onClick={() => setShowPasswordModal(true)}>
                  Change Password
                </Button>
              </div>

              <div>
                <h3 className="text-lg font-medium mb-4">Two-Factor Authentication</h3>
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-600 dark:text-gray-400">
                      {profile?.security.twoFactorEnabled
                        ? 'Two-factor authentication is enabled'
                        : 'Two-factor authentication is disabled'}
                    </p>
                  </div>
                  <Button
                    variant={profile?.security.twoFactorEnabled ? 'danger' : 'primary'}
                    onClick={() => setShowTwoFactorModal(true)}
                  >
                    {profile?.security.twoFactorEnabled ? 'Disable 2FA' : 'Enable 2FA'}
                  </Button>
                </div>
              </div>

              <div>
                <h3 className="text-lg font-medium mb-4">Login History</h3>
                <div className="space-y-4">
                  {profile?.security.loginHistory.map((login, index) => (
                    <div
                      key={index}
                      className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800 rounded-lg"
                    >
                      <div>
                        <p className="font-medium">{login.device}</p>
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                          {new Date(login.date).toLocaleString()}
                        </p>
                      </div>
                      <p className="text-sm text-gray-600 dark:text-gray-400">{login.ip}</p>
                    </div>
                  ))}
                </div>
              </div>

              <div>
                <h3 className="text-lg font-medium mb-4 text-red-600">Danger Zone</h3>
                <Button variant="danger" onClick={() => setShowDeleteModal(true)}>
                  Delete Account
                </Button>
              </div>
            </div>
          </Card>
        )}

        {/* Activity */}
        {activeTab === 'activity' && (
          <Card>
            <div className="space-y-6">
              <div>
                <h3 className="text-lg font-medium mb-4">Recent Activity</h3>
                <div className="space-y-4">{/* Add activity history here */}</div>
              </div>
            </div>
          </Card>
        )}
      </div>

      {/* Password Change Modal */}
      <Modal
        isOpen={showPasswordModal}
        title="Change Password"
        onClose={() => setShowPasswordModal(false)}
      >
        <div className="space-y-4">
          <Input label="Current Password" placeholder="Enter current password" type="password" />
          <Input label="New Password" placeholder="Enter new password" type="password" />
          <Input label="Confirm New Password" placeholder="Confirm new password" type="password" />
          <div className="flex justify-end space-x-4">
            <Button variant="secondary" onClick={() => setShowPasswordModal(false)}>
              Cancel
            </Button>
            <Button
              disabled={saving}
              variant="primary"
              onClick={() => handlePasswordChange('', '')}
            >
              {saving ? <Spinner size="small" /> : 'Change Password'}
            </Button>
          </div>
        </div>
      </Modal>

      {/* Two-Factor Modal */}
      <Modal
        isOpen={showTwoFactorModal}
        title={profile?.security.twoFactorEnabled ? 'Disable 2FA' : 'Enable 2FA'}
        onClose={() => setShowTwoFactorModal(false)}
      >
        <div className="space-y-4">
          <p className="text-gray-600">
            {profile?.security.twoFactorEnabled
              ? 'Are you sure you want to disable two-factor authentication? This will make your account less secure.'
              : 'Scan the QR code with your authenticator app to enable two-factor authentication.'}
          </p>
          {!profile?.security.twoFactorEnabled && (
            <div className="flex justify-center">{/* Add QR code here */}</div>
          )}
          <div className="flex justify-end space-x-4">
            <Button variant="secondary" onClick={() => setShowTwoFactorModal(false)}>
              Cancel
            </Button>
            <Button
              disabled={saving}
              variant={profile?.security.twoFactorEnabled ? 'danger' : 'primary'}
              onClick={handleTwoFactorToggle}
            >
              {saving ? (
                <Spinner size="small" />
              ) : profile?.security.twoFactorEnabled ? (
                'Disable 2FA'
              ) : (
                'Enable 2FA'
              )}
            </Button>
          </div>
        </div>
      </Modal>

      {/* Delete Account Modal */}
      <Modal
        isOpen={showDeleteModal}
        title="Delete Account"
        onClose={() => setShowDeleteModal(false)}
      >
        <div className="space-y-4">
          <p className="text-red-600">
            Warning: This action cannot be undone. All your data will be permanently deleted.
          </p>
          <Input
            label="Confirm Password"
            placeholder="Enter your password to confirm"
            type="password"
          />
          <div className="flex justify-end space-x-4">
            <Button variant="secondary" onClick={() => setShowDeleteModal(false)}>
              Cancel
            </Button>
            <Button disabled={saving} variant="danger" onClick={handleDeleteAccount}>
              {saving ? <Spinner size="small" /> : 'Delete Account'}
            </Button>
          </div>
        </div>
      </Modal>

      {/* Toast Notifications */}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

import React from 'react';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';
import Grid from '@mui/material/Grid';
import CircularProgress from '@mui/material/CircularProgress';
import Alert from '@mui/material/Alert';
import Select from '@mui/material/Select';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import InputLabel from '@mui/material/InputLabel';
import Slider from '@mui/material/Slider';
import TextField from '@mui/material/TextField';
import { useRiskProfile } from '../../hooks/useRiskProfile';
import { RiskProfile } from '../../types/core';

export const RiskProfileManager: React.FC = () => {
  const { activeProfile, profiles, isLoading, error, updateProfile, setActiveProfile } =
    useRiskProfile();

  const [selectedProfile, setSelectedProfile] = React.useState<string>('');
  const [isEditing, setIsEditing] = React.useState(false);
  const [editedProfile, setEditedProfile] = React.useState(activeProfile);

  React.useEffect(() => {
    if (activeProfile) {
      setSelectedProfile(activeProfile.id);
      setEditedProfile(activeProfile);
    }
  }, [activeProfile]);

  const handleProfileSelect = async (profileId: string) => {
    setSelectedProfile(profileId);
    await setActiveProfile(profileId);
  };

  const handleEdit = () => {
    setIsEditing(true);
  };

  const handleSave = async () => {
    if (editedProfile) {
      const success = await updateProfile(editedProfile);
      if (success) {
        setIsEditing(false);
      }
    }
  };

  const handleCancel = () => {
    setEditedProfile(activeProfile);
    setIsEditing(false);
  };

  const handleProfileChange = (field: keyof RiskProfile, value: number) => {
    if (editedProfile) {
      setEditedProfile(prev => ({
        ...prev!,
        [field]: value,
        updatedAt: Date.now(),
      }));
    }
  };

  if (isLoading) {
    return (
      <Box alignItems="center" display="flex" justifyContent="center" minHeight="200px">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2 }}>
        Error loading risk profiles: {error.message}
      </Alert>
    );
  }

  return (
    <Box>
      <Typography gutterBottom variant="h5">
        Risk Profile Management
      </Typography>

      <Grid container spacing={3}>
        <Grid item md={4} xs={12}>
          <Card>
            <CardContent>
              <FormControl fullWidth sx={{ mb: 2 }}>
                <InputLabel>Select Profile</InputLabel>
                <Select
                  label="Select Profile"
                  value={selectedProfile}
                  onChange={e => handleProfileSelect(e.target.value)}
                >
                  {profiles.map(profile => (
                    <MenuItem key={profile.id} value={profile.id}>
                      {profile.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>

              {activeProfile && (
                <Box>
                  <Typography gutterBottom variant="h6">
                    {activeProfile.name}
                  </Typography>

                  {isEditing ? (
                    <Box>
                      <Typography gutterBottom>Maximum Stake</Typography>
                      <Slider
                        max={1000}
                        min={10}
                        step={10}
                        sx={{ mb: 2 }}
                        value={editedProfile?.maxStake || 0}
                        valueLabelDisplay="auto"
                        onChange={(_, value) => handleProfileChange('maxStake', value as number)}
                      />

                      <Typography gutterBottom>Minimum Stake</Typography>
                      <Slider
                        max={100}
                        min={1}
                        step={1}
                        sx={{ mb: 2 }}
                        value={editedProfile?.minStake || 0}
                        valueLabelDisplay="auto"
                        onChange={(_, value) => handleProfileChange('minStake', value as number)}
                      />

                      <Typography gutterBottom>Confidence Threshold</Typography>
                      <Slider
                        max={0.95}
                        min={0.5}
                        step={0.05}
                        sx={{ mb: 2 }}
                        value={editedProfile?.confidenceThreshold || 0}
                        valueLabelDisplay="auto"
                        onChange={(_, value) =>
                          handleProfileChange('confidenceThreshold', value as number)
                        }
                      />

                      <Box display="flex" gap={1} mt={2}>
                        <Button fullWidth color="primary" variant="contained" onClick={handleSave}>
                          Save Changes
                        </Button>
                        <Button fullWidth variant="outlined" onClick={handleCancel}>
                          Cancel
                        </Button>
                      </Box>
                    </Box>
                  ) : (
                    <Box>
                      <Typography gutterBottom color="text.secondary" variant="body2">
                        Maximum Stake: ${activeProfile.maxStake}
                      </Typography>
                      <Typography gutterBottom color="text.secondary" variant="body2">
                        Minimum Stake: ${activeProfile.minStake}
                      </Typography>
                      <Typography gutterBottom color="text.secondary" variant="body2">
                        Confidence Threshold: {(activeProfile.confidenceThreshold * 100).toFixed(0)}
                        %
                      </Typography>
                      <Button
                        fullWidth
                        color="primary"
                        sx={{ mt: 2 }}
                        variant="contained"
                        onClick={handleEdit}
                      >
                        Edit Profile
                      </Button>
                    </Box>
                  )}
                </Box>
              )}
            </CardContent>
          </Card>
        </Grid>

        <Grid item md={8} xs={12}>
          <Card>
            <CardContent>
              <Typography gutterBottom variant="h6">
                Risk Profile Statistics
              </Typography>
              {activeProfile && (
                <Grid container spacing={2}>
                  <Grid item xs={6}>
                    <Typography color="text.secondary" variant="body2">
                      Maximum Exposure
                    </Typography>
                    <Typography variant="h6">${activeProfile.maxExposure}</Typography>
                  </Grid>
                  <Grid item xs={6}>
                    <Typography color="text.secondary" variant="body2">
                      Volatility Threshold
                    </Typography>
                    <Typography variant="h6">
                      {(activeProfile.volatilityThreshold * 100).toFixed(0)}%
                    </Typography>
                  </Grid>
                  <Grid item xs={6}>
                    <Typography color="text.secondary" variant="body2">
                      Stop Loss
                    </Typography>
                    <Typography variant="h6">
                      {(activeProfile.stopLossPercentage * 100).toFixed(0)}%
                    </Typography>
                  </Grid>
                  <Grid item xs={6}>
                    <Typography color="text.secondary" variant="body2">
                      Take Profit
                    </Typography>
                    <Typography variant="h6">
                      {(activeProfile.takeProfitPercentage * 100).toFixed(0)}%
                    </Typography>
                  </Grid>
                </Grid>
              )}
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

import React, { useState, useEffect } from 'react';
import { UnifiedServiceRegistry } from '../../services/unified/UnifiedServiceRegistry';
