                      handleConfigChange('riskProfile', {
                        ...config.riskProfile,
                        maxDrawdown: value,
                      })
                    }
                  />
                  <div className="flex justify-between text-sm text-gray-600 dark:text-gray-400">
                    <span>5%</span>
                    <span>Current: {config.riskProfile.maxDrawdown}%</span>
                    <span>50%</span>
