    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    BarElement,
    Title,
    Tooltip,
    Legend,
    Filler
} from 'chart.js';

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    BarElement,
    Title,
    Tooltip,
    Legend,
    Filler
);

interface ChartData {
    labels: string[];
    datasets: {
        label: string;
        data: number[];
        backgroundColor?: string | string[];
        borderColor?: string | string[];
        fill?: boolean;
        tension?: number;
    }[];
}

interface AdvancedChartsProps {
    data: ChartData;
    type: 'line' | 'bar';
    title?: string;
    height?: number;
    options?: any;
}

/**
 * AdvancedCharts renders a high-performance, accessible chart using Chart.js.
 * - Wrapped in <figure> with <figcaption> for semantic context
 * - ARIA label and role for screen readers
 * - Keyboard accessible (tabIndex)
 */
export const AdvancedCharts: React.FC<AdvancedChartsProps> = React.memo(({
    data,
    type,
    title,
    height = 300,
    options = {}
}) => {
    const defaultOptions = React.useMemo(() => ({
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
            legend: {
                position: 'top' as const,
                labels: {
                    color: '#fff',
                    font: {
                        family: 'Inter'
                    }
                }
            },
            title: {
                display: !!title,
                text: title,
                color: '#fff',
                font: {
                    family: 'Inter',
                    size: 16
                }
            },
            tooltip: {
                backgroundColor: 'rgba(0, 0, 0, 0.8)',
                titleColor: '#fff',
                bodyColor: '#fff',
                borderColor: 'rgba(255, 255, 255, 0.1)',
                borderWidth: 1
            }
        },
        scales: {
            x: {
                grid: {
                    color: 'rgba(255, 255, 255, 0.1)'
                },
                ticks: {
                    color: '#fff'
                }
            },
            y: {
                grid: {
                    color: 'rgba(255, 255, 255, 0.1)'
                },
                ticks: {
                    color: '#fff'
                }
            }
        }
    }), []);

    return (
        <figure style={{ height }}>
            {title && <figcaption style={{ color: '#fff', fontFamily: 'Inter', fontSize: 16 }}>{title}</figcaption>}
            <Chart
                type={type}
                data={data}
                options={{ ...defaultOptions, ...options }}
                aria-label={title || 'Chart'}
                role="img"
                tabIndex={0}
            />
        </figure>
    );
});

export const PredictionConfidenceChart = React.memo(({ predictions }: { predictions: { confidence: number; label: string; }[] }) => {
