import React from 'react';
import { Responsive, WidthProvider } from 'react-grid-layout';
import 'react-grid-layout/css/styles.css';
import 'react-resizable/css/styles.css';

const ResponsiveGridLayout = WidthProvider(Responsive);

interface GridProps {
  children: React.ReactNode;
  className?: string;
  layout?: any;
  onLayoutChange?: (layout: any) => void;
}

export const Grid: React.FC<GridProps> = ({
  children,
  className = '',
  layout = {},
  onLayoutChange,
}) => {
  const defaultLayout = {
    lg: [
      { i: 'a', x: 0, y: 0, w: 1, h: 2 },
      { i: 'b', x: 1, y: 0, w: 1, h: 2 },
      { i: 'c', x: 2, y: 0, w: 1, h: 2 },
    ],
    md: [
      { i: 'a', x: 0, y: 0, w: 1, h: 2 },
      { i: 'b', x: 1, y: 0, w: 1, h: 2 },
      { i: 'c', x: 0, y: 2, w: 1, h: 2 },
    ],
    sm: [
      { i: 'a', x: 0, y: 0, w: 1, h: 2 },
      { i: 'b', x: 0, y: 2, w: 1, h: 2 },
      { i: 'c', x: 0, y: 4, w: 1, h: 2 },
    ],
  };

  const breakpoints = { lg: 1200, md: 996, sm: 768 };
  const cols = { lg: 3, md: 2, sm: 1 };

  return (
    <ResponsiveGridLayout
      isDraggable
      isResizable
      breakpoints={breakpoints}
      className={className}
      cols={cols}
      layouts={layout || defaultLayout}
      margin={[16, 16]}
      rowHeight={100}
      onLayoutChange={onLayoutChange}
    >
      {React.Children.map(children, (child, index) => (
        <div key={String.fromCharCode(97 + index)}>{child}</div>
      ))}
    </ResponsiveGridLayout>
  );
};

import React, { useEffect, useState } from 'react';
import WebSocketManager from '@/services/unified/WebSocketManager';
import { ModelConfidenceIndicator } from './ml-status-indicators';

interface RealTimeMetricsProps {
    initialMetrics?: {
        predictions: number;
        opportunities: number;
        activeModels: number;
        totalProfit: number;
    };
}

export const RealTimeMetrics: React.FC<RealTimeMetricsProps> = ({
    initialMetrics = {
        predictions: 0,
        opportunities: 0,
        activeModels: 0,
        totalProfit: 0
    }
}) => {
    const [metrics, setMetrics] = useState(initialMetrics);

    useEffect(() => {
        WebSocketManager.instance.subscribe('metrics:update', (data) => {
            setMetrics(prev => ({
                ...prev,
                ...data
            }));
        });

        return () => {
            WebSocketManager.instance.unsubscribe('metrics:update');
        };
    }, []);

    return (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            <MetricCard
                title="Active Predictions"
                value={metrics.predictions}
                icon="📊"
                trend={metrics.predictions > initialMetrics.predictions ? 'up' : 'down'}
            />
            <MetricCard
                title="Betting Opportunities"
                value={metrics.opportunities}
                icon="🎯"
                trend={metrics.opportunities > initialMetrics.opportunities ? 'up' : 'down'}
            />
            <MetricCard
                title="Active Models"
                value={metrics.activeModels}
                icon="🤖"
                trend={metrics.activeModels > initialMetrics.activeModels ? 'up' : 'down'}
            />
            <MetricCard
                title="Total Profit"
                value={`$${metrics.totalProfit.toFixed(2)}`}
                icon="💰"
                trend={metrics.totalProfit > initialMetrics.totalProfit ? 'up' : 'down'}
                isMonetary
            />
        </div>
    );
};

interface MetricCardProps {
    title: string;
    value: number | string;
    icon: string;
    trend: 'up' | 'down';
    isMonetary?: boolean;
}

const MetricCard: React.FC<MetricCardProps> = ({
    title,
    value,
    icon,
    trend,
    isMonetary
}) => {
    const getTrendColor = (t: string) => {
        return t === 'up' ? 'text-success-500' : 'text-error-500';
    };

    const getTrendIcon = (t: string) => {
        return t === 'up' ? '↑' : '↓';
    };

    return (
        <div className="glass-premium p-4 rounded-xl">
            <div className="flex items-center justify-between mb-2">
                <div className="text-2xl">{icon}</div>
                <div className={`text-sm font-medium ${getTrendColor(trend)}`}>
                    {getTrendIcon(trend)}
                </div>
            </div>
            <div className="text-sm text-gray-500">{title}</div>
            <div className={`text-2xl font-bold ${isMonetary ? 'text-success-500' : ''}`}>
                {value}
            </div>
        </div>
    );
};

import ErrorBoundary from './ErrorBoundary';
import React from 'react';

interface WithErrorBoundaryOptions {
  fallback?: React.ReactNode;
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
}

export function withErrorBoundary<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  options: WithErrorBoundaryOptions = {}
) {
  const displayName = WrappedComponent.displayName || WrappedComponent.name || 'Component';

  function WithErrorBoundary(props: P) {
    return (
      <ErrorBoundary>
        <WrappedComponent {...props} />
      </ErrorBoundary>
    );
  }

  WithErrorBoundary.displayName = `withErrorBoundary(${displayName})`;

  return WithErrorBoundary;
}

