      console.warn('TheOddsAdapter not initialized: VITE_THEODDS_API_KEY is missing.');
    }

    // Configure and register SportsRadarAdapter
    const sportsRadarApiKey = import.meta.env.VITE_SPORTRADAR_API_KEY;
    if (sportsRadarApiKey) {
      const sportsRadarAdapter = new SportsRadarAdapter({
        apiKey: sportsRadarApiKey,
        baseUrl: 'https://api.sportradar.us',
        cacheTimeout: 300000,
      });
      this.registerDataSource(sportsRadarAdapter);
    } else {
      console.warn('SportsRadarAdapter not initialized: VITE_SPORTRADAR_API_KEY is missing.');
    }

    // Configure and register DailyFantasyAdapter
    const dailyFantasyApiKey = import.meta.env.VITE_DAILYFANTASY_API_KEY;
    if (dailyFantasyApiKey) {
      const dailyFantasyAdapter = new DailyFantasyAdapter({
        apiKey: dailyFantasyApiKey,
        baseUrl: 'https://api.example.com/dailyfantasy',
        cacheTimeout: 300000,
      });
      this.registerDataSource(dailyFantasyAdapter);
    } else {
      console.warn('DailyFantasyAdapter not initialized: VITE_DAILYFANTASY_API_KEY is missing.');
    }

    // Configure and register PrizePicksAdapter
    const prizePicksApiKey = import.meta.env.VITE_PRIZEPICKS_API_KEY;
    if (prizePicksApiKey) {
      const prizePicksAdapter = new PrizePicksAdapter({
        apiKey: prizePicksApiKey,
        baseUrl: import.meta.env.VITE_PRIZEPICKS_API_URL || 'https://api.prizepicks.com',
        cacheTimeout: 300000, // 5 minutes cache
      });
      this.registerDataSource(prizePicksAdapter);
    } else {
      console.warn('PrizePicksAdapter not initialized: VITE_PRIZEPICKS_API_KEY is missing.');
    }

    this.setupEventListeners();
  }

  static getInstance(): DataIntegrationHub {
    if (!DataIntegrationHub.instance) {
      DataIntegrationHub.instance = new DataIntegrationHub();
    }
    return DataIntegrationHub.instance;
  }

  private initializeIntegratedData(): IntegratedData {
    return {
      timestamp: Date.now(),
      projections: {},
      sentiment: {},
      odds: {},
      injuries: {},
      trends: {},
    };
  }

  public registerDataSource(source: DataSource<any>): void {
    this.dataSources.set(source.id, source);
    this.metrics.set(source.id, {
      latency: [],
      errorRate: 0,
      lastUpdate: 0,
      dataQuality: 0,
    });
  }

  public async startRealTimeSync(): Promise<void> {
    this.isRealTimeEnabled = true;
    await this.synchronizeAll();
  }

  public stopRealTimeSync(): void {
    this.isRealTimeEnabled = false;
  }

  public setSyncInterval(milliseconds: number): void {
    this.syncInterval = milliseconds;
  }

  private async synchronizeAll(): Promise<void> {
    const traceId = this.performanceMonitor.startTrace('data-sync');

    try {
      const syncPromises = Array.from(this.dataSources.entries()).map(async ([id, source]) => {
        const startTime = Date.now();
        try {
          const data = await source.fetch();
          this.updateSourceMetrics(id, {
            latency: [Date.now() - startTime],
            errorRate: 0,
            lastUpdate: Date.now(),
            dataQuality: 0.8,
          });
          return { id, data, error: null } as const;
        } catch (error) {
          this.updateSourceMetrics(id, {
            latency: [Date.now() - startTime],
            errorRate: 1,
            lastUpdate: Date.now(),
            dataQuality: 0.0,
          });
          return {
            id,
            data: null,
            error: error instanceof Error ? error : new Error(String(error)),
          } as const;
        }
      });

      const results = await Promise.all(syncPromises);
      await this.integrateData(results);

      if (this.isRealTimeEnabled) {
        setTimeout(() => this.synchronizeAll(), this.syncInterval);
      }

      this.performanceMonitor.endTrace(traceId);
    } catch (error) {
      this.performanceMonitor.endTrace(traceId, error as Error);
      throw error;
    }
  }

  private updateSourceMetrics(sourceId: string, metrics: DataSourceMetrics): void {
    if (!this.metrics.has(sourceId)) {
      this.metrics.set(sourceId, metrics);
    } else {
      const existingMetrics = this.metrics.get(sourceId)!;
      this.metrics.set(sourceId, {
        ...existingMetrics,
        latency: [...existingMetrics.latency, ...metrics.latency].slice(-10),
        errorRate: metrics.errorRate,
        lastUpdate: metrics.lastUpdate,
        dataQuality: metrics.dataQuality,
      });
    }
    this.emitMetricsUpdate(sourceId);
  }

  private async integrateData(
    results: Array<{ id: string; data: any; error: Error | null }>
  ): Promise<void> {
    const newData = this.initializeIntegratedData();
    const correlations: DataCorrelation[] = [];

    for (const result of results) {
      if (result.error) continue;

      // Cache the raw data with metadata
      const confidence = this.calculateDataConfidence(result.data);
      this.dataCache.set(result.id, {
        data: result.data,
        timestamp: Date.now(),
        correlations: [], // Placeholder, to be updated later if correlation analysis is run on this source
        confidence,
      });

      this.updateIntegratedDataSource(newData, result);
    }

    // After all individual sources are processed and cached, perform cross-source analysis
    // For example, calculate correlations if multiple projection sources exist
    // this.analyzeAndCacheCorrelations(results.filter(r => !r.error).map(r => ({id: r.id, data: r.data })));

    this.integratedData = newData;
    this.eventBus.emit('data:integrated', {
      integratedData: this.integratedData,
      timestamp: Date.now(),
    });
  }

  private calculateDataConfidence(data: any): number {
    // Basic confidence: presence of data and key fields
    if (!data) return 0;
    if (data.projections && Array.isArray(data.projections) && data.projections.length > 0)
      return 0.75;
    if (data.sentiment && Object.keys(data.sentiment).length > 0) return 0.7;
    // Add more sophisticated checks based on data quality, recency, etc.
    return 0.5; // Default baseline confidence
  }

  // Placeholder for a more sophisticated correlation analysis if needed
  // private analyzeAndCacheCorrelations(activeDataSources: Array<{id: string, data: any }>): void {
  //   // ... implementation ...
  // }

  private updateIntegratedDataSource(
    newData: IntegratedData,
    result: { id: string; data: any; error: Error | null }
  ): void {
    if (result.error || !result.data) return;

    switch (result.id) {
      case 'daily-fantasy': // Assuming DailyFantasyAdapter.id is 'daily-fantasy'
        this.integrateProjections(newData, result.data as DailyFantasyData);
        break;
      case 'prize-picks': // Assuming PrizePicksAdapter.id is 'prize-picks'
        this.integratePrizePicksProjections(newData, result.data as PrizePicksData);
        break;
      case 'social-sentiment': // Assuming SocialSentimentAdapter.id is 'social-sentiment'
        this.integrateSentiment(newData, result.data as SocialSentimentData[]); // Assuming it's an array
        break;
      case 'sports-radar': // Assuming SportsRadarAdapter.id is 'sports-radar'
        this.integrateSportsData(newData, result.data as SportsRadarData);
        break;
      case 'the-odds': // Assuming TheOddsAdapter.id is 'the-odds'
        this.integrateOdds(newData, result.data as TheOddsData);
        break;
      // Add cases for other adapters like ESPN if they have specific integration logic
      default:
        console.warn(
          `DataIntegrationHub: No specific integration logic for source ID: ${result.id}`
        );
        // Attempt a generic integration or log/ignore
        break;
    }
  }

  private integrateProjections(newData: IntegratedData, dailyFantasyData: DailyFantasyData): void {
    dailyFantasyData.projections.forEach(projection => {
      const playerId = projection.name.toLowerCase().replace(/\s+/g, '-');
      if (!newData.projections[playerId]) {
        newData.projections[playerId] = {
          stats: {},
          confidence: 0.8,
          lastUpdated: Date.now(),
        };
      }

      // Map DailyFantasy stats to our internal format
      newData.projections[playerId].stats = {
        points: projection.pts,
        rebounds: projection.reb,
        assists: projection.ast,
        steals: projection.stl,
        blocks: projection.blk,
        threePointers: projection.three_pt,
        minutes: projection.min,
      };
      newData.projections[playerId].lastUpdated = Date.now();
    });
  }

  private integratePrizePicksProjections(
    newData: IntegratedData,
    prizePicksData: PrizePicksData
  ): void {
    prizePicksData.projections.forEach((proj: PrizePicksProjection) => {
      if (!newData.projections[proj.playerId]) {
        newData.projections[proj.playerId] = {
          stats: {},
          confidence: 0.8,
          lastUpdated: Date.now(),
        };
      }

      // Map PrizePicks stat types to our internal format
      const statType = proj.statType.toLowerCase();
      newData.projections[proj.playerId].stats[statType] = proj.line;
      newData.projections[proj.playerId].lastUpdated = Date.now();
    });
  }

  private integrateSentiment(
    newData: IntegratedData,
    sentimentDataArray: SocialSentimentData[]
  ): void {
    sentimentDataArray.forEach(data => {
      newData.sentiment[data.player] = data;
    });
  }

  private integrateSportsData(newData: IntegratedData, sportsData: SportsRadarData): void {
    sportsData.games.forEach(game => {
      game.players.forEach(player => {
        if (player.injuries.length > 0) {
          newData.injuries[player.id] = {
            status: player.injuries[0].status,
            details: player.injuries[0].type,
            impact: this.calculateInjuryImpact(player.injuries[0]),
            timeline: player.injuries[0].startDate,
          };
        }
      });
    });
  }

  private integrateOdds(newData: IntegratedData, oddsData: TheOddsData): void {
    oddsData.events.forEach(event => {
      const markets: Record<string, number> = {};
      event.bookmakers.forEach(bookmaker => {
        bookmaker.markets.forEach(market => {
          market.outcomes.forEach(outcome => {
            markets[`${market.key}_${outcome.name}`] = outcome.price;
          });
        });
      });

      newData.odds[event.id] = {
        markets,
        movement: this.calculateOddsMovement(event.id, markets),
      };
    });
  }

  private calculateInjuryImpact(injury: { status: string; type: string }): number {
    const statusImpact =
      {
        out: 1,
        doubtful: 0.75,
        questionable: 0.5,
        probable: 0.25,
      }[injury.status.toLowerCase()] ?? 0;

    return statusImpact;
  }

  private calculateOddsMovement(
    eventId: string,
    currentMarkets: Record<string, number>
  ): { direction: 'up' | 'down' | 'stable'; magnitude: number } {
    const previousData = this.integratedData.odds[eventId];
    if (!previousData) {
      return { direction: 'stable', magnitude: 0 };
    }

    const avgCurrentPrice =
      Object.values(currentMarkets).reduce((a, b) => a + b, 0) /
      Object.values(currentMarkets).length;
    const avgPreviousPrice =
      Object.values(previousData.markets).reduce((a, b) => a + b, 0) /
      Object.values(previousData.markets).length;

    const difference = avgCurrentPrice - avgPreviousPrice;
    const magnitude = Math.abs(difference);

    if (magnitude < 0.05) return { direction: 'stable', magnitude };
    return {
      direction: difference > 0 ? 'up' : 'down',
      magnitude,
    };
  }

  private analyzeTrendsWithCorrelations(
    newData: IntegratedData,
    correlations: DataCorrelation[]
  ): void {
    // Analyze projection trends
    this.analyzeProjectionTrends(newData);

    // Analyze sentiment trends
    this.analyzeSentimentTrends(newData);

    // Analyze market trends
    this.analyzeMarketTrends(newData);

    // Analyze correlation trends
    this.analyzeCorrelationTrends(newData, correlations);
  }

  private analyzeProjectionTrends(newData: IntegratedData): void {
    Object.entries(newData.projections).forEach(([playerId, projection]) => {
      Object.entries(projection.stats).forEach(([metric, value]) => {
        const trendKey = `${playerId}_${metric}`;
        const previousValue = this.integratedData.projections[playerId]?.stats[metric];

        if (previousValue !== undefined) {
          const change = value - previousValue;
          const significance = this.calculateTrendSignificance(change, previousValue);

          newData.trends[trendKey] = {
            value,
            change,
            significance,
          };
        }
      });
    });
  }

  private analyzeSentimentTrends(newData: IntegratedData): void {
    Object.entries(newData.sentiment).forEach(([playerId, sentiment]) => {
      const trendKey = `${playerId}_sentiment`;
      const previousSentiment = this.integratedData.sentiment[playerId];

      if (previousSentiment) {
        const change = sentiment.sentiment.score - previousSentiment.sentiment.score;
        const volumeChange = sentiment.sentiment.volume - previousSentiment.sentiment.volume;
        const significance = this.calculateTrendSignificance(
          change,
          previousSentiment.sentiment.score
        );

        newData.trends[trendKey] = {
          value: sentiment.sentiment.score,
          change,
          significance: significance * (1 + Math.min(1, volumeChange / 1000)),
        };
      }
    });
  }

  private analyzeMarketTrends(newData: IntegratedData): void {
    Object.entries(newData.odds).forEach(([eventId, odds]) => {
      Object.entries(odds.markets).forEach(([market, price]) => {
        const trendKey = `${eventId}_${market}`;
        const previousPrice = this.integratedData.odds[eventId]?.markets[market];

        if (previousPrice !== undefined) {
          const change = price - previousPrice;
          const significance = this.calculateTrendSignificance(change, previousPrice);

          newData.trends[trendKey] = {
            value: price,
            change,
            significance,
          };
        }
      });
    });
  }

  private analyzeCorrelationTrends(newData: IntegratedData, correlations: DataCorrelation[]): void {
    // Analyze correlations between different data points
    Object.entries(newData.projections).forEach(([playerId, projection]) => {
      const sentiment = newData.sentiment[playerId];
      const injuries = newData.injuries[playerId];

      if (sentiment && projection) {
        const correlationKey = `${playerId}_sentiment_correlation`;
        const sentimentImpact = sentiment.sentiment.score * (sentiment.sentiment.volume / 1000);
        const performanceCorrelation = this.calculateCorrelation(Object.values(projection.stats), [
          sentimentImpact,
        ]);

        newData.trends[correlationKey] = {
          value: performanceCorrelation,
          change: 0, // We don't track change for correlations
          significance: Math.abs(performanceCorrelation),
        };
      }

      if (injuries) {
        const injuryKey = `${playerId}_injury_impact`;
        newData.trends[injuryKey] = {
          value: injuries.impact,
          change: 0,
          significance: injuries.impact,
        };
      }
    });

    // Analyze correlations with other data sources
    for (const correlation of correlations) {
      const sourceA = correlation.sourceA;
      const sourceB = correlation.sourceB;
      const correlationValue = correlation.correlation;
      const significance = correlation.significance;

      const trendKey = `${sourceA}_${sourceB}_correlation`;
      newData.trends[trendKey] = {
        value: correlationValue,
        change: 0,
        significance: significance,
      };
    }
  }

  private calculateTrendSignificance(change: number, baseValue: number): number {
    if (baseValue === 0) return change === 0 ? 0 : 1;
    const percentageChange = Math.abs(change / baseValue);
    return Math.min(1, percentageChange);
  }

  private calculateCorrelation(series1: number[], series2: number[]): number {
    if (series1.length !== series2.length || series1.length === 0) return 0;

    const mean1 = series1.reduce((a, b) => a + b, 0) / series1.length;
    const mean2 = series2.reduce((a, b) => a + b, 0) / series2.length;

    const variance1 = series1.reduce((a, b) => a + Math.pow(b - mean1, 2), 0);
    const variance2 = series2.reduce((a, b) => a + Math.pow(b - mean2, 2), 0);

    if (variance1 === 0 || variance2 === 0) return 0;

    const covariance = series1.reduce((a, b, i) => {
      return a + (b - mean1) * (series2[i] - mean2);
    }, 0);

    return covariance / Math.sqrt(variance1 * variance2);
  }

  private setupEventListeners(): void {
    this.eventBus.on('dataSource:error', async event => {
      const sourceId = event.sourceId;
      const metrics = this.metrics.get(sourceId) || {
        latency: [],
        errorRate: 0,
        lastUpdate: 0,
        dataQuality: 0,
      };
      this.updateSourceMetrics(sourceId, {
        ...metrics,
        errorRate: metrics.errorRate + 0.1,
        dataQuality: metrics.dataQuality * 0.9,
      });
    });

    this.eventBus.on('cache:clear', event => {
      if (event.source === 'all' || event.source === 'dataHub') {
        this.dataCache.clear();
        this.correlationCache.clear();
        this.integratedData = this.initializeIntegratedData();

        this.eventBus.emit('cache:cleared', { source: 'dataHub' });
      }
    });

    this.eventBus.on('config:updated', event => {
      if (event.section === 'dataSources' || event.section === 'all') {
        // Handle config updates
      }
    });
  }

  public getIntegratedData(): IntegratedData {
    return this.integratedData;
  }

  public getSourceMetrics(): Map<string, DataSourceMetrics> {
    return new Map(this.metrics);
  }

  private calculateMetrics(sourceId: string, data: any): DataSourceMetrics {
    const startTime = Date.now();
    return {
      latency: [Date.now() - startTime],
      errorRate: 0,
      lastUpdate: Date.now(),
      dataQuality: 0.8,
    };
  }

  private emitMetricsUpdate(sourceId: string): void {
    const metrics = this.metrics.get(sourceId) || {
      latency: [],
      errorRate: 0,
      lastUpdate: 0,
      dataQuality: 0,
    };
    this.eventBus.emit('data-source-metric-updated', {
      sourceId,
      latency: metrics.latency[0] || 0,
      errorRate: metrics.errorRate,
      lastUpdate: metrics.lastUpdate,
      dataQuality: metrics.dataQuality,
    });
  }
}

import { DataSource } from './PredictionEngine';
import { EventBus } from './EventBus';
import { PerformanceMonitor } from './PerformanceMonitor';

export interface PipelineMetrics {
  processedCount: number;
  errorCount: number;
  averageLatency: number;
  lastProcessed: number;
  throughput: number;
}

export interface PipelineStage<T, U> {
  id: string;
  transform(data: T): Promise<U>;
  validate?(data: T): Promise<boolean>;
  cleanup?(data: T): Promise<void>;
}

export interface DataSink<T> {
  id: string;
  write(data: T): Promise<void>;
  flush?(): Promise<void>;
}

export class DataCache<T> {
  private cache: Map<string, { data: T; timestamp: number; ttl: number }>;

  constructor(private defaultTtl: number = 5 * 60 * 1000) {
    this.cache = new Map();
  }

  set(key: string, data: T, ttl?: number): void {
    this.cache.set(key, {
      data,
      timestamp: Date.now(),
      ttl: ttl ?? this.defaultTtl,
    });
  }

  get(key: string): T | undefined {
    const entry = this.cache.get(key);
    if (!entry) return undefined;

    if (Date.now() - entry.timestamp > entry.ttl) {
      this.cache.delete(key);
      return undefined;
    }

    return entry.data;
  }

  clear(): void {
    this.cache.clear();
  }
}

export class StreamingDataPipeline<T, U> {
  private readonly metrics: PipelineMetrics;
  private readonly cache: DataCache<T>;
  private readonly eventBus: EventBus;
  private readonly performanceMonitor: PerformanceMonitor;
  private isRunning: boolean = false;
  private processInterval: NodeJS.Timeout | null = null;

  constructor(
    private readonly source: DataSource,
    private readonly stages: PipelineStage<any, any>[],
    private readonly sink: DataSink<U>,
    private readonly options: {
      cacheEnabled: boolean;
      cacheTtl?: number;
      processingInterval?: number;
      retryAttempts?: number;
      batchSize?: number;
    } = {
      cacheEnabled: true,
      cacheTtl: 5 * 60 * 1000,
      processingInterval: 1000,
      retryAttempts: 3,
      batchSize: 100,
    }
  ) {
    this.metrics = {
      processedCount: 0,
      errorCount: 0,
      averageLatency: 0,
      lastProcessed: 0,
      throughput: 0,
    };
    this.cache = new DataCache<T>(options.cacheTtl);
    this.eventBus = EventBus.getInstance();
    this.performanceMonitor = PerformanceMonitor.getInstance();
  }

  async start(): Promise<void> {
    if (this.isRunning) return;
    this.isRunning = true;

    this.processInterval = setInterval(() => this.process(), this.options.processingInterval);

    this.eventBus.publish({
      type: 'pipeline:started',
      payload: {
        sourceId: this.source.id,
        sinkId: this.sink.id,
        timestamp: Date.now(),
      },
    });
  }

  async stop(): Promise<void> {
    if (!this.isRunning) return;
    this.isRunning = false;

    if (this.processInterval) {
      clearInterval(this.processInterval);
      this.processInterval = null;
    }

    if (this.sink.flush) {
      await this.sink.flush();
    }

    this.eventBus.publish({
      type: 'pipeline:stopped',
      payload: {
        sourceId: this.source.id,
        sinkId: this.sink.id,
        timestamp: Date.now(),
        metrics: this.metrics,
      },
    });
  }

  private async process(): Promise<void> {
    const traceId = this.performanceMonitor.startTrace('pipeline-processing', {
      sourceId: this.source.id,
      sinkId: this.sink.id,
    });

    try {
      const startTime = Date.now();
      const data = await this.source.fetch();

      if (this.options.cacheEnabled) {
        const cacheKey = this.generateCacheKey(data as T);
        const cached = this.cache.get(cacheKey);
        if (cached) {
          this.performanceMonitor.endTrace(traceId);
          return;
        }
        this.cache.set(cacheKey, data as T);
      }

      let transformed = data;
      for (const stage of this.stages) {
        const stageTraceId = this.performanceMonitor.startTrace(`pipeline-stage-${stage.id}`);

        try {
          if (stage.validate) {
            const isValid = await stage.validate(transformed);
            if (!isValid) {
              throw new Error(`Validation failed at stage ${stage.id}`);
            }
          }

          transformed = await stage.transform(transformed);
          this.performanceMonitor.endTrace(stageTraceId);
        } catch (error) {
          this.performanceMonitor.endTrace(stageTraceId, error as Error);
          throw error;
        }
      }

      await this.sink.write(transformed as U);

      const duration = Date.now() - startTime;
      this.updateMetrics(duration);

      this.eventBus.publish({
        type: 'pipeline:processed',
        payload: {
          sourceId: this.source.id,
          sinkId: this.sink.id,
          duration,
          timestamp: Date.now(),
        },
      });

      this.performanceMonitor.endTrace(traceId);
    } catch (error) {
      this.metrics.errorCount++;
      this.performanceMonitor.endTrace(traceId, error as Error);

      this.eventBus.publish({
        type: 'pipeline:error',
        payload: {
          sourceId: this.source.id,
          sinkId: this.sink.id,
          error: error as Error,
          timestamp: Date.now(),
        },
      });
    }
  }

  private generateCacheKey(data: T): string {
    return `${this.source.id}-${JSON.stringify(data)}`;
  }

  private updateMetrics(duration: number): void {
    this.metrics.processedCount++;
    this.metrics.lastProcessed = Date.now();
    this.metrics.averageLatency =
      (this.metrics.averageLatency * (this.metrics.processedCount - 1) + duration) /
      this.metrics.processedCount;
    this.metrics.throughput =
      this.metrics.processedCount / ((Date.now() - this.metrics.lastProcessed) / 1000);
  }

  getMetrics(): PipelineMetrics {
    return { ...this.metrics };
  }
}

export interface DataSource<T> {
  id: string;
  fetch(): Promise<T>;
  connect(): Promise<void>;
  disconnect(): Promise<void>;
  getData(): Promise<T>;
  isConnected(): boolean;
  getMetadata(): Record<string, any>;
}

export interface DataSourceConfig {
  url: string;
  apiKey?: string;
  options?: Record<string, any>;
}

export interface DataSourceMetrics {
  latency: number[];
  errorRate: number;
  lastUpdate: number;
  dataQuality: number;
}

import EventEmitter from 'eventemitter3';

// Minimal EventTypes for EventBus
export interface EventTypes {
  [event: string]: unknown;
}

export class EventBus {
  private static instance: EventBus;
  private emitter: any; // eventemitter3 v4+ workaround

  private constructor() {
    this.emitter = new (EventEmitter as any)();
  }

  public static getInstance(): EventBus {
    if (!EventBus.instance) {
      EventBus.instance = new EventBus();
    }
    return EventBus.instance;
  }

  public on<K extends keyof EventTypes & (string | symbol)>(event: K, listener: (data: EventTypes[K]) => void): void {
    this.emitter.on(event as string | symbol, listener);
  }

  public once<K extends keyof EventTypes & (string | symbol)>(event: K, listener: (data: EventTypes[K]) => void): void {
    this.emitter.once(event as string | symbol, listener);
  }

  public off<K extends keyof EventTypes & (string | symbol)>(event: K, listener: (data: EventTypes[K]) => void): void {
    this.emitter.off(event as string | symbol, listener);
  }

  public emit<K extends keyof EventTypes & (string | symbol)>(event: K, data: EventTypes[K]): void {
    this.emitter.emit(event as string | symbol, data);
  }

  public removeAllListeners<K extends keyof EventTypes & (string | symbol)>(event?: K): void {
    this.emitter.removeAllListeners(event as string | symbol | undefined);
  }

  public listenerCount<K extends keyof EventTypes & (string | symbol)>(event: K): number {
    return this.emitter.listenerCount(event as string | symbol);
  }

  public listeners<K extends keyof EventTypes & (string | symbol)>(event: K): Array<(data: EventTypes[K]) => void> {
    return this.emitter.listeners(event as string | symbol) as Array<(data: EventTypes[K]) => void>;
  }

  public eventNames(): Array<keyof EventTypes> {
    return this.emitter.eventNames() as Array<keyof EventTypes>;
  }

  // Add onAny/offAny methods for DebugPanel
  public onAny(listener: (eventName: string, data: any) => void): void {
    this.emitter.onAny(listener);
  }

  public offAny(listener: (eventName: string, data: any) => void): void {
    this.emitter.offAny(listener);
  }
}

// Singleton instance for convenience
export const eventBus = EventBus.getInstance();

import { EventBus } from './EventBus';
import { PerformanceMonitor } from './PerformanceMonitor';

export interface FeatureMetadata {
  id: string;
  name: string;
  description: string;
  version: string;
  dependencies: string[];
  category: string;
  tags: string[];
}

export interface FeatureContext {
  timestamp: number;
  environment: string;
  userId?: string;
  sessionId?: string;
  metadata: Record<string, string | number | boolean | object>;
}

export interface FeatureComponent<T, U> {
  metadata: FeatureMetadata;
  process(input: T, context: FeatureContext): Promise<U>;
  combine<V>(next: FeatureComponent<U, V>): FeatureComponent<T, V>;
  validate(input: T): Promise<boolean>;
  rollback(input: T, error: Error): Promise<void>;
}

export class ComposableFeature<T, U> implements FeatureComponent<T, U> {
  private readonly eventBus: EventBus;
  private readonly performanceMonitor: PerformanceMonitor;

  constructor(
    public readonly metadata: FeatureMetadata,
    private readonly processor: (input: T, context: FeatureContext) => Promise<U>,
    private readonly validator?: (input: T) => Promise<boolean>,
    private readonly rollbackHandler?: (input: T, error: Error) => Promise<void>
  ) {
    this.eventBus = EventBus.getInstance();
    this.performanceMonitor = PerformanceMonitor.getInstance();
  }

  async process(input: T, context: FeatureContext): Promise<U> {
    const traceId = this.performanceMonitor.startTrace(`feature-${this.metadata.id}`, {
      featureId: this.metadata.id,
      category: this.metadata.category,
      version: this.metadata.version,
    });

    try {
      // Validate input if validator exists
      if (this.validator && !(await this.validate(input))) {
        throw new Error(`Input validation failed for feature ${this.metadata.id}`);
      }

      // Process the input
      const startTime = Date.now();
      const result = await this.processor(input, context);
      const duration = Date.now() - startTime;

      // Emit success event
      this.eventBus.publish({
        type: 'feature:executed',
        payload: {
          featureId: this.metadata.id,
          duration,
          success: true,
          timestamp: Date.now(),
          context,
        },
      });

      this.performanceMonitor.endTrace(traceId);
      return result;
    } catch (error) {
      // Handle error and attempt rollback
      this.performanceMonitor.endTrace(traceId, error as Error);

      if (this.rollbackHandler) {
        await this.rollbackHandler(input, error as Error);
      }

      // Emit error event
      this.eventBus.publish({
        type: 'feature:error',
        payload: {
          featureId: this.metadata.id,
          error: error as Error,
          timestamp: Date.now(),
          context,
        },
      });

      throw error;
    }
  }

  combine<V>(next: FeatureComponent<U, V>): FeatureComponent<T, V> {
    return new ComposableFeature<T, V>(
      {
        id: `${this.metadata.id}->${next.metadata.id}`,
        name: `${this.metadata.name} -> ${next.metadata.name}`,
        description: `Composed feature: ${this.metadata.description} -> ${next.metadata.description}`,
        version: `${this.metadata.version}+${next.metadata.version}`,
        dependencies: [...this.metadata.dependencies, ...next.metadata.dependencies],
        category: this.metadata.category,
        tags: [...new Set([...this.metadata.tags, ...next.metadata.tags])],
      },
      async (input: T, context: FeatureContext) => {
        const intermediate = await this.process(input, context);
        return next.process(intermediate, context);
      }
    );
  }

  async validate(input: T): Promise<boolean> {
    if (this.validator) {
      return this.validator(input);
    }
    return true;
  }

  async rollback(input: T, error: Error): Promise<void> {
    if (this.rollbackHandler) {
      await this.rollbackHandler(input, error);
    }
  }
}

export class FeatureRegistry {
  private static instance: FeatureRegistry;
  private readonly features: Map<string, FeatureComponent<any, any>>;
  private readonly eventBus: EventBus;

  private constructor() {
    this.features = new Map();
    this.eventBus = EventBus.getInstance();
  }

  static getInstance(): FeatureRegistry {
    if (!FeatureRegistry.instance) {
      FeatureRegistry.instance = new FeatureRegistry();
    }
    return FeatureRegistry.instance;
  }

  registerFeature<T, U>(feature: FeatureComponent<T, U>): void {
    if (this.features.has(feature.metadata.id)) {
      throw new Error(`Feature with ID ${feature.metadata.id} is already registered`);
    }

    this.features.set(feature.metadata.id, feature);
    this.eventBus.publish({
      type: 'feature:registered',
      payload: {
        featureId: feature.metadata.id,
        metadata: feature.metadata,
        timestamp: Date.now(),
      },
    });
  }

  getFeature<T, U>(featureId: string): FeatureComponent<T, U> | undefined {
    return this.features.get(featureId) as FeatureComponent<T, U>;
  }

  listFeatures(): FeatureMetadata[] {
    return Array.from(this.features.values()).map(f => f.metadata);
  }

  composeFeatures<T, U, V>(
    firstFeatureId: string,
    secondFeatureId: string
  ): FeatureComponent<T, V> | undefined {
    const first = this.getFeature<T, U>(firstFeatureId);
    const second = this.getFeature<U, V>(secondFeatureId);

    if (!first || !second) {
      return undefined;
    }

    return first.combine(second);
  }

  async executeFeature<T, U>(featureId: string, input: T, context: FeatureContext): Promise<U> {
    const feature = this.getFeature<T, U>(featureId);
    if (!feature) {
      throw new Error(`Feature ${featureId} not found`);
    }

    return feature.process(input, context);
  }
}

import { EventBus } from './EventBus';
import { PerformanceMonitor } from './PerformanceMonitor';
import { UnifiedConfigManager } from './UnifiedConfigManager';
import { UnifiedMonitor } from './UnifiedMonitor';

export interface Feature {
  id: string;
  name: string;
  description: string;
  enabled: boolean;
  rolloutPercentage: number;
  dependencies: string[];
  tags: string[];
  metadata: Record<string, any>;
}

export interface Experiment {
  id: string;
  name: string;
  description: string;
  status: 'active' | 'inactive' | 'completed';
  variants: Array<{
    id: string;
    name: string;
    weight: number;
  }>;
  audience: {
    percentage: number;
    filters?: Record<string, any>;
  };
  startDate: number;
  endDate?: number;
  metadata: Record<string, any>;
}

export interface UserContext {
  userId: string;
  userGroups: string[];
  attributes: Record<string, any>;
}

export class FeatureFlags {
  private static instance: FeatureFlags;
  private readonly eventBus: EventBus;
  private readonly performanceMonitor: PerformanceMonitor;
  private readonly monitor: UnifiedMonitor;
  private readonly configManager: UnifiedConfigManager;
  private readonly features: Map<string, Feature>;
  private readonly experiments: Map<string, Experiment>;
  private readonly userAssignments: Map<string, Record<string, string>>;

  private constructor() {
    this.eventBus = EventBus.getInstance();
    this.performanceMonitor = PerformanceMonitor.getInstance();
    this.monitor = UnifiedMonitor.getInstance();
    this.configManager = UnifiedConfigManager.getInstance();
    this.features = new Map();
    this.experiments = new Map();
    this.userAssignments = new Map();
  }

  public static getInstance(): FeatureFlags {
    if (!FeatureFlags.instance) {
      FeatureFlags.instance = new FeatureFlags();
    }
    return FeatureFlags.instance;
  }

  public async initialize(): Promise<void> {
    const traceId = this.performanceMonitor.startTrace('feature-flags-init');
    try {
      const config = await this.configManager.getConfig();

      // Initialize features
      if (config.features) {
        for (const feature of config.features) {
          this.features.set(feature.id, feature);
        }
      }

      // Initialize experiments
      if (config.experiments) {
        for (const experiment of config.experiments) {
          this.experiments.set(experiment.id, experiment);
        }
      }

      this.performanceMonitor.endTrace(traceId);
    } catch (error) {
      this.performanceMonitor.endTrace(traceId, error as Error);
      throw error;
    }
  }

  public isFeatureEnabled(featureId: string, context: UserContext): boolean {
    const feature = this.features.get(featureId);
    if (!feature) return false;

    // Check if feature is globally enabled
    if (!feature.enabled) return false;

    // Check dependencies
    if (!this.areDependenciesSatisfied(feature, context)) return false;

    // Check rollout percentage
    if (!this.isUserInRollout(context.userId, feature.rolloutPercentage)) return false;

    return true;
  }

  public getExperimentVariant(experimentId: string, context: UserContext): string | null {
    const experiment = this.experiments.get(experimentId);
    if (!experiment || experiment.status !== 'active') return null;

    // Check if user is in experiment audience
    if (!this.isUserInAudience(context, experiment.audience)) return null;

    // Get or assign variant
    const userAssignments = this.userAssignments.get(context.userId) || {};
    if (userAssignments[experimentId]) {
      return userAssignments[experimentId];
    }

    // Assign new variant
    const variant = this.assignVariant(experiment, context);
    if (variant) {
      this.userAssignments.set(context.userId, {
        ...userAssignments,
        [experimentId]: variant.id,
      });
      return variant.id;
    }

    return null;
  }

  private areDependenciesSatisfied(feature: Feature, context: UserContext): boolean {
    return feature.dependencies.every(depId => this.isFeatureEnabled(depId, context));
  }

  private isUserInRollout(userId: string, percentage: number): boolean {
    const hash = this.hashString(userId);
    const normalized = hash / Math.pow(2, 32);
    return normalized <= percentage / 100;
  }

  private isUserInAudience(context: UserContext, audience: Experiment['audience']): boolean {
    // Check percentage rollout
    if (!this.isUserInRollout(context.userId, audience.percentage)) return false;

    // Check filters if they exist
    if (audience.filters) {
      for (const [key, value] of Object.entries(audience.filters)) {
        if (context.attributes[key] !== value) return false;
      }
    }

    return true;
  }

  private assignVariant(
    experiment: Experiment,
    context: UserContext
  ): Experiment['variants'][0] | null {
    const totalWeight = experiment.variants.reduce((sum, v) => sum + v.weight, 0);
    const hash = this.hashString(`${context.userId}:${experiment.id}`);
    const normalized = (hash / Math.pow(2, 32)) * totalWeight;

    let cumulative = 0;
    for (const variant of experiment.variants) {
      cumulative += variant.weight;
      if (normalized <= cumulative) {
        return variant;
      }
    }

    return null;
  }

  private hashString(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return Math.abs(hash);
  }

  public registerFeature(feature: Feature): void {
    if (this.features.has(feature.id)) {
      throw new Error(`Feature ${feature.id} already exists`);
    }
    this.features.set(feature.id, feature);
  }

  public updateFeature(featureId: string, updates: Partial<Feature>): void {
    const feature = this.features.get(featureId);
    if (!feature) {
      throw new Error(`Feature ${featureId} not found`);
    }

    this.features.set(featureId, {
      ...feature,
      ...updates,
    });

    this.eventBus.emit('feature:updated', {
      featureId,
      updates,
      timestamp: Date.now(),
    });
  }

  public registerExperiment(experiment: Experiment): void {
    if (this.experiments.has(experiment.id)) {
      throw new Error(`Experiment ${experiment.id} already exists`);
    }
    this.experiments.set(experiment.id, experiment);
  }

  public updateExperiment(experimentId: string, updates: Partial<Experiment>): void {
    const experiment = this.experiments.get(experimentId);
    if (!experiment) {
      throw new Error(`Experiment ${experimentId} not found`);
    }

    this.experiments.set(experimentId, {
      ...experiment,
      ...updates,
    });

    this.eventBus.emit('experiment:updated', {
      experimentId,
      timestamp: Date.now(),
    });
  }

  public getAllFeatures(): Feature[] {
    return Array.from(this.features.values());
  }

  public getAllExperiments(): Experiment[] {
    return Array.from(this.experiments.values());
  }

  public getUserAssignments(userId: string): Record<string, string> {
    return this.userAssignments.get(userId) || {};
  }

  public clearUserAssignments(userId: string): void {
    this.userAssignments.delete(userId);
  }
}

import { v4 as uuidv4 } from 'uuid';
import {
  FinalPredictionEngine,
  FinalPredictionEngineDependencies,
  FinalPredictionEngineConfig,
  ModelOutput,
  ModelWeight,
  RiskProfile,
  FinalPrediction,
  RiskLevel,
  FeatureImpact,
  FinalPredictionError,
  ModelContributions,
  ShapValue,
  ShapExplanation,
  ModelExplanation,
  PredictionWithExplanation,
  ModelType,
} from './types';

export class FinalPredictionEngineImpl implements FinalPredictionEngine {
  private config: FinalPredictionEngineConfig;
  private modelWeights: Map<string, ModelWeight>;
  private riskProfiles: Map<string, RiskProfile>;
  private featureStats: Record<string, { mean: number; std: number }> = {};
  private confidenceWeights: number[] = [0.3, 0.3, 0.4];
  private currentPrediction: number = 0.5;

  constructor(
    private dependencies: FinalPredictionEngineDependencies,
    initialConfig: FinalPredictionEngineConfig
  ) {
    this.config = initialConfig;
    this.modelWeights = new Map(initialConfig.modelWeights.map(weight => [weight.type, weight]));
    this.riskProfiles = new Map(Object.entries(initialConfig.riskProfiles));
  }

  async generatePrediction(
    modelOutputs: ModelOutput[],
    riskProfile: RiskProfile,
    context?: Record<string, any>
  ): Promise<FinalPrediction> {
    const startTime = Date.now();
    const decisionPath: string[] = [];

    try {
      // Validate inputs
      this.validateModelOutputs(modelOutputs);
      this.validateRiskProfile(riskProfile);

      // Calculate weighted scores
      const weightedScores = this.calculateWeightedScores(modelOutputs);
      decisionPath.push('Calculated weighted scores');

      // Determine risk level
      const riskLevel = this.determineRiskLevel(weightedScores, riskProfile);
      decisionPath.push(`Determined risk level: ${riskLevel}`);

      // Calculate final score
      const finalScore = this.calculateFinalScore(weightedScores, riskProfile);
      decisionPath.push(`Calculated final score: ${finalScore}`);

      // Check for sure odds
      const isSureOdds = this.checkSureOdds(weightedScores);
      decisionPath.push(`Sure odds check: ${isSureOdds}`);

      // Calculate payout range
      const payoutRange = this.calculatePayoutRange(finalScore, riskProfile);
      decisionPath.push('Calculated payout range');

      // Aggregate features
      const { topFeatures, supportingFeatures } = this.aggregateFeatures(modelOutputs);
      decisionPath.push('Aggregated features');

      // Create final prediction
      const prediction: FinalPrediction = {
        id: uuidv4(),
        timestamp: Date.now(),
        confidenceWindow: {
          start: startTime,
          end: Date.now(),
        },
        finalScore,
        confidence: weightedScores.averageConfidence,
        riskLevel,
        isSureOdds,
        payoutRange,
        modelContributions: weightedScores.contributions,
        topFeatures,
        supportingFeatures,
        metadata: {
          processingTime: Date.now() - startTime,
          dataFreshness: this.calculateDataFreshness(modelOutputs),
          signalQuality: this.calculateSignalQuality(modelOutputs),
          decisionPath,
        },
      };

      // Log and track metrics
      this.logPrediction(prediction);
      this.trackMetrics(prediction);

      return prediction;
    } catch (error) {
      throw new FinalPredictionError('Failed to generate prediction', 'PREDICTION', 'ERROR', {
        error,
        context,
      });
    }
  }

  private validateModelOutputs(outputs: ModelOutput[]): void {
    if (!outputs.length) {
      throw new FinalPredictionError('No model outputs provided');
    }

    const uniqueTypes = new Set(outputs.map(o => o.type));
    if (uniqueTypes.size !== outputs.length) {
      throw new FinalPredictionError('Duplicate model types detected');
    }
  }

  private validateRiskProfile(profile: RiskProfile): void {
    if (!this.riskProfiles.has(profile.type)) {
      throw new FinalPredictionError(`Invalid risk profile: ${profile.type}`);
    }
  }

  private calculateWeightedScores(modelOutputs: ModelOutput[]) {
    const contributions: ModelContributions = {
      historical: { weight: 0, confidence: 0, score: 0 },
      market: { weight: 0, confidence: 0, score: 0 },
      sentiment: { weight: 0, confidence: 0, score: 0 },
      correlation: { weight: 0, confidence: 0, score: 0 },
    };
    let totalWeight = 0;
    let weightedScore = 0;
    let totalConfidence = 0;

    for (const output of modelOutputs) {
      const weight = this.modelWeights.get(output.type);
      if (!weight) continue;

      const contribution = {
        weight: weight.weight,
        confidence: output.confidence,
        score: output.score,
      };

      contributions[output.type] = contribution;
      totalWeight += weight.weight;
      weightedScore += output.score * weight.weight;
      totalConfidence += output.confidence * weight.weight;
    }

    return {
      weightedScore: weightedScore / totalWeight,
      averageConfidence: totalConfidence / totalWeight,
      contributions,
    };
  }

  private determineRiskLevel(
    weightedScores: { weightedScore: number; averageConfidence: number },
    riskProfile: RiskProfile
  ): RiskLevel {
    const { weightedScore, averageConfidence } = weightedScores;
    const riskScore = (1 - averageConfidence) * (1 + Math.abs(weightedScore - 0.5));

    if (riskScore < 0.3) return 'low';
    if (riskScore < 0.6) return 'medium';
    return 'high';
  }

  private calculateFinalScore(
    weightedScores: { weightedScore: number; averageConfidence: number },
    riskProfile: RiskProfile
  ): number {
    const { weightedScore, averageConfidence } = weightedScores;
    const riskMultiplier = riskProfile.multiplier;

    return weightedScore * (averageConfidence * riskMultiplier);
  }

  private checkSureOdds(weightedScores: { averageConfidence: number }): boolean {
    return weightedScores.averageConfidence >= this.config.sureOddsThreshold;
  }

  private calculatePayoutRange(
    finalScore: number,
    riskProfile: RiskProfile
  ): { min: number; max: number; expected: number } {
    const baseMultiplier = riskProfile.multiplier;
    const confidenceRange = 0.2; // 20% range

    return {
      min: finalScore * (1 - confidenceRange) * baseMultiplier,
      max: finalScore * (1 + confidenceRange) * baseMultiplier,
      expected: finalScore * baseMultiplier,
    };
  }

  private aggregateFeatures(modelOutputs: ModelOutput[]): {
    topFeatures: FeatureImpact[];
    supportingFeatures: FeatureImpact[];
  } {
    const featureMap = new Map<string, FeatureImpact>();

    // Convert features to FeatureImpact objects
    for (const output of modelOutputs) {
      Object.entries(output.features).forEach(([name, value]) => {
        const existing = featureMap.get(name);
        if (existing) {
          existing.weight = (existing.weight + value) / 2;
          existing.impact = (existing.impact + value) / 2;
        } else {
          featureMap.set(name, {
            name,
            weight: value,
            impact: value,
          });
        }
      });
    }

    // Sort by impact
    const sortedFeatures = Array.from(featureMap.values()).sort(
      (a, b) => Math.abs(b.impact) - Math.abs(a.impact)
    );

    return {
      topFeatures: sortedFeatures.slice(0, this.config.maxFeatures),
      supportingFeatures: sortedFeatures.slice(
        this.config.maxFeatures,
        this.config.maxFeatures * 2
      ),
    };
  }

  private calculateDataFreshness(modelOutputs: ModelOutput[]): number {
    const now = Date.now();
    const freshnessScores = modelOutputs.map(output => {
      const age = now - output.timestamp;
      return Math.max(0, 1 - age / (24 * 60 * 60 * 1000)); // 24 hours max
    });
    return freshnessScores.reduce((a, b) => a + b, 0) / freshnessScores.length;
  }

  private calculateSignalQuality(modelOutputs: ModelOutput[]): number {
    return modelOutputs.reduce((quality, output) => {
      return (
        quality * (output.metadata.signalStrength * (1 - output.metadata.latency / 1000)) // Normalize latency
      );
    }, 1);
  }

  private logPrediction(prediction: FinalPrediction): void {
    this.dependencies.logger.info('Generated final prediction', {
      predictionId: prediction.id,
      finalScore: prediction.finalScore,
      confidence: prediction.confidence,
      riskLevel: prediction.riskLevel,
      isSureOdds: prediction.isSureOdds,
      processingTime: prediction.metadata.processingTime,
    });
  }

  private trackMetrics(prediction: FinalPrediction): void {
    this.dependencies.metrics.track('prediction_generated', {
      predictionId: prediction.id,
      confidence: prediction.confidence,
      riskLevel: prediction.riskLevel,
      processingTime: prediction.metadata.processingTime,
    });
  }

  async updateModelWeights(weights: ModelWeight[]): Promise<void> {
    this.modelWeights = new Map(weights.map(weight => [weight.type, weight]));
    await this.dependencies.config.set('modelWeights', weights);
  }

  async updateRiskProfiles(profiles: Record<string, RiskProfile>): Promise<void> {
    this.riskProfiles = new Map(Object.entries(profiles));
    await this.dependencies.config.set('riskProfiles', profiles);
  }

  async getEngineMetrics(): Promise<Record<string, number>> {
    return {
      modelCount: this.modelWeights.size,
      riskProfileCount: this.riskProfiles.size,
      sureOddsThreshold: this.config.sureOddsThreshold,
      featureThreshold: this.config.featureThreshold,
    };
  }

  async validatePrediction(prediction: FinalPrediction): Promise<boolean> {
    try {
      // Validate required fields
      if (!prediction.id || !prediction.timestamp || !prediction.finalScore) {
        return false;
      }

      // Validate confidence window
      if (prediction.confidenceWindow.start > prediction.confidenceWindow.end) {
        return false;
      }

      // Validate risk level
      if (!['low', 'medium', 'high'].includes(prediction.riskLevel)) {
        return false;
      }

      // Validate payout range
      if (
        prediction.payoutRange.min > prediction.payoutRange.max ||
        prediction.payoutRange.expected < prediction.payoutRange.min ||
        prediction.payoutRange.expected > prediction.payoutRange.max
      ) {
        return false;
      }

      return true;
    } catch (error) {
      this.dependencies.logger.error('Failed to validate prediction', { error });
      return false;
    }
  }

  private calculateShapValues(
    modelName: string,
    features: Record<string, number>,
    prediction: number
  ): ShapExplanation {
    const baseValue = 0.5; // Default base value
    const shapValues: ShapValue[] = [];

    // Get feature importance for this model
    const featureImportance = this.getFeatureImportance(modelName);

    // Calculate SHAP values based on feature importance and prediction
    Object.entries(features).forEach(([feature, value]) => {
      const importance = featureImportance[feature] || 0;
      const normalizedValue =
        (value - this.featureStats[feature]?.mean || 0.5) / (this.featureStats[feature]?.std || 1);
      const impact = importance * normalizedValue;

      shapValues.push({
        feature,
        value,
        impact,
        direction: impact > 0 ? 'positive' : 'negative',
        confidence: this.calculateFeatureConfidence(feature, value),
      });
    });

    // Sort by absolute impact
    shapValues.sort((a, b) => Math.abs(b.impact) - Math.abs(a.impact));

    return {
      baseValue,
      shapValues,
      prediction,
      confidence: this.calculateConfidence(shapValues),
      timestamp: Date.now(),
    };
  }

  private calculateFeatureConfidence(feature: string, value: number): number {
    const stats = this.featureStats[feature];
    if (!stats) return 0.5;

    // Calculate how far the value is from the mean in terms of standard deviations
    const zScore = Math.abs((value - stats.mean) / stats.std);

    // Convert to confidence score (higher confidence for values closer to mean)
    return Math.max(0, 1 - zScore / 3); // 3 standard deviations = 0 confidence
  }

  private calculateConfidence(shapValues: ShapValue[]): number {
    // Calculate confidence based on multiple factors
    const factors = [
      this.calculateShapConsistency(shapValues),
      this.calculateFeatureConfidence(shapValues),
      this.calculateModelAgreement(shapValues),
    ];

    // Weighted average of confidence factors
    return factors.reduce((sum, factor, index) => sum + factor * this.confidenceWeights[index], 0);
  }

  private calculateShapConsistency(shapValues: ShapValue[]): number {
    // Calculate how consistent the SHAP values are in their direction
    const positiveImpacts = shapValues.filter(sv => sv.impact > 0).length;
    const negativeImpacts = shapValues.filter(sv => sv.impact < 0).length;
    const totalImpacts = shapValues.length;

    if (totalImpacts === 0) return 0.5;

    // Higher confidence when impacts are more consistent in direction
    return Math.max(positiveImpacts, negativeImpacts) / totalImpacts;
  }

  private calculateModelAgreement(shapValues: ShapValue[]): number {
    // Calculate how well the features agree with the model's prediction
    const predictionDirection = this.currentPrediction > 0.5 ? 1 : -1;
    const agreeingFeatures = shapValues.filter(
      sv => (sv.impact > 0 && predictionDirection > 0) || (sv.impact < 0 && predictionDirection < 0)
    ).length;

    return agreeingFeatures / shapValues.length;
  }

  private getFeatureImportance(modelName: string): Record<string, number> {
    // Get feature importance from model metrics
    const modelMetrics = this.dependencies.metricsService.getModelMetrics(modelName);
    return modelMetrics.featureImportance || {};
  }

  private async generatePredictions(
    features: Record<string, number>
  ): Promise<Record<string, ModelOutput>> {
    const predictions: Record<string, ModelOutput> = {};

    // Generate predictions from each model
    for (const [modelName, weight] of this.modelWeights.entries()) {
      try {
        const modelOutputs: ModelOutput[] = [
          {
            type: modelName as ModelType,
            score: 0,
            features,
            prediction: 0,
            confidence: 0,
            timestamp: Date.now(),
            metadata: {
              signalStrength: 1,
              latency: 0,
            },
          },
        ];

        const output = await this.generatePrediction(
          modelOutputs,
          this.riskProfiles.get('default')!
        );
        predictions[modelName] = {
          type: modelName as ModelType,
          score: output.finalScore,
          features,
          prediction: output.finalScore,
          confidence: output.confidence,
          timestamp: Date.now(),
          metadata: {
            signalStrength: output.metadata.signalQuality,
            latency: output.metadata.processingTime,
          },
        };
      } catch (error) {
        this.dependencies.logger.error(`Error generating prediction for model ${modelName}:`, {
          error: error instanceof Error ? error.message : 'Unknown error',
          modelName,
        });
      }
    }

    return predictions;
  }

  private combinePredictions(predictions: Record<string, ModelOutput>): {
    prediction: number;
    confidence: number;
  } {
    let weightedSum = 0;
    let totalWeight = 0;

    for (const [modelName, output] of Object.entries(predictions)) {
      const weight = this.modelWeights.get(modelName)?.weight || 0;
      weightedSum += output.prediction * weight;
      totalWeight += weight;
    }

    const finalPrediction = totalWeight > 0 ? weightedSum / totalWeight : 0;
    const confidence = this.calculateOverallConfidence(predictions);

    return { prediction: finalPrediction, confidence };
  }

  private calculateOverallConfidence(predictions: Record<string, ModelOutput>): number {
    const confidences = Object.values(predictions).map(p => p.confidence);
    return confidences.length > 0 ? confidences.reduce((a, b) => a + b, 0) / confidences.length : 0;
  }

  public async generatePredictionWithExplanation(
    features: Record<string, number>,
    riskLevel: RiskLevel = 'medium'
  ): Promise<PredictionWithExplanation> {
    const modelOutputs = await this.generatePredictions(features);
    const explanations: ModelExplanation[] = [];

    // Calculate SHAP values for each model
    for (const [modelName, output] of Object.entries(modelOutputs)) {
      const shapExplanation = this.calculateShapValues(modelName, features, output.prediction);

      explanations.push({
        modelName,
        shapExplanation,
        featureImportance: this.getFeatureImportance(modelName),
        confidence: output.confidence,
      });
    }

    // Combine predictions with explanations
    const finalPrediction = this.combinePredictions(modelOutputs);

    return {
      prediction: finalPrediction.prediction,
      confidence: finalPrediction.confidence,
      explanations,
      timestamp: Date.now(),
    };
  }
}

