import { ModelVersion, ModelEvaluation, ModelEvaluatorConfig } from './types';
import { FeatureLogger } from '../../services/analytics/featureLogging';

export class ModelEvaluator {
  private config: ModelEvaluatorConfig;
  private logger: FeatureLogger;

  constructor(config: ModelEvaluatorConfig) {
    this.config = config;
    this.logger = new FeatureLogger({});
  }

  async evaluate(model: ModelVersion, data: any): Promise<ModelEvaluation> {
    try {
      const startTime = Date.now();

      // Split data for validation
      const { trainData, validationData } = this.splitData(data);

      // Get predictions
      const predictions = await this.getPredictions(model, validationData);

      // Calculate metrics
      const metrics = await this.calculateMetrics(validationData, predictions);

      // Calculate performance metrics
      const performanceMetrics = this.calculatePerformanceMetrics(startTime);

      // Calculate feature importance
      const featureImportance = await this.calculateFeatureImportance(model, validationData);

      // Calculate custom metrics
      const customMetrics = await this.calculateCustomMetrics(validationData, predictions);

      // Calculate confusion matrix and ROC curve
      const confusionMatrix = this.calculateConfusionMatrix(validationData, predictions);
      const rocCurve = this.calculateROCCurve(validationData, predictions);

      const evaluation: ModelEvaluation = {
        accuracy: metrics.accuracy || 0,
        precision: metrics.precision || 0,
        recall: metrics.recall || 0,
        f1Score: metrics.f1Score || 0,
        confusionMatrix,
        rocCurve,
        featureImportance,
        performanceMetrics,
        customMetrics,
      };

      this.logger.info(`Evaluated model ${model.modelId} version ${model.version}`);
      return evaluation;
    } catch (error) {
      this.logger.error(`Failed to evaluate model ${model.modelId}`, error);
      throw error;
    }
  }

  private splitData(data: any): { trainData: any; validationData: any } {
    const splitIndex = Math.floor(data.length * (1 - this.config.validationSplit));
    return {
      trainData: data.slice(0, splitIndex),
      validationData: data.slice(splitIndex),
    };
  }

  private async getPredictions(model: ModelVersion, data: any): Promise<any[]> {
    // Implementation depends on the model type and prediction interface
    // This is a placeholder that should be implemented based on your model types
    return [];
  }

  private async calculateMetrics(data: any, predictions: any[]): Promise<Partial<ModelEvaluation>> {
    const metrics: Partial<ModelEvaluation> = {};

    // Calculate accuracy
    metrics.accuracy = this.calculateAccuracy(data, predictions);

    // Calculate precision
    metrics.precision = this.calculatePrecision(data, predictions);

    // Calculate recall
    metrics.recall = this.calculateRecall(data, predictions);

    // Calculate F1 score
    metrics.f1Score = this.calculateF1Score(metrics.precision, metrics.recall);

    return metrics;
  }

  private calculateAccuracy(data: any, predictions: any[]): number {
    let correct = 0;
    for (let i = 0; i < data.length; i++) {
      if (data[i] === predictions[i]) correct++;
    }
    return correct / data.length;
  }

  private calculatePrecision(data: any, predictions: any[]): number {
    let truePositives = 0;
    let falsePositives = 0;

    for (let i = 0; i < data.length; i++) {
      if (predictions[i] === 1) {
        if (data[i] === 1) truePositives++;
        else falsePositives++;
      }
    }

    return truePositives / (truePositives + falsePositives);
  }

  private calculateRecall(data: any, predictions: any[]): number {
    let truePositives = 0;
    let falseNegatives = 0;

    for (let i = 0; i < data.length; i++) {
      if (data[i] === 1) {
        if (predictions[i] === 1) truePositives++;
        else falseNegatives++;
      }
    }

    return truePositives / (truePositives + falseNegatives);
  }

  private calculateF1Score(precision: number, recall: number): number {
    return (2 * (precision * recall)) / (precision + recall);
  }

  private calculateConfusionMatrix(data: any, predictions: any[]): number[][] {
    const matrix = [
      [0, 0],
      [0, 0],
    ];

    for (let i = 0; i < data.length; i++) {
      matrix[data[i]][predictions[i]]++;
    }

    return matrix;
  }

  private calculateROCCurve(
    data: any,
    predictions: any[]
  ): {
    fpr: number[];
    tpr: number[];
    thresholds: number[];
  } {
    const thresholds = this.generateThresholds(predictions);
    const fpr: number[] = [];
    const tpr: number[] = [];

    for (const threshold of thresholds) {
      const { falsePositiveRate, truePositiveRate } = this.calculateRates(
        data,
        predictions,
        threshold
      );
      fpr.push(falsePositiveRate);
      tpr.push(truePositiveRate);
    }

    return { fpr, tpr, thresholds };
  }

  private generateThresholds(predictions: any[]): number[] {
    const uniqueValues = [...new Set(predictions)].sort();
    return uniqueValues;
  }

  private calculateRates(
    data: any,
    predictions: any[],
    threshold: number
  ): {
    falsePositiveRate: number;
    truePositiveRate: number;
  } {
    let truePositives = 0;
    let falsePositives = 0;
    let trueNegatives = 0;
    let falseNegatives = 0;

    for (let i = 0; i < data.length; i++) {
      const predicted = predictions[i] >= threshold ? 1 : 0;
      if (data[i] === 1) {
        if (predicted === 1) truePositives++;
        else falseNegatives++;
      } else {
        if (predicted === 1) falsePositives++;
        else trueNegatives++;
      }
    }

    return {
      falsePositiveRate: falsePositives / (falsePositives + trueNegatives),
      truePositiveRate: truePositives / (truePositives + falseNegatives),
    };
  }

  private calculatePerformanceMetrics(startTime: number): {
    trainingTime: number;
    inferenceTime: number;
    memoryUsage: number;
  } {
    const endTime = Date.now();
    const trainingTime = endTime - startTime;

    // These are placeholder implementations
    // Real implementations should measure actual inference time and memory usage
    return {
      trainingTime,
      inferenceTime: 0,
      memoryUsage: 0,
    };
  }

  private async calculateFeatureImportance(
    model: ModelVersion,
    data: any
  ): Promise<Record<string, number>> {
    // Implementation depends on the model type
    // This is a placeholder that should be implemented based on your model types
    return {};
  }

  private async calculateCustomMetrics(
    data: any,
    predictions: any[]
  ): Promise<Record<string, number>> {
    const metrics: Record<string, number> = {};

    if (this.config.customMetrics) {
      for (const [name, calculator] of Object.entries(this.config.customMetrics)) {
        metrics[name] = calculator(data, predictions);
      }
    }

    return metrics;
  }
}

import { ModelMetadata, ModelVersion, ModelEvaluation } from './types';
import { ModelRegistry } from './ModelRegistry';
import { ModelEvaluator } from './ModelEvaluator';
import { FeatureLogger } from '../../services/analytics/featureLogging';

export class ModelManager {
  private registry: ModelRegistry;
  private evaluator: ModelEvaluator;
  private logger: FeatureLogger;
  private modelCache: Map<string, any>;

  constructor(config: { registryConfig?: any; evaluatorConfig?: any; loggerConfig?: any }) {
    this.registry = new ModelRegistry(config.registryConfig);
    this.evaluator = new ModelEvaluator(config.evaluatorConfig);
    this.logger = new FeatureLogger(config.loggerConfig);
    this.modelCache = new Map();
  }

  async createModel(metadata: ModelMetadata): Promise<string> {
    try {
      const modelId = await this.registry.registerModel(metadata);
      this.logger.info(`Created new model with ID: ${modelId}`);
      return modelId;
    } catch (error) {
      this.logger.error('Failed to create model', error);
      throw error;
    }
  }

  async trainModel(modelId: string, data: any, config: any): Promise<ModelVersion> {
    try {
      const model = await this.registry.getModel(modelId);
      const version = await model.train(data, config);

      // Evaluate the new version
      const evaluation = await this.evaluator.evaluate(version, data);
      version.metrics = evaluation;

      // Update registry
      await this.registry.updateModel(modelId, version);

      this.logger.info(`Trained model ${modelId} to version ${version.version}`);
      return version;
    } catch (error) {
      this.logger.error(`Failed to train model ${modelId}`, error);
      throw error;
    }
  }

  async predict(modelId: string, data: any): Promise<any> {
    try {
      // Check cache first
      const cacheKey = `${modelId}_${JSON.stringify(data)}`;
      if (this.modelCache.has(cacheKey)) {
        return this.modelCache.get(cacheKey);
      }

      const model = await this.registry.getModel(modelId);
      const prediction = await model.predict(data);

      // Cache the result
      this.modelCache.set(cacheKey, prediction);

      return prediction;
    } catch (error) {
      this.logger.error(`Failed to make prediction with model ${modelId}`, error);
      throw error;
    }
  }

  async evaluateModel(modelId: string, data: any): Promise<ModelEvaluation> {
    try {
      const model = await this.registry.getModel(modelId);
      const evaluation = await this.evaluator.evaluate(model, data);

      // Update model metrics
      await this.registry.updateMetrics(modelId, evaluation);

      this.logger.info(`Evaluated model ${modelId}`);
      return evaluation;
    } catch (error) {
      this.logger.error(`Failed to evaluate model ${modelId}`, error);
      throw error;
    }
  }

  async getModelVersions(modelId: string): Promise<ModelVersion[]> {
    try {
      return await this.registry.getModelVersions(modelId);
    } catch (error) {
      this.logger.error(`Failed to get versions for model ${modelId}`, error);
      throw error;
    }
  }

  async getModelMetadata(modelId: string): Promise<ModelMetadata> {
    try {
      return await this.registry.getModelMetadata(modelId);
    } catch (error) {
      this.logger.error(`Failed to get metadata for model ${modelId}`, error);
      throw error;
    }
  }

  async updateModelMetadata(modelId: string, metadata: Partial<ModelMetadata>): Promise<void> {
    try {
      await this.registry.updateModelMetadata(modelId, metadata);
      this.logger.info(`Updated metadata for model ${modelId}`);
    } catch (error) {
      this.logger.error(`Failed to update metadata for model ${modelId}`, error);
      throw error;
    }
  }

  async deleteModel(modelId: string): Promise<void> {
    try {
      await this.registry.deleteModel(modelId);
      this.modelCache.delete(modelId);
      this.logger.info(`Deleted model ${modelId}`);
    } catch (error) {
      this.logger.error(`Failed to delete model ${modelId}`, error);
      throw error;
    }
  }

  async cleanupCache(): Promise<void> {
    try {
      this.modelCache.clear();
      this.logger.info('Cleared model cache');
    } catch (error) {
      this.logger.error('Failed to cleanup cache', error);
      throw error;
    }
  }
}

import { ModelMetadata, ModelVersion, ModelRegistryConfig } from './types';
import { FeatureLogger } from '../../services/analytics/featureLogging';
import * as fs from 'fs/promises';
import * as path from 'path';

export class ModelRegistry {
  private config: ModelRegistryConfig;
  private logger: FeatureLogger;
  private models: Map<string, ModelMetadata>;
  private versions: Map<string, ModelVersion[]>;

  constructor(config: ModelRegistryConfig) {
    this.config = config;
    this.logger = new FeatureLogger({});
    this.models = new Map();
    this.versions = new Map();
    this.initialize();
  }

  private async initialize(): Promise<void> {
    try {
      await fs.mkdir(this.config.storagePath, { recursive: true });
      await this.loadModels();
    } catch (error) {
      this.logger.error('Failed to initialize model registry', error);
      throw error;
    }
  }

  private async loadModels(): Promise<void> {
    try {
      const files = await fs.readdir(this.config.storagePath);
      for (const file of files) {
        if (file.endsWith('.json')) {
          const content = await fs.readFile(path.join(this.config.storagePath, file), 'utf-8');
          const model = JSON.parse(content) as ModelMetadata;
          this.models.set(model.id, model);
          await this.loadVersions(model.id);
        }
      }
    } catch (error) {
      this.logger.error('Failed to load models', error);
      throw error;
    }
  }

  private async loadVersions(modelId: string): Promise<void> {
    try {
      const versionPath = path.join(this.config.storagePath, modelId, 'versions');
      const files = await fs.readdir(versionPath);
      const versions: ModelVersion[] = [];

      for (const file of files) {
        if (file.endsWith('.json')) {
          const content = await fs.readFile(path.join(versionPath, file), 'utf-8');
          versions.push(JSON.parse(content) as ModelVersion);
        }
      }

      this.versions.set(modelId, versions);
    } catch (error) {
      this.logger.error(`Failed to load versions for model ${modelId}`, error);
      throw error;
    }
  }

  async registerModel(metadata: ModelMetadata): Promise<string> {
    try {
      const modelPath = path.join(this.config.storagePath, metadata.id);
      await fs.mkdir(modelPath, { recursive: true });
      await fs.mkdir(path.join(modelPath, 'versions'), { recursive: true });

      await fs.writeFile(path.join(modelPath, 'metadata.json'), JSON.stringify(metadata, null, 2));

      this.models.set(metadata.id, metadata);
      this.versions.set(metadata.id, []);

      this.logger.info(`Registered new model: ${metadata.id}`);
      return metadata.id;
    } catch (error) {
      this.logger.error('Failed to register model', error);
      throw error;
    }
  }

  async getModel(modelId: string): Promise<ModelMetadata> {
    const model = this.models.get(modelId);
    if (!model) {
      throw new Error(`Model not found: ${modelId}`);
    }
    return model;
  }

  async updateModel(modelId: string, version: ModelVersion): Promise<void> {
    try {
      const versions = this.versions.get(modelId) || [];
      versions.push(version);

      // Maintain version limit
      if (versions.length > this.config.maxVersions) {
        versions.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
        versions.splice(this.config.maxVersions);
      }

      await fs.writeFile(
        path.join(this.config.storagePath, modelId, 'versions', `${version.version}.json`),
        JSON.stringify(version, null, 2)
      );

      this.versions.set(modelId, versions);
      this.logger.info(`Updated model ${modelId} with version ${version.version}`);
    } catch (error) {
      this.logger.error(`Failed to update model ${modelId}`, error);
      throw error;
    }
  }

  async getModelVersions(modelId: string): Promise<ModelVersion[]> {
    return this.versions.get(modelId) || [];
  }

  async getModelMetadata(modelId: string): Promise<ModelMetadata> {
    const model = this.models.get(modelId);
    if (!model) {
      throw new Error(`Model not found: ${modelId}`);
    }
    return model;
  }

  async updateModelMetadata(modelId: string, metadata: Partial<ModelMetadata>): Promise<void> {
    try {
      const model = await this.getModel(modelId);
      const updatedModel = { ...model, ...metadata, updatedAt: new Date() };

      await fs.writeFile(
        path.join(this.config.storagePath, modelId, 'metadata.json'),
        JSON.stringify(updatedModel, null, 2)
      );

      this.models.set(modelId, updatedModel);
      this.logger.info(`Updated metadata for model ${modelId}`);
    } catch (error) {
      this.logger.error(`Failed to update metadata for model ${modelId}`, error);
      throw error;
    }
  }

  async updateMetrics(modelId: string, evaluation: any): Promise<void> {
    try {
      const versions = this.versions.get(modelId);
      if (!versions || versions.length === 0) {
        throw new Error(`No versions found for model ${modelId}`);
      }

      const latestVersion = versions[versions.length - 1];
      latestVersion.metrics = evaluation;

      await fs.writeFile(
        path.join(this.config.storagePath, modelId, 'versions', `${latestVersion.version}.json`),
        JSON.stringify(latestVersion, null, 2)
      );

      this.logger.info(`Updated metrics for model ${modelId}`);
    } catch (error) {
      this.logger.error(`Failed to update metrics for model ${modelId}`, error);
      throw error;
    }
  }

  async deleteModel(modelId: string): Promise<void> {
    try {
      const modelPath = path.join(this.config.storagePath, modelId);
      await fs.rm(modelPath, { recursive: true });

      this.models.delete(modelId);
      this.versions.delete(modelId);

      this.logger.info(`Deleted model ${modelId}`);
    } catch (error) {
      this.logger.error(`Failed to delete model ${modelId}`, error);
      throw error;
    }
  }

  async backup(): Promise<void> {
    if (!this.config.backupEnabled) return;

    try {
      const backupPath = path.join(this.config.storagePath, 'backups', new Date().toISOString());
      await fs.mkdir(backupPath, { recursive: true });

      for (const [modelId, model] of this.models.entries()) {
        const modelPath = path.join(this.config.storagePath, modelId);
        const backupModelPath = path.join(backupPath, modelId);

        await fs.mkdir(backupModelPath, { recursive: true });
        await fs.cp(modelPath, backupModelPath, { recursive: true });
      }

      this.logger.info('Created model registry backup');
    } catch (error) {
      this.logger.error('Failed to create backup', error);
      throw error;
    }
  }
}

