import axios from 'axios'
import { useNavigate } from 'react-router-dom'
import { useState, useEffect } from 'react'


interface User {
  id: string
  username: string
  email: string
}

interface AuthState {
  user: User | null
  token: string | null
  loading: boolean
  error: string | null
}

export const useAuth = () => {
  const [state, setState] = useState<AuthState>({
    user: null,
    token: localStorage.getItem('token'),
    loading: true,
    error: null,
  })
  
  const navigate = useNavigate()
  
  useEffect(() => {
    const token = localStorage.getItem('token')
    if (token) {
      // Verify token and get user data
      axios.get('/api/v1/auth/me', {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then(response => {
        setState(prev => ({
          ...prev,
          user: response.data,
          loading: false
        }))
      })
      .catch(() => {
        localStorage.removeItem('token')
        setState(prev => ({
          ...prev,
          token: null,
          user: null,
          loading: false
        }))
      })
    } else {
      setState(prev => ({ ...prev, loading: false }))
    }
  }, [])
  
  const login = async (username: string, password: string) => {
    try {
      const response = await axios.post('/api/v1/auth/token', {
        username,
        password
      })
      
      const { token, user } = response.data
      localStorage.setItem('token', token)
      setState(prev => ({
        ...prev,
        token,
        user,
        error: null
      }))
      
      navigate('/')
    } catch (error) {
      setState(prev => ({
        ...prev,
        error: 'Invalid credentials'
      }))
    }
  }
  
  const logout = () => {
    localStorage.removeItem('token')
    setState({
      user: null,
      token: null,
      loading: false,
      error: null
    })
    navigate('/login')
  }
  
  return {
    ...state,
    login,
    logout
  }
}

import useStore from '../store/useStore';
import { useEffect } from 'react';



export const useDarkMode = () => {
  const isDarkMode = useStore((state) => state.isDarkMode);
  const toggleDarkMode = useStore((state) => state.toggleDarkMode);

  useEffect(() => {
    const root = window.document.documentElement;
    if (isDarkMode) {
      root.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handleChange = (e: MediaQueryListEvent) => {
      if (!localStorage.getItem('theme')) {
        toggleDarkMode();
      }
    };

    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, [toggleDarkMode]);

  return {
    isDarkMode,
    toggleDarkMode
  };
};

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useStore } from '../store';
import { api } from '../services/api';
import { showError, showSuccess } from '../components/Toaster';
import { Bet, Prop, UserStats, PerformanceData, Headline } from '../types';

export const useDataFetching = () => {
  const queryClient = useQueryClient();
  const { setProps, setStats, setPerformance, setHeadlines } = useStore();

  // Fetch props
  const { data: props, isLoading: isLoadingProps } = useQuery({
    queryKey: ['props'],
    queryFn: async () => {
      const response = await api.getProps();
      setProps(response.data);
      return response.data;
    },
    onError: error => {
      showError('Failed to fetch props');
      console.error('Error fetching props:', error);
    },
  });

  // Fetch user stats
  const { data: stats, isLoading: isLoadingStats } = useQuery({
    queryKey: ['stats'],
    queryFn: async () => {
      const response = await api.getUserStats();
      setStats(response.data);
      return response.data;
    },
    onError: error => {
      showError('Failed to fetch user stats');
      console.error('Error fetching stats:', error);
    },
  });

  // Fetch performance data
  const { data: performance, isLoading: isLoadingPerformance } = useQuery({
    queryKey: ['performance'],
    queryFn: async () => {
      const response = await api.getPerformance();
      setPerformance(response.data);
      return response.data;
    },
    onError: error => {
      showError('Failed to fetch performance data');
      console.error('Error fetching performance:', error);
    },
  });

  // Fetch headlines
  const { data: headlines, isLoading: isLoadingHeadlines } = useQuery({
    queryKey: ['headlines'],
    queryFn: async () => {
      const response = await api.getHeadlines();
      setHeadlines(response.data);
      return response.data;
    },
    onError: error => {
      showError('Failed to fetch headlines');
      console.error('Error fetching headlines:', error);
    },
  });

  // Place bet mutation
  const placeBetMutation = useMutation({
    mutationFn: async (bet: Omit<Bet, 'id' | 'createdAt' | 'updatedAt'>) => {
      const response = await api.placeBet(bet);
      return response.data;
    },
    onSuccess: () => {
      showSuccess('Bet placed successfully');
      queryClient.invalidateQueries({ queryKey: ['stats'] });
    },
    onError: error => {
      showError('Failed to place bet');
      console.error('Error placing bet:', error);
    },
  });

  return {
    props,
    stats,
    performance,
    headlines,
    isLoadingProps,
    isLoadingStats,
    isLoadingPerformance,
    isLoadingHeadlines,
    placeBet: placeBetMutation.mutate,
    isPlacingBet: placeBetMutation.isPending,
  };
};

import { useState, useEffect } from 'react';

interface DeviceMotionState {
  acceleration: {
    x: number | null;
    y: number | null;
    z: number | null;
  };
  accelerationIncludingGravity: {
    x: number | null;
    y: number | null;
    z: number | null;
  };
  rotationRate: {
    alpha: number | null;
    beta: number | null;
    gamma: number | null;
  };
  interval: number | null;
  error: Error | null;
}

export const useDeviceMotion = (): DeviceMotionState => {
  const [state, setState] = useState<DeviceMotionState>({
    acceleration: {
      x: null,
      y: null,
      z: null,
    },
    accelerationIncludingGravity: {
      x: null,
      y: null,
      z: null,
    },
    rotationRate: {
      alpha: null,
      beta: null,
      gamma: null,
    },
    interval: null,
    error: null,
  });

  useEffect(() => {
    const handleMotion = (event: DeviceMotionEvent) => {
      setState({
        acceleration: {
          x: event.acceleration?.x ?? null,
          y: event.acceleration?.y ?? null,
          z: event.acceleration?.z ?? null,
        },
        accelerationIncludingGravity: {
          x: event.accelerationIncludingGravity?.x ?? null,
          y: event.accelerationIncludingGravity?.y ?? null,
          z: event.accelerationIncludingGravity?.z ?? null,
        },
        rotationRate: {
          alpha: event.rotationRate?.alpha ?? null,
          beta: event.rotationRate?.beta ?? null,
          gamma: event.rotationRate?.gamma ?? null,
        },
        interval: event.interval,
        error: null,
      });
    };

    const handleError = (error: Error) => {
      setState(prev => ({
        ...prev,
        error,
      }));
    };

    if (window.DeviceMotionEvent) {
      if (typeof (DeviceMotionEvent as any).requestPermission === 'function') {
        // iOS 13+ requires permission
        (DeviceMotionEvent as any)
          .requestPermission()
          .then((permissionState: string) => {
            if (permissionState === 'granted') {
              window.addEventListener('devicemotion', handleMotion);
            } else {
              handleError(new Error('Permission to access device motion was denied'));
            }
          })
          .catch(handleError);
      } else {
        // Non-iOS devices
        window.addEventListener('devicemotion', handleMotion);
      }
    } else {
      handleError(new Error('Device motion not supported'));
    }

    return () => {
      window.removeEventListener('devicemotion', handleMotion);
    };
  }, []);

  return state;
};

// Example usage:
// const {
//   acceleration,
//   accelerationIncludingGravity,
//   rotationRate,
//   interval,
//   error,
// } = useDeviceMotion();
//
// if (error) return <div>Error: {error.message}</div>;
//
// return (
//   <div>
//     <h3>Acceleration (excluding gravity)</h3>
//     <p>X: {acceleration.x} m/s²</p>
//     <p>Y: {acceleration.y} m/s²</p>
//     <p>Z: {acceleration.z} m/s²</p>
//
//     <h3>Acceleration (including gravity)</h3>
//     <p>X: {accelerationIncludingGravity.x} m/s²</p>
//     <p>Y: {accelerationIncludingGravity.y} m/s²</p>
//     <p>Z: {accelerationIncludingGravity.z} m/s²</p>
//
//     <h3>Rotation Rate</h3>
//     <p>Alpha: {rotationRate.alpha}°/s</p>
//     <p>Beta: {rotationRate.beta}°/s</p>
//     <p>Gamma: {rotationRate.gamma}°/s</p>
//
//     <p>Interval: {interval}ms</p>
//   </div>
// );

import { useState, useEffect } from 'react';

interface DeviceOrientationState {
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  absolute: boolean | null;
  error: Error | null;
}

export const useDeviceOrientation = (): DeviceOrientationState => {
  const [state, setState] = useState<DeviceOrientationState>({
    alpha: null,
    beta: null,
    gamma: null,
    absolute: null,
    error: null,
  });

  useEffect(() => {
    const handleOrientation = (event: DeviceOrientationEvent) => {
      setState({
        alpha: event.alpha,
        beta: event.beta,
        gamma: event.gamma,
        absolute: event.absolute,
        error: null,
      });
    };

    const handleError = (error: Error) => {
      setState(prev => ({
        ...prev,
        error,
      }));
    };

    if (window.DeviceOrientationEvent) {
      if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
        // iOS 13+ requires permission
        (DeviceOrientationEvent as any)
          .requestPermission()
          .then((permissionState: string) => {
            if (permissionState === 'granted') {
              window.addEventListener('deviceorientation', handleOrientation);
            } else {
              handleError(new Error('Permission to access device orientation was denied'));
            }
          })
          .catch(handleError);
      } else {
        // Non-iOS devices
        window.addEventListener('deviceorientation', handleOrientation);
      }
    } else {
      handleError(new Error('Device orientation not supported'));
    }

    return () => {
      window.removeEventListener('deviceorientation', handleOrientation);
    };
  }, []);

  return state;
};

// Example usage:
// const { alpha, beta, gamma, absolute, error } = useDeviceOrientation();
//
// if (error) return <div>Error: {error.message}</div>;
//
// return (
//   <div>
//     <p>Alpha (z-axis rotation): {alpha}°</p>
//     <p>Beta (x-axis rotation): {beta}°</p>
//     <p>Gamma (y-axis rotation): {gamma}°</p>
//     <p>Absolute: {absolute ? 'Yes' : 'No'}</p>
//   </div>
// );

import { useState, useCallback, useEffect } from 'react';



type ValidationRule<T> = {
  validate: (value: T) => boolean;
  message: string;
};

type FieldRules<T> = {
  [K in keyof T]?: ValidationRule<T[K]>[];
};

type FormErrors<T> = {
  [K in keyof T]?: string;
};

interface UseFormOptions<T> {
  initialValues: T;
  validationRules?: FieldRules<T>;
  onSubmit?: (values: T) => void | Promise<void>;
  validateOnChange?: boolean;
  validateOnBlur?: boolean;
}

export const useForm = <T extends Record<string, any>>({
  initialValues,
  validationRules = {},
  onSubmit,
  validateOnChange = false,
  validateOnBlur = true
}: UseFormOptions<T>) => {
  const [values, setValues] = useState<T>(initialValues);
  const [errors, setErrors] = useState<FormErrors<T>>({});
  const [touched, setTouched] = useState<Record<keyof T, boolean>>(() => {
    const touchedFields = {} as Record<keyof T, boolean>;
    Object.keys(initialValues).forEach((key) => {
      touchedFields[key as keyof T] = false;
    });
    return touchedFields;
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const validateField = useCallback(
    (name: keyof T, value: T[keyof T]): string | undefined => {
      const fieldRules = validationRules[name];
      if (!fieldRules) return undefined;

      for (const rule of fieldRules) {
        if (!rule.validate(value)) {
          return rule.message;
        }
      }

      return undefined;
    },
    [validationRules]
  );

  const validateForm = useCallback((): FormErrors<T> => {
    const newErrors: FormErrors<T> = {};
    let hasErrors = false;

    Object.keys(values).forEach((key) => {
      const error = validateField(key as keyof T, values[key as keyof T]);
      if (error) {
        newErrors[key as keyof T] = error;
        hasErrors = true;
      }
    });

    return hasErrors ? newErrors : {};
  }, [values, validateField]);

  const handleChange = useCallback(
    (name: keyof T, value: T[keyof T]) => {
      setValues((prev) => ({ ...prev, [name]: value }));
      if (validateOnChange) {
        const error = validateField(name, value);
        setErrors((prev) => ({ ...prev, [name]: error }));
      }
    },
    [validateOnChange, validateField]
  );

  const handleBlur = useCallback(
    (name: keyof T) => {
      setTouched((prev) => ({ ...prev, [name]: true }));
      if (validateOnBlur) {
        const error = validateField(name, values[name]);
        setErrors((prev) => ({ ...prev, [name]: error }));
      }
    },
    [validateOnBlur, validateField, values]
  );

  const handleSubmit = useCallback(
    async (e?: React.FormEvent) => {
      if (e) {
        e.preventDefault();
      }

      const formErrors = validateForm();
      setErrors(formErrors);

      if (Object.keys(formErrors).length === 0 && onSubmit) {
        setIsSubmitting(true);
        try {
          await onSubmit(values);
        } catch (error) {
          console.error('Form submission error:', error);
        } finally {
          setIsSubmitting(false);
        }
      }
    },
    [validateForm, onSubmit, values]
  );

  const reset = useCallback(() => {
    setValues(initialValues);
    setErrors({});
    setTouched(
      Object.keys(initialValues).reduce(
        (acc, key) => ({ ...acc, [key]: false }),
        {} as Record<keyof T, boolean>
      )
    );
  }, [initialValues]);

  const setFieldValue = useCallback(
    (name: keyof T, value: T[keyof T]) => {
      handleChange(name, value);
    },
    [handleChange]
  );

  const setFieldError = useCallback((name: keyof T, error: string) => {
    setErrors((prev) => ({ ...prev, [name]: error }));
  }, []);

  useEffect(() => {
    return () => {
      setValues(initialValues);
      setErrors({});
      setTouched({} as Record<keyof T, boolean>);
    };
  }, [initialValues]);

  return {
    values,
    errors,
    touched,
    isSubmitting,
    handleChange,
    handleBlur,
    handleSubmit,
    reset,
    setFieldValue,
    setFieldError,
    validateField,
    validateForm
  };
};

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getPlayers, submitLineup, type Player, type LineupSubmission } from '@/services/api';
import { useCallback, useMemo } from 'react';

export const LINEUP_QUERY_KEY = ['lineup'];

export function useLineupAPI() {
  const queryClient = useQueryClient();

  const {
    data: players = [],
    isLoading,
    error,
  } = useQuery({
    queryKey: LINEUP_QUERY_KEY,
    queryFn: getPlayers,
  });

  const submitMutation = useMutation({
    mutationFn: submitLineup,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: LINEUP_QUERY_KEY });
    },
  });

  const filterPlayers = useCallback(
    ({
      position,
      team,
      minSalary,
      maxSalary,
      minConfidence,
      searchTerm,
    }: {
      position?: string;
      team?: string;
      minSalary?: number;
      maxSalary?: number;
      minConfidence?: number;
      searchTerm?: string;
    } = {}) => {
      return players.filter(player => {
        if (position && player.position !== position) return false;
        if (team && player.team !== team) return false;
        if (minSalary && player.salary < minSalary) return false;
        if (maxSalary && player.salary > maxSalary) return false;
        if (minConfidence && player.confidence < minConfidence) return false;
        if (searchTerm && !player.name.toLowerCase().includes(searchTerm.toLowerCase()))
          return false;
        return true;
      });
    },
    [players]
  );

  const positions = useMemo(() => {
    return Array.from(new Set(players.map(p => p.position))).sort();
  }, [players]);

  const teams = useMemo(() => {
    return Array.from(new Set(players.map(p => p.team))).sort();
  }, [players]);

  const validateLineup = useCallback((selectedPlayers: Player[]) => {
    const errors: string[] = [];
    const totalSalary = selectedPlayers.reduce((sum, p) => sum + p.salary, 0);

    if (totalSalary > 50000) {
      errors.push('Lineup exceeds salary cap of $50,000');
    }

    const positionCounts = selectedPlayers.reduce(
      (counts, player) => {
        counts[player.position] = (counts[player.position] || 0) + 1;
        return counts;
      },
      {} as Record<string, number>
    );

    // Example position requirements - adjust based on sport
    const requirements = {
      QB: 1,
      RB: 2,
      WR: 3,
      TE: 1,
      FLEX: 1,
      DST: 1,
    };

    Object.entries(requirements).forEach(([position, required]) => {
      const actual = positionCounts[position] || 0;
      if (actual < required) {
        errors.push(`Need ${required} ${position}, have ${actual}`);
      }
    });

    return {
      isValid: errors.length === 0,
      errors,
      totalSalary,
    };
  }, []);

  return {
    players,
    isLoading,
    error,
    filterPlayers,
    positions,
    teams,
    validateLineup,
    submitLineup: submitMutation.mutate,
    isSubmitting: submitMutation.isPending,
    submitError: submitMutation.error,
  };
}

import useStore from '../store/useStore';
import { OddsUpdate, PlayerProp, Sport, PropType } from '../types';
import { useState, useEffect, useCallback } from 'react';
import { useWebSocket } from './useWebSocket';



interface UseLiveOddsOptions {
  sport?: Sport;
  propType?: PropType;
  minOddsChange?: number;
}

export const useLiveOdds = ({
  sport,
  propType,
  minOddsChange = 0.1
}: UseLiveOddsOptions = {}) => {
  const [updates, setUpdates] = useState<OddsUpdate[]>([]);
  const [activeProps, setActiveProps] = useState<PlayerProp[]>([]);
  const { addToast } = useStore();

  const { send, isConnected } = useWebSocket({
    url: 'wss://api.betproai.com/ws/odds',
    onMessage: useCallback(
      (message: any) => {
        if (message.type === 'odds_update') {
          const update = message.data as OddsUpdate;
          
          // Filter by sport and prop type if specified
          if (sport && update.sport !== sport) return;
          if (propType && update.propType !== propType) return;

          // Only show significant changes
          const oddsChange = Math.abs(update.newOdds - update.oldOdds);
          if (oddsChange < minOddsChange) return;

          setUpdates(prev => {
            const newUpdates = [update, ...prev].slice(0, 50); // Keep last 50 updates
            return newUpdates;
          });

          // Notify on significant changes
          if (oddsChange >= 0.5) {
            addToast({
              id: `odds-update-${update.id}`,
              type: 'info',
              title: 'Significant Odds Movement',
              message: `${update.player} ${update.propType} line has moved from ${update.oldOdds} to ${update.newOdds}`
            });
          }
        }
      },
      [sport, propType, minOddsChange, addToast]
    )
  });

  // Subscribe to specific props
  const subscribe = useCallback(
    (props: PlayerProp[]) => {
      if (!isConnected) return;

      setActiveProps(props);
      send({
        type: 'subscribe',
        data: props.map(prop => ({
          id: prop.id,
          sport: prop.player.team.sport,
          propType: prop.type
        }))
      });
    },
    [isConnected, send]
  );

  // Unsubscribe from specific props
  const unsubscribe = useCallback(
    (propIds: string[]) => {
      if (!isConnected) return;

      setActiveProps(prev => prev.filter(prop => !propIds.includes(prop.id)));
      send({
        type: 'unsubscribe',
        data: propIds
      });
    },
    [isConnected, send]
  );

  // Resubscribe on reconnection
  useEffect(() => {
    if (isConnected && activeProps.length > 0) {
      subscribe(activeProps);
    }
  }, [isConnected, activeProps, subscribe]);

  return {
    updates,
    activeProps,
    isConnected,
    subscribe,
    unsubscribe,
    clearUpdates: () => setUpdates([])
  };
};

import React, { createContext, useContext, useState, ReactNode } from 'react';

interface LoggerContextType {
  log: (message: string) => void;
  error: (message: string) => void;
  warn: (message: string) => void;
  info: (message: string) => void;
}

const LoggerContext = createContext<LoggerContextType | undefined>(undefined);

export const useLogger = () => {
  const context = useContext(LoggerContext);
  if (!context) {
    throw new Error('useLogger must be used within a LoggerProvider');
  }
  return context;
};

interface LoggerProviderProps {
  children: ReactNode;
}

export const LoggerProvider: React.FC<LoggerProviderProps> = ({ children }) => {
  const logger = {
    log: (message: string) => console.log(message),
    error: (message: string) => console.error(message),
    warn: (message: string) => console.warn(message),
    info: (message: string) => console.info(message),
  };

  return React.createElement(LoggerContext.Provider, { value: logger }, children);
};

import { useState, useEffect, useCallback } from 'react';
import { MLSimulationService } from '../services/MLSimulationService';
