import { useState, useEffect } from 'react';
import { useAuth } from './useAuth';

interface CalibrationPoint {
  prob_pred: number;
  prob_true: number;
  count: number;
}

interface ModelCalibration {
  model: string;
  calibration_curve: CalibrationPoint[];
  brier_score: number;
  timestamp: string;
}

interface CalibrationState {
  calibration: ModelCalibration[];
  loading: boolean;
  error: string | null;
}

export const useModelCalibration = () => {
  const [state, setState] = useState<CalibrationState>({
    calibration: [],
    loading: true,
    error: null,
  });

  const { token } = useAuth();

  const fetchCalibration = async () => {
    try {
      const response = await fetch('/api/predictions/model-calibration', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch model calibration');
      }

      const calibration = await response.json();
      setState(prev => ({
        ...prev,
        calibration,
        loading: false,
      }));
    } catch (error) {
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'An error occurred',
        loading: false,
      }));
    }
  };

  const getLatestCalibration = () => {
    if (state.calibration.length === 0) return null;
    return state.calibration[state.calibration.length - 1];
  };

  const getCalibrationHistory = (model: string) => {
    return state.calibration
      .filter(c => c.model === model)
      .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  };

  const getCalibrationTrend = (model: string) => {
    const history = getCalibrationHistory(model);
    return history.map(h => ({
      timestamp: h.timestamp,
      brier_score: h.brier_score,
    }));
  };

  const getCalibrationError = (model: string) => {
    const latest = getLatestCalibration();
    if (!latest) return null;

    const calibrationCurve = latest.calibration_curve;
    let totalError = 0;
    let totalCount = 0;

    for (const point of calibrationCurve) {
      const error = Math.abs(point.prob_pred - point.prob_true);
      totalError += error * point.count;
      totalCount += point.count;
    }

    return totalCount > 0 ? totalError / totalCount : null;
  };

  const getCalibrationReliability = (model: string) => {
    const latest = getLatestCalibration();
    if (!latest) return null;

    const calibrationCurve = latest.calibration_curve;
    let reliability = 0;
    let totalCount = 0;

    for (const point of calibrationCurve) {
      const reliabilityScore = 1 - Math.abs(point.prob_pred - point.prob_true);
      reliability += reliabilityScore * point.count;
      totalCount += point.count;
    }

    return totalCount > 0 ? reliability / totalCount : null;
  };

  useEffect(() => {
    if (token) {
      fetchCalibration();
    }
  }, [token]);

  return {
    calibration: state.calibration,
    loading: state.loading,
    error: state.error,
    fetchCalibration,
    getLatestCalibration,
    getCalibrationHistory,
    getCalibrationTrend,
    getCalibrationError,
    getCalibrationReliability,
  };
};

import { ML_CONFIG } from '../config/constants';
import { predictionService, PredictionRequest, PredictionResponse, GeneralInsight } from '../services/predictionService';
import { useState, useCallback } from 'react';


interface UsePredictionReturn {
    makePrediction: (features: { [key: string]: number }, propId?: string, context?: { [key: string]: any }) => Promise<PredictionResponse>;
    getInsights: () => Promise<GeneralInsight[]>;
    isLoading: boolean;
    error: Error | null;
    lastPrediction: PredictionResponse | null;
}

export function usePrediction(): UsePredictionReturn {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<Error | null>(null);
    const [lastPrediction, setLastPrediction] = useState<PredictionResponse | null>(null);

    const makePrediction = useCallback(async (
        features: { [key: string]: number },
        propId?: string,
        context?: { [key: string]: any }
    ) => {
        setIsLoading(true);
        setError(null);
        
        try {
            const request = predictionService.createPredictionRequest(features, propId, context);
            const response = await predictionService.predict(request);
            
            // Only store predictions above confidence threshold
            if (response.confidence && response.confidence >= ML_CONFIG.CONFIDENCE_THRESHOLD) {
                setLastPrediction(response);
            }
            
            return response;
        } catch (err) {
            const error = err instanceof Error ? err : new Error('Failed to make prediction');
            setError(error);
            throw error;
        } finally {
            setIsLoading(false);
        }
    }, []);

    const getInsights = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        
        try {
            return await predictionService.getGeneralInsights();
        } catch (err) {
            const error = err instanceof Error ? err : new Error('Failed to fetch insights');
            setError(error);
            throw error;
        } finally {
            setIsLoading(false);
        }
    }, []);

    return {
        makePrediction,
        getInsights,
        isLoading,
        error,
        lastPrediction
    };
}

import { useState, useCallback } from 'react';
import { Prediction, RiskProfile } from '../types/core';
import { EventBus } from '../unified/EventBus';
import { ErrorHandler } from '../core/ErrorHandler';
import { PerformanceMonitor } from '../unified/PerformanceMonitor';
import { ModelVersioning } from '../unified/ModelVersioning';

export const usePredictionService = () => {
  const eventBus = EventBus.getInstance();
  const errorHandler = ErrorHandler.getInstance();
  const performanceMonitor = PerformanceMonitor.getInstance();
  const modelVersioning = ModelVersioning.getInstance();

  const getPredictions = useCallback(async (riskProfile: RiskProfile): Promise<Prediction[]> => {
    const startTime = performance.now();
    try {
      // Get current model version
      const currentModel = modelVersioning.getCurrentVersion();

      // Emit event to request predictions
      eventBus.emit('prediction:request', {
        riskProfile,
        modelVersion: currentModel.version,
        timestamp: Date.now(),
      });

      // Wait for predictions response
      const response = await new Promise<Prediction[]>((resolve, reject) => {
        const timeout = setTimeout(() => {
          reject(new Error('Prediction request timed out'));
        }, 5000);

        const handler = (predictions: Prediction[]) => {
          clearTimeout(timeout);
          eventBus.off('prediction:response', handler);
          resolve(predictions);
        };

        eventBus.on('prediction:response', handler);
      });

      performanceMonitor.updateComponentMetrics('prediction-service', {
        renderCount: 1,
        renderTime: performance.now() - startTime,
        memoryUsage: JSON.stringify(response).length,
        errorCount: 0,
        lastUpdate: Date.now(),
      });

      return response;
    } catch (error) {
      const err = error as Error;
      errorHandler.handleError(err, {
        code: 'PREDICTION_REQUEST_ERROR',
        category: 'BUSINESS',
        severity: 'HIGH',
        component: 'PredictionService',
        retryable: true,
        recoveryStrategy: {
          type: 'retry',
          maxRetries: 3,
          timeout: 1000,
        },
      });

      performanceMonitor.updateComponentMetrics('prediction-service', {
        renderCount: 0,
        renderTime: 0,
        memoryUsage: 0,
        errorCount: 1,
        lastUpdate: Date.now(),
      });

      throw err;
    }
  }, []);

  const subscribeToUpdates = useCallback(
    (onUpdate: (prediction: Prediction) => void, onError: (error: Error) => void) => {
      const startTime = performance.now();

      const handleUpdate = (prediction: Prediction) => {
        try {
          onUpdate(prediction);
          performanceMonitor.updateComponentMetrics('prediction-service', {
            renderCount: 1,
            renderTime: performance.now() - startTime,
            memoryUsage: JSON.stringify(prediction).length,
            errorCount: 0,
            lastUpdate: Date.now(),
          });
        } catch (error) {
          const err = error as Error;
          onError(err);
          errorHandler.handleError(err, {
            code: 'PREDICTION_UPDATE_ERROR',
            category: 'BUSINESS',
            severity: 'MEDIUM',
            component: 'PredictionService',
            retryable: true,
          });
        }
      };

      const handleError = (error: Error) => {
        onError(error);
        errorHandler.handleError(error, {
          code: 'PREDICTION_SUBSCRIPTION_ERROR',
          category: 'BUSINESS',
          severity: 'MEDIUM',
          component: 'PredictionService',
          retryable: true,
        });
      };

      eventBus.on('prediction:update', handleUpdate);
      eventBus.on('prediction:error', handleError);

      return () => {
        eventBus.off('prediction:update', handleUpdate);
        eventBus.off('prediction:error', handleError);
      };
    },
    []
  );

  return {
    getPredictions,
    subscribeToUpdates,
  };
};

import { useState, useEffect, useCallback } from 'react';
import { UnifiedServiceRegistry } from '../services/unified/UnifiedServiceRegistry';
import { UnifiedPredictionService } from '../services/unified/UnifiedPredictionService';
import { UnifiedAnalyticsService } from '../services/unified/UnifiedAnalyticsService';
import { webSocketManager } from '../services/unified/WebSocketManager';
import type { PredictionStreamPayload } from '../../shared/webSocket';

export interface PredictionModelOutput {
  confidenceScore: number;
  confidenceColor: 'success' | 'warning' | 'danger';
  topFeatures: Array<{
    name: string;
    value: number;
    impact: number;
  }>;
  modelMeta: {
    type: string;
    version: string;
    lastUpdated: number;
  };
}

export interface PredictionState {
  predictions: Array<{
    id: string;
    event: string;
    market: string;
    selection: string;
    modelOutput: PredictionModelOutput;
    timestamp: number;
  }>;
  loading: boolean;
  error: string | null;
}

export const usePredictions = () => {
  const serviceRegistry = UnifiedServiceRegistry.getInstance();
  const predictionService = serviceRegistry.getService<UnifiedPredictionService>('prediction');
  const analyticsService = serviceRegistry.getService<UnifiedAnalyticsService>('analytics');


  const [state, setState] = useState<PredictionState>({
    predictions: [],
    loading: true,
    error: null,
  });

  const getConfidenceColor = useCallback((score: number): 'success' | 'warning' | 'danger' => {
    if (score >= 0.8) return 'success';
    if (score >= 0.6) return 'warning';
    return 'danger';
  }, []);

  const processModelOutput = useCallback(
    (rawOutput: any): PredictionModelOutput => {
      return {
        confidenceScore: rawOutput.confidence,
        confidenceColor: getConfidenceColor(rawOutput.confidence),
        topFeatures: rawOutput.features.map((f: any) => ({
          name: f.name,
          value: f.value,
          impact: f.impact,
        })),
        modelMeta: {
          type: rawOutput.modelType || 'default',
          version: rawOutput.modelVersion || '1.0.0',
          lastUpdated: rawOutput.timestamp || Date.now(),
        },
      };
    },
    [getConfidenceColor]
  );

  const loadPredictions = useCallback(async () => {
    try {
      setState(prev => ({ ...prev, loading: true, error: null }));
      const predictions = await predictionService.getPredictions();

      const processedPredictions = predictions.map(pred => ({
        id: pred.id,
        event: pred.event,
        market: pred.market,
        selection: pred.selection,
        modelOutput: processModelOutput(pred),
        timestamp: pred.timestamp,
      }));

      setState({
        predictions: processedPredictions,
        loading: false,
        error: null,
      });
    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: 'Failed to load predictions',
      }));
    }
  }, [predictionService, processModelOutput]);

  useEffect(() => {
    loadPredictions();

    // Setup WebSocket connection for real-time updates
    let unsub: (() => void) | undefined;
    let isMounted = true;
    const reconnectTimeout: NodeJS.Timeout | null = null;
    const reconnectAttempts = 0;
    const maxReconnectAttempts = 5;
    const reconnectInterval = 3000;

    function handlePredictionUpdate(data: PredictionStreamPayload) {
      if (!isMounted) return;
      setState(prev => ({
        ...prev,
        predictions: [
          {
            id: data.id,
            event: data.eventName,
            market: data.betType,
            selection: data.selection || '',
            modelOutput: processModelOutput(data),
            timestamp: Date.parse(data.timestamp),
          },
          ...prev.predictions,
        ],
      }));
    }

    // Subscribe to predictions event
    webSocketManager.on('predictions', handlePredictionUpdate);

    return () => {
      isMounted = false;
      webSocketManager.off('predictions', handlePredictionUpdate);
    };
  }, [loadPredictions, webSocketService, processModelOutput]);

  const getPredictionById = useCallback(
    (id: string) => {
      return state.predictions.find(p => p.id === id);
    },
    [state.predictions]
  );

  const getRecentPredictions = useCallback(
    (limit: number = 5) => {
      return state.predictions.slice(0, limit);
    },
    [state.predictions]
  );

  return {
    ...state,
    loadPredictions,
    getPredictionById,
    getRecentPredictions,
  };
};

import { useStore } from '../../stores/useStore';
import type { Opportunity } from '../../types/core';
import type { PlayerProp, Sport, PropType } from '../../types/core';
import { dailyFantasyService } from '../services/dailyFantasy';
import { oddsjamService } from '../services/oddsjam';
import { useState, useEffect, useCallback } from 'react';
import { webSocketManager } from '../services/unified/WebSocketManager';



interface UsePropsOptions {
  autoRefresh?: boolean;
  refreshInterval?: number;
  sport?: Sport;
  propType?: PropType;
}

export const useProps = ({
  autoRefresh = true,
  refreshInterval = 30000,
  sport,
  propType
}: UsePropsOptions = {}) => {
  const [props, setProps] = useState<PlayerProp[]>([]);
  const [opportunities, setOpportunities] = useState<Opportunity[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const { addToast } = useStore();

  const fetchProps = useCallback(async () => {
    try {
      const [propsData, arbitrageData] = await Promise.all([
        dailyFantasyService.getPlayers({ sport, position: propType }),
        oddsjamService.getArbitrageOpportunities(sport || 'NBA')
      ]);

      setProps(propsData as PlayerProp[]);
      setOpportunities(
        (arbitrageData as any[]).map((item) => ({
          ...item,
          propId: item.id,
          analysis: {
            historicalTrends: [],
            marketSignals: [],
            riskFactors: []
          }
        }))
      );
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error('Failed to fetch props'));
      addToast({
        id: 'props-error',
        type: 'error',
        title: 'Error',
        message: 'Failed to fetch props data'
      });
    } finally {
      setIsLoading(false);
    }
  }, [sport, propType, addToast]);

  useEffect(() => {
    fetchProps();

    if (autoRefresh) {
      const interval = setInterval(fetchProps, refreshInterval);
      return () => clearInterval(interval);
    }
  }, [fetchProps, autoRefresh, refreshInterval]);

  useEffect(() => {
    function handlePropUpdate(data: PlayerProp) {
      setProps(prev => {
        const index = prev.findIndex(p => p.id === data.id);
        if (index === -1) return [...prev, data];
        const updated = [...prev];
        updated[index] = data;
        return updated;
      });
    }

    function handleArbitrageAlert(data: Opportunity & { potentialProfit?: number; player?: { name: string } }) {
      setOpportunities(prev => [...prev, data]);
      addToast({
        id: data.id,
        type: 'info',
        title: 'New Arbitrage Opportunity',
        message: `${data.potentialProfit ?? ''}% profit available on ${data.player?.name ?? ''}`
      });
    }

    webSocketManager.on('prop_update', handlePropUpdate);
    webSocketManager.on('arbitrage_alert', handleArbitrageAlert);

    return () => {
      webSocketManager.off('prop_update', handlePropUpdate);
      webSocketManager.off('arbitrage_alert', handleArbitrageAlert);
    };
  }, [addToast]);

  const refreshProps = () => {
    setIsLoading(true);
    fetchProps();
  };

  return {
    props,
    opportunities,
    isLoading,
    error,
    refreshProps
  };
};

import { useApiRequest } from './useApiRequest';
import { useState, useCallback, useRef, useEffect } from 'react';



interface QueryConfig<T> {
  url: string;
  params?: Record<string, any>;
  transform?: (data: any) => T;
  dependencies?: any[];
  enabled?: boolean;
  refetchInterval?: number;
  onSuccess?: (data: T) => void;
  onError?: (error: Error) => void;
}

interface QueryState<T> {
  data: T | null;
  error: Error | null;
  isLoading: boolean;
  isValidating: boolean;
  timestamp: number | null;
}

interface QueryResult<T> extends QueryState<T> {
  refetch: () => Promise<void>;
  setData: (data: T) => void;
  updateData: (updater: (prev: T | null) => T) => void;
  reset: () => void;
}

interface QueryBuilderOptions {
  cacheTime?: number;
  retries?: number;
  retryDelay?: number;
  suspense?: boolean;
}

export function useQueryBuilder<T>(
  config: QueryConfig<T>,
  options: QueryBuilderOptions = {}
): QueryResult<T> {
  const {
    url,
    params,
    transform,
    dependencies = [],
    enabled = true,
    refetchInterval,
    onSuccess,
    onError
  } = config;

  const queryUrl = useCallback(() => {
    const searchParams = new URLSearchParams();
    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value != null) {
          searchParams.append(key, String(value));
        }
      });
    }
    const queryString = searchParams.toString();
    return queryString ? `${url}?${queryString}` : url;
  }, [url, params]);

  const {
    data: rawData,
    error,
    isLoading,
    isValidating,
    mutate
  } = useApiRequest<any>(queryUrl(), {
    cacheTime: options.cacheTime,
    retries: options.retries,
    retryDelay: options.retryDelay,
    enabled: enabled,
    onError
  });

  const [state, setState] = useState<QueryState<T>>({
    data: null,
    error: null,
    isLoading: true,
    isValidating: false,
    timestamp: null
  });

  const transformData = useCallback(
    (data: any): T => {
      if (transform) {
        try {
          return transform(data);
        } catch (error) {
          console.error('Error transforming data:', error);
          throw error;
        }
      }
      return data;
    },
    [transform]
  );

  // Update state when raw data changes
  useEffect(() => {
    if (rawData) {
      try {
        const transformedData = transformData(rawData);
        setState(prev => ({
          ...prev,
          data: transformedData,
          error: null,
          isLoading: false,
          isValidating: false,
          timestamp: Date.now()
        }));
        onSuccess?.(transformedData);
      } catch (error) {
        if (error instanceof Error) {
          setState(prev => ({
            ...prev,
            error,
            isLoading: false,
            isValidating: false
          }));
          onError?.(error);
        }
      }
    }
  }, [rawData, transformData, onSuccess, onError]);

  // Handle error state
  useEffect(() => {
    if (error) {
      setState(prev => ({
        ...prev,
        error,
        isLoading: false,
        isValidating: false
      }));
    }
  }, [error]);

  // Setup refetch interval
  useEffect(() => {
    if (!refetchInterval || !enabled) return;

    const intervalId = setInterval(() => {
      mutate();
    }, refetchInterval);

    return () => clearInterval(intervalId);
  }, [refetchInterval, enabled, mutate]);

  // Refetch when dependencies change
  useEffect(() => {
    if (enabled) {
      mutate();
    }
  }, [...dependencies, enabled]);

  const setData = useCallback((data: T) => {
    setState(prev => ({
      ...prev,
      data,
      error: null,
      timestamp: Date.now()
    }));
  }, []);

  const updateData = useCallback((updater: (prev: T | null) => T) => {
    setState(prev => ({
      ...prev,
      data: updater(prev.data),
      timestamp: Date.now()
    }));
  }, []);

  const reset = useCallback(() => {
    setState({
      data: null,
      error: null,
      isLoading: true,
      isValidating: false,
      timestamp: null
    });
  }, []);

  return {
    ...state,
    refetch: mutate,
    setData,
    updateData,
    reset
  };
}

