import { useEffect, useRef, useCallback, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { PREDICTIONS_QUERY_KEY } from './usePredictions';
import { useToast } from '../components/ToastContext';

interface RealtimeMessage {
  type: 'welcome' | 'ping' | 'update' | 'data';
  channel?: string;
  data?: any;
  timestamp: number;
}

interface UseRealtimePredictionsOptions {
  enabled?: boolean;
  channels?: string[];
  onError?: (error: Error) => void;
  reconnectAttempts?: number;
  reconnectInterval?: number;
}

interface ConnectionState {
  isConnected: boolean;
  isConnecting: boolean;
  lastMessageTimestamp: number | null;
  reconnectAttempts: number;
}

export function useRealtimePredictions({
  enabled = true,
  channels = ['predictions', 'market', 'sentiment'],
  onError,
  reconnectAttempts: maxReconnectAttempts = 5,
  reconnectInterval = 5000,
}: UseRealtimePredictionsOptions = {}) {
  const [state, setState] = useState<ConnectionState>({
    isConnected: false,
    isConnecting: false,
    lastMessageTimestamp: null,
    reconnectAttempts: 0,
  });

  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout>();
  const queryClient = useQueryClient();
  const toast = useToast();

  const updateState = useCallback((updates: Partial<ConnectionState>) => {
    setState(prev => ({ ...prev, ...updates }));
  }, []);

  const connect = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;

    updateState({ isConnecting: true });
    const ws = new WebSocket(import.meta.env.VITE_WS_URL || 'ws://localhost:8080');

    ws.onopen = () => {
      updateState({
        isConnected: true,
        isConnecting: false,
        reconnectAttempts: 0,
      });

      // Subscribe to channels
      ws.send(
        JSON.stringify({
          type: 'subscribe',
          channels,
        })
      );
    };

    ws.onclose = () => {
      updateState({
        isConnected: false,
        isConnecting: false,
      });

      // Attempt to reconnect if we haven't exceeded max attempts
      if (state.reconnectAttempts < maxReconnectAttempts) {
        updateState(prev => ({
          reconnectAttempts: prev.reconnectAttempts + 1,
        }));

        reconnectTimeoutRef.current = setTimeout(() => {
          connect();
        }, reconnectInterval);
      } else {
        toast('Connection lost. Please refresh the page.', 'error');
      }
    };

    ws.onerror = error => {
      updateState({
        isConnected: false,
        isConnecting: false,
      });
      onError?.(error as Error);
      toast('Connection error occurred', 'error');
    };

    ws.onmessage = event => {
      try {
        const message: RealtimeMessage = JSON.parse(event.data);
        updateState({ lastMessageTimestamp: Date.now() });

        switch (message.type) {
          case 'ping':
            ws.send(JSON.stringify({ type: 'pong' }));
            break;

          case 'update':
          case 'data':
            if (message.channel === 'predictions') {
              // Update predictions cache with timestamp
              queryClient.setQueryData(PREDICTIONS_QUERY_KEY, (oldData: any) => {
                if (!oldData) return message.data;
                return {
                  ...oldData,
                  predictions: {
                    ...oldData.predictions,
                    ...message.data,
                    lastUpdated: message.timestamp,
                  },
                };
              });
            }
            break;
        }
      } catch (error) {
        console.error('Failed to parse WebSocket message:', error);
        toast('Failed to process update', 'error');
      }
    };

    wsRef.current = ws;
  }, [
    channels,
    onError,
    queryClient,
    toast,
    maxReconnectAttempts,
    reconnectInterval,
    state.reconnectAttempts,
    updateState,
  ]);

  const disconnect = useCallback(() => {
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
    }
    updateState({
      isConnected: false,
      isConnecting: false,
      lastMessageTimestamp: null,
      reconnectAttempts: 0,
    });
  }, [updateState]);

  useEffect(() => {
    if (enabled) {
      connect();
    } else {
      disconnect();
    }

    return () => {
      disconnect();
    };
  }, [enabled, connect, disconnect]);

  const isStale = useCallback(() => {
    if (!state.lastMessageTimestamp) return true;
    const staleThreshold = 30000; // 30 seconds
    return Date.now() - state.lastMessageTimestamp > staleThreshold;
  }, [state.lastMessageTimestamp]);

  return {
    isConnected: state.isConnected,
    isConnecting: state.isConnecting,
    lastMessageTimestamp: state.lastMessageTimestamp,
    isStale: isStale(),
    reconnectAttempts: state.reconnectAttempts,
    connect,
    disconnect,
  };
}

import { useState, useCallback, useEffect } from 'react';
import { RiskProfile } from '../types/core';
import { EventBus } from '../unified/EventBus';
import { ErrorHandler } from '../unified/ErrorHandler';
import { PerformanceMonitor } from '../unified/PerformanceMonitor';
import { RiskProfileService } from '../services/risk/RiskProfileService';

export function useRiskProfile() {
  // const [riskProfile, setRiskProfile] = useState<RiskProfile>(); // This state is derived from activeProfile from the service
  const [activeProfile, setActiveProfile] = useState<RiskProfile | null>(null);
  const [profiles, setProfiles] = useState<RiskProfile[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const validateBet = useCallback(
    (bet: {
      stake: number;
      confidence: number;
      kellyFraction: number; // Retaining for now, though not used in this iteration
      sport: string; // Retaining for now
      market: string; // Retaining for now
      eventId: string; // Retaining for now
    }) => {
      const errors: string[] = [];

      if (!activeProfile) {
        errors.push('No active risk profile found. Cannot validate bet.');
        return { isValid: false, errors };
      }

      // Assuming RiskProfile has maxStake and confidenceThreshold from core.ts
      // These might be optional, so handle potential undefined values
      const { maxStake, confidenceThreshold } = activeProfile;

      if (typeof maxStake === 'number' && bet.stake > maxStake) {
        errors.push(`Bet stake (${bet.stake}) exceeds the maximum allowed stake (${maxStake}).`);
      }

      if (typeof confidenceThreshold === 'number' && bet.confidence < confidenceThreshold) {
        errors.push(
          `Bet confidence (${bet.confidence}) is below the minimum required threshold (${confidenceThreshold}).`
        );
      }

      // TODO: Add more validation rules based on other RiskProfile properties like:
      // - activeProfile.allowedSports
      // - activeProfile.allowedMarkets
      // - activeProfile.betLimits (e.g., maxDailyLoss, maxExposure)
      // - activeProfile.kellyMultiplierSettings (related to bet.kellyFraction)

      return { isValid: errors.length === 0, errors };
    },
    [activeProfile]
  );

  const riskProfileService = RiskProfileService.getInstance();
  const eventBus = EventBus.getInstance();
  const errorHandler = ErrorHandler.getInstance();
  const performanceMonitor = PerformanceMonitor.getInstance();

  // Load initial profiles
  useEffect(() => {
    const loadProfiles = async () => {
      try {
        setIsLoading(true);
        const allProfiles = riskProfileService.getAllProfiles();
        const currentProfile = riskProfileService.getActiveProfile();

        setProfiles(allProfiles);
        setActiveProfile(currentProfile);
        setError(null);
      } catch (err) {
        const error = err as Error;
        setError(error);
        errorHandler.handleError(error, 'load_risk_profiles');
      } finally {
        setIsLoading(false);
      }
    };

    loadProfiles();
  }, []);

  // Subscribe to profile updates
  useEffect(() => {
    const handleProfileUpdate = (data: { profileId: string }) => {
      const updatedProfile = riskProfileService.getProfile(data.profileId);
      if (updatedProfile) {
        setProfiles(prev => prev.map(p => (p.id === updatedProfile.id ? updatedProfile : p)));
        if (activeProfile?.id === updatedProfile.id) {
          setActiveProfile(updatedProfile);
        }
      }
    };

    const handleProfileActivation = (data: { profileId: string }) => {
      const newActiveProfile = riskProfileService.getProfile(data.profileId);
      if (newActiveProfile) {
        setActiveProfile(newActiveProfile);
      }
    };

    eventBus.on('risk:profile:updated', handleProfileUpdate);
    eventBus.on('risk:profile:activated', handleProfileActivation);

    return () => {
      eventBus.off('risk:profile:updated', handleProfileUpdate);
      eventBus.off('risk:profile:activated', handleProfileActivation);
    };
  }, [activeProfile?.id]);

  const updateProfile = useCallback(async (profile: RiskProfile) => {
    try {
      const startTime = Date.now();
      riskProfileService.updateProfile(profile);
      performanceMonitor.trackMetric('profile_update_duration', Date.now() - startTime);
      return true;
    } catch (err) {
      const error = err as Error;
      setError(error);
      errorHandler.handleError(error, 'update_risk_profile');
      return false;
    }
  }, []);

  const setActiveProfileById = useCallback(async (profileId: string) => {
    try {
      const startTime = Date.now();
      riskProfileService.setActiveProfile(profileId);
      performanceMonitor.trackMetric('profile_activation_duration', Date.now() - startTime);
      return true;
    } catch (err) {
      const error = err as Error;
      setError(error);
      errorHandler.handleError(error, 'activate_risk_profile');
      return false;
    }
  }, []);

  return {
    activeProfile,
    profiles,
    isLoading,
    error,
    updateProfile,
    setActiveProfile: setActiveProfileById,
  };
}

import { useDataSync } from './useDataSync';
import { useRealtimeData } from './useRealtimeData';
import { useState, useEffect, useCallback } from 'react';



export type AlertType = 'INJURY' | 'LINEUP' | 'WEATHER' | 'LINE_MOVEMENT' | 'ARBITRAGE';

export interface Alert {
  id: string;
  type: AlertType;
  severity: 'low' | 'medium' | 'high';
  title: string;
  message: string;
  timestamp: number;
  metadata: {
    sportId?: string;
    gameId?: string;
    playerId?: string;
    teamId?: string;
    impactScore?: number;
    lineMovement?: {
      from: number;
      to: number;
      book: string;
    };
  };
  read: boolean;
}

interface WebSocketMessage {
  type: string;
  data: Alert;
}

interface SmartAlertsConfig {
  enabledTypes?: AlertType[];
  minSeverity?: 'low' | 'medium' | 'high';
  wsEndpoint: string;
  onNewAlert?: (alert: Alert) => void;
}

interface SmartAlertsResult {
  alerts: Alert[];
  unreadCount: number;
  markAsRead: (alertId: string) => void;
  markAllAsRead: () => void;
  clearAlerts: () => void;
  isConnected: boolean;
}

export function useSmartAlerts({
  enabledTypes = ['INJURY', 'LINEUP', 'WEATHER', 'LINE_MOVEMENT', 'ARBITRAGE'],
  minSeverity = 'low',
  wsEndpoint,
  onNewAlert
}: SmartAlertsConfig): SmartAlertsResult {
  const [alerts, setAlerts] = useState<Alert[]>([]);
  
  const { data: realtimeData, isConnected } = useRealtimeData<Alert>({
    url: wsEndpoint,
    onMessage: (message: WebSocketMessage) => {
      if (message.type === 'ALERT' && isAlertRelevant(message.data)) {
        handleNewAlert(message.data);
      }
    }
  });

  const { data: syncedAlerts } = useDataSync({
    key: 'smart-alerts',
    initialData: alerts,
    syncInterval: 60000
  });

  const isAlertRelevant = useCallback((alert: Alert) => {
    const severityLevels = { low: 0, medium: 1, high: 2 };
    return (
      enabledTypes.includes(alert.type) &&
      severityLevels[alert.severity] >= severityLevels[minSeverity]
    );
  }, [enabledTypes, minSeverity]);

  const handleNewAlert = useCallback((alert: Alert) => {
    setAlerts(prev => [alert, ...prev].slice(0, 100)); // Keep last 100 alerts
    onNewAlert?.(alert);
  }, [onNewAlert]);

  const markAsRead = useCallback((alertId: string) => {
    setAlerts(prev =>
      prev.map(alert =>
        alert.id === alertId ? { ...alert, read: true } : alert
      )
    );
  }, []);

  const markAllAsRead = useCallback(() => {
    setAlerts(prev =>
      prev.map(alert => ({ ...alert, read: true }))
    );
  }, []);

  const clearAlerts = useCallback(() => {
    setAlerts([]);
  }, []);

  const unreadCount = alerts.filter(alert => !alert.read).length;

  return {
    alerts,
    unreadCount,
    markAsRead,
    markAllAsRead,
    clearAlerts,
    isConnected
  };
}

import { useState, useCallback, useRef, useEffect } from 'react';



type StateConfig<TState extends string, TEvent extends string> = {
  [K in TState]: {
    on?: {
      [E in TEvent]?: {
        target: TState;
        action?: (context: unknown) => void;
        guard?: (context: unknown) => boolean;
      };
    };
    onEnter?: (context: unknown) => void;
    onExit?: (context: unknown) => void;
  };
};

interface StateMachineOptions<TState extends string, TEvent extends string> {
  initial: TState;
  states: StateConfig<TState, TEvent>;
  context?: unknown;
  onTransition?: (from: TState, to: TState, event: TEvent) => void;
}

interface StateMachineResult<TState extends string, TEvent extends string> {
  state: TState;
  context: unknown;
  send: (event: TEvent) => void;
  can: (event: TEvent) => boolean;
  matches: (state: TState) => boolean;
  history: Array<{ state: TState; event: TEvent | null }>;
}

export function useStateMachine<TState extends string, TEvent extends string>({
  initial,
  states,
  context: initialContext = {},
  onTransition
}: StateMachineOptions<TState, TEvent>): StateMachineResult<TState, TEvent> {
  const [currentState, setCurrentState] = useState<TState>(initial);
  const [context, setContext] = useState(initialContext);
  const historyRef = useRef<Array<{ state: TState; event: TEvent | null }>>([
    { state: initial, event: null }
  ]);

  const transition = useCallback(
    (event: TEvent) => {
      const stateConfig = states[currentState];
      const eventConfig = stateConfig.on?.[event];

      if (!eventConfig) {
        console.warn(
          `No transition defined for event "${event}" in state "${currentState}"`
        );
        return false;
      }

      if (eventConfig.guard && !eventConfig.guard(context)) {
        console.warn(
          `Transition guard prevented event "${event}" in state "${currentState}"`
        );
        return false;
      }

      // Execute exit action of current state
      stateConfig.onExit?.(context);

      // Execute transition action
      if (eventConfig.action) {
        eventConfig.action(context);
      }

      const nextState = eventConfig.target;

      // Execute enter action of next state
      states[nextState].onEnter?.(context);

      // Update state
      setCurrentState(nextState);
      historyRef.current.push({ state: nextState, event });

      // Notify transition listeners
      onTransition?.(currentState, nextState, event);

      return true;
    },
    [currentState, states, context, onTransition]
  );

  const can = useCallback(
    (event: TEvent): boolean => {
      const stateConfig = states[currentState];
      const eventConfig = stateConfig.on?.[event];

      if (!eventConfig) {
        return false;
      }

      if (eventConfig.guard && !eventConfig.guard(context)) {
        return false;
      }

      return true;
    },
    [currentState, states, context]
  );

  const matches = useCallback(
    (state: TState): boolean => currentState === state,
    [currentState]
  );

  useEffect(() => {
    // Execute initial state's enter action
    states[initial].onEnter?.(context);
  }, [initial, states]);

  return {
    state: currentState,
    context,
    send: transition,
    can,
    matches,
    history: historyRef.current
  };
}

