import { PlayerProp, Entry, PerformanceMetrics, BettingOpportunity, Alert, BetRecord } from '../types/core';
import { ProcessedPrizePicksProp } from '../types/prizePicks';
import { create } from 'zustand';
import { devtools } from 'zustand/middleware';
import { persist } from 'zustand/middleware';



interface User {
  id: string;
  name: string;
  email: string;
  role: 'user' | 'admin';
}

interface AppState {
  // Auth
  user: User | null;
  login: (email: string, password: string) => Promise<void>;
  register: (name: string, email: string, password: string) => Promise<void>;
  logout: () => void;

  // Props and Entries
  props: ProcessedPrizePicksProp[];
  selectedProps: string[];
  entries: Entry[];
  
  // Performance and Analytics
  metrics: PerformanceMetrics | null;
  opportunities: BettingOpportunity[];
  alerts: Alert[];
  
  // UI State
  darkMode: boolean;
  sidebarOpen: boolean;
  activeModal: string | null;
  
  // Actions
  setProps: (props: ProcessedPrizePicksProp[]) => void;
  togglePropSelection: (propId: string) => void;
  addEntry: (entry: Entry) => void;
  updateEntry: (entryId: string, updates: Partial<Entry>) => void;
  setMetrics: (metrics: PerformanceMetrics) => void;
  addOpportunity: (opportunity: BettingOpportunity) => void;
  removeOpportunity: (opportunityId: string) => void;
  addAlert: (alert: Alert) => void;
  removeAlert: (alertId: string) => void;
  toggleDarkMode: () => void;
  toggleSidebar: () => void;
  setActiveModal: (modalId: string | null) => void;
  bets: BetRecord[];
  addBet: (bet: BetRecord) => void;
  updateBet: (betId: string, updates: Partial<BetRecord>) => void;
  removeBet: (betId: string) => void;
}

const useStore = create<AppState>()(
  devtools(
    persist(
      (set) => ({
        // Initial State
        user: null,
        props: [],
        selectedProps: [],
        entries: [],
        metrics: null,
        opportunities: [],
        alerts: [],
        darkMode: false,
        sidebarOpen: true,
        activeModal: null,
        bets: [],

        // Auth Actions
        login: async (email: string, password: string) => {
          try {
            // TODO: Replace with actual API call
            const response = await fetch('/api/auth/login', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ email, password })
            });
            
            if (!response.ok) {
              throw new Error('Invalid credentials');
            }
            
            const user = await response.json();
            set({ user });
          } catch (error) {
            throw error;
          }
        },

        register: async (name: string, email: string, password: string) => {
          try {
            // TODO: Replace with actual API call
            const response = await fetch('/api/auth/register', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ name, email, password })
            });
            
            if (!response.ok) {
              throw new Error('Registration failed');
            }
            
            const user = await response.json();
            set({ user });
          } catch (error) {
            throw error;
          }
        },

        logout: () => set({ user: null }),

        // Actions
        setProps: (props) => set({ props }),
        
        togglePropSelection: (propId) =>
          set((state) => ({
            selectedProps: state.selectedProps.includes(propId)
              ? state.selectedProps.filter(id => id !== propId)
              : [...state.selectedProps, propId]
          })),
        
        addEntry: (entry) =>
          set((state) => ({
            entries: [...state.entries, entry]
          })),
        
        updateEntry: (entryId, updates) =>
          set((state) => ({
            entries: state.entries.map(entry =>
              entry.id === entryId ? { ...entry, ...updates } : entry
            )
          })),
        
        setMetrics: (metrics) => set({ metrics }),
        
        addOpportunity: (opportunity) =>
          set((state) => ({
            opportunities: [...state.opportunities, opportunity]
          })),
        
        removeOpportunity: (opportunityId) =>
          set((state) => ({
            opportunities: state.opportunities.filter(opp => opp.id !== opportunityId)
          })),
        
        addAlert: (alert) =>
          set((state) => ({
            alerts: [...state.alerts, alert]
          })),
        
        removeAlert: (alertId) =>
          set((state) => ({
            alerts: state.alerts.filter(alert => alert.id !== alertId)
          })),
        
        toggleDarkMode: () =>
          set((state) => ({
            darkMode: !state.darkMode
          })),
        
        toggleSidebar: () =>
          set((state) => ({
            sidebarOpen: !state.sidebarOpen
          })),
        
        setActiveModal: (modalId) => set({ activeModal: modalId }),
        
        addBet: (bet) => set((state) => ({
          bets: [...state.bets, bet]
        })),
        
        updateBet: (betId, updates) => set((state) => ({
          bets: state.bets.map(bet => 
            bet.id === betId ? { ...bet, ...updates } : bet
          )
        })),
        
        removeBet: (betId) => set((state) => ({
          bets: state.bets.filter(bet => bet.id !== betId)
        })),
      }),
      {
        name: 'sports-betting-store',
        partialize: (state) => ({
          user: state.user,
          props: state.props,
          selectedProps: state.selectedProps,
          entries: state.entries,
          metrics: state.metrics,
          opportunities: state.opportunities,
          alerts: state.alerts,
          darkMode: state.darkMode,
          sidebarOpen: state.sidebarOpen,
          activeModal: state.activeModal,
          bets: state.bets
        })
      }
    )
  )
);

export default useStore;

import { useState, useEffect } from 'react';
import { useAuth } from './useAuth';

interface TimeSeriesPoint {
  timestamp: string;
  value: number;
  forecast?: number;
  lower_bound?: number;
  upper_bound?: number;
  feature?: string;
}

interface TimeSeriesState {
  timeSeries: TimeSeriesPoint[];
  loading: boolean;
  error: string | null;
}

export const useTimeSeries = () => {
  const [state, setState] = useState<TimeSeriesState>({
    timeSeries: [],
    loading: true,
    error: null,
  });

  const { token } = useAuth();

  const fetchTimeSeries = async () => {
    try {
      const response = await fetch('/api/predictions/time-series', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch time series data');
      }

      const timeSeries = await response.json();
      setState(prev => ({
        ...prev,
        timeSeries,
        loading: false,
      }));
    } catch (error) {
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'An error occurred',
        loading: false,
      }));
    }
  };

  const getLatestTimeSeries = () => {
    if (state.timeSeries.length === 0) return null;
    return state.timeSeries[state.timeSeries.length - 1];
  };

  const getTimeSeriesHistory = (feature?: string) => {
    return state.timeSeries
      .filter(ts => !feature || ts.feature === feature)
      .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  };

  const getTimeSeriesTrend = (feature?: string) => {
    const history = getTimeSeriesHistory(feature);
    return history.map(h => ({
      timestamp: h.timestamp,
      value: h.value,
      forecast: h.forecast,
      lower_bound: h.lower_bound,
      upper_bound: h.upper_bound,
    }));
  };

  const getTimeSeriesFeatures = () => {
    const features = new Set<string>();
    state.timeSeries.forEach(ts => {
      if (ts.feature) features.add(ts.feature);
    });
    return Array.from(features);
  };

  const getTimeSeriesSummary = () => {
    const features = getTimeSeriesFeatures();
    const summary = {
      total_points: state.timeSeries.length,
      features: features.length,
      time_range: {
        start: state.timeSeries[0]?.timestamp,
        end: state.timeSeries[state.timeSeries.length - 1]?.timestamp,
      },
      feature_stats: features.map(feature => {
        const points = state.timeSeries.filter(ts => ts.feature === feature);
        const values = points.map(p => p.value);
        return {
          feature,
          count: points.length,
          mean: values.reduce((a, b) => a + b, 0) / values.length,
          min: Math.min(...values),
          max: Math.max(...values),
        };
      }),
    };
    return summary;
  };

  const getForecastAccuracy = (feature?: string) => {
    const history = getTimeSeriesHistory(feature);
    const forecastPoints = history.filter(h => h.forecast !== undefined);

    if (forecastPoints.length === 0) return null;

    let totalError = 0;
    let totalPoints = 0;

    for (const point of forecastPoints) {
      if (point.forecast !== undefined) {
        const error = Math.abs(point.value - point.forecast);
        totalError += error;
        totalPoints++;
      }
    }

    return totalPoints > 0 ? totalError / totalPoints : null;
  };

  const getConfidenceIntervals = (feature?: string) => {
    const history = getTimeSeriesHistory(feature);
    return history.filter(h => h.lower_bound !== undefined && h.upper_bound !== undefined);
  };

  useEffect(() => {
    if (token) {
      fetchTimeSeries();
    }
  }, [token]);

  return {
    timeSeries: state.timeSeries,
    loading: state.loading,
    error: state.error,
    fetchTimeSeries,
    getLatestTimeSeries,
    getTimeSeriesHistory,
    getTimeSeriesTrend,
    getTimeSeriesFeatures,
    getTimeSeriesSummary,
    getForecastAccuracy,
    getConfidenceIntervals,
  };
};

import { useState, useEffect, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { UnifiedServiceRegistry } from '../services/unified/UnifiedServiceRegistry';
import { UnifiedAnalyticsService } from '../services/unified/UnifiedAnalyticsService';
import { webSocketManager } from '../services/unified/WebSocketManager';
import { UnifiedErrorService } from '../services/unified/UnifiedErrorService';

// Types
export interface AnalyticsConfig {
  ml?: {
    autoUpdate?: boolean;
    updateInterval?: number;
  };
  performance?: boolean;
  drift?: boolean;
  betting?: boolean;
  realtime?: boolean;
}

// Stronger typing for MLAnalyticsResult
export interface MLAnalyticsResult {
  predictions: number[];
  probabilities: number[];
  metrics: {
    accuracy: number;
    precision: number;
    recall: number;
    f1Score: number;
  };
  insights: {
    featureImportance: Record<string, number>;
    shap: Record<string, number[]>;
    lime: Record<string, number>;
  };
}

export interface PerformanceMetrics {
  accuracy: number;
  precision: number;
  recall: number;
  f1: number;
  roc_auc: number;
  mae: number;
  rmse: number;
}

export interface ModelPerformance {
  model: string;
  metrics: PerformanceMetrics;
  timestamp: string;
}

export interface DriftPoint {
  timestamp: string;
  value: number;
  threshold: number;
  is_drift: boolean;
  feature?: string;
}

export interface BettingAnalytics {
  roi: number;
  winRate: number;
  profitLoss: number;
  riskMetrics: {
    var: number;
    sharpe: number;
    sortino: number;
  };
  confidence: number;
}

export interface RealtimeMetrics {
  latency: number;
  throughput: number;
  errorRate: number;
  resourceUsage: {
    cpu: number;
    memory: number;
    network: number;
  };
}

export interface AnalyticsError {
  message: string;
  code?: string;
  context?: string;
}

export interface AnalyticsState {
  ml: {
    data: MLAnalyticsResult | null;
    loading: boolean;
    error: string | null;
  };
  performance: {
    data: ModelPerformance[] | null;
    loading: boolean;
    error: string | null;
  };
  drift: {
    data: DriftPoint[] | null;
    loading: boolean;
    error: string | null;
  };
  betting: {
    data: BettingAnalytics | null;
    loading: boolean;
    error: string | null;
  };
  realtime: {
    data: RealtimeMetrics | null;
    loading: boolean;
    error: string | null;
  };
}

export const useUnifiedAnalytics = (config: AnalyticsConfig = {}) => {
  const [state, setState] = useState<AnalyticsState>({
    ml: { data: null, loading: false, error: null },
    performance: { data: null, loading: false, error: null },
    drift: { data: null, loading: false, error: null },
    betting: { data: null, loading: false, error: null },
    realtime: { data: null, loading: false, error: null },
  });

  const serviceRegistry = UnifiedServiceRegistry.getInstance();
  const analyticsService = serviceRegistry.getService<UnifiedAnalyticsService>('analytics');
  // Use 'as any' to bypass BaseService constraint for errorService
  const errorService = serviceRegistry.getService('error') as UnifiedErrorService | undefined;

  // --- ML Analytics (using getModelPerformance as a proxy for ML analytics) ---
  const mlQuery = useQuery<ModelPerformance[] | null, AnalyticsError>({
    queryKey: ['mlAnalytics'],
    queryFn: async () => {
      if (!analyticsService) throw { message: 'Analytics service unavailable' };
      try {
        const result = await analyticsService.getModelPerformance('', '', '');
        setState(prev => ({
          ...prev,
          ml: {
            data: result
              ? {
                  predictions: [],
                  probabilities: [],
                  metrics: result,
                  insights: { featureImportance: {}, shap: {}, lime: {} },
                }
              : null,
            loading: false,
            error: null,
          },
        }));
        return result
          ? [{ model: 'default', metrics: result, timestamp: new Date().toISOString() }]
          : null;
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Failed to fetch ML analytics';
        if (errorService)
          errorService.handleError(new Error(errorMessage), {
            code: 'ML_ANALYTICS_ERROR',
            source: 'useUnifiedAnalytics',
            details: { context: 'mlAnalytics' },
          });
        setState(prev => ({
          ...prev,
          ml: { data: null, loading: false, error: errorMessage },
        }));
        throw {
          message: errorMessage,
          code: 'ML_ANALYTICS_ERROR',
          context: 'mlAnalytics',
        } as AnalyticsError;
      }
    },
    enabled: !!config.ml,
    refetchInterval: config.ml?.autoUpdate ? config.ml.updateInterval : false,
  });

  // --- Performance Metrics ---
  const performanceQuery = useQuery<PerformanceMetrics | null, AnalyticsError>({
    queryKey: ['performanceMetrics'],
    queryFn: async () => {
      if (!analyticsService) throw { message: 'Analytics service unavailable' };
      try {
        const result = await analyticsService.getPerformanceMetrics('week');
        setState(prev => ({
          ...prev,
          performance: {
            data: result
              ? [{ model: 'default', metrics: result, timestamp: new Date().toISOString() }]
              : null,
            loading: false,
            error: null,
          },
        }));
        return result;
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Failed to fetch performance metrics';
        if (errorService)
          errorService.handleError(new Error(errorMessage), {
            code: 'PERFORMANCE_METRICS_ERROR',
            source: 'useUnifiedAnalytics',
            details: { context: 'performanceMetrics' },
          });
        setState(prev => ({
          ...prev,
          performance: { data: null, loading: false, error: errorMessage },
        }));
        throw {
          message: errorMessage,
          code: 'PERFORMANCE_METRICS_ERROR',
          context: 'performanceMetrics',
        } as AnalyticsError;
      }
    },
    enabled: !!config.performance,
  });

  // --- Drift Detection (not implemented in service, placeholder) ---
  const driftQuery = useQuery<DriftPoint[] | null, AnalyticsError>({
    queryKey: ['driftDetection'],
    queryFn: async () => {
      setState(prev => ({
        ...prev,
        drift: { data: null, loading: false, error: null },
      }));
      return null;
    },
    enabled: !!config.drift,
  });

  // --- Betting Analytics (using getBettingStats as a proxy) ---
  const bettingQuery = useQuery<BettingAnalytics | null, AnalyticsError>({
    queryKey: ['bettingAnalytics'],
    queryFn: async () => {
      if (!analyticsService) throw { message: 'Analytics service unavailable' };
      try {
        const result = await analyticsService.getBettingStats('', '', '');
        setState(prev => ({
          ...prev,
          betting: {
            data: result
              ? {
                  roi: 0, // Not available in result
                  winRate: result.winRate ?? 0,
                  profitLoss: result.profitLoss ?? 0,
                  riskMetrics: { var: 0, sharpe: 0, sortino: 0 },
                  confidence: 0,
                }
              : null,
            loading: false,
            error: null,
          },
        }));
        return result
          ? {
              roi: 0, // Not available in result
              winRate: result.winRate ?? 0,
              profitLoss: result.profitLoss ?? 0,
              riskMetrics: { var: 0, sharpe: 0, sortino: 0 },
              confidence: 0,
            }
          : null;
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Failed to fetch betting analytics';
        if (errorService)
          errorService.handleError(new Error(errorMessage), {
            code: 'BETTING_ANALYTICS_ERROR',
            source: 'useUnifiedAnalytics',
            details: { context: 'bettingAnalytics' },
          });
        setState(prev => ({
          ...prev,
          betting: { data: null, loading: false, error: errorMessage },
        }));
        throw {
          message: errorMessage,
          code: 'BETTING_ANALYTICS_ERROR',
          context: 'bettingAnalytics',
        } as AnalyticsError;
      }
    },
    enabled: !!config.betting,
  });

  // --- Realtime Metrics (not implemented in service, placeholder) ---
  const realtimeQuery = useQuery<RealtimeMetrics | null, AnalyticsError>({
    queryKey: ['realtimeMetrics'],
    queryFn: async () => {
      setState(prev => ({
        ...prev,
        realtime: { data: null, loading: false, error: null },
      }));
      return null;
    },
    enabled: !!config.realtime,
  });

  // --- WebSocket Updates ---
  /**
   * Subscribes to analytics WebSocket events via the unified webSocketManager.
   * Updates state in response to real-time analytics events.
   */
  useEffect(() => {
    function handleAnalyticsEvent(data: any) {
      switch (data.type) {
        case 'ml':
          setState(prev => ({
            ...prev,
            ml: { data: data.payload, loading: false, error: null },
          }));
          break;
        case 'performance':
          setState(prev => ({
            ...prev,
            performance: { data: data.payload, loading: false, error: null },
          }));
          break;
        case 'drift':
          setState(prev => ({
            ...prev,
            drift: { data: data.payload, loading: false, error: null },
          }));
          break;
        case 'betting':
          setState(prev => ({
            ...prev,
            betting: { data: data.payload, loading: false, error: null },
          }));
          break;
        case 'realtime':
          setState(prev => ({
            ...prev,
            realtime: { data: data.payload, loading: false, error: null },
          }));
          break;
        default:
          console.warn?.('Unknown analytics WebSocket type', data.type);
      }
    }
    webSocketManager.on('analytics', handleAnalyticsEvent);
    return () => {
      webSocketManager.off('analytics', handleAnalyticsEvent);
    };
  }, []);

  // --- Memoized return values ---
  const ml = useMemo(
    () => ({
      data: state.ml.data,
      loading: state.ml.loading,
      error: state.ml.error,
      refetch: mlQuery.refetch,
    }),
    [state.ml, mlQuery.refetch]
  );

  const performance = useMemo(
    () => ({
      data: state.performance.data,
      loading: state.performance.loading,
      error: state.performance.error,
      refetch: performanceQuery.refetch,
    }),
    [state.performance, performanceQuery.refetch]
  );

  const drift = useMemo(
    () => ({
      data: state.drift.data,
      loading: state.drift.loading,
      error: state.drift.error,
      refetch: driftQuery.refetch,
    }),
    [state.drift, driftQuery.refetch]
  );

  const betting = useMemo(
    () => ({
      data: state.betting.data,
      loading: state.betting.loading,
      error: state.betting.error,
      refetch: bettingQuery.refetch,
    }),
    [state.betting, bettingQuery.refetch]
  );

  const realtime = useMemo(
    () => ({
      data: state.realtime.data,
      loading: state.realtime.loading,
      error: state.realtime.error,
      refetch: realtimeQuery.refetch,
    }),
    [state.realtime, realtimeQuery.refetch]
  );

  // TODO: Add more granular loading/error states if needed
  // TODO: Add ARIA live region support for analytics-driven UI updates
  // TODO: Add more comprehensive test coverage for analytics hook

  return {
    ml,
    performance,
    drift,
    betting,
    realtime,
    isLoading:
      state.ml.loading ||
      state.performance.loading ||
      state.drift.loading ||
      state.betting.loading ||
      state.realtime.loading,
    error:
      state.ml.error ||
      state.performance.error ||
      state.drift.error ||
      state.betting.error ||
      state.realtime.error,
  };
};
// END useUnifiedAnalytics

import useStore from '../store/useStore';
import { WSMessage } from '../types';
import { useEffect, useCallback, useRef } from 'react';



interface UseWebSocketOptions {
  url: string;
  onMessage?: (message: WSMessage) => void;
  reconnectAttempts?: number;
  reconnectDelay?: number;
  autoReconnect?: boolean;
}

export const useWebSocket = ({
  url,
  onMessage,
  reconnectAttempts = 5,
  reconnectDelay = 1000,
  autoReconnect = true
}: UseWebSocketOptions) => {
  const ws = useRef<WebSocket | null>(null);
  const reconnectCount = useRef(0);
  const { addToast } = useStore();

  const connect = useCallback(() => {
    try {
      ws.current = new WebSocket(url);

      ws.current.onopen = () => {
        
        reconnectCount.current = 0;
      };

      ws.current.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data) as WSMessage;
          onMessage?.(message);
        } catch (error) {
          console.error('Failed to parse WebSocket message:', error);
        }
      };

      ws.current.onclose = () => {
        
        if (autoReconnect && reconnectCount.current < reconnectAttempts) {
          const delay = reconnectDelay * Math.pow(2, reconnectCount.current);
          
          setTimeout(() => {
            reconnectCount.current++;
            connect();
          }, delay);
        } else if (reconnectCount.current >= reconnectAttempts) {
          addToast({
            id: 'ws-error',
            type: 'error',
            title: 'Connection Error',
            message: 'Failed to establish WebSocket connection. Please try again later.'
          });
        }
      };

      ws.current.onerror = (error) => {
        console.error('WebSocket error:', error);
      };
    } catch (error) {
      console.error('Failed to create WebSocket connection:', error);
    }
  }, [url, onMessage, reconnectAttempts, reconnectDelay, autoReconnect, addToast]);

  const disconnect = useCallback(() => {
    if (ws.current) {
      ws.current.close();
      ws.current = null;
    }
  }, []);

  const send = useCallback((data: any) => {
    if (ws.current?.readyState === WebSocket.OPEN) {
      ws.current.send(JSON.stringify(data));
    } else {
      console.error('WebSocket is not connected');
    }
  }, []);

  useEffect(() => {
    connect();
    return () => {
      disconnect();
    };
  }, [connect, disconnect]);

  return {
    send,
    disconnect,
    reconnect: connect,
    isConnected: ws.current?.readyState === WebSocket.OPEN
  };
};

import { useState, useEffect, useCallback } from 'react';



interface WindowSize {
  width: number;
  height: number;
  isMobile: boolean;
  isTablet: boolean;
  isDesktop: boolean;
}

interface UseWindowSizeOptions {
  debounceMs?: number;
  mobileBreakpoint?: number;
  tabletBreakpoint?: number;
}

function debounce<T extends (...args: any[]) => void>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: number;

  return (...args: Parameters<T>) => {
    window.clearTimeout(timeout);
    timeout = window.setTimeout(() => func(...args), wait);
  };
}

export function useWindowSize({
  debounceMs = 250,
  mobileBreakpoint = 640,
  tabletBreakpoint = 1024
}: UseWindowSizeOptions = {}): WindowSize {
  const [windowSize, setWindowSize] = useState<WindowSize>({
    width: typeof window !== 'undefined' ? window.innerWidth : 0,
    height: typeof window !== 'undefined' ? window.innerHeight : 0,
    isMobile: false,
    isTablet: false,
    isDesktop: false
  });

  const handleResize = useCallback(() => {
    const width = window.innerWidth;
    const height = window.innerHeight;

    setWindowSize({
      width,
      height,
      isMobile: width < mobileBreakpoint,
      isTablet: width >= mobileBreakpoint && width < tabletBreakpoint,
      isDesktop: width >= tabletBreakpoint
    });
  }, [mobileBreakpoint, tabletBreakpoint]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    // Initial call
    handleResize();

    // Set up debounced event listener
    const debouncedHandleResize = debounce(handleResize, debounceMs);
    window.addEventListener('resize', debouncedHandleResize);

    // Cleanup
    return () => {
      window.removeEventListener('resize', debouncedHandleResize);
    };
  }, [debounceMs, handleResize]);

  return windowSize;
}

// Breakpoint constants
export const BREAKPOINTS = {
  MOBILE: 640,
  TABLET: 1024,
  DESKTOP: 1280,
  WIDE: 1536
} as const;

// Media query hooks
export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const mediaQuery = window.matchMedia(query);
    setMatches(mediaQuery.matches);

    const handler = (event: MediaQueryListEvent) => {
      setMatches(event.matches);
    };

    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, [query]);

  return matches;
}

// Predefined media query hooks
export function useIsMobile() {
  return useMediaQuery(`(max-width: ${BREAKPOINTS.MOBILE - 1}px)`);
}

export function useIsTablet() {
  return useMediaQuery(
    `(min-width: ${BREAKPOINTS.MOBILE}px) and (max-width: ${BREAKPOINTS.TABLET - 1}px)`
  );
}

export function useIsDesktop() {
  return useMediaQuery(`(min-width: ${BREAKPOINTS.TABLET}px)`);
}

