          {/* DEV BYPASS BUTTON: Only show in development */}
          {process.env.NODE_ENV === 'development' && (
            <Button
              variant="outlined"
              color="secondary"
              fullWidth
              sx={{ mt: 2, border: '2px dashed #1976d2', color: '#1976d2' }}
