    return this.get(`/games/${gameId}`);
  }
}

import { EventEmitter } from 'events';
import BackendIntegrationService from './BackendIntegrationService';
import { UnifiedWebSocketService } from './unified/UnifiedWebSocketService';
import { UnifiedLogger } from './unified/UnifiedLogger';
import { ArbitrageService } from './ArbitrageService';
import { PrizePicksAPI } from './PrizePicksAPI';

export interface MoneyMakingOpportunity {
  id: string;
  type: 'prizepicks' | 'arbitrage' | 'value_bet' | 'kelly_optimal';
  source: string;
  playerName: string;
  statType: string;
  line: number;
  odds: number;
  confidence: number;
  expectedValue: number;
  kellyFraction: number;
  projectedReturn: number;
  riskLevel: 'low' | 'medium' | 'high';
  timeRemaining: number; // minutes
  analysis: {
    historicalTrends: string[];
    marketSignals: string[];
    riskFactors: string[];
    modelBreakdown: Record<string, number>;
    shapValues?: Array<{ feature: string; value: number; impact: number }>;
  };
  metadata: {
    createdAt: number;
    expiresAt: number;
    modelVersion: string;
    predictionId: string;
  };
}

export interface PortfolioOptimization {
  opportunities: MoneyMakingOpportunity[];
  totalExpectedValue: number;
  totalKellyFraction: number;
  riskScore: number;
  diversificationScore: number;
  allocation: Record<string, number>; // opportunity_id -> amount
  constraints: {
    maxSingleBet: number;
    maxTotalExposure: number;
    minConfidence: number;
  };
}

class RealTimeMoneyMakingService extends EventEmitter {
  private static instance: RealTimeMoneyMakingService;
  private logger: UnifiedLogger;
  private backendService: BackendIntegrationService;
  private wsService: UnifiedWebSocketService;
  private arbitrageService: ArbitrageService;
  private prizePicksService: PrizePicksAPI;
  
  private opportunities: Map<string, MoneyMakingOpportunity> = new Map();
  private isActive: boolean = false;
  private scanInterval: NodeJS.Timeout | null = null;
  private performanceMetrics = {
    totalOpportunitiesFound: 0,
    totalBetsPlaced: 0,
    totalProfit: 0,
    winRate: 0,
    avgKellyFraction: 0,
    lastScanTime: 0,
  };

  private constructor() {
    super();
    this.logger = UnifiedLogger.getInstance();
    this.backendService = BackendIntegrationService.getInstance();
    this.wsService = UnifiedWebSocketService.getInstance();
    this.arbitrageService = ArbitrageService.getInstance();
    this.prizePicksService = PrizePicksAPI.getInstance();
    
    this.setupEventListeners();
  }

  static getInstance(): RealTimeMoneyMakingService {
    if (!RealTimeMoneyMakingService.instance) {
      RealTimeMoneyMakingService.instance = new RealTimeMoneyMakingService();
    }
    return RealTimeMoneyMakingService.instance;
  }

  private setupEventListeners(): void {
    // Real-time opportunity detection
    this.wsService.subscribe('market:odds_change', this.handleOddsChange.bind(this));
    this.wsService.subscribe('arbitrage:opportunity', this.handleArbitrageOpportunity.bind(this));
    this.wsService.subscribe('prediction:update', this.handlePredictionUpdate.bind(this));
    this.wsService.subscribe('prizepicks:new_prop', this.handleNewProp.bind(this));
  }

  async startRealTimeScanning(config: {
    sports: string[];
    minConfidence: number;
    maxExposure: number;
    scanIntervalMs: number;
    strategies: string[];
  }): Promise<void> {
    if (this.isActive) {
      this.logger.warn('Real-time scanning already active');
      return;
    }

    this.isActive = true;
    this.logger.info('Starting real-time money-making scanner', config);

    // Initial scan
    await this.performFullScan(config);

    // Set up periodic scanning
    this.scanInterval = setInterval(async () => {
      await this.performFullScan(config);
    }, config.scanIntervalMs);

    this.emit('scanning:started', config);
  }

  async stopRealTimeScanning(): Promise<void> {
    if (!this.isActive) return;

    this.isActive = false;
    
    if (this.scanInterval) {
      clearInterval(this.scanInterval);
      this.scanInterval = null;
    }

    this.logger.info('Stopped real-time money-making scanner');
    this.emit('scanning:stopped');
  }

  private async performFullScan(config: any): Promise<void> {
    const startTime = Date.now();
    
    try {
      // Parallel scanning across different opportunity types
      const scanPromises = [
        this.scanPrizePicksOpportunities(config),
        this.scanArbitrageOpportunities(config),
        this.scanValueBetOpportunities(config),
      ];

      const results = await Promise.allSettled(scanPromises);
      
      // Process successful scans
      const allOpportunities: MoneyMakingOpportunity[] = [];
      results.forEach((result, index) => {
        if (result.status === 'fulfilled') {
          allOpportunities.push(...result.value);
        } else {
          this.logger.error(`Scan ${index} failed`, { error: result.reason });
        }
      });

      // Update opportunities cache
      this.updateOpportunities(allOpportunities);

      // Optimize portfolio
      const portfolio = await this.optimizePortfolio(allOpportunities, config);
      
      this.performanceMetrics.lastScanTime = Date.now();
      this.performanceMetrics.totalOpportunitiesFound += allOpportunities.length;

      this.emit('scan:completed', {
        opportunities: allOpportunities,
        portfolio,
        scanTime: Date.now() - startTime,
        metrics: this.performanceMetrics,
      });

    } catch (error) {
      this.logger.error('Full scan failed', { error: error.message });
      this.emit('scan:error', error);
    }
  }

  private async scanPrizePicksOpportunities(config: any): Promise<MoneyMakingOpportunity[]> {
    try {
      const props = await this.prizePicksService.getAvailableProps({
        sports: config.sports,
        timeWindow: 'today',
      });

      const opportunities: MoneyMakingOpportunity[] = [];

      for (const prop of props.slice(0, 50)) { // Limit for performance
        const prediction = await this.backendService.getPrediction({
          player_id: prop.playerId,
          metric: prop.statType,
          timeframe: 'today',
          include_shap: true,
        });

        if (prediction.prediction.confidence >= config.minConfidence) {
          const kellyFraction = this.calculateKellyFraction(
            prediction.prediction.confidence,
            prop.overOdds
          );

          opportunities.push({
            id: `prizepicks-${prop.playerId}-${prop.statType}`,
            type: 'prizepicks',
            source: 'PrizePicks',
            playerName: prop.playerName,
            statType: prop.statType,
            line: prop.line,
            odds: prop.overOdds,
            confidence: prediction.prediction.confidence,
            expectedValue: this.calculateExpectedValue(prediction.prediction.confidence, prop.overOdds),
            kellyFraction,
            projectedReturn: prediction.prediction.value,
            riskLevel: this.calculateRiskLevel(prediction.prediction.confidence, kellyFraction),
            timeRemaining: this.calculateTimeRemaining(prop.gameTime),
            analysis: {
              historicalTrends: prediction.analysis.historical_trends,
              marketSignals: prediction.analysis.market_signals,
              riskFactors: prediction.analysis.risk_factors,
              modelBreakdown: prediction.analysis.model_breakdown,
              shapValues: prediction.shap_values,
            },
            metadata: {
              createdAt: Date.now(),
              expiresAt: Date.now() + (4 * 60 * 60 * 1000), // 4 hours
              modelVersion: prediction.meta.model_version,
              predictionId: prediction.meta.prediction_id,
            },
          });
        }
      }

      return opportunities;
    } catch (error) {
      this.logger.error('PrizePicks scan failed', { error: error.message });
      return [];
    }
  }

  private async scanArbitrageOpportunities(config: any): Promise<MoneyMakingOpportunity[]> {
    try {
      const arbOpportunities = await this.backendService.getArbitrageOpportunities({
        sports: config.sports,
        min_profit: 0.02, // 2% minimum profit
        time_window: 'today',
      });

      return arbOpportunities.map(arb => ({
        id: `arbitrage-${arb.id}`,
        type: 'arbitrage',
        source: `${arb.bookmaker1.name} vs ${arb.bookmaker2.name}`,
        playerName: arb.event,
        statType: arb.market,
        line: 0, // Arbitrage doesn't have a line
        odds: arb.bookmaker1.odds,
        confidence: 0.99, // Arbitrage is near-certain profit
        expectedValue: arb.profit_percentage,
        kellyFraction: 0.05, // Conservative for arbitrage
        projectedReturn: arb.profit,
        riskLevel: 'low',
        timeRemaining: this.calculateTimeRemainingFromString(arb.expires_at),
        analysis: {
          historicalTrends: ['Risk-free arbitrage opportunity'],
          marketSignals: ['Price discrepancy detected'],
          riskFactors: ['Timing risk', 'Liquidity risk'],
          modelBreakdown: { 'Arbitrage Scanner': 1.0 },
        },
        metadata: {
          createdAt: Date.now(),
          expiresAt: new Date(arb.expires_at).getTime(),
          modelVersion: 'arbitrage-v1.0',
          predictionId: arb.id,
        },
      }));
    } catch (error) {
      this.logger.error('Arbitrage scan failed', { error: error.message });
      return [];
    }
  }

  private async scanValueBetOpportunities(config: any): Promise<MoneyMakingOpportunity[]> {
    try {
      const valueBets = await this.backendService.getBettingOpportunities({
        sports: config.sports,
        confidence_threshold: config.minConfidence,
        time_window: 'today',
        strategy_mode: 'value_maximizer',
      });

      return valueBets.map(bet => ({
        id: `value-${bet.id}`,
        type: 'value_bet',
        source: 'ML Value Scanner',
        playerName: bet.player_name,
        statType: bet.stat_type,
        line: bet.line,
        odds: bet.over_odds,
        confidence: bet.confidence,
        expectedValue: bet.expected_value,
        kellyFraction: bet.kelly_fraction,
        projectedReturn: bet.line + (bet.expected_value / 100),
        riskLevel: bet.risk_level,
        timeRemaining: this.calculateTimeRemainingFromString(bet.time_remaining),
        analysis: {
          historicalTrends: bet.analysis.historical_trends,
          marketSignals: bet.analysis.market_signals,
          riskFactors: bet.analysis.risk_factors,
          modelBreakdown: { 'Value Scanner': 1.0 },
        },
        metadata: {
          createdAt: Date.now(),
          expiresAt: Date.now() + (6 * 60 * 60 * 1000), // 6 hours
          modelVersion: 'value-v1.0',
          predictionId: bet.id,
        },
      }));
    } catch (error) {
      this.logger.error('Value bet scan failed', { error: error.message });
      return [];
    }
  }

  private async optimizePortfolio(
    opportunities: MoneyMakingOpportunity[],
    config: any
  ): Promise<PortfolioOptimization> {
    // Sort by Kelly-adjusted expected value
    const sorted = opportunities.sort((a, b) => {
      const aScore = a.expectedValue * a.kellyFraction * a.confidence;
      const bScore = b.expectedValue * b.kellyFraction * b.confidence;
      return bScore - aScore;
    });

    // Apply portfolio constraints
    const selected: MoneyMakingOpportunity[] = [];
    let totalKellyFraction = 0;
    const allocation: Record<string, number> = {};

    for (const opp of sorted) {
      if (selected.length >= 10) break; // Max 10 positions
      if (totalKellyFraction + opp.kellyFraction > config.maxExposure) break;
      if (opp.confidence < config.minConfidence) continue;

      selected.push(opp);
      totalKellyFraction += opp.kellyFraction;
      allocation[opp.id] = Math.round(1000 * opp.kellyFraction); // $1000 base bankroll
    }

    const totalExpectedValue = selected.reduce((sum, opp) => sum + opp.expectedValue, 0);
    const riskScore = this.calculatePortfolioRisk(selected);
    const diversificationScore = this.calculateDiversification(selected);

    return {
      opportunities: selected,
      totalExpectedValue,
      totalKellyFraction,
      riskScore,
      diversificationScore,
      allocation,
      constraints: {
        maxSingleBet: Math.max(...Object.values(allocation)),
        maxTotalExposure: config.maxExposure,
        minConfidence: config.minConfidence,
      },
    };
  }

  private calculateKellyFraction(confidence: number, odds: number): number {
    const b = odds - 1; // net odds
    const p = confidence; // probability of winning
    const q = 1 - p; // probability of losing
    
    const kelly = (b * p - q) / b;
    return Math.max(0, Math.min(kelly * 0.25, 0.1)); // Conservative Kelly with 25% multiplier, max 10%
  }

  private calculateExpectedValue(confidence: number, odds: number): number {
    const impliedProbability = 1 / odds;
    return (confidence * odds - 1) * 100; // Return as percentage
  }

  private calculateRiskLevel(confidence: number, kellyFraction: number): 'low' | 'medium' | 'high' {
    if (confidence > 0.8 && kellyFraction < 0.03) return 'low';
    if (confidence > 0.7 && kellyFraction < 0.06) return 'medium';
    return 'high';
  }

  private calculateTimeRemaining(gameTime: string): number {
    const gameDate = new Date(gameTime);
    const now = new Date();
    return Math.max(0, Math.floor((gameDate.getTime() - now.getTime()) / (1000 * 60))); // minutes
  }

  private calculateTimeRemainingFromString(timeStr: string): number {
    if (timeStr.includes('hour')) {
      const hours = parseInt(timeStr.match(/\d+/)?.[0] || '0');
      return hours * 60;
    }
    if (timeStr.includes('minute')) {
      return parseInt(timeStr.match(/\d+/)?.[0] || '0');
    }
    return 60; // Default 1 hour
  }

  private calculatePortfolioRisk(opportunities: MoneyMakingOpportunity[]): number {
    const avgConfidence = opportunities.reduce((sum, opp) => sum + opp.confidence, 0) / opportunities.length;
    const avgKelly = opportunities.reduce((sum, opp) => sum + opp.kellyFraction, 0) / opportunities.length;
    
    // Risk score: lower is better (0-100)
    return Math.max(0, 100 - (avgConfidence * 50 + (1 - avgKelly * 10) * 50));
  }

  private calculateDiversification(opportunities: MoneyMakingOpportunity[]): number {
    const sports = new Set(opportunities.map(opp => opp.statType));
    const types = new Set(opportunities.map(opp => opp.type));
    const sources = new Set(opportunities.map(opp => opp.source));
    
    // Diversification score: higher is better (0-100)
    const sportDiv = Math.min(sports.size / 4, 1) * 40; // Max 40 points for sports diversity
    const typeDiv = Math.min(types.size / 3, 1) * 30; // Max 30 points for type diversity
    const sourceDiv = Math.min(sources.size / 3, 1) * 30; // Max 30 points for source diversity
    
    return sportDiv + typeDiv + sourceDiv;
  }

  private updateOpportunities(newOpportunities: MoneyMakingOpportunity[]): void {
    // Remove expired opportunities
    const now = Date.now();
    for (const [id, opp] of this.opportunities) {
      if (opp.metadata.expiresAt < now) {
        this.opportunities.delete(id);
      }
    }

    // Add new opportunities
    newOpportunities.forEach(opp => {
      this.opportunities.set(opp.id, opp);
    });

    this.emit('opportunities:updated', Array.from(this.opportunities.values()));
  }

  // Event handlers for real-time updates
  private async handleOddsChange(data: any): Promise<void> {
    // Handle real-time odds changes
    this.logger.info('Odds change detected', data);
    this.emit('odds:changed', data);
  }

  private async handleArbitrageOpportunity(data: any): Promise<void> {
    // Handle new arbitrage opportunities
    this.logger.info('Arbitrage opportunity detected', data);
    this.emit('arbitrage:found', data);
  }

  private async handlePredictionUpdate(data: any): Promise<void> {
    // Handle prediction updates
    this.logger.info('Prediction update received', data);
    this.emit('prediction:updated', data);
  }

  private async handleNewProp(data: any): Promise<void> {
    // Handle new PrizePicks props
    this.logger.info('New prop detected', data);
    this.emit('prop:new', data);
  }

  // Public interface methods
  getActiveOpportunities(): MoneyMakingOpportunity[] {
    return Array.from(this.opportunities.values());
  }

  getPerformanceMetrics() {
    return { ...this.performanceMetrics };
  }

  async placeBet(opportunityId: string, amount: number): Promise<{ success: boolean; betId?: string; error?: string }> {
    const opportunity = this.opportunities.get(opportunityId);
    if (!opportunity) {
      return { success: false, error: 'Opportunity not found' };
    }

    try {
      const result = await this.backendService.placeBet({
        opportunity_id: opportunityId,
        amount,
        bet_type: opportunity.type,
        selection: opportunity.projectedReturn > opportunity.line ? 'over' : 'under',
      });

      if (result.success) {
        this.performanceMetrics.totalBetsPlaced++;
        this.opportunities.delete(opportunityId); // Remove placed opportunity
        this.emit('bet:placed', { opportunityId, amount, betId: result.bet_id });
      }

      return result;
    } catch (error) {
      this.logger.error('Failed to place bet', { error: error.message, opportunityId });
      return { success: false, error: error.message };
    }
  }
}

export default RealTimeMoneyMakingService;

import { BettingOpportunity, BetRecord } from '../types/core';
import { EventBus } from '../core/EventBus';
import { UnifiedConfigManager } from '../core/UnifiedConfigManager.ts';



export interface RiskConfig {
  maxExposure: number;
  maxExposurePerBet: number;
  maxExposurePerPlayer: number;
  maxExposurePerMetric: number;
  maxActiveBets: number;
  minBankroll: number;
  maxBankrollPercentage: number;
  stopLossPercentage: number;
  takeProfitPercentage: number;
  confidenceThresholds: {
    low: number;
    medium: number;
    high: number;
  };
  volatilityThresholds: {
    low: number;
    medium: number;
    high: number;
  };
}

export interface RiskAssessment {
  id: string;
  timestamp: number;
  opportunity: BettingOpportunity;
  riskLevel: 'low' | 'medium' | 'high';
  maxStake: number;
  factors: {
    exposure: number;
    confidence: number;
    volatility: number;
    correlation: number;
    timeToEvent: number;
  };
  limits: {
    maxExposure: number;
    maxStake: number;
    minOdds: number;
    maxOdds: number;
  };
  warnings: string[];
  recommendations: string[];
}

export interface RiskMetrics {
  totalExposure: number;
  exposureByPlayer: Record<string, number>;
  exposureByMetric: Record<string, number>;
  activeBets: number;
  bankroll: number;
  profitLoss: number;
  roi: number;
  winRate: number;
  averageStake: number;
  maxDrawdown: number;
  sharpeRatio: number;
  kellyMultiplier: number;
}

export class RiskManagerService {
  private static instance: RiskManagerService;
  private readonly eventBus: EventBus;
  private readonly configManager: UnifiedConfigManager;
  private readonly config: RiskConfig;
  private readonly activeBets: Map<string, BetRecord>;
  private readonly riskAssessments: Map<string, RiskAssessment>;
  private metrics: RiskMetrics;

  private constructor() {
    this.eventBus = EventBus.getInstance();
    this.configManager = UnifiedConfigManager.getInstance();
    this.config = this.initializeConfig();
    this.activeBets = new Map();
    this.riskAssessments = new Map();
    this.metrics = this.initializeMetrics();
    this.setupEventListeners();
  }

  public static getInstance(): RiskManagerService {
    if (!RiskManagerService.instance) {
      RiskManagerService.instance = new RiskManagerService();
    }
    return RiskManagerService.instance;
  }

  private initializeConfig(): RiskConfig {
    const config = this.configManager.getConfig();
    return {
      maxExposure: 10000,
      maxExposurePerBet: 1000,
      maxExposurePerPlayer: 2000,
      maxExposurePerMetric: 5000,
      maxActiveBets: 50,
      minBankroll: 1000,
      maxBankrollPercentage: 0.1,
      stopLossPercentage: 0.2,
      takeProfitPercentage: 0.5,
      confidenceThresholds: {
        low: 0.3,
        medium: 0.6,
        high: 0.8
      },
      volatilityThresholds: {
        low: 0.1,
        medium: 0.3,
        high: 0.5
      }
    };
  }

  private initializeMetrics(): RiskMetrics {
    return {
      totalExposure: 0,
      exposureByPlayer: {},
      exposureByMetric: {},
      activeBets: 0,
      bankroll: 0,
      profitLoss: 0,
      roi: 0,
      winRate: 0,
      averageStake: 0,
      maxDrawdown: 0,
      sharpeRatio: 0,
      kellyMultiplier: 1
    };
  }

  private setupEventListeners(): void {
    // Listen for new betting opportunities
    this.eventBus.on('prediction:update', async (event) => {
      try {
        const assessment = await this.assessRisk(event.data);
        this.riskAssessments.set(assessment.id, assessment);
        
        this.eventBus.emit('data:updated', {
          sourceId: 'risk-manager',
          data: [assessment]
        });
      } catch (error) {
        console.error('Error assessing risk:', error);
      }
    });

    // Listen for placed bets
    this.eventBus.on('bet:placed', (event) => {
      const { bet } = event.data;
      this.updateExposure(bet);
      this.updateMetrics();
    });

    // Listen for settled bets
    this.eventBus.on('bet:settled', (event) => {
      const { bet, result } = event.data;
      this.handleBetSettlement(bet.id, result);
      this.updateMetrics();
    });

    // Listen for bankroll updates
    this.eventBus.on('bankroll:update', (event) => {
      const { state } = event.data;
      this.metrics.bankroll = state.balance;
      this.updateMetrics();
    });
  }

  private async assessRisk(opportunity: BettingOpportunity): Promise<RiskAssessment> {
    const assessment: RiskAssessment = {
      id: `risk_${opportunity.id}_${Date.now()}`,
      timestamp: Date.now(),
      opportunity,
      riskLevel: 'medium',
      maxStake: 0,
      factors: {
        exposure: 0,
        confidence: 0,
        volatility: 0,
        correlation: 0,
        timeToEvent: 0
      },
      limits: {
        maxExposure: this.config.maxExposure,
        maxStake: this.config.maxExposurePerBet,
        minOdds: 1.1,
        maxOdds: 10
      },
      warnings: [],
      recommendations: []
    };

    // Calculate risk factors
    assessment.factors.exposure = this.calculateExposureFactor(opportunity);
    assessment.factors.confidence = this.calculateConfidenceFactor(opportunity);
    assessment.factors.volatility = this.calculateVolatilityFactor(opportunity);
    assessment.factors.correlation = this.calculateCorrelationFactor(opportunity);
    assessment.factors.timeToEvent = this.calculateTimeToEventFactor(opportunity);

    // Calculate overall risk level
    assessment.riskLevel = this.calculateOverallRisk(assessment.factors);

    // Calculate max stake
    assessment.maxStake = this.calculateMaxStake(assessment);

    // Generate warnings and recommendations
    this.generateWarnings(assessment);
    this.generateRecommendations(assessment);

    return assessment;
  }

  private calculateExposureFactor(opportunity: BettingOpportunity): number {
    const playerExposure = this.metrics.exposureByPlayer[opportunity.playerId] || 0;
    const metricExposure = this.metrics.exposureByMetric[opportunity.metric] || 0;
    
    const playerFactor = playerExposure / this.config.maxExposurePerPlayer;
    const metricFactor = metricExposure / this.config.maxExposurePerMetric;
    const totalFactor = this.metrics.totalExposure / this.config.maxExposure;

    return Math.max(playerFactor, metricFactor, totalFactor);
  }

  private calculateConfidenceFactor(opportunity: BettingOpportunity): number {
    const { confidence } = opportunity;
    if (confidence >= this.config.confidenceThresholds.high) return 0.2;
    if (confidence >= this.config.confidenceThresholds.medium) return 0.5;
    return 0.8;
  }

  private calculateVolatilityFactor(opportunity: BettingOpportunity): number {
    const volatility = opportunity.metadata?.volatility || 0;
    if (volatility <= this.config.volatilityThresholds.low) return 0.2;
    if (volatility <= this.config.volatilityThresholds.medium) return 0.5;
    return 0.8;
  }

  private calculateCorrelationFactor(opportunity: BettingOpportunity): number {
    // Calculate correlation with existing bets
    let maxCorrelation = 0;
    for (const bet of this.activeBets.values()) {
      const correlation = this.calculateBetCorrelation(bet, opportunity);
      maxCorrelation = Math.max(maxCorrelation, correlation);
    }
    return maxCorrelation;
  }

  private calculateTimeToEventFactor(opportunity: BettingOpportunity): number {
    const timeToEvent = opportunity.metadata?.timeToEvent || 0;
    if (timeToEvent > 86400) return 0.2; // More than 24 hours
    if (timeToEvent > 3600) return 0.5; // More than 1 hour
    return 0.8; // Less than 1 hour
  }

  private calculateBetCorrelation(bet: BetRecord, opportunity: BettingOpportunity): number {
    // Simple correlation based on shared factors
    let correlation = 0;
    
    // Same player
    if (bet.playerId === opportunity.playerId) {
      correlation += 0.3;
    }
    
    // Same metric
    if (bet.metric === opportunity.metric) {
      correlation += 0.3;
    }
    
    // Same time period
    const timeDiff = Math.abs(
      (opportunity.metadata?.eventTime || 0) - 
      (bet.metadata?.eventTime || 0)
    );
    if (timeDiff < 3600) correlation += 0.4;
    else if (timeDiff < 86400) correlation += 0.2;

    return correlation;
  }

  private calculateOverallRisk(factors: RiskAssessment['factors']): 'low' | 'medium' | 'high' {
    const riskScore = 
      factors.exposure * 0.3 +
      factors.confidence * 0.2 +
      factors.volatility * 0.2 +
      factors.correlation * 0.2 +
      factors.timeToEvent * 0.1;

    if (riskScore <= 0.3) return 'low';
    if (riskScore <= 0.6) return 'medium';
    return 'high';
  }

  private calculateMaxStake(assessment: RiskAssessment): number {
    const { riskLevel, factors, opportunity } = assessment;
    let maxStake = this.config.maxExposurePerBet;

    // Adjust based on risk level
    if (riskLevel === 'high') maxStake *= 0.5;
    else if (riskLevel === 'medium') maxStake *= 0.75;

    // Adjust based on bankroll
    maxStake = Math.min(maxStake, this.metrics.bankroll * this.config.maxBankrollPercentage);

    // Adjust based on exposure
    const remainingExposure = this.config.maxExposure - this.metrics.totalExposure;
    maxStake = Math.min(maxStake, remainingExposure);

    // Adjust based on player exposure
    const playerExposure = this.metrics.exposureByPlayer[opportunity.playerId] || 0;
    const remainingPlayerExposure = this.config.maxExposurePerPlayer - playerExposure;
    maxStake = Math.min(maxStake, remainingPlayerExposure);

    // Adjust based on metric exposure
    const metricExposure = this.metrics.exposureByMetric[opportunity.metric] || 0;
    const remainingMetricExposure = this.config.maxExposurePerMetric - metricExposure;
    maxStake = Math.min(maxStake, remainingMetricExposure);

    // Apply Kelly criterion
    maxStake *= this.metrics.kellyMultiplier;

    return Math.max(0, Math.floor(maxStake));
  }

  private generateWarnings(assessment: RiskAssessment): void {
    const { factors, opportunity } = assessment;

    if (factors.exposure > 0.8) {
      assessment.warnings.push('High exposure level');
    }

    if (factors.confidence < this.config.confidenceThresholds.medium) {
      assessment.warnings.push('Low confidence prediction');
    }

    if (factors.volatility > this.config.volatilityThresholds.high) {
      assessment.warnings.push('High market volatility');
    }

    if (factors.correlation > 0.7) {
      assessment.warnings.push('High correlation with existing bets');
    }

    if (factors.timeToEvent > 0.7) {
      assessment.warnings.push('Close to event start time');
    }

    if (this.metrics.activeBets >= this.config.maxActiveBets) {
      assessment.warnings.push('Maximum active bets reached');
    }

    if (this.metrics.bankroll < this.config.minBankroll) {
      assessment.warnings.push('Bankroll below minimum threshold');
    }
  }

  private generateRecommendations(assessment: RiskAssessment): void {
    const { riskLevel, maxStake, opportunity } = assessment;

    if (maxStake > 0) {
      assessment.recommendations.push(`Recommended maximum stake: $${maxStake}`);
    } else {
      assessment.recommendations.push('Do not place this bet');
    }

    if (riskLevel === 'high') {
      assessment.recommendations.push('Consider reducing position size');
      assessment.recommendations.push('Set tight stop loss');
    }

    if (assessment.factors.correlation > 0.5) {
      assessment.recommendations.push('Consider hedging existing positions');
    }

    if (assessment.factors.volatility > this.config.volatilityThresholds.medium) {
      assessment.recommendations.push('Monitor market conditions closely');
    }
  }

  private updateExposure(bet: BetRecord): void {
    this.activeBets.set(bet.id, bet);
    
    // Update exposure metrics
    this.metrics.totalExposure += bet.stake;
    this.metrics.exposureByPlayer[bet.playerId] = 
      (this.metrics.exposureByPlayer[bet.playerId] || 0) + bet.stake;
    this.metrics.exposureByMetric[bet.metric] = 
      (this.metrics.exposureByMetric[bet.metric] || 0) + bet.stake;
    this.metrics.activeBets = this.activeBets.size;
  }

  private handleBetSettlement(betId: string, result: { won: boolean; profitLoss: number }): void {
    const bet = this.activeBets.get(betId);
    if (!bet) return;

    // Update exposure
    this.metrics.totalExposure -= bet.stake;
    this.metrics.exposureByPlayer[bet.playerId] -= bet.stake;
    this.metrics.exposureByMetric[bet.metric] -= bet.stake;
    
    // Update P&L
    this.metrics.profitLoss += result.profitLoss;
    
    // Remove from active bets
    this.activeBets.delete(betId);
    this.metrics.activeBets = this.activeBets.size;
  }

  private updateMetrics(): void {
    // Calculate ROI
    this.metrics.roi = this.metrics.bankroll > 0 
      ? this.metrics.profitLoss / this.metrics.bankroll 
      : 0;

    // Calculate win rate
    const settledBets = Array.from(this.activeBets.values())
      .filter(bet => bet.result && bet.result !== 'pending');
    const winningBets = settledBets.filter(bet => bet.result === 'win');
    this.metrics.winRate = settledBets.length > 0 
      ? winningBets.length / settledBets.length 
      : 0;

    // Calculate average stake
    const totalStake = Array.from(this.activeBets.values())
      .reduce((sum, bet) => sum + bet.stake, 0);
    this.metrics.averageStake = this.activeBets.size > 0 
      ? totalStake / this.activeBets.size 
      : 0;

    // Emit metrics update
    this.eventBus.emit('metric:recorded', {
      name: 'risk_metrics',
      value: this.metrics.totalExposure,
      timestamp: Date.now(),
      labels: {
        active_bets: String(this.metrics.activeBets),
        win_rate: this.metrics.winRate.toFixed(2),
        roi: this.metrics.roi.toFixed(2)
      }
    });
  }

  public getRiskAssessment(id: string): RiskAssessment | undefined {
    return this.riskAssessments.get(id);
  }

  public getMetrics(): RiskMetrics {
    return { ...this.metrics };
  }

  public getActiveBets(): BetRecord[] {
    return Array.from(this.activeBets.values());
  }

  public getConfig(): RiskConfig {
    return { ...this.config };
  }
}

import { EventEmitter } from 'events';

interface SentimentAnalysis {
  text: string;
  sentiment: 'positive' | 'negative' | 'neutral';
  confidence: number;
  platform: string;
  timestamp: number;
  topics: string[];
  entities: {
    name: string;
    type: string;
    sentiment: number;
  }[];
}

interface SentimentTrend {
  entityId: string;
  entityType: string;
  timeframe: string;
  platform?: string;
  sentiment: {
    positive: number;
    negative: number;
    neutral: number;
  };
  volume: number;
  trends: {
    timestamp: number;
    sentiment: number;
    volume: number;
  }[];
}

interface EntityMention {
  entityId: string;
  entityType: string;
  mentions: {
    text: string;
    platform: string;
    sentiment: number;
    timestamp: number;
    engagement: number;
  }[];
  summary: {
    totalMentions: number;
    avgSentiment: number;
    platforms: string[];
  };
}

interface SentimentConfig {
  apiUrl: string;
  apiKey: string;
  batchSize: number;
  refreshInterval: number;
  enableRealTime: boolean;
}

/**
 * Modern SocialSentimentService with proper async/await and error handling
 */
export class SocialSentimentService extends EventEmitter {
  private config: SentimentConfig;
  private cache = new Map<string, { data: any; timestamp: number }>();
  private analysisQueue: Array<{
    text: string;
    platform: string;
    timestamp: number;
  }> = [];
  private readonly CACHE_TTL = 300000; // 5 minutes

  constructor() {
    super();
    this.config = {
      apiUrl: import.meta.env.VITE_SENTIMENT_API_URL || 'https://api.sentiment.com',
      apiKey: import.meta.env.VITE_SENTIMENT_API_KEY || '',
      batchSize: 50,
      refreshInterval: 30000,
      enableRealTime: import.meta.env.VITE_ENABLE_SENTIMENT === 'true',
    };

    if (this.config.enableRealTime) {
      this.startProcessingQueue();
    }
  }

  /**
   * Queue text for sentiment analysis
   */
  queueAnalysis(text: string, platform: string): void {
    if (import.meta.env.VITE_DISABLE_SOCIAL_SENTIMENT === 'true') {
      return;
    }

    this.queueForAnalysis(text, platform, Date.now());
  }

  /**
   * Analyze sentiment for a single text
   */
  async analyzeSentiment(text: string, platform: string): Promise<SentimentAnalysis | null> {
    if (import.meta.env.VITE_DISABLE_SOCIAL_SENTIMENT === 'true') {
      return this.simulateSentiment(text, platform);
    }

    try {
      const response = await fetch(`${this.config.apiUrl}/analyze`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.config.apiKey}`,
        },
        body: JSON.stringify({
          text,
          platform,
          options: {
            includeEntities: true,
            includeTopics: true,
          },
        }),
      });

      if (!response.ok) {
        throw new Error(`Sentiment API error: ${response.status}`);
      }

      const result = await response.json();
      this.reportStatus('sentiment-api', true, 0.9);
      return result;
    } catch (error) {
      console.error('Error analyzing sentiment:', error);
      this.reportStatus('sentiment-api', false, 0.1);
      return this.simulateSentiment(text, platform);
    }
  }

  /**
   * Get sentiment trend for an entity
   */
  async getSentimentTrend(params: {
    entityId: string;
    entityType: string;
    timeframe: string;
    platform?: string;
  }): Promise<SentimentTrend | null> {
    const cacheKey = this.getCacheKey('trend', params);
    const cached = this.getCachedData<SentimentTrend>(cacheKey);
    if (cached) return cached;

    try {
      const response = await fetch(`${this.config.apiUrl}/trends`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${this.config.apiKey}`,
        },
      });

      if (!response.ok) {
        throw new Error(`Trends API error: ${response.status}`);
      }

      const trend = await response.json() as SentimentTrend;
      this.setCachedData(cacheKey, trend);
      return trend;
    } catch (error) {
      console.error('Error fetching sentiment trend:', error);
      return null;
    }
  }

  /**
   * Get entity mentions
   */
  async getEntityMentions(entityId: string, entityType: string): Promise<EntityMention | null> {
    const cacheKey = this.getCacheKey(`entity:${entityId}`);
    const cached = this.getCachedData<EntityMention>(cacheKey);
    if (cached) return cached;

    try {
      const response = await fetch(`${this.config.apiUrl}/entities/${entityId}`, {
        headers: {
          'Authorization': `Bearer ${this.config.apiKey}`,
        },
      });

      if (!response.ok) {
        throw new Error(`Entity mentions API error: ${response.status}`);
      }

      const mentions = await response.json() as EntityMention;
      this.setCachedData(cacheKey, mentions);
      return mentions;
    } catch (error) {
      console.error('Error fetching entity mentions:', error);
      return null;
    }
  }

  /**
   * Start processing the analysis queue
   */
  private async startProcessingQueue(): Promise<void> {
    setInterval(async () => {
      if (this.analysisQueue.length === 0) return;

      const batch = this.analysisQueue.splice(0, this.config.batchSize);
      try {
        await this.analyzeBatch(batch);
      } catch (error) {
        console.error('Error processing sentiment batch:', error);
      }
    }, this.config.refreshInterval);
  }

  /**
   * Process a batch of sentiment analysis requests
   */
  private async analyzeBatch(batch: Array<{
    text: string;
    platform: string;
    timestamp: number;
  }>): Promise<SentimentAnalysis[]> {
    const startTime = Date.now();
    try {
      const response = await fetch(`${this.config.apiUrl}/analyze/batch`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.config.apiKey}`,
        },
        body: JSON.stringify({ batch }),
      });

      if (!response.ok) {
        throw new Error(`Batch sentiment API error: ${response.status}`);
      }

      const result = await response.json();
      const analyses = result.analyses as SentimentAnalysis[];

      // Emit metrics
      this.emit('metric:recorded', {
        type: 'sentiment_batch_processed',
        value: analyses.length,
        duration: Date.now() - startTime,
        timestamp: Date.now(),
      });

      return analyses;
    } catch (error) {
      console.error('Error in batch sentiment analysis:', error);
      
      // Return simulated results for fallback
      return batch.map(item => this.simulateSentiment(item.text, item.platform));
    }
  }

  /**
   * Add text to analysis queue
   */
  private queueForAnalysis(text: string, platform: string, timestamp: number): void {
    this.analysisQueue.push({ text, platform, timestamp });

    // Emit queue metrics
    this.emit('metric:recorded', {
      type: 'sentiment_queue_size',
      value: this.analysisQueue.length,
      timestamp: Date.now(),
    });
  }

  /**
   * Simulate sentiment analysis for fallback
   */
  private simulateSentiment(text: string, platform: string): SentimentAnalysis {
    const words = text.toLowerCase().split(' ');
    const positiveWords = ['good', 'great', 'excellent', 'amazing', 'win', 'victory'];
    const negativeWords = ['bad', 'terrible', 'awful', 'loss', 'fail', 'injury'];
    
    let sentiment: 'positive' | 'negative' | 'neutral' = 'neutral';
    let confidence = 0.5;

    if (words.some(word => positiveWords.includes(word))) {
      sentiment = 'positive';
      confidence = 0.7;
    } else if (words.some(word => negativeWords.includes(word))) {
      sentiment = 'negative';
      confidence = 0.7;
    }

    return {
      text,
      sentiment,
      confidence,
      platform,
      timestamp: Date.now(),
      topics: ['sports', 'betting'],
      entities: [],
    };
  }

  /**
   * Report service status
   */
  private reportStatus(source: string, connected: boolean, quality: number): void {
    if (typeof window !== 'undefined') {
      (window as any).appStatus = (window as any).appStatus || {};
      (window as any).appStatus[source] = { connected, quality, timestamp: Date.now() };
    }
    console.info(`[SocialSentimentService] ${source} status:`, { connected, quality });
  }

  /**
   * Generate cache key
   */
  private getCacheKey(endpoint: string, params?: Record<string, any>): string {
    const paramStr = params ? JSON.stringify(params) : '';
    return `${endpoint}:${paramStr}`;
  }

  /**
   * Get cached data if still valid
   */
  private getCachedData<T>(key: string): T | null {
    const cached = this.cache.get(key);
    if (cached && Date.now() - cached.timestamp < this.CACHE_TTL) {
      return cached.data as T;
    }
    return null;
  }

  /**
   * Set data in cache
   */
  private setCachedData<T>(key: string, data: T): void {
    this.cache.set(key, { data, timestamp: Date.now() });
  }

  /**
   * Clear all cached data
   */
  clearCache(): void {
    this.cache.clear();
  }

  /**
   * Clear specific cache item
   */
  clearCacheItem(key: string): void {
    this.cache.delete(key);
  }

  /**
   * Get current queue size
   */
  getQueueSize(): number {
    return this.analysisQueue.length;
  }

  /**
   * Check if queue is processing
   */
  isQueueProcessing(): boolean {
    return this.config.enableRealTime;
  }
}

