import { FeatureConfig, FeatureLoggerConfig } from './types';

export class FeatureLogger {
  private readonly config: FeatureLoggerConfig;

  constructor(config?: Partial<FeatureLoggerConfig>) {
    this.config = {
      logLevel: config?.logLevel || 'info',
      logFormat: config?.logFormat || 'json',
      logOutput: config?.logOutput || 'console',
      logFile: config?.logFile || 'feature-engineering.log',
      maxLogSize: config?.maxLogSize || 10 * 1024 * 1024, // 10MB
      maxLogFiles: config?.maxLogFiles || 5,
    };
  }

  public info(message: string, data?: any): void {
    this.log('info', message, data);
  }

  public warn(message: string, data?: any): void {
    this.log('warn', message, data);
  }

  public error(message: string, error?: any): void {
    this.log('error', message, error);
  }

  public debug(message: string, data?: any): void {
    this.log('debug', message, data);
  }

  private log(level: string, message: string, data?: any): void {
    if (!this.shouldLog(level)) {
      return;
    }

    const logEntry = this.createLogEntry(level, message, data);
    const formattedLog = this.formatLog(logEntry);

    this.writeLog(formattedLog);
  }

  private shouldLog(level: string): boolean {
    const levels = ['error', 'warn', 'info', 'debug'];
    const currentLevelIndex = levels.indexOf(this.config.logLevel);
    const targetLevelIndex = levels.indexOf(level);

    return targetLevelIndex <= currentLevelIndex;
  }

  private createLogEntry(level: string, message: string, data?: any): any {
    const timestamp = new Date().toISOString();
    const entry: any = {
      timestamp,
      level,
      message,
    };

    if (data) {
      if (data instanceof Error) {
        entry.error = {
          name: data.name,
          message: data.message,
          stack: data.stack,
        };
      } else {
        entry.data = data;
      }
    }

    return entry;
  }

  private formatLog(entry: any): string {
    if (this.config.logFormat === 'json') {
      return JSON.stringify(entry);
    }

    // Simple text format
    const timestamp = entry.timestamp;
    const level = entry.level.toUpperCase();
    const message = entry.message;
    let formatted = `[${timestamp}] ${level}: ${message}`;

    if (entry.error) {
      formatted += `\nError: ${entry.error.name}: ${entry.error.message}`;
      if (entry.error.stack) {
        formatted += `\nStack: ${entry.error.stack}`;
      }
    } else if (entry.data) {
      formatted += `\nData: ${JSON.stringify(entry.data, null, 2)}`;
    }

    return formatted;
  }

  private writeLog(formattedLog: string): void {
    if (this.config.logOutput === 'console') {
      this.writeToConsole(formattedLog);
    } else if (this.config.logOutput === 'file') {
      this.writeToFile(formattedLog);
    }
  }

  private writeToConsole(formattedLog: string): void {
    const level = formattedLog.includes('ERROR')
      ? 'error'
      : formattedLog.includes('WARN')
        ? 'warn'
        : formattedLog.includes('DEBUG')
          ? 'debug'
          : 'info';

    switch (level) {
      case 'error':
        console.error(formattedLog);
        break;
      case 'warn':
        console.warn(formattedLog);
        break;
      case 'debug':
        console.debug(formattedLog);
        break;
      default:
        console.log(formattedLog);
    }
  }

  private writeToFile(formattedLog: string): void {
    // This is a placeholder implementation
    // In a real application, implement file writing with rotation
    console.log(`[FILE] ${formattedLog}`);
  }

  public getLogLevel(): string {
    return this.config.logLevel;
  }

  public setLogLevel(level: FeatureLoggerConfig['logLevel']): void {
    this.config.logLevel = level;
  }

  public getLogFormat(): string {
    return this.config.logFormat;
  }

  public setLogFormat(format: FeatureLoggerConfig['logFormat']): void {
    this.config.logFormat = format;
  }

  public getLogOutput(): string {
    return this.config.logOutput;
  }

  public setLogOutput(output: FeatureLoggerConfig['logOutput']): void {
    this.config.logOutput = output;
  }
}

import { FeatureConfig, EngineeredFeatures, FeatureMonitoringConfig } from './types';
import { FeatureLogger } from './featureLogging';

interface MonitoringMetrics {
  timestamp: string;
  featureCounts: {
    numerical: number;
    categorical: number;
    temporal: number;
    derived: number;
  };
  qualityMetrics: {
    completeness: number;
    consistency: number;
    relevance: number;
    stability: number;
  };
  performanceMetrics: {
    processingTime: number;
    memoryUsage: number;
    errorRate: number;
  };
}

export class FeatureMonitor {
  private readonly config: FeatureMonitoringConfig;
  private readonly logger: FeatureLogger;
  private readonly metrics: MonitoringMetrics[];
  private monitoringInterval: NodeJS.Timeout | null;

  constructor(config: FeatureMonitoringConfig) {
    this.config = config;
    this.logger = new FeatureLogger();
    this.metrics = [];
    this.monitoringInterval = null;
    this.initializeMonitoring();
  }

  private initializeMonitoring(): void {
    if (this.config.enabled) {
      this.startMonitoring();
      this.logger.info('Initialized feature monitoring');
    }
  }

  private startMonitoring(): void {
    if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
    }

    this.monitoringInterval = setInterval(() => {
      this.collectMetrics();
    }, this.config.metricsInterval);
  }

  private async collectMetrics(): Promise<void> {
    try {
      const latestMetrics = this.getLatestMetrics();
      if (latestMetrics) {
        // Recalculate metrics based on the latest data
        await this.monitorFeatures(
          {
            numerical: {},
            categorical: {},
            temporal: {},
            derived: {},
            metadata: {
              featureNames: [],
              featureTypes: {},
              scalingParams: {},
              encodingMaps: {},
              lastUpdated: new Date().toISOString(),
            },
          },
          0
        );
      }
    } catch (error) {
      this.logger.error('Failed to collect metrics', error);
    }
  }

  public async monitorFeatures(
    features: EngineeredFeatures,
    processingTime: number
  ): Promise<void> {
    try {
      if (!this.config.enabled) {
        return;
      }

      const metrics = await this.calculateMetrics(features, processingTime);
      this.metrics.push(metrics);

      // Check for alerts
      this.checkAlerts(metrics);

      // Trim metrics history if needed
      if (this.metrics.length > this.config.maxMetricsHistory) {
        this.metrics.splice(0, this.metrics.length - this.config.maxMetricsHistory);
      }

      this.logger.debug('Collected feature monitoring metrics', metrics);
    } catch (error) {
      this.logger.error('Failed to monitor features', error);
    }
  }

  private async calculateMetrics(
    features: EngineeredFeatures,
    processingTime: number
  ): Promise<MonitoringMetrics> {
    const timestamp = new Date().toISOString();
    const featureCounts = {
      numerical: Object.keys(features.numerical).length,
      categorical: Object.keys(features.categorical).length,
      temporal: Object.keys(features.temporal).length,
      derived: Object.keys(features.derived).length,
    };

    const qualityMetrics = await this.calculateQualityMetrics(features);
    const performanceMetrics = this.calculatePerformanceMetrics(processingTime);

    return {
      timestamp,
      featureCounts,
      qualityMetrics,
      performanceMetrics,
    };
  }

  private async calculateQualityMetrics(
    features: EngineeredFeatures
  ): Promise<MonitoringMetrics['qualityMetrics']> {
    const completeness = this.calculateCompleteness(features);
    const consistency = this.calculateConsistency(features);
    const relevance = this.calculateRelevance(features);
    const stability = this.calculateStability(features);

    return {
      completeness,
      consistency,
      relevance,
      stability,
    };
  }

  private calculateCompleteness(features: EngineeredFeatures): number {
    let totalValues = 0;
    let missingValues = 0;

    // Check numerical features
    for (const values of Object.values(features.numerical)) {
      totalValues += values.length;
      missingValues += values.filter(v => v === null || v === undefined || isNaN(v)).length;
    }

    // Check categorical features
    for (const values of Object.values(features.categorical)) {
      totalValues += values.length;
      missingValues += values.filter(v => v === null || v === undefined || v === '').length;
    }

    // Check temporal features
    for (const values of Object.values(features.temporal)) {
      totalValues += values.length;
      missingValues += values.filter(v => v === null || v === undefined || isNaN(v)).length;
    }

    // Check derived features
    for (const values of Object.values(features.derived)) {
      totalValues += values.length;
      missingValues += values.filter(v => v === null || v === undefined || isNaN(v)).length;
    }

    return totalValues > 0 ? 1 - missingValues / totalValues : 0;
  }

  private calculateConsistency(features: EngineeredFeatures): number {
    let consistencyScore = 0;
    let totalChecks = 0;

    // Check numerical features
    for (const [feature, values] of Object.entries(features.numerical)) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);

      // Check for outliers
      const outliers = values.filter(v => Math.abs(v - mean) > 3 * std).length;
      consistencyScore += 1 - outliers / values.length;
      totalChecks++;
    }

    // Check categorical features
    for (const [feature, values] of Object.entries(features.categorical)) {
      const uniqueValues = new Set(values).size;
      const expectedUnique = Math.min(values.length, 10); // Assuming max 10 categories
      consistencyScore += 1 - Math.abs(uniqueValues - expectedUnique) / expectedUnique;
      totalChecks++;
    }

    return totalChecks > 0 ? consistencyScore / totalChecks : 0;
  }

  private calculateRelevance(features: EngineeredFeatures): number {
    let relevanceScore = 0;
    let totalFeatures = 0;

    // Check numerical features
    for (const [feature, values] of Object.entries(features.numerical)) {
      const variance = this.calculateVariance(values);
      relevanceScore += variance > 0 ? 1 : 0;
      totalFeatures++;
    }

    // Check categorical features
    for (const [feature, values] of Object.entries(features.categorical)) {
      const uniqueValues = new Set(values).size;
      relevanceScore += uniqueValues > 1 ? 1 : 0;
      totalFeatures++;
    }

    // Check temporal features
    for (const [feature, values] of Object.entries(features.temporal)) {
      const trend = this.calculateTrend(values);
      relevanceScore += Math.abs(trend) > 0.01 ? 1 : 0;
      totalFeatures++;
    }

    // Check derived features
    for (const [feature, values] of Object.entries(features.derived)) {
      const variance = this.calculateVariance(values);
      relevanceScore += variance > 0 ? 1 : 0;
      totalFeatures++;
    }

    return totalFeatures > 0 ? relevanceScore / totalFeatures : 0;
  }

  private calculateStability(features: EngineeredFeatures): number {
    let stabilityScore = 0;
    let totalFeatures = 0;

    // Check numerical features
    for (const [feature, values] of Object.entries(features.numerical)) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);
      stabilityScore += std / (Math.abs(mean) + 1e-10);
      totalFeatures++;
    }

    // Check categorical features
    for (const [feature, values] of Object.entries(features.categorical)) {
      const valueCounts = values.reduce(
        (acc, val) => {
          acc[val] = (acc[val] || 0) + 1;
          return acc;
        },
        {} as Record<string, number>
      );

      const maxCount = Math.max(...Object.values(valueCounts));
      const minCount = Math.min(...Object.values(valueCounts));
      stabilityScore += 1 - (maxCount - minCount) / (maxCount + 1e-10);
      totalFeatures++;
    }

    // Check temporal features
    for (const [feature, values] of Object.entries(features.temporal)) {
      const seasonality = this.calculateSeasonality(values);
      stabilityScore += seasonality.strength;
      totalFeatures++;
    }

    // Check derived features
    for (const [feature, values] of Object.entries(features.derived)) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);
      stabilityScore += std / (Math.abs(mean) + 1e-10);
      totalFeatures++;
    }

    return totalFeatures > 0 ? stabilityScore / totalFeatures : 0;
  }

  private calculatePerformanceMetrics(
    processingTime: number
  ): MonitoringMetrics['performanceMetrics'] {
    const memoryUsage = process.memoryUsage().heapUsed / 1024 / 1024; // MB
    const errorRate = this.calculateErrorRate();

    return {
      processingTime,
      memoryUsage,
      errorRate,
    };
  }

  private calculateErrorRate(): number {
    const recentMetrics = this.metrics.slice(-10);
    if (recentMetrics.length === 0) {
      return 0;
    }

    const errorCount = recentMetrics.filter(m => m.performanceMetrics.errorRate > 0).length;
    return errorCount / recentMetrics.length;
  }

  private calculateVariance(values: number[]): number {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    return values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
  }

  private calculateTrend(values: number[]): number {
    const x = Array.from({ length: values.length }, (_, i) => i);
    return this.calculateLinearRegressionSlope(x, values);
  }

  private calculateLinearRegressionSlope(x: number[], y: number[]): number {
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);
    const sumXY = x.reduce((sum, xi, i) => sum + xi * y[i], 0);
    const sumXX = x.reduce((sum, xi) => sum + xi * xi, 0);

    return (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
  }

  private calculateSeasonality(values: number[]): {
    hasSeasonality: boolean;
    period: number;
    strength: number;
  } {
    const maxLag = Math.min(50, Math.floor(values.length / 2));
    let bestPeriod = 1;
    let maxAutocorr = -1;

    for (let lag = 1; lag <= maxLag; lag++) {
      const autocorr = this.calculateAutocorrelation(values, lag);
      if (autocorr > maxAutocorr) {
        maxAutocorr = autocorr;
        bestPeriod = lag;
      }
    }

    return {
      hasSeasonality: maxAutocorr > 0.5,
      period: bestPeriod,
      strength: maxAutocorr,
    };
  }

  private calculateAutocorrelation(values: number[], lag: number): number {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    let numerator = 0;
    let denominator = 0;

    for (let i = 0; i < values.length - lag; i++) {
      numerator += (values[i] - mean) * (values[i + lag] - mean);
      denominator += Math.pow(values[i] - mean, 2);
    }

    return numerator / denominator;
  }

  private checkAlerts(metrics: MonitoringMetrics): void {
    // Check quality metrics
    if (metrics.qualityMetrics.completeness < this.config.alertThresholds.completeness) {
      this.logger.warn(
        `Low feature completeness: ${metrics.qualityMetrics.completeness.toFixed(2)}`
      );
    }

    if (metrics.qualityMetrics.consistency < this.config.alertThresholds.consistency) {
      this.logger.warn(`Low feature consistency: ${metrics.qualityMetrics.consistency.toFixed(2)}`);
    }

    if (metrics.qualityMetrics.relevance < this.config.alertThresholds.relevance) {
      this.logger.warn(`Low feature relevance: ${metrics.qualityMetrics.relevance.toFixed(2)}`);
    }

    if (metrics.qualityMetrics.stability < this.config.alertThresholds.stability) {
      this.logger.warn(`Low feature stability: ${metrics.qualityMetrics.stability.toFixed(2)}`);
    }

    // Check performance metrics
    if (metrics.performanceMetrics.processingTime > this.config.alertThresholds.processingTime) {
      this.logger.warn(
        `High processing time: ${metrics.performanceMetrics.processingTime.toFixed(2)}ms`
      );
    }

    if (metrics.performanceMetrics.memoryUsage > this.config.alertThresholds.memoryUsage) {
      this.logger.warn(`High memory usage: ${metrics.performanceMetrics.memoryUsage.toFixed(2)}MB`);
    }

    if (metrics.performanceMetrics.errorRate > this.config.alertThresholds.errorRate) {
      this.logger.warn(`High error rate: ${metrics.performanceMetrics.errorRate.toFixed(2)}`);
    }
  }

  public getMetrics(): MonitoringMetrics[] {
    return [...this.metrics];
  }

  public getLatestMetrics(): MonitoringMetrics | null {
    return this.metrics.length > 0 ? this.metrics[this.metrics.length - 1] : null;
  }

  public isEnabled(): boolean {
    return this.config.enabled;
  }

  public setEnabled(enabled: boolean): void {
    this.config.enabled = enabled;
    if (enabled) {
      this.startMonitoring();
    } else if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
      this.monitoringInterval = null;
    }
  }

  public getMetricsInterval(): number {
    return this.config.metricsInterval;
  }

  public setMetricsInterval(interval: number): void {
    this.config.metricsInterval = interval;
    if (this.config.enabled) {
      this.startMonitoring();
    }
  }
}

import { FeatureConfig, EngineeredFeatures, FeatureRegistryConfig } from './types';
import { FeatureLogger } from './featureLogging';
import { FeatureStore } from './featureStore';

export class FeatureRegistry {
  private readonly config: FeatureRegistryConfig;
  private readonly logger: FeatureLogger;
  private readonly store: FeatureStore;
  private readonly registry: Map<string, EngineeredFeatures>;

  constructor(config: FeatureRegistryConfig) {
    this.config = config;
    this.logger = new FeatureLogger();
    this.store = new FeatureStore({
      path: this.config.path,
      type: 'local',
      backupEnabled: this.config.backupEnabled,
      backupInterval: this.config.backupInterval,
    });
    this.registry = new Map();
    this.initializeRegistry();
  }

  private async initializeRegistry(): Promise<void> {
    try {
      const versions = await this.store.listVersions();
      for (const version of versions) {
        const features = await this.store.loadFeatures(version);
        this.registry.set(version, features);
      }
      this.logger.info(`Initialized feature registry with ${versions.length} versions`);
    } catch (error) {
      this.logger.error('Failed to initialize feature registry', error);
      throw error;
    }
  }

  public async registerFeatures(features: EngineeredFeatures, version: string): Promise<void> {
    try {
      // Validate features
      if (!this.validateFeatures(features)) {
        throw new Error('Invalid features');
      }

      // Save features to store
      await this.store.saveFeatures(features, version);

      // Update registry
      this.registry.set(version, features);

      // Update metadata
      features.metadata.lastUpdated = new Date().toISOString();

      this.logger.info(`Registered features version ${version}`);
    } catch (error) {
      this.logger.error('Failed to register features', error);
      throw error;
    }
  }

  public async getFeatures(version: string): Promise<EngineeredFeatures> {
    try {
      // Check registry first
      const features = this.registry.get(version);
      if (features) {
        return features;
      }

      // Load from store if not in registry
      const loadedFeatures = await this.store.loadFeatures(version);
      this.registry.set(version, loadedFeatures);
      return loadedFeatures;
    } catch (error) {
      this.logger.error('Failed to get features', error);
      throw error;
    }
  }

  public async listVersions(): Promise<string[]> {
    try {
      return Array.from(this.registry.keys());
    } catch (error) {
      this.logger.error('Failed to list versions', error);
      throw error;
    }
  }

  public async getVersionInfo(version: string): Promise<any> {
    try {
      return await this.store.getVersionInfo(version);
    } catch (error) {
      this.logger.error('Failed to get version info', error);
      throw error;
    }
  }

  public async deleteVersion(version: string): Promise<void> {
    try {
      // Delete from store
      await this.store.deleteVersion(version);

      // Remove from registry
      this.registry.delete(version);

      this.logger.info(`Deleted features version ${version}`);
    } catch (error) {
      this.logger.error('Failed to delete version', error);
      throw error;
    }
  }

  public async cleanupOldVersions(maxVersions: number): Promise<void> {
    try {
      await this.store.cleanupOldVersions(maxVersions);
      await this.initializeRegistry(); // Reload registry after cleanup
    } catch (error) {
      this.logger.error('Failed to cleanup old versions', error);
      throw error;
    }
  }

  private validateFeatures(features: EngineeredFeatures): boolean {
    try {
      // Check required fields
      if (
        !features.numerical ||
        !features.categorical ||
        !features.temporal ||
        !features.derived ||
        !features.metadata
      ) {
        return false;
      }

      // Check metadata
      const metadata = features.metadata;
      if (
        !metadata.featureNames ||
        !metadata.featureTypes ||
        !metadata.scalingParams ||
        !metadata.encodingMaps
      ) {
        return false;
      }

      // Check feature types
      for (const [feature, type] of Object.entries(metadata.featureTypes)) {
        if (!['numerical', 'categorical', 'temporal', 'derived'].includes(type)) {
          return false;
        }
      }

      // Check scaling parameters
      for (const [feature, params] of Object.entries(metadata.scalingParams)) {
        if (typeof params.mean !== 'number' || typeof params.std !== 'number' || params.std <= 0) {
          return false;
        }
      }

      return true;
    } catch (error) {
      this.logger.error('Failed to validate features', error);
      return false;
    }
  }

  public async getFeatureStats(version: string): Promise<any> {
    try {
      const features = await this.getFeatures(version);
      const stats = {
        numerical: this.calculateNumericalStats(features.numerical),
        categorical: this.calculateCategoricalStats(features.categorical),
        temporal: this.calculateTemporalStats(features.temporal),
        derived: this.calculateDerivedStats(features.derived),
      };

      return stats;
    } catch (error) {
      this.logger.error('Failed to get feature stats', error);
      throw error;
    }
  }

  private calculateNumericalStats(features: Record<string, number[]>): Record<string, any> {
    const stats: Record<string, any> = {};
    for (const [feature, values] of Object.entries(features)) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);
      const min = Math.min(...values);
      const max = Math.max(...values);

      stats[feature] = {
        mean,
        std,
        min,
        max,
        count: values.length,
        missing: values.filter(v => v === null || v === undefined || isNaN(v)).length,
      };
    }
    return stats;
  }

  private calculateCategoricalStats(features: Record<string, string[]>): Record<string, any> {
    const stats: Record<string, any> = {};
    for (const [feature, values] of Object.entries(features)) {
      const uniqueValues = new Set(values);
      const valueCounts = values.reduce(
        (acc, val) => {
          acc[val] = (acc[val] || 0) + 1;
          return acc;
        },
        {} as Record<string, number>
      );

      stats[feature] = {
        uniqueCount: uniqueValues.size,
        valueCounts,
        count: values.length,
        missing: values.filter(v => v === null || v === undefined || v === '').length,
      };
    }
    return stats;
  }

  private calculateTemporalStats(features: Record<string, number[]>): Record<string, any> {
    const stats: Record<string, any> = {};
    for (const [feature, values] of Object.entries(features)) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);

      // Calculate trend
      const x = Array.from({ length: values.length }, (_, i) => i);
      const slope = this.calculateLinearRegressionSlope(x, values);

      // Calculate seasonality
      const seasonality = this.calculateSeasonality(values);

      stats[feature] = {
        mean,
        std,
        trend: {
          slope,
          direction: slope > 0 ? 'increasing' : slope < 0 ? 'decreasing' : 'stable',
        },
        seasonality,
        count: values.length,
        missing: values.filter(v => v === null || v === undefined || isNaN(v)).length,
      };
    }
    return stats;
  }

  private calculateDerivedStats(features: Record<string, number[]>): Record<string, any> {
    const stats: Record<string, any> = {};
    for (const [feature, values] of Object.entries(features)) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);

      stats[feature] = {
        mean,
        std,
        count: values.length,
        missing: values.filter(v => v === null || v === undefined || isNaN(v)).length,
      };
    }
    return stats;
  }

  private calculateLinearRegressionSlope(x: number[], y: number[]): number {
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);
    const sumXY = x.reduce((sum, xi, i) => sum + xi * y[i], 0);
    const sumXX = x.reduce((sum, xi) => sum + xi * xi, 0);

    return (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
  }

  private calculateSeasonality(values: number[]): {
    hasSeasonality: boolean;
    period: number;
    strength: number;
  } {
    const maxLag = Math.min(50, Math.floor(values.length / 2));
    let bestPeriod = 1;
    let maxAutocorr = -1;

    for (let lag = 1; lag <= maxLag; lag++) {
      const autocorr = this.calculateAutocorrelation(values, lag);
      if (autocorr > maxAutocorr) {
        maxAutocorr = autocorr;
        bestPeriod = lag;
      }
    }

    return {
      hasSeasonality: maxAutocorr > 0.5,
      period: bestPeriod,
      strength: maxAutocorr,
    };
  }

  private calculateAutocorrelation(values: number[], lag: number): number {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    let numerator = 0;
    let denominator = 0;

    for (let i = 0; i < values.length - lag; i++) {
      numerator += (values[i] - mean) * (values[i + lag] - mean);
      denominator += Math.pow(values[i] - mean, 2);
    }

    return numerator / denominator;
  }
}

import { FeatureConfig, EngineeredFeatures, FeatureSelectionResult } from './types';
import { Matrix } from 'ml-matrix';
import { FeatureLogger } from './featureLogging';

export class FeatureSelector {
  private readonly config: FeatureConfig;
  private readonly logger: FeatureLogger;

  constructor(config: FeatureConfig) {
    this.config = config;
    this.logger = new FeatureLogger();
  }

  public async selectFeatures(features: EngineeredFeatures): Promise<FeatureSelectionResult> {
    try {
      const result: FeatureSelectionResult = {
        numerical: [],
        categorical: [],
        temporal: [],
        derived: [],
        importance: {},
      };

      // Select numerical features
      result.numerical = await this.selectNumericalFeatures(features.numerical);

      // Select categorical features
      result.categorical = await this.selectCategoricalFeatures(features.categorical);

      // Select temporal features
      result.temporal = await this.selectTemporalFeatures(features.temporal);

      // Select derived features
      result.derived = await this.selectDerivedFeatures(features.derived);

      // Calculate feature importance
      result.importance = await this.calculateFeatureImportance(features, result);

      // Filter features based on importance threshold
      this.filterFeaturesByImportance(result);

      return result;
    } catch (error) {
      this.logger.error('Error in feature selection', error);
      throw error;
    }
  }

  private async selectNumericalFeatures(features: Record<string, number[]>): Promise<string[]> {
    const selectedFeatures: string[] = [];
    const featureMatrix = this.createFeatureMatrix(features);

    // Calculate correlation matrix
    const correlationMatrix = this.calculateCorrelationMatrix(featureMatrix);

    // Remove highly correlated features
    const uncorrelatedFeatures = this.removeCorrelatedFeatures(
      Object.keys(features),
      correlationMatrix
    );

    // Calculate variance
    const varianceScores = this.calculateVarianceScores(featureMatrix);

    // Select features based on variance threshold
    for (const feature of uncorrelatedFeatures) {
      if (varianceScores[feature] > this.config.featureSelectionThreshold) {
        selectedFeatures.push(feature);
      }
    }

    return selectedFeatures;
  }

  private async selectCategoricalFeatures(features: Record<string, string[]>): Promise<string[]> {
    const selectedFeatures: string[] = [];

    for (const [feature, values] of Object.entries(features)) {
      // Calculate cardinality
      const cardinality = new Set(values).size;

      // Calculate information value
      const informationValue = this.calculateInformationValue(values);

      // Select features based on cardinality and information value
      if (
        cardinality > 1 &&
        cardinality < values.length / 2 &&
        informationValue > this.config.featureSelectionThreshold
      ) {
        selectedFeatures.push(feature);
      }
    }

    return selectedFeatures;
  }

  private async selectTemporalFeatures(features: Record<string, number[]>): Promise<string[]> {
    const selectedFeatures: string[] = [];
    const featureMatrix = this.createFeatureMatrix(features);

    // Calculate autocorrelation
    const autocorrelationScores = this.calculateAutocorrelationScores(featureMatrix);

    // Calculate trend strength
    const trendScores = this.calculateTrendScores(featureMatrix);

    // Select features based on autocorrelation and trend strength
    for (const [feature, values] of Object.entries(features)) {
      const autocorrelation = autocorrelationScores[feature];
      const trendStrength = trendScores[feature];

      if (
        autocorrelation > this.config.featureSelectionThreshold ||
        trendStrength > this.config.featureSelectionThreshold
      ) {
        selectedFeatures.push(feature);
      }
    }

    return selectedFeatures;
  }

  private async selectDerivedFeatures(features: Record<string, number[]>): Promise<string[]> {
    const selectedFeatures: string[] = [];
    const featureMatrix = this.createFeatureMatrix(features);

    // Calculate mutual information
    const mutualInfoScores = this.calculateMutualInformationScores(featureMatrix);

    // Select features based on mutual information
    for (const [feature, score] of Object.entries(mutualInfoScores)) {
      if (score > this.config.featureSelectionThreshold) {
        selectedFeatures.push(feature);
      }
    }

    return selectedFeatures;
  }

  private async calculateFeatureImportance(
    features: EngineeredFeatures,
    selectedFeatures: FeatureSelectionResult
  ): Promise<Record<string, number>> {
    const importance: Record<string, number> = {};
    const allFeatures = {
      ...features.numerical,
      ...features.temporal,
      ...features.derived,
    };

    // Calculate feature importance using multiple methods
    const varianceImportance = this.calculateVarianceImportance(allFeatures);
    const correlationImportance = this.calculateCorrelationImportance(allFeatures);
    const mutualInfoImportance = this.calculateMutualInfoImportance(allFeatures);

    // Combine importance scores
    for (const feature of selectedFeatures.numerical) {
      importance[feature] = this.combineImportanceScores(
        varianceImportance[feature],
        correlationImportance[feature],
        mutualInfoImportance[feature]
      );
    }

    return importance;
  }

  private createFeatureMatrix(features: Record<string, number[]>): Matrix {
    const featureNames = Object.keys(features);
    const numSamples = features[featureNames[0]].length;
    const matrix = new Matrix(numSamples, featureNames.length);

    for (let i = 0; i < featureNames.length; i++) {
      const feature = features[featureNames[i]];
      for (let j = 0; j < numSamples; j++) {
        matrix.set(j, i, feature[j]);
      }
    }

    return matrix;
  }

  private calculateCorrelationMatrix(matrix: Matrix): Matrix {
    const centered = matrix.sub(matrix.mean('column'));
    const covariance = centered
      .transpose()
      .mmul(centered)
      .div(matrix.rows - 1);
    const stdDevs = matrix.std('column');
    const correlation = new Matrix(matrix.columns, matrix.columns);

    for (let i = 0; i < matrix.columns; i++) {
      for (let j = 0; j < matrix.columns; j++) {
        correlation.set(i, j, covariance.get(i, j) / (stdDevs[i] * stdDevs[j]));
      }
    }

    return correlation;
  }

  private removeCorrelatedFeatures(features: string[], correlationMatrix: Matrix): string[] {
    const selectedFeatures: string[] = [];
    const correlationThreshold = 0.8;

    for (let i = 0; i < features.length; i++) {
      let isCorrelated = false;
      for (const selectedFeature of selectedFeatures) {
        const j = features.indexOf(selectedFeature);
        if (Math.abs(correlationMatrix.get(i, j)) > correlationThreshold) {
          isCorrelated = true;
          break;
        }
      }
      if (!isCorrelated) {
        selectedFeatures.push(features[i]);
      }
    }

    return selectedFeatures;
  }

  private calculateVarianceScores(matrix: Matrix): Record<string, number> {
    const varianceScores: Record<string, number> = {};
    const variances = matrix.variance('column');

    for (let i = 0; i < matrix.columns; i++) {
      varianceScores[`feature_${i}`] = variances[i];
    }

    return varianceScores;
  }

  private calculateInformationValue(values: string[]): number {
    const valueCounts = new Map<string, number>();
    for (const value of values) {
      valueCounts.set(value, (valueCounts.get(value) || 0) + 1);
    }

    let informationValue = 0;
    const totalCount = values.length;

    for (const [_, count] of valueCounts) {
      const probability = count / totalCount;
      informationValue -= probability * Math.log2(probability);
    }

    return informationValue;
  }

  private calculateAutocorrelationScores(matrix: Matrix): Record<string, number> {
    const scores: Record<string, number> = {};
    const lag = 1;

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      let numerator = 0;
      let denominator = 0;
      const mean = column.reduce((a, b) => a + b, 0) / column.length;

      for (let j = 0; j < column.length - lag; j++) {
        numerator += (column[j] - mean) * (column[j + lag] - mean);
        denominator += Math.pow(column[j] - mean, 2);
      }

      scores[`feature_${i}`] = numerator / denominator;
    }

    return scores;
  }

  private calculateTrendScores(matrix: Matrix): Record<string, number> {
    const scores: Record<string, number> = {};

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const x = Array.from({ length: column.length }, (_, i) => i);
      const slope = this.calculateLinearRegressionSlope(x, column);
      scores[`feature_${i}`] = Math.abs(slope);
    }

    return scores;
  }

  private calculateMutualInformationScores(matrix: Matrix): Record<string, number> {
    const scores: Record<string, number> = {};
    const numBins = 10;

    for (let i = 0; i < matrix.columns; i++) {
      let totalMI = 0;
      const columnI = matrix.getColumn(i);

      for (let j = 0; j < matrix.columns; j++) {
        if (i !== j) {
          const columnJ = matrix.getColumn(j);
          const mi = this.calculateMutualInformation(columnI, columnJ, numBins);
          totalMI += mi;
        }
      }

      scores[`feature_${i}`] = totalMI / (matrix.columns - 1);
    }

    return scores;
  }

  private calculateMutualInformation(x: number[], y: number[], numBins: number): number {
    const xBins = this.discretize(x, numBins);
    const yBins = this.discretize(y, numBins);
    const jointCounts = new Map<string, number>();
    const xCounts = new Map<number, number>();
    const yCounts = new Map<number, number>();
    const n = x.length;

    for (let i = 0; i < n; i++) {
      const key = `${xBins[i]},${yBins[i]}`;
      jointCounts.set(key, (jointCounts.get(key) || 0) + 1);
      xCounts.set(xBins[i], (xCounts.get(xBins[i]) || 0) + 1);
      yCounts.set(yBins[i], (yCounts.get(yBins[i]) || 0) + 1);
    }

    let mi = 0;
    for (const [key, count] of jointCounts) {
      const [xBin, yBin] = key.split(',').map(Number);
      const pxy = count / n;
      const px = xCounts.get(xBin)! / n;
      const py = yCounts.get(yBin)! / n;
      mi += pxy * Math.log2(pxy / (px * py));
    }

    return mi;
  }

  private discretize(values: number[], numBins: number): number[] {
    const min = Math.min(...values);
    const max = Math.max(...values);
    const binSize = (max - min) / numBins;

    return values.map(value => {
      const bin = Math.floor((value - min) / binSize);
      return Math.min(bin, numBins - 1);
    });
  }

  private calculateLinearRegressionSlope(x: number[], y: number[]): number {
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);
    const sumXY = x.reduce((sum, xi, i) => sum + xi * y[i], 0);
    const sumXX = x.reduce((sum, xi) => sum + xi * xi, 0);

    return (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
  }

  private calculateVarianceImportance(features: Record<string, number[]>): Record<string, number> {
    const importance: Record<string, number> = {};
    for (const [feature, values] of Object.entries(features)) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const variance = values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
      importance[feature] = variance;
    }
    return this.normalizeScores(importance);
  }

  private calculateCorrelationImportance(
    features: Record<string, number[]>
  ): Record<string, number> {
    const importance: Record<string, number> = {};
    const featureMatrix = this.createFeatureMatrix(features);
    const correlationMatrix = this.calculateCorrelationMatrix(featureMatrix);

    for (let i = 0; i < featureMatrix.columns; i++) {
      const correlations = correlationMatrix.getColumn(i);
      importance[`feature_${i}`] =
        correlations.reduce((a, b) => a + Math.abs(b), 0) / correlations.length;
    }

    return this.normalizeScores(importance);
  }

  private calculateMutualInfoImportance(
    features: Record<string, number[]>
  ): Record<string, number> {
    const importance: Record<string, number> = {};
    const featureMatrix = this.createFeatureMatrix(features);
    const mutualInfoScores = this.calculateMutualInformationScores(featureMatrix);

    for (const [feature, score] of Object.entries(mutualInfoScores)) {
      importance[feature] = score;
    }

    return this.normalizeScores(importance);
  }

  private combineImportanceScores(
    varianceScore: number,
    correlationScore: number,
    mutualInfoScore: number
  ): number {
    return (varianceScore + correlationScore + mutualInfoScore) / 3;
  }

  private normalizeScores(scores: Record<string, number>): Record<string, number> {
    const values = Object.values(scores);
    const min = Math.min(...values);
    const max = Math.max(...values);
    const range = max - min;

    return Object.fromEntries(
      Object.entries(scores).map(([key, value]) => [key, range === 0 ? 0 : (value - min) / range])
    );
  }

  private filterFeaturesByImportance(result: FeatureSelectionResult): void {
    const threshold = this.config.featureSelectionThreshold;
    const maxFeatures = this.config.maxFeatures;

    // Sort features by importance
    const sortedFeatures = Object.entries(result.importance)
      .sort(([, a], [, b]) => b - a)
      .slice(0, maxFeatures);

    // Update selected features
    result.numerical = result.numerical.filter(feature =>
      sortedFeatures.some(([f]) => f === feature)
    );
    result.categorical = result.categorical.filter(feature =>
      sortedFeatures.some(([f]) => f === feature)
    );
    result.temporal = result.temporal.filter(feature =>
      sortedFeatures.some(([f]) => f === feature)
    );
    result.derived = result.derived.filter(feature => sortedFeatures.some(([f]) => f === feature));
  }
}

import { FeatureConfig, EngineeredFeatures, FeatureStoreConfig } from './types';
import { FeatureLogger } from './featureLogging';
import * as fs from 'fs';
import * as path from 'path';

export class FeatureStore {
  private readonly config: FeatureStoreConfig;
  private readonly logger: FeatureLogger;
  private readonly storePath: string;

  constructor(config: FeatureStoreConfig) {
    this.config = config;
    this.logger = new FeatureLogger();
    this.storePath = this.config.path || path.join(process.cwd(), 'feature-store');
    this.initializeStore();
  }

  private initializeStore(): void {
    try {
      if (!fs.existsSync(this.storePath)) {
        fs.mkdirSync(this.storePath, { recursive: true });
        this.logger.info(`Created feature store directory at ${this.storePath}`);
      }

      // Create subdirectories for different feature types
      const subdirs = ['numerical', 'categorical', 'temporal', 'derived', 'metadata'];
      for (const dir of subdirs) {
        const dirPath = path.join(this.storePath, dir);
        if (!fs.existsSync(dirPath)) {
          fs.mkdirSync(dirPath);
          this.logger.info(`Created subdirectory for ${dir} features`);
        }
      }
    } catch (error) {
      this.logger.error('Failed to initialize feature store', error);
      throw error;
    }
  }

  public async saveFeatures(features: EngineeredFeatures, version: string): Promise<void> {
    try {
      const timestamp = new Date().toISOString();
      const versionDir = path.join(this.storePath, version);

      // Create version directory
      if (!fs.existsSync(versionDir)) {
        fs.mkdirSync(versionDir, { recursive: true });
      }

      // Save numerical features
      await this.saveFeatureType(
        features.numerical,
        path.join(versionDir, 'numerical'),
        'numerical'
      );

      // Save categorical features
      await this.saveFeatureType(
        features.categorical,
        path.join(versionDir, 'categorical'),
        'categorical'
      );

      // Save temporal features
      await this.saveFeatureType(features.temporal, path.join(versionDir, 'temporal'), 'temporal');

      // Save derived features
      await this.saveFeatureType(features.derived, path.join(versionDir, 'derived'), 'derived');

      // Save metadata
      await this.saveMetadata(features.metadata, versionDir);

      // Create version info file
      const versionInfo = {
        version,
        timestamp,
        featureCounts: {
          numerical: Object.keys(features.numerical).length,
          categorical: Object.keys(features.categorical).length,
          temporal: Object.keys(features.temporal).length,
          derived: Object.keys(features.derived).length,
        },
      };

      fs.writeFileSync(
        path.join(versionDir, 'version-info.json'),
        JSON.stringify(versionInfo, null, 2)
      );

      this.logger.info(`Saved features version ${version}`, versionInfo);
    } catch (error) {
      this.logger.error('Failed to save features', error);
      throw error;
    }
  }

  private async saveFeatureType(
    features: Record<string, any[]>,
    dirPath: string,
    type: string
  ): Promise<void> {
    try {
      if (!fs.existsSync(dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true });
      }

      for (const [feature, values] of Object.entries(features)) {
        const filePath = path.join(dirPath, `${feature}.json`);
        fs.writeFileSync(filePath, JSON.stringify(values, null, 2));
      }

      this.logger.debug(`Saved ${type} features to ${dirPath}`);
    } catch (error) {
      this.logger.error(`Failed to save ${type} features`, error);
      throw error;
    }
  }

  private async saveMetadata(
    metadata: EngineeredFeatures['metadata'],
    versionDir: string
  ): Promise<void> {
    try {
      const metadataPath = path.join(versionDir, 'metadata.json');
      fs.writeFileSync(metadataPath, JSON.stringify(metadata, null, 2));
      this.logger.debug('Saved feature metadata');
    } catch (error) {
      this.logger.error('Failed to save feature metadata', error);
      throw error;
    }
  }

  public async loadFeatures(version: string): Promise<EngineeredFeatures> {
    try {
      const versionDir = path.join(this.storePath, version);
      if (!fs.existsSync(versionDir)) {
        throw new Error(`Feature version ${version} not found`);
      }

      const features: EngineeredFeatures = {
        numerical: {},
        categorical: {},
        temporal: {},
        derived: {},
        metadata: {
          featureNames: [],
          featureTypes: {},
          scalingParams: {},
          encodingMaps: {},
          lastUpdated: new Date().toISOString(),
        },
      };

      // Load numerical features
      features.numerical = await this.loadFeatureType(
        path.join(versionDir, 'numerical'),
        'numerical'
      );

      // Load categorical features
      features.categorical = await this.loadFeatureType(
        path.join(versionDir, 'categorical'),
        'categorical'
      );

      // Load temporal features
      features.temporal = await this.loadFeatureType(path.join(versionDir, 'temporal'), 'temporal');

      // Load derived features
      features.derived = await this.loadFeatureType(path.join(versionDir, 'derived'), 'derived');

      // Load metadata
      features.metadata = await this.loadMetadata(versionDir);

      this.logger.info(`Loaded features version ${version}`);
      return features;
    } catch (error) {
      this.logger.error('Failed to load features', error);
      throw error;
    }
  }

  private async loadFeatureType(dirPath: string, type: string): Promise<Record<string, any[]>> {
    try {
      const features: Record<string, any[]> = {};
      const files = fs.readdirSync(dirPath);

      for (const file of files) {
        if (file.endsWith('.json')) {
          const feature = path.basename(file, '.json');
          const filePath = path.join(dirPath, file);
          const content = fs.readFileSync(filePath, 'utf-8');
          features[feature] = JSON.parse(content);
        }
      }

      this.logger.debug(`Loaded ${type} features from ${dirPath}`);
      return features;
    } catch (error) {
      this.logger.error(`Failed to load ${type} features`, error);
      throw error;
    }
  }

  private async loadMetadata(versionDir: string): Promise<EngineeredFeatures['metadata']> {
    try {
      const metadataPath = path.join(versionDir, 'metadata.json');
      const content = fs.readFileSync(metadataPath, 'utf-8');
      return JSON.parse(content);
    } catch (error) {
      this.logger.error('Failed to load feature metadata', error);
      throw error;
    }
  }

  public async listVersions(): Promise<string[]> {
    try {
      const versions = fs
        .readdirSync(this.storePath)
        .filter(dir => fs.statSync(path.join(this.storePath, dir)).isDirectory())
        .filter(dir => fs.existsSync(path.join(this.storePath, dir, 'version-info.json')));

      return versions;
    } catch (error) {
      this.logger.error('Failed to list feature versions', error);
      throw error;
    }
  }

  public async getVersionInfo(version: string): Promise<any> {
    try {
      const versionInfoPath = path.join(this.storePath, version, 'version-info.json');
      if (!fs.existsSync(versionInfoPath)) {
        throw new Error(`Version info for ${version} not found`);
      }

      const content = fs.readFileSync(versionInfoPath, 'utf-8');
      return JSON.parse(content);
    } catch (error) {
      this.logger.error('Failed to get version info', error);
      throw error;
    }
  }

  public async deleteVersion(version: string): Promise<void> {
    try {
      const versionDir = path.join(this.storePath, version);
      if (!fs.existsSync(versionDir)) {
        throw new Error(`Feature version ${version} not found`);
      }

      fs.rmSync(versionDir, { recursive: true, force: true });
      this.logger.info(`Deleted feature version ${version}`);
    } catch (error) {
      this.logger.error('Failed to delete feature version', error);
      throw error;
    }
  }

  public async cleanupOldVersions(maxVersions: number): Promise<void> {
    try {
      const versions = await this.listVersions();
      if (versions.length <= maxVersions) {
        return;
      }

      // Sort versions by timestamp
      const versionInfos = await Promise.all(
        versions.map(async version => ({
          version,
          info: await this.getVersionInfo(version),
        }))
      );

      versionInfos.sort(
        (a, b) => new Date(b.info.timestamp).getTime() - new Date(a.info.timestamp).getTime()
      );

      // Delete oldest versions
      const versionsToDelete = versionInfos.slice(maxVersions);
      for (const { version } of versionsToDelete) {
        await this.deleteVersion(version);
      }

      this.logger.info(`Cleaned up ${versionsToDelete.length} old feature versions`);
    } catch (error) {
      this.logger.error('Failed to cleanup old versions', error);
      throw error;
    }
  }
}

import { FeatureConfig, FeatureTransformationResult } from './types';
import { FeatureLogger } from './featureLogging';
import { Matrix } from 'ml-matrix';

export class FeatureTransformer {
  private readonly config: FeatureConfig;
  private readonly logger: FeatureLogger;

  constructor(config: FeatureConfig) {
    this.config = config;
    this.logger = new FeatureLogger();
  }

  public async transformNumerical(
    features: Record<string, number[]>
  ): Promise<Record<string, number[]>> {
    try {
      const transformed: Record<string, number[]> = {};
      const featureMatrix = this.createFeatureMatrix(features);

      // Apply transformations
      const normalized = this.normalizeFeatures(featureMatrix);
      const scaled = this.scaleFeatures(normalized);
      const transformedMatrix = this.applyNonlinearTransformations(scaled);

      // Convert back to record format
      for (let i = 0; i < Object.keys(features).length; i++) {
        const featureName = Object.keys(features)[i];
        transformed[featureName] = transformedMatrix.getColumn(i);
      }

      return transformed;
    } catch (error) {
      this.logger.error('Error transforming numerical features', error);
      throw error;
    }
  }

  public async transformCategorical(
    features: Record<string, string[]>
  ): Promise<Record<string, string[]>> {
    try {
      const transformed: Record<string, string[]> = {};

      for (const [feature, values] of Object.entries(features)) {
        // Apply categorical transformations
        transformed[feature] = this.applyCategoricalTransformations(values);
      }

      return transformed;
    } catch (error) {
      this.logger.error('Error transforming categorical features', error);
      throw error;
    }
  }

  public async transformTemporal(
    features: Record<string, number[]>
  ): Promise<Record<string, number[]>> {
    try {
      const transformed: Record<string, number[]> = {};
      const featureMatrix = this.createFeatureMatrix(features);

      // Apply temporal transformations
      const detrended = this.detrendFeatures(featureMatrix);
      const deseasonalized = this.deseasonalizeFeatures(detrended);
      const transformedMatrix = this.applyTemporalTransformations(deseasonalized);

      // Convert back to record format
      for (let i = 0; i < Object.keys(features).length; i++) {
        const featureName = Object.keys(features)[i];
        transformed[featureName] = transformedMatrix.getColumn(i);
      }

      return transformed;
    } catch (error) {
      this.logger.error('Error transforming temporal features', error);
      throw error;
    }
  }

  public async transformDerived(
    features: Record<string, number[]>
  ): Promise<Record<string, number[]>> {
    try {
      const transformed: Record<string, number[]> = {};
      const featureMatrix = this.createFeatureMatrix(features);

      // Apply derived feature transformations
      const normalized = this.normalizeFeatures(featureMatrix);
      const transformedMatrix = this.applyDerivedTransformations(normalized);

      // Convert back to record format
      for (let i = 0; i < Object.keys(features).length; i++) {
        const featureName = Object.keys(features)[i];
        transformed[featureName] = transformedMatrix.getColumn(i);
      }

      return transformed;
    } catch (error) {
      this.logger.error('Error transforming derived features', error);
      throw error;
    }
  }

  private createFeatureMatrix(features: Record<string, number[]>): Matrix {
    const featureNames = Object.keys(features);
    const numSamples = features[featureNames[0]].length;
    const matrix = new Matrix(numSamples, featureNames.length);

    for (let i = 0; i < featureNames.length; i++) {
      const feature = features[featureNames[i]];
      for (let j = 0; j < numSamples; j++) {
        matrix.set(j, i, feature[j]);
      }
    }

    return matrix;
  }

  private normalizeFeatures(matrix: Matrix): Matrix {
    const normalized = new Matrix(matrix.rows, matrix.columns);
    const means = matrix.mean('column');
    const stds = matrix.std('column');

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const mean = means[i];
      const std = stds[i];

      for (let j = 0; j < matrix.rows; j++) {
        normalized.set(j, i, (column[j] - mean) / std);
      }
    }

    return normalized;
  }

  private scaleFeatures(matrix: Matrix): Matrix {
    const scaled = new Matrix(matrix.rows, matrix.columns);
    const mins = matrix.min('column');
    const maxs = matrix.max('column');

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const min = mins[i];
      const max = maxs[i];
      const range = max - min;

      for (let j = 0; j < matrix.rows; j++) {
        scaled.set(j, i, (column[j] - min) / range);
      }
    }

    return scaled;
  }

  private applyNonlinearTransformations(matrix: Matrix): Matrix {
    const transformed = new Matrix(matrix.rows, matrix.columns);

    // Apply various nonlinear transformations
    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const transformedColumn = column.map(value => {
        // Apply multiple transformations and combine them
        const logTransformed = Math.log1p(Math.abs(value)) * Math.sign(value);
        const sqrtTransformed = Math.sqrt(Math.abs(value)) * Math.sign(value);
        const cubeRootTransformed = Math.cbrt(value);
        const sigmoidTransformed = 1 / (1 + Math.exp(-value));

        // Combine transformations with weights
        return (
          0.3 * logTransformed +
          0.3 * sqrtTransformed +
          0.2 * cubeRootTransformed +
          0.2 * sigmoidTransformed
        );
      });

      for (let j = 0; j < matrix.rows; j++) {
        transformed.set(j, i, transformedColumn[j]);
      }
    }

    return transformed;
  }

  private applyCategoricalTransformations(values: string[]): string[] {
    // Apply various categorical transformations
    return values.map(value => {
      // Convert to lowercase
      const lowercased = value.toLowerCase();

      // Remove special characters
      const cleaned = lowercased.replace(/[^a-z0-9]/g, '');

      // Apply stemming (simplified version)
      const stemmed = this.stemWord(cleaned);

      return stemmed;
    });
  }

  private stemWord(word: string): string {
    // Simple stemming implementation
    // In a real application, use a proper stemming library
    if (word.endsWith('ing')) {
      return word.slice(0, -3);
    }
    if (word.endsWith('ed')) {
      return word.slice(0, -2);
    }
    if (word.endsWith('s')) {
      return word.slice(0, -1);
    }
    return word;
  }

  private detrendFeatures(matrix: Matrix): Matrix {
    const detrended = new Matrix(matrix.rows, matrix.columns);

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const x = Array.from({ length: column.length }, (_, i) => i);
      const slope = this.calculateLinearRegressionSlope(x, column);
      const intercept = this.calculateLinearRegressionIntercept(x, column, slope);

      const detrendedColumn = column.map((value, index) => {
        const trend = slope * index + intercept;
        return value - trend;
      });

      for (let j = 0; j < matrix.rows; j++) {
        detrended.set(j, i, detrendedColumn[j]);
      }
    }

    return detrended;
  }

  private deseasonalizeFeatures(matrix: Matrix): Matrix {
    const deseasonalized = new Matrix(matrix.rows, matrix.columns);

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const seasonality = this.calculateSeasonality(column);

      const deseasonalizedColumn = column.map((value, index) => {
        return value - seasonality[index % seasonality.length];
      });

      for (let j = 0; j < matrix.rows; j++) {
        deseasonalized.set(j, i, deseasonalizedColumn[j]);
      }
    }

    return deseasonalized;
  }

  private calculateSeasonality(values: number[]): number[] {
    // Calculate seasonal pattern
    const period = this.findSeasonalPeriod(values);
    const seasonalPattern = new Array(period).fill(0);
    const counts = new Array(period).fill(0);

    for (let i = 0; i < values.length; i++) {
      const position = i % period;
      seasonalPattern[position] += values[i];
      counts[position]++;
    }

    // Calculate average seasonal pattern
    for (let i = 0; i < period; i++) {
      seasonalPattern[i] /= counts[i];
    }

    // Center the pattern
    const mean = seasonalPattern.reduce((a, b) => a + b, 0) / period;
    return seasonalPattern.map(value => value - mean);
  }

  private findSeasonalPeriod(values: number[]): number {
    // Find the period with highest autocorrelation
    const maxLag = Math.min(50, Math.floor(values.length / 2));
    let bestPeriod = 1;
    let maxAutocorr = -1;

    for (let lag = 1; lag <= maxLag; lag++) {
      const autocorr = this.calculateAutocorrelation(values, lag);
      if (autocorr > maxAutocorr) {
        maxAutocorr = autocorr;
        bestPeriod = lag;
      }
    }

    return bestPeriod;
  }

  private calculateAutocorrelation(values: number[], lag: number): number {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    let numerator = 0;
    let denominator = 0;

    for (let i = 0; i < values.length - lag; i++) {
      numerator += (values[i] - mean) * (values[i + lag] - mean);
      denominator += Math.pow(values[i] - mean, 2);
    }

    return numerator / denominator;
  }

  private applyTemporalTransformations(matrix: Matrix): Matrix {
    const transformed = new Matrix(matrix.rows, matrix.columns);

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const transformedColumn = this.applyTemporalTransformationsToColumn(column);

      for (let j = 0; j < matrix.rows; j++) {
        transformed.set(j, i, transformedColumn[j]);
      }
    }

    return transformed;
  }

  private applyTemporalTransformationsToColumn(values: number[]): number[] {
    // Apply various temporal transformations
    return values.map((value, index) => {
      // Calculate moving average
      const windowSize = 5;
      const start = Math.max(0, index - windowSize + 1);
      const window = values.slice(start, index + 1);
      const movingAvg = window.reduce((a, b) => a + b, 0) / window.length;

      // Calculate exponential smoothing
      const alpha = 0.3;
      const smoothed = index === 0 ? value : alpha * value + (1 - alpha) * values[index - 1];

      // Combine transformations
      return 0.5 * (value - movingAvg) + 0.5 * smoothed;
    });
  }

  private applyDerivedTransformations(matrix: Matrix): Matrix {
    const transformed = new Matrix(matrix.rows, matrix.columns);

    for (let i = 0; i < matrix.columns; i++) {
      const column = matrix.getColumn(i);
      const transformedColumn = this.applyDerivedTransformationsToColumn(column);

      for (let j = 0; j < matrix.rows; j++) {
        transformed.set(j, i, transformedColumn[j]);
      }
    }

    return transformed;
  }

  private applyDerivedTransformationsToColumn(values: number[]): number[] {
    // Apply various derived feature transformations
    return values.map((value, index) => {
      // Calculate rate of change
      const rateOfChange = index === 0 ? 0 : value - values[index - 1];

      // Calculate acceleration
      const acceleration = index < 2 ? 0 : rateOfChange - (values[index - 1] - values[index - 2]);

      // Calculate cumulative sum
      const cumulativeSum = values.slice(0, index + 1).reduce((a, b) => a + b, 0);

      // Combine transformations
      return 0.4 * value + 0.3 * rateOfChange + 0.2 * acceleration + 0.1 * cumulativeSum;
    });
  }

  private calculateLinearRegressionSlope(x: number[], y: number[]): number {
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);
    const sumXY = x.reduce((sum, xi, i) => sum + xi * y[i], 0);
    const sumXX = x.reduce((sum, xi) => sum + xi * xi, 0);

    return (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
  }

  private calculateLinearRegressionIntercept(x: number[], y: number[], slope: number): number {
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);

    return (sumY - slope * sumX) / n;
  }
}

import { FeatureConfig, EngineeredFeatures, FeatureValidationResult } from './types';
import { FeatureLogger } from './featureLogging';
import { Matrix } from 'ml-matrix';

export class FeatureValidator {
  private readonly config: FeatureConfig;
  private readonly logger: FeatureLogger;

  constructor(config: FeatureConfig) {
    this.config = config;
    this.logger = new FeatureLogger();
  }

  public async validate(features: EngineeredFeatures): Promise<FeatureValidationResult> {
    try {
      const result: FeatureValidationResult = {
        isValid: true,
        errors: [],
        warnings: [],
      };

      // Validate numerical features
      const numericalValidation = await this.validateNumericalFeatures(features.numerical);
      this.mergeValidationResults(result, numericalValidation);

      // Validate categorical features
      const categoricalValidation = await this.validateCategoricalFeatures(features.categorical);
      this.mergeValidationResults(result, categoricalValidation);

      // Validate temporal features
      const temporalValidation = await this.validateTemporalFeatures(features.temporal);
      this.mergeValidationResults(result, temporalValidation);

      // Validate derived features
      const derivedValidation = await this.validateDerivedFeatures(features.derived);
      this.mergeValidationResults(result, derivedValidation);

      // Validate feature metadata
      const metadataValidation = await this.validateFeatureMetadata(features.metadata);
      this.mergeValidationResults(result, metadataValidation);

      // Check overall validation threshold
      result.isValid = this.checkValidationThreshold(result);

      return result;
    } catch (error) {
      this.logger.error('Error in feature validation', error);
      throw error;
    }
  }

  private async validateNumericalFeatures(
    features: Record<string, number[]>
  ): Promise<FeatureValidationResult> {
    const result: FeatureValidationResult = {
      isValid: true,
      errors: [],
      warnings: [],
    };

    for (const [feature, values] of Object.entries(features)) {
      // Check for missing values
      const missingCount = values.filter(v => v === null || v === undefined || isNaN(v)).length;
      if (missingCount > 0) {
        result.errors.push(`Feature ${feature} has ${missingCount} missing values`);
      }

      // Check for infinite values
      const infiniteCount = values.filter(v => !isFinite(v)).length;
      if (infiniteCount > 0) {
        result.errors.push(`Feature ${feature} has ${infiniteCount} infinite values`);
      }

      // Check for constant values
      const uniqueValues = new Set(values).size;
      if (uniqueValues === 1) {
        result.warnings.push(`Feature ${feature} is constant`);
      }

      // Check for outliers
      const outliers = this.detectOutliers(values);
      if (outliers.length > 0) {
        result.warnings.push(`Feature ${feature} has ${outliers.length} outliers`);
      }

      // Check for distribution
      const distributionCheck = this.checkDistribution(values);
      if (!distributionCheck.isValid) {
        result.warnings.push(
          `Feature ${feature} has non-normal distribution: ${distributionCheck.reason}`
        );
      }
    }

    return result;
  }

  private async validateCategoricalFeatures(
    features: Record<string, string[]>
  ): Promise<FeatureValidationResult> {
    const result: FeatureValidationResult = {
      isValid: true,
      errors: [],
      warnings: [],
    };

    for (const [feature, values] of Object.entries(features)) {
      // Check for missing values
      const missingCount = values.filter(v => v === null || v === undefined || v === '').length;
      if (missingCount > 0) {
        result.errors.push(`Feature ${feature} has ${missingCount} missing values`);
      }

      // Check cardinality
      const uniqueValues = new Set(values).size;
      if (uniqueValues === 1) {
        result.warnings.push(`Feature ${feature} has only one unique value`);
      } else if (uniqueValues === values.length) {
        result.warnings.push(`Feature ${feature} has too many unique values`);
      }

      // Check value distribution
      const distribution = this.calculateValueDistribution(values);
      const imbalancedCategories = this.detectImbalancedCategories(distribution);
      if (imbalancedCategories.length > 0) {
        result.warnings.push(
          `Feature ${feature} has imbalanced categories: ${imbalancedCategories.join(', ')}`
        );
      }
    }

    return result;
  }

  private async validateTemporalFeatures(
    features: Record<string, number[]>
  ): Promise<FeatureValidationResult> {
    const result: FeatureValidationResult = {
      isValid: true,
      errors: [],
      warnings: [],
    };

    for (const [feature, values] of Object.entries(features)) {
      // Check for missing values
      const missingCount = values.filter(v => v === null || v === undefined || isNaN(v)).length;
      if (missingCount > 0) {
        result.errors.push(`Feature ${feature} has ${missingCount} missing values`);
      }

      // Check for temporal consistency
      const consistencyCheck = this.checkTemporalConsistency(values);
      if (!consistencyCheck.isValid) {
        result.errors.push(
          `Feature ${feature} has temporal inconsistency: ${consistencyCheck.reason}`
        );
      }

      // Check for seasonality
      const seasonalityCheck = this.checkSeasonality(values);
      if (seasonalityCheck.hasSeasonality) {
        result.warnings.push(
          `Feature ${feature} shows seasonality with period ${seasonalityCheck.period}`
        );
      }

      // Check for trend
      const trendCheck = this.checkTrend(values);
      if (trendCheck.hasTrend) {
        result.warnings.push(`Feature ${feature} shows ${trendCheck.trendType} trend`);
      }
    }

    return result;
  }

  private async validateDerivedFeatures(
    features: Record<string, number[]>
  ): Promise<FeatureValidationResult> {
    const result: FeatureValidationResult = {
      isValid: true,
      errors: [],
      warnings: [],
    };

    for (const [feature, values] of Object.entries(features)) {
      // Check for missing values
      const missingCount = values.filter(v => v === null || v === undefined || isNaN(v)).length;
      if (missingCount > 0) {
        result.errors.push(`Feature ${feature} has ${missingCount} missing values`);
      }

      // Check for infinite values
      const infiniteCount = values.filter(v => !isFinite(v)).length;
      if (infiniteCount > 0) {
        result.errors.push(`Feature ${feature} has ${infiniteCount} infinite values`);
      }

      // Check for correlation with original features
      const correlationCheck = this.checkFeatureCorrelation(feature, values);
      if (correlationCheck.hasHighCorrelation) {
        result.warnings.push(
          `Feature ${feature} has high correlation with ${correlationCheck.correlatedFeatures.join(', ')}`
        );
      }
    }

    return result;
  }

  private async validateFeatureMetadata(
    metadata: EngineeredFeatures['metadata']
  ): Promise<FeatureValidationResult> {
    const result: FeatureValidationResult = {
      isValid: true,
      errors: [],
      warnings: [],
    };

    // Check feature names
    if (metadata.featureNames.length === 0) {
      result.errors.push('No feature names provided');
    }

    // Check feature types
    for (const [feature, type] of Object.entries(metadata.featureTypes)) {
      if (!['numerical', 'categorical', 'temporal', 'derived'].includes(type)) {
        result.errors.push(`Invalid feature type for ${feature}: ${type}`);
      }
    }

    // Check scaling parameters
    for (const [feature, params] of Object.entries(metadata.scalingParams)) {
      if (isNaN(params.mean) || isNaN(params.std) || params.std <= 0) {
        result.errors.push(`Invalid scaling parameters for ${feature}`);
      }
    }

    // Check encoding maps
    for (const [feature, encodingMap] of Object.entries(metadata.encodingMaps)) {
      if (Object.keys(encodingMap).length === 0) {
        result.warnings.push(`Empty encoding map for ${feature}`);
      }
    }

    return result;
  }

  private mergeValidationResults(
    target: FeatureValidationResult,
    source: FeatureValidationResult
  ): void {
    target.errors.push(...source.errors);
    target.warnings.push(...source.warnings);
    target.isValid = target.isValid && source.isValid;
  }

  private checkValidationThreshold(result: FeatureValidationResult): boolean {
    const totalChecks = result.errors.length + result.warnings.length;
    const errorRatio = result.errors.length / totalChecks;
    return errorRatio <= 1 - this.config.validationThreshold;
  }

  private detectOutliers(values: number[]): number[] {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);
    const threshold = 3; // 3 standard deviations

    return values.filter(value => Math.abs(value - mean) > threshold * std);
  }

  private checkDistribution(values: number[]): { isValid: boolean; reason: string } {
    // Simple normality test using skewness and kurtosis
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);

    const skewness =
      values.reduce((a, b) => a + Math.pow(b - mean, 3), 0) / (values.length * Math.pow(std, 3));
    const kurtosis =
      values.reduce((a, b) => a + Math.pow(b - mean, 4), 0) / (values.length * Math.pow(std, 4)) -
      3;

    if (Math.abs(skewness) > 1) {
      return { isValid: false, reason: `High skewness (${skewness.toFixed(2)})` };
    }
    if (Math.abs(kurtosis) > 1) {
      return { isValid: false, reason: `High kurtosis (${kurtosis.toFixed(2)})` };
    }

    return { isValid: true, reason: '' };
  }

  private calculateValueDistribution(values: string[]): Record<string, number> {
    const distribution: Record<string, number> = {};
    const total = values.length;

    for (const value of values) {
      distribution[value] = (distribution[value] || 0) + 1;
    }

    for (const key of Object.keys(distribution)) {
      distribution[key] /= total;
    }

    return distribution;
  }

  private detectImbalancedCategories(distribution: Record<string, number>): string[] {
    const threshold = 0.1; // 10% threshold for imbalance
    return Object.entries(distribution)
      .filter(([_, ratio]) => ratio < threshold)
      .map(([category]) => category);
  }

  private checkTemporalConsistency(values: number[]): {
    isValid: boolean;
    reason: string;
  } {
    // Check for gaps in the sequence
    const gaps = this.findTemporalGaps(values);
    if (gaps.length > 0) {
      return {
        isValid: false,
        reason: `Found ${gaps.length} temporal gaps`,
      };
    }

    // Check for sudden changes
    const changes = this.detectSuddenChanges(values);
    if (changes.length > 0) {
      return {
        isValid: false,
        reason: `Found ${changes.length} sudden changes`,
      };
    }

    return { isValid: true, reason: '' };
  }

  private findTemporalGaps(values: number[]): number[] {
    const gaps: number[] = [];
    for (let i = 1; i < values.length; i++) {
      if (values[i] - values[i - 1] > 1) {
        gaps.push(i);
      }
    }
    return gaps;
  }

  private detectSuddenChanges(values: number[]): number[] {
    const changes: number[] = [];
    const threshold = 3; // 3 standard deviations

    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const std = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);

    for (let i = 1; i < values.length; i++) {
      const change = Math.abs(values[i] - values[i - 1]);
      if (change > threshold * std) {
        changes.push(i);
      }
    }

    return changes;
  }

  private checkSeasonality(values: number[]): {
    hasSeasonality: boolean;
    period: number;
  } {
    const maxLag = Math.min(50, Math.floor(values.length / 2));
    let bestPeriod = 1;
    let maxAutocorr = -1;

    for (let lag = 1; lag <= maxLag; lag++) {
      const autocorr = this.calculateAutocorrelation(values, lag);
      if (autocorr > maxAutocorr) {
        maxAutocorr = autocorr;
        bestPeriod = lag;
      }
    }

    return {
      hasSeasonality: maxAutocorr > 0.5,
      period: bestPeriod,
    };
  }

  private checkTrend(values: number[]): {
    hasTrend: boolean;
    trendType: string;
  } {
    const x = Array.from({ length: values.length }, (_, i) => i);
    const slope = this.calculateLinearRegressionSlope(x, values);

    if (Math.abs(slope) < 0.01) {
      return { hasTrend: false, trendType: '' };
    }

    return {
      hasTrend: true,
      trendType: slope > 0 ? 'increasing' : 'decreasing',
    };
  }

  private checkFeatureCorrelation(
    feature: string,
    values: number[]
  ): {
    hasHighCorrelation: boolean;
    correlatedFeatures: string[];
  } {
    // This is a placeholder implementation
    // In a real application, calculate correlation with other features
    return {
      hasHighCorrelation: false,
      correlatedFeatures: [],
    };
  }

  private calculateAutocorrelation(values: number[], lag: number): number {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    let numerator = 0;
    let denominator = 0;

    for (let i = 0; i < values.length - lag; i++) {
      numerator += (values[i] - mean) * (values[i + lag] - mean);
      denominator += Math.pow(values[i] - mean, 2);
    }

    return numerator / denominator;
  }

  private calculateLinearRegressionSlope(x: number[], y: number[]): number {
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);
    const sumXY = x.reduce((sum, xi, i) => sum + xi * y[i], 0);
    const sumXX = x.reduce((sum, xi) => sum + xi * xi, 0);

    return (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
  }
}

