import { AppError, APIError } from '../core/UnifiedError';
import { User } from '../types';
import { unifiedMonitor } from '../core/UnifiedMonitor';

// src/services/authService.ts

const API_BASE_URL = import.meta.env.VITE_API_URL;
const AUTH_API_PREFIX = `${API_BASE_URL}/api/auth`;

// Matches the Token model from backend/routes/auth_route.py
interface BackendTokenResponse {
  access_token: string;
  token_type: string;
  user: User; // Assuming backend User model matches frontend User type
}

// Response structure expected by the original frontend code (e.g., AuthSlice)
interface AuthServiceLoginResponse {
  user: User;
  token: string;
}

/**
 * Logs in a user.
 * Expected backend response (from /api/auth/login):
 * {
 *   "access_token": "string (jwt)",
 *   "token_type": "bearer",
 *   "user": { "id": "string", "username": "string", "email": "string", ... }
 * }
 */
export const login = async (credentials: { email: string; password: string }): Promise<AuthServiceLoginResponse> => {
  const trace = unifiedMonitor.startTrace('authService.login', 'http.client');
  try {
    const { post } = await import('./api');
    const response = await post<BackendTokenResponse>(`${AUTH_API_PREFIX}/login`, credentials);
    
    if (trace) {
      trace.setHttpStatus(response.status);
      unifiedMonitor.endTrace(trace);
    }

    // Adapt backend response to the structure AuthSlice expects
    return {
      user: response.data.user,
      token: response.data.access_token,
    };
  } catch (error: any) {
    const errContext = { service: 'authService', operation: 'login', email: credentials.email };
    unifiedMonitor.reportError(error, errContext);
    if (trace) {
      trace.setHttpStatus(error.response?.status || 500);
      unifiedMonitor.endTrace(trace);
    }
    if (error.response && error.response.data && error.response.data.detail) {
      throw new APIError(error.response.data.detail, error.response.status, errContext, error);
    }
    throw new AppError('Login failed. Please check your credentials or try again later.', undefined, errContext, error);
  }
};

// Logout is typically a client-side token removal. 
// The backend /auth/logout is a placeholder but can be called for completeness.
export const logout = async (): Promise<void> => {
  const trace = unifiedMonitor.startTrace('authService.logout', 'http.client');
  try {
    const { post } = await import('./api');
    await post(`${AUTH_API_PREFIX}/logout`); 
    if (trace) {
        trace.setHttpStatus(200); // Assuming logout call is fire and forget or returns 200
        unifiedMonitor.endTrace(trace);
    }
  } catch (error: any) {
    // Usually, logout errors aren't critical for the client's ability to log out (clear token).
    unifiedMonitor.reportError(error, { service: 'authService', operation: 'logout' }, 'warning');
    if (trace) {
        trace.setHttpStatus(error.response?.status || 500);
        unifiedMonitor.endTrace(trace);
    }
  }
  // Primary logout action (clearing token) is handled in the authSlice or consuming component.
};

/**
 * Fetches the current authenticated user's details.
 * Requires a valid JWT in the Authorization header (handled by apiClient interceptor).
 * Expected backend response (from /api/users/me, which should be a protected route):
 * {
 *   "id": "string",
 *   "username": "string",
 *   "email": "string",
 *   // ... other user fields as defined in the User type
 * }
 */
export const fetchCurrentUser = async (): Promise<User> => {
    const trace = unifiedMonitor.startTrace('authService.fetchCurrentUser', 'http.client');
    try {
        const { get } = await import('./api');
        const response = await get<User>(`${API_BASE_URL}/api/users/me`);
        if (trace) {
            trace.setHttpStatus(response.status);
            unifiedMonitor.endTrace(trace);
        }
        return response.data;
    } catch (error: any) {
        const errContext = { service: 'authService', operation: 'fetchCurrentUser' };
        unifiedMonitor.reportError(error, errContext);
        if (trace) {
            trace.setHttpStatus(error.response?.status || 500);
            unifiedMonitor.endTrace(trace);
        }
        if (error.response && error.response.status === 401) {
             throw new APIError('Unauthorized. Please log in again.', 401, errContext, error);
        }
        throw new AppError('Failed to fetch user profile.', undefined, errContext, error);
    }
};

// Combining into a service object as per original structure
export const authService = {
  login,
  logout,
  fetchCurrentUser,
};

import { Injectable } from '@nestjs/common';
import { UserPersonalizationService } from '../analytics/userPersonalizationService';
import { PredictionOptimizationService } from '../analytics/predictionOptimizationService';
import { RiskManagementService } from '../riskManagement';
import { BankrollService } from '../bankroll';
import { NotificationService } from '../notification';
import { UnifiedBettingCore } from '../unified/UnifiedBettingCore';
import { EventEmitter } from 'events';

@Injectable()
export class BettingAutomationService extends EventEmitter {
  private static instance: BettingAutomationService;
  private isRunning: boolean = false;
  private readonly updateInterval: number = 5 * 60 * 1000; // 5 minutes
  private updateTimer: NodeJS.Timeout | null = null;

  private constructor(
    private readonly userPersonalizationService: UserPersonalizationService,
    private readonly predictionOptimizationService: PredictionOptimizationService,
    private readonly riskManagementService: RiskManagementService,
    private readonly bankrollService: BankrollService,
    private readonly notificationService: NotificationService,
    private readonly unifiedBettingCore: UnifiedBettingCore
  ) {
    super();
  }

  public static getInstance(): BettingAutomationService {
    if (!BettingAutomationService.instance) {
      BettingAutomationService.instance = new BettingAutomationService(
        new UserPersonalizationService(),
        new PredictionOptimizationService(),
        RiskManagementService.getInstance(),
        BankrollService.getInstance(),
        NotificationService.getInstance(),
        UnifiedBettingCore.getInstance()
      );
    }
    return BettingAutomationService.instance;
  }

  public async start(): Promise<void> {
    if (this.isRunning) {
      return;
    }

    try {
      this.isRunning = true;
      this.notificationService.notify('info', 'Betting automation started');

      // Initialize all services
      await this.initializeServices();

      // Start the update loop
      this.startUpdateLoop();

      // Set up event listeners
      this.setupEventListeners();

      this.emit('started');
    } catch (error) {
      this.isRunning = false;
      this.notificationService.notify('error', 'Failed to start betting automation', { error });
      throw error;
    }
  }

  public async stop(): Promise<void> {
    if (!this.isRunning) {
      return;
    }

    try {
      this.isRunning = false;
      if (this.updateTimer) {
        clearInterval(this.updateTimer);
        this.updateTimer = null;
      }

      this.notificationService.notify('info', 'Betting automation stopped');
      this.emit('stopped');
    } catch (error) {
      this.notificationService.notify('error', 'Error stopping betting automation', { error });
      throw error;
    }
  }

  private async initializeServices(): Promise<void> {
    try {
      // Initialize each service
      await Promise.all([
        this.userPersonalizationService.initialize(),
        this.predictionOptimizationService.initialize(),
        this.riskManagementService.initialize(),
        this.bankrollService.initialize(),
        this.unifiedBettingCore.initialize(),
      ]);
    } catch (error) {
      this.notificationService.notify('error', 'Failed to initialize services', { error });
      throw error;
    }
  }

  private startUpdateLoop(): void {
    this.updateTimer = setInterval(async () => {
      try {
        await this.performUpdate();
      } catch (error) {
        this.notificationService.notify('error', 'Error in update loop', { error });
      }
    }, this.updateInterval);
  }

  private async performUpdate(): Promise<void> {
    try {
      // Get latest predictions
      const predictions = await this.predictionOptimizationService.getOptimizedPrediction({
        timestamp: Date.now(),
        marketData: await this.getMarketData(),
        userProfiles: await this.getUserProfiles(),
      });

      // Process each prediction
      for (const prediction of predictions) {
        // Get personalized prediction
        const personalizedPrediction =
          await this.userPersonalizationService.getPersonalizedPrediction(
            prediction.userId,
            prediction
          );

        // Assess risk
        const riskAssessment = await this.riskManagementService.assessRisk({
          prediction: personalizedPrediction,
          bankroll: this.bankrollService.getCurrentBalance(),
          activeBets: await this.getActiveBets(),
        });

        // Make betting decision
        if (this.shouldPlaceBet(riskAssessment)) {
          await this.placeBet(personalizedPrediction, riskAssessment);
        }
      }

      // Update bankroll metrics
      await this.updateBankrollMetrics();

      // Check for stop loss/take profit
      this.checkBankrollLimits();
    } catch (error) {
      this.notificationService.notify('error', 'Error in update cycle', { error });
    }
  }

  private setupEventListeners(): void {
    // Listen for bankroll events
    this.bankrollService.on('stopLoss', () => {
      this.notificationService.notify('warning', 'Stop loss reached');
      this.stop();
    });

    this.bankrollService.on('takeProfit', () => {
      this.notificationService.notify('success', 'Take profit reached');
      this.stop();
    });

    // Listen for risk events
    this.riskManagementService.on('highRisk', data => {
      this.notificationService.notify('warning', 'High risk detected', data);
    });

    // Listen for prediction events
    this.predictionOptimizationService.on('modelUpdate', data => {
      this.notificationService.notify('info', 'Prediction models updated', data);
    });
  }

  private async getMarketData(): Promise<any> {
    // Implement market data fetching
    return {};
  }

  private async getUserProfiles(): Promise<any[]> {
    // Implement user profile fetching
    return [];
  }

  private async getActiveBets(): Promise<any[]> {
    // Implement active bets fetching
    return [];
  }

  private shouldPlaceBet(riskAssessment: any): boolean {
    return (
      riskAssessment.riskLevel === 'low' &&
      riskAssessment.expectedValue > 0 &&
      riskAssessment.confidence > 0.7
    );
  }

  private async placeBet(prediction: any, riskAssessment: any): Promise<void> {
    try {
      const stake = this.calculateStake(riskAssessment);
      await this.unifiedBettingCore.placeBet({
        prediction,
        stake,
        riskAssessment,
      });

      this.notificationService.notify('success', 'Bet placed successfully', {
        prediction,
        stake,
        riskAssessment,
      });
    } catch (error) {
      this.notificationService.notify('error', 'Failed to place bet', { error });
    }
  }

  private calculateStake(riskAssessment: any): number {
    const maxStake = riskAssessment.maxStake;
    const recommendedStake = riskAssessment.recommendedStake;
    return Math.min(maxStake, recommendedStake);
  }

  private async updateBankrollMetrics(): Promise<void> {
    const metrics = await this.bankrollService.getMetrics();
    this.emit('metricsUpdated', metrics);
  }

  private checkBankrollLimits(): void {
    if (this.bankrollService.checkStopLoss()) {
      this.stop();
    }
    if (this.bankrollService.checkTakeProfit()) {
      this.stop();
    }
  }
}

import apiService from './api';
import { Transaction, BankrollSettings, BankrollStats } from '../types/bankroll';
import { notificationService } from './notification';
import { Injectable } from '@nestjs/common';
import { EventEmitter } from 'events';

export interface BankrollTransaction {
  id: string;
  type: 'deposit' | 'withdrawal' | 'bet' | 'win' | 'loss';
  amount: number;
  timestamp: string;
  description: string;
  status: 'pending' | 'completed' | 'failed';
  metadata?: any;
}

@Injectable()
export class BankrollService extends EventEmitter {
  private static instance: BankrollService;
  private currentBalance: number = 1000; // Starting balance
  private transactions: Transaction[] = [];
  private settings: BankrollSettings = {
    maxBetPercentage: 0.05,
    stopLossPercentage: 0.1,
    takeProfitPercentage: 0.2,
    kellyFraction: 0.5,
  };

  private constructor() {
    super();
    // Initialize balance from localStorage if available
    const storedBalance = localStorage.getItem('current_balance');
    if (storedBalance) {
      this.currentBalance = parseFloat(storedBalance);
    }
  }

  public static getInstance(): BankrollService {
    if (!BankrollService.instance) {
      BankrollService.instance = new BankrollService();
    }
    return BankrollService.instance;
  }

  public async initialize(): Promise<void> {
    // Initialize bankroll service
  }

  public async getBalance(): Promise<number> {
    try {
      const response = await apiService.getUserProfile();
      this.currentBalance = response.data.balance;
      localStorage.setItem('current_balance', this.currentBalance.toString());
      return this.currentBalance;
    } catch (error) {
      console.error('Failed to fetch balance:', error);
      throw error;
    }
  }

  public async deposit(amount: number): Promise<Transaction> {
    try {
      const response = await apiService.createTransaction({
        type: 'deposit',
        amount,
        status: 'pending',
      });

      if (response.data.status === 'completed') {
        this.currentBalance += amount;
        localStorage.setItem('current_balance', this.currentBalance.toString());
      }

      return response.data;
    } catch (error) {
      console.error('Failed to process deposit:', error);
      throw error;
    }
  }

  public async withdraw(amount: number): Promise<Transaction> {
    if (amount > this.currentBalance) {
      throw new Error('Insufficient funds');
    }

    try {
      const response = await apiService.createTransaction({
        type: 'withdrawal',
        amount,
        status: 'pending',
      });

      if (response.data.status === 'completed') {
        this.currentBalance -= amount;
        localStorage.setItem('current_balance', this.currentBalance.toString());
      }

      return response.data;
    } catch (error) {
      console.error('Failed to process withdrawal:', error);
      throw error;
    }
  }

  public async getTransactionHistory(): Promise<Transaction[]> {
    try {
      const response = await apiService.getTransactions();
      return response.data;
    } catch (error) {
      console.error('Failed to fetch transaction history:', error);
      throw error;
    }
  }

  public getCurrentBalance(): number {
    return this.currentBalance;
  }

  public async updateBalance(amount: number, type: 'win' | 'loss' | 'bet'): Promise<void> {
    try {
      const response = await apiService.createTransaction({
        type,
        amount: Math.abs(amount),
        status: 'completed',
      });

      if (response.data.status === 'completed') {
        switch (type) {
          case 'win':
            this.currentBalance += amount;
            break;
          case 'loss':
          case 'bet':
            this.currentBalance -= amount;
            break;
        }
        localStorage.setItem('current_balance', this.currentBalance.toString());
      }
    } catch (error) {
      console.error('Failed to update balance:', error);
      throw error;
    }
  }

  public getTransactions(): Transaction[] {
    return this.transactions;
  }

  public getSettings(): BankrollSettings {
    return this.settings;
  }

  public updateSettings(newSettings: Partial<BankrollSettings>): void {
    this.settings = { ...this.settings, ...newSettings };
  }

  public getStats(): BankrollStats {
    const stats: BankrollStats = {
      currentBalance: this.currentBalance,
      startingBalance: this.getStartingBalance(),
      totalDeposits: this.getTotalDeposits(),
      totalWithdrawals: this.getTotalWithdrawals(),
      totalBets: this.getTotalBets(),
      totalWins: this.getTotalWins(),
      totalLosses: this.getTotalLosses(),
      netProfit: this.getNetProfit(),
      roi: this.getROI(),
      winRate: this.getWinRate(),
      averageBetSize: this.getAverageBetSize(),
      largestWin: this.getLargestWin(),
      largestLoss: this.getLargestLoss(),
      currentStreak: this.getCurrentStreak(),
      bestStreak: this.getBestStreak(),
      worstStreak: this.getWorstStreak(),
    };

    return stats;
  }

  private getStartingBalance(): number {
    const firstDeposit = this.transactions.find(t => t.type === 'deposit');
    return firstDeposit ? firstDeposit.amount : 0;
  }

  private getTotalDeposits(): number {
    return this.transactions
      .filter(t => t.type === 'deposit')
      .reduce((sum, t) => sum + t.amount, 0);
  }

  private getTotalWithdrawals(): number {
    return Math.abs(
      this.transactions.filter(t => t.type === 'withdrawal').reduce((sum, t) => sum + t.amount, 0)
    );
  }

  private getTotalBets(): number {
    return this.transactions.filter(t => t.type === 'bet').length;
  }

  private getTotalWins(): number {
    return this.transactions.filter(t => t.type === 'win').length;
  }

  private getTotalLosses(): number {
    return this.transactions.filter(t => t.type === 'loss').length;
  }

  private getNetProfit(): number {
    return this.transactions.reduce((sum, t) => sum + t.amount, 0);
  }

  private getROI(): number {
    const totalBets = this.getTotalBets();
    if (totalBets === 0) return 0;
    return (this.getNetProfit() / this.getTotalDeposits()) * 100;
  }

  private getWinRate(): number {
    const totalBets = this.getTotalBets();
    if (totalBets === 0) return 0;
    return (this.getTotalWins() / totalBets) * 100;
  }

  private getAverageBetSize(): number {
    const bets = this.transactions.filter(t => t.type === 'bet');
    if (bets.length === 0) return 0;
    return Math.abs(bets.reduce((sum, t) => sum + t.amount, 0)) / bets.length;
  }

  private getLargestWin(): number {
    const wins = this.transactions.filter(t => t.type === 'win');
    if (wins.length === 0) return 0;
    return Math.max(...wins.map(t => t.amount));
  }

  private getLargestLoss(): number {
    const losses = this.transactions.filter(t => t.type === 'loss');
    if (losses.length === 0) return 0;
    return Math.abs(Math.min(...losses.map(t => t.amount)));
  }

  private getCurrentStreak(): number {
    let streak = 0;
    for (let i = this.transactions.length - 1; i >= 0; i--) {
      const t = this.transactions[i];
      if (t.type === 'win') streak++;
      else if (t.type === 'loss') break;
    }
    return streak;
  }

  private getBestStreak(): number {
    let currentStreak = 0;
    let bestStreak = 0;
    for (const t of this.transactions) {
      if (t.type === 'win') {
        currentStreak++;
        bestStreak = Math.max(bestStreak, currentStreak);
      } else if (t.type === 'loss') {
        currentStreak = 0;
      }
    }
    return bestStreak;
  }

  private getWorstStreak(): number {
    let currentStreak = 0;
    let worstStreak = 0;
    for (const t of this.transactions) {
      if (t.type === 'loss') {
        currentStreak++;
        worstStreak = Math.max(worstStreak, currentStreak);
      } else if (t.type === 'win') {
        currentStreak = 0;
      }
    }
    return worstStreak;
  }

  public getMaxBetAmount(): number {
    return this.currentBalance * this.settings.maxBetPercentage;
  }

  private getDailyBetsCount(): number {
    const today = new Date().toISOString().split('T')[0];
    return this.transactions.filter(t => t.type === 'bet' && t.timestamp.startsWith(today)).length;
  }

  private getConcurrentBetsCount(): number {
    return this.transactions.filter(t => t.type === 'bet' && t.status === 'completed').length;
  }

  public checkStopLoss(): boolean {
    const stopLossAmount = this.currentBalance * this.settings.stopLossPercentage;
    return this.currentBalance <= stopLossAmount;
  }

  public checkTakeProfit(): boolean {
    const takeProfitAmount = this.currentBalance * this.settings.takeProfitPercentage;
    return this.currentBalance >= takeProfitAmount;
  }

  public getMetrics(): BankrollStats {
    const totalWins = this.transactions.filter(t => t.type === 'win').length;
    const totalLosses = this.transactions.filter(t => t.type === 'loss').length;
    const totalBets = this.transactions.filter(t => t.type === 'bet').length;
    const winRate = totalBets > 0 ? totalWins / totalBets : 0;
    const averageBetSize =
      totalBets > 0
        ? this.transactions.filter(t => t.type === 'bet').reduce((sum, t) => sum + t.amount, 0) /
          totalBets
        : 0;
    const largestWin = Math.max(
      ...this.transactions.filter(t => t.type === 'win').map(t => t.amount),
      0
    );
    const largestLoss = Math.min(
      ...this.transactions.filter(t => t.type === 'loss').map(t => t.amount),
      0
    );
    const netProfit = this.currentBalance - 1000; // Starting balance
    const roi = netProfit / 1000; // ROI relative to starting balance

    return {
      currentBalance: this.currentBalance,
      startingBalance: 1000,
      totalWins,
      totalLosses,
      winRate,
      averageBetSize,
      largestWin,
      largestLoss,
      netProfit,
      roi,
    };
  }
}

