  private async calculateCorrelations(props: PropAnalysis[]): Promise<number[][]> {
    const n = props.length;
    const matrix = Array(n)
      .fill(0)
      .map(() => Array(n).fill(0));

    // Calculate pairwise correlations
    for (let i = 0; i < n; i++) {
      for (let j = i; j < n; j++) {
        if (i === j) {
          matrix[i][j] = 1;
        } else {
