import { EventEmitter } from 'events';
import {
  BettingOdds,
  MarketMetrics,
  MarketEfficiencyMetrics,
  MarketAnomaly,
} from '../types/betting';
import { MarketContext } from '../types/core';
import { AdvancedMLService } from './analytics/advancedMLService';
import { HyperAdvancedMLService } from './analytics/hyperAdvancedMLService';
import { UltraMLService } from './analytics/ultraMLService';

export class MarketAnalysisService extends EventEmitter {
  private static instance: MarketAnalysisService;
  private marketMetrics: Map<string, MarketMetrics> = new Map();
  private anomalies: Map<string, MarketAnomaly[]> = new Map();
  private readonly ANOMALY_THRESHOLD = 2.0;
  private readonly EFFICIENCY_WINDOW = 24 * 60 * 60 * 1000;
  private readonly VOLUME_WINDOW = 60 * 60 * 1000; // 1 hour
  private readonly TREND_WINDOW = 5; // Number of data points for trend analysis
  private readonly advancedML: AdvancedMLService;
  private readonly hyperAdvancedML: HyperAdvancedMLService;
  private readonly ultraML: UltraMLService;

  private constructor() {
    super();
    this.advancedML = AdvancedMLService.getInstance();
    this.hyperAdvancedML = HyperAdvancedMLService.getInstance();
    this.ultraML = UltraMLService.getInstance();
  }

  public static getInstance(): MarketAnalysisService {
    if (!MarketAnalysisService.instance) {
      MarketAnalysisService.instance = new MarketAnalysisService();
    }
    return MarketAnalysisService.instance;
  }

  public updateMarketMetrics(eventId: string, odds: BettingOdds[]): void {
    const currentMetrics = this.marketMetrics.get(eventId) || {
      volume: {
        totalVolume: 0,
        lastUpdate: Date.now(),
        volumeHistory: [],
      },
      liquidity: 0,
      volatility: 0,
      trend: 0,
    };

    // Update metrics with advanced analysis
    this.updateVolumeMetrics(currentMetrics, odds);
    this.updateLiquidityMetrics(currentMetrics, odds);
    this.updateVolatilityMetrics(currentMetrics);
    this.updateTrendMetrics(currentMetrics);

    // Store updated metrics
    this.marketMetrics.set(eventId, currentMetrics);

    // Enhanced anomaly detection with ML
    this.detectAnomalies(eventId, currentMetrics, odds);

    // Calculate market efficiency with advanced metrics
    const efficiencyMetrics = this.calculateMarketEfficiency(eventId, odds);
    this.emit('marketEfficiency', { eventId, metrics: efficiencyMetrics });

    // Emit real-time market updates
    this.emit('marketUpdate', { eventId, metrics: currentMetrics });
  }

  private updateVolumeMetrics(metrics: MarketMetrics, odds: BettingOdds[]): void {
    const currentTime = Date.now();
    const recentVolume = odds.reduce((sum, odd) => sum + (odd.volume || 0), 0);

    // Update volume history with time-based window
    metrics.volume.volumeHistory = metrics.volume.volumeHistory
      .filter(v => currentTime - v.timestamp <= this.VOLUME_WINDOW)
      .concat({ timestamp: currentTime, volume: recentVolume });

    metrics.volume.totalVolume = metrics.volume.volumeHistory.reduce((sum, v) => sum + v.volume, 0);
    metrics.volume.lastUpdate = currentTime;
  }

  private updateLiquidityMetrics(metrics: MarketMetrics, odds: BettingOdds[]): void {
    if (odds.length < 2) return;

    const bestBack = Math.max(...odds.map(o => o.odds));
    const bestLay = Math.min(...odds.map(o => o.odds));
    const spread = bestBack - bestLay;
    const totalStake = odds.reduce((sum, odd) => sum + (odd.maxStake || 0), 0);

    // Enhanced liquidity calculation considering market depth
    const depthWeightedStake = odds.reduce((sum, odd) => {
      const depth = (odd.maxStake || 0) / (spread || 1);
      return sum + depth;
    }, 0);

    metrics.liquidity = depthWeightedStake / (spread || 1);
  }

  private updateVolatilityMetrics(metrics: MarketMetrics): void {
    if (metrics.volume.volumeHistory.length < 2) return;

    const volumes = metrics.volume.volumeHistory.map(v => v.volume);
    const returns = volumes.slice(1).map((v, i) => Math.log(v / volumes[i]));

    const mean = returns.reduce((sum, r) => sum + r, 0) / returns.length;
    const variance = returns.reduce((sum, r) => sum + Math.pow(r - mean, 2), 0) / returns.length;

    metrics.volatility = Math.sqrt(variance) * Math.sqrt(252); // Annualized volatility
  }

  private updateTrendMetrics(metrics: MarketMetrics): void {
    if (metrics.volume.volumeHistory.length < 2) return;

    const recentVolumes = metrics.volume.volumeHistory.slice(-this.TREND_WINDOW);
    const xMean = (recentVolumes.length - 1) / 2;
    const yMean = recentVolumes.reduce((sum, v) => sum + v.volume, 0) / recentVolumes.length;

    let numerator = 0;
    let denominator = 0;

    recentVolumes.forEach((v, i) => {
      const xDiff = i - xMean;
      const yDiff = v.volume - yMean;
      numerator += xDiff * yDiff;
      denominator += xDiff * xDiff;
    });

    metrics.trend = denominator === 0 ? 0 : numerator / denominator;
  }

  private async detectAnomalies(
    eventId: string,
    metrics: MarketMetrics,
    odds: BettingOdds[]
  ): Promise<void> {
    const anomalies: MarketAnomaly[] = [];

    // Volume anomaly detection with ML enhancement
    if (metrics.volume.volumeHistory.length >= 5) {
      const recentVolumes = metrics.volume.volumeHistory.slice(-5).map(v => v.volume);
      const mlPrediction = await this.advancedML.predictVolumeAnomaly(recentVolumes);

      if (mlPrediction.isAnomaly) {
        anomalies.push({
          type: 'volume',
          severity: this.getAnomalySeverity(mlPrediction.deviation),
          description: `ML-detected volume anomaly: ${mlPrediction.deviation.toFixed(2)} standard deviations from expected`,
          timestamp: Date.now(),
          metrics: {
            current: recentVolumes[recentVolumes.length - 1],
            expected: mlPrediction.expectedValue,
            deviation: mlPrediction.deviation,
          },
        });
      }
    }

    // Price anomaly detection
    if (odds.length >= 2) {
      const priceAnomaly = await this.detectPriceAnomaly(odds);
      if (priceAnomaly) {
        anomalies.push(priceAnomaly);
      }
    }

    // Spread anomaly detection
    const spreadAnomaly = await this.detectSpreadAnomaly(odds);
    if (spreadAnomaly) {
      anomalies.push(spreadAnomaly);
    }

    // Liquidity anomaly detection
    const liquidityAnomaly = await this.detectLiquidityAnomaly(metrics, odds);
    if (liquidityAnomaly) {
      anomalies.push(liquidityAnomaly);
    }

    // Store and emit anomalies
    if (anomalies.length > 0) {
      this.anomalies.set(eventId, anomalies);
      this.emit('marketAnomaly', { eventId, anomalies });
    }
  }

  private async detectPriceAnomaly(odds: BettingOdds[]): Promise<MarketAnomaly | null> {
    const pricePrediction = await this.hyperAdvancedML.predictPriceAnomaly(odds);

    if (pricePrediction.isAnomaly) {
      return {
        type: 'price',
        severity: this.getAnomalySeverity(pricePrediction.deviation),
        description: `ML-detected price anomaly: ${pricePrediction.deviation.toFixed(2)} standard deviations from expected`,
        timestamp: Date.now(),
        metrics: {
          current: pricePrediction.currentPrice,
          expected: pricePrediction.expectedPrice,
          deviation: pricePrediction.deviation,
        },
      };
    }
    return null;
  }

  private async detectSpreadAnomaly(odds: BettingOdds[]): Promise<MarketAnomaly | null> {
    const spreadPrediction = await this.ultraML.predictSpreadAnomaly(odds);

    if (spreadPrediction.isAnomaly) {
      return {
        type: 'spread',
        severity: this.getAnomalySeverity(spreadPrediction.deviation),
        description: `ML-detected spread anomaly: ${spreadPrediction.deviation.toFixed(2)} standard deviations from expected`,
        timestamp: Date.now(),
        metrics: {
          current: spreadPrediction.currentSpread,
          expected: spreadPrediction.expectedSpread,
          deviation: spreadPrediction.deviation,
        },
      };
    }
    return null;
  }

  private async detectLiquidityAnomaly(
    metrics: MarketMetrics,
    odds: BettingOdds[]
  ): Promise<MarketAnomaly | null> {
    const liquidityPrediction = await this.advancedML.predictLiquidityAnomaly(metrics, odds);

    if (liquidityPrediction.isAnomaly) {
      return {
        type: 'liquidity',
        severity: this.getAnomalySeverity(liquidityPrediction.deviation),
        description: `ML-detected liquidity anomaly: ${liquidityPrediction.deviation.toFixed(2)} standard deviations from expected`,
        timestamp: Date.now(),
        metrics: {
          current: liquidityPrediction.currentLiquidity,
          expected: liquidityPrediction.expectedLiquidity,
          deviation: liquidityPrediction.deviation,
        },
      };
    }
    return null;
  }

  private getAnomalySeverity(deviation: number): 'low' | 'medium' | 'high' {
    if (deviation >= 3.0) return 'high';
    if (deviation >= 2.0) return 'medium';
    return 'low';
  }

  private calculateMarketEfficiency(eventId: string, odds: BettingOdds[]): MarketEfficiencyMetrics {
    const metrics = this.marketMetrics.get(eventId);
    if (!metrics) {
      return {
        spreadEfficiency: 0,
        volumeEfficiency: 0,
        priceDiscovery: 0,
        marketDepth: 0,
      };
    }

    // Enhanced market efficiency calculations
    const spreadEfficiency = this.calculateSpreadEfficiency(odds);
    const volumeEfficiency = this.calculateVolumeEfficiency(metrics, odds);
    const priceDiscovery = this.calculatePriceDiscovery(metrics);
    const marketDepth = this.calculateMarketDepth(metrics, odds);

    return {
      spreadEfficiency,
      volumeEfficiency,
      priceDiscovery,
      marketDepth,
    };
  }

  private calculateSpreadEfficiency(odds: BettingOdds[]): number {
    if (odds.length < 2) return 0;

    const bestBack = Math.max(...odds.map(o => o.odds));
    const bestLay = Math.min(...odds.map(o => o.odds));
    const spread = bestBack - bestLay;
    const midPrice = (bestBack + bestLay) / 2;

    // Normalize spread efficiency (0-1 scale)
    return Math.max(0, 1 - spread / midPrice);
  }

  private calculateVolumeEfficiency(metrics: MarketMetrics, odds: BettingOdds[]): number {
    if (odds.length < 2) return 0;

    const spread = Math.max(...odds.map(o => o.odds)) - Math.min(...odds.map(o => o.odds));
    const volume = metrics.volume.totalVolume;

    // Higher volume relative to spread indicates higher efficiency
    return volume / (spread * 1000); // Normalize to reasonable range
  }

  private calculatePriceDiscovery(metrics: MarketMetrics): number {
    if (metrics.volume.volumeHistory.length < 2) return 0;

    // Calculate how quickly prices adjust to new information
    const recentVolumes = metrics.volume.volumeHistory.slice(-5);
    const volumeChanges = recentVolumes
      .slice(1)
      .map((v, i) => Math.abs(v.volume - recentVolumes[i].volume));
    const avgChange = volumeChanges.reduce((sum, change) => sum + change, 0) / volumeChanges.length;

    return avgChange / metrics.volume.totalVolume;
  }

  private calculateMarketDepth(metrics: MarketMetrics, odds: BettingOdds[]): number {
    if (odds.length < 2) return 0;

    const totalStake = odds.reduce((sum, odd) => sum + (odd.maxStake || 0), 0);
    const spread = Math.max(...odds.map(o => o.odds)) - Math.min(...odds.map(o => o.odds));

    // Higher total stake relative to spread indicates deeper market
    return totalStake / (spread * 1000); // Normalize to reasonable range
  }

  public getMarketMetrics(eventId: string): MarketMetrics | undefined {
    return this.marketMetrics.get(eventId);
  }

  public getAnomalies(eventId: string): MarketAnomaly[] {
    return this.anomalies.get(eventId) || [];
  }

  public getMarketEfficiency(eventId: string): MarketEfficiencyMetrics | undefined {
    const metrics = this.marketMetrics.get(eventId);
    if (!metrics) return undefined;

    return this.calculateMarketEfficiency(eventId, []);
  }
}

import { EventEmitter } from 'events';
import {
  BettingOdds,
  BettingDecision,
  ArbitrageOpportunity,
  LineShoppingResult,
} from '../types/betting';
import { MarketContext, BettingContext } from '../types/core';

interface PerformanceMetrics {
  totalBets: number;
  winningBets: number;
  losingBets: number;
  pushBets: number;
  totalProfit: number;
  roi: number;
  averageOdds: number;
  averageConfidence: number;
  averageStake: number;
  bestBet: {
    profit: number;
    odds: number;
    confidence: number;
    timestamp: number;
  };
  worstBet: {
    loss: number;
    odds: number;
    confidence: number;
    timestamp: number;
  };
  byBetType: Record<
    string,
    {
      count: number;
      profit: number;
      roi: number;
    }
  >;
  byMarket: Record<
    string,
    {
      count: number;
      profit: number;
      roi: number;
    }
  >;
  byTimeframe: Record<
    string,
    {
      count: number;
      profit: number;
      roi: number;
    }
  >;
}

interface ModelMetrics {
  accuracy: number;
  precision: number;
  recall: number;
  f1Score: number;
  confusionMatrix: {
    truePositives: number;
    falsePositives: number;
    trueNegatives: number;
    falseNegatives: number;
  };
  calibration: {
    expected: number[];
    actual: number[];
  };
  featureImportance: Record<string, number>;
  byConfidence: Record<
    string,
    {
      count: number;
      accuracy: number;
      profit: number;
    }
  >;
}

interface SystemMetrics {
  uptime: number;
  responseTime: {
    average: number;
    p95: number;
    p99: number;
  };
  errorRate: number;
  operationCounts: Record<string, number>;
  resourceUsage: {
    cpu: number;
    memory: number;
    network: {
      bytesIn: number;
      bytesOut: number;
    };
  };
}

export class MetricsService extends EventEmitter {
  private static instance: MetricsService;
  private performanceMetrics: PerformanceMetrics;
  private modelMetrics: ModelMetrics;
  private systemMetrics: SystemMetrics;
  private startTime: number;

  private constructor() {
    super();
    this.startTime = Date.now();
    this.initializeMetrics();
  }

  public static getInstance(): MetricsService {
    if (!MetricsService.instance) {
      MetricsService.instance = new MetricsService();
    }
    return MetricsService.instance;
  }

  private initializeMetrics(): void {
    this.performanceMetrics = {
      totalBets: 0,
      winningBets: 0,
      losingBets: 0,
      pushBets: 0,
      totalProfit: 0,
      roi: 0,
      averageOdds: 0,
      averageConfidence: 0,
      averageStake: 0,
      bestBet: {
        profit: 0,
        odds: 0,
        confidence: 0,
        timestamp: 0,
      },
      worstBet: {
        loss: 0,
        odds: 0,
        confidence: 0,
        timestamp: 0,
      },
      byBetType: {},
      byMarket: {},
      byTimeframe: {},
    };

    this.modelMetrics = {
      accuracy: 0,
      precision: 0,
      recall: 0,
      f1Score: 0,
      confusionMatrix: {
        truePositives: 0,
        falsePositives: 0,
        trueNegatives: 0,
        falseNegatives: 0,
      },
      calibration: {
        expected: [],
        actual: [],
      },
      featureImportance: {},
      byConfidence: {},
    };

    this.systemMetrics = {
      uptime: 0,
      responseTime: {
        average: 0,
        p95: 0,
        p99: 0,
      },
      errorRate: 0,
      operationCounts: {},
      resourceUsage: {
        cpu: 0,
        memory: 0,
        network: {
          bytesIn: 0,
          bytesOut: 0,
        },
      },
    };
  }

  public trackBet(
    decision: BettingDecision,
    result: 'WIN' | 'LOSS' | 'PUSH',
    profit: number
  ): void {
    this.performanceMetrics.totalBets++;
    this.performanceMetrics.totalProfit += profit;

    switch (result) {
      case 'WIN':
        this.performanceMetrics.winningBets++;
        if (profit > this.performanceMetrics.bestBet.profit) {
          this.performanceMetrics.bestBet = {
            profit,
            odds: decision.stake,
            confidence: decision.confidence,
            timestamp: Date.now(),
          };
        }
        break;
      case 'LOSS':
        this.performanceMetrics.losingBets++;
        if (profit < this.performanceMetrics.worstBet.loss) {
          this.performanceMetrics.worstBet = {
            loss: profit,
            odds: decision.stake,
            confidence: decision.confidence,
            timestamp: Date.now(),
          };
        }
        break;
      case 'PUSH':
        this.performanceMetrics.pushBets++;
        break;
    }

    // Update bet type metrics
    const betType = decision.type;
    if (!this.performanceMetrics.byBetType[betType]) {
      this.performanceMetrics.byBetType[betType] = {
        count: 0,
        profit: 0,
        roi: 0,
      };
    }
    this.performanceMetrics.byBetType[betType].count++;
    this.performanceMetrics.byBetType[betType].profit += profit;
    this.performanceMetrics.byBetType[betType].roi =
      this.performanceMetrics.byBetType[betType].profit /
      this.performanceMetrics.byBetType[betType].count;

    // Update overall metrics
    this.performanceMetrics.roi =
      this.performanceMetrics.totalProfit / this.performanceMetrics.totalBets;
    this.performanceMetrics.averageOdds =
      (this.performanceMetrics.averageOdds * (this.performanceMetrics.totalBets - 1) +
        decision.stake) /
      this.performanceMetrics.totalBets;
    this.performanceMetrics.averageConfidence =
      (this.performanceMetrics.averageConfidence * (this.performanceMetrics.totalBets - 1) +
        decision.confidence) /
      this.performanceMetrics.totalBets;

    this.emit('metricsUpdated', {
      type: 'performance',
      data: this.performanceMetrics,
    });
  }

  public trackPrediction(
    predictedValue: number,
    actualValue: number,
    confidence: number,
    features: Record<string, number>
  ): void {
    // Update confusion matrix
    const isCorrect = Math.abs(predictedValue - actualValue) < 0.1;
    if (predictedValue > 0.5) {
      if (isCorrect) {
        this.modelMetrics.confusionMatrix.truePositives++;
      } else {
        this.modelMetrics.confusionMatrix.falsePositives++;
      }
    } else {
      if (isCorrect) {
        this.modelMetrics.confusionMatrix.trueNegatives++;
      } else {
        this.modelMetrics.confusionMatrix.falseNegatives++;
      }
    }

    // Update calibration
    this.modelMetrics.calibration.expected.push(predictedValue);
    this.modelMetrics.calibration.actual.push(actualValue);

    // Update feature importance
    Object.entries(features).forEach(([feature, importance]) => {
      this.modelMetrics.featureImportance[feature] =
        (this.modelMetrics.featureImportance[feature] || 0) + importance;
    });

    // Update confidence-based metrics
    const confidenceBucket = Math.floor(confidence * 10) / 10;
    if (!this.modelMetrics.byConfidence[confidenceBucket]) {
      this.modelMetrics.byConfidence[confidenceBucket] = {
        count: 0,
        accuracy: 0,
        profit: 0,
      };
    }
    this.modelMetrics.byConfidence[confidenceBucket].count++;
    this.modelMetrics.byConfidence[confidenceBucket].accuracy =
      (this.modelMetrics.byConfidence[confidenceBucket].accuracy *
        (this.modelMetrics.byConfidence[confidenceBucket].count - 1) +
        (isCorrect ? 1 : 0)) /
      this.modelMetrics.byConfidence[confidenceBucket].count;

    // Update overall metrics
    const total =
      this.modelMetrics.confusionMatrix.truePositives +
      this.modelMetrics.confusionMatrix.falsePositives +
      this.modelMetrics.confusionMatrix.trueNegatives +
      this.modelMetrics.confusionMatrix.falseNegatives;

    this.modelMetrics.accuracy =
      (this.modelMetrics.confusionMatrix.truePositives +
        this.modelMetrics.confusionMatrix.trueNegatives) /
      total;

    this.modelMetrics.precision =
      this.modelMetrics.confusionMatrix.truePositives /
      (this.modelMetrics.confusionMatrix.truePositives +
        this.modelMetrics.confusionMatrix.falsePositives);

    this.modelMetrics.recall =
      this.modelMetrics.confusionMatrix.truePositives /
      (this.modelMetrics.confusionMatrix.truePositives +
        this.modelMetrics.confusionMatrix.falseNegatives);

    this.modelMetrics.f1Score =
      (2 * (this.modelMetrics.precision * this.modelMetrics.recall)) /
      (this.modelMetrics.precision + this.modelMetrics.recall);

    this.emit('metricsUpdated', {
      type: 'model',
      data: this.modelMetrics,
    });
  }

  public trackOperation(operation: string, duration: number, success: boolean): void {
    // Update operation counts
    this.systemMetrics.operationCounts[operation] =
      (this.systemMetrics.operationCounts[operation] || 0) + 1;

    // Update response time metrics
    const currentAvg = this.systemMetrics.responseTime.average;
    const count = this.systemMetrics.operationCounts[operation];
    this.systemMetrics.responseTime.average = (currentAvg * (count - 1) + duration) / count;

    // Update error rate
    if (!success) {
      this.systemMetrics.errorRate = (this.systemMetrics.errorRate * (count - 1) + 1) / count;
    }

    // Update uptime
    this.systemMetrics.uptime = Date.now() - this.startTime;

    this.emit('metricsUpdated', {
      type: 'system',
      data: this.systemMetrics,
    });
  }

  public getPerformanceMetrics(): PerformanceMetrics {
    return { ...this.performanceMetrics };
  }

  public getModelMetrics(): ModelMetrics {
    return { ...this.modelMetrics };
  }

  public getSystemMetrics(): SystemMetrics {
    return { ...this.systemMetrics };
  }

  public resetMetrics(): void {
    this.initializeMetrics();
    this.emit('metricsReset');
  }
}

import { BaseModel } from '../models/BaseModel';
import { ModelRegistry } from '../registry/ModelRegistry';
import { EventEmitter } from 'events';

interface EnsembleConfig {
  name: string;
  models: string[];
  weights?: { [modelName: string]: number };
  votingStrategy: 'weighted' | 'majority' | 'confidence';
  minConfidence: number;
  minModels: number;
}

interface EnsemblePrediction {
  prediction: any;
  confidence: number;
  modelContributions: {
    [modelName: string]: {
      prediction: any;
      confidence: number;
      weight: number;
    };
  };
  metadata: {
    timestamp: number;
    modelCount: number;
    votingStrategy: string;
  };
}

export class EnsembleManager extends EventEmitter {
  private static instance: EnsembleManager;
  private ensembles: Map<string, EnsembleConfig> = new Map();
  private modelRegistry: ModelRegistry;

  private constructor() {
    super();
    this.modelRegistry = ModelRegistry.getInstance();
  }

  public static getInstance(): EnsembleManager {
    if (!EnsembleManager.instance) {
      EnsembleManager.instance = new EnsembleManager();
    }
    return EnsembleManager.instance;
  }

  public async createEnsemble(config: EnsembleConfig): Promise<void> {
    // Validate models exist
    for (const modelName of config.models) {
      if (!this.modelRegistry.getModel(modelName)) {
        throw new Error(`Model ${modelName} not found in registry`);
      }
    }

    // Initialize weights if not provided
    if (!config.weights) {
      config.weights = {};
      const weight = 1 / config.models.length;
      config.models.forEach(model => {
        config.weights![model] = weight;
      });
    }

    this.ensembles.set(config.name, config);
    this.emit('ensembleCreated', { name: config.name, config });
  }

  public async getEnsemblePrediction(
    ensembleName: string,
    input: any
  ): Promise<EnsemblePrediction> {
    const ensemble = this.ensembles.get(ensembleName);
    if (!ensemble) {
      throw new Error(`Ensemble ${ensembleName} not found`);
    }

    // Get predictions from all models
    const predictions = await Promise.all(
      ensemble.models.map(async modelName => {
        const model = this.modelRegistry.getModel(modelName);
        if (!model) {
          throw new Error(`Model ${modelName} not found`);
        }
        const prediction = await model.predict(input);
        return {
          modelName,
          prediction,
          weight: ensemble.weights![modelName],
        };
      })
    );

    // Combine predictions based on voting strategy
    const combinedPrediction = this.combinePredictions(predictions, ensemble);

    // Create ensemble prediction object
    const ensemblePrediction: EnsemblePrediction = {
      prediction: combinedPrediction.prediction,
      confidence: combinedPrediction.confidence,
      modelContributions: {},
      metadata: {
        timestamp: Date.now(),
        modelCount: predictions.length,
        votingStrategy: ensemble.votingStrategy,
      },
    };

    // Add individual model contributions
    predictions.forEach(({ modelName, prediction, weight }) => {
      ensemblePrediction.modelContributions[modelName] = {
        prediction: prediction.prediction,
        confidence: prediction.confidence,
        weight,
      };
    });

    this.emit('predictionGenerated', {
      ensembleName,
      prediction: ensemblePrediction,
    });

    return ensemblePrediction;
  }

  private combinePredictions(
    predictions: Array<{
      modelName: string;
      prediction: any;
      weight: number;
    }>,
    ensemble: EnsembleConfig
  ): { prediction: any; confidence: number } {
    switch (ensemble.votingStrategy) {
      case 'weighted':
        return this.weightedVoting(predictions);
      case 'majority':
        return this.majorityVoting(predictions);
      case 'confidence':
        return this.confidenceVoting(predictions);
      default:
        throw new Error(`Unknown voting strategy: ${ensemble.votingStrategy}`);
    }
  }

  private weightedVoting(
    predictions: Array<{
      modelName: string;
      prediction: any;
      weight: number;
    }>
  ): { prediction: any; confidence: number } {
    const weightedSum = predictions.reduce(
      (sum, { prediction, weight }) => sum + prediction.prediction * weight,
      0
    );

    const confidence = predictions.reduce(
      (sum, { prediction, weight }) => sum + prediction.confidence * weight,
      0
    );

    return {
      prediction: weightedSum,
      confidence,
    };
  }

  private majorityVoting(
    predictions: Array<{
      modelName: string;
      prediction: any;
      weight: number;
    }>
  ): { prediction: any; confidence: number } {
    const votes = new Map<any, number>();
    let totalConfidence = 0;

    predictions.forEach(({ prediction }) => {
      const vote = Math.round(prediction.prediction);
      votes.set(vote, (votes.get(vote) || 0) + 1);
      totalConfidence += prediction.confidence;
    });

    let maxVotes = 0;
    let majorityPrediction = null;

    votes.forEach((count, prediction) => {
      if (count > maxVotes) {
        maxVotes = count;
        majorityPrediction = prediction;
      }
    });

    return {
      prediction: majorityPrediction,
      confidence: totalConfidence / predictions.length,
    };
  }

  private confidenceVoting(
    predictions: Array<{
      modelName: string;
      prediction: any;
      weight: number;
    }>
  ): { prediction: any; confidence: number } {
    const sortedPredictions = [...predictions].sort(
      (a, b) => b.prediction.confidence - a.prediction.confidence
    );

    return {
      prediction: sortedPredictions[0].prediction.prediction,
      confidence: sortedPredictions[0].prediction.confidence,
    };
  }

  public async updateEnsembleWeights(
    ensembleName: string,
    weights: { [modelName: string]: number }
  ): Promise<void> {
    const ensemble = this.ensembles.get(ensembleName);
    if (!ensemble) {
      throw new Error(`Ensemble ${ensembleName} not found`);
    }

    // Validate weights
    const totalWeight = Object.values(weights).reduce((sum, weight) => sum + weight, 0);
    if (Math.abs(totalWeight - 1) > 0.0001) {
      throw new Error('Weights must sum to 1');
    }

    ensemble.weights = weights;
    this.emit('weightsUpdated', { ensembleName, weights });
  }

  public getEnsembleConfig(ensembleName: string): EnsembleConfig | undefined {
    return this.ensembles.get(ensembleName);
  }

  public getAllEnsembles(): Map<string, EnsembleConfig> {
    return new Map(this.ensembles);
  }

  public async removeEnsemble(ensembleName: string): Promise<void> {
    if (this.ensembles.delete(ensembleName)) {
      this.emit('ensembleRemoved', { name: ensembleName });
    }
  }
}

