import { ModelMetrics } from '../types/ModelMetrics';
import { ModelVersion } from '../models/ModelVersion';
import { ModelMetadata } from '../models/ModelMetadata';
import * as tf from '@tensorflow/tfjs';
import * as shap from 'shap';
import { KellyCriterion } from '../strategies/KellyCriterion';
import { BestBetSelector } from '../strategies/BestBetSelector';
import { UnifiedLogger } from '../../core/UnifiedLogger';
import { UnifiedMonitor } from '../../core/UnifiedMonitor';

export class ModelEvaluator {
  private static instance: ModelEvaluator;
  private logger: UnifiedLogger;
  private monitor: UnifiedMonitor;
  private kellyCriterion: KellyCriterion;
  private bestBetSelector: BestBetSelector;

  private constructor() {
    this.logger = UnifiedLogger.getInstance();
    this.monitor = UnifiedMonitor.getInstance();
    this.kellyCriterion = new KellyCriterion();
    this.bestBetSelector = new BestBetSelector();
  }

  public static getInstance(): ModelEvaluator {
    if (!ModelEvaluator.instance) {
      ModelEvaluator.instance = new ModelEvaluator();
    }
    return ModelEvaluator.instance;
  }

  public async evaluateModel(
    model: tf.LayersModel,
    testData: tf.Tensor,
    testLabels: tf.Tensor,
    metadata: ModelMetadata
  ): Promise<ModelMetrics> {
    try {
      this.logger.info('Starting model evaluation');
      this.monitor.startTimer('model_evaluation');

      // Basic metrics
      const predictions = model.predict(testData) as tf.Tensor;
      const metrics = await this.calculateBasicMetrics(predictions, testLabels);

      // SHAP analysis
      const shapValues = await this.performShapAnalysis(model, testData);
      metrics.shapValues = shapValues;

      // Feature importance
      metrics.featureImportance = await this.calculateFeatureImportance(model, testData);

      // Prediction confidence analysis
      metrics.predictionConfidence = await this.analyzePredictionConfidence(predictions);

      // Performance metrics
      metrics.performanceMetrics = await this.measurePerformance(model, testData);

      // Drift detection
      metrics.driftMetrics = await this.detectDrift(model, testData);

      // Kelly Criterion analysis
      const kellyMetrics = await this.kellyCriterion.analyze(predictions, testLabels);
      metrics.customMetrics = {
        ...metrics.customMetrics,
        kellyFraction: kellyMetrics.fraction,
        expectedValue: kellyMetrics.expectedValue,
      };

      // Best bet selection
      const bestBets = await this.bestBetSelector.selectBets(predictions, testLabels);
      metrics.customMetrics = {
        ...metrics.customMetrics,
        bestBetAccuracy: bestBets.accuracy,
        bestBetROI: bestBets.roi,
      };

      this.monitor.endTimer('model_evaluation');
      this.logger.info('Model evaluation completed successfully');

      return metrics;
    } catch (error) {
      this.logger.error('Model evaluation failed', error);
      throw error;
    }
  }

  private async calculateBasicMetrics(
    predictions: tf.Tensor,
    labels: tf.Tensor
  ): Promise<Partial<ModelMetrics>> {
    const predArray = await predictions.array();
    const labelArray = await labels.array();

    const confusionMatrix = this.calculateConfusionMatrix(predArray, labelArray);
    const accuracy = this.calculateAccuracy(confusionMatrix);
    const precision = this.calculatePrecision(confusionMatrix);
    const recall = this.calculateRecall(confusionMatrix);
    const f1Score = this.calculateF1Score(precision, recall);
    const auc = await this.calculateAUC(predArray, labelArray);

    return {
      accuracy,
      precision,
      recall,
      f1Score,
      auc,
      confusionMatrix,
    };
  }

  private async performShapAnalysis(
    model: tf.LayersModel,
    data: tf.Tensor
  ): Promise<Record<string, number[]>> {
    const explainer = new shap.DeepExplainer(model);
    const shapValues = await explainer.explain(data);
    return this.processShapValues(shapValues);
  }

  private async calculateFeatureImportance(
    model: tf.LayersModel,
    data: tf.Tensor
  ): Promise<Record<string, number>> {
    const importance: Record<string, number> = {};
    const features = model.inputs[0].shape[1];

    for (let i = 0; i < features; i++) {
      const perturbedData = this.perturbFeature(data, i);
      const originalPred = model.predict(data) as tf.Tensor;
      const perturbedPred = model.predict(perturbedData) as tf.Tensor;

      const importanceScore = tf.mean(tf.abs(tf.sub(originalPred, perturbedPred))).arraySync();
      importance[`feature_${i}`] = importanceScore;
    }

    return importance;
  }

  private async analyzePredictionConfidence(
    predictions: tf.Tensor
  ): Promise<ModelMetrics['predictionConfidence']> {
    const predArray = await predictions.array();
    const confidences = predArray.map(p => Math.max(...p));

    return {
      mean: this.calculateMean(confidences),
      std: this.calculateStd(confidences),
      distribution: this.calculateDistribution(confidences),
    };
  }

  private async measurePerformance(
    model: tf.LayersModel,
    data: tf.Tensor
  ): Promise<ModelMetrics['performanceMetrics']> {
    const startTime = performance.now();
    const batchSize = 32;
    const numBatches = Math.ceil(data.shape[0] / batchSize);
    let totalTime = 0;

    for (let i = 0; i < numBatches; i++) {
      const batchStart = performance.now();
      const batch = data.slice([i * batchSize, 0], [batchSize, data.shape[1]]);
      await model.predict(batch);
      totalTime += performance.now() - batchStart;
    }

    const avgInferenceTime = totalTime / data.shape[0];
    const throughput = 1000 / avgInferenceTime;

    return {
      inferenceTime: avgInferenceTime,
      throughput,
      latency: avgInferenceTime,
      memoryUsage: tf.memory().numTensors,
    };
  }

  private async detectDrift(
    model: tf.LayersModel,
    data: tf.Tensor
  ): Promise<ModelMetrics['driftMetrics']> {
    const predictions = model.predict(data) as tf.Tensor;
    const predArray = await predictions.array();

    return {
      featureDrift: await this.calculateFeatureDrift(data),
      predictionDrift: this.calculatePredictionDrift(predArray),
      dataQuality: await this.assessDataQuality(data),
    };
  }

  // Helper methods
  private calculateConfusionMatrix(
    predictions: number[][],
    labels: number[][]
  ): ModelMetrics['confusionMatrix'] {
    let tp = 0,
      tn = 0,
      fp = 0,
      fn = 0;

    for (let i = 0; i < predictions.length; i++) {
      const pred = predictions[i].indexOf(Math.max(...predictions[i]));
      const label = labels[i].indexOf(Math.max(...labels[i]));

      if (pred === 1 && label === 1) tp++;
      else if (pred === 0 && label === 0) tn++;
      else if (pred === 1 && label === 0) fp++;
      else if (pred === 0 && label === 1) fn++;
    }

    return { truePositives: tp, trueNegatives: tn, falsePositives: fp, falseNegatives: fn };
  }

  private calculateAccuracy(matrix: ModelMetrics['confusionMatrix']): number {
    const total =
      matrix.truePositives + matrix.trueNegatives + matrix.falsePositives + matrix.falseNegatives;
    return (matrix.truePositives + matrix.trueNegatives) / total;
  }

  private calculatePrecision(matrix: ModelMetrics['confusionMatrix']): number {
    return matrix.truePositives / (matrix.truePositives + matrix.falsePositives);
  }

  private calculateRecall(matrix: ModelMetrics['confusionMatrix']): number {
    return matrix.truePositives / (matrix.truePositives + matrix.falseNegatives);
  }

  private calculateF1Score(precision: number, recall: number): number {
    return (2 * (precision * recall)) / (precision + recall);
  }

  private async calculateAUC(predictions: number[][], labels: number[][]): Promise<number> {
    // Implement AUC calculation using trapezoidal rule
    return 0.85; // Placeholder
  }

  private processShapValues(shapValues: any): Record<string, number[]> {
    // Process and format SHAP values
    return {};
  }

  private perturbFeature(data: tf.Tensor, featureIndex: number): tf.Tensor {
    const perturbed = data.clone();
    const noise = tf.randomNormal([data.shape[0], 1]);
    return tf.tensor2d(
      perturbed.arraySync().map((row, i) => {
        row[featureIndex] += noise.arraySync()[i][0];
        return row;
      })
    );
  }

  private calculateMean(values: number[]): number {
    return values.reduce((a, b) => a + b, 0) / values.length;
  }

  private calculateStd(values: number[]): number {
    const mean = this.calculateMean(values);
    const squareDiffs = values.map(value => Math.pow(value - mean, 2));
    return Math.sqrt(this.calculateMean(squareDiffs));
  }

  private calculateDistribution(values: number[]): number[] {
    const bins = 10;
    const min = Math.min(...values);
    const max = Math.max(...values);
    const binSize = (max - min) / bins;

    return Array(bins)
      .fill(0)
      .map((_, i) => {
        const binStart = min + i * binSize;
        const binEnd = binStart + binSize;
        return values.filter(v => v >= binStart && v < binEnd).length;
      });
  }

  private async calculateFeatureDrift(data: tf.Tensor): Promise<Record<string, number>> {
    // Implement feature drift detection
    return {};
  }

  private calculatePredictionDrift(predictions: number[][]): number {
    // Implement prediction drift detection
    return 0;
  }

  private async assessDataQuality(data: tf.Tensor): Promise<Record<string, number>> {
    // Implement data quality assessment
    return {};
  }
}

import { BaseModel } from '../models/BaseModel';
import { AdvancedEnsembleModel } from '../models/AdvancedEnsembleModel';
import { MarketIntelligenceModel } from '../models/MarketIntelligenceModel';
import { GameTheoryModel } from '../models/GameTheoryModel';
import { TemporalPatternModel } from '../models/TemporalPatternModel';
import { AlternativeDataModel } from '../models/AlternativeDataModel';
import { RealityExploitationEngine } from '../models/RealityExploitationEngine';
import { QuantumProbabilityModel } from '../models/QuantumProbabilityModel';
import { ModelConfig, AdvancedEnsembleConfig } from '../types';
import { validateModelConfig } from '../config/modelConfig';
import { UnifiedErrorHandler } from '../../core/UnifiedErrorHandler';
import { UnifiedLogger } from '../../core/UnifiedLogger';
import { UnifiedMonitor } from '../../core/UnifiedMonitor';
import {
  ModelError,
  ConfigurationError,
  TrainingError,
  PredictionError,
  PersistenceError,
} from '../../core/UnifiedError';

export class ModelFactory {
  private static instance: ModelFactory;
  private models: Map<string, BaseModel>;
  private configs: Map<string, ModelConfig | AdvancedEnsembleConfig>;
  private metrics: Map<string, any>;
  private predictionHistory: Array<{
    timestamp: string;
    modelId: string;
    input: any;
    output: any;
    confidence?: number;
  }>;
  private logger: UnifiedLogger;
  private errorHandler: UnifiedErrorHandler;
  private monitor: UnifiedMonitor;

  private constructor() {
    this.models = new Map();
    this.configs = new Map();
    this.metrics = new Map();
    this.predictionHistory = [];
    this.logger = UnifiedLogger.getInstance();
    this.errorHandler = UnifiedErrorHandler.getInstance();
    this.monitor = UnifiedMonitor.getInstance();
  }

  public static getInstance(): ModelFactory {
    if (!ModelFactory.instance) {
      ModelFactory.instance = new ModelFactory();
    }
    return ModelFactory.instance;
  }

  public createModel(config: ModelConfig | AdvancedEnsembleConfig): BaseModel {
    try {
      validateModelConfig(config);
      this.configs.set(config.name, config);

      let model: BaseModel;
      switch (config.type) {
        case 'ensemble':
          model = new AdvancedEnsembleModel(config as AdvancedEnsembleConfig);
          break;
        case 'market_intelligence':
          model = new MarketIntelligenceModel(config);
          break;
        case 'game_theory':
          model = new GameTheoryModel(config, config.name);
          break;
        case 'temporal_pattern':
          model = new TemporalPatternModel(config, config.name);
          break;
        case 'alternative_data':
          model = new AlternativeDataModel(config, config.name);
          break;
        case 'reality_exploitation':
          model = new RealityExploitationEngine(config, config.name);
          break;
        case 'quantum_probability':
          model = new QuantumProbabilityModel(config, config.name);
          break;
        default:
          throw new ConfigurationError(`Unsupported model type: ${config.type}`);
      }

      this.models.set(config.name, model);
      this.logger.info(`Model ${config.name} created successfully`);
      this.monitor.setMetric(`model_${config.name}_created`, true);
      return model;
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'ModelFactory.createModel', { config });
      throw error;
    }
  }

  public trainModel(modelId: string, data: any): Promise<void> {
    try {
      const model = this.getModel(modelId);
      if (!model) {
        throw new ModelError(`Model ${modelId} not found`);
      }

      this.logger.info(`Training model ${modelId}`);
      this.monitor.setMetric(`model_${modelId}_training_started`, true);
      return model
        .train(data)
        .then(() => {
          this.logger.info(`Model ${modelId} trained successfully`);
          this.monitor.setMetric(`model_${modelId}_training_completed`, true);
        })
        .catch(error => {
          this.errorHandler.handleError(error as Error, 'ModelFactory.trainModel', {
            modelId,
            data,
          });
          throw new TrainingError(`Failed to train model ${modelId}`, { error });
        });
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'ModelFactory.trainModel', { modelId, data });
      throw error;
    }
  }

  public predict(modelId: string, input: any): Promise<any> {
    try {
      const model = this.getModel(modelId);
      if (!model) {
        throw new ModelError(`Model ${modelId} not found`);
      }

      this.logger.info(`Making prediction with model ${modelId}`);
      this.monitor.setMetric(`model_${modelId}_prediction_started`, true);
      return model
        .predict(input)
        .then(result => {
          this.predictionHistory.push({
            timestamp: new Date().toISOString(),
            modelId,
            input,
            output: result.output,
            confidence: result.confidence,
          });
          this.logger.info(`Prediction completed for model ${modelId}`);
          this.monitor.setMetric(`model_${modelId}_prediction_completed`, true);
          return result;
        })
        .catch(error => {
          this.errorHandler.handleError(error as Error, 'ModelFactory.predict', { modelId, input });
          throw new PredictionError(`Failed to make prediction with model ${modelId}`, { error });
        });
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'ModelFactory.predict', { modelId, input });
      throw error;
    }
  }

  public getModel(modelId: string): BaseModel | undefined {
    return this.models.get(modelId);
  }

  public getModelConfig(modelId: string): ModelConfig | AdvancedEnsembleConfig | undefined {
    return this.configs.get(modelId);
  }

  public getModelMetrics(modelId: string): any {
    return this.metrics.get(modelId);
  }

  public getPredictionHistory(modelId?: string): Array<{
    timestamp: string;
    modelId: string;
    input: any;
    output: any;
    confidence?: number;
  }> {
    if (modelId) {
      return this.predictionHistory.filter(entry => entry.modelId === modelId);
    }
    return [...this.predictionHistory];
  }

  public saveModel(modelId: string, path: string): Promise<void> {
    try {
      const model = this.getModel(modelId);
      if (!model) {
        throw new ModelError(`Model ${modelId} not found`);
      }

      this.logger.info(`Saving model ${modelId} to ${path}`);
      this.monitor.setMetric(`model_${modelId}_save_started`, true);
      return model
        .save(path)
        .then(() => {
          this.logger.info(`Model ${modelId} saved successfully`);
          this.monitor.setMetric(`model_${modelId}_save_completed`, true);
        })
        .catch(error => {
          this.errorHandler.handleError(error as Error, 'ModelFactory.saveModel', {
            modelId,
            path,
          });
          throw new PersistenceError(`Failed to save model ${modelId}`, { error });
        });
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'ModelFactory.saveModel', { modelId, path });
      throw error;
    }
  }

  public loadModel(modelId: string, path: string): Promise<void> {
    try {
      const model = this.getModel(modelId);
      if (!model) {
        throw new ModelError(`Model ${modelId} not found`);
      }

      this.logger.info(`Loading model ${modelId} from ${path}`);
      this.monitor.setMetric(`model_${modelId}_load_started`, true);
      return model
        .load(path)
        .then(() => {
          this.logger.info(`Model ${modelId} loaded successfully`);
          this.monitor.setMetric(`model_${modelId}_load_completed`, true);
        })
        .catch(error => {
          this.errorHandler.handleError(error as Error, 'ModelFactory.loadModel', {
            modelId,
            path,
          });
          throw new PersistenceError(`Failed to load model ${modelId}`, { error });
        });
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'ModelFactory.loadModel', { modelId, path });
      throw error;
    }
  }

  public removeModel(modelId: string): void {
    try {
      if (!this.models.has(modelId)) {
        throw new ModelError(`Model ${modelId} not found`);
      }

      this.models.delete(modelId);
      this.configs.delete(modelId);
      this.metrics.delete(modelId);
      this.predictionHistory = this.predictionHistory.filter(entry => entry.modelId !== modelId);
      this.logger.info(`Model ${modelId} removed successfully`);
      this.monitor.setMetric(`model_${modelId}_removed`, true);
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'ModelFactory.removeModel', { modelId });
      throw error;
    }
  }

  public listModels(): string[] {
    return Array.from(this.models.keys());
  }

  public getModelInfo(modelId: string):
    | {
        config: ModelConfig | AdvancedEnsembleConfig;
        isTrained: boolean;
        lastUpdate: string;
        metrics: any;
      }
    | undefined {
    const model = this.getModel(modelId);
    const config = this.getModelConfig(modelId);
    if (!model || !config) {
      return undefined;
    }

    return {
      config,
      isTrained: model.isModelTrained(),
      lastUpdate: model.getLastUpdate(),
      metrics: this.getModelMetrics(modelId),
    };
  }

  public isModelTrained(modelId: string): boolean {
    const model = this.getModel(modelId);
    return model ? model.isModelTrained() : false;
  }
}

import { z } from 'zod';
import { UnifiedLogger } from '../../../core/UnifiedLogger';
import { UnifiedErrorHandler } from '../../../core/UnifiedErrorHandler';
import {
  HistoricalGameData,
  PlayerStats,
  TeamStats,
  VenueStats,
  OfficialStats,
} from '../../data/HistoricalDataService';

// Feature schemas
export const FeatureSchema = z.object({
  name: z.string(),
  value: z.number(),
  importance: z.number(),
  metadata: z.record(z.unknown()).optional(),
});

export const FeatureSetSchema = z.object({
  features: z.array(FeatureSchema),
  timestamp: z.string(),
  metadata: z.record(z.unknown()).optional(),
});

// Type definitions
export type Feature = z.infer<typeof FeatureSchema>;
export type FeatureSet = z.infer<typeof FeatureSetSchema>;

export interface FeatureEngineeringConfig {
  windowSizes: number[];
  smoothingFactors: number[];
  featureGroups: string[];
  importanceThreshold: number;
  validationConfig: {
    strict: boolean;
    allowPartial: boolean;
  };
}

export class AdvancedFeatureEngineeringService {
  private logger: UnifiedLogger;
  private errorHandler: UnifiedErrorHandler;
  private config: FeatureEngineeringConfig;
  private featureCache: Map<string, FeatureSet>;

  constructor(config: FeatureEngineeringConfig) {
    this.logger = UnifiedLogger.getInstance();
    this.errorHandler = UnifiedErrorHandler.getInstance();
    this.config = config;
    this.featureCache = new Map();
  }

  async initialize(): Promise<void> {
    try {
      this.logger.info('AdvancedFeatureEngineeringService initialized successfully');
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'AdvancedFeatureEngineeringService.initialize');
      throw error;
    }
  }

  async generateFeatures(
    data: {
      gameData?: HistoricalGameData[];
      playerStats?: PlayerStats[];
      teamStats?: TeamStats[];
      venueStats?: VenueStats[];
      officialStats?: OfficialStats[];
    },
    options: {
      includeRolling?: boolean;
      includeExponential?: boolean;
      includeInteraction?: boolean;
      includeAdvanced?: boolean;
    } = {}
  ): Promise<FeatureSet> {
    try {
      const features: Feature[] = [];

      if (data.gameData) {
        features.push(...(await this.generateGameFeatures(data.gameData, options)));
      }

      if (data.playerStats) {
        features.push(...(await this.generatePlayerFeatures(data.playerStats, options)));
      }

      if (data.teamStats) {
        features.push(...(await this.generateTeamFeatures(data.teamStats, options)));
      }

      if (data.venueStats) {
        features.push(...(await this.generateVenueFeatures(data.venueStats, options)));
      }

      if (data.officialStats) {
        features.push(...(await this.generateOfficialFeatures(data.officialStats, options)));
      }

      // Filter features by importance
      const filteredFeatures = features.filter(
