import { ModelFactory } from '../factory/ModelFactory';
import { ModelConfig } from '../models/BaseModel';
import { AdvancedEnsembleConfig } from '../models/AdvancedEnsembleModel';
import {
  createModelConfig,
  validateModelConfig,
  validateRegularModelConfig,
} from '../config/modelConfig';
import { ModelRegistry, ModelType } from '../registry/ModelRegistry';

export class ModelManager {
  private static instance: ModelManager;
  private modelFactory: ModelFactory;
  private modelRegistry: ModelRegistry;
  private activeModels: Set<string> = new Set();
  private modelMetrics: Map<string, any> = new Map();

  private constructor() {
    this.modelFactory = ModelFactory.getInstance();
    this.modelRegistry = ModelRegistry.getInstance();
  }

  static getInstance(): ModelManager {
    if (!ModelManager.instance) {
      ModelManager.instance = new ModelManager();
    }
    return ModelManager.instance;
  }

  async initializeModel(
    modelId: string,
    type: ModelType,
    config?: Partial<ModelConfig | AdvancedEnsembleConfig>
  ): Promise<void> {
    try {
      // Get default configuration from registry
      const defaultConfig = this.modelRegistry.getDefaultConfig(type);

      // Merge with provided config if any
      const finalConfig = config ? { ...defaultConfig, ...config } : defaultConfig;

      // Validate configuration based on model type
      if (type === 'ensemble') {
        validateModelConfig(finalConfig as AdvancedEnsembleConfig);
      } else {
        validateRegularModelConfig(finalConfig as ModelConfig);
      }

      // Create model using factory
      await this.modelFactory.createModel(finalConfig, modelId);
      this.activeModels.add(modelId);

      console.log(`Model ${modelId} initialized successfully`);
    } catch (error) {
      console.error(`Failed to initialize model ${modelId}:`, error);
      throw error;
    }
  }

  async trainModel(modelId: string, data: any): Promise<void> {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    try {
      await this.modelFactory.trainModel(modelId, data);
      console.log(`Model ${modelId} trained successfully`);
    } catch (error) {
      console.error(`Failed to train model ${modelId}:`, error);
      throw error;
    }
  }

  async predict(modelId: string, input: any): Promise<any> {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    try {
      return await this.modelFactory.predict(modelId, input);
    } catch (error) {
      console.error(`Failed to get prediction from model ${modelId}:`, error);
      throw error;
    }
  }

  async evaluateModel(modelId: string, data: any): Promise<any> {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    try {
      const metrics = await this.modelFactory.evaluateModel(modelId, data);
      this.modelMetrics.set(modelId, metrics);
      return metrics;
    } catch (error) {
      console.error(`Failed to evaluate model ${modelId}:`, error);
      throw error;
    }
  }

  async updateModel(modelId: string, update: any): Promise<void> {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    try {
      await this.modelFactory.updateModel(modelId, update);
      console.log(`Model ${modelId} updated successfully`);
    } catch (error) {
      console.error(`Failed to update model ${modelId}:`, error);
      throw error;
    }
  }

  async saveModel(modelId: string, path: string): Promise<void> {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    try {
      await this.modelFactory.saveModel(modelId, path);
      console.log(`Model ${modelId} saved successfully to ${path}`);
    } catch (error) {
      console.error(`Failed to save model ${modelId}:`, error);
      throw error;
    }
  }

  async loadModel(modelId: string, path: string): Promise<void> {
    try {
      await this.modelFactory.loadModel(modelId, path);
      this.activeModels.add(modelId);
      console.log(`Model ${modelId} loaded successfully from ${path}`);
    } catch (error) {
      console.error(`Failed to load model ${modelId}:`, error);
      throw error;
    }
  }

  deactivateModel(modelId: string): void {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    this.activeModels.delete(modelId);
    this.modelMetrics.delete(modelId);
    console.log(`Model ${modelId} deactivated`);
  }

  getActiveModels(): string[] {
    return Array.from(this.activeModels);
  }

  getModelMetrics(modelId: string): any {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    return this.modelMetrics.get(modelId);
  }

  isModelActive(modelId: string): boolean {
    return this.activeModels.has(modelId);
  }

  getModelInfo(modelId: string): any {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    return this.modelFactory.getModelInfo(modelId);
  }

  isModelTrained(modelId: string): boolean {
    if (!this.activeModels.has(modelId)) {
      throw new Error(`Model ${modelId} is not active`);
    }

    return this.modelFactory.isModelTrained(modelId);
  }

  getAvailableModelTypes(): ModelType[] {
    return this.modelRegistry.getAvailableModelTypes();
  }

  getModelTypeInfo(type: ModelType): any {
    return this.modelRegistry.getModelTypeInfo(type);
  }
}

/**
 * Advanced ensemble model that combines multiple specialized models for improved predictions.
 */

import { BaseModel } from './BaseModel';
import { AdvancedEnsembleConfig, ModelMetrics, ModelPrediction } from '../types';
import { UnifiedLogger } from '../../core/UnifiedLogger';
import { UnifiedErrorHandler } from '../../core/UnifiedErrorHandler';
import { MarketIntelligenceModel } from './MarketIntelligenceModel';

export class AdvancedEnsembleModel extends BaseModel {
  private models: Map<string, BaseModel> = new Map();
  private weights: Map<string, number> = new Map();
  protected readonly logger: UnifiedLogger;
  protected readonly errorHandler: UnifiedErrorHandler;

  constructor(config: AdvancedEnsembleConfig) {
    super(config);
    this.logger = UnifiedLogger.getInstance();
    this.errorHandler = UnifiedErrorHandler.getInstance();
    this.initializeModels(config);
  }

  private initializeModels(config: AdvancedEnsembleConfig): void {
    try {
      config.models.forEach(modelConfig => {
        const model = this.createModel(modelConfig);
        this.models.set(modelConfig.name, model);
        this.weights.set(modelConfig.name, modelConfig.weight);
      });
      this.logger.info(`Initialized ensemble model with ${this.models.size} models`);
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'AdvancedEnsembleModel.initializeModels', {
        config,
      });
      throw error;
    }
  }

  private createModel(config: any): BaseModel {
    // For now, we'll use MarketIntelligenceModel as a concrete implementation
    // In a real implementation, this would create different model types based on config.type
    return new MarketIntelligenceModel(config);
  }

  async predict(data: any): Promise<any> {
    try {
      const predictions: Array<{ model: string; prediction: any; confidence: number }> = [];

      for (const [modelName, model] of this.models) {
        const prediction = await model.predict(data);
        predictions.push({
          model: modelName,
          prediction: prediction.output,
          confidence: prediction.confidence || 1.0,
        });
      }

      const weightedPrediction = this.combinePredictions(predictions);
      return this.createPrediction(weightedPrediction, this.calculateConfidence(predictions));
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'AdvancedEnsembleModel.predict', { data });
      throw error;
    }
  }

  private combinePredictions(
    predictions: Array<{ model: string; prediction: any; confidence: number }>
  ): any {
    const totalWeight = predictions.reduce(
      (sum, pred) => sum + (this.weights.get(pred.model) || 0),
      0
    );
    return predictions.reduce((sum, pred) => {
      const weight = (this.weights.get(pred.model) || 0) / totalWeight;
      return sum + pred.prediction * weight;
    }, 0);
  }

  private calculateConfidence(
    predictions: Array<{ model: string; prediction: any; confidence: number }>
  ): number {
    const totalWeight = predictions.reduce(
      (sum, pred) => sum + (this.weights.get(pred.model) || 0),
      0
    );
    return predictions.reduce((sum, pred) => {
      const weight = (this.weights.get(pred.model) || 0) / totalWeight;
      return sum + pred.confidence * weight;
    }, 0);
  }

  async train(data: any): Promise<void> {
    try {
      for (const [modelName, model] of this.models) {
        await model.train(data);
        this.logger.info(`Trained model: ${modelName}`);
      }
      this.isTrained = true;
      this.lastUpdate = new Date().toISOString();
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'AdvancedEnsembleModel.train', { data });
      throw error;
    }
  }

  async evaluate(data: any): Promise<ModelMetrics> {
    try {
      const metrics: ModelMetrics = {};
      let totalWeight = 0;

      for (const [modelName, model] of this.models) {
        const modelMetrics = await model.evaluate(data);
        const weight = this.weights.get(modelName) || 0;
        totalWeight += weight;

        // Combine metrics with weights
        Object.entries(modelMetrics).forEach(([key, value]) => {
          if (value !== undefined) {
            metrics[key as keyof ModelMetrics] =
              (metrics[key as keyof ModelMetrics] || 0) + value * weight;
          }
        });
      }

      // Normalize metrics by total weight
      Object.keys(metrics).forEach(key => {
        if (metrics[key as keyof ModelMetrics] !== undefined) {
          metrics[key as keyof ModelMetrics] =
            (metrics[key as keyof ModelMetrics] as number) / totalWeight;
        }
      });

      return metrics;
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'AdvancedEnsembleModel.evaluate', { data });
      throw error;
    }
  }

  async save(path: string): Promise<void> {
    try {
      for (const [modelName, model] of this.models) {
        await model.save(`${path}/${modelName}`);
      }
      this.logger.info(`Saved ensemble model to: ${path}`);
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'AdvancedEnsembleModel.save', { path });
      throw error;
    }
  }

  async load(path: string): Promise<void> {
    try {
      for (const [modelName, model] of this.models) {
        await model.load(`${path}/${modelName}`);
      }
      this.logger.info(`Loaded ensemble model from: ${path}`);
    } catch (error) {
      this.errorHandler.handleError(error as Error, 'AdvancedEnsembleModel.load', { path });
      throw error;
    }
  }
}

