  private microTrendWindow: number = 5; // Last 5 games
  private macroTrendWindow: number = 20; // Last 20 games
  private circadianThreshold: number = 0.7;
  private cyclicalThreshold: number = 0.6;

  constructor(config: ModelConfig) {
