  async save(path: string): Promise<void> {
    // Implement save logic
  }

  async load(path: string): Promise<void> {
    // Implement load logic
    this.isTrained = true;
  }

  private analyzeMicroTrends(features: Record<string, any>): number {
    const recentGames = features.recentGames || [];
    if (recentGames.length < this.microTrendWindow) {
      return 0.5; // Neutral if not enough data
    }

    // Calculate trend direction and strength
    const recentValues = recentGames.slice(-this.microTrendWindow);
    const trend = this.calculateTrend(recentValues);
    const volatility = this.calculateVolatility(recentValues);

    // Combine trend and volatility into a score
    return Math.min(1, Math.max(0, (trend + (1 - volatility)) / 2));
  }

  private analyzeMacroTrends(features: Record<string, any>): number {
    const historicalGames = features.historicalGames || [];
    if (historicalGames.length < this.macroTrendWindow) {
      return 0.5; // Neutral if not enough data
    }

    // Calculate long-term trend
    const longTermValues = historicalGames.slice(-this.macroTrendWindow);
    const trend = this.calculateTrend(longTermValues);
    const momentum = this.calculateMomentum(longTermValues);

    // Combine trend and momentum into a score
    return Math.min(1, Math.max(0, (trend + momentum) / 2));
  }

  private analyzeCyclicalPatterns(features: Record<string, any>): number {
    const historicalGames = features.historicalGames || [];
    if (historicalGames.length < 10) {
      return 0.5; // Neutral if not enough data
    }

    // Detect cyclical patterns
    const seasonality = this.detectSeasonality(historicalGames);
    const periodicity = this.detectPeriodicity(historicalGames);
    const phase = this.calculatePhase(historicalGames);

    // Combine cyclical indicators into a score
    return Math.min(1, Math.max(0, (seasonality + periodicity + phase) / 3));
  }

  private analyzeCircadianFactors(features: Record<string, any>): number {
    const gameTime = features.gameTime || 0;
    const timeZone = features.timeZone || 0;
    const travelDistance = features.travelDistance || 0;
    const restDays = features.restDays || 0;

    // Calculate circadian impact
    const timeZoneImpact = this.calculateTimeZoneImpact(gameTime, timeZone);
    const travelImpact = this.calculateTravelImpact(travelDistance, restDays);
    const restImpact = this.calculateRestImpact(restDays);

    // Combine circadian factors into a score
    return Math.min(1, Math.max(0, (timeZoneImpact + travelImpact + restImpact) / 3));
  }

  private calculateTrend(values: number[]): number {
    if (values.length < 2) return 0;

    const xMean = (values.length - 1) / 2;
    const yMean = values.reduce((a: number, b: number) => a + b, 0) / values.length;

    let numerator = 0;
    let denominator = 0;

    for (let i = 0; i < values.length; i++) {
      numerator += (i - xMean) * (values[i] - yMean);
      denominator += Math.pow(i - xMean, 2);
    }

    const slope = numerator / denominator;
    return (slope + 1) / 2; // Normalize to [0,1]
  }

  private calculateVolatility(values: number[]): number {
    if (values.length < 2) return 0;

    const mean = values.reduce((a: number, b: number) => a + b, 0) / values.length;
    const variance =
      values.reduce((a: number, b: number) => a + Math.pow(b - mean, 2), 0) / values.length;

    return Math.min(1, Math.sqrt(variance));
  }

  private calculateMomentum(values: number[]): number {
    if (values.length < 2) return 0;

    const recentValues = values.slice(-3);
    const oldValues = values.slice(-6, -3);

    const recentAvg = recentValues.reduce((a: number, b: number) => a + b, 0) / recentValues.length;
    const oldAvg = oldValues.reduce((a: number, b: number) => a + b, 0) / oldValues.length;

    return (recentAvg - oldAvg + 1) / 2; // Normalize to [0,1]
  }

  private detectSeasonality(values: number[]): number {
    // Simple seasonality detection using autocorrelation
    const lag = 5; // Look for patterns every 5 games
    if (values.length < lag * 2) return 0.5;

    const correlations = [];
    for (let i = 0; i < lag; i++) {
      const correlation = this.calculateCorrelation(values.slice(0, -i - 1), values.slice(i + 1));
      correlations.push(correlation);
    }

    return Math.max(...correlations);
  }

  private detectPeriodicity(values: number[]): number {
    // Simple periodicity detection using FFT
    if (values.length < 10) return 0.5;

    const frequencies = this.calculateFrequencies(values);
    const dominantFrequency = Math.max(...frequencies);

    return Math.min(1, dominantFrequency);
  }

  private calculatePhase(values: number[]): number {
    // Calculate phase of cyclical pattern
    if (values.length < 10) return 0.5;

    const frequencies = this.calculateFrequencies(values);
    const phase = Math.atan2(frequencies[1], frequencies[0]);

    return (phase + Math.PI) / (2 * Math.PI); // Normalize to [0,1]
  }

  private calculateTimeZoneImpact(gameTime: number, timeZone: number): number {
    // Calculate impact of time zone difference
    const timeZoneDiff = Math.abs(timeZone);
    const gameTimeFactor = Math.sin((gameTime / 24) * Math.PI);

    return Math.min(1, timeZoneDiff * 0.1 + gameTimeFactor * 0.9);
  }

  private calculateTravelImpact(travelDistance: number, restDays: number): number {
    // Calculate impact of travel
    const distanceFactor = Math.min(1, travelDistance / 5000);
    const restFactor = Math.min(1, restDays / 3);

    return Math.min(1, distanceFactor * 0.7 + restFactor * 0.3);
  }

  private calculateRestImpact(restDays: number): number {
    // Calculate impact of rest days
    return Math.min(1, restDays / 5);
  }

  private calculateCorrelation(x: number[], y: number[]): number {
    if (x.length !== y.length || x.length < 2) return 0;

    const xMean = x.reduce((a, b) => a + b, 0) / x.length;
    const yMean = y.reduce((a, b) => a + b, 0) / y.length;

    let numerator = 0;
    let xDenominator = 0;
    let yDenominator = 0;

    for (let i = 0; i < x.length; i++) {
      const xDiff = x[i] - xMean;
      const yDiff = y[i] - yMean;
      numerator += xDiff * yDiff;
      xDenominator += xDiff * xDiff;
      yDenominator += yDiff * yDiff;
    }

    return numerator / Math.sqrt(xDenominator * yDenominator);
  }

  private calculateFrequencies(values: number[]): number[] {
    // Simple FFT implementation
    const n = values.length;
    const frequencies = new Array(n).fill(0);

    for (let k = 0; k < n; k++) {
      for (let j = 0; j < n; j++) {
        const angle = (2 * Math.PI * k * j) / n;
        frequencies[k] += values[j] * (Math.cos(angle) - Math.sin(angle));
      }
    }

    return frequencies;
  }
}

import {
  OptimizationStrategy,
  OptimizationConfig,
  OptimizationResult,
} from './OptimizationStrategy';
import { GaussianProcess } from '../models/GaussianProcess';

export class BayesianOptimization extends OptimizationStrategy {
  private gp: GaussianProcess;
  private observedPoints: number[][] = [];
  private observedValues: number[] = [];
  private acquisitionFunction: (mean: number, std: number) => number;

  constructor(config: OptimizationConfig) {
    super(config);
    if (config.type !== 'bayesian') {
      throw new Error('BayesianOptimization requires bayesian optimization type');
    }

    // Initialize Gaussian Process
    this.gp = new GaussianProcess({
      kernel: config.parameters.kernel!,
      noise: 1e-6,
    });

    // Set up acquisition function
    this.acquisitionFunction = this.getAcquisitionFunction(config.parameters.acquisitionFunction!);
  }

  public async optimize(): Promise<OptimizationResult> {
    const startTime = Date.now();
    this.initializeRandomPoints();

    const maxIterations = this.config.parameters.generations || 100;
    for (let iteration = 0; iteration < maxIterations; iteration++) {
      this.currentIteration = iteration;

      // Update Gaussian Process
      this.gp.fit(this.observedPoints, this.observedValues);

      // Find next point to evaluate
      const nextPoint = this.findNextPoint();

      // Evaluate the point
      if (this.checkConstraints(nextPoint)) {
        const value = await this.evaluateObjective(nextPoint);

        // Update observed points and values
        this.observedPoints.push(nextPoint);
        this.observedValues.push(value);

        // Update best solution if needed
        if (value < this.bestValue) {
          this.updateBest(nextPoint, value);
        }
      }

      // Check for convergence
      if (this.checkConvergence()) {
        break;
      }

      this.emit('iterationComplete', {
        iteration,
        bestValue: this.bestValue,
        bestParameters: this.bestParameters,
      });
    }

    return this.getResult();
  }

  private initializeRandomPoints(): void {
    const dimension = this.getDimension();
    const numInitialPoints = Math.min(10, this.config.parameters.populationSize || 10);

    for (let i = 0; i < numInitialPoints; i++) {
      const point = this.generateRandomPoint(dimension);
      if (this.checkConstraints(point)) {
        this.evaluateObjective(point).then(value => {
          this.observedPoints.push(point);
          this.observedValues.push(value);
          if (value < this.bestValue) {
            this.updateBest(point, value);
          }
        });
      }
    }
  }

  private getDimension(): number {
    if (this.config.constraints?.min) {
      return this.config.constraints.min.length;
    }
    if (this.config.constraints?.max) {
      return this.config.constraints.max.length;
    }
    throw new Error('Cannot determine parameter dimension from constraints');
  }

  private generateRandomPoint(dimension: number): number[] {
    const point = Array(dimension).fill(0);
    const { min, max } = this.config.constraints!;

    for (let i = 0; i < dimension; i++) {
      const minVal = min?.[i] ?? -10;
      const maxVal = max?.[i] ?? 10;
      point[i] = minVal + Math.random() * (maxVal - minVal);
    }

    return point;
  }

  private getAcquisitionFunction(type: 'ucb' | 'ei' | 'pi'): (mean: number, std: number) => number {
    switch (type) {
      case 'ucb':
        return (mean: number, std: number) => mean - 2 * std; // Lower confidence bound
      case 'ei':
        return (mean: number, std: number) => {
          const bestValue = Math.min(...this.observedValues);
          const z = (bestValue - mean) / std;
          return (bestValue - mean) * this.normalCDF(z) + std * this.normalPDF(z);
        };
      case 'pi':
        return (mean: number, std: number) => {
          const bestValue = Math.min(...this.observedValues);
          const z = (bestValue - mean) / std;
          return this.normalCDF(z);
        };
      default:
        throw new Error(`Unknown acquisition function type: ${type}`);
    }
  }

  private findNextPoint(): number[] {
    const dimension = this.getDimension();
    const numCandidates = 1000;
    let bestPoint: number[] = [];
    let bestAcquisition = -Infinity;

    // Generate random candidates
    for (let i = 0; i < numCandidates; i++) {
      const candidate = this.generateRandomPoint(dimension);
      if (this.checkConstraints(candidate)) {
        const [mean, std] = this.gp.predict(candidate);
        const acquisition = this.acquisitionFunction(mean, std);

        if (acquisition > bestAcquisition) {
          bestAcquisition = acquisition;
          bestPoint = candidate;
        }
      }
    }

    return bestPoint;
  }

  private normalCDF(x: number): number {
    return 0.5 * (1 + Math.erf(x / Math.sqrt(2)));
  }

  private normalPDF(x: number): number {
    return Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);
  }

  protected checkConvergence(): boolean {
    if (this.history.length < 10) {
      return false;
    }

    // Check if the improvement in the last few iterations is small
    const recentHistory = this.history.slice(-10);
    const valueConvergence = super.checkConvergence();

    // Check if the uncertainty in the GP is small
    const lastPoint = this.observedPoints[this.observedPoints.length - 1];
    const [_, std] = this.gp.predict(lastPoint);
    const uncertaintyConvergence = std < 1e-3;

    return valueConvergence || uncertaintyConvergence;
  }
}

import {
  OptimizationStrategy,
  OptimizationConfig,
  OptimizationResult,
} from './OptimizationStrategy';

export class GeneticAlgorithm extends OptimizationStrategy {
  private population: number[][] = [];
  private fitness: number[] = [];
  private velocities: number[][] = [];

  constructor(config: OptimizationConfig) {
    super(config);
    if (config.type !== 'genetic') {
      throw new Error('GeneticAlgorithm requires genetic optimization type');
    }
  }

  public async optimize(): Promise<OptimizationResult> {
    const startTime = Date.now();
    this.initializePopulation();

    for (let generation = 0; generation < this.config.parameters.generations!; generation++) {
      this.currentIteration = generation;

      // Evaluate fitness for all individuals
      await this.evaluatePopulation();

      // Select parents
      const parents = this.selectParents();

      // Create new population through crossover and mutation
      this.population = await this.createNewPopulation(parents);

      // Check for convergence
      if (this.checkConvergence()) {
        break;
      }

      this.emit('generationComplete', {
        generation,
        bestValue: this.bestValue,
        bestParameters: this.bestParameters,
      });
    }

    return this.getResult();
  }

  private initializePopulation(): void {
    const { populationSize } = this.config.parameters;
    const dimension = this.getDimension();

    this.population = Array(populationSize)
      .fill(null)
      .map(() => this.generateRandomIndividual(dimension));

    this.velocities = Array(populationSize)
      .fill(null)
      .map(() => Array(dimension).fill(0));
  }

  private getDimension(): number {
    if (this.config.constraints?.min) {
      return this.config.constraints.min.length;
    }
    if (this.config.constraints?.max) {
      return this.config.constraints.max.length;
    }
    throw new Error('Cannot determine parameter dimension from constraints');
  }

  private generateRandomIndividual(dimension: number): number[] {
    const individual = Array(dimension).fill(0);
    const { min, max } = this.config.constraints!;

    for (let i = 0; i < dimension; i++) {
      const minVal = min?.[i] ?? -10;
      const maxVal = max?.[i] ?? 10;
      individual[i] = minVal + Math.random() * (maxVal - minVal);
    }

    return individual;
  }

  private async evaluatePopulation(): Promise<void> {
    this.fitness = await Promise.all(
      this.population.map(async individual => {
        if (!this.checkConstraints(individual)) {
          return Infinity;
        }
        return await this.evaluateObjective(individual);
      })
    );

    // Update best solution
    const bestIndex = this.fitness.indexOf(Math.min(...this.fitness));
    if (this.fitness[bestIndex] < this.bestValue) {
      this.updateBest(this.population[bestIndex], this.fitness[bestIndex]);
    }
  }

  private selectParents(): number[][] {
    const { populationSize } = this.config.parameters;
    const parents: number[][] = [];

    // Tournament selection
    for (let i = 0; i < populationSize; i++) {
      const tournamentSize = 3;
      const tournament = Array(tournamentSize)
        .fill(null)
        .map(() => Math.floor(Math.random() * populationSize));

      const winner = tournament.reduce((best, current) =>
        this.fitness[current] < this.fitness[best] ? current : best
      );

      parents.push([...this.population[winner]]);
    }

    return parents;
  }

  private async createNewPopulation(parents: number[][]): Promise<number[][]> {
    const { populationSize, crossoverRate, mutationRate } = this.config.parameters;
    const newPopulation: number[][] = [];

    // Elitism: Keep the best individual
    const bestIndex = this.fitness.indexOf(Math.min(...this.fitness));
    newPopulation.push([...this.population[bestIndex]]);

    // Create rest of the population
    while (newPopulation.length < populationSize) {
      // Select two parents
      const parent1 = parents[Math.floor(Math.random() * parents.length)];
      const parent2 = parents[Math.floor(Math.random() * parents.length)];

      // Crossover
      let child1: number[], child2: number[];
      if (Math.random() < crossoverRate!) {
        [child1, child2] = this.crossover(parent1, parent2);
      } else {
        child1 = [...parent1];
        child2 = [...parent2];
      }

      // Mutation
      if (Math.random() < mutationRate!) {
        this.mutate(child1);
      }
      if (Math.random() < mutationRate!) {
        this.mutate(child2);
      }

      newPopulation.push(child1);
      if (newPopulation.length < populationSize) {
        newPopulation.push(child2);
      }
    }

    return newPopulation;
  }

  private crossover(parent1: number[], parent2: number[]): [number[], number[]] {
    const dimension = parent1.length;
    const crossoverPoint = Math.floor(Math.random() * dimension);

    const child1 = [...parent1.slice(0, crossoverPoint), ...parent2.slice(crossoverPoint)];

    const child2 = [...parent2.slice(0, crossoverPoint), ...parent1.slice(crossoverPoint)];

    return [child1, child2];
  }

  private mutate(individual: number[]): void {
    const { min, max } = this.config.constraints!;
    const dimension = individual.length;

    for (let i = 0; i < dimension; i++) {
      if (Math.random() < 0.1) {
        // 10% chance of mutation per gene
        const minVal = min?.[i] ?? -10;
        const maxVal = max?.[i] ?? 10;
        individual[i] = minVal + Math.random() * (maxVal - minVal);
      }
    }
  }
}

import {
  OptimizationStrategy,
  OptimizationConfig,
  OptimizationResult,
} from './OptimizationStrategy';

export class ParticleSwarm extends OptimizationStrategy {
  private particles: number[][] = [];
  private velocities: number[][] = [];
  private personalBests: number[][] = [];
  private personalBestValues: number[] = [];
  private globalBest: number[] = [];
  private globalBestValue: number = Infinity;

  constructor(config: OptimizationConfig) {
    super(config);
    if (config.type !== 'particleSwarm') {
      throw new Error('ParticleSwarm requires particleSwarm optimization type');
    }
  }

  public async optimize(): Promise<OptimizationResult> {
    const startTime = Date.now();
    this.initializeSwarm();

    const maxIterations = this.config.parameters.generations || 100;
    for (let iteration = 0; iteration < maxIterations; iteration++) {
      this.currentIteration = iteration;

      // Update particles
      await this.updateParticles();

      // Check for convergence
      if (this.checkConvergence()) {
        break;
      }

      this.emit('iterationComplete', {
        iteration,
        bestValue: this.bestValue,
        bestParameters: this.bestParameters,
      });
    }

    return this.getResult();
  }

  private initializeSwarm(): void {
    const { populationSize } = this.config.parameters;
    const dimension = this.getDimension();

    // Initialize particles
    this.particles = Array(populationSize)
      .fill(null)
      .map(() => this.generateRandomParticle(dimension));

    // Initialize velocities
    this.velocities = Array(populationSize)
      .fill(null)
      .map(() => Array(dimension).fill(0));

    // Initialize personal bests
    this.personalBests = this.particles.map(p => [...p]);
    this.personalBestValues = Array(populationSize).fill(Infinity);

    // Initialize global best
    this.globalBest = [...this.particles[0]];
    this.globalBestValue = Infinity;
  }

  private getDimension(): number {
    if (this.config.constraints?.min) {
      return this.config.constraints.min.length;
    }
    if (this.config.constraints?.max) {
      return this.config.constraints.max.length;
    }
    throw new Error('Cannot determine parameter dimension from constraints');
  }

  private generateRandomParticle(dimension: number): number[] {
    const particle = Array(dimension).fill(0);
    const { min, max } = this.config.constraints!;

    for (let i = 0; i < dimension; i++) {
      const minVal = min?.[i] ?? -10;
      const maxVal = max?.[i] ?? 10;
      particle[i] = minVal + Math.random() * (maxVal - minVal);
    }

    return particle;
  }

  private async updateParticles(): Promise<void> {
    const { populationSize } = this.config.parameters;
    const { inertiaWeight, cognitiveWeight, socialWeight } = this.config.parameters;

    for (let i = 0; i < populationSize; i++) {
      // Update velocity
      for (let j = 0; j < this.particles[i].length; j++) {
        const r1 = Math.random();
        const r2 = Math.random();

        this.velocities[i][j] =
          inertiaWeight! * this.velocities[i][j] +
          cognitiveWeight! * r1 * (this.personalBests[i][j] - this.particles[i][j]) +
          socialWeight! * r2 * (this.globalBest[j] - this.particles[i][j]);
      }

      // Update position
      for (let j = 0; j < this.particles[i].length; j++) {
        this.particles[i][j] += this.velocities[i][j];

        // Apply bounds
        const { min, max } = this.config.constraints!;
        if (min) {
          this.particles[i][j] = Math.max(this.particles[i][j], min[j]);
        }
        if (max) {
          this.particles[i][j] = Math.min(this.particles[i][j], max[j]);
        }
      }

      // Evaluate new position
      if (this.checkConstraints(this.particles[i])) {
        const value = await this.evaluateObjective(this.particles[i]);

        // Update personal best
        if (value < this.personalBestValues[i]) {
          this.personalBestValues[i] = value;
          this.personalBests[i] = [...this.particles[i]];

          // Update global best
          if (value < this.globalBestValue) {
            this.globalBestValue = value;
            this.globalBest = [...this.particles[i]];
            this.updateBest(this.particles[i], value);
          }
        }
      }
    }
  }

  protected checkConvergence(): boolean {
    if (this.history.length < 10) {
      return false;
    }

    // Check if particles have converged to a small region
    const recentHistory = this.history.slice(-10);
    const positionVariances = this.calculatePositionVariances();

    const avgVariance =
      positionVariances.reduce((sum, variance) => sum + variance, 0) / positionVariances.length;
    const valueConvergence = super.checkConvergence();

    return avgVariance < 1e-6 || valueConvergence;
  }

  private calculatePositionVariances(): number[] {
    const dimension = this.particles[0].length;
    const variances: number[] = [];

    for (let j = 0; j < dimension; j++) {
      const positions = this.particles.map(p => p[j]);
      const mean = positions.reduce((sum, pos) => sum + pos, 0) / positions.length;
      const variance =
        positions.reduce((sum, pos) => sum + Math.pow(pos - mean, 2), 0) / positions.length;
      variances.push(variance);
    }

    return variances;
  }
}

import {
  OptimizationStrategy,
  OptimizationConfig,
  OptimizationResult,
} from './OptimizationStrategy';

export class SimulatedAnnealing extends OptimizationStrategy {
  private currentSolution: number[] = [];
  private currentValue: number = Infinity;
  private temperature: number;

  constructor(config: OptimizationConfig) {
    super(config);
    if (config.type !== 'simulatedAnnealing') {
      throw new Error('SimulatedAnnealing requires simulatedAnnealing optimization type');
    }
    this.temperature = config.parameters.temperature!;
  }

  public async optimize(): Promise<OptimizationResult> {
    const startTime = Date.now();
    this.initializeSolution();

    const maxIterations = this.config.parameters.generations || 1000;
    const coolingRate = this.config.parameters.coolingRate!;

    for (let iteration = 0; iteration < maxIterations; iteration++) {
      this.currentIteration = iteration;

      // Generate and evaluate neighbor
      const neighbor = this.generateNeighbor();
      if (this.checkConstraints(neighbor)) {
        const neighborValue = await this.evaluateObjective(neighbor);

        // Accept or reject neighbor
        if (this.acceptNeighbor(neighborValue)) {
          this.currentSolution = neighbor;
          this.currentValue = neighborValue;

          // Update best solution if needed
          if (neighborValue < this.bestValue) {
            this.updateBest(neighbor, neighborValue);
          }
        }
      }

      // Cool down
      this.temperature *= coolingRate;

      // Check for convergence
      if (this.checkConvergence()) {
        break;
      }

      this.emit('iterationComplete', {
        iteration,
        temperature: this.temperature,
        currentValue: this.currentValue,
        bestValue: this.bestValue,
      });
    }

    return this.getResult();
  }

  private initializeSolution(): void {
    const dimension = this.getDimension();
    this.currentSolution = this.generateRandomSolution(dimension);

    if (this.checkConstraints(this.currentSolution)) {
      this.evaluateObjective(this.currentSolution).then(value => {
        this.currentValue = value;
        this.updateBest(this.currentSolution, value);
      });
    }
  }

  private getDimension(): number {
    if (this.config.constraints?.min) {
      return this.config.constraints.min.length;
    }
    if (this.config.constraints?.max) {
      return this.config.constraints.max.length;
    }
    throw new Error('Cannot determine parameter dimension from constraints');
  }

  private generateRandomSolution(dimension: number): number[] {
    const solution = Array(dimension).fill(0);
    const { min, max } = this.config.constraints!;

    for (let i = 0; i < dimension; i++) {
      const minVal = min?.[i] ?? -10;
      const maxVal = max?.[i] ?? 10;
      solution[i] = minVal + Math.random() * (maxVal - minVal);
    }

    return solution;
  }

  private generateNeighbor(): number[] {
    const neighbor = [...this.currentSolution];
    const dimension = neighbor.length;
    const { min, max } = this.config.constraints!;

    // Select a random dimension to modify
    const dimensionToModify = Math.floor(Math.random() * dimension);

    // Generate a random step size based on temperature
    const stepSize = this.temperature * (Math.random() * 2 - 1);

    // Apply the step
    neighbor[dimensionToModify] += stepSize;

    // Ensure bounds
    if (min) {
      neighbor[dimensionToModify] = Math.max(neighbor[dimensionToModify], min[dimensionToModify]);
    }
    if (max) {
      neighbor[dimensionToModify] = Math.min(neighbor[dimensionToModify], max[dimensionToModify]);
    }

    return neighbor;
  }

  private acceptNeighbor(neighborValue: number): boolean {
    // Always accept better solutions
    if (neighborValue < this.currentValue) {
      return true;
    }

    // Calculate acceptance probability
    const deltaE = neighborValue - this.currentValue;
    const probability = Math.exp(-deltaE / this.temperature);

    // Accept with probability
    return Math.random() < probability;
  }

  protected checkConvergence(): boolean {
    if (this.history.length < 10) {
      return false;
    }

    // Check if temperature is low enough
    if (this.temperature < 1e-6) {
      return true;
    }

    // Check if solution has stabilized
    const recentHistory = this.history.slice(-10);
    const valueConvergence = super.checkConvergence();

    return valueConvergence;
  }
}

