import { BaseModel } from '../models/BaseModel';
import { ModelConfig, ModelMetrics, ModelType } from '../types';
import { EventEmitter } from 'events';

export class ModelRegistry extends EventEmitter {
  private static instance: ModelRegistry;
  private models: Map<string, BaseModel> = new Map();
  private modelMetrics: Map<string, ModelMetrics> = new Map();
  private modelWeights: Map<string, number> = new Map();

  private constructor() {
    super();
  }

  public static getInstance(): ModelRegistry {
    if (!ModelRegistry.instance) {
      ModelRegistry.instance = new ModelRegistry();
    }
    return ModelRegistry.instance;
  }

  public registerModel(model: BaseModel): void {
    const config = model.getConfig();
    this.models.set(config.name, model);
    this.modelMetrics.set(config.name, {});
    this.modelWeights.set(config.name, 1.0);
    this.emit('modelRegistered', config.name);
  }

  public unregisterModel(modelName: string): void {
    this.models.delete(modelName);
    this.modelMetrics.delete(modelName);
    this.modelWeights.delete(modelName);
    this.emit('modelUnregistered', modelName);
  }

  public getModel(modelName: string): BaseModel | undefined {
    return this.models.get(modelName);
  }

  public getModelsByType(type: ModelType): BaseModel[] {
    return Array.from(this.models.values()).filter(model => model.getType() === type);
  }

  public getAllModels(): BaseModel[] {
    return Array.from(this.models.values());
  }

  public updateModelMetrics(modelName: string, metrics: ModelMetrics): void {
    this.modelMetrics.set(modelName, metrics);
    this.emit('metricsUpdated', modelName, metrics);
  }

  public getModelMetrics(modelName: string): ModelMetrics | undefined {
    return this.modelMetrics.get(modelName);
  }

  public updateModelWeights(): void {
    let totalAccuracy = 0;
    let modelCount = 0;

    // Calculate total accuracy
    for (const [name, metrics] of this.modelMetrics.entries()) {
      if (metrics.accuracy !== undefined) {
        totalAccuracy += metrics.accuracy;
        modelCount++;
      }
    }

    if (modelCount === 0) return;

    const averageAccuracy = totalAccuracy / modelCount;

    // Update weights based on relative accuracy
    for (const [name, metrics] of this.modelMetrics.entries()) {
      if (metrics.accuracy !== undefined) {
        const weight = metrics.accuracy / averageAccuracy;
        this.modelWeights.set(name, weight);
      }
    }

    this.emit('weightsUpdated', Object.fromEntries(this.modelWeights));
  }

  public getModelWeight(modelName: string): number {
    return this.modelWeights.get(modelName) || 1.0;
  }

  public async trainAllModels(data: any): Promise<void> {
    const trainingPromises = Array.from(this.models.values()).map(model => model.train(data));
    await Promise.all(trainingPromises);
    this.emit('allModelsTrained');
  }

  public async evaluateAllModels(data: any): Promise<void> {
    const evaluationPromises = Array.from(this.models.values()).map(async model => {
      const metrics = await model.evaluate(data);
      this.updateModelMetrics(model.getName(), metrics);
    });
    await Promise.all(evaluationPromises);
    this.updateModelWeights();
    this.emit('allModelsEvaluated');
  }

  public async saveAllModels(basePath: string): Promise<void> {
    const savePromises = Array.from(this.models.values()).map(model =>
      model.save(`${basePath}/${model.getName()}`)
    );
    await Promise.all(savePromises);
    this.emit('allModelsSaved');
  }

  public async loadAllModels(basePath: string): Promise<void> {
    const loadPromises = Array.from(this.models.values()).map(model =>
      model.load(`${basePath}/${model.getName()}`)
    );
    await Promise.all(loadPromises);
    this.emit('allModelsLoaded');
  }
}

import { BaseModel } from '../models/BaseModel';
import { EventEmitter } from 'events';
import * as tf from '@tensorflow/tfjs-node';

interface ResourceAllocation {
  modelId: string;
  gpuMemory: number;
  cpuMemory: number;
  startTime: number;
}

export class ResourceManager extends EventEmitter {
  private static instance: ResourceManager;
  private allocations: Map<string, ResourceAllocation> = new Map();
  private totalGPUMemory: number;
  private totalCPUMemory: number;
  private gpuMemoryLimit: number;
  private cpuMemoryLimit: number;

  private constructor() {
    super();
    this.initializeResources();
  }

  public static getInstance(): ResourceManager {
    if (!ResourceManager.instance) {
      ResourceManager.instance = new ResourceManager();
    }
    return ResourceManager.instance;
  }

  private async initializeResources(): Promise<void> {
    try {
      // Get GPU information
      const gpuInfo = await tf.getBackend().getGPGPUContext();
      this.totalGPUMemory = gpuInfo.getMaxTextureSize() * 4; // Approximate GPU memory
      this.gpuMemoryLimit = this.totalGPUMemory * 0.9; // 90% of total GPU memory      // Get CPU information (browser-compatible approach)
      const memoryInfo = (navigator as any).deviceMemory;
      this.totalCPUMemory = memoryInfo ? memoryInfo * 1024 * 1024 * 1024 : 8 * 1024 * 1024 * 1024; // Use deviceMemory API or fallback to 8GB
      this.cpuMemoryLimit = this.totalCPUMemory * 0.8; // 80% of total CPU memory
    } catch (error) {
      console.error('Failed to initialize resources:', error);
      // Fallback to conservative limits
      this.totalGPUMemory = 4 * 1024 * 1024 * 1024; // 4GB
      this.gpuMemoryLimit = this.totalGPUMemory * 0.5;
      this.totalCPUMemory = 8 * 1024 * 1024 * 1024; // 8GB
      this.cpuMemoryLimit = this.totalCPUMemory * 0.5;
    }
  }

  public async allocateResources(model: BaseModel): Promise<void> {
    const modelId = model.config.name;

    if (this.allocations.has(modelId)) {
      throw new Error(`Resources already allocated for model ${modelId}`);
    }

    try {
      // Get model resource requirements
      const requirements = await this.getModelRequirements(model);

      // Check if resources are available
      await this.checkResourceAvailability(requirements);

      // Allocate resources
      this.allocations.set(modelId, {
        modelId,
        gpuMemory: requirements.gpuMemory,
        cpuMemory: requirements.cpuMemory,
        startTime: Date.now(),
      });

      this.emit('resourcesAllocated', {
        modelId,
        allocation: this.allocations.get(modelId),
      });
    } catch (error) {
      this.emit('allocationError', { modelId, error });
      throw error;
    }
  }

  public async releaseResources(modelId: string): Promise<void> {
    const allocation = this.allocations.get(modelId);
    if (allocation) {
      this.allocations.delete(modelId);
      this.emit('resourcesReleased', { modelId, allocation });
    }
  }

  private async getModelRequirements(model: BaseModel): Promise<{
    gpuMemory: number;
    cpuMemory: number;
  }> {
    // Estimate resource requirements based on model type and configuration
    const baseMemory = 100 * 1024 * 1024; // 100MB base memory

    let gpuMemory = baseMemory;
    let cpuMemory = baseMemory;

    switch (model.config.type) {
      case 'deepLearning':
        gpuMemory *= 4; // Deep learning models need more GPU memory
        break;
      case 'timeSeries':
        cpuMemory *= 2; // Time series models need more CPU memory
        break;
      case 'optimization':
        cpuMemory *= 3; // Optimization models need more CPU memory
        break;
    }

    return { gpuMemory, cpuMemory };
  }

  private async checkResourceAvailability(requirements: {
    gpuMemory: number;
    cpuMemory: number;
  }): Promise<void> {
    const currentGPUUsage = this.getCurrentGPUUsage();
    const currentCPUUsage = this.getCurrentCPUUsage();

    if (currentGPUUsage + requirements.gpuMemory > this.gpuMemoryLimit) {
      throw new Error('Insufficient GPU memory available');
    }

    if (currentCPUUsage + requirements.cpuMemory > this.cpuMemoryLimit) {
      throw new Error('Insufficient CPU memory available');
    }
  }

  private getCurrentGPUUsage(): number {
    return Array.from(this.allocations.values()).reduce(
      (total, allocation) => total + allocation.gpuMemory,
      0
    );
  }

  private getCurrentCPUUsage(): number {
    return Array.from(this.allocations.values()).reduce(
      (total, allocation) => total + allocation.cpuMemory,
      0
    );
  }

  public getResourceUtilization(): {
    gpu: { used: number; total: number; percentage: number };
    cpu: { used: number; total: number; percentage: number };
  } {
    const gpuUsed = this.getCurrentGPUUsage();
    const cpuUsed = this.getCurrentCPUUsage();

    return {
      gpu: {
        used: gpuUsed,
        total: this.totalGPUMemory,
        percentage: (gpuUsed / this.totalGPUMemory) * 100,
      },
      cpu: {
        used: cpuUsed,
        total: this.totalCPUMemory,
        percentage: (cpuUsed / this.totalCPUMemory) * 100,
      },
    };
  }

  public async cleanup(): Promise<void> {
    // Release all allocated resources
    const modelIds = Array.from(this.allocations.keys());
    await Promise.all(modelIds.map(id => this.releaseResources(id)));

    // Clear GPU memory
    await tf.disposeVariables();

    this.emit('cleanupComplete');
  }
}

