  opportunityId: string;
  market: string;
  placedOdds: number;
  closingOdds: number;
  stake: number;
  result: 'WIN' | 'LOSS' | 'PUSH';
  payout: number;
  timestamp: number;
  metadata: {
    type: BettingOpportunity['type'];
    books: string[];
    clv?: number;
    edgeRetention?: number;
  };
}

export interface PerformanceMetrics {
  totalBets: number;
  winRate: number;
  roi: number;
  clvAverage: number;
  edgeRetention: number;
  kellyMultiplier: number;
  marketEfficiencyScore: number;
  profitByStrategy: Record<BettingOpportunity['type'], number>;
  variance: number;
  sharpeRatio: number;
  averageClv: number;
  sharpnessScore: number;
}

export interface ClvAnalysis {
  clvValue: number;
  edgeRetained: number;
  marketEfficiency: number;
  timeValue: number;
  factors: {
    name: string;
    impact: number;
    description: string;
