  BettingMetrics as BettingMetricsType,
  BettingHistoryEntry,
} from '../../types/betting';

interface BettingConfig {
  minConfidence: number;
  maxStakePercentage: number;
  riskProfile: RiskProfileType;
  autoRefresh: boolean;
  refreshInterval: number;
}

interface BettingMetrics {
  totalBets: number;
  winRate: number;
  averageOdds: number;
  profitLoss: number;
  roi: number;
  sharpeRatio: number;
  maxDrawdown: number;
}

interface BettingOpportunity {
  event_id: string;
  market: string;
  odds: number;
  prediction?: {
    confidence: number;
    probability: number;
  };
  marketEdge: number;
  timestamp: string;
}

class UnifiedBettingService {
  private static instance: UnifiedBettingService | null = null;
  private readonly predictionService: UnifiedPredictionService;
  private readonly wsService: WebSocketManager;
  private config: BettingConfig = {
    minConfidence: 0.7,
    maxStakePercentage: 0.1,
    riskProfile: RiskProfileType.MODERATE,
    autoRefresh: true,
    refreshInterval: 30000,
  };

  private readonly apiUrl: string;

  protected constructor() {
    this.apiUrl = process.env.VITE_API_URL || 'http://localhost:8000';
    this.predictionService = UnifiedPredictionService.getInstance();
    this.wsService = WebSocketManager.getInstance();
    this.initializeWebSocketHandlers();
  }

  public static getInstance(): UnifiedBettingService {
    if (!UnifiedBettingService.instance) {
      UnifiedBettingService.instance = new UnifiedBettingService();
    }
    return UnifiedBettingService.instance;
  }

  private initializeWebSocketHandlers(): void {
    this.wsService.on('odds_update', this.handleOddsUpdate.bind(this));
    this.wsService.on('betting_opportunities', this.handleBettingOpportunities.bind(this));
    this.wsService.on('bet_result', this.handleBetResult.bind(this));
  }

  private handleOddsUpdate(data: any): void {
    // Update local odds cache and notify subscribers
    this.emit('odds_update', data);
  }

  private handleBettingOpportunities(data: any): void {
    // Process and validate betting opportunities
    const opportunities = this.validateBettingOpportunities(data.opportunities);
    this.emit('betting_opportunities', opportunities);
  }

  private handleBetResult(data: any): void {
    // Process bet results and update metrics
    this.updateBettingMetrics(data);
    this.emit('bet_result', data);
  }

  private validateBettingOpportunities(opportunities: BettingOpportunity[]): BettingOpportunity[] {
    return opportunities.filter(opportunity => {
      const confidence = this.calculateOpportunityConfidence(opportunity);
      return confidence >= this.config.minConfidence;
    });
  }

  private calculateOpportunityConfidence(opportunity: BettingOpportunity): number {
    // Combine prediction confidence with market edge
    const predictionConfidence = opportunity.prediction?.confidence || 0;
    const marketEdge = opportunity.marketEdge || 0;
    return predictionConfidence * 0.7 + marketEdge * 0.3;
  }

  private updateBettingMetrics(result: any): void {
    // Update local metrics cache
    this.emit('metrics_update', this.calculateMetrics(result));
  }

  private calculateMetrics(result: any): BettingMetrics {
    // Calculate updated betting metrics based on new result
    return {
      totalBets: (result.totalBets || 0) + 1,
      winRate: this.calculateWinRate(result),
      averageOdds: this.calculateAverageOdds(result),
      profitLoss: this.calculateProfitLoss(result),
      roi: this.calculateROI(result),
      sharpeRatio: this.calculateSharpeRatio(result),
      maxDrawdown: this.calculateMaxDrawdown(result),
    };
  }

  private calculateWinRate(result: any): number {
    const wins = result.wins || 0;
    const total = result.totalBets || 1;
    return wins / total;
  }

  private calculateAverageOdds(result: any): number {
    const totalOdds = result.totalOdds || 0;
    const count = result.oddsCount || 1;
    return totalOdds / count;
  }

  private calculateProfitLoss(result: any): number {
    return result.profitLoss || 0;
  }

  private calculateROI(result: any): number {
    const profitLoss = this.calculateProfitLoss(result);
    const totalStaked = result.totalStaked || 1;
    return (profitLoss / totalStaked) * 100;
  }

  private calculateSharpeRatio(result: any): number {
    const returns = result.returns || [];
    if (returns.length < 2) return 0;

    const mean = returns.reduce((a: number, b: number) => a + b, 0) / returns.length;
    const variance =
      returns.reduce((a: number, b: number) => a + Math.pow(b - mean, 2), 0) / returns.length;
    const stdDev = Math.sqrt(variance);

    return stdDev === 0 ? 0 : mean / stdDev;
  }

  private calculateMaxDrawdown(result: any): number {
    const returns = result.returns || [];
    if (returns.length === 0) return 0;

    let peak = returns[0];
    let maxDrawdown = 0;

    for (const value of returns) {
      if (value > peak) {
        peak = value;
      }
      const drawdown = (peak - value) / peak;
      maxDrawdown = Math.max(maxDrawdown, drawdown);
    }

    return maxDrawdown;
  }

  public async getBettingOpportunities(): Promise<BettingOpportunity[]> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/betting/opportunities`);
      return this.validateBettingOpportunities(response.data);
    } catch (error) {
      console.error('Error fetching betting opportunities:', error);
      toast.error('Failed to fetch betting opportunities');
      return [];
    }
  }

  public async placeBet(bet: BetRecommendation): Promise<boolean> {
    try {
      const response = await axios.post(`${this.apiUrl}/api/betting/place`, bet);
      this.emit('bet_placed', response.data);
      return true;
    } catch (error) {
      console.error('Error placing bet:', error);
      toast.error('Failed to place bet');
      return false;
    }
  }

  public async getBettingMetrics(): Promise<BettingMetricsType> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/betting/metrics`);
      return response.data;
    } catch (error) {
      console.error('Error fetching betting metrics:', error);
      return {
        total_bets: 0,
        winning_bets: 0,
        losing_bets: 0,
        total_stake: 0,
        total_profit: 0,
        roi: 0,
        win_rate: 0,
        average_odds: 0,
        average_stake: 0,
        risk_score: 0,
        timestamp: new Date().toISOString(),
      };
    }
  }

  public async getBetHistory(): Promise<BettingHistoryEntry[]> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/betting/history`);
      return response.data;
    } catch (error) {
      console.error('Error fetching bet history:', error);
      return [];
    }
  }

  public setConfig(newConfig: Partial<BettingConfig>): void {
    this.config = { ...this.config, ...newConfig };
    this.emit('config_updated', this.config);
  }

  public getConfig(): BettingConfig {
    return { ...this.config };
  }

  // Placeholder for event emission logic. If you need to propagate events to the UI or other consumers,
  // integrate with a global event bus or observer pattern as appropriate for your application.
  private emit(type: string, data: any): void {
    // No-op: implement as needed for your architecture.
  }
}

