import { UnifiedCache } from '../unified/UnifiedCache';
import { BettingContext, MarketContext, PredictionResult } from '../types';
import { BaseService } from './BaseService';
import { UnifiedServiceRegistry } from './UnifiedServiceRegistry';
import { UnifiedErrorService } from './UnifiedErrorService';
import {
  Bet,
  BettingState,
  BettingConfig,
  BettingStats,
  BettingOpportunity,
  BettingValidation,
} from '../../types/betting';
import { Event, Market, Selection, Odds } from '../../types/sports';
import { ModelOutput } from '../../types/prediction';
import {
  BettingPreview,
  BettingPreviewRequest,
  BettingValidationRequest,
  BettingPlaceRequest,
} from '../../types/betting';

export interface Bet {
  id: string;
  event: string;
  amount: number;
  odds: number;
  timestamp: number;
  status: 'active' | 'won' | 'lost' | 'cancelled';
  type: 'single' | 'multiple' | 'system';
  selections: BetSelection[];
}

export interface BetSelection {
  event: string;
  market: string;
  selection: string;
  odds: number;
  status: 'active' | 'won' | 'lost' | 'cancelled';
}

export interface BettingOpportunity {
  id: string;
  event: string;
  market: string;
  selection: string;
  odds: number;
  prediction: {
    confidence: number;
    expectedValue: number;
  };
  timestamp: number;
}

export class UnifiedBettingService extends BaseService {
  private static instance: UnifiedBettingService;
  private readonly predictionService: UnifiedPredictionService;
  private readonly config: UnifiedConfigManager;
  private readonly logger: UnifiedLogger;
  private readonly cache: UnifiedCache;
  private errorService: UnifiedErrorService;
  private bets: Map<string, Bet>;
  private state: BettingState = {
    bets: [],
    activeBets: [],
    balance: 0,
    isLoading: false,
    error: null,
  };

  private constructor(registry: UnifiedServiceRegistry) {
    super('betting', registry);
    this.predictionService = UnifiedPredictionService.getInstance();
    this.config = UnifiedConfigManager.getInstance();
    this.logger = UnifiedLogger.getInstance();
    this.cache = UnifiedCache.getInstance();
    this.errorService = registry.getService<UnifiedErrorService>('error');
    this.bets = new Map();
  }

  public static getInstance(registry: UnifiedServiceRegistry): UnifiedBettingService {
    if (!UnifiedBettingService.instance) {
      UnifiedBettingService.instance = new UnifiedBettingService(registry);
    }
    return UnifiedBettingService.instance;
  }

  public async analyzeOpportunity(
    marketContext: MarketContext,
    bettingContext: BettingContext
  ): Promise<BettingOpportunity | null> {
    try {
      // Get prediction
      const prediction = await this.predictionService.generatePrediction(
        marketContext,
        bettingContext
      );

      // Calculate expected value
      const expectedValue = this.calculateExpectedValue(prediction.prediction, marketContext.odds);

      // Calculate Kelly fraction
      const kellyFraction = this.calculateKellyFraction(prediction.prediction, marketContext.odds);

      // Check if opportunity meets criteria
      if (!this.meetsBettingCriteria(prediction, expectedValue, kellyFraction)) {
        return null;
      }

      const opportunity: BettingOpportunity = {
        id: `${marketContext.eventId}-${marketContext.marketType}`,
        event: marketContext.eventId,
        market: marketContext.marketType,
        selection: '',
        odds: marketContext.odds,
        prediction,
        timestamp: Date.now(),
      };

      // Cache the opportunity
      await this.cache.set(
        `opportunity:${opportunity.id}`,
        opportunity,
        this.config.get('opportunityCacheTTL')
      );

      // Emit opportunity event
      this.emit('opportunity:found', opportunity);

      return opportunity;
    } catch (error) {
      this.logger.error('Failed to analyze betting opportunity', {
        error,
        marketContext,
        bettingContext,
      });
      throw error;
    }
  }

  private calculateExpectedValue(probability: number, odds: number): number {
    return probability * odds - 1;
  }

  private calculateKellyFraction(probability: number, odds: number): number {
    const q = 1 - probability;
    const b = odds - 1;
    return (b * probability - q) / b;
  }

  private meetsBettingCriteria(
    prediction: PredictionResult,
    expectedValue: number,
    kellyFraction: number
  ): boolean {
    const minConfidence = this.config.get('minConfidence');
    const maxRiskPerBet = this.config.get('maxRiskPerBet');

    return (
      prediction.confidence >= minConfidence &&
      expectedValue > 0 &&
      kellyFraction > 0 &&
      kellyFraction <= maxRiskPerBet
    );
  }

  public async getOpportunities(): Promise<BettingOpportunity[]> {
    try {
      const opportunities: BettingOpportunity[] = [];
      for (const [key, value] of this.cache.entries()) {
        if (key.startsWith('opportunity:')) {
          opportunities.push(value as BettingOpportunity);
        }
      }
      return opportunities;
    } catch (error) {
      this.logger.error('Failed to get betting opportunities', { error });
      throw error;
    }
  }

  public async placeBet(params: {
    eventId: string;
    marketId: string;
    selectionId: string;
    odds: Odds;
    stake: number;
    strategy: string;
    confidenceScore: number;
    expectedValue: number;
    kellyFraction: number;
  }): Promise<Bet> {
    try {
      this.logger.info('Placing bet', 'UnifiedBettingService', params);
      const response = await this.api.post('/betting/place', params);
      const bet = response.data;

      // Update local state
      this.state.bets.push(bet);
      this.state.activeBets.push(bet);
      this.state.balance -= bet.stake;

      // Cache the bet
      this.cache.set(`bet:${bet.id}`, bet);

      return bet;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'placeBet', params },
      });
      throw error;
    }
  }

  private isValidStake(stake: number, opportunity: BettingOpportunity): boolean {
    const maxStake = this.calculateMaxStake(opportunity);
    return stake > 0 && stake <= maxStake;
  }

  private calculateMaxStake(opportunity: BettingOpportunity): number {
    const bankrollPercentage = this.config.get('bankrollPercentage');
    const maxRiskPerBet = this.config.get('maxRiskPerBet');

    // Get current bankroll from cache or default
    const bankroll = this.cache.get('bankroll') || 1000;

    // Calculate maximum stake based on Kelly fraction and risk limits
    const kellyStake = bankroll * opportunity.kellyFraction;
    const riskLimitStake = bankroll * maxRiskPerBet;
    const percentageStake = bankroll * bankrollPercentage;

    return Math.min(kellyStake, riskLimitStake, percentageStake);
  }

  async getBets(timeRange: 'day' | 'week' | 'month' | 'year' = 'week'): Promise<Bet[]> {
    try {
      const now = Date.now();
      const rangeInMs = this.getTimeRangeInMs(timeRange);
      const cutoff = now - rangeInMs;

      return Array.from(this.bets.values())
        .filter(bet => bet.timestamp >= cutoff)
        .sort((a, b) => b.timestamp - a.timestamp);
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'getBets', timeRange },
      });
      throw error;
    }
  }

  async getRecentBets(limit: number = 10): Promise<Bet[]> {
    try {
      return Array.from(this.bets.values())
        .sort((a, b) => b.timestamp - a.timestamp)
        .slice(0, limit);
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'getRecentBets', limit },
      });
      throw error;
    }
  }

  async updateBetStatus(betId: string, status: 'won' | 'lost' | 'cancelled'): Promise<Bet> {
    try {
      const bet = this.bets.get(betId);
      if (!bet) {
        throw new Error(`Bet with ID ${betId} not found`);
      }

      bet.status = status;
      bet.selections.forEach(selection => {
        selection.status = status;
      });

      this.bets.set(betId, bet);
      return bet;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'updateBetStatus', betId, status },
      });
      throw error;
    }
  }

  private generateId(): string {
    return `bet_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private getTimeRangeInMs(timeRange: 'day' | 'week' | 'month' | 'year'): number {
    const day = 24 * 60 * 60 * 1000;
    switch (timeRange) {
      case 'day':
        return day;
      case 'week':
        return 7 * day;
      case 'month':
        return 30 * day;
      case 'year':
        return 365 * day;
      default:
        return day;
    }
  }

  async getBettingHistory(eventId: string, marketId: string, selectionId: string): Promise<Bet[]> {
    try {
      const cacheKey = `history:${eventId}:${marketId}:${selectionId}`;
      const cached = this.cache.get<Bet[]>(cacheKey);
      if (cached) return cached;

      const response = await this.api.get('/betting/history', {
        params: { eventId, marketId, selectionId },
      });
      this.cache.set(cacheKey, response.data);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'getBettingHistory', eventId, marketId, selectionId },
      });
      throw error;
    }
  }

  async getActiveBets(): Promise<Bet[]> {
    try {
      const cached = this.cache.get<Bet[]>('activeBets');
      if (cached) return cached;

      const response = await this.api.get('/betting/active');
      this.state.activeBets = response.data;
      this.cache.set('activeBets', response.data);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'getActiveBets' },
      });
      throw error;
    }
  }

  async getBettingStats(
    eventId: string,
    marketId: string,
    selectionId: string
  ): Promise<BettingStats> {
    try {
      const cacheKey = `stats:${eventId}:${marketId}:${selectionId}`;
      const cached = this.cache.get<BettingStats>(cacheKey);
      if (cached) return cached;

      const response = await this.api.get('/betting/stats', {
        params: { eventId, marketId, selectionId },
      });
      this.cache.set(cacheKey, response.data);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'getBettingStats', eventId, marketId, selectionId },
      });
      throw error;
    }
  }

  async getBalance(): Promise<number> {
    try {
      const cached = this.cache.get<number>('balance');
      if (cached) return cached;

      const response = await this.api.get('/betting/balance');
      this.state.balance = response.data;
      this.cache.set('balance', response.data);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'getBalance' },
      });
      throw error;
    }
  }

  async updateOdds(odds: Odds): Promise<void> {
    try {
      await this.api.post('/betting/odds', { odds });
      this.cache.delete('activeBets'); // Invalidate active bets cache
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'updateOdds', odds },
      });
      throw error;
    }
  }

  async calculateKellyFraction(odds: Odds, probability: number): Promise<number> {
    try {
      const cacheKey = `kelly:${odds.id}:${probability}`;
      const cached = this.cache.get<number>(cacheKey);
      if (cached) return cached;

      const response = await this.api.post('/betting/kelly', {
        odds,
        probability,
      });
      this.cache.set(cacheKey, response.data);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'calculateKellyFraction', odds, probability },
      });
      throw error;
    }
  }

  async getBettingOpportunities(
    event: Event,
    market: Market,
    selection: Selection,
    modelOutput: ModelOutput
  ): Promise<{
    opportunities: BettingOpportunity[];
  }> {
    try {
      const cacheKey = `opportunities:${event.id}:${market.id}:${selection.id}`;
      const cached = this.cache.get<{ opportunities: BettingOpportunity[] }>(cacheKey);
      if (cached) return cached;

      const response = await this.api.post('/betting/opportunities', {
        event,
        market,
        selection,
        modelOutput,
      });
      this.cache.set(cacheKey, response.data);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: {
          method: 'getBettingOpportunities',
          event,
          market,
          selection,
          modelOutput,
        },
      });
      throw error;
    }
  }

  async validateBet(params: {
    eventId: string;
    marketId: string;
    selectionId: string;
    stake: number;
    odds: Odds;
  }): Promise<BettingValidation> {
    try {
      const response = await this.api.post('/betting/validate', params);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'validateBet', params },
      });
      throw error;
    }
  }

  async getBettingConfig(): Promise<BettingConfig> {
    try {
      const cached = this.cache.get<BettingConfig>('bettingConfig');
      if (cached) return cached;

      const response = await this.api.get('/betting/config');
      this.cache.set('bettingConfig', response.data);
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'getBettingConfig' },
      });
      throw error;
    }
  }

  async updateBettingConfig(config: Partial<BettingConfig>): Promise<BettingConfig> {
    try {
      const response = await this.api.put('/betting/config', config);
      this.cache.delete('bettingConfig'); // Invalidate config cache
      return response.data;
    } catch (error) {
      this.handleError(error, {
        code: 'BETTING_ERROR',
        source: 'UnifiedBettingService',
        details: { method: 'updateBettingConfig', config },
      });
      throw error;
    }
  }

  async previewBet(request: BettingPreviewRequest): Promise<BettingPreview | null> {
    try {
      const response = await this.api.post<BettingPreview>('/betting/preview', request);
      return response.data;
    } catch (error) {
      this.logger.error('Failed to preview bet', error);
      return null;
    }
  }

  async validateBet(request: BettingValidationRequest): Promise<BettingValidation> {
    try {
      const response = await this.api.post<BettingValidation>('/betting/validate', request);
      return response.data;
    } catch (error) {
      this.logger.error('Failed to validate bet', error);
      return {
        isValid: false,
        errors: ['Failed to validate bet'],
      };
    }
  }

  async placeBet(request: BettingPlaceRequest): Promise<Bet | null> {
    try {
      const response = await this.api.post<Bet>('/betting/place', request);
      return response.data;
    } catch (error) {
      this.logger.error('Failed to place bet', error);
      return null;
    }
  }
}

interface CacheEntry<T> {
  value: T;
  timestamp: number;
  ttl: number;
}

export class UnifiedCache {
  private static instance: UnifiedCache;
  private cache: Map<string, CacheEntry<any>> = new Map();
  private defaultTTL: number = 5 * 60 * 1000; // 5 minutes

  private constructor() {}

  static getInstance(): UnifiedCache {
    if (!UnifiedCache.instance) {
      UnifiedCache.instance = new UnifiedCache();
    }
    return UnifiedCache.instance;
  }

  set<T>(key: string, value: T, ttl: number = this.defaultTTL): void {
    this.cache.set(key, {
      value,
      timestamp: Date.now(),
      ttl,
    });
  }

  get<T>(key: string): T | null {
    const entry = this.cache.get(key);
    if (!entry) return null;

    if (this.isExpired(entry)) {
      this.cache.delete(key);
      return null;
    }

    return entry.value as T;
  }

  has(key: string): boolean {
    const entry = this.cache.get(key);
    if (!entry) return false;

    if (this.isExpired(entry)) {
      this.cache.delete(key);
      return false;
    }

    return true;
  }

  delete(key: string): void {
    this.cache.delete(key);
  }

  clear(): void {
    this.cache.clear();
  }

  private isExpired(entry: CacheEntry<any>): boolean {
    return Date.now() - entry.timestamp > entry.ttl;
  }

  getSize(): number {
    return this.cache.size;
  }

  getKeys(): string[] {
    return Array.from(this.cache.keys());
  }

  setDefaultTTL(ttl: number): void {
    this.defaultTTL = ttl;
  }
}

export class UnifiedConfig {
  private static instance: UnifiedConfig;
  private config: Record<string, any> = {};

  private constructor() {}

  static getInstance(): UnifiedConfig {
    if (!UnifiedConfig.instance) {
      UnifiedConfig.instance = new UnifiedConfig();
    }
    return UnifiedConfig.instance;
  }

  get<T>(key: string, defaultValue?: T): T {
    return (this.config[key] as T) ?? defaultValue;
  }

  set<T>(key: string, value: T): void {
    this.config[key] = value;
  }

  has(key: string): boolean {
    return key in this.config;
  }

  delete(key: string): void {
    delete this.config[key];
  }

  clear(): void {
    this.config = {};
  }

  getAll(): Record<string, any> {
    return { ...this.config };
  }
}

import EventEmitter from 'eventemitter3';
import axios, { AxiosInstance } from 'axios';
import { io, Socket } from 'socket.io-client';
import { z } from 'zod';

// Data source types
export enum DataSource {
  PRIZEPICKS = 'prizepicks',
  ESPN = 'espn',
  ODDS_API = 'odds_api',
}

// Unified response schema
const DataResponseSchema = z.object({
  source: z.nativeEnum(DataSource),
  timestamp: z.number(),
  data: z.unknown(),
  status: z.enum(['success', 'error']),
});

type DataResponse = z.infer<typeof DataResponseSchema>;

export class UnifiedDataService extends EventEmitter {
  private static instance: UnifiedDataService;
  private apiClients: Map<DataSource, AxiosInstance>;
  private wsConnections: Map<DataSource, WebSocket>;
  private cache: Map<string, { data: any; timestamp: number }>;

  private constructor() {
    super();
    this.apiClients = new Map();
    this.wsConnections = new Map();
    this.cache = new Map();
    this.initializeClients();
    this.initializeWebSockets();
  }

  static getInstance(): UnifiedDataService {
    if (!UnifiedDataService.instance) {
      UnifiedDataService.instance = new UnifiedDataService();
    }
    return UnifiedDataService.instance;
  }

  private initializeClients() {
    // Initialize API clients
    Object.values(DataSource).forEach(source => {
      this.apiClients.set(
        source,
        axios.create({
          baseURL: this.getBaseUrl(source),
          timeout: 10000,
        })
      );
    });
  }

  private initializeWebSockets() {
    // Initialize WebSocket connections for each data source
    Object.values(DataSource).forEach(source => {
      const ws = new WebSocket(this.getWebSocketUrl(source));

      ws.onmessage = event => {
        const data = JSON.parse(event.data);
        this.emit(`ws:${source}:${data.type}`, data);
      };

      ws.onerror = error => {
        this.emit('error', { source, error });
      };

      this.wsConnections.set(source, ws);
    });
  }

  private getBaseUrl(source: DataSource): string {
    // Configure base URLs for different data sources
    const urls = {
      [DataSource.PRIZEPICKS]: process.env.PRIZEPICKS_API_URL,
      [DataSource.ESPN]: process.env.ESPN_API_URL,
      [DataSource.ODDS_API]: process.env.ODDS_API_URL,
    };
    return urls[source] || '';
  }

  private getWebSocketUrl(source: DataSource): string {
    switch (source) {
      case DataSource.PRIZEPICKS:
        return 'wss://api.prizepicks.com/ws';
      case DataSource.ODDS_API:
        return 'wss://api.odds-api.com/ws';
      default:
        throw new Error(`Unknown data source: ${source}`);
    }
  }

  async fetchData<T>(source: DataSource, endpoint: string): Promise<T> {
    try {
      const response = await fetch(this.getApiUrl(source, endpoint));
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      return await response.json();
    } catch (error) {
      this.emit('error', { source, endpoint, error });
      throw error;
    }
  }

  private getApiUrl(source: DataSource, endpoint: string): string {
    const baseUrl = this.getBaseUrl(source);
    return `${baseUrl}${endpoint}`;
  }

  async fetchDataFromApi(
    source: DataSource,
    endpoint: string,
    params?: any
  ): Promise<DataResponse> {
    const cacheKey = `${source}:${endpoint}:${JSON.stringify(params)}`;
    const cached = this.cache.get(cacheKey);

    // Return cached data if it's less than 30 seconds old
    if (cached && Date.now() - cached.timestamp < 30000) {
      return {
        source,
        timestamp: cached.timestamp,
        data: cached.data,
        status: 'success',
      };
    }

    try {
      const client = this.apiClients.get(source);
      if (!client) throw new Error(`No client found for source: ${source}`);

      const response = await client.get(endpoint, { params });

      // Cache the response
      this.cache.set(cacheKey, {
        data: response.data,
        timestamp: Date.now(),
      });

      return {
        source,
        timestamp: Date.now(),
        data: response.data,
        status: 'success',
      };
    } catch (error) {
      this.emit('error', { source, error });
      return {
        source,
        timestamp: Date.now(),
        data: null,
        status: 'error',
      };
    }
  }

  connectWebSocket(source: DataSource, options: { events: string[] }) {
    if (this.wsConnections.has(source)) return;

    const socket = io(this.getBaseUrl(source), {
      transports: ['websocket'],
      autoConnect: true,
    });

    options.events.forEach(event => {
      socket.on(event, data => {
        this.emit(`ws:${source}:${event}`, data);
      });
    });

    socket.on('connect_error', error => {
      this.emit('ws:error', { source, error });
    });

    this.wsConnections.set(source, socket);
  }

  disconnectWebSocket(source: DataSource) {
    const socket = this.wsConnections.get(source);
    if (socket) {
      socket.disconnect();
      this.wsConnections.delete(source);
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

import { EventEmitter } from 'events';
import { UnifiedConfigManager } from '../unified/UnifiedConfig';
import { UnifiedLogger } from '../unified/UnifiedLogger';
import { UnifiedCache } from '../unified/UnifiedCache';
import { BaseService } from './BaseService';
import { UnifiedServiceRegistry } from './UnifiedServiceRegistry';

export interface ErrorContext {
  code: string;
  message: string;
  severity: 'error' | 'warning' | 'info';
  timestamp: number;
  source: string;
  details?: Record<string, any>;
  stack?: string;
}

export interface ErrorDetails {
  code: string;
  source: string;
  details?: Record<string, any>;
  timestamp?: number;
}

export class UnifiedErrorService extends BaseService {
  private static instance: UnifiedErrorService;
  private readonly config: UnifiedConfigManager;
  private readonly logger: UnifiedLogger;
  private readonly cache: UnifiedCache;
  private readonly errorHistory: ErrorContext[] = [];
  private readonly maxErrorHistory = 100;
  private errors: ErrorDetails[] = [];
  private readonly maxErrors: number = 1000;

  private constructor(registry: UnifiedServiceRegistry) {
    super('error', registry);
    this.config = UnifiedConfigManager.getInstance();
    this.logger = UnifiedLogger.getInstance();
    this.cache = UnifiedCache.getInstance();
  }

  public static getInstance(registry: UnifiedServiceRegistry): UnifiedErrorService {
    if (!UnifiedErrorService.instance) {
      UnifiedErrorService.instance = new UnifiedErrorService(registry);
    }
    return UnifiedErrorService.instance;
  }

  public handleError(error: unknown, details: ErrorDetails): void {
    const errorDetails: ErrorDetails = {
      ...details,
      timestamp: Date.now(),
    };

    // Log error to console in development
    if (process.env.NODE_ENV === 'development') {
      console.error('Error:', error);
      console.error('Details:', errorDetails);
    }

    // Store error
    this.errors.unshift(errorDetails);
    if (this.errors.length > this.maxErrors) {
      this.errors.pop();
    }

    // Emit error event
    this.emit('error', { error, details: errorDetails });
  }

  public getErrors(limit: number = 100): ErrorDetails[] {
    return this.errors.slice(0, limit);
  }

  public clearErrors(): void {
    this.errors = [];
  }

  public getErrorCount(): number {
    return this.errors.length;
  }

  public getErrorsByCode(code: string): ErrorDetails[] {
    return this.errors.filter(error => error.code === code);
  }

  public getErrorsBySource(source: string): ErrorDetails[] {
    return this.errors.filter(error => error.source === source);
  }

  public getRecentErrors(timeRange: 'day' | 'week' | 'month' = 'day'): ErrorDetails[] {
    const now = Date.now();
    const rangeInMs = this.getTimeRangeInMs(timeRange);
    const cutoff = now - rangeInMs;

    return this.errors.filter(error => (error.timestamp || 0) >= cutoff);
  }

  private getTimeRangeInMs(timeRange: 'day' | 'week' | 'month'): number {
    const day = 24 * 60 * 60 * 1000;
    switch (timeRange) {
      case 'day':
        return day;
      case 'week':
        return 7 * day;
      case 'month':
        return 30 * day;
      default:
        return day;
    }
  }

  public getErrorHistory(): ErrorContext[] {
    return [...this.errorHistory];
  }

  public getRecentErrors(): ErrorContext[] {
    return this.errorHistory.slice(0, 10);
  }

  public clearErrorHistory(): void {
    this.errorHistory.length = 0;
    this.cache.delete('recent_errors');
    this.emit('error:history:cleared');
  }

  public subscribe(callback: (error: ErrorContext) => void): () => void {
    this.on('error:occurred', callback);
    return () => this.off('error:occurred', callback);
  }

  private handleErrorBySeverity(error: ErrorContext): void {
    switch (error.severity) {
      case 'error':
        this.handleCriticalError(error);
        break;
      case 'warning':
        this.handleWarning(error);
        break;
      case 'info':
        this.handleInfo(error);
        break;
    }
  }

  private handleCriticalError(error: ErrorContext): void {
    // Implement critical error handling logic
    // For example, notify administrators, trigger fallback mechanisms, etc.
    this.emit('error:critical', error);
  }

  private handleWarning(error: ErrorContext): void {
    // Implement warning handling logic
    // For example, log to monitoring system, notify developers, etc.
    this.emit('error:warning', error);
  }

  private handleInfo(error: ErrorContext): void {
    // Implement info handling logic
    // For example, log to analytics, track patterns, etc.
    this.emit('error:info', error);
  }

  public isErrorRecoverable(error: ErrorContext): boolean {
    // Implement logic to determine if an error is recoverable
    const recoverableCodes = this.config.get('recoverableErrorCodes') || [];
    return recoverableCodes.includes(error.code);
  }

  public getErrorMetrics(): {
    totalErrors: number;
    criticalErrors: number;
    warnings: number;
    info: number;
    lastErrorTime: number;
  } {
    return {
      totalErrors: this.errorHistory.length,
      criticalErrors: this.errorHistory.filter(e => e.severity === 'error').length,
      warnings: this.errorHistory.filter(e => e.severity === 'warning').length,
      info: this.errorHistory.filter(e => e.severity === 'info').length,
      lastErrorTime: this.errorHistory[0]?.timestamp || 0,
    };
  }
}

export enum LogLevel {
  DEBUG = 'DEBUG',
  INFO = 'INFO',
  WARN = 'WARN',
  ERROR = 'ERROR',
}

export interface LogEntry {
  level: LogLevel;
  message: string;
  timestamp: number;
  source?: string;
  details?: any;
}

export class UnifiedLogger {
  private static instance: UnifiedLogger;
  private logLevel: LogLevel = LogLevel.INFO;
  private logs: LogEntry[] = [];

  private constructor() {}

  static getInstance(): UnifiedLogger {
    if (!UnifiedLogger.instance) {
      UnifiedLogger.instance = new UnifiedLogger();
    }
    return UnifiedLogger.instance;
  }

  setLogLevel(level: LogLevel): void {
    this.logLevel = level;
  }

  debug(message: string, source?: string, details?: any): void {
    this.log(LogLevel.DEBUG, message, source, details);
  }

  info(message: string, source?: string, details?: any): void {
    this.log(LogLevel.INFO, message, source, details);
  }

  warn(message: string, source?: string, details?: any): void {
    this.log(LogLevel.WARN, message, source, details);
  }

  error(message: string, source?: string, details?: any): void {
    this.log(LogLevel.ERROR, message, source, details);
  }

  private log(level: LogLevel, message: string, source?: string, details?: any): void {
    if (this.shouldLog(level)) {
      const entry: LogEntry = {
        level,
        message,
        timestamp: Date.now(),
        source,
        details,
      };
      this.logs.push(entry);
      this.outputLog(entry);
    }
  }

  private shouldLog(level: LogLevel): boolean {
    const levels = Object.values(LogLevel);
    return levels.indexOf(level) >= levels.indexOf(this.logLevel);
  }

  private outputLog(entry: LogEntry): void {
    const timestamp = new Date(entry.timestamp).toISOString();
    const source = entry.source ? `[${entry.source}]` : '';
    const details = entry.details ? ` ${JSON.stringify(entry.details)}` : '';
    console.log(`${timestamp} ${entry.level} ${source} ${entry.message}${details}`);
  }

  getLogs(level?: LogLevel): LogEntry[] {
    return level ? this.logs.filter(log => log.level === level) : [...this.logs];
  }

  clearLogs(): void {
    this.logs = [];
  }
}

import { BaseService } from './BaseService';
import { UnifiedServiceRegistry } from './UnifiedServiceRegistry';
import { UnifiedErrorService } from './UnifiedErrorService';
import { UnifiedStateService } from './UnifiedStateService';

export type NotificationType = 'info' | 'success' | 'warning' | 'error';

export interface Notification {
  id: string;
  type: NotificationType;
  message: string;
  title?: string;
  timestamp: number;
  read: boolean;
  data?: Record<string, any>;
}

export interface NotificationOptions {
  title?: string;
  duration?: number;
  data?: Record<string, any>;
  sound?: boolean;
  priority?: 'low' | 'normal' | 'high';
}

export class UnifiedNotificationService extends BaseService {
  private errorService: UnifiedErrorService;
  private stateService: UnifiedStateService;
  private readonly defaultDuration: number = 5000;
  private readonly maxNotifications: number = 100;

  constructor(registry: UnifiedServiceRegistry) {
    super('notification', registry);
    const errorService = registry.getService('error');
    const stateService = registry.getService('state');
    if (!errorService || !stateService) {
      throw new Error('Required services not found in registry');
    }
    this.errorService = errorService as unknown as UnifiedErrorService;
    this.stateService = stateService as unknown as UnifiedStateService;
  }

  notifyUser(
    notification: Omit<Notification, 'id' | 'timestamp' | 'read'>,
    options: NotificationOptions = {}
  ): void {
    try {
      const newNotification: Notification = {
        ...notification,
        id: this.generateId(),
        timestamp: Date.now(),
        read: false,
      };

      // Add to state
      const currentNotifications = this.stateService.getState().notifications;
      const updatedNotifications = [newNotification, ...currentNotifications].slice(
        0,
        this.maxNotifications
      );

      this.stateService.setState({ notifications: updatedNotifications });

      // Play sound if enabled
      if (options.sound && this.stateService.getState().settings.sound) {
        this.playNotificationSound(notification.type);
      }

      // Auto-dismiss if duration is specified
      if (options.duration !== 0) {
        setTimeout(() => {
          this.dismissNotification(newNotification.id);
        }, options.duration || this.defaultDuration);
      }
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'NOTIFICATION_ERROR',
        source: 'UnifiedNotificationService',
        details: { method: 'notifyUser', notification, options },
      });
    }
  }

  dismissNotification(notificationId: string): void {
    try {
      const currentNotifications = this.stateService.getState().notifications;
      const updatedNotifications = currentNotifications.filter(
        notification => notification.id !== notificationId
      );

      this.stateService.setState({ notifications: updatedNotifications });
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'NOTIFICATION_ERROR',
        source: 'UnifiedNotificationService',
        details: { method: 'dismissNotification', notificationId },
      });
    }
  }

  markAsRead(notificationId: string): void {
    try {
      const currentNotifications = this.stateService.getState().notifications;
      const updatedNotifications = currentNotifications.map(notification =>
        notification.id === notificationId ? { ...notification, read: true } : notification
      );

      this.stateService.setState({ notifications: updatedNotifications });
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'NOTIFICATION_ERROR',
        source: 'UnifiedNotificationService',
        details: { method: 'markAsRead', notificationId },
      });
    }
  }

  clearAll(): void {
    try {
      this.stateService.setState({ notifications: [] });
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'NOTIFICATION_ERROR',
        source: 'UnifiedNotificationService',
        details: { method: 'clearAll' },
      });
    }
  }

  getUnreadCount(): number {
    try {
      return this.stateService.getState().notifications.filter(notification => !notification.read)
        .length;
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'NOTIFICATION_ERROR',
        source: 'UnifiedNotificationService',
        details: { method: 'getUnreadCount' },
      });
      return 0;
    }
  }

  private generateId(): string {
    return `notif_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private playNotificationSound(type: Notification['type']): void {
    try {
      const audio = new Audio();
      switch (type) {
        case 'success':
          audio.src = '/sounds/success.mp3';
          break;
        case 'error':
          audio.src = '/sounds/error.mp3';
          break;
        case 'warning':
          audio.src = '/sounds/warning.mp3';
          break;
        default:
          audio.src = '/sounds/info.mp3';
      }
      audio.play().catch(error => {
        this.errorService.handleError(error, {
          code: 'NOTIFICATION_ERROR',
          source: 'UnifiedNotificationService',
          details: { method: 'playNotificationSound', type },
        });
      });
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'NOTIFICATION_ERROR',
        source: 'UnifiedNotificationService',
        details: { method: 'playNotificationSound', type },
      });
    }
  }

  notify(type: NotificationType, message: string): void {
    const notification: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      message,
      timestamp: Date.now(),
      read: false,
    };

    // Log notification
    this.logger.info(`Notification [${type}]: ${message}`);
  }
}

import { EventBus } from '../../core/EventBus';
import { ErrorHandler } from '../../core/ErrorHandler';
import { PerformanceMonitor } from '../../core/PerformanceMonitor';
import { UnifiedConfig } from '../../core/UnifiedConfig';
import { WebSocketManager } from './WebSocketManager';
import { RiskProfile } from '../../types/core';

export interface PredictionResult {
  id: string;
  event: string;
  market: string;
  prediction: number;
  confidence: number;
  riskScore: number;
  timestamp: number;
  metadata: {
    modelVersion: string;
    features: Record<string, number>;
    shapValues?: Record<string, number>;
    performanceMetrics?: Record<string, number>;
  };
}

export class UnifiedPredictionService {
  private static instance: UnifiedPredictionService;
  private readonly eventBus: EventBus;
  private readonly errorHandler: ErrorHandler;
  private readonly performanceMonitor: PerformanceMonitor;
  private readonly config: UnifiedConfig;
  private readonly wsService: WebSocketManager;
  private activePredictions: Map<string, PredictionResult>;
  private predictionSubscribers: Set<(prediction: PredictionResult) => void>;

  private constructor() {
    this.eventBus = EventBus.getInstance();
    this.errorHandler = ErrorHandler.getInstance();
    this.performanceMonitor = PerformanceMonitor.getInstance();
    this.config = UnifiedConfig.getInstance();
    this.wsService = WebSocketManager.getInstance();
    this.activePredictions = new Map();
    this.predictionSubscribers = new Set();
    this.initialize();
  }

  public static getInstance(): UnifiedPredictionService {
    if (!UnifiedPredictionService.instance) {
      UnifiedPredictionService.instance = new UnifiedPredictionService();
    }
    return UnifiedPredictionService.instance;
  }

  private initialize(): void {
    this.setupWebSocketHandlers();
    this.setupEventListeners();
  }

  private setupWebSocketHandlers(): void {
    this.wsService.on('prediction:update', (data: PredictionResult) => {
      this.handlePredictionUpdate(data);
    });

    this.wsService.subscribe('prediction:error', (error: any) => {
      this.errorHandler.handleError(error, 'UnifiedPredictionService', 'high');
    });
  }

  private setupEventListeners(): void {
    this.eventBus.on('risk:profile:updated', (profile: RiskProfile) => {
      this.recalculatePredictions(profile);
    });
  }

  private handlePredictionUpdate(prediction: PredictionResult): void {
    try {
      this.activePredictions.set(prediction.id, prediction);
      this.predictionSubscribers.forEach(callback => callback(prediction));
      this.performanceMonitor.trackMetric('prediction:update', {
        predictionId: prediction.id,
        confidence: prediction.confidence,
        riskScore: prediction.riskScore,
      });
    } catch (error) {
      this.errorHandler.handleError(error, 'UnifiedPredictionService', 'medium', {
        action: 'handlePredictionUpdate',
        predictionId: prediction.id,
      });
    }
  }

  private async recalculatePredictions(profile: RiskProfile): Promise<void> {
    try {
      const predictions = Array.from(this.activePredictions.values());
      for (const prediction of predictions) {
        const updatedPrediction = await this.recalculatePrediction(prediction, profile);
        this.handlePredictionUpdate(updatedPrediction);
      }
    } catch (error) {
      this.errorHandler.handleError(error, 'UnifiedPredictionService', 'high', {
        action: 'recalculatePredictions',
        profileId: profile.id,
      });
    }
  }

  private async recalculatePrediction(
    prediction: PredictionResult,
    profile: RiskProfile
  ): Promise<PredictionResult> {
    const startTime = performance.now();
    try {
      // Implement prediction recalculation logic based on risk profile
      const updatedPrediction = {
        ...prediction,
        riskScore: this.calculateRiskScore(prediction, profile),
        confidence: this.adjustConfidence(prediction, profile),
      };

      this.performanceMonitor.trackMetric('prediction:recalculation', {
        predictionId: prediction.id,
        duration: performance.now() - startTime,
      });

      return updatedPrediction;
    } catch (error) {
      this.errorHandler.handleError(error, 'UnifiedPredictionService', 'medium', {
        action: 'recalculatePrediction',
        predictionId: prediction.id,
      });
      return prediction;
    }
  }

  private calculateRiskScore(prediction: PredictionResult, profile: RiskProfile): number {
    // Implement risk score calculation based on prediction and profile
    const confidence = typeof prediction.confidence === 'number' ? prediction.confidence : 0;
    const riskToleranceLevel =
      typeof profile.riskToleranceLevel === 'number' ? profile.riskToleranceLevel : 0;
    const maxRiskScore = typeof profile.maxRiskScore === 'number' ? profile.maxRiskScore : 1;
    return Math.min(confidence * riskToleranceLevel, maxRiskScore);
  }

  private adjustConfidence(prediction: PredictionResult, profile: RiskProfile): number {
    // Implement confidence adjustment based on risk profile
    const confidence = typeof prediction.confidence === 'number' ? prediction.confidence : 0;
    const riskToleranceLevel =
      typeof profile.riskToleranceLevel === 'number' ? profile.riskToleranceLevel : 0;
    const minConfidenceThreshold =
      typeof profile.minConfidenceThreshold === 'number' ? profile.minConfidenceThreshold : 0;
    return Math.max(confidence * (1 - riskToleranceLevel * 0.2), minConfidenceThreshold);
  }

  public subscribeToPredictions(callback: (prediction: PredictionResult) => void): () => void {
    this.predictionSubscribers.add(callback);
    return () => this.predictionSubscribers.delete(callback);
  }

  public getActivePredictions(): PredictionResult[] {
    return Array.from(this.activePredictions.values());
  }

  public getPrediction(id: string): PredictionResult | undefined {
    return this.activePredictions.get(id);
  }
}

import { UnifiedLogger } from './UnifiedLogger';
import { UnifiedSettingsService } from './UnifiedSettingsService';
import { UnifiedErrorService } from './UnifiedErrorService';
import { UnifiedBackupService } from './UnifiedBackupService';
import { UnifiedServiceRegistry } from '../unified/UnifiedServiceRegistry';
import { promises as fs } from 'fs';
import path from 'path';
import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

interface DatabaseConfig {
  postgres?: {
    host: string;
    port: number;
    database: string;
    username: string;
    password: string;
  };
  redis?: {
    host: string;
    port: number;
    password: string;
  };
}

export interface RecoveryConfig {
  enabled: boolean;
  autoRecovery: boolean;
  maxRetries: number;
  retryDelay: number;
  backupVerification: boolean;
  healthCheckInterval: number;
}

export interface RecoveryResult {
  success: boolean;
  timestamp: number;
  component: string;
  action: string;
  error?: string;
  details?: any;
}

export class UnifiedRecoveryService {
  private static instance: UnifiedRecoveryService;
  private logger: UnifiedLogger;
  private settings: UnifiedSettingsService;
  private errorService: UnifiedErrorService;
  private backupService: UnifiedBackupService;
  private config: RecoveryConfig;
  private recoveryAttempts: Map<string, number>;

  private constructor(registry: UnifiedServiceRegistry) {
    this.logger = UnifiedLogger.getInstance();
    this.settings = UnifiedSettingsService.getInstance(registry);
    this.errorService = UnifiedErrorService.getInstance(registry);
    this.backupService = UnifiedBackupService.getInstance(registry);
    this.config = this.loadConfig();
    this.recoveryAttempts = new Map();
  }

  public static getInstance(registry: UnifiedServiceRegistry): UnifiedRecoveryService {
    if (!UnifiedRecoveryService.instance) {
      UnifiedRecoveryService.instance = new UnifiedRecoveryService(registry);
    }
    return UnifiedRecoveryService.instance;
  }

  private loadConfig(): RecoveryConfig {
    return {
      enabled: this.settings.get('recovery.enabled', true),
      autoRecovery: this.settings.get('recovery.autoRecovery', true),
      maxRetries: this.settings.get('recovery.maxRetries', 3),
      retryDelay: this.settings.get('recovery.retryDelay', 5000),
      backupVerification: this.settings.get('recovery.backupVerification', true),
      healthCheckInterval: this.settings.get('recovery.healthCheckInterval', 60000),
    };
  }

  public async performRecovery(component: string, action: string): Promise<RecoveryResult> {
    if (!this.config.enabled) {
      return {
        success: false,
        timestamp: Date.now(),
        component,
        action,
        error: 'Recovery service is disabled',
      };
    }

    const attemptKey = `${component}:${action}`;
    const attempts = (this.recoveryAttempts.get(attemptKey) || 0) + 1;
    this.recoveryAttempts.set(attemptKey, attempts);

    if (attempts > this.config.maxRetries) {
      return {
        success: false,
        timestamp: Date.now(),
        component,
        action,
        error: `Maximum recovery attempts (${this.config.maxRetries}) exceeded`,
      };
    }

    try {
      this.logger.info(`Starting recovery for ${component} (attempt ${attempts})`, 'recovery');

      // Verify latest backup
      if (this.config.backupVerification) {
        const backupPath = await this.getLatestBackup();
        if (backupPath) {
          const isValid = await this.backupService.verifyBackup(backupPath);
          if (!isValid) {
            throw new Error('Backup verification failed');
          }
        }
      }

      // Perform component-specific recovery
      const result = await this.recoverComponent(component, action);

      // Reset recovery attempts on success
      if (result.success) {
        this.recoveryAttempts.delete(attemptKey);
      }

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error(`Recovery failed: ${errorMessage}`, 'recovery');
      this.errorService.handleError(error, 'recovery', `${component}:${action}`);

      // Schedule retry if auto-recovery is enabled
      if (this.config.autoRecovery && attempts < this.config.maxRetries) {
        setTimeout(() => {
          this.performRecovery(component, action);
        }, this.config.retryDelay);
      }

      return {
        success: false,
        timestamp: Date.now(),
        component,
        action,
        error: errorMessage,
      };
    }
  }

  private async getLatestBackup(): Promise<string | null> {
    try {
      const backupDir = this.settings.get<string>('backup.path', './backups');
      const entries = await fs.readdir(backupDir);
      const backups = entries
        .filter(entry => entry.startsWith('backup_'))
        .sort()
        .reverse();

      return backups.length > 0 ? path.join(backupDir, backups[0]) : null;
    } catch (error) {
      this.logger.error('Failed to get latest backup', 'recovery');
      return null;
    }
  }

  private async recoverComponent(component: string, action: string): Promise<RecoveryResult> {
    switch (component) {
      case 'database':
        return this.recoverDatabase();
      case 'websocket':
        return this.recoverWebSocket();
      case 'api':
        return this.recoverAPI();
      case 'ml':
        return this.recoverML();
      default:
        throw new Error(`Unknown component: ${component}`);
    }
  }

  private async recoverDatabase(): Promise<RecoveryResult> {
    try {
      const dbConfig = this.settings.get<DatabaseConfig>('database', {});

      // Recover PostgreSQL
      if (dbConfig.postgres) {
        const { host, port, database, username, password } = dbConfig.postgres;
        const env = { ...process.env, PGPASSWORD: password };
        await execAsync(`pg_restore -h ${host} -p ${port} -U ${username} -d ${database} -c -v`, {
          env,
        });
      }

      // Recover Redis
      if (dbConfig.redis) {
        const { host, port, password } = dbConfig.redis;
        const env = { ...process.env, REDISCLI_AUTH: password };
        await execAsync(`redis-cli -h ${host} -p ${port} FLUSHALL`, { env });
      }

      return {
        success: true,
        timestamp: Date.now(),
        component: 'database',
        action: 'recovery',
      };
    } catch (error) {
      throw new Error(
        `Database recovery failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  private async recoverWebSocket(): Promise<RecoveryResult> {
    try {
      // Implement WebSocket recovery logic
      return {
        success: true,
        timestamp: Date.now(),
        component: 'websocket',
        action: 'recovery',
      };
    } catch (error) {
      throw new Error(
        `WebSocket recovery failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  private async recoverAPI(): Promise<RecoveryResult> {
    try {
      // Implement API recovery logic
      return {
        success: true,
        timestamp: Date.now(),
        component: 'api',
        action: 'recovery',
      };
    } catch (error) {
      throw new Error(
        `API recovery failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  private async recoverML(): Promise<RecoveryResult> {
    try {
      // Implement ML model recovery logic
      return {
        success: true,
        timestamp: Date.now(),
        component: 'ml',
        action: 'recovery',
      };
    } catch (error) {
      throw new Error(
        `ML recovery failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  public getRecoveryAttempts(component: string, action: string): number {
    return this.recoveryAttempts.get(`${component}:${action}`) || 0;
  }

  public resetRecoveryAttempts(component: string, action: string): void {
    this.recoveryAttempts.delete(`${component}:${action}`);
  }

  public clearAllRecoveryAttempts(): void {
    this.recoveryAttempts.clear();
  }
}

import UnifiedErrorService from './errorService';
import UnifiedNotificationService from './notificationService';
import UnifiedLoggingService from './loggingService';
import UnifiedSettingsService from './settingsService';
import { UnifiedServiceRegistry } from './UnifiedServiceRegistry';

export abstract class UnifiedServiceBase {
  protected readonly errorService: UnifiedErrorService;
  protected readonly notificationService: UnifiedNotificationService;
  protected readonly loggingService: UnifiedLoggingService;
  protected readonly settingsService: UnifiedSettingsService;
  protected readonly serviceRegistry: UnifiedServiceRegistry;

  protected constructor(serviceName: string, registry: UnifiedServiceRegistry) {
    this.serviceRegistry = registry;
    this.errorService = UnifiedErrorService.getInstance(registry);
    this.notificationService = UnifiedNotificationService.getInstance(registry);
    this.loggingService = UnifiedLoggingService.getInstance(registry);
    this.settingsService = UnifiedSettingsService.getInstance(registry);
    this.loggingService.info(`Initializing ${serviceName}`, serviceName);
  }

  protected async handleServiceOperation<T>(
    operation: () => Promise<T>,
    operationName: string,
    serviceName: string,
    successMessage?: string,
    errorMessage?: string
  ): Promise<T> {
    try {
      this.loggingService.debug(`Starting ${operationName}`, serviceName);
      const result = await operation();

      if (successMessage) {
        this.notificationService.notify('success', successMessage);
      }

      this.loggingService.info(`Completed ${operationName}`, serviceName);
      return result;
    } catch (error) {
      const errorMsg = errorMessage || `Failed to ${operationName}`;
      this.errorService.handleError(
        error instanceof Error ? error : new Error(errorMsg),
        serviceName,
        'high',
        { operation: operationName }
      );
      this.notificationService.notify('error', errorMsg);
      throw error;
    }
  }

  protected handleWebSocketError(error: any, serviceName: string, context?: any): void {
    this.errorService.handleError(
      error instanceof Error ? error : new Error('WebSocket error occurred'),
      serviceName,
      'high',
      { ...context, type: 'websocket' }
    );
  }

  protected logOperation(
    level: 'debug' | 'info' | 'warn' | 'error',
    message: string,
    serviceName: string,
    data?: any
  ): void {
    this.loggingService.log(level, message, serviceName, data);
  }

  // Lifecycle methods
  async initialize(): Promise<void> {
    this.loggingService.info(`Initializing service`, this.constructor.name);
  }

  async cleanup(): Promise<void> {
    this.loggingService.info(`Cleaning up service`, this.constructor.name);
  }

  // Cache management
  protected getCacheKey(...parts: (string | number)[]): string {
    return `${this.constructor.name}:${parts.join(':')}`;
  }

  // Service registry helpers
  protected getService<T>(name: string): T | undefined {
    return this.serviceRegistry.getService<T>(name);
  }

  protected emit(event: string, data: any): void {
    this.serviceRegistry.emit(event, data);
  }
}

import { BaseService } from './BaseService';
import { UnifiedServiceRegistry } from './UnifiedServiceRegistry';
import { UnifiedErrorService } from './UnifiedErrorService';

export interface AppState {
  user: {
    id: string;
    username: string;
    preferences: Record<string, any>;
  } | null;
  session: {
    id: string;
    startTime: number;
    lastActivity: number;
  } | null;
  notifications: {
    id: string;
    type: 'info' | 'success' | 'warning' | 'error';
    message: string;
    timestamp: number;
    read: boolean;
  }[];
  performance: {
    lastUpdate: number;
    metrics: Record<string, any>;
  };
  settings: {
    theme: 'light' | 'dark' | 'system';
    notifications: boolean;
    sound: boolean;
    language: string;
  };
}

export class UnifiedStateService extends BaseService {
  private errorService: UnifiedErrorService;
  private state: AppState;
  private readonly storageKey: string = 'app_state';
  private readonly persistState: boolean = true;

  constructor(registry: UnifiedServiceRegistry) {
    super('state', registry);
    this.errorService = registry.getService<UnifiedErrorService>('error');
    this.state = this.getInitialState();
    this.loadState();
  }

  private getInitialState(): AppState {
    return {
      user: null,
      session: null,
      notifications: [],
      performance: {
        lastUpdate: Date.now(),
        metrics: {},
      },
      settings: {
        theme: 'system',
        notifications: true,
        sound: true,
        language: 'en',
      },
    };
  }

  private loadState(): void {
    try {
      if (this.persistState) {
        const savedState = localStorage.getItem(this.storageKey);
        if (savedState) {
          this.state = JSON.parse(savedState);
        }
      }
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'STATE_ERROR',
        source: 'UnifiedStateService',
        details: { method: 'loadState' },
      });
    }
  }

  private saveState(): void {
    try {
      if (this.persistState) {
        localStorage.setItem(this.storageKey, JSON.stringify(this.state));
      }
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'STATE_ERROR',
        source: 'UnifiedStateService',
        details: { method: 'saveState' },
      });
    }
  }

  getState(): AppState {
    return { ...this.state };
  }

  setState(newState: Partial<AppState>): void {
    try {
      this.state = {
        ...this.state,
        ...newState,
      };
      this.saveState();
    } catch (error) {
      this.errorService.handleError(error, {
        code: 'STATE_ERROR',
        source: 'UnifiedStateService',
        details: { method: 'setState', newState },
      });
    }
  }

  updateUser(user: AppState['user']): void {
    this.setState({ user });
  }

  updateSession(session: AppState['session']): void {
    this.setState({ session });
  }

  addNotification(
    notification: Omit<AppState['notifications'][0], 'id' | 'timestamp' | 'read'>
  ): void {
    const newNotification = {
      ...notification,
      id: `notif_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      timestamp: Date.now(),
      read: false,
    };

    this.setState({
      notifications: [newNotification, ...this.state.notifications],
    });
  }

  markNotificationAsRead(notificationId: string): void {
    this.setState({
      notifications: this.state.notifications.map(notification =>
        notification.id === notificationId ? { ...notification, read: true } : notification
      ),
    });
  }

  clearNotifications(): void {
    this.setState({ notifications: [] });
  }

  updatePerformanceMetrics(metrics: Record<string, any>): void {
    this.setState({
      performance: {
        lastUpdate: Date.now(),
        metrics,
      },
    });
  }

  updateSettings(settings: Partial<AppState['settings']>): void {
    this.setState({
      settings: {
        ...this.state.settings,
        ...settings,
      },
    });
  }

  resetState(): void {
    this.state = this.getInitialState();
    this.saveState();
  }
}

import { EventEmitter } from 'events';
import { useAppStore } from '../../stores/appStore';
import { WSMessage, WebSocketConfig } from '../../types/core';

interface WebSocketConnection {
  socket: WebSocket;
  messageQueue: WSMessage[];
  isConnected: boolean;
  reconnectAttempts: number;
  heartbeatTimer?: NodeJS.Timeout;
}

export class WebSocketManager extends EventEmitter {
  private static instance: WebSocketManager;
  private connections: Map<string, WebSocketConnection>;
  private readonly defaultConfig: Required<WebSocketConfig>;

  private constructor() {
    super();
    this.connections = new Map();
    this.defaultConfig = {
      url: process.env.VITE_WS_URL || 'wss://api.betproai.com/ws',
      reconnectInterval: 1000,
      maxRetries: 5,
    };
  }

  public static getInstance(): WebSocketManager {
    if (!WebSocketManager.instance) {
      WebSocketManager.instance = new WebSocketManager();
    }
    return WebSocketManager.instance;
  }

  public connect(config: Partial<WebSocketConfig> = {}): void {
    const fullConfig = { ...this.defaultConfig, ...config };
    const userId = useAppStore.getState().user?.id;
    const clientId = userId || `anon_client_${Math.random().toString(36).substring(2, 10)}`;
    const wsUrl = `${fullConfig.url}?client_id=${encodeURIComponent(clientId)}`;

    if (this.connections.has(wsUrl)) {
      return;
    }

    const connection: WebSocketConnection = {
      socket: new WebSocket(wsUrl),
      messageQueue: [],
      isConnected: false,
      reconnectAttempts: 0,
    };

    this.setupSocketHandlers(connection, fullConfig);
    this.connections.set(wsUrl, connection);
  }

  private setupSocketHandlers(
    connection: WebSocketConnection,
    config: Required<WebSocketConfig>
  ): void {
    const { socket } = connection;

    socket.onopen = () => {
      connection.isConnected = true;
      connection.reconnectAttempts = 0;
      this.processMessageQueue(connection);
      this.setupHeartbeat(connection, config);
      this.emit('connected', config.url);
    };

    socket.onclose = () => {
      connection.isConnected = false;
      this.clearHeartbeat(connection);
      this.emit('disconnected', config.url);
      this.handleReconnect(connection, config);
    };

    socket.onerror = error => {
      this.emit('error', { url: config.url, error });
    };

    socket.onmessage = event => {
      try {
        const message = JSON.parse(event.data);
        this.emit('message', { url: config.url, message });
      } catch (error) {
        this.emit('error', {
          url: config.url,
          error: new Error('Failed to parse WebSocket message'),
        });
      }
    };
  }

  private setupHeartbeat(connection: WebSocketConnection, config: Required<WebSocketConfig>): void {
    connection.heartbeatTimer = setInterval(() => {
      if (connection.isConnected) {
        this.send(config.url, {
          type: 'ping',
          data: {},
          timestamp: Date.now(),
        });
      }
    }, config.reconnectInterval);
  }

  private clearHeartbeat(connection: WebSocketConnection): void {
    if (connection.heartbeatTimer) {
      clearInterval(connection.heartbeatTimer);
      connection.heartbeatTimer = undefined;
    }
  }

  private handleReconnect(
    connection: WebSocketConnection,
    config: Required<WebSocketConfig>
  ): void {
    if (connection.reconnectAttempts < config.maxRetries) {
      connection.reconnectAttempts++;
      setTimeout(
        () => {
          this.connect(config);
        },
        config.reconnectInterval * Math.pow(2, connection.reconnectAttempts - 1)
      );
    } else {
      this.emit('reconnect_failed', config.url);
    }
  }

  private processMessageQueue(connection: WebSocketConnection): void {
    while (connection.messageQueue.length > 0) {
      const message = connection.messageQueue.shift();
      if (message) {
        connection.socket.send(JSON.stringify(message));
      }
    }
  }

  public send(url: string, message: WSMessage): void {
    const connection = this.connections.get(url);
    if (!connection) {
      throw new Error(`No WebSocket connection found for URL: ${url}`);
    }

    if (connection.isConnected) {
      connection.socket.send(JSON.stringify(message));
    } else {
      connection.messageQueue.push(message);
    }
  }

  public disconnect(url: string): void {
    const connection = this.connections.get(url);
    if (connection) {
      this.clearHeartbeat(connection);
      connection.socket.close();
      this.connections.delete(url);
    }
  }

  public isConnected(url: string): boolean {
    return this.connections.get(url)?.isConnected ?? false;
  }

  public getConnectionStatus(): Record<string, boolean> {
    const status: Record<string, boolean> = {};
    Array.from(this.connections.entries()).forEach(([url, connection]) => {
      status[url] = connection.isConnected;
    });
    return status;
  }
}

