  public async getPerformanceBreakdown(): Promise<any> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/analytics/performance-breakdown`, {
        params: { window: this.config.metricsWindow },
      });
      return response.data;
    } catch (error) {
