      console.error('Error fetching risk analysis:', error);
      return {
        volatility: 0,
        sharpeRatio: 0,
        maxDrawdown: 0,
        valueAtRisk: 0,
        riskAdjustedReturn: 0,
      };
    }
  }

  public setConfig(newConfig: Partial<AnalyticsConfig>): void {
    this.config = { ...this.config, ...newConfig };
    this.clearCache();
  }

  public getConfig(): AnalyticsConfig {
    return { ...this.config };
  }

  private clearCache(): void {
    this.metricsCache.clear();
    this.lastUpdate = 0;
  }

  public isCacheValid(): boolean {
    if (!this.lastUpdate) return false;
    return Date.now() - this.lastUpdate < this.config.refreshInterval;
  }

  public async refreshData(): Promise<void> {
    await Promise.all([
      this.getBettingMetrics(),
      this.getModelPerformance(),
      this.getBettingStats(),
      this.getPerformanceBreakdown(),
      this.getRiskAnalysis(),
    ]);
  }
}

export default UnifiedAnalyticsService;

import UnifiedNotificationService from './notificationService';
import UnifiedSettingsService from './settingsService';

interface ErrorDetails {
  code: string;
  message: string;
  stack?: string;
  timestamp: number;
  source: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  context?: any;
}

interface ErrorConfig {
  logToConsole: boolean;
  showNotifications: boolean;
  reportToServer: boolean;
  maxStoredErrors: number;
  autoClearInterval: number;
}

class UnifiedErrorService {
  private static instance: UnifiedErrorService | null = null;
  private readonly notificationService: UnifiedNotificationService;
  private readonly settingsService: UnifiedSettingsService;
  private errors: ErrorDetails[] = [];
  private readonly STORAGE_KEY = 'esa_errors';
  private readonly MAX_ERRORS = 100;

  private config: ErrorConfig = {
    logToConsole: true,
    showNotifications: true,
    reportToServer: true,
    maxStoredErrors: 100,
    autoClearInterval: 24 * 60 * 60 * 1000, // 24 hours
  };

  protected constructor() {
    this.notificationService = UnifiedNotificationService.getInstance();
    this.settingsService = UnifiedSettingsService.getInstance();
    this.loadErrors();
    this.setupAutoClear();
  }

  public static getInstance(): UnifiedErrorService {
    if (!UnifiedErrorService.instance) {
      UnifiedErrorService.instance = new UnifiedErrorService();
    }
    return UnifiedErrorService.instance;
  }

  private loadErrors(): void {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        this.errors = JSON.parse(stored);
      }
    } catch (error) {
      console.error('Error loading stored errors:', error);
      this.errors = [];
    }
  }

  private saveErrors(): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.errors));
    } catch (error) {
      console.error('Error saving errors:', error);
    }
  }

  private setupAutoClear(): void {
    setInterval(() => {
      this.clearOldErrors(this.config.autoClearInterval);
    }, this.config.autoClearInterval);
  }

  public handleError(
    error: Error | string,
    source: string,
    severity: ErrorDetails['severity'] = 'medium',
    context?: any
  ): void {
    const errorDetails: ErrorDetails = {
      code: this.generateErrorCode(error),
      message: error instanceof Error ? error.message : error,
      stack: error instanceof Error ? error.stack : undefined,
      timestamp: Date.now(),
      source,
      severity,
      context,
    };

    // Store error
    this.errors.unshift(errorDetails);
    if (this.errors.length > this.config.maxStoredErrors) {
      this.errors = this.errors.slice(0, this.config.maxStoredErrors);
    }
    this.saveErrors();

    // Log to console if enabled
    if (this.config.logToConsole) {
      this.logToConsole(errorDetails);
    }

    // Show notification if enabled
    if (this.config.showNotifications) {
      this.showNotification(errorDetails);
    }

    // Report to server if enabled
    if (this.config.reportToServer) {
      this.reportToServer(errorDetails);
    }

    // Dispatch error event
    this.dispatchErrorEvent(errorDetails);
  }

  private generateErrorCode(error: Error | string): string {
    const prefix = 'ESA';
    const timestamp = Date.now().toString(36);
    const random = Math.random().toString(36).substring(2, 5);
    return `${prefix}-${timestamp}-${random}`;
  }

  private logToConsole(error: ErrorDetails): void {
    const isDebug = this.settingsService.isDebugMode();
    const logMethod = error.severity === 'critical' ? 'error' : 'warn';

    if (isDebug) {
      console[logMethod]('Error Details:', {
        code: error.code,
        message: error.message,
        source: error.source,
        severity: error.severity,
        context: error.context,
        stack: error.stack,
      });
    } else {
      console[logMethod](`[${error.code}] ${error.message}`);
    }
  }

  private showNotification(error: ErrorDetails): void {
    const message = `[${error.code}] ${error.message}`;
    const title = `Error in ${error.source}`;

    switch (error.severity) {
      case 'critical':
        this.notificationService.notify('error', message, title, error);
        break;
      case 'high':
        this.notificationService.notify('error', message, title, error);
        break;
      case 'medium':
        this.notificationService.notify('warning', message, title, error);
        break;
      case 'low':
        this.notificationService.notify('info', message, title, error);
        break;
    }
  }

  private async reportToServer(error: ErrorDetails): Promise<void> {
    try {
      const settings = this.settingsService.getSettings();
      const response = await fetch(`${settings.apiUrl}/api/errors`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(error),
      });

      if (!response.ok) {
        throw new Error('Failed to report error to server');
      }
    } catch (error) {
      console.error('Error reporting to server:', error);
    }
  }

  private dispatchErrorEvent(error: ErrorDetails): void {
    const event = new CustomEvent('error', {
      detail: error,
    });
    window.dispatchEvent(event);
  }

  public getErrors(): ErrorDetails[] {
    return [...this.errors];
  }

  public getErrorsBySeverity(severity: ErrorDetails['severity']): ErrorDetails[] {
    return this.errors.filter(error => error.severity === severity);
  }

  public getErrorsBySource(source: string): ErrorDetails[] {
    return this.errors.filter(error => error.source === source);
  }

  public clearErrors(): void {
    this.errors = [];
    this.saveErrors();
  }

  public clearOldErrors(maxAge: number): void {
    const cutoff = Date.now() - maxAge;
    this.errors = this.errors.filter(error => error.timestamp > cutoff);
    this.saveErrors();
  }

  public updateConfig(config: Partial<ErrorConfig>): void {
    this.config = { ...this.config, ...config };
  }

  public getConfig(): ErrorConfig {
    return { ...this.config };
  }
}

export default UnifiedErrorService;

import UnifiedSettingsService from './settingsService';
import UnifiedErrorService from './errorService';

interface LogEntry {
  id: string;
  level: 'debug' | 'info' | 'warn' | 'error';
  message: string;
  timestamp: number;
  source: string;
  data?: any;
  tags?: string[];
}

interface LogConfig {
  enabled: boolean;
  minLevel: LogEntry['level'];
  maxEntries: number;
  persistToStorage: boolean;
  consoleOutput: boolean;
  serverOutput: boolean;
  autoClearInterval: number;
  tags: string[];
}

class UnifiedLoggingService {
  private static instance: UnifiedLoggingService | null = null;
  private readonly settingsService: UnifiedSettingsService;
  private readonly errorService: UnifiedErrorService;
  private logs: LogEntry[] = [];
  private readonly STORAGE_KEY = 'esa_logs';
  private readonly MAX_LOGS = 1000;

  private config: LogConfig = {
    enabled: true,
    minLevel: 'info',
    maxEntries: 1000,
    persistToStorage: true,
    consoleOutput: true,
    serverOutput: true,
    autoClearInterval: 24 * 60 * 60 * 1000, // 24 hours
    tags: ['app', 'user', 'betting', 'prediction', 'analytics'],
  };

  protected constructor() {
    this.settingsService = UnifiedSettingsService.getInstance();
    this.errorService = UnifiedErrorService.getInstance();
    this.loadLogs();
    this.setupAutoClear();
  }

  public static getInstance(): UnifiedLoggingService {
    if (!UnifiedLoggingService.instance) {
      UnifiedLoggingService.instance = new UnifiedLoggingService();
    }
    return UnifiedLoggingService.instance;
  }

  private loadLogs(): void {
    if (!this.config.persistToStorage) return;

    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        this.logs = JSON.parse(stored);
      }
    } catch (error: unknown) {
      this.errorService.handleError(
        error instanceof Error ? error : new Error('Failed to load logs'),
        'LoggingService',
        'low',
        { action: 'loadLogs' }
      );
      this.logs = [];
    }
  }

  private saveLogs(): void {
    if (!this.config.persistToStorage) return;

    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.logs));
    } catch (error: unknown) {
      this.errorService.handleError(
        error instanceof Error ? error : new Error('Failed to save logs'),
        'LoggingService',
        'low',
        { action: 'saveLogs' }
      );
    }
  }

  private setupAutoClear(): void {
    setInterval(() => {
      this.clearOldLogs(this.config.autoClearInterval);
    }, this.config.autoClearInterval);
  }

  private createLogEntry(
    level: LogEntry['level'],
    message: string,
    source: string,
    data?: any,
    tags?: string[]
  ): LogEntry {
    return {
      id: this.generateLogId(),
      level,
      message,
      timestamp: Date.now(),
      source,
      data,
      tags: tags || [],
    };
  }

  private generateLogId(): string {
    return `LOG-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;
  }

  private shouldLog(level: LogEntry['level']): boolean {
    if (!this.config.enabled) return false;

    const levels: LogEntry['level'][] = ['debug', 'info', 'warn', 'error'];
    const minLevelIndex = levels.indexOf(this.config.minLevel);
    const currentLevelIndex = levels.indexOf(level);

    return currentLevelIndex >= minLevelIndex;
  }

  private logToConsole(entry: LogEntry): void {
    if (!this.config.consoleOutput) return;

    const isDebug = this.settingsService.isDebugMode();
    const logMethod = entry.level === 'error' ? 'error' : entry.level;

    if (isDebug) {
      console[logMethod]('Log Entry:', {
        id: entry.id,
        level: entry.level,
        message: entry.message,
        source: entry.source,
        timestamp: new Date(entry.timestamp).toISOString(),
        data: entry.data,
        tags: entry.tags,
      });
    } else {
      console[logMethod](`[${entry.source}] ${entry.message}`);
    }
  }

  private async logToServer(entry: LogEntry): Promise<void> {
    if (!this.config.serverOutput) return;

    try {
      const settings = this.settingsService.getSettings();
      const response = await fetch(`${settings.apiUrl}/api/logs`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(entry),
      });

      if (!response.ok) {
        throw new Error('Failed to send log to server');
      }
    } catch (error: unknown) {
      this.errorService.handleError(
        error instanceof Error ? error : new Error('Failed to send log to server'),
        'LoggingService',
        'low',
        { action: 'logToServer', logEntry: entry }
      );
    }
  }

  public log(
    level: LogEntry['level'],
    message: string,
    source: string,
    data?: any,
    tags?: string[]
  ): void {
    if (!this.shouldLog(level)) return;

    const entry = this.createLogEntry(level, message, source, data, tags);

    // Store log
    this.logs.unshift(entry);
    if (this.logs.length > this.config.maxEntries) {
      this.logs = this.logs.slice(0, this.config.maxEntries);
    }
    this.saveLogs();

    // Output log
    this.logToConsole(entry);
    this.logToServer(entry);

    // Dispatch log event
    this.dispatchLogEvent(entry);
  }

  private dispatchLogEvent(entry: LogEntry): void {
    const event = new CustomEvent('log', {
      detail: entry,
    });
    window.dispatchEvent(event);
  }

  public debug(message: string, source: string, data?: any, tags?: string[]): void {
    this.log('debug', message, source, data, tags);
  }

  public info(message: string, source: string, data?: any, tags?: string[]): void {
    this.log('info', message, source, data, tags);
  }

  public warn(message: string, source: string, data?: any, tags?: string[]): void {
    this.log('warn', message, source, data, tags);
  }

  public error(message: string, source: string, data?: any, tags?: string[]): void {
    this.log('error', message, source, data, tags);
  }

  public getLogs(): LogEntry[] {
    return [...this.logs];
  }

  public getLogsByLevel(level: LogEntry['level']): LogEntry[] {
    return this.logs.filter(log => log.level === level);
  }

  public getLogsBySource(source: string): LogEntry[] {
    return this.logs.filter(log => log.source === source);
  }

  public getLogsByTag(tag: string): LogEntry[] {
    return this.logs.filter(log => log.tags?.includes(tag));
  }

  public clearLogs(): void {
    this.logs = [];
    this.saveLogs();
  }

  public clearOldLogs(maxAge: number): void {
    const cutoff = Date.now() - maxAge;
    this.logs = this.logs.filter(log => log.timestamp > cutoff);
    this.saveLogs();
  }

  public updateConfig(config: Partial<LogConfig>): void {
    this.config = { ...this.config, ...config };
  }

  public getConfig(): LogConfig {
    return { ...this.config };
  }
}

export default UnifiedLoggingService;

import { toast, ToastOptions } from 'react-toastify';
import UnifiedSettingsService from './settingsService';

interface NotificationConfig {
  position: 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left';
  autoClose: number;
  hideProgressBar: boolean;
  closeOnClick: boolean;
  pauseOnHover: boolean;
  draggable: boolean;
  progress: number | undefined;
}

interface Notification {
  id: string;
  type: 'info' | 'success' | 'warning' | 'error';
  message: string;
  title?: string;
  timestamp: number;
  read: boolean;
  data?: any;
}

class UnifiedNotificationService {
  private static instance: UnifiedNotificationService | null = null;
  private readonly settingsService: UnifiedSettingsService;
  private notifications: Notification[] = [];
  private readonly STORAGE_KEY = 'esa_notifications';
  private readonly MAX_NOTIFICATIONS = 100;

  private defaultConfig: NotificationConfig = {
    position: 'top-right',
    autoClose: 5000,
    hideProgressBar: false,
    closeOnClick: true,
    pauseOnHover: true,
    draggable: true,
    progress: undefined,
  };

  protected constructor() {
    this.settingsService = UnifiedSettingsService.getInstance();
    this.loadNotifications();
  }

  public static getInstance(): UnifiedNotificationService {
    if (!UnifiedNotificationService.instance) {
      UnifiedNotificationService.instance = new UnifiedNotificationService();
    }
    return UnifiedNotificationService.instance;
  }

  private loadNotifications(): void {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        this.notifications = JSON.parse(stored);
      }
    } catch (error) {
      console.error('Error loading notifications:', error);
      this.notifications = [];
    }
  }

  private saveNotifications(): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.notifications));
    } catch (error) {
      console.error('Error saving notifications:', error);
    }
  }

  private createNotification(
    type: Notification['type'],
    message: string,
    title?: string,
    data?: any
  ): Notification {
    return {
      id: Date.now().toString(),
      type,
      message,
      title,
      timestamp: Date.now(),
      read: false,
      data,
    };
  }

  private showToast(notification: Notification, options?: ToastOptions): void {
    const config = { ...this.defaultConfig, ...options };

    switch (notification.type) {
      case 'success':
        toast.success(notification.message, config);
        break;
      case 'error':
        toast.error(notification.message, config);
        break;
      case 'warning':
        toast.warning(notification.message, config);
        break;
      default:
        toast.info(notification.message, config);
    }
  }

  public notify(
    type: Notification['type'],
    message: string,
    title?: string,
    data?: any,
    options?: ToastOptions
  ): void {
    const preferences = this.settingsService.getPreferences();

    // Check if notifications are enabled
    if (!preferences.notifications.enabled) {
      return;
    }

    // Create and store notification
    const notification = this.createNotification(type, message, title, data);
    this.notifications.unshift(notification);

    // Trim notifications if exceeding max limit
    if (this.notifications.length > this.MAX_NOTIFICATIONS) {
      this.notifications = this.notifications.slice(0, this.MAX_NOTIFICATIONS);
    }

    // Save notifications
    this.saveNotifications();

    // Show toast if appropriate
    if (preferences.notifications.desktop) {
      this.showToast(notification, options);
    }

    // Dispatch notification event
    this.dispatchNotificationEvent(notification);
  }

  private dispatchNotificationEvent(notification: Notification): void {
    const event = new CustomEvent('notification', {
      detail: notification,
    });
    window.dispatchEvent(event);
  }

  public getNotifications(): Notification[] {
    return [...this.notifications];
  }

  public getUnreadNotifications(): Notification[] {
    return this.notifications.filter(n => !n.read);
  }

  public markAsRead(id: string): void {
    const notification = this.notifications.find(n => n.id === id);
    if (notification) {
      notification.read = true;
      this.saveNotifications();
    }
  }

  public markAllAsRead(): void {
    this.notifications.forEach(n => (n.read = true));
    this.saveNotifications();
  }

  public clearNotifications(): void {
    this.notifications = [];
    this.saveNotifications();
  }

  public clearOldNotifications(maxAge: number): void {
    const cutoff = Date.now() - maxAge;
    this.notifications = this.notifications.filter(n => n.timestamp > cutoff);
    this.saveNotifications();
  }

  public getNotificationCount(): number {
    return this.notifications.length;
  }

  public getUnreadCount(): number {
    return this.notifications.filter(n => !n.read).length;
  }

  public updateConfig(config: Partial<NotificationConfig>): void {
    this.defaultConfig = { ...this.defaultConfig, ...config };
  }
}

export default UnifiedNotificationService;

import { BettingOpportunity, BookOdds } from '../../types/betting';
import axios from 'axios';
import type { ModelPrediction } from '../../types/prediction';
import { toast } from 'react-toastify';

// Core interfaces
export interface WeatherCondition {
  temperature: number;
  windSpeed: number;
  precipitation: number;
  humidity: number;
  windDirection: number;
}

export interface InjuryReport {
  playerId: string;
  playerName: string;
  position: string;
  status: 'OUT' | 'DOUBTFUL' | 'QUESTIONABLE' | 'PROBABLE';
  details: string;
  impactScore: number;
}

export interface SentimentData {
  source: 'TWITTER' | 'NEWS' | 'REDDIT';
  sentiment: number;
  volume: number;
  keywords: string[];
  timestamp: number;
}

export interface PredictionResult {
  predictedValue: number;
  confidence: number;
  factors: PredictionFactor[];
  metadata: Record<string, any>;
  kellyValue: number;
  marketEdge: number;
  shapValues: Record<string, number>;
}

export interface PredictionFactor {
  name: string;
  impact: number;
  confidence: number;
  description: string;
  metadata: Record<string, any>;
}

export interface WeatherData {
  temperature: number;
  windSpeed: number;
  precipitation: number;
  humidity: number;
  conditions: string;
}

export interface HistoricalPattern {
  pattern: string;
  similarity: number;
  outcome: string;
  confidence: number;
  metadata: {
    matchCount: number;
    winRate: number;
    averageOddsMovement: number;
  };
}

interface ModelWeights {
  [key: string]: number;
}

interface PredictionConfig {
  minConfidence: number;
  maxStakePercentage: number;
  riskProfile: 'conservative' | 'moderate' | 'aggressive';
  autoRefresh: boolean;
  refreshInterval: number;
}

interface ModelOutput {
  type: string;
  prediction: number;
  confidence: number;
  shapValues: Record<string, number>;
}

interface Prediction {
  id: string;
  timestamp: string;
  prediction: number;
  confidence: number;
  shapValues: Record<string, number>;
  kellyValue: number;
  marketEdge: number;
}

class UnifiedPredictionService {
  private static instance: UnifiedPredictionService | null = null;
  private weatherCache: Map<string, WeatherData>;
  private injuryCache: Map<string, InjuryReport[]>;
  private sentimentCache: Map<string, SentimentData[]>;
  private modelWeights: ModelWeights = {
    xgboost: 0.3,
    lightgbm: 0.25,
    catboost: 0.2,
    neuralNetwork: 0.15,
    randomForest: 0.1,
  };

  private config: PredictionConfig = {
    minConfidence: 0.7,
    maxStakePercentage: 0.1,
    riskProfile: 'moderate',
    autoRefresh: true,
    refreshInterval: 30000,
  };

  private readonly apiUrl: string;
  private readonly wsUrl: string;

  protected constructor() {
    this.weatherCache = new Map();
    this.injuryCache = new Map();
    this.sentimentCache = new Map();
    this.apiUrl = process.env.VITE_API_URL || 'http://localhost:8000';
    this.wsUrl = process.env.VITE_WS_URL || 'ws://localhost:8000';
  }

  public static getInstance(): UnifiedPredictionService {
    if (!UnifiedPredictionService.instance) {
      UnifiedPredictionService.instance = new UnifiedPredictionService();
    }
    return UnifiedPredictionService.instance;
  }

  public async analyzePredictionFactors(
    opportunity: BettingOpportunity
  ): Promise<PredictionFactor[]> {
    const factors: PredictionFactor[] = [];

    // Parallel execution of factor analysis
    const [injuryFactors, weatherFactor, sentimentFactor, patternFactors] = await Promise.all([
      this.analyzeInjuryImpact(opportunity),
      this.analyzeWeatherImpact(opportunity),
      this.analyzeSentiment(opportunity),
      this.findHistoricalPatterns(opportunity),
    ]);

    factors.push(...injuryFactors);
    if (weatherFactor) factors.push(weatherFactor);
    factors.push(sentimentFactor);
    factors.push(...patternFactors);

    return this.normalizePredictionFactors(factors);
  }

  private async analyzeInjuryImpact(opportunity: BettingOpportunity): Promise<PredictionFactor[]> {
    const injuries = this.injuryCache.get(opportunity.event_name) || [];
    return injuries
      .filter(injury => injury.impactScore > 0.3)
      .map(injury => ({
        name: 'Injury Impact',
        impact: -injury.impactScore,
        confidence: this.calculateInjuryConfidence(injury),
        description: `${injury.playerName} (${injury.position}) - ${injury.status}`,
        metadata: {
          playerId: injury.playerId,
          status: injury.status,
          position: injury.position,
        },
      }));
  }

  private calculateInjuryConfidence(injury: InjuryReport): number {
    const statusConfidence = {
      OUT: 1,
      DOUBTFUL: 0.75,
      QUESTIONABLE: 0.5,
      PROBABLE: 0.25,
    };

    return statusConfidence[injury.status] * injury.impactScore;
  }

  private async analyzeWeatherImpact(
    opportunity: BettingOpportunity
  ): Promise<PredictionFactor | null> {
    const weather = this.weatherCache.get(opportunity.event_name);
    if (!weather) return null;

    const impact = this.calculateWeatherImpact(weather);
    if (Math.abs(impact) < 0.2) return null;

    return {
      name: 'Weather Conditions',
      impact,
      confidence: 0.8,
      description: `${weather.conditions} - ${weather.temperature}°F, Wind: ${weather.windSpeed}mph`,
      metadata: { ...weather },
    };
  }

  private calculateWeatherImpact(weather: WeatherData): number {
    let impact = 0;

    if (weather.windSpeed > 15) {
      impact -= (weather.windSpeed - 15) / 30;
    }

    if (weather.precipitation > 0) {
      impact -= weather.precipitation / 10;
    }

    const optimalTemp = 70;
    const tempDiff = Math.abs(weather.temperature - optimalTemp);
    if (tempDiff > 30) {
      impact -= (tempDiff - 30) / 50;
    }

    return Math.max(-1, Math.min(1, impact));
  }

  private async analyzeSentiment(opportunity: BettingOpportunity): Promise<PredictionFactor> {
    const sentimentData = this.sentimentCache.get(opportunity.event_name) || [];

    if (sentimentData.length === 0) {
      return {
        name: 'Market Sentiment',
        impact: 0,
        confidence: 0,
        description: 'No sentiment data available',
        metadata: { dataPoints: 0 },
      };
    }

    const recentSentiment = sentimentData
      .filter(data => Date.now() - data.timestamp < 24 * 60 * 60 * 1000)
      .reduce((acc, data) => acc + data.sentiment * data.volume, 0);

    const totalVolume = sentimentData.reduce((acc, data) => acc + data.volume, 0);
    const averageSentiment = totalVolume > 0 ? recentSentiment / totalVolume : 0;

    return {
      name: 'Market Sentiment',
      impact: averageSentiment,
      confidence: Math.min(1, totalVolume / 1000),
      description: `Average sentiment: ${averageSentiment.toFixed(2)}`,
      metadata: {
        dataPoints: sentimentData.length,
        keywords: this.aggregateKeywords(sentimentData),
      },
    };
  }

  private aggregateKeywords(sentimentData: SentimentData[]): string[] {
    const keywordCounts = new Map<string, number>();
    sentimentData.forEach(data => {
      data.keywords.forEach(keyword => {
        keywordCounts.set(keyword, (keywordCounts.get(keyword) || 0) + 1);
      });
    });

    return Array.from(keywordCounts.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([keyword]) => keyword);
  }

  private async findHistoricalPatterns(
    opportunity: BettingOpportunity
  ): Promise<PredictionFactor[]> {
    const patterns = await this.findSimilarHistoricalScenarios(opportunity);
    return patterns.map(pattern => ({
      name: 'Historical Pattern',
      impact: this.calculatePatternImpact(pattern),
      confidence: pattern.confidence,
      description: `Pattern: ${pattern.pattern} (${(pattern.similarity * 100).toFixed(1)}% similar)`,
      metadata: pattern.metadata,
    }));
  }

  private async findSimilarHistoricalScenarios(
    opportunity: BettingOpportunity
  ): Promise<HistoricalPattern[]> {
    try {
      const response = await axios.post(`${this.apiUrl}/api/predictions/historical-patterns`, {
        market: opportunity.event_name,
        odds: opportunity.odds,
        timestamp: opportunity.start_time,
      });
      return response.data.patterns;
    } catch (error) {
      console.error('Error finding historical patterns:', error);
      return [];
    }
  }

  private calculatePatternImpact(pattern: HistoricalPattern): number {
    return pattern.similarity * (pattern.metadata.winRate - 0.5) * 2;
  }

  private normalizePredictionFactors(factors: PredictionFactor[]): PredictionFactor[] {
    const totalConfidence = factors.reduce((sum, factor) => sum + factor.confidence, 0);
    return factors.map(factor => ({
      ...factor,
      impact: factor.impact * (factor.confidence / totalConfidence),
    }));
  }

  public async getPredictions(eventId: string): Promise<ModelPrediction[]> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/predictions/${eventId}`);
      return this.processPredictions(response.data);
    } catch (error) {
      console.error('Error fetching predictions:', error);
      toast.error('Failed to fetch predictions');
      return [];
    }
  }

  private processPredictions(rawPredictions: any[]): ModelPrediction[] {
    return rawPredictions.map(prediction => ({
      ...prediction,
      confidence: this.calculateConfidence(prediction),
      timeDecay: this.calculateTimeDecay(prediction.timestamp),
      performanceFactor: this.calculatePerformanceFactor(prediction.performance),
    }));
  }

  private calculateConfidence(prediction: any): number {
    const baseConfidence = prediction.confidence || 0.5;
    const modelWeight = this.modelWeights[prediction.modelType] || 0.2;
    return baseConfidence * modelWeight;
  }

  private calculateTimeDecay(timestamp: string): number {
    const age = Date.now() - new Date(timestamp).getTime();
    return Math.exp(-age / (24 * 60 * 60 * 1000)); // 24-hour decay
  }

  private calculatePerformanceFactor(performance: any): number {
    return performance?.accuracy || 0.5;
  }

  public async updateModelWeights(performance: { [key: string]: number }): Promise<void> {
    const totalPerformance = Object.values(performance).reduce((sum, val) => sum + val, 0);
    Object.keys(performance).forEach(model => {
      this.modelWeights[model] = performance[model] / totalPerformance;
    });
  }

  public setConfig(newConfig: Partial<PredictionConfig>): void {
    this.config = { ...this.config, ...newConfig };
  }

  public getConfig(): PredictionConfig {
    return { ...this.config };
  }

  public async getRecentPredictions(): Promise<Prediction[]> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/predictions/recent`);
      return response.data;
    } catch (error) {
      console.error('Error fetching recent predictions:', error);
      return [];
    }
  }

  public async generatePrediction(modelOutputs: ModelOutput[]): Promise<Prediction | null> {
    try {
      const response = await axios.post(`${this.apiUrl}/api/predictions/generate`, {
        modelOutputs,
        config: this.config,
      });
      return response.data;
    } catch (error) {
      console.error('Error generating prediction:', error);
      return null;
    }
  }

  public async getEngineMetrics(): Promise<any> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/predictions/metrics`);
      return response.data;
    } catch (error) {
      console.error('Error fetching engine metrics:', error);
      return null;
    }
  }

  public async getModelPerformance(modelType: string): Promise<any> {
    try {
      const response = await axios.get(
        `${this.apiUrl}/api/predictions/model-performance/${modelType}`
      );
      return response.data;
    } catch (error) {
      console.error('Error fetching model performance:', error);
      return null;
    }
  }

  public async getFeatureImportance(modelType: string): Promise<Record<string, number>> {
    try {
      const response = await axios.get(
        `${this.apiUrl}/api/predictions/feature-importance/${modelType}`
      );
      return response.data;
    } catch (error) {
      console.error('Failed to fetch feature importance:', error);
      return {};
    }
  }

  public async getShapValues(eventId: string): Promise<Record<string, number>> {
    try {
      const response = await axios.get(`${this.apiUrl}/api/predictions/shap-values/${eventId}`);
      return response.data;
    } catch (error) {
      console.error('Failed to fetch SHAP values:', error);
      return {};
    }
  }

  // Cache management methods
  public updateWeatherData(market: string, data: WeatherData): void {
    this.weatherCache.set(market, data);
  }

  public updateInjuryData(market: string, data: InjuryReport[]): void {
    this.injuryCache.set(market, data);
  }

  public updateSentimentData(market: string, data: SentimentData): void {
    const existingData = this.sentimentCache.get(market) || [];
    this.sentimentCache.set(market, [...existingData, data]);
  }

  public clearCaches(): void {
    this.weatherCache.clear();
    this.injuryCache.clear();
    this.sentimentCache.clear();
  }
}

export default UnifiedPredictionService;

import { unifiedMonitor } from '../../core/UnifiedMonitor';
// import { APIError, AppError } from '../../core/UnifiedError'; // File does not exist, use UnifiedErrorService if needed

// Error handling utilities
export const handleApiError = (error: any, context: string): never => {
  const trace = unifiedMonitor.startTrace(`error.${context}`, 'error');

  if (trace) {
    trace.setHttpStatus(error.response?.status || 500);
    unifiedMonitor.endTrace(trace);
  }

  if (error instanceof APIError) throw error;
  if (error instanceof AppError) throw error;

  throw new AppError(`Error in ${context}`, error.response?.status || 500, { context }, error);
};

// Data transformation utilities
export const transformData = <T, R>(data: T, transformer: (data: T) => R, context: string): R => {
  try {
    return transformer(data);
  } catch (error) {
    handleApiError(error, `${context}.transform`);
  }
};

// Validation utilities
export const validateResponse = <T>(
  response: any,
  validator: (data: any) => data is T,
  context: string
): T => {
  if (!validator(response)) {
    throw new AppError(`Invalid response in ${context}`, 500, { response, context });
  }
  return response;
};

// Cache utilities
const cache = new Map<string, { data: any; timestamp: number }>();
const DEFAULT_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

export const getCachedData = <T>(key: string, ttl: number = DEFAULT_CACHE_TTL): T | null => {
  const cached = cache.get(key);
  if (!cached) return null;

  const now = Date.now();
  if (now - cached.timestamp > ttl) {
    cache.delete(key);
    return null;
  }

  return cached.data as T;
};

export const setCachedData = <T>(key: string, data: T): void => {
  cache.set(key, {
    data,
    timestamp: Date.now(),
  });
};

export const clearCache = (key?: string): void => {
  if (key) {
    cache.delete(key);
  } else {
    cache.clear();
  }
};

// Retry utilities
export const retry = async <T>(
  fn: () => Promise<T>,
  options: {
    maxAttempts?: number;
    delay?: number;
    backoff?: number;
    context?: string;
  } = {}
): Promise<T> => {
  const { maxAttempts = 3, delay = 1000, backoff = 2, context = 'retry' } = options;

  let lastError: any;
  let currentDelay = delay;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === maxAttempts) break;

      const trace = unifiedMonitor.startTrace(`retry.${context}.attempt${attempt}`, 'retry');
      if (trace) {
        trace.setHttpStatus(error.response?.status || 500);
        unifiedMonitor.endTrace(trace);
      }

      await new Promise(resolve => setTimeout(resolve, currentDelay));
      currentDelay *= backoff;
    }
  }

  throw lastError;
};

// Rate limiting utilities
const rateLimits = new Map<string, { count: number; resetTime: number }>();

export const checkRateLimit = (key: string, limit: number, window: number): boolean => {
  const now = Date.now();
  const current = rateLimits.get(key);

  if (!current || now > current.resetTime) {
    rateLimits.set(key, { count: 1, resetTime: now + window });
    return true;
  }

  if (current.count >= limit) {
    return false;
  }

  current.count++;
  return true;
};

// Logging utilities
export const logServiceCall = (
  service: string,
  method: string,
  params?: any,
  result?: any,
  error?: any
): void => {
  const trace = unifiedMonitor.startTrace(`${service}.${method}`, 'service');

  if (trace) {
    if (error) {
      trace.setHttpStatus(error.response?.status || 500);
      unifiedMonitor.captureException(error, {
        extra: {
          service,
          method,
          params,
          result,
        },
      });
    } else {
      trace.setHttpStatus(200);
    }
    unifiedMonitor.endTrace(trace);
  }
};

// Performance monitoring utilities
export const measurePerformance = async <T>(fn: () => Promise<T>, context: string): Promise<T> => {
  const start = performance.now();
  try {
    const result = await fn();
    const duration = performance.now() - start;

    const trace = unifiedMonitor.startTrace(`performance.${context}`, 'performance');
    if (trace) {
      trace.setDuration(duration);
      unifiedMonitor.endTrace(trace);
    }

    return result;
  } catch (error) {
    const duration = performance.now() - start;

    const trace = unifiedMonitor.startTrace(`performance.${context}.error`, 'performance');
    if (trace) {
      trace.setDuration(duration);
      trace.setHttpStatus(error.response?.status || 500);
      unifiedMonitor.endTrace(trace);
    }

    throw error;
  }
};

