  toggleSidebar: () => void;
  setActiveModal: (modalId: string | null) => void;
  bets: BetRecord[];
  addBet: (bet: BetRecord) => void;
  updateBet: (betId: string, updates: Partial<BetRecord>) => void;
  removeBet: (betId: string) => void;
}

const useStore = create<AppState>()(
  devtools(
    persist(
      set => ({
        // Initial State
        user: null,
        props: [],
        selectedProps: [],
        entries: [],
        metrics: null,
        opportunities: [],
        alerts: [],
        darkMode: false,
        sidebarOpen: true,
        activeModal: null,
        bets: [],

        // Auth Actions
        login: async (email: string, password: string) => {
          try {
            // TODO: Replace with actual API call
            const response = await fetch('/api/auth/login', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ email, password }),
            });

            if (!response.ok) {
              throw new Error('Invalid credentials');
            }

            const user = await response.json();
            set({ user });
          } catch (error) {
            throw error;
          }
        },

        register: async (name: string, email: string, password: string) => {
          try {
            // TODO: Replace with actual API call
            const response = await fetch('/api/auth/register', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ name, email, password }),
            });

            if (!response.ok) {
              throw new Error('Registration failed');
            }

            const user = await response.json();
            set({ user });
          } catch (error) {
            throw error;
          }
        },

        logout: () => set({ user: null }),

        // Actions
        setProps: props => set({ props }),

        togglePropSelection: propId =>
          set(state => ({
            selectedProps: state.selectedProps.includes(propId)
              ? state.selectedProps.filter(id => id !== propId)
              : [...state.selectedProps, propId],
          })),

        addEntry: entry =>
          set(state => ({
            entries: [...state.entries, entry],
          })),

        updateEntry: (entryId, updates) =>
          set(state => ({
            entries: state.entries.map(entry =>
              entry.id === entryId ? { ...entry, ...updates } : entry
            ),
          })),

        setMetrics: metrics => set({ metrics }),

        addOpportunity: opportunity =>
          set(state => ({
            opportunities: [...state.opportunities, opportunity],
          })),

        removeOpportunity: opportunityId =>
          set(state => ({
            opportunities: state.opportunities.filter(opp => opp.id !== opportunityId),
          })),

        addAlert: alert =>
          set(state => ({
            alerts: [...state.alerts, alert],
          })),

        removeAlert: alertId =>
          set(state => ({
            alerts: state.alerts.filter(alert => alert.id !== alertId),
          })),

        toggleDarkMode: () =>
          set(state => ({
            darkMode: !state.darkMode,
          })),

        toggleSidebar: () =>
          set(state => ({
            sidebarOpen: !state.sidebarOpen,
