const API_BASE_URL = import.meta.env.VITE_API_URL;
const BETTING_BACKEND_PREFIX = `${API_BASE_URL}/api/betting`;

// --- Backend Type Definitions (mirroring Pydantic models from betting_route.py) ---
interface BackendBetLeg {
    prop_id: string;
    market_key: string;
    outcome: string;
    odds: number;
    player_id?: string;
    game_id?: string;
