import { measurePerformance } from './PerformanceMonitor.ts';

export interface StrategyContext {
  timestamp: number;
  environment: string;
  parameters: StrategyParameters;
}

type StrategyParameters = Record<string, string | number | boolean | object>;

export interface StrategyComponent<T, U> {
  id: string;
  name: string;
  version: string;
  priority: number;
  dependencies: string[];
  evaluate(input: T, context: StrategyContext): Promise<U>;
  validate?(input: T): Promise<boolean>;
  canHandle(input: T): boolean;
}

export interface StrategyResult<T> {
  id: string;
  timestamp: number;
  duration: number;
  data: T;
  confidence: number;
  metadata: {
    strategy: string;
    version: string;
    parameters: Record<string, string | number | boolean | object>;
  };
  metrics: {
    accuracy: number;
    reliability: number;
    performance: number;
  };
}

export class StrategyRegistry {
  private static instance: StrategyRegistry;
  private readonly strategies: Map<string, StrategyComponent<unknown, unknown>>;
  private readonly eventBus: EventBus;
  private readonly performanceMonitor: PerformanceMonitor;

  private constructor() {
    this.strategies = new Map();
    this.eventBus = EventBus.getInstance();
    this.performanceMonitor = PerformanceMonitor.getInstance();
  }

  static getInstance(): StrategyRegistry {
    if (!StrategyRegistry.instance) {
      StrategyRegistry.instance = new StrategyRegistry();
    }
    return StrategyRegistry.instance;
  }

  registerStrategy<T, U>(strategy: StrategyComponent<T, U>): void {
    if (this.strategies.has(strategy.id)) {
      throw new Error(`Strategy with ID ${strategy.id} is already registered`);
    }

    // Validate dependencies
    for (const depId of strategy.dependencies) {
      if (!this.strategies.has(depId)) {
        throw new Error(`Dependency ${depId} not found for strategy ${strategy.id}`);
      }
    }

    this.strategies.set(strategy.id, strategy);
    this.eventBus.publish({
      type: 'strategy:registered',
      payload: {
        strategyId: strategy.id,
        name: strategy.name,
        version: strategy.version,
        timestamp: Date.now()
      }
    });
  }

  async evaluate<T, U>(
    strategyId: string,
    input: T,
    context: StrategyContext
  ): Promise<StrategyResult<U>> {
    const strategy = this.strategies.get(strategyId) as StrategyComponent<T, U>;
    if (!strategy) {
      throw new Error(`Strategy ${strategyId} not found`);
    }

    const traceId = this.performanceMonitor.startTrace(`strategy-${strategy.id}`, {
      strategyId: strategy.id,
      version: strategy.version
    });

    try {
      if (!strategy.canHandle(input)) {
        throw new Error(`Strategy ${strategy.id} cannot handle the provided input`);
      }

      if (strategy.validate && !(await strategy.validate(input))) {
        throw new Error(`Input validation failed for strategy ${strategy.id}`);
      }

      const startTime = Date.now();
      const result = await strategy.evaluate(input, context);
      const duration = Date.now() - startTime;

      const metrics = this.calculateMetrics(result);
      const strategyResult: StrategyResult<U> = {
        id: `${strategy.id}-${startTime}`,
        timestamp: startTime,
        duration,
        data: result,
        confidence: this.calculateConfidence(result),
        metadata: {
          strategy: strategy.id,
          version: strategy.version,
          parameters: context.parameters
        },
        metrics
      };

      this.eventBus.publish({
        type: 'strategy:evaluated',
        payload: {
          strategyId: strategy.id,
          resultId: strategyResult.id,
          duration,
          metrics,
          timestamp: Date.now()
        }
      });

      this.performanceMonitor.endTrace(traceId);
      return strategyResult;
    } catch (error) {
      this.performanceMonitor.endTrace(traceId, error as Error);
      throw error;
    }
  }

  async evaluateWithPipeline<T, U>(
    strategies: string[],
    input: T,
    context: StrategyContext
  ): Promise<StrategyResult<U>> {
    const sortedStrategies = this.sortStrategiesByDependencies(strategies);
    let currentInput: unknown = input;
    let lastResult: StrategyResult<unknown> | null = null;

    for (const strategyId of sortedStrategies) {
      lastResult = await this.evaluate(strategyId, currentInput, {
        ...context,
        parameters: {
          ...context.parameters,
          previousResults: lastResult ? [lastResult] : []
        }
      });
      currentInput = lastResult.data;
    }

    return lastResult as StrategyResult<U>;
  }

  private sortStrategiesByDependencies(strategyIds: string[]): string[] {
    const graph = new Map<string, Set<string>>();
    const visited = new Set<string>();
    const sorted: string[] = [];

    // Build dependency graph
    for (const id of strategyIds) {
      const strategy = this.strategies.get(id);
      if (!strategy) continue;

      graph.set(id, new Set(strategy.dependencies));
    }

    // Topological sort
    const visit = (id: string) => {
      if (visited.has(id)) return;
      visited.add(id);

      const deps = graph.get(id) || new Set();
      for (const dep of deps) {
        visit(dep);
      }

      sorted.push(id);
    };

    for (const id of strategyIds) {
      visit(id);
    }

    return sorted;
  }

  private calculateConfidence(result: unknown): number {
    if (typeof result === 'object' && result !== null) {
      if ('confidence' in result) return result.confidence;
      if ('probability' in result) return result.probability;
      if ('score' in result) return result.score;
    }
    return 1;
  }

  private calculateMetrics(result: unknown): StrategyResult<unknown>['metrics'] {
    return {
      accuracy: this.calculateAccuracy(result),
      reliability: this.calculateReliability(result),
      performance: this.calculatePerformance(result)
    };
  }

  private calculateAccuracy(result: unknown): number {
    if (typeof result === 'object' && result !== null) {
      if ('accuracy' in result) return result.accuracy;
      if ('confidence' in result) return result.confidence;
    }
    return 1;
  }

  private calculateReliability(result: unknown): number {
    if (typeof result === 'object' && result !== null) {
      if ('reliability' in result) return result.reliability;
      if ('stability' in result) return result.stability;
    }
    return 1;
  }

  private calculatePerformance(result: unknown): number {
    if (typeof result === 'object' && result !== null) {
      if ('performance' in result) return result.performance;
      if ('efficiency' in result) return result.efficiency;
    }
    return 1;
  }

  getStrategy<T, U>(strategyId: string): StrategyComponent<T, U> | undefined {
    return this.strategies.get(strategyId) as StrategyComponent<T, U>;
  }

  listStrategies(): Array<{ id: string; name: string; version: string }> {
    return Array.from(this.strategies.values()).map(s => ({
      id: s.id,
      name: s.name,
      version: s.version
    }));
  }
}

export class ComposableStrategy<T, U> implements StrategyComponent<T, U> {
  constructor(
    public readonly id: string,
    public readonly name: string,
    public readonly version: string,
    public readonly priority: number,
    public readonly dependencies: string[],
    private readonly evaluator: (input: T, context: StrategyContext) => Promise<U>,
    private readonly validator?: (input: T) => Promise<boolean>,
    private readonly handler?: (input: T) => boolean
  ) {}

  async evaluate(input: T, context: StrategyContext): Promise<U> {
    return this.evaluator(input, context);
  }

  async validate(input: T): Promise<boolean> {
    if (this.validator) {
      return this.validator(input);
    }
    return true;
  }

  canHandle(input: T): boolean {
    if (this.handler) {
      return this.handler(input);
    }
    return true;
  }

  compose<V>(next: StrategyComponent<U, V>): StrategyComponent<T, V> {
    return new ComposableStrategy(
      `${this.id}->${next.id}`,
      `${this.name} -> ${next.name}`,
      `${this.version}+${next.version}`,
      Math.max(this.priority, next.priority),
      [...this.dependencies, ...next.dependencies],
      async (input: T, context: StrategyContext) => {
        const intermediate = await this.evaluate(input, context);
        return next.evaluate(intermediate, context);
      }
    );
  }
}

import { AdvancedAnalysisEngine, AnalysisResult as AdvancedAnalysisResult } from './AdvancedAnalysisEngine.js';
import { DataIntegrationHub, IntegratedData } from './DataIntegrationHub.js';
import { EventBus } from '../core/EventBus.ts';
import FeatureFlags from './FeatureFlags.ts';
import { PerformanceMetrics, StrategyRecommendation, RiskTolerance } from '../types/core.ts';
import { PerformanceMonitor } from './PerformanceMonitor.js';
import { PredictionEngine } from './PredictionEngine.js';



// All imports and usages of missing modules (AnalysisEngine, SentimentEngine) have been removed. Fallback logic is implemented where needed. See roadmap for tracking.


interface StrategyConfig {
  maxExposure: number;
  minStake: number;
  maxStake: number;
  kellyFraction: number;
  volatilityThreshold: number;
  liquidityThreshold: number;
  depthThreshold: number;
  momentumThreshold: number;
  marginOfError: number;
  stopLossPercentage: number;
  takeProfitPercentage: number;
  hedgingThreshold: number;
  maxVolatility: number;
  minLiquidity: number;
  minValueGap: number;
  sentimentThreshold: number;
  minConfidence: number;
  maxRiskLevel: RiskTolerance;
  requiredDataQuality: number;
  marketEfficiencyThreshold: number;
}

interface StrategyPerformance {
  totalExecutions: number;
  successRate: number;
  averageReturn: number;
  riskProfile: {
    level: RiskTolerance;
    factors: string[];
  };
  lastUpdated: number;
}

interface CompositeStrategy {
  id: string;
  name: string;
  strategies: string[];
  weights: number[];
  performance: StrategyPerformance;
  conditions: {
    minConfidence: number;
    maxRisk: RiskTolerance;
    marketStates: string[];
  };
}

interface StrategyState {
  bankroll: number;
  activeBets: Map<string, BettingPosition>;
  performance: PerformanceMetrics;
}

interface BettingPosition {
  id: string;
  type: 'OVER' | 'UNDER';
  stake: number;
  odds: number;
  timestamp: number;
  status: 'pending' | 'active' | 'closed';
}

interface MarketData {
  playerId: string;
  metric: string;
  currentLine: number;
  movement: string;
  valueGap: number;
  volatility: number;
  liquidity: number;
  marketDepth: number;
  momentum: number;
}

interface SentimentAnalysis {
  score: number;
  trend: string;
  keyFactors: string[];
}

interface StrategyEvaluatedPayload {
  strategyId: string;
  result: StrategyRecommendation;
}

function toRiskTolerance(level: string): RiskTolerance {
  switch (level) {
    case 'LOW': return 'low';
    case 'MEDIUM': return 'medium';
    case 'HIGH': return 'high';
    default: return level as RiskTolerance;
  }
}

export class StrategyEngine {
  private static instance: StrategyEngine;
  private readonly eventBus: EventBus;
  private readonly performanceMonitor: PerformanceMonitor;
  private readonly featureManager: FeatureFlags;
  private readonly analysisEngine: AdvancedAnalysisEngine;
  private readonly dataHub: DataIntegrationHub;
  private readonly config: StrategyConfig;
  private readonly state: StrategyState;
  private readonly predictionEngine: PredictionEngine;
  private readonly strategyPerformance: Map<string, StrategyPerformance>;
  private readonly PERFORMANCE_UPDATE_INTERVAL = 1000 * 60 * 60; // 1 hour
  private compositeStrategies: Map<string, CompositeStrategy>;

  private constructor() {
    this.eventBus = EventBus.getInstance();
    this.performanceMonitor = PerformanceMonitor.getInstance();
    this.featureManager = FeatureFlags.getInstance();
    this.analysisEngine = AdvancedAnalysisEngine.getInstance();
    this.dataHub = DataIntegrationHub.getInstance();
    this.config = this.getDefaultConfig();
    this.state = this.getDefaultState();
    this.compositeStrategies = new Map();
    this.strategyPerformance = new Map();
    this.predictionEngine = PredictionEngine.getInstance();
    this.setupPerformanceTracking();
  }

  static getInstance(): StrategyEngine {
    if (!StrategyEngine.instance) {
      StrategyEngine.instance = new StrategyEngine();
    }
    return StrategyEngine.instance;
  }

  private getDefaultConfig(): StrategyConfig {
    return {
      maxExposure: 100,
      minStake: 10,
      maxStake: 100,
      kellyFraction: 0.5,
      volatilityThreshold: 0.5,
      liquidityThreshold: 0.5,
      depthThreshold: 0.5,
      momentumThreshold: 0.5,
      marginOfError: 0.05,
      stopLossPercentage: 0.1,
      takeProfitPercentage: 0.2,
      hedgingThreshold: 0.1,
      maxVolatility: 1.5,
      minLiquidity: 0.5,
      minValueGap: 0.1,
      sentimentThreshold: 0.6,
      minConfidence: 0.7,
      maxRiskLevel: 'medium',
      requiredDataQuality: 0.8,
      marketEfficiencyThreshold: 0.85
    };
  }

  private getDefaultState(): StrategyState {
    return {
      bankroll: 1000,
      activeBets: new Map(),
      performance: {
        totalBets: 0,
        winRate: 0,
        roi: 0,
        averageOdds: 0,
        profitLoss: 0,
        latency: [],
        throughput: 0,
        errorRate: 0,
        resourceUsage: {
          cpu: 0,
          memory: 0,
          network: 0
        },
        streakData: {
          current: 0,
          longest: {
            wins: 0,
            losses: 0
          }
        }
      }
    };
  }

  private setupPerformanceTracking(): void {
    setInterval(() => this.updateStrategyPerformance(), this.PERFORMANCE_UPDATE_INTERVAL);

    this.eventBus.on('strategy:execution-completed', (event: any) => {
      const { strategyId, result } = event.payload as StrategyEvaluatedPayload;
      this.updateStrategyResult(strategyId, result);
    });
  }

  public createCompositeStrategy(
    name: string,
    strategies: string[],
    weights: number[],
    conditions: CompositeStrategy['conditions']
  ): string {
    if (strategies.length !== weights.length) {
      throw new Error('Strategies and weights arrays must have the same length');
    }

    if (Math.abs(weights.reduce((a, b) => a + b, 0) - 1) > 0.0001) {
      throw new Error('Weights must sum to 1');
    }

    const id = `composite-${Date.now()}`;
    this.compositeStrategies.set(id, {
      id,
      name,
      strategies,
      weights,
      conditions,
      performance: {
        totalExecutions: 0,
        successRate: 0,
        averageReturn: 0,
        riskProfile: {
          level: 'low',
          factors: []
        },
        lastUpdated: Date.now()
      }
    });

    return id;
  }

  public async analyzeOpportunity(
    playerId: string,
    metric: string
  ): Promise<StrategyRecommendation | null> {
    const traceId = this.performanceMonitor.startTrace('strategy-analysis');

    try {
      const analysis = await this.analysisEngine.analyzePlayer(playerId);
      if (!this.meetsQualityThresholds(analysis)) {
        return null;
      }

      const data = this.dataHub.getIntegratedData();
      const baseRecommendation = await this.generateRecommendation(
        playerId,
        metric,
        analysis,
        data
      );

      if (!baseRecommendation) {
        return null;
      }

      // Apply composite strategies if available
      const enhancedRecommendation = await this.applyCompositeStrategies(
        baseRecommendation,
        analysis,
        data
      );

      this.performanceMonitor.endTrace(traceId);
      return enhancedRecommendation;
    } catch (error) {
      this.performanceMonitor.endTrace(traceId, error as Error);
      throw error;
    }
  }

  private meetsQualityThresholds(analysis: AdvancedAnalysisResult): boolean {
    return (
      analysis.meta_analysis.data_quality >= this.config.requiredDataQuality &&
      analysis.meta_analysis.market_efficiency >= this.config.marketEfficiencyThreshold
    );
  }

  private async generateRecommendation(
    playerId: string,
    metric: string,
    analysis: AdvancedAnalysisResult,
    data: IntegratedData
  ): Promise<StrategyRecommendation | null> {
    const prediction = analysis.predictions[metric];
    if (!prediction || prediction.confidence < this.config.minConfidence) {
      return null;
    }

    const marketData = this.analyzeMarketData(playerId, metric, data);
    const sentiment = this.analyzeSentiment(playerId, data);
    const valueGap = this.calculateValueGap(marketData);

    if (Math.abs(valueGap) < this.config.minValueGap) {
      return null;
    }

    const position = valueGap > 0 ? 'over' : 'under';
    const riskAssessment = this.assessRisk(marketData, analysis);

    if (this.getRiskLevel(toRiskTolerance(String(riskAssessment.riskLevel))) > this.getRiskLevel(toRiskTolerance(this.config.maxRiskLevel))) {
      return null;
    }

    return {
      id: `strategy-${Date.now()}`,
      type: position.toUpperCase() as 'OVER' | 'UNDER',
      confidence: prediction.confidence,
      parameters: {
        stake: 0, // TODO: Calculate recommended stake
        expectedValue: this.calculateExpectedValue(valueGap, prediction.confidence),
      },
      riskAssessment,
      analysis: {
        historicalTrends: this.analyzeHistoricalTrends(playerId, metric, data),
        marketSignals: this.analyzeMarketSignals(playerId, metric, data),
        riskFactors: this.analyzeRiskFactors(playerId, metric, data),
      },
      propId: `${playerId}:${metric}`
    };
  }

  private analyzeMarketData(
    playerId: string,
    metric: string,
    data: IntegratedData
  ): MarketData {
    const relevantMarkets = this.findRelevantMarkets(playerId, metric, data);
    let currentLine = 0;
    let movement = 'stable';
    let valueGap = 0;
    if (relevantMarkets && Object.keys(relevantMarkets).length > 0) {
      currentLine = this.calculateWeightedLine(relevantMarkets);
      movement = this.analyzeMarketMovement(relevantMarkets, data);
      valueGap = this.calculateMarketValueGap(currentLine, data.projections[playerId]?.stats[metric]);
    }
    return {
      playerId,
      metric,
      currentLine,
      movement,
      valueGap,
      volatility: 0,
      liquidity: 0,
      marketDepth: 0,
      momentum: 0
    };
  }

  private findRelevantMarkets(
    playerId: string,
    metric: string,
    data: IntegratedData
  ): Record<string, number> | null {
    const markets: Record<string, number> = {};
    
    Object.entries(data.odds).forEach(([eventId, odds]) => {
      Object.entries(odds.markets).forEach(([market, price]) => {
        if (this.isMarketRelevant(market, playerId, metric)) {
          markets[market] = price;
        }
      });
    });

    return Object.keys(markets).length > 0 ? markets : null;
  }

  private isMarketRelevant(market: string, playerId: string, metric: string): boolean {
    const marketLower = market.toLowerCase();
    const metricLower = metric.toLowerCase();
    const playerLower = playerId.toLowerCase();

    return (
      marketLower.includes(playerLower) &&
      marketLower.includes(metricLower)
    );
  }

  private calculateWeightedLine(markets: Record<string, number>): number {
    const prices = Object.values(markets);
    if (prices.length === 0) return 0;
    
    // Simple average for now, could be enhanced with volume-weighted average
    return prices.reduce((a, b) => a + b, 0) / prices.length;
  }

  private analyzeMarketMovement(
    markets: Record<string, number>,
    data: IntegratedData
  ): string {
    const movements = Object.keys(markets).map(market => {
      const eventId = this.findEventIdForMarket(market, data);
      if (!eventId) return 'stable';
      
      const odds = data.odds[eventId];
      return odds?.movement.direction ?? 'stable';
    });

    const upCount = movements.filter(m => m === 'up').length;
    const downCount = movements.filter(m => m === 'down').length;

    if (Math.abs(upCount - downCount) < 2) return 'stable';
    return upCount > downCount ? 'increasing' : 'decreasing';
  }

  private findEventIdForMarket(market: string, data: IntegratedData): string | null {
    for (const [eventId, odds] of Object.entries(data.odds)) {
      if (market in odds.markets) {
        return eventId;
      }
    }
    return null;
  }

  private calculateMarketValueGap(currentLine: number, projectedValue?: number): number {
    if (!projectedValue) return 0;
    return projectedValue - currentLine;
  }

  private analyzeSentiment(
    playerId: string,
    data: IntegratedData
  ): string {
    const sentiment = data.sentiment[playerId];
    if (!sentiment) {
      return `${playerId}:unknown:0:neutral:[]`;
    }
    return `${playerId}:${sentiment.sentiment.score}:${this.determineSentimentTrend(sentiment)}:${sentiment.keywords.join(',')}`;
  }

  private calculateValueGap(marketData: MarketData): number {
    return marketData.valueGap;
  }

  private assessRisk(
    marketData: MarketData,
    analysis: AdvancedAnalysisResult
  ): StrategyRecommendation['riskAssessment'] {
    const riskLevel = this.calculateRiskLevel(marketData, analysis);
    const riskFactors = this.identifyRiskFactors(marketData, analysis);

    return {
      level: riskLevel as unknown,
      factors: riskFactors
    };
  }

  private calculateRiskLevel(marketData: MarketData, analysis: AdvancedAnalysisResult): RiskTolerance {
    const volatility = marketData.volatility;
    const liquidity = marketData.liquidity;
    const marketDepth = marketData.marketDepth;

    const riskScore = (volatility * 0.4) + ((1 - liquidity) * 0.3) + ((1 - marketDepth) * 0.3);

    if (riskScore < 0.3) return 'low';
    if (riskScore < 0.7) return 'medium';
    return 'high';
  }

  private identifyRiskFactors(marketData: MarketData, analysis: AdvancedAnalysisResult): string[] {
    const factors: string[] = [];

    if (marketData.volatility > this.config.volatilityThreshold) {
      factors.push('High market volatility');
    }
    if (marketData.liquidity < this.config.liquidityThreshold) {
      factors.push('Low market liquidity');
    }
    if (marketData.marketDepth < this.config.depthThreshold) {
      factors.push('Insufficient market depth');
    }
    if (marketData.momentum < this.config.momentumThreshold) {
      factors.push('Weak market momentum');
    }

    // Add risks from analysis
    Object.entries(analysis.risks).forEach(([type, risk]) => {
      if (toRiskTolerance(risk.level) !== 'low') {
        factors.push(...risk.factors);
      }
    });

    return factors;
  }

  private calculateExpectedValue(valueGap: number, confidence: number): number {
    return Math.abs(valueGap) * confidence * (1 - this.config.marginOfError);
  }

  private determineSentimentTrend(
    sentiment: IntegratedData['sentiment'][string]
  ): string {
    const score = sentiment.sentiment.score;
    const volume = sentiment.sentiment.volume;
    
    if (volume < 100) return 'insufficient data';
    
    if (Math.abs(score) < 0.2) return 'neutral';
    if (Math.abs(score) < 0.5) return score > 0 ? 'slightly positive' : 'slightly negative';
    if (Math.abs(score) < 0.8) return score > 0 ? 'positive' : 'negative';
    return score > 0 ? 'strongly positive' : 'strongly negative';
  }

  private getRiskLevel(level: RiskTolerance): number {
    switch (level) {
      case 'low': return 1;
      case 'medium': return 2;
      case 'high': return 3;
    }
  }

  private async applyCompositeStrategies(
    baseRecommendation: StrategyRecommendation,
    analysis: AdvancedAnalysisResult,
    data: IntegratedData
  ): Promise<StrategyRecommendation> {
    const finalRecommendation = { ...baseRecommendation };
    const totalConfidence = 0;
    let totalWeight = 0;

    for (const [, composite] of this.compositeStrategies) {
      if (this.shouldApplyStrategy(composite, analysis, data)) {
        const strategyResults = await Promise.all(
          composite.strategies.map(async (strategyId, index) => {
            const result = await this.executeStrategy(
              strategyId,
              baseRecommendation,
              analysis,
              data
            );
            return {
              result,
              weight: composite.weights[index]
            };
          })
        );

        // Combine strategy results
        strategyResults.forEach(({ result, weight }) => {
          if (result) {
            finalRecommendation.confidence =
              (finalRecommendation.confidence * totalWeight + result.confidence * weight) /
              (totalWeight + weight);
            const resultEV = result.parameters?.expectedValue ?? 0;
            const finalEV = finalRecommendation.parameters?.expectedValue ?? 0;
            if (!finalRecommendation.parameters) finalRecommendation.parameters = { stake: 0, expectedValue: 0 };
            finalRecommendation.parameters.expectedValue =
              (finalEV * totalWeight + resultEV * weight) /
              (totalWeight + weight);
            totalWeight += weight;
          }
        });
      }
    }

    return finalRecommendation;
  }

  private shouldApplyStrategy(
    strategy: CompositeStrategy,
    analysis: AdvancedAnalysisResult,
    data: IntegratedData
  ): boolean {
    // Check confidence threshold
    if (analysis.meta_analysis.prediction_stability < strategy.conditions.minConfidence) {
      return false;
    }

    // Check risk level
    const maxRiskLevel = this.getRiskLevel(toRiskTolerance(strategy.conditions.maxRisk));
    const currentRisk = Object.values(analysis.risks).some(
      risk => this.getRiskLevel(toRiskTolerance(risk.level)) > maxRiskLevel
    );
    if (currentRisk) {
      return false;
    }

    // Check market state conditions
    const marketState = this.determineMarketState(data);
    if (!strategy.conditions.marketStates.includes(marketState)) {
      return false;
    }

    return true;
  }


  private async executeStrategy(
    strategyId: string,
    baseRecommendation: StrategyRecommendation,
    analysis: AdvancedAnalysisResult,
    data: IntegratedData
  ): Promise<StrategyRecommendation | null> {
    // Example: Adjust recommendation based on risk and market signals
    let rec = { ...baseRecommendation };
    // Type guard: only act if riskAssessment exists and has a 'level' property
    if ((analysis as any).riskAssessment && (analysis as any).riskAssessment.level === 'high') {
      rec.confidence *= 0.8;
      // rec.parameters = { ...rec.parameters, adjusted: true }; // 'adjusted' not in type, skip or document for roadmap
    }
    // Type guard: only act if analysis property exists and has marketSignals
    if ((analysis as any).analysis && Array.isArray((analysis as any).analysis.marketSignals) && (analysis as any).analysis.marketSignals.includes('sharp_move')) {
      rec.confidence *= 0.9;
    }
    // Add more logic as needed
    return rec;
  }


  private determineMarketState(data: IntegratedData): string {
    // Simple example: use volatility and trend
    // volatility and trend not present on IntegratedData; skip or document for roadmap
    return 'stable';
  }

  private analyzeHistoricalTrends(playerId: string, metric: string, data: IntegratedData): string[] {
    // Example: return trend signals based on data
    // trend property not present on IntegratedData; skip or document for roadmap
    return [];
    return ['flat'];
  }

  private analyzeMarketSignals(playerId: string, metric: string, data: IntegratedData): string[] {
    // Example: detect sharp moves or volume spikes
    const signals = [];
    // volume and priceChange not present on IntegratedData; skip or document for roadmap
    return signals;
  }

  private analyzeRiskFactors(playerId: string, metric: string, data: IntegratedData): string[] {
    // Example: flag high volatility or missing data
    const factors = [];
    if (!data /* || !data.history */) factors.push('missing_data');
    // volatility not present on IntegratedData; skip or document for roadmap
    return factors;
  }

  private updateStrategyResult(strategyId: string, result: StrategyRecommendation): void {
    const performance = this.strategyPerformance.get(strategyId) || {
      totalExecutions: 0,
      successRate: 0,
      averageReturn: 0,
      riskProfile: {
        level: 'low',
        factors: []
      },
      lastUpdated: Date.now()
    };

    // Update performance metrics
    performance.totalExecutions++;
    performance.lastUpdated = Date.now();

    this.strategyPerformance.set(strategyId, performance);

    // Adjust composite strategy weights based on performance
    this.adjustStrategyWeights();
  }

  private adjustStrategyWeights(): void {
    for (const [id, composite] of this.compositeStrategies) {
      const performances = composite.strategies.map(
        strategyId => this.strategyPerformance.get(strategyId)
      );

      if (performances.some(p => !p)) continue;

      // Calculate new weights based on relative performance
      const totalPerformance = performances.reduce(
        (sum, p) => sum + (p!.averageReturn * p!.successRate),
        0
      );

      const newWeights = performances.map(
        p => (p!.averageReturn * p!.successRate) / totalPerformance
      );

      // Update weights
      this.compositeStrategies.set(id, {
        ...composite,
        weights: newWeights
      });
    }
  }

  private updateStrategyPerformance(): void {
    for (const [strategyId, performance] of this.strategyPerformance) {
      if (Date.now() - performance.lastUpdated > this.PERFORMANCE_UPDATE_INTERVAL) {
        // Recalculate long-term performance metrics
        this.recalculatePerformanceMetrics(strategyId);
      }
    }
  }

  private recalculatePerformanceMetrics(strategyId: string): void {
