import React, { Suspense } from 'react';

interface LazyLoadProps {
  fallback?: React.ReactNode;
}

export const lazyLoad = (
  importFunc: () => Promise<{ default: React.ComponentType<any> }>,
  fallback: React.ReactNode = null
) => {
  const LazyComponent = React.lazy(importFunc);

  return (props: any) => (
    <Suspense fallback={fallback}>
      <LazyComponent {...props} />
    </Suspense>
  );
};

import type { EntryStatus, LineupType, PropType } from './common';
import type { PlayerProp, Entry } from './core';



/**
 * Convert American odds to decimal format
 */
export const oddsToDecimal = (odds: string): number => {
  const numOdds = parseInt(odds);
  if (numOdds > 0) {
    return (numOdds / 100) + 1;
  } else {
    return (-100 / numOdds) + 1;
  }
};

/**
 * Calculate potential payout for a parlay bet
 */
export const calculatePotentialPayout = (entry: number, odds: string[]): number => {
  const decimalOdds = odds.map(oddsToDecimal);
  const totalOdds = decimalOdds.reduce((acc, curr) => acc * curr, 1);
  return Math.round(entry * totalOdds * 100) / 100;
};

/**
 * Calculate win probability based on historical percentages
 */
export const calculateWinProbability = (percentages: number[]): number => {
  if (!percentages.length) return 0;
  const combinedProbability = percentages.reduce((acc, curr) => acc * (curr / 100), 1);
  return Math.round(combinedProbability * 100);
};

/**
 * Generate a random odds change for simulation
 */
export const generateRandomOddsChange = (currentOdds: string): string => {
  const change = Math.random() > 0.5 ? 5 : -5;
  const numOdds = parseInt(currentOdds);
  
  if (numOdds > 0) {
    return Math.max(100, numOdds + change).toString();
  } else {
    return Math.min(-100, numOdds - change).toString();
  }
};

/**
 * Format currency values
 */
export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(amount);
};

/**
 * Calculate progress percentage
 */
export const calculateProgressPercentage = (current: number, target: number): number => {
  if (target === 0) return 0;
  const percentage = (current / target) * 100;
  return Math.min(100, Math.max(0, percentage));
};

/**
 * Calculate implied probability from odds
 */
export const calculateImpliedProbability = (odds: string): number => {
  const numOdds = parseInt(odds);
  if (numOdds > 0) {
    return Math.round((100 / (numOdds + 100)) * 100);
  } else {
    return Math.round((-numOdds / (-numOdds + 100)) * 100);
  }
};

/**
 * Calculate Kelly Criterion bet size
 */
export const calculateKellyBet = (
  bankroll: number,
  probability: number,
  odds: string
): number => {
  const decimalOdds = oddsToDecimal(odds);
  const impliedProb = 1 / decimalOdds;
  const edge = (probability / 100) - impliedProb;
  
  if (edge <= 0) return 0;
  
  const fraction = (edge * decimalOdds) / (decimalOdds - 1);
  const kellyBet = bankroll * Math.min(fraction, 0.1); // Cap at 10% of bankroll
  
  return Math.round(kellyBet * 100) / 100;
};

// Convert American odds to decimal odds
export const americanToDecimal = (americanOdds: number): number => {
  if (americanOdds > 0) {
    return (americanOdds / 100) + 1;
  } else {
    return (100 / Math.abs(americanOdds)) + 1;
  }
};

// Convert decimal odds to American odds
export const decimalToAmerican = (decimalOdds: number): number => {
  if (decimalOdds >= 2) {
    return (decimalOdds - 1) * 100;
  } else {
    return -100 / (decimalOdds - 1);
  }
};

// Calculate implied probability from decimal odds
export const calculateImpliedProbabilityDecimal = (decimalOdds: number): number => {
  return 1 / decimalOdds;
};

interface WinFactors {
  form?: number;
  weather?: number;
  rest?: number;
}

// Calculate win probability based on various factors
export const calculateWinProbabilityFactors = (
  prop: PlayerProp,
  factors: WinFactors
): number => {
  const baseProb = prop.confidence / 100;
  
  // Apply weights to different factors
  let adjustedProb = baseProb;
  
  if (factors.form) {
    adjustedProb *= (1 + (factors.form - 0.5) * 0.2);
  }
  
  if (factors.weather) {
    adjustedProb *= (1 + factors.weather * 0.1);
  }
  
  if (factors.rest) {
    adjustedProb *= (1 + factors.rest * 0.15);
  }
  
  // Ensure probability is between 0 and 1
  return Math.min(Math.max(adjustedProb, 0), 1);
};

// Calculate Kelly Criterion bet size
export const calculateKellyCriterion = (
  probability: number,
  decimalOdds: number,
  bankroll: number,
  fraction: number = 1
): number => {
  const q = 1 - probability;
  const b = decimalOdds - 1;
  
  const kelly = (b * probability - q) / b;
  
  // Apply fractional Kelly (default: full Kelly)
  return Math.max(0, kelly * fraction * bankroll);
};

// Calculate parlay odds
export const calculateParlayOdds = (decimalOdds: number[]): number => {
  return decimalOdds.reduce((acc, odds) => acc * odds, 1);
};

// Calculate potential payout
export const calculatePotentialPayoutDecimal = (
  stake: number,
  odds: number,
  type: 'american' | 'decimal' = 'american'
): number => {
  const decimalOdds = type === 'american' ? americanToDecimal(odds) : odds;
  return stake * decimalOdds;
};

// Format currency
export const formatCurrencyDecimal = (amount: number): string => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
};

// Format percentage
export const formatPercentage = (value: number): string => {
  return `${(value * 100).toFixed(1)}%`;
};

// Calculate risk level multiplier
export const getRiskMultiplier = (type: LineupType): number => {
  switch (type) {
    case LineupType.SINGLE:
      return 0.5;
    case LineupType.PARLAY:
      return 2;
    case LineupType.TEASER:
    default:
      return 1;
  }
};

// Calculate entry progress
export const calculateEntryProgress = (entry: Entry): number => {
  if (entry.status !== EntryStatus.PENDING) {
    return entry.status === EntryStatus.WON ? 100 : 0;
  }

  const totalProgress = entry.props.reduce((acc, prop) => {
    // In a real app, this would use live game data
    // For now, we'll generate a random progress
    const progress = Math.random() * 100;
    return acc + progress;
  }, 0);

  return Math.round(totalProgress / entry.props.length);
};

// Format odds for display
export const formatOdds = (odds: number, format: 'american' | 'decimal' = 'american'): string => {
  if (format === 'decimal') {
    return odds.toFixed(2);
  }
  
  const oddsString = odds > 0 ? `+${odds}` : odds.toString();
  return oddsString;
};

// Calculate arbitrage opportunity
export const calculateArbitrage = (
  odds1: number,
  odds2: number,
  stake: number
): { profit: number; split: [number, number] } | null => {
  const decimal1 = americanToDecimal(odds1);
  const decimal2 = americanToDecimal(odds2);
  
  const prob1 = 1 / decimal1;
  const prob2 = 1 / decimal2;
  
  const totalProb = prob1 + prob2;
  
  if (totalProb < 1) {
    const stake1 = (stake * prob1) / totalProb;
    const stake2 = (stake * prob2) / totalProb;
    
    const payout1 = stake1 * decimal1;
    const payout2 = stake2 * decimal2;
    
    const profit = Math.min(payout1, payout2) - stake;
    
    return {
      profit,
      split: [stake1, stake2],
    };
  }
  
  return null;
};

// Calculate value rating (0-100)
export const calculateValueRating = (
  impliedProbability: number,
  modelProbability: number
): number => {
  const edge = modelProbability - impliedProbability;
  // Convert edge to 0-100 scale with diminishing returns
  return Math.min(100, Math.round(edge * 200));
};

/**
 * Utility functions for custom performance and metric tracking using Sentry.
 * Provides tracing, custom metrics, and tagging for frontend observability.
 */
/**
 * Utility functions for custom performance and metric tracking using Sentry.
 * Provides tracing, custom metrics, and tagging for frontend observability.
 */
import * as Sentry from "@sentry/react";

/**
 * Type for Sentry Span (compatible with Sentry v7+).
 */
type Span = ReturnType<typeof Sentry.startTransaction> | Sentry.Span | undefined;

/**
 * PerformanceTrackingService
 *
 * Provides utility functions to instrument custom performance monitoring
 * using Sentry. This allows for detailed tracing of application-specific
 * operations and collection of custom metrics.
 */
class PerformanceTrackingService {
  /**
   * Tracks currently active spans by name.
   * Used to manage and finish spans that are started via startTrace.
   */
  private activeSpans: Map<string, Sentry.Span> = new Map();

  /**
   * Starts a new Sentry transaction/span for a specific operation.
   * In Sentry v7+, transactions are used for top-level traces.
   *
   * The created span is stored in the `activeSpans` map by its `name`.
   * If a span with the same name already exists, it will be overwritten.
   *
   * @param name A descriptive name for the span (e.g., 'user_login_flow', 'load_dashboard_data').
   * @param op An operation name, often a category (e.g., 'ui.load', 'api.request', 'function').
   * @param description Optional longer description for the span.
   */
  public startTrace(name: string, op: string, description?: string): Sentry.Span | undefined {
    try {
      const transaction = Sentry.startTransaction({
        name,
        op,
        description,
      });

      if (transaction) {
        this.activeSpans.set(name, transaction);
      }

      return transaction;
    } catch (error) {
      console.warn('[PerformanceTrackingService] Could not start trace:', error);
      return undefined;
    }
  }

  /**
   * Adds a child span to an active Sentry span.
   * Spans can be nested to measure individual operations.
   * @param parentSpan The parent Sentry Span object.
   * @param op The operation name for the child span.
   * @param description Optional description for the span.
   * @param data Optional data to attach as span attributes (key-value pairs for additional context).
   * @returns The Sentry Span object, or undefined if the parent span is invalid.
   */
  public addSpanToTrace(
    parentSpan: Sentry.Span | undefined,
    op: string,
    description?: string,
    data?: Record<string, unknown>
  ): Sentry.Span | undefined {
    if (!parentSpan) {
      console.warn('[PerformanceTrackingService] No parent span provided. Cannot add child span.');
      return undefined;
    }

    try {
      const childSpan = parentSpan.startChild({
        op,
        description,
        data,
      });

      return childSpan;
    } catch (error) {
      console.warn('[PerformanceTrackingService] Could not add child span:', error);
      return undefined;
    }
  }

  /**
   * Ends a Sentry span and removes it from the activeSpans map if present.
   * @param span The Sentry Span object to finish.
   */
  public endTrace(span: Sentry.Span | undefined): void {
    if (span) {
      try {
        span.finish();
        // Remove from active map if it was stored by name
        for (const [name, storedSpan] of this.activeSpans.entries()) {
          if (storedSpan === span) {
            this.activeSpans.delete(name);
            break;
          }
        }
      } catch (error) {
        console.warn('[PerformanceTrackingService] Error ending trace:', error);
      }
    } else {
      console.warn('[PerformanceTrackingService] Attempted to end an undefined trace.');
    }
  }

  /**
   * Ends a Sentry span (alias for endTrace, for semantic clarity).
   * @param span The Sentry Span object to finish.
   */
  public endSpan(span: Sentry.Span | undefined): void {
    this.endTrace(span);
  }

  /**
   * Records a custom metric using Sentry's custom measurement API.
   * @param params.name The metric name.
   * @param params.value The value of the metric.
   * @param params.unit The unit of the metric (e.g., 'millisecond', 'byte').
   * @param params.tags Optional tags to attach to the metric.
   * @param params.type The type of metric (e.g., 'increment', 'distribution', 'gauge', 'set').
   */
  public recordMetric({
    name,
    value,
    unit,
    tags,
    type = 'increment'
  }: {
    name: string;
    value: number;
    unit?: string;
    tags?: { [key: string]: string | number | boolean };
    type?: 'increment' | 'distribution' | 'gauge' | 'set';
  }): void {
    try {
      // Sentry v7+ does not have a public metrics API in the browser SDK as of 2024.
      // Instead, record as a custom measurement on the current active span/transaction.
      const activeSpan = Array.from(this.activeSpans.values())[0];
      if (activeSpan) {
        if (!activeSpan.data) activeSpan.data = {};
        activeSpan.setMeasurement?.(name, value, unit);
        // Attach tags as extra data if provided
        if (tags) {
          Object.entries(tags).forEach(([tagKey, tagValue]) => {
            activeSpan.setTag?.(tagKey, String(tagValue));
          });
        }
      } else {
        // Fallback: Attach to the current scope (not as a metric, but as extra context)
        Sentry.setContext('metric', { name, value, unit, tags, type });
      }
    } catch (error) {
      console.warn('[PerformanceTrackingService] Error recording metric:', error);
    }
  }

  /**
   * Sets a tag on the current Sentry scope.
   * @param key The tag key.
   * @param value The tag value.
   */
  public setTag(key: string, value: string | number | boolean): void {
    try {
      Sentry.setTag(key, String(value));
    } catch (error) {
      console.warn('[PerformanceTrackingService] Error setting tag:', error);
    }
  }

  /**
   * Sets extra context data on the current Sentry scope.
   * @param key The context key.
   * @param data The context data.
   */
  public setExtra(key: string, data: unknown): void {
    try {
      Sentry.setExtra(key, data);
    } catch (error) {
      console.warn('[PerformanceTrackingService] Error setting extra data:', error);
    }
  }
}

/**
 * Singleton instance of PerformanceTrackingService.
 * Use this for all custom performance and metric tracking in the frontend.
 */
export const performanceTrackingService = new PerformanceTrackingService();

/**
 * Example Usage (conceptual):
 *     // ... await Promise.all([...]) ...
 *     performanceTrackingService.recordMetric({ name: 'dashboard.data.items_loaded', value: 100 });
 *   } catch (e) {
